# ============================================================
#  GameBoost - Optimiseur de jeu pour Windows 10 / 11
#  Mode Jeu : ne garde que le jeu, Discord et l'essentiel.
# ============================================================

param([string]$IconPath = "", [switch]$Minimized, [string]$Edition = "", [int]$WaitPid = 0)

# --- Compatibilite : verifications de demarrage -------------------------------
# Le lanceur (GameBoost.exe) lit ce fichier pour afficher une explication claire si le demarrage echoue.
$Script:ErrFile = Join-Path $env:APPDATA 'GameBoost\erreur_demarrage.txt'
function Write-StartupError($text) {
    try {
        $d = Split-Path -Parent $Script:ErrFile
        if (-not (Test-Path -LiteralPath $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null }
        Set-Content -LiteralPath $Script:ErrFile -Value $text -Encoding UTF8
    } catch {}
}
if ($ExecutionContext.SessionState.LanguageMode -ne 'FullLanguage') {
    Write-StartupError ("PowerShell fonctionne en mode restreint (" + $ExecutionContext.SessionState.LanguageMode + ") sur ce PC.")
    exit 3
}
if ($PSVersionTable.PSVersion.Major -lt 5) {
    Write-StartupError ("PowerShell " + $PSVersionTable.PSVersion + " est trop ancien (PowerShell 5 est inclus dans Windows 10 et 11).")
    exit 2
}
$Script:WinBuild = 0; $Script:WinDisplay = ""
try {
    $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop
    $Script:WinBuild = [int]$cv.CurrentBuildNumber
    $Script:WinDisplay = [string]$cv.DisplayVersion
    if (-not $Script:WinDisplay) { $Script:WinDisplay = [string]$cv.ReleaseId }
} catch {}
if ($Script:WinBuild -gt 0 -and $Script:WinBuild -lt 10240) {
    Write-StartupError "GameBoost a besoin de Windows 10 ou Windows 11."
    exit 2
}
$Script:HostExe = (Get-Process -Id $PID).Path
if (-not $Script:HostExe) { $Script:HostExe = 'powershell.exe' }

# --- Relance automatique en administrateur ---------------------------------
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    try {
        $extra = ""; if ($Edition) { $extra += " -Edition " + ($Edition -replace '[^A-Za-z]', '') }; if ($WaitPid -gt 0) { $extra += " -WaitPid " + [int]$WaitPid }
        Start-Process $Script:HostExe -Verb RunAs -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`" -IconPath `"$IconPath`"$(if ($Minimized) { ' -Minimized' })$extra"
    } catch {
        Add-Type -AssemblyName System.Windows.Forms
        [System.Windows.Forms.MessageBox]::Show("GameBoost a besoin des droits administrateur pour fonctionner.", "GameBoost") | Out-Null
        Write-StartupError "Droits administrateur refuses."
        exit 4
    }
    exit
}

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
[System.Windows.Forms.Application]::EnableVisualStyles()
try { [System.Windows.Forms.Application]::SetUnhandledExceptionMode([System.Windows.Forms.UnhandledExceptionMode]::CatchException) } catch {}
[System.Windows.Forms.Application]::add_ThreadException({
    param($sender, $e)
    try { Log ("ERREUR interne (GameBoost continue) : " + $e.Exception.Message) } catch {}
})

# Une seule instance a la fois
# (changement de modele : la nouvelle instance attend la fin de l'ancienne, qui remet le turbo et la carte graphique)
if ($WaitPid -gt 0) {
    try { $prevProc = [System.Diagnostics.Process]::GetProcessById($WaitPid); [void]$prevProc.WaitForExit(20000); $prevProc.Dispose() } catch {}
}
$created = $false
$Script:Mutex = New-Object System.Threading.Mutex($true, "Local\GameBoostApp", [ref]$created)
if (-not $created -and $WaitPid -gt 0) {
    try { if ($Script:Mutex.WaitOne(10000)) { $created = $true } } catch [System.Threading.AbandonedMutexException] { $created = $true } catch {}
}
if (-not $created) {
    # Deja ouvert (souvent reduit pres de l'horloge) : on demande a la fenetre deja ouverte de revenir au premier plan
    $shown = $false
    try {
        if (-not ('GBFront' -as [type])) { Add-Type -TypeDefinition 'using System.Runtime.InteropServices; public static class GBFront { [DllImport("user32.dll")] public static extern bool AllowSetForegroundWindow(int pid); }' }
        [void][GBFront]::AllowSetForegroundWindow(-1)
    } catch {}
    try { $ev = [System.Threading.EventWaitHandle]::OpenExisting('Local\GameBoostShow'); [void]$ev.Set(); $shown = $true } catch {}
    if (-not $shown) { [System.Windows.Forms.MessageBox]::Show("GameBoost est deja ouvert (regarde pres de l'horloge, dans la barre des taches).", "GameBoost") | Out-Null }
    exit
}
# Signal "affiche-toi" envoye par un 2e lancement de GameBoost
$Script:ShowEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, 'Local\GameBoostShow')

# --- Code C# : compile UNE fois puis garde en cache (demarrage beaucoup plus rapide) ----------
# Cache dans ProgramData\GameBoost, accessible en ecriture seulement par les administrateurs et le systeme
# (un programme lance sans droits admin ne peut pas y glisser un faux fichier).
$Script:GBCompileNotes = New-Object System.Collections.ArrayList
$Script:GBCompileError = ""
function Test-GBSecureDir($path) {
    try {
        $trusted = @('S-1-5-32-544', 'S-1-5-18')
        $acl = Get-Acl -LiteralPath $path -ErrorAction Stop
        if ($trusted -notcontains $acl.GetOwner([System.Security.Principal.SecurityIdentifier]).Value) { return $false }
        if (-not $acl.AreAccessRulesProtected) { return $false }
        foreach ($r in $acl.GetAccessRules($true, $true, [System.Security.Principal.SecurityIdentifier])) {
            if ($r.AccessControlType -eq 'Allow' -and $trusted -notcontains $r.IdentityReference.Value) { return $false }
        }
        return $true
    } catch { return $false }
}
function New-GBSecureDir($path) {
    if ((Test-Path -LiteralPath $path) -and -not (Test-GBSecureDir $path)) { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop }
    if (-not (Test-Path -LiteralPath $path)) {
        New-Item -ItemType Directory -Path $path -Force -ErrorAction Stop | Out-Null
        $acl = New-Object System.Security.AccessControl.DirectorySecurity
        $acl.SetAccessRuleProtection($true, $false)
        foreach ($sid in @('S-1-5-32-544', 'S-1-5-18')) {
            $id = New-Object System.Security.Principal.SecurityIdentifier($sid)
            $acl.AddAccessRule((New-Object System.Security.AccessControl.FileSystemAccessRule($id, 'FullControl', 'ContainerInherit, ObjectInherit', 'None', 'Allow')))
        }
        $acl.SetOwner((New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')))
        Set-Acl -LiteralPath $path -AclObject $acl -ErrorAction Stop
    }
    return (Test-GBSecureDir $path)
}
function Get-GBCacheDir {
    if ($Script:GBCacheDirDone) { return $Script:GBCacheDir }
    $Script:GBCacheDirDone = $true; $Script:GBCacheDir = $null
    try {
        if (-not $env:ProgramData) { return $null }
        $root = Join-Path $env:ProgramData 'GameBoost'
        if (-not (New-GBSecureDir $root)) { return $null }
        $d = Join-Path $root 'cache'
        if (New-GBSecureDir $d) { $Script:GBCacheDir = $d }
    } catch {}
    return $Script:GBCacheDir
}
function Add-GBCompiled([string]$Name, [string]$Source, $Refs, [string]$Probe) {
    if ($Probe -as [type]) { return $true }
    $extra = @{}
    if ($Refs -and @($Refs).Count -gt 0) { $extra.ReferencedAssemblies = @($Refs) }
    if ($PSVersionTable.PSEdition -eq 'Core') { $extra.IgnoreWarnings = $true; $extra.WarningAction = 'SilentlyContinue' }
    $dir = Get-GBCacheDir
    if ($dir) {
        try {
            $sha = [System.Security.Cryptography.SHA256]::Create()
            $sig = $Name + '|' + $PSVersionTable.PSVersion + '|' + [Environment]::Version + '|' + [IntPtr]::Size + '|' + (@($Refs) -join ';') + '|' + $Source
            $hb = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($sig)); $sha.Dispose()
            $hash = -join ($hb[0..7] | ForEach-Object { $_.ToString('x2') })
            $dll = Join-Path $dir ($Name + '_' + $hash + '.dll')
            if (Test-Path -LiteralPath $dll) {
                try { Add-Type -LiteralPath $dll -ErrorAction Stop } catch {}
                if ($Probe -as [type]) { [void]$Script:GBCompileNotes.Add($Name + ' (cache)'); return $true }
                Remove-Item -LiteralPath $dll -Force -ErrorAction SilentlyContinue
            }
            Add-Type -TypeDefinition $Source -OutputAssembly $dll -OutputType Library -ErrorAction Stop @extra
            if (-not ($Probe -as [type])) { Add-Type -LiteralPath $dll -ErrorAction Stop }
            if ($Probe -as [type]) {
                [void]$Script:GBCompileNotes.Add($Name + ' (compile, mis en cache)')
                Get-ChildItem -LiteralPath $dir -Filter ($Name + '_*.dll') -ErrorAction SilentlyContinue | Where-Object { $_.FullName -ne $dll } | Remove-Item -Force -ErrorAction SilentlyContinue
                return $true
            }
        } catch { $Script:GBCompileError = $_.Exception.Message }
        if ($Probe -as [type]) { return $true }
    }
    try { Add-Type -TypeDefinition $Source -ErrorAction Stop @extra; [void]$Script:GBCompileNotes.Add($Name + ' (memoire)') }
    catch { $Script:GBCompileError = $_.Exception.Message }
    return [bool]($Probe -as [type])
}

# --- Interface GameBoost : theme neo-futuriste, composants dessines, animations et curseur ---------
# (si la compilation est bloquee par l'antivirus ou la strategie, GameBoost garde les controles Windows classiques)
$Script:UiOK = $true
try {
$uiSrc = @"
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Text;
using System.Runtime.InteropServices;
using System.Windows.Forms;

// ======================= GameBoost UI : theme neo-futuriste / cyberpunk =======================

// Courbe de Bezier cubique (meme calcul que les navigateurs pour cubic-bezier)
public class CubicBezier {
    double cx, bx, ax, cy, by, ay;
    public CubicBezier(double p1x, double p1y, double p2x, double p2y) {
        cx = 3 * p1x; bx = 3 * (p2x - p1x) - cx; ax = 1 - cx - bx;
        cy = 3 * p1y; by = 3 * (p2y - p1y) - cy; ay = 1 - cy - by;
    }
    double SX(double t) { return ((ax * t + bx) * t + cx) * t; }
    double SY(double t) { return ((ay * t + by) * t + cy) * t; }
    double DX(double t) { return (3 * ax * t + 2 * bx) * t + cx; }
    public double Solve(double x) {
        if (x <= 0) return 0;
        if (x >= 1) return 1;
        double t = x;
        for (int i = 0; i < 8; i++) {
            double e = SX(t) - x;
            if (Math.Abs(e) < 1e-6) return SY(t);
            double d = DX(t);
            if (Math.Abs(d) < 1e-6) break;
            t -= e / d;
        }
        double lo = 0, hi = 1; t = x;
        for (int i = 0; i < 40; i++) {
            double v = SX(t);
            if (Math.Abs(v - x) < 1e-6) break;
            if (x > v) lo = t; else hi = t;
            t = (lo + hi) / 2;
        }
        return SY(t);
    }
}

// Moteur d'animation : un seul minuteur (60 i/s) pour tous les composants, actif seulement s'il y a une animation
public static class GBMotion {
    [DllImport("user32.dll")] static extern bool SystemParametersInfo(uint action, uint param, ref bool value, uint winIni);
    public static readonly CubicBezier EaseOut = new CubicBezier(0.23, 1, 0.32, 1);       // entrees, retours
    public static readonly CubicBezier EaseInOut = new CubicBezier(0.77, 0, 0.175, 1);    // changements d'etat a l'ecran
    public static readonly CubicBezier Ease = new CubicBezier(0.25, 0.1, 0.25, 1);        // survol, couleurs
    public static bool ForceReduced = false;
    static int _reduced = -1;
    // Respecte "Afficher les animations dans Windows" (Accessibilite > Effets visuels)
    public static bool Reduced {
        get {
            if (ForceReduced) return true;
            if (_reduced < 0) { bool on = true; try { SystemParametersInfo(0x1042, 0, ref on, 0); } catch { } _reduced = on ? 0 : 1; }
            return _reduced == 1;
        }
    }
    static readonly Stopwatch _clock = Stopwatch.StartNew();
    public static double Now { get { return _clock.Elapsed.TotalMilliseconds; } }
    static readonly List<Tween> _active = new List<Tween>();
    static Timer _timer;
    internal static void Start(Tween t) {
        if (!_active.Contains(t)) _active.Add(t);
        if (_timer == null) { _timer = new Timer(); _timer.Interval = 15; _timer.Tick += Tick; }
        if (!_timer.Enabled) _timer.Start();
    }
    static void Tick(object sender, EventArgs e) {
        double now = Now;
        for (int i = _active.Count - 1; i >= 0; i--) {
            if (i >= _active.Count) continue;
            if (_active[i].Step(now)) _active.RemoveAt(i);
        }
        if (_active.Count == 0) _timer.Stop();
    }
}

// Valeur animee : se redirige depuis la valeur actuelle si on la relance (interruptible, comme une transition CSS)
public class Tween {
    public float Value;
    float _from, _to;
    double _start, _dur;
    CubicBezier _curve;
    public Control Owner;
    public bool Running;
    public bool Motion = true;   // false = simple fondu de couleur, garde meme si les animations Windows sont coupees
    public event EventHandler Updated;
    public Tween(Control owner, float v) { Owner = owner; Value = v; _to = v; }
    public float Target { get { return _to; } }
    public void To(float target, double ms, CubicBezier curve) { To(target, ms, curve, 0); }
    // Repart d'une valeur donnee (meme si une animation vers la meme cible tourne deja)
    public void From(float from, float target, double ms, CubicBezier curve) { Value = from; Running = false; To(target, ms, curve, 0); }
    public void To(float target, double ms, CubicBezier curve, double delay) {
        if (Running && Math.Abs(target - _to) < 0.0001f) return;
        _to = target;
        bool canAnimate = Owner != null && !Owner.IsDisposed && Owner.IsHandleCreated && Owner.Visible;
        if (canAnimate) { Form f = Owner.FindForm(); if (f == null || f.WindowState == FormWindowState.Minimized) canAnimate = false; }   // rien n'anime fenetre reduite / cachee
        if ((Motion && GBMotion.Reduced) || ms <= 0 || !canAnimate) {
            Value = target; Running = false;
            if (Owner != null && !Owner.IsDisposed) Owner.Invalidate();
            if (Updated != null) Updated(this, EventArgs.Empty);
            return;
        }
        _from = Value; _start = GBMotion.Now + delay; _dur = ms; _curve = curve; Running = true;
        GBMotion.Start(this);
    }
    internal bool Step(double now) {
        if (Owner == null || Owner.IsDisposed) { Running = false; return true; }
        double p = (now - _start) / _dur;
        if (p < 0) return false;
        bool done = p >= 1;
        Value = done ? _to : _from + (float)_curve.Solve(p) * (_to - _from);
        if (done) Running = false;
        Owner.Invalidate();
        if (Updated != null) Updated(this, EventArgs.Empty);
        return done;
    }
}

public static class GBTheme {
    public static Color Bg = Color.FromArgb(7, 8, 15);
    public static Color Panel = Color.FromArgb(14, 16, 28);
    public static Color PanelHi = Color.FromArgb(22, 26, 44);
    public static Color Line = Color.FromArgb(40, 48, 78);
    public static Color Text = Color.FromArgb(226, 240, 255);
    public static Color Muted = Color.FromArgb(118, 132, 162);
    public static Color Cyan = Color.FromArgb(0, 240, 255);
    public static Color Magenta = Color.FromArgb(255, 42, 109);
    public static Color Yellow = Color.FromArgb(252, 238, 10);
    public static Color Green = Color.FromArgb(5, 255, 161);
    public static Color Violet = Color.FromArgb(150, 110, 255);
    // Modele (NEXUS par defaut) : PowerShell remplace ces valeurs avant de creer les controles
    public static Color Deep = Color.FromArgb(4, 5, 10);          // champs de saisie, listes deroulantes
    public static Color Sel = Color.FromArgb(26, 32, 56);         // element choisi dans une liste
    public static Color Track = Color.FromArgb(26, 30, 50);       // piste des curseurs
    public static Color Disabled = Color.FromArgb(60, 66, 90);    // curseur desactive
    public static Color Accent = Color.FromArgb(0, 240, 255);
    public static Color Accent2 = Color.FromArgb(255, 42, 109);
    public static Color OnAccent = Color.FromArgb(10, 10, 18);    // texte sur l'accent
    public static Color Card = Color.FromArgb(14, 16, 28);
    public static Color MeterOk = Color.FromArgb(0, 240, 255);    // jauge dans la zone normale
    public static int Edition = 0;        // 0 NEXUS, 1 ARENA, 2 PURE
    public static int Shape = 0;          // 0 coins coupes, 1 arrondi, 2 pilule
    public static int Radius = 8;
    public static bool Glow = true;       // lueur neon au survol
    public static bool IsDarkTheme = true;
    public static int Motion = 0;         // 0 neon (net), 1 punch, 2 soft (doux)

    public static Color Mix(Color a, Color b, float t) {
        t = Math.Max(0f, Math.Min(1f, t));
        return Color.FromArgb(255, (int)(a.R + (b.R - a.R) * t), (int)(a.G + (b.G - a.G) * t), (int)(a.B + (b.B - a.B) * t));
    }
    public static bool IsDark(Color c) { return (c.R * 299 + c.G * 587 + c.B * 114) / 1000 < 140; }
    // Texte lisible sur une couleur pleine, en theme sombre comme en theme clair
    public static Color TextOn(Color c) {
        if (IsDark(c)) return IsDarkTheme ? Text : Color.White;
        return IsDarkTheme ? Color.FromArgb(10, 10, 18) : Text;
    }

    // Rectangle a coins coupes (haut-gauche et bas-droit) : la forme "HUD"
    public static GraphicsPath Chamfer(RectangleF r, float c) {
        GraphicsPath p = new GraphicsPath();
        p.AddLine(r.Left + c, r.Top, r.Right, r.Top);
        p.AddLine(r.Right, r.Top, r.Right, r.Bottom - c);
        p.AddLine(r.Right, r.Bottom - c, r.Right - c, r.Bottom);
        p.AddLine(r.Right - c, r.Bottom, r.Left, r.Bottom);
        p.AddLine(r.Left, r.Bottom, r.Left, r.Top + c);
        p.CloseFigure();
        return p;
    }
    public static GraphicsPath Pill(RectangleF r) {
        GraphicsPath p = new GraphicsPath();
        float d = Math.Max(2f, Math.Min(r.Height, r.Width));
        p.AddArc(r.X, r.Y, d, d, 90, 180);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 180);
        p.CloseFigure();
        return p;
    }
    // Rectangle a coins arrondis (rayon limite a la moitie du cote le plus court)
    public static GraphicsPath RoundRect(RectangleF r, float rad) {
        GraphicsPath p = new GraphicsPath();
        float d = Math.Min(rad * 2f, Math.Min(r.Width, r.Height));
        if (d < 1f) { p.AddRectangle(r); return p; }
        p.AddArc(r.X, r.Y, d, d, 180, 90);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
        p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
        p.CloseFigure();
        return p;
    }
    // Forme du modele : coins coupes (cut), arrondi (Radius x echelle) ou pilule
    public static GraphicsPath ShapePath(RectangleF r, float cut, float s) {
        if (Shape == 2) return Pill(r);
        if (Shape == 1) return RoundRect(r, Radius * s);
        return Chamfer(r, cut);
    }

    [DllImport("dwmapi.dll")] static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int value, int size);
    [DllImport("uxtheme.dll", CharSet = CharSet.Unicode)] static extern int SetWindowTheme(IntPtr hwnd, string app, string idList);
    static int Ref(Color c) { return c.R | (c.G << 8) | (c.B << 16); }
    // Barre de titre : mode sombre ou clair, couleur de titre, bordure et texte (couleurs : Windows 11)
    public static void Chrome(IntPtr hwnd, bool dark, Color caption, Color border, Color text) {
        try { int on = dark ? 1 : 0; if (DwmSetWindowAttribute(hwnd, 20, ref on, 4) != 0) DwmSetWindowAttribute(hwnd, 19, ref on, 4); } catch { }
        try {
            int cap = Ref(caption); DwmSetWindowAttribute(hwnd, 35, ref cap, 4);
            int bd = Ref(border); DwmSetWindowAttribute(hwnd, 34, ref bd, 4);
            int txt = Ref(text); DwmSetWindowAttribute(hwnd, 36, ref txt, 4);
        } catch { }
    }
    // Barre de titre sombre (Windows 10 2004+), couleur de titre et bordure neon (Windows 11) ; theme clair : barre claire
    public static void DarkChrome(IntPtr hwnd) {
        if (!IsDarkTheme) { LightChrome(hwnd); return; }
        Chrome(hwnd, true, Bg, Cyan, Text);
    }
    public static void LightChrome(IntPtr hwnd) { Chrome(hwnd, false, Bg, Line, Text); }
    // Barres de defilement sombres (rien en theme clair : celles de Windows conviennent)
    public static void DarkScrollbars(Control c) { if (!IsDarkTheme) return; try { SetWindowTheme(c.Handle, "DarkMode_Explorer", null); } catch { } }
    // Fenetre affichee et au premier plan, meme si GameBoost a ete lance par un PowerShell cache
    // (Windows applique sinon le mode "cache" du lanceur a la premiere fenetre : on ne voyait que l'icone pres de l'horloge)
    [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr hwnd, int cmd);
    [DllImport("user32.dll")] static extern bool BringWindowToTop(IntPtr hwnd);
    [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr hwnd);
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hwnd, out uint pid);
    [DllImport("kernel32.dll")] static extern uint GetCurrentThreadId();
    [DllImport("user32.dll")] static extern bool AttachThreadInput(uint a, uint b, bool attach);
    [DllImport("user32.dll")] static extern bool IsIconic(IntPtr hwnd);
    [DllImport("user32.dll")] static extern IntPtr SetActiveWindow(IntPtr hwnd);
    [DllImport("user32.dll")] static extern IntPtr SetFocus(IntPtr hwnd);
    [DllImport("user32.dll")] static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);
    [DllImport("user32.dll")] static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);
    // Windows refuse souvent le premier plan (appli en administrateur, clic venant de la barre des taches) :
    // on se rattache au fil de la fenetre de devant, touche Alt fantome (debloque le verrou), puis premier plan
    public static bool IsFront(Form f) { try { return GetForegroundWindow() == f.Handle; } catch { return false; } }
    public static bool ShowFront(Form f) {
        try {
            IntPtr h = f.Handle;
            ShowWindow(h, IsIconic(h) ? 9 : 5);
            IntPtr fg = GetForegroundWindow();
            if (fg == h) return true;
            uint pid; uint fgT = fg == IntPtr.Zero ? 0 : GetWindowThreadProcessId(fg, out pid);
            uint me = GetCurrentThreadId();
            bool att = false;
            if (fgT != 0 && fgT != me) att = AttachThreadInput(me, fgT, true);
            try {
                keybd_event(0x12, 0, 0, UIntPtr.Zero); keybd_event(0x12, 0, 2, UIntPtr.Zero);
                SetWindowPos(h, new IntPtr(-1), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0040);
                SetWindowPos(h, new IntPtr(-2), 0, 0, 0, 0, 0x0001 | 0x0002 | 0x0040);
                BringWindowToTop(h); SetForegroundWindow(h); SetActiveWindow(h); SetFocus(h);
            } finally { if (att) AttachThreadInput(me, fgT, false); }
            return GetForegroundWindow() == h;
        } catch { return false; }
    }
    // Overlay : la souris passe a travers, pas d'icone dans la barre des taches, ne prend jamais le focus du jeu
    [DllImport("user32.dll")] static extern int GetWindowLong(IntPtr hwnd, int index);
    [DllImport("user32.dll")] static extern int SetWindowLong(IntPtr hwnd, int index, int value);
    public static void MakeOverlay(Form f) {
        try { int ex = GetWindowLong(f.Handle, -20); SetWindowLong(f.Handle, -20, ex | 0x20 | 0x80000 | 0x80 | 0x08000000); } catch { }
    }
    public static void ShowNoActivate(Form f) { try { ShowWindow(f.Handle, 4); } catch { } }
    // Sans scintillement pendant le defilement et les mises a jour
    public static void DoubleBuffer(Control c) {
        try { typeof(Control).GetProperty("DoubleBuffered", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance).SetValue(c, true, null); } catch { }
    }
    // Liste a en-tetes sombres : dessin fait ici (compile) et non en PowerShell a chaque ligne = defilement fluide
    public static void StyleList(ListView lv, Font headerFont, Color headerBg, Color line, Color headerText, bool separators) {
        DoubleBuffer(lv);
        lv.OwnerDraw = true;
        lv.DrawColumnHeader += delegate(object s, DrawListViewColumnHeaderEventArgs e) {
            using (SolidBrush b = new SolidBrush(headerBg)) e.Graphics.FillRectangle(b, e.Bounds);
            using (Pen p = new Pen(line, 1)) {
                e.Graphics.DrawLine(p, e.Bounds.Left, e.Bounds.Bottom - 1, e.Bounds.Right, e.Bounds.Bottom - 1);
                if (separators) e.Graphics.DrawLine(p, e.Bounds.Right - 1, e.Bounds.Top + 4, e.Bounds.Right - 1, e.Bounds.Bottom - 5);
            }
            Rectangle tr = new Rectangle(e.Bounds.X + 6, e.Bounds.Y, Math.Max(1, e.Bounds.Width - 8), e.Bounds.Height);
            TextRenderer.DrawText(e.Graphics, e.Header.Text, headerFont, tr, headerText,
                TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        };
        lv.DrawItem += delegate(object s, DrawListViewItemEventArgs e) { e.DrawDefault = true; };
        lv.DrawSubItem += delegate(object s, DrawListViewSubItemEventArgs e) { e.DrawDefault = true; };
    }
    // Navigation de Config Windows (titres de section + pages) dessinee ici : le defilement de la liste reste instantane
    public static void StyleNav(ListBox lb, Font hdrFont, Font itemFont, Color bg, Color selBg, Color hdrC, Color txt, Color acc, float scale) {
        DoubleBuffer(lb);
        lb.MeasureItem += delegate(object s, MeasureItemEventArgs e) {
            System.Collections.IDictionary p = lb.Items[e.Index] as System.Collections.IDictionary;
            bool isH = p != null && p["H"] != null && p["H"].ToString().Length > 0;
            e.ItemHeight = (int)(((isH && e.Index > 0) ? 36 : 30) * scale);
        };
        lb.DrawItem += delegate(object s, DrawItemEventArgs e) {
            if (e.Index < 0) return;
            System.Collections.IDictionary p = lb.Items[e.Index] as System.Collections.IDictionary;
            using (SolidBrush b = new SolidBrush(bg)) e.Graphics.FillRectangle(b, e.Bounds);
            if (p == null) return;
            object h = p["H"];
            if (h != null && h.ToString().Length > 0) {
                Rectangle hr = new Rectangle(e.Bounds.X + 10, e.Bounds.Y, e.Bounds.Width - 12, e.Bounds.Height - 6);
                string pre = Edition == 0 ? "// " : "";   // prefixe "//" : NEXUS seulement
                TextRenderer.DrawText(e.Graphics, pre + h.ToString(), hdrFont, hr, hdrC, TextFormatFlags.Bottom | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
                return;
            }
            bool sel = (e.State & DrawItemState.Selected) != 0;
            if (sel) {
                using (SolidBrush sb = new SolidBrush(selBg)) e.Graphics.FillRectangle(sb, e.Bounds);
                if (Edition != 2) using (SolidBrush ab = new SolidBrush(acc)) e.Graphics.FillRectangle(ab, e.Bounds.X, e.Bounds.Y + 5, 3, e.Bounds.Height - 10);
            }
            Rectangle tr = new Rectangle(e.Bounds.X + 22, e.Bounds.Y, e.Bounds.Width - 24, e.Bounds.Height);
            TextRenderer.DrawText(e.Graphics, Convert.ToString(p["T"]), itemFont, tr, sel ? acc : txt, TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        };
    }
    // Liste deroulante sombre (le style Windows reste blanc meme avec BackColor)
    public static void StyleCombo(ComboBox cb, Color bg, Color fg, Color hi) {
        cb.DrawMode = DrawMode.OwnerDrawFixed; cb.FlatStyle = FlatStyle.Flat; cb.BackColor = bg; cb.ForeColor = fg;
        cb.DrawItem += delegate(object s, DrawItemEventArgs e) {
            bool sel = (e.State & DrawItemState.Selected) != 0 && (e.State & DrawItemState.ComboBoxEdit) == 0;
            using (SolidBrush b = new SolidBrush(sel ? hi : bg)) e.Graphics.FillRectangle(b, e.Bounds);
            if (e.Index < 0) return;
            Rectangle r = new Rectangle(e.Bounds.X + 4, e.Bounds.Y, Math.Max(1, e.Bounds.Width - 6), e.Bounds.Height);
            TextRenderer.DrawText(e.Graphics, cb.GetItemText(cb.Items[e.Index]), cb.Font, r, fg,
                TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        };
    }
}

// ----------------------- Bouton du theme : coins coupes neon (NEXUS), arrondi (ARENA, PURE) -----------------------
public class GBButton : Button {
    Tween _hover, _press, _morph, _sweep;
    Color _fromFill, _toFill;
    public bool Filled = false;
    public int Cut = 8;
    // Tuile : titre en haut a gauche + description en dessous (page Outils, resume de l'accueil)
    public string Desc = "";
    public Font DescFont;
    bool _badge;
    public bool Badge { get { return _badge; } set { _badge = value; Invalidate(); } }   // point jaune : quelque chose a voir
    public GBButton() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _hover = new Tween(this, 0); _press = new Tween(this, 0); _morph = new Tween(this, 1); _sweep = new Tween(this, 1);
        _hover.Motion = false; _morph.Motion = false;
        _fromFill = _toFill = GBTheme.Panel;
        FlatStyle = FlatStyle.Flat;
        Cursor = Cursors.Hand;
        ForeColor = GBTheme.Cyan;
    }
    // Balayage lumineux unique (activation du boost : evenement rare)
    public void Sweep() { _sweep.From(0f, 1f, 520, GBMotion.EaseInOut); }
    static Color TextOn(Color c) { return GBTheme.TextOn(c); }
    Color CurrentFill { get { return GBTheme.Mix(_fromFill, _toFill, _morph.Value); } }
    // Changement d'etat (BOOST -> ARRETER) : la couleur se transforme au lieu de sauter
    protected override void OnBackColorChanged(EventArgs e) {
        base.OnBackColorChanged(e);
        _fromFill = CurrentFill; _toFill = BackColor;
        _morph.From(0f, 1f, 240, GBMotion.EaseInOut);
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color parentBg = Parent != null ? Parent.BackColor : GBTheme.Bg;
        g.Clear(parentBg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
        float s = Math.Max(1f, g.DpiX / 96f);
        float h = Enabled ? _hover.Value : 0f;
        float pr = _press.Value;
        bool hud = GBTheme.Shape == 0, light = !GBTheme.IsDarkTheme;
        // Appui : 0.97 (NEXUS), 0.96 plus franc (ARENA), 0.98 + assombrissement (PURE)
        float depth = GBTheme.Motion == 1 ? 0.04f : (GBTheme.Motion == 2 ? 0.02f : 0.03f);
        float scale = 1f - depth * pr;
        g.TranslateTransform(Width / 2f, Height / 2f); g.ScaleTransform(scale, scale); g.TranslateTransform(-Width / 2f, -Height / 2f);
        Color accent = Enabled ? ForeColor : GBTheme.Muted;
        RectangleF r = new RectangleF(1.5f * s, 1.5f * s, Width - 3f * s, Height - 3f * s);
        float cut = Math.Min(Cut * s, Math.Min(r.Width, r.Height) / 2.5f);
        using (GraphicsPath p = GBTheme.ShapePath(r, cut, s)) {
            Color fill;
            if (light) fill = Filled ? GBTheme.Mix(CurrentFill, Color.Black, 0.08f * h) : GBTheme.Mix(GBTheme.Panel, accent, 0.08f + 0.06f * h);
            else fill = Filled ? GBTheme.Mix(CurrentFill, Color.White, 0.14f * h) : GBTheme.Mix(GBTheme.Panel, accent, 0.06f + 0.10f * h);
            if (GBTheme.Motion == 2 && pr > 0.001f) fill = GBTheme.Mix(fill, Color.Black, 0.10f * pr);
            if (!Enabled) fill = GBTheme.Mix(fill, parentBg, 0.55f);
            using (SolidBrush b = new SolidBrush(fill)) g.FillPath(b, p);
            if (GBTheme.Glow && h > 0.01f) {
                Color glow = Filled ? CurrentFill : accent;
                for (int i = 3; i >= 1; i--) using (Pen gp = new Pen(Color.FromArgb((int)(30 * h / i), glow), (1.5f + i * 2.5f) * s)) g.DrawPath(gp, p);
            }
            float sw = _sweep.Value;
            if (sw > 0.001f && sw < 0.999f) {
                Region old = g.Clip; g.SetClip(p, CombineMode.Intersect);
                float bw = r.Height * 1.4f, cx = r.Left - bw + (r.Width + bw * 2) * sw;
                PointF[] band = { new PointF(cx, r.Top), new PointF(cx + bw * 0.55f, r.Top), new PointF(cx + bw * 0.15f, r.Bottom), new PointF(cx - bw * 0.4f, r.Bottom) };
                using (SolidBrush wb = new SolidBrush(Color.FromArgb(110, Color.White))) g.FillPolygon(wb, band);
                g.Clip = old;
            }
            Color border;
            if (light) border = Filled ? fill : GBTheme.Mix(fill, accent, 0.22f + 0.25f * h);
            else border = Filled ? GBTheme.Mix(CurrentFill, Color.White, 0.30f * h) : GBTheme.Mix(GBTheme.Mix(accent, parentBg, 0.50f), accent, h);
            using (Pen pen = new Pen(border, (light ? 1f : 1.2f) * s)) g.DrawPath(pen, p);
            if (hud) {
                Color tickC = Filled ? GBTheme.Mix(CurrentFill, Color.White, 0.5f) : accent;
                using (Pen tick = new Pen(tickC, 2.2f * s)) g.DrawLine(tick, r.Left, r.Top + cut, r.Left + cut, r.Top);
            }
        }
        Color tc;
        if (!Enabled) tc = GBTheme.Muted;
        else if (Filled) tc = GBTheme.Mix(TextOn(_fromFill), TextOn(_toFill), _morph.Value);   // le texte suit la couleur sans "saut"
        else if (light) tc = accent;
        else tc = GBTheme.Mix(GBTheme.Mix(accent, GBTheme.Text, 0.45f), accent, h);
        if (!string.IsNullOrEmpty(Desc)) {
            float pad = 14 * s, th = Font.GetHeight(g);
            RectangleF tr = new RectangleF(r.Left + pad, r.Top + 9 * s, r.Width - pad * 2 - (_badge ? 14 * s : 0), th + 2);
            using (StringFormat sf = new StringFormat()) {
                sf.Trimming = StringTrimming.EllipsisCharacter; sf.FormatFlags = StringFormatFlags.NoWrap;
                using (SolidBrush tb = new SolidBrush(Enabled ? accent : GBTheme.Muted)) g.DrawString(Text, Font, tb, tr, sf);
            }
            Font df = DescFont ?? Font;
            RectangleF dr = new RectangleF(r.Left + pad, tr.Bottom + 3 * s, r.Width - pad * 2, Math.Max(1f, r.Bottom - tr.Bottom - 7 * s));
            using (StringFormat sf = new StringFormat()) {
                sf.Trimming = StringTrimming.EllipsisWord;
                using (SolidBrush db = new SolidBrush(Enabled ? GBTheme.Mix(GBTheme.Muted, GBTheme.Text, 0.15f + 0.35f * h) : GBTheme.Muted)) g.DrawString(Desc, df, db, dr, sf);
            }
        } else {
            using (StringFormat sf = new StringFormat()) {
                sf.Alignment = StringAlignment.Center; sf.LineAlignment = StringAlignment.Center;
                sf.Trimming = StringTrimming.EllipsisCharacter; sf.FormatFlags = StringFormatFlags.NoWrap;
                using (SolidBrush tb = new SolidBrush(tc)) g.DrawString(Text, Font, tb, r, sf);
            }
        }
        if (_badge) {
            float d = 8 * s, bx = r.Right - 12 * s - d, by = r.Top + 10 * s;
            if (GBTheme.Glow) using (SolidBrush gb = new SolidBrush(Color.FromArgb(60, GBTheme.Yellow))) g.FillEllipse(gb, bx - 3 * s, by - 3 * s, d + 6 * s, d + 6 * s);
            using (SolidBrush bb = new SolidBrush(GBTheme.Yellow)) g.FillEllipse(bb, bx, by, d, d);
        }
        if (Focused && ShowFocusCues && Enabled) {
            g.ResetTransform();
            if (hud) {
                using (Pen fp = new Pen(Color.FromArgb(160, accent), 1f)) {
                    float m = 3 * s, L = 6 * s;
                    g.DrawLine(fp, Width - m - L, Height - m, Width - m, Height - m); g.DrawLine(fp, Width - m, Height - m - L, Width - m, Height - m);
                }
            } else {
                RectangleF fr = new RectangleF(0.5f * s, 0.5f * s, Width - 1f * s - 1, Height - 1f * s - 1);
                using (GraphicsPath fpth = GBTheme.ShapePath(fr, cut, s)) using (Pen fp = new Pen(Color.FromArgb(150, accent), 1.5f * s)) g.DrawPath(fp, fpth);
            }
        }
    }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover.To(1, 150, GBMotion.Ease); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 200, GBMotion.Ease); _press.To(0, 160, GBMotion.EaseOut); }
    protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left && Enabled) _press.To(1, 100, GBMotion.EaseOut); }
    protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); _press.To(0, 160, GBMotion.EaseOut); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); if (!Enabled) { _hover.To(0, 0, GBMotion.Ease); _press.To(0, 0, GBMotion.Ease); } Invalidate(); }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnForeColorChanged(EventArgs e) { base.OnForeColorChanged(e); Invalidate(); }
}

// ----------------------- Interrupteur (remplace la case a cocher) : neon (NEXUS), plein (ARENA), facon iOS (PURE) -----------------------
public class GBToggle : CheckBox {
    Tween _knob, _hover;
    bool _keyboard;
    public Color OnColor = GBTheme.Cyan;
    public GBToggle() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _knob = new Tween(this, 0); _hover = new Tween(this, 0); _hover.Motion = false;
        AutoSize = false;
        Cursor = Cursors.Hand;
    }
    protected override void OnCheckedChanged(EventArgs e) {
        base.OnCheckedChanged(e);
        // Clavier (Espace) : changement instantane. Souris : le bouton glisse (PURE un peu plus doux).
        int ms = GBTheme.Motion == 2 ? 200 : (GBTheme.Motion == 1 ? 140 : 160);
        _knob.To(Checked ? 1f : 0f, _keyboard ? 0 : ms, GBMotion.EaseOut);
        _keyboard = false;
    }
    protected override void OnCreateControl() { base.OnCreateControl(); _knob.Value = Checked ? 1f : 0f; }
    protected override void OnKeyDown(KeyEventArgs e) { if (e.KeyCode == Keys.Space) _keyboard = true; base.OnKeyDown(e); }
    protected override void OnMouseDown(MouseEventArgs e) { _keyboard = false; base.OnMouseDown(e); }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover.To(1, 120, GBMotion.Ease); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 180, GBMotion.Ease); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); Invalidate(); }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = Parent != null ? Parent.BackColor : GBTheme.Bg;
        g.Clear(bg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        float k = _knob.Value, h = Enabled ? _hover.Value : 0f;
        Color on = Enabled ? OnColor : GBTheme.Muted;
        RectangleF tr;
        if (GBTheme.Edition == 0) {
            float tw = 26 * s, th = 14 * s;
            tr = new RectangleF(2 * s, (Height - th) / 2f, tw, th);
            using (GraphicsPath p = GBTheme.Pill(tr)) {
                if (k > 0.01f && Enabled) using (Pen glow = new Pen(Color.FromArgb((int)(45 * k), on), 4f * s)) g.DrawPath(glow, p);
                using (SolidBrush b = new SolidBrush(GBTheme.Mix(GBTheme.PanelHi, GBTheme.Mix(GBTheme.Panel, on, 0.35f), k))) g.FillPath(b, p);
                Color border = GBTheme.Mix(GBTheme.Mix(GBTheme.Line, GBTheme.Muted, h), on, k);
                using (Pen pen = new Pen(border, 1.2f * s)) g.DrawPath(pen, p);
            }
            float d = th - 5 * s;
            float x = tr.Left + 2.5f * s + (tw - 5 * s - d) * k;
            RectangleF kr = new RectangleF(x, tr.Top + 2.5f * s, d, d);
            using (SolidBrush kb = new SolidBrush(GBTheme.Mix(GBTheme.Mix(GBTheme.Muted, GBTheme.Text, h * 0.5f), on, k))) g.FillEllipse(kb, kr);
        } else {
            bool pure = GBTheme.Edition == 2;
            float tw = 30 * s, th = (pure ? 18 : 16) * s;
            tr = new RectangleF(2 * s, (Height - th) / 2f, tw, th);
            using (GraphicsPath p = GBTheme.Pill(tr)) {
                if (GBTheme.Glow && k > 0.01f && Enabled) using (Pen glow = new Pen(Color.FromArgb((int)(55 * k), on), 5f * s)) g.DrawPath(glow, p);
                Color off = pure ? GBTheme.Mix(GBTheme.PanelHi, GBTheme.Muted, 0.10f * h) : GBTheme.Mix(GBTheme.PanelHi, GBTheme.Line, h);
                using (SolidBrush b = new SolidBrush(GBTheme.Mix(off, on, k))) g.FillPath(b, p);
                if (!pure) using (Pen pen = new Pen(GBTheme.Mix(GBTheme.Line, on, k), 1f * s)) g.DrawPath(pen, p);
            }
            float d = th - 4 * s;
            float x = tr.Left + 2f * s + (tw - 4 * s - d) * k;
            RectangleF kr = new RectangleF(x, tr.Top + 2f * s, d, d);
            if (pure) {
                // Bouton blanc avec une ombre douce (comme iOS)
                using (SolidBrush sh = new SolidBrush(Color.FromArgb(38, 0, 0, 0))) g.FillEllipse(sh, kr.X, kr.Y + 1f * s, kr.Width, kr.Height);
                using (SolidBrush kb = new SolidBrush(Enabled ? Color.White : GBTheme.Mix(Color.White, GBTheme.Muted, 0.2f))) g.FillEllipse(kb, kr);
            } else {
                using (SolidBrush kb = new SolidBrush(GBTheme.Mix(GBTheme.Mix(GBTheme.Muted, GBTheme.Text, 0.4f + 0.4f * h), Color.White, k))) g.FillEllipse(kb, kr);
            }
        }
        Rectangle textR = new Rectangle((int)(tr.Right + 7 * s), 0, Math.Max(1, Width - (int)(tr.Right + 7 * s)), Height);
        Color tc = Enabled ? ForeColor : GBTheme.Muted;
        TextRenderer.DrawText(g, Text, Font, textR, tc, TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        if (Focused && ShowFocusCues) using (Pen fp = new Pen(Color.FromArgb(140, on), 1f)) g.DrawLine(fp, textR.Left, Height - 2, Math.Min(Width - 2, textR.Left + TextRenderer.MeasureText(Text, Font).Width), Height - 2);
    }
}

// ----------------------- Jauge (CPU, GPU, RAM, ping) : segments (NEXUS, ARENA), barre continue (PURE) -----------------------
public class GBMeter : Control {
    Tween _v;
    string _label = "", _text = "--", _sub = "";
    public int Segments = 24;
    public float WarnAt = 70f, AlertAt = 90f;
    public GBMeter() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _v = new Tween(this, 0);
        TabStop = false;
    }
    public string Label { get { return _label; } set { _label = value; Invalidate(); } }
    public string Sub { get { return _sub; } set { _sub = value ?? ""; Invalidate(); } }   // ex : nom de la carte graphique
    public Color LabelColor = GBTheme.Muted;
    public void SetValue(float pct, string text) {
        _text = text ?? "--";
        _v.To(Math.Max(0f, Math.Min(100f, pct)), 0, GBMotion.EaseOut);   // donnees lues en continu : pas d'animation
        Invalidate();
    }
    Color ColorFor(float v) { return v >= AlertAt ? GBTheme.Magenta : (v >= WarnAt ? GBTheme.Yellow : GBTheme.MeterOk); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : GBTheme.Bg);
        float s = Math.Max(1f, g.DpiX / 96f);
        float v = _v.Value;
        Color c = ColorFor(_v.Target);
        int textH = (int)(16 * s);
        TextFormatFlags nf = TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.VerticalCenter;
        int vw = Math.Min(Width * 2 / 3, TextRenderer.MeasureText(g, _text, Font, Size.Empty, nf).Width + 2);
        TextRenderer.DrawText(g, _text, Font, new Rectangle(Width - vw, 0, vw, textH), GBTheme.Text, nf | TextFormatFlags.Right | TextFormatFlags.EndEllipsis);
        TextRenderer.DrawText(g, _label, Font, new Rectangle(0, 0, Math.Max(1, Width - vw - (int)(6 * s)), textH), LabelColor, nf | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
        int subH = string.IsNullOrEmpty(_sub) ? 0 : (int)(15 * s);
        if (subH > 0) TextRenderer.DrawText(g, _sub, Font, new Rectangle(0, Height - subH, Width, subH), GBTheme.Muted, nf | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
        float top = textH + 3 * s, bh = Height - top - 1 - (subH > 0 ? subH + 2 * s : 0);
        if (bh < 3) return;
        if (GBTheme.Edition == 2) {
            // PURE : une barre continue aux bouts arrondis, fine et centree
            float bar = Math.Min(bh, 6 * s);
            RectangleF tr = new RectangleF(0, top + (bh - bar) / 2f, Width - 1, bar);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath tp = GBTheme.Pill(tr)) using (SolidBrush off = new SolidBrush(GBTheme.PanelHi)) g.FillPath(off, tp);
            float fw = tr.Width * v / 100f;
            if (fw > 0.5f) {
                RectangleF fr = new RectangleF(tr.X, tr.Y, Math.Max(bar, fw), bar);
                using (GraphicsPath fp = GBTheme.Pill(fr)) using (SolidBrush on = new SolidBrush(c)) g.FillPath(on, fp);
            }
            return;
        }
        float gap = 2 * s;
        float segW = (Width - gap * (Segments - 1)) / Segments;
        float lit = v / 100f * Segments;
        bool round = GBTheme.Shape != 0;
        if (round) g.SmoothingMode = SmoothingMode.AntiAlias;
        float rr = Math.Min(2f * s, segW / 2f);
        using (SolidBrush off = new SolidBrush(GBTheme.PanelHi))
        using (SolidBrush on = new SolidBrush(c)) {
            for (int i = 0; i < Segments; i++) {
                RectangleF sr = new RectangleF(i * (segW + gap), top, segW, bh);
                float a = Math.Max(0f, Math.Min(1f, lit - i));
                if (!round) {
                    g.FillRectangle(off, sr);
                    if (a >= 0.999f) g.FillRectangle(on, sr);
                    else if (a > 0) using (SolidBrush b = new SolidBrush(Color.FromArgb((int)(255 * a), c))) g.FillRectangle(b, sr);
                } else {
                    using (GraphicsPath sp = GBTheme.RoundRect(sr, rr)) {
                        g.FillPath(off, sp);
                        if (a >= 0.999f) g.FillPath(on, sp);
                        else if (a > 0) using (SolidBrush b = new SolidBrush(Color.FromArgb((int)(255 * a), c))) g.FillPath(b, sp);
                    }
                }
            }
        }
    }
}

// ----------------------- Titre de section : "// TITRE ----" (NEXUS), barre d'accent (ARENA), titre simple (PURE) -----------------------
public class GBHeader : Control {
    public Color Accent = GBTheme.Cyan;
    public string Hint = "";
    public Font HintFont;
    public GBHeader() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        TabStop = false;
    }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : GBTheme.Bg);
        float s = Math.Max(1f, g.DpiX / 96f);
        TextFormatFlags fl = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
        int x;
        if (GBTheme.Edition == 0) {
            string pre = "// ";
            Size ps = TextRenderer.MeasureText(g, pre, Font, Size.Empty, fl);
            TextRenderer.DrawText(g, pre, Font, new Rectangle(0, 0, ps.Width, Height), Color.FromArgb(255, GBTheme.Magenta), fl);
            string t = Text.ToUpperInvariant();
            Size ts = TextRenderer.MeasureText(g, t, Font, Size.Empty, fl);
            TextRenderer.DrawText(g, t, Font, new Rectangle(ps.Width, 0, ts.Width + 2, Height), Accent, fl);
            x = ps.Width + ts.Width + (int)(8 * s);
        } else if (GBTheme.Edition == 1) {
            // ARENA : petite barre d'accent arrondie, titre en capitales
            g.SmoothingMode = SmoothingMode.AntiAlias;
            float bh = Math.Min(Height - 4 * s, 14 * s);
            using (GraphicsPath bp = GBTheme.RoundRect(new RectangleF(0, (Height - bh) / 2f, 4 * s, bh), 2 * s)) using (SolidBrush ab = new SolidBrush(Accent)) g.FillPath(ab, bp);
            int tx = (int)(11 * s);
            string t = Text.ToUpperInvariant();
            Size ts = TextRenderer.MeasureText(g, t, Font, Size.Empty, fl);
            TextRenderer.DrawText(g, t, Font, new Rectangle(tx, 0, ts.Width + 2, Height), GBTheme.Text, fl);
            x = tx + ts.Width + (int)(8 * s);
        } else {
            // PURE : le titre, simplement
            Size ts = TextRenderer.MeasureText(g, Text, Font, Size.Empty, fl);
            TextRenderer.DrawText(g, Text, Font, new Rectangle(0, 0, ts.Width + 2, Height), GBTheme.Text, fl);
            x = ts.Width + (int)(8 * s);
        }
        if (!string.IsNullOrEmpty(Hint) && HintFont != null) {
            Size hs = TextRenderer.MeasureText(g, Hint, HintFont, Size.Empty, fl);
            TextRenderer.DrawText(g, Hint, HintFont, new Rectangle(x, 0, hs.Width + 2, Height), GBTheme.Muted, fl);
            x += hs.Width + (int)(8 * s);
        }
        if (GBTheme.Edition == 2) return;
        int y = Height / 2;
        int end = Width - (int)(2 * s);
        if (end - x > 12 * s) {
            if (GBTheme.Edition == 0) {
                using (Pen line = new Pen(GBTheme.Line, 1f)) g.DrawLine(line, x, y, end - 10 * s, y);
                using (SolidBrush b = new SolidBrush(Accent)) g.FillRectangle(b, end - 6 * s, y - 1.5f * s, 6 * s, 3 * s);
            } else {
                using (Pen line = new Pen(GBTheme.Line, 1f)) g.DrawLine(line, x, y, end, y);
            }
        }
    }
}

// ----------------------- Element de navigation (colonne de gauche de la fenetre principale) -----------------------
public class GBNavItem : Control {
    Tween _hover, _sel;
    bool _selected, _badge;
    public string Glyph = "";
    public Font GlyphFont;
    public Color Accent = GBTheme.Cyan;
    public GBNavItem() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        _hover = new Tween(this, 0); _hover.Motion = false;
        _sel = new Tween(this, 0); _sel.Motion = false;
        Cursor = Cursors.Hand; TabStop = true;
    }
    public bool Selected { get { return _selected; } set { if (_selected == value) return; _selected = value; _sel.To(value ? 1f : 0f, 160, GBMotion.Ease); Invalidate(); } }
    public bool Badge { get { return _badge; } set { _badge = value; Invalidate(); } }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover.To(1, 120, GBMotion.Ease); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 180, GBMotion.Ease); }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override bool IsInputKey(Keys k) { if (k == Keys.Enter || k == Keys.Space) return true; return base.IsInputKey(k); }
    protected override void OnKeyDown(KeyEventArgs e) { base.OnKeyDown(e); if (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Space) { e.Handled = true; OnClick(EventArgs.Empty); } }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = Parent != null ? Parent.BackColor : GBTheme.Bg;
        g.Clear(bg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        float k = _sel.Value, h = _hover.Value;
        RectangleF box = new RectangleF(10 * s, 2 * s, Width - 20 * s, Height - 4 * s);
        bool pure = GBTheme.Edition == 2;
        if (GBTheme.Shape == 0) {
            float a = Math.Max(0.13f * k, 0.06f * h);
            if (a > 0.005f) using (SolidBrush b = new SolidBrush(GBTheme.Mix(bg, Accent, a))) g.FillRectangle(b, box);
            if (k > 0.01f) using (SolidBrush b = new SolidBrush(Color.FromArgb((int)(255 * k), Accent))) g.FillRectangle(b, box.Left, box.Top + 7 * s, 3 * s, box.Height - 14 * s);
        } else {
            // Fond arrondi : teinte d'accent (ARENA, avec la barre), teinte douce sans barre (PURE)
            float a = pure ? Math.Max(0.12f * k, 0.05f * h) : Math.Max(0.16f * k, 0.07f * h);
            Color tint = pure && k < 0.01f ? GBTheme.Text : Accent;
            if (a > 0.005f) using (GraphicsPath bp = GBTheme.RoundRect(box, Math.Min(GBTheme.Radius, 10) * s)) using (SolidBrush b = new SolidBrush(GBTheme.Mix(bg, tint, a))) g.FillPath(b, bp);
            if (!pure && k > 0.01f) using (GraphicsPath ip = GBTheme.RoundRect(new RectangleF(box.Left + 4 * s, box.Top + 9 * s, 3 * s, box.Height - 18 * s), 1.5f * s)) using (SolidBrush b = new SolidBrush(Color.FromArgb((int)(255 * k), Accent))) g.FillPath(b, ip);
        }
        Color fg = GBTheme.Mix(GBTheme.Mix(GBTheme.Muted, GBTheme.Text, 0.55f + 0.45f * h), Accent, k);
        int x = (int)(24 * s);
        TextFormatFlags fl = TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
        if (GlyphFont != null && !string.IsNullOrEmpty(Glyph)) {
            TextRenderer.DrawText(g, Glyph, GlyphFont, new Rectangle(x, 0, (int)(22 * s), Height), fg, fl | TextFormatFlags.HorizontalCenter | TextFormatFlags.NoPadding);
            x += (int)(32 * s);
        }
        TextRenderer.DrawText(g, Text, Font, new Rectangle(x, 0, Math.Max(1, Width - x - (int)(26 * s)), Height), fg, fl | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
        if (_badge) {
            float d = 8 * s, bx = Width - 26 * s, by = Height / 2f - d / 2f;
            if (GBTheme.Glow) using (SolidBrush gb = new SolidBrush(Color.FromArgb(60, GBTheme.Yellow))) g.FillEllipse(gb, bx - 3 * s, by - 3 * s, d + 6 * s, d + 6 * s);
            using (SolidBrush bb = new SolidBrush(GBTheme.Yellow)) g.FillEllipse(bb, bx, by, d, d);
        }
        if (Focused && ShowFocusCues) {
            if (GBTheme.Shape == 0) using (Pen fp = new Pen(Color.FromArgb(130, Accent), 1f)) g.DrawRectangle(fp, box.Left, box.Top, box.Width - 1, box.Height - 1);
            else using (GraphicsPath fpth = GBTheme.RoundRect(new RectangleF(box.Left, box.Top, box.Width - 1, box.Height - 1), Math.Min(GBTheme.Radius, 10) * s)) using (Pen fp = new Pen(Color.FromArgb(130, Accent), 1f)) g.DrawPath(fp, fpth);
        }
    }
}

// ----------------------- Liste deroulante du theme (dessinee en entier : la version Windows reste blanche) -----------------------
public class GBCombo : ComboBox {
    bool _hover;
    public Color Border = GBTheme.Line;
    public Color Hi = GBTheme.Sel;
    public GBCombo() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        DrawMode = DrawMode.OwnerDrawFixed; DropDownStyle = ComboBoxStyle.DropDownList; FlatStyle = FlatStyle.Flat;
        BackColor = GBTheme.Deep; ForeColor = GBTheme.Text;
        Cursor = Cursors.Hand;
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        float s = Math.Max(1f, g.DpiX / 96f);
        bool hot = Enabled && (_hover || Focused || DroppedDown);
        Color bc = hot ? GBTheme.Mix(Border, GBTheme.Cyan, 0.65f) : Border;
        if (GBTheme.Shape == 0) {
            using (SolidBrush b = new SolidBrush(BackColor)) g.FillRectangle(b, ClientRectangle);
            using (Pen p = new Pen(bc, 1f)) g.DrawRectangle(p, 0, 0, Width - 1, Height - 1);
        } else {
            g.Clear(Parent != null ? Parent.BackColor : GBTheme.Bg);
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath rp = GBTheme.RoundRect(new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f), Math.Min(GBTheme.Radius, 8) * s)) {
                using (SolidBrush b = new SolidBrush(BackColor)) g.FillPath(b, rp);
                using (Pen p = new Pen(bc, 1f)) g.DrawPath(p, rp);
            }
        }
        int aw = (int)(24 * s);
        float cx = Width - aw / 2f, cy = Height / 2f;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        using (Pen ap = new Pen(Enabled ? GBTheme.Cyan : GBTheme.Muted, 1.6f * s))
            g.DrawLines(ap, new PointF[] { new PointF(cx - 4 * s, cy - 2 * s), new PointF(cx, cy + 2 * s), new PointF(cx + 4 * s, cy - 2 * s) });
        string t = SelectedIndex >= 0 ? GetItemText(SelectedItem) : "";
        TextRenderer.DrawText(g, t, Font, new Rectangle((int)(8 * s), 0, Math.Max(1, Width - aw - (int)(10 * s)), Height), Enabled ? ForeColor : GBTheme.Muted,
            TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
    }
    protected override void OnDrawItem(DrawItemEventArgs e) {
        bool sel = (e.State & DrawItemState.Selected) != 0;
        using (SolidBrush b = new SolidBrush(sel ? Hi : BackColor)) e.Graphics.FillRectangle(b, e.Bounds);
        if (e.Index < 0) return;
        Rectangle r = new Rectangle(e.Bounds.X + 6, e.Bounds.Y, Math.Max(1, e.Bounds.Width - 8), e.Bounds.Height);
        TextRenderer.DrawText(e.Graphics, GetItemText(Items[e.Index]), Font, r, sel ? GBTheme.Cyan : ForeColor,
            TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
    }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover = true; Invalidate(); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover = false; Invalidate(); }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override void OnSelectedIndexChanged(EventArgs e) { base.OnSelectedIndexChanged(e); Invalidate(); }
    protected override void OnDropDownClosed(EventArgs e) { base.OnDropDownClosed(e); Invalidate(); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); Invalidate(); }
}

// ----------------------- Carte : bordure fine et repere neon (NEXUS), arrondie avec repere (ARENA), blanche et douce (PURE) -----------------------
public class GBCard : Panel {
    public Color Border = GBTheme.Line;
    public Color Accent = GBTheme.Cyan;
    public GBCard() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        BackColor = GBTheme.Card;
    }
    protected override void OnPaint(PaintEventArgs e) {
        if (GBTheme.Shape == 0) {
            base.OnPaint(e);
            Graphics g0 = e.Graphics;
            float s0 = Math.Max(1f, g0.DpiX / 96f);
            using (Pen p = new Pen(Border, 1f)) g0.DrawRectangle(p, 0, 0, Width - 1, Height - 1);
            using (SolidBrush a = new SolidBrush(Accent)) g0.FillRectangle(a, 0, 0, 22 * s0, 2 * s0);
            return;
        }
        Graphics g = e.Graphics;
        float s = Math.Max(1f, g.DpiX / 96f);
        g.Clear(Parent != null ? Parent.BackColor : GBTheme.Bg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float rad = (GBTheme.Radius + 2) * s;
        bool pure = GBTheme.Edition == 2;
        RectangleF r = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - (pure ? 2.5f : 1.5f));
        if (pure) {
            // Ombre tres legere sous la carte (sur le fond de la page)
            using (GraphicsPath sp = GBTheme.RoundRect(new RectangleF(r.X, r.Y + 1.5f, r.Width, r.Height), rad))
            using (SolidBrush sb = new SolidBrush(Color.FromArgb(16, 0, 0, 0))) g.FillPath(sb, sp);
        }
        using (GraphicsPath p = GBTheme.RoundRect(r, rad)) {
            using (SolidBrush b = new SolidBrush(BackColor)) g.FillPath(b, p);
            Color bc = pure ? GBTheme.Mix(Border, BackColor, 0.35f) : Border;
            using (Pen pen = new Pen(bc, 1f)) g.DrawPath(pen, p);
        }
        if (!pure) using (GraphicsPath ap = GBTheme.Pill(new RectangleF(rad, 0.5f, 26 * s, 3 * s))) using (SolidBrush a = new SolidBrush(Accent)) g.FillPath(a, ap);
    }
}

// ----------------------- Texte d'etat qui se "decode" quand il change (rare : debut / fin du boost ; PURE : change simplement) -----------------------
public class GBDecodeLabel : Label {
    const string Glyphs = "#%&/\\<>[]=+*01_";
    string _target;
    Tween _p;
    readonly Random _rnd = new Random();
    public GBDecodeLabel() {
        _p = new Tween(this, 1);
        _p.Updated += delegate { Render(); };
    }
    public override string Text {
        get { return _target ?? base.Text; }
        set {
            string v = value ?? "";
            if (_target == null || GBTheme.Edition == 2) { _target = v; base.Text = v; return; }
            if (v == _target) return;
            _target = v;
            _p.From(0f, 1f, 220, GBMotion.EaseOut);   // instantane si animations coupees ou fenetre cachee
            if (!_p.Running) base.Text = v;
        }
    }
    void Render() {
        string t = _target ?? "";
        float p = _p.Value;
        if (p >= 1f || t.Length == 0) { base.Text = t; return; }
        int shown = (int)(t.Length * p);
        char[] c = t.ToCharArray();
        for (int i = shown; i < c.Length; i++) if (c[i] != ' ') c[i] = Glyphs[_rnd.Next(Glyphs.Length)];
        base.Text = new string(c);
    }
}

// ----------------------- Titre : "glitch" (NEXUS), ombre d'accent (ARENA), sobre (PURE) -----------------------
public class GBTitle : Control {
    public string Sub = "";
    public Font SubFont;
    public GBTitle() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        TabStop = false;
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : GBTheme.Bg);
        g.TextRenderingHint = TextRenderingHint.AntiAliasGridFit;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        SizeF ts = g.MeasureString(Text, Font);
        if (GBTheme.Edition == 0) {
            using (SolidBrush m = new SolidBrush(Color.FromArgb(170, GBTheme.Magenta))) g.DrawString(Text, Font, m, -2 * s + 1, 1 * s);
            using (SolidBrush c = new SolidBrush(Color.FromArgb(150, GBTheme.Cyan))) g.DrawString(Text, Font, c, 2 * s + 1, -1 * s);
            using (SolidBrush w = new SolidBrush(GBTheme.Text)) g.DrawString(Text, Font, w, 1, 0);
            float y = ts.Height - 2 * s;
            using (Pen line = new Pen(GBTheme.Line, 1f)) g.DrawLine(line, 2, y, Width - 2, y);
            using (Pen a = new Pen(GBTheme.Yellow, 3f * s)) g.DrawLine(a, 2, y, 2 + 46 * s, y);
            using (Pen b = new Pen(GBTheme.Cyan, 3f * s)) g.DrawLine(b, 2 + 52 * s, y, 2 + 60 * s, y);
        } else if (GBTheme.Edition == 1) {
            // ARENA : ombre decalee de l'accent (style autocollant) et trait accent / accent 2
            using (SolidBrush m = new SolidBrush(Color.FromArgb(200, GBTheme.Accent))) g.DrawString(Text, Font, m, 1 + 2 * s, 2 * s);
            using (SolidBrush w = new SolidBrush(GBTheme.Text)) g.DrawString(Text, Font, w, 1, 0);
            float y = ts.Height - 1 * s;
            using (GraphicsPath a = GBTheme.Pill(new RectangleF(2, y - 1.5f * s, 40 * s, 3.5f * s))) using (SolidBrush b = new SolidBrush(GBTheme.Accent)) g.FillPath(b, a);
            using (GraphicsPath a = GBTheme.Pill(new RectangleF(2 + 45 * s, y - 1.5f * s, 12 * s, 3.5f * s))) using (SolidBrush b = new SolidBrush(GBTheme.Accent2)) g.FillPath(b, a);
        } else {
            using (SolidBrush w = new SolidBrush(GBTheme.Text)) g.DrawString(Text, Font, w, 1, 0);
        }
        if (!string.IsNullOrEmpty(Sub) && SubFont != null)
            TextRenderer.DrawText(g, Sub, SubFont, new Point((int)(ts.Width + 4 * s), (int)(ts.Height / 2 - 6 * s)), GBTheme.Muted);
    }
}

// Curseur de reglage GameBoost : piste, partie remplie, bouton rond deplacable, valeur affichee.
// Souris (clic / glisser), molette (si selectionne), clavier (fleches, Debut, Fin). Dessin lisse et sans scintillement.
public class GBSlider : Control {
    int _min = 0, _max = 100, _value = 50;
    bool _drag, _hover;
    public Color TrackColor = GBTheme.Track;
    public Color FillColor = GBTheme.Cyan;
    public Color ThumbColor = GBTheme.IsDarkTheme ? GBTheme.Bg : Color.White;
    public Color ValueColor = GBTheme.Text;
    public Color DisabledColor = GBTheme.Disabled;
    Tween _grow;
    public int TrackHeight = 6;
    public int ThumbSize = 16;
    public bool ShowValue = true;
    public int ValueWidth = 120;
    public string Suffix = "";
    public string[] Labels = null;        // texte pour chaque valeur (ex : Basse, Normale, Haute)
    public Color[] LabelColors = null;    // couleur pour chaque valeur
    public int Snap = 1;                  // pas (ex : 256 pour des Mo)
    public int StepKey = 1;
    public int StepWheel = 1;
    public event EventHandler ValueChanged;    // pendant le deplacement
    public event EventHandler ValueCommitted;  // quand l'utilisateur lache le curseur

    public GBSlider() {
        SetStyle(ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw |
                 ControlStyles.UserPaint | ControlStyles.Selectable, true);
        Height = 28; Width = 260;
        Cursor = Cursors.Hand;
        TabStop = true;
        _grow = new Tween(this, 0);
    }
    void UpdateGrow() { _grow.To(((_hover || _drag) && Enabled) ? 1f : 0f, (_hover || _drag) ? 150 : 200, GBMotion.Ease); }

    public int Minimum { get { return _min; } set { _min = value; if (_max < _min) _max = _min; SetValueSilently(_value); } }
    public int Maximum { get { return _max; } set { _max = Math.Max(value, _min); SetValueSilently(_value); } }
    public int Value {
        get { return _value; }
        set {
            int v = Clamp(value);
            if (v != _value) { _value = v; Invalidate(); if (ValueChanged != null) ValueChanged(this, EventArgs.Empty); }
        }
    }
    public void SetValueSilently(int v) { _value = Clamp(v); Invalidate(); }

    int Clamp(int v) {
        v = Math.Max(_min, Math.Min(_max, v));
        if (Snap > 1) { v = _min + (int)Math.Round((double)(v - _min) / Snap) * Snap; v = Math.Max(_min, Math.Min(_max, v)); }
        return v;
    }

    float Scale() { using (Graphics g = CreateGraphics()) { return Math.Max(1f, g.DpiX / 96f); } }

    Rectangle TrackRect(float s) {
        int th = (int)(ThumbSize * s), tr = Math.Max(2, (int)(TrackHeight * s));
        int vw = ShowValue ? (int)(ValueWidth * s) : 0;
        int pad = th / 2 + 2;
        return new Rectangle(pad, (Height - tr) / 2, Math.Max(10, Width - vw - pad * 2), tr);
    }
    int XFromValue(Rectangle r, int v) { if (_max == _min) return r.Left; return r.Left + (int)Math.Round((double)(v - _min) * r.Width / (_max - _min)); }
    int ValueFromX(int x) {
        Rectangle r = TrackRect(Scale());
        if (r.Width <= 0) return _min;
        double t = (double)(x - r.Left) / r.Width;
        t = Math.Max(0, Math.Min(1, t));
        return Clamp(_min + (int)Math.Round(t * (_max - _min)));
    }

    public string ValueText {
        get {
            int i = _value - _min;
            if (Labels != null && i >= 0 && i < Labels.Length) return Labels[i];
            return _value.ToString() + Suffix;
        }
    }
    Color CurrentFill {
        get {
            int i = _value - _min;
            if (LabelColors != null && i >= 0 && i < LabelColors.Length) return LabelColors[i];
            return FillColor;
        }
    }

    static GraphicsPath Pill(Rectangle r) {
        GraphicsPath p = new GraphicsPath();
        int d = Math.Max(2, Math.Min(r.Height, r.Width));
        p.AddArc(r.X, r.Y, d, d, 90, 180);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 180);
        p.CloseFigure();
        return p;
    }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.Clear(BackColor);
        float s = Math.Max(1f, g.DpiX / 96f);
        Rectangle r = TrackRect(s);
        Color fill = Enabled ? CurrentFill : DisabledColor;
        using (GraphicsPath p = Pill(r)) using (SolidBrush b = new SolidBrush(TrackColor)) g.FillPath(b, p);
        int tx = XFromValue(r, _value);
        Rectangle f = new Rectangle(r.Left, r.Top, Math.Max(r.Height, tx - r.Left), r.Height);
        if (Enabled && GBTheme.Glow) using (GraphicsPath gp = Pill(f)) using (Pen glow = new Pen(Color.FromArgb(40, fill), 4f * s)) g.DrawPath(glow, gp);
        using (GraphicsPath p = Pill(f)) using (SolidBrush b = new SolidBrush(fill)) g.FillPath(b, p);
        float k = Enabled ? _grow.Value : 0f;
        int ts = (int)(ThumbSize * s + 3 * s * k);
        Rectangle th = new Rectangle(tx - ts / 2, Height / 2 - ts / 2, ts, ts);
        if (GBTheme.Edition == 2) {
            // PURE : bouton blanc avec ombre douce, sans anneau colore (comme macOS)
            using (SolidBrush sh = new SolidBrush(Color.FromArgb(30 + (int)(20 * k), 0, 0, 0))) g.FillEllipse(sh, th.X - 0.5f, th.Y + 1f * s, th.Width + 1f, th.Height + 1f);
            using (SolidBrush b = new SolidBrush(Enabled ? ThumbColor : BackColor)) g.FillEllipse(b, th);
            using (Pen pen = new Pen(Color.FromArgb(40, 0, 0, 0), 1f)) g.DrawEllipse(pen, th);
            if (Focused && Enabled) using (Pen fp = new Pen(Color.FromArgb(140, fill), 2f * s)) g.DrawEllipse(fp, th.X - 3, th.Y - 3, th.Width + 6, th.Height + 6);
        } else {
            if (k > 0.01f) using (Pen ring = new Pen(Color.FromArgb((int)(70 * k), fill), 4f * s)) g.DrawEllipse(ring, th);
            using (SolidBrush b = new SolidBrush(Enabled ? ThumbColor : BackColor)) g.FillEllipse(b, th);
            using (Pen pen = new Pen(fill, 2f * s)) g.DrawEllipse(pen, th);
            float dot = Math.Max(2f, ts * 0.32f);
            using (SolidBrush db = new SolidBrush(fill)) g.FillEllipse(db, tx - dot / 2f, Height / 2f - dot / 2f, dot, dot);
            if (Focused && Enabled) {
                using (Pen fp = new Pen(Color.FromArgb(110, fill), 1f)) g.DrawEllipse(fp, th.X - 3, th.Y - 3, th.Width + 6, th.Height + 6);
            }
        }
        if (ShowValue) {
            int vw = (int)(ValueWidth * s);
            Rectangle vr = new Rectangle(Width - vw + (int)(6 * s), 0, vw - (int)(6 * s), Height);
            Color tc = Enabled ? (LabelColors != null ? fill : ValueColor) : DisabledColor;
            TextRenderer.DrawText(g, ValueText, Font, vr, tc, TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
        }
    }

    void Commit() { if (ValueCommitted != null) ValueCommitted(this, EventArgs.Empty); }

    protected override void OnMouseDown(MouseEventArgs e) {
        base.OnMouseDown(e);
        if (e.Button == MouseButtons.Left && Enabled) { Focus(); _drag = true; Capture = true; UpdateGrow(); Value = ValueFromX(e.X); Invalidate(); }
    }
    protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); if (_drag) Value = ValueFromX(e.X); }
    protected override void OnMouseUp(MouseEventArgs e) {
        base.OnMouseUp(e);
        if (_drag) { _drag = false; Capture = false; UpdateGrow(); Invalidate(); Commit(); }
    }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover = true; UpdateGrow(); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover = false; UpdateGrow(); }
    protected override void OnMouseWheel(MouseEventArgs e) {
        base.OnMouseWheel(e);
        if (!Enabled || !Focused) return;
        int old = _value;
        Value = _value + (e.Delta > 0 ? 1 : -1) * Math.Max(StepWheel, Snap);
        if (_value != old) Commit();
    }
    protected override bool IsInputKey(Keys k) {
        if (k == Keys.Left || k == Keys.Right || k == Keys.Up || k == Keys.Down || k == Keys.Home || k == Keys.End) return true;
        return base.IsInputKey(k);
    }
    protected override void OnKeyDown(KeyEventArgs e) {
        base.OnKeyDown(e);
        if (!Enabled) return;
        int old = _value;
        int step = Math.Max(StepKey, Snap);
        if (e.KeyCode == Keys.Left || e.KeyCode == Keys.Down) Value = _value - step;
        else if (e.KeyCode == Keys.Right || e.KeyCode == Keys.Up) Value = _value + step;
        else if (e.KeyCode == Keys.Home) Value = _min;
        else if (e.KeyCode == Keys.End) Value = _max;
        if (_value != old) Commit();
    }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); UpdateGrow(); Invalidate(); }
}

// ----------------------- Carte du choix du modele (NEXUS / ARENA / PURE) : apercu dessine avec les couleurs du modele -----------------------
public class GBEditionCard : Control {
    Tween _hover, _press;
    public string Title = "", Tagline = "", Desc = "";
    public Font TitleFont, TagFont, DescFont;
    public Color CBg, CPanel, CLine, CText, CMuted, CAccent, CAccent2, COnAccent;
    public int CShape = 0, CRadius = 8;
    public bool CGlow = true, Current = false;
    public GBEditionCard() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        _hover = new Tween(this, 0); _hover.Motion = false; _press = new Tween(this, 0);
        Cursor = Cursors.Hand; TabStop = true;
    }
    GraphicsPath Shp(RectangleF r, float cut, float rad) {
        if (CShape == 2) return GBTheme.Pill(r);
        if (CShape == 1) return GBTheme.RoundRect(r, rad);
        return GBTheme.Chamfer(r, cut);
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : Color.Black);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
        float s = Math.Max(1f, g.DpiX / 96f);
        float h = _hover.Value, pr = _press.Value;
        bool kf = Focused && ShowFocusCues;   // anneau de focus au clavier seulement
        bool hot = h > 0.01f || kf;
        float sc = 1f - 0.03f * pr;
        g.TranslateTransform(Width / 2f, Height / 2f); g.ScaleTransform(sc, sc); g.TranslateTransform(-Width / 2f, -Height / 2f);
        RectangleF r = new RectangleF(5 * s, 5 * s, Width - 10 * s, Height - 10 * s);
        float rad = (CRadius + 4) * s;
        using (GraphicsPath p = Shp(r, 16 * s, rad)) {
            if (CGlow && h > 0.01f) for (int i = 3; i >= 1; i--) using (Pen gp = new Pen(Color.FromArgb((int)(34 * h / i), CAccent), (1.5f + i * 2.5f) * s)) g.DrawPath(gp, p);
            using (SolidBrush b = new SolidBrush(CBg)) g.FillPath(b, p);
            Color bc = GBTheme.Mix(CLine, CAccent, kf ? 1f : h);
            using (Pen pen = new Pen(bc, (hot ? 2f : 1f) * s)) g.DrawPath(pen, p);
        }
        // Apercu : une mini fenetre aux couleurs du modele (carte, titre, jauge, interrupteur, bouton)
        float pad = 18 * s;
        RectangleF win = new RectangleF(r.Left + pad, r.Top + pad, r.Width - pad * 2, r.Height * 0.42f);
        using (GraphicsPath wp = Shp(win, 10 * s, CRadius * s)) {
            using (SolidBrush b = new SolidBrush(CPanel)) g.FillPath(b, wp);
            using (Pen pen = new Pen(CLine, 1f)) g.DrawPath(pen, wp);
        }
        float ix = win.Left + 12 * s, iw = win.Width - 24 * s, iy = win.Top + 12 * s;
        using (SolidBrush tb = new SolidBrush(CText)) g.FillRectangle(tb, ix, iy, iw * 0.45f, 6 * s);
        using (SolidBrush mb = new SolidBrush(CMuted)) { g.FillRectangle(mb, ix, iy + 12 * s, iw * 0.75f, 3 * s); g.FillRectangle(mb, ix, iy + 19 * s, iw * 0.6f, 3 * s); }
        // Jauge
        float my = iy + 30 * s, mw = iw * 0.62f, mh = 5 * s;
        using (SolidBrush off = new SolidBrush(GBTheme.Mix(CPanel, CMuted, 0.25f))) g.FillRectangle(off, ix, my, mw, mh);
        using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(ix, my, mw * 0.7f + 1, mh), CAccent, CAccent2, 0f)) g.FillRectangle(lb, ix, my, mw * 0.7f, mh);
        // Interrupteur allume
        RectangleF tg = new RectangleF(ix + iw - 26 * s, my - 4 * s, 26 * s, 14 * s);
        using (GraphicsPath tp = GBTheme.Pill(tg)) using (SolidBrush b = new SolidBrush(CAccent)) g.FillPath(b, tp);
        using (SolidBrush kb = new SolidBrush(COnAccent)) g.FillEllipse(kb, tg.Right - 12 * s, tg.Top + 2 * s, 10 * s, 10 * s);
        // Bouton plein
        RectangleF bt = new RectangleF(ix, win.Bottom - 26 * s, iw, 16 * s);
        if (bt.Top > my + 10 * s) {
            using (GraphicsPath bp = Shp(bt, 5 * s, CRadius * 0.6f * s)) using (SolidBrush b = new SolidBrush(CAccent)) g.FillPath(b, bp);
        }
        // Textes
        float ty = win.Bottom + 16 * s;
        TextFormatFlags fl = TextFormatFlags.Left | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        Font tf = TitleFont ?? Font, gf = TagFont ?? Font, df = DescFont ?? Font;
        Size ts = TextRenderer.MeasureText(g, Title, tf, Size.Empty, fl);
        TextRenderer.DrawText(g, Title, tf, new Rectangle((int)(r.Left + pad), (int)ty, (int)(r.Width - pad * 2), ts.Height), CText, fl | TextFormatFlags.SingleLine);
        if (Current) {
            string cur = "ACTUEL";
            Size cs = TextRenderer.MeasureText(g, cur, df, Size.Empty, fl);
            RectangleF cr = new RectangleF(r.Right - pad - cs.Width - 12 * s, ty + (ts.Height - cs.Height - 6 * s) / 2f, cs.Width + 12 * s, cs.Height + 6 * s);
            using (GraphicsPath cp = GBTheme.Pill(cr)) using (SolidBrush b = new SolidBrush(GBTheme.Mix(CBg, CAccent, 0.22f))) g.FillPath(b, cp);
            TextRenderer.DrawText(g, cur, df, new Rectangle((int)(cr.Left + 6 * s), (int)(cr.Top + 3 * s), cs.Width + 2, cs.Height), CAccent, fl | TextFormatFlags.SingleLine);
        }
        ty += ts.Height + 4 * s;
        Size gs = TextRenderer.MeasureText(g, Tagline, gf, Size.Empty, fl);
        TextRenderer.DrawText(g, Tagline, gf, new Rectangle((int)(r.Left + pad), (int)ty, (int)(r.Width - pad * 2), gs.Height), CAccent, fl | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        ty += gs.Height + 8 * s;
        TextRenderer.DrawText(g, Desc, df, new Rectangle((int)(r.Left + pad), (int)ty, (int)(r.Width - pad * 2), (int)Math.Max(1f, r.Bottom - ty - 10 * s)), CMuted, fl | TextFormatFlags.WordBreak | TextFormatFlags.EndEllipsis);
    }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover.To(1, 150, GBMotion.Ease); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 200, GBMotion.Ease); _press.To(0, 160, GBMotion.EaseOut); }
    protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button == MouseButtons.Left) { Focus(); _press.To(1, 100, GBMotion.EaseOut); } }
    protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); _press.To(0, 160, GBMotion.EaseOut); }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override bool IsInputKey(Keys k) { if (k == Keys.Enter || k == Keys.Space) return true; return base.IsInputKey(k); }
    protected override void OnKeyDown(KeyEventArgs e) { base.OnKeyDown(e); if (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Space) { e.Handled = true; OnClick(EventArgs.Empty); } }
}
"@
    $uiRefs = @('System.Windows.Forms', 'System.Drawing')
    if ($PSVersionTable.PSEdition -eq 'Core') {
        # PowerShell 7 (secours) : WinForms y est decoupe en plusieurs assemblies -> references explicites
        $refDir = Join-Path $PSHOME 'ref'
        $uiRefs = New-Object System.Collections.Generic.List[string]
        foreach ($a in @([System.Windows.Forms.Form].Assembly, [System.Drawing.Bitmap].Assembly)) {
            $cands = @($a.Location) + @(foreach ($an in $a.GetReferencedAssemblies()) { try { [System.Reflection.Assembly]::Load($an).Location } catch {} })
            foreach ($l in $cands) { if ($l -and -not $uiRefs.Contains($l) -and -not (Test-Path -LiteralPath (Join-Path $refDir (Split-Path $l -Leaf)))) { $uiRefs.Add($l) } }
        }
        if (Test-Path -LiteralPath $refDir) { foreach ($r in Get-ChildItem -LiteralPath $refDir -Filter *.dll) { $uiRefs.Add($r.FullName) } }
    }
    if (-not (Add-GBCompiled 'GBUi' $uiSrc $uiRefs 'GBSlider')) { throw $Script:GBCompileError }
} catch { $Script:UiOK = $false }
$Script:SliderOK = $Script:UiOK

$Script:NativeOK = $true
try {
$nativeSrc = @"
using System;
using System.Runtime.InteropServices;
public static class GBNative {
    // Texte net sur les ecrans zoomes (125 %, 150 %, 200 %) : GameBoost met ses fenetres a l'echelle lui-meme
    [DllImport("shcore.dll")] static extern int SetProcessDpiAwareness(int value);
    [DllImport("user32.dll")] static extern bool SetProcessDPIAware();
    public static bool MakeDpiAware() {
        try { int hr = SetProcessDpiAwareness(1); if (hr == 0 || hr == unchecked((int)0x80070005)) return true; } catch { }
        try { return SetProcessDPIAware(); } catch { return false; }
    }
    [DllImport("psapi.dll")]
    public static extern bool EmptyWorkingSet(IntPtr hProcess);
    [DllImport("user32.dll")]
    public static extern bool SystemParametersInfo(uint action, uint param, int[] vparam, uint winIni);
    // Mode d'alimentation de Windows 10/11 (curseur "Meilleures performances")
    [DllImport("powrprof.dll")]
    public static extern uint PowerGetActualOverlayScheme(out Guid overlay);
    [DllImport("powrprof.dll")]
    public static extern uint PowerSetActiveOverlayScheme(Guid overlay);
    [DllImport("powrprof.dll")]
    [return: MarshalAs(UnmanagedType.I1)]
    static extern bool GetPwrCapabilities(byte[] caps);
    // PC en "veille moderne" (S0) : la plupart des portables recents
    public static bool IsModernStandby() {
        byte[] b = new byte[256];
        if (!GetPwrCapabilities(b)) return false;
        return b[20] != 0;   // SYSTEM_POWER_CAPABILITIES.AoAc
    }
}
public static class GBMem {
    [StructLayout(LayoutKind.Sequential)]
    struct LUID { public uint Low; public int High; }
    [StructLayout(LayoutKind.Sequential)]
    struct TOKEN_PRIVILEGES { public uint Count; public LUID Luid; public uint Attr; }
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool OpenProcessToken(IntPtr h, uint access, out IntPtr token);
    [DllImport("advapi32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    static extern bool LookupPrivilegeValue(string system, string name, out LUID luid);
    [DllImport("advapi32.dll", SetLastError = true)]
    static extern bool AdjustTokenPrivileges(IntPtr token, bool disableAll, ref TOKEN_PRIVILEGES state, uint len, IntPtr prev, IntPtr retLen);
    [DllImport("kernel32.dll")]
    static extern IntPtr GetCurrentProcess();
    [DllImport("kernel32.dll")]
    static extern bool CloseHandle(IntPtr h);
    [DllImport("ntdll.dll")]
    static extern int NtSetSystemInformation(int infoClass, ref int info, int length);
    public static bool EnablePrivilege(string name) {
        IntPtr token;
        if (!OpenProcessToken(GetCurrentProcess(), 0x0020 | 0x0008, out token)) return false;
        try {
            TOKEN_PRIVILEGES tp = new TOKEN_PRIVILEGES();
            tp.Count = 1; tp.Attr = 0x2;
            LUID luid;
            if (!LookupPrivilegeValue(null, name, out luid)) return false;
            tp.Luid = luid;
            if (!AdjustTokenPrivileges(token, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero)) return false;
            return Marshal.GetLastWin32Error() == 0;
        } finally { CloseHandle(token); }
    }
    // Vide la liste "en attente" (standby) : meme methode que Intelligent Standby List Cleaner
    public static int PurgeStandby() {
        EnablePrivilege("SeProfileSingleProcessPrivilege");
        int command = 4;                                  // MemoryPurgeStandbyList
        return NtSetSystemInformation(80, ref command, 4); // SystemMemoryListInformation
    }
}
// Cartes graphiques vues par le noyau graphique de Windows (D3DKMT) : type, memoire video, emplacement PCI
public static class GBGpu {
    [StructLayout(LayoutKind.Sequential)]
    public struct LUID { public uint LowPart; public int HighPart; }
    [StructLayout(LayoutKind.Sequential)]
    struct ADAPTERINFO { public uint hAdapter; public LUID AdapterLuid; public uint NumOfSources; public int bPrecisePresentRegionsPreferred; }
    [StructLayout(LayoutKind.Sequential)]
    struct ENUMADAPTERS2 { public uint NumAdapters; public IntPtr pAdapters; }
    [StructLayout(LayoutKind.Sequential)]
    struct QUERYADAPTERINFO { public uint hAdapter; public int Type; public IntPtr pPrivateDriverData; public uint PrivateDriverDataSize; }
    [StructLayout(LayoutKind.Sequential)]
    struct CLOSEADAPTER { public uint hAdapter; }
    [DllImport("gdi32.dll")] static extern int D3DKMTEnumAdapters2(ref ENUMADAPTERS2 e);
    [DllImport("gdi32.dll")] static extern int D3DKMTQueryAdapterInfo(ref QUERYADAPTERINFO q);
    [DllImport("gdi32.dll")] static extern int D3DKMTCloseAdapter(ref CLOSEADAPTER c);

    public class Info {
        public string Luid; public string Name;
        public uint TypeFlags; public bool TypeOk;
        public ulong DedicatedVideo; public ulong DedicatedSystem; public ulong SharedSystem; public bool MemOk;
        public uint Bus; public uint Device; public uint Function; public bool AddrOk;
        public uint Sources;
    }

    static int Query(uint h, int type, IntPtr buf, int size) {
        QUERYADAPTERINFO q = new QUERYADAPTERINFO();
        q.hAdapter = h; q.Type = type; q.pPrivateDriverData = buf; q.PrivateDriverDataSize = (uint)size;
        return D3DKMTQueryAdapterInfo(ref q);
    }

    public static Info[] List() {
        System.Collections.Generic.List<Info> result = new System.Collections.Generic.List<Info>();
        ENUMADAPTERS2 e = new ENUMADAPTERS2();
        if (D3DKMTEnumAdapters2(ref e) != 0 || e.NumAdapters == 0) return result.ToArray();
        int sz = Marshal.SizeOf(typeof(ADAPTERINFO));
        uint count = e.NumAdapters;
        e.pAdapters = Marshal.AllocHGlobal(sz * (int)count);
        try {
            if (D3DKMTEnumAdapters2(ref e) != 0) return result.ToArray();
            for (int i = 0; i < e.NumAdapters && i < count; i++) {
                ADAPTERINFO a = (ADAPTERINFO)Marshal.PtrToStructure(new IntPtr(e.pAdapters.ToInt64() + (long)i * sz), typeof(ADAPTERINFO));
                Info inf = new Info();
                inf.Luid = string.Format("luid_0x{0:x8}_0x{1:x8}", (uint)a.AdapterLuid.HighPart, a.AdapterLuid.LowPart);
                inf.Sources = a.NumOfSources;
                IntPtr buf = Marshal.AllocHGlobal(4096);
                try {
                    if (Query(a.hAdapter, 15, buf, 4) == 0) { inf.TypeFlags = (uint)Marshal.ReadInt32(buf); inf.TypeOk = true; }            // KMTQAITYPE_ADAPTERTYPE
                    if (Query(a.hAdapter, 3, buf, 24) == 0) {                                                                                  // KMTQAITYPE_GETSEGMENTSIZE
                        inf.DedicatedVideo = (ulong)Marshal.ReadInt64(buf, 0); inf.DedicatedSystem = (ulong)Marshal.ReadInt64(buf, 8);
                        inf.SharedSystem = (ulong)Marshal.ReadInt64(buf, 16); inf.MemOk = true;
                    }
                    if (Query(a.hAdapter, 6, buf, 12) == 0) {                                                                                  // KMTQAITYPE_ADAPTERADDRESS
                        inf.Bus = (uint)Marshal.ReadInt32(buf, 0); inf.Device = (uint)Marshal.ReadInt32(buf, 4); inf.Function = (uint)Marshal.ReadInt32(buf, 8); inf.AddrOk = true;
                    }
                    if (Query(a.hAdapter, 8, buf, 260 * 2 * 4) == 0) { inf.Name = Marshal.PtrToStringUni(buf); }                              // KMTQAITYPE_ADAPTERREGISTRYINFO
                } finally { Marshal.FreeHGlobal(buf); }
                CLOSEADAPTER c = new CLOSEADAPTER(); c.hAdapter = a.hAdapter; D3DKMTCloseAdapter(ref c);
                result.Add(inf);
            }
        } finally { Marshal.FreeHGlobal(e.pAdapters); }
        return result.ToArray();
    }
}
"@
    if (-not (Add-GBCompiled 'GBNative' $nativeSrc $null 'GBGpu')) { throw $Script:GBCompileError }
} catch {
    $Script:NativeOK = $false
    $Script:NativeError = $_.Exception.Message
}

# --- Mesures rapides sans WMI (compteurs Windows PDH, instantane des processus, ping en arriere-plan) ---
$Script:FastOK = $true
try {
$fastSrc = @"
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Net;
using System.Net.NetworkInformation;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using System.Text.RegularExpressions;
using System.Threading;

// ======================= GameBoost : mesures rapides (sans WMI) =======================

// Compteurs de performance Windows (PDH), comme le Gestionnaire des taches : une seule collecte pour tout
public class GBPdh : IDisposable {
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] static extern uint PdhOpenQuery(string src, IntPtr user, out IntPtr query);
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] static extern uint PdhAddEnglishCounter(IntPtr query, string path, IntPtr user, out IntPtr counter);
    [DllImport("pdh.dll")] static extern uint PdhCollectQueryData(IntPtr query);
    [DllImport("pdh.dll")] static extern uint PdhCloseQuery(IntPtr query);
    [DllImport("pdh.dll", CharSet = CharSet.Unicode)] static extern uint PdhGetFormattedCounterArray(IntPtr counter, uint fmt, ref uint bufSize, out uint count, IntPtr buffer);
    [DllImport("pdh.dll")] static extern uint PdhGetFormattedCounterValue(IntPtr counter, uint fmt, IntPtr type, out FmtValue value);

    [StructLayout(LayoutKind.Explicit, Size = 16)]
    struct FmtValue { [FieldOffset(0)] public uint CStatus; [FieldOffset(8)] public double Value; }

    const uint FMT_DOUBLE_NOCAP = 0x200 | 0x8000;
    const uint PDH_MORE_DATA = 0x800007D2;
    const int ITEM_SIZE = 24;     // PDH_FMT_COUNTERVALUE_ITEM_W : nom (pointeur) + valeur alignee sur 8 octets (x86, x64, ARM64)
    const int ITEM_VALUE = 8;

    class Def { public string Key; public string Path; public bool Multi; public IntPtr Handle; }
    readonly List<Def> _defs = new List<Def>();
    IntPtr _query = IntPtr.Zero;
    int _collects;
    readonly Dictionary<string, double> _values = new Dictionary<string, double>();
    readonly Dictionary<string, KeyValuePair<string, double>[]> _arrays = new Dictionary<string, KeyValuePair<string, double>[]>();
    public int RefreshEvery = 6;      // recree la requete toutes les N collectes (nouvelles instances : jeu lance, nouveau disque...)
    public bool Ok { get { return _query != IntPtr.Zero; } }
    public string LastError = "";

    public void Add(string key, string englishPath, bool multi) { _defs.Add(new Def { Key = key, Path = englishPath, Multi = multi }); }

    public bool Open() {
        Close();
        IntPtr q;
        uint rc = PdhOpenQuery(null, IntPtr.Zero, out q);
        if (rc != 0) { LastError = "PdhOpenQuery 0x" + rc.ToString("X8"); return false; }
        _query = q;
        int ok = 0;
        foreach (Def d in _defs) {
            IntPtr c;
            if (PdhAddEnglishCounter(_query, d.Path, IntPtr.Zero, out c) == 0) { d.Handle = c; ok++; } else d.Handle = IntPtr.Zero;
        }
        if (ok == 0) { LastError = "aucun compteur"; Close(); return false; }
        PdhCollectQueryData(_query);   // premiere collecte = point de depart des compteurs de debit
        return true;
    }

    public bool Has(string key) { foreach (Def d in _defs) if (d.Key == key) return d.Handle != IntPtr.Zero; return false; }

    // Collecte tout, met les resultats en cache, puis recree la requete si besoin (sans trou de mesure)
    public bool Collect() {
        if (_query == IntPtr.Zero) return false;
        if (PdhCollectQueryData(_query) != 0) { return false; }
        _values.Clear(); _arrays.Clear();
        foreach (Def d in _defs) {
            if (d.Handle == IntPtr.Zero) continue;
            if (d.Multi) { KeyValuePair<string, double>[] a = ReadArray(d.Handle); if (a != null) _arrays[d.Key] = a; }
            else {
                FmtValue v;
                if (PdhGetFormattedCounterValue(d.Handle, FMT_DOUBLE_NOCAP, IntPtr.Zero, out v) == 0 && (v.CStatus == 0 || v.CStatus == 1)) _values[d.Key] = v.Value;
            }
        }
        _collects++;
        if (RefreshEvery > 0 && _collects % RefreshEvery == 0) Open();
        return true;
    }

    KeyValuePair<string, double>[] ReadArray(IntPtr counter) {
        uint size = 0, count;
        uint rc = PdhGetFormattedCounterArray(counter, FMT_DOUBLE_NOCAP, ref size, out count, IntPtr.Zero);
        if (rc != PDH_MORE_DATA || size == 0) return rc == 0 ? new KeyValuePair<string, double>[0] : null;
        IntPtr buf = Marshal.AllocHGlobal((int)size);
        try {
            rc = PdhGetFormattedCounterArray(counter, FMT_DOUBLE_NOCAP, ref size, out count, buf);
            if (rc != 0) return null;
            List<KeyValuePair<string, double>> res = new List<KeyValuePair<string, double>>((int)count);
            for (int i = 0; i < count; i++) {
                IntPtr it = new IntPtr(buf.ToInt64() + (long)i * ITEM_SIZE);
                uint st = (uint)Marshal.ReadInt32(it, ITEM_VALUE);
                if (st != 0 && st != 1) continue;
                string name = Marshal.PtrToStringUni(Marshal.ReadIntPtr(it, 0));
                double val = BitConverter.Int64BitsToDouble(Marshal.ReadInt64(it, ITEM_VALUE + 8));
                res.Add(new KeyValuePair<string, double>(name ?? "", val));
            }
            return res.ToArray();
        } finally { Marshal.FreeHGlobal(buf); }
    }

    // NaN = pas disponible (compteur absent ou premiere mesure)
    public double Value(string key) { double v; return _values.TryGetValue(key, out v) ? v : double.NaN; }
    public KeyValuePair<string, double>[] Array(string key) { KeyValuePair<string, double>[] a; return _arrays.TryGetValue(key, out a) ? a : null; }

    // Moteurs GPU : utilisation par carte (moteur le plus occupe, somme des processus) et par processus
    static readonly Regex EngRx = new Regex(@"^pid_(\d+)_(luid_0x[0-9a-fA-F]+_0x[0-9a-fA-F]+)_phys_\d+_eng_(\d+)_engtype_", RegexOptions.Compiled);
    public GBGpuAgg GpuAgg(string key) {
        KeyValuePair<string, double>[] a = Array(key);
        if (a == null) return null;
        GBGpuAgg r = new GBGpuAgg();
        Dictionary<string, double> eng = new Dictionary<string, double>();
        foreach (KeyValuePair<string, double> kv in a) {
            Match m = EngRx.Match(kv.Key);
            if (!m.Success) continue;
            string luid = m.Groups[2].Value.ToLowerInvariant();
            string ek = luid + "|" + m.Groups[3].Value;
            double u = kv.Value; if (u < 0 || double.IsNaN(u)) u = 0;
            double cur; eng.TryGetValue(ek, out cur); eng[ek] = cur + u;
            string pk = luid + "|" + m.Groups[1].Value;
            double pm; r.Procs.TryGetValue(pk, out pm); if (u > pm) r.Procs[pk] = u; else if (!r.Procs.ContainsKey(pk)) r.Procs[pk] = 0;
        }
        foreach (KeyValuePair<string, double> kv in eng) {
            string luid = kv.Key.Substring(0, kv.Key.IndexOf('|'));
            double v = Math.Min(100.0, kv.Value);
            double cur; if (!r.Adapters.TryGetValue(luid, out cur) || v > cur) r.Adapters[luid] = v;
        }
        return r;
    }

    public void Close() { if (_query != IntPtr.Zero) { PdhCloseQuery(_query); _query = IntPtr.Zero; } foreach (Def d in _defs) d.Handle = IntPtr.Zero; }
    public void Dispose() { Close(); }
}

public class GBGpuAgg {
    public Dictionary<string, double> Adapters = new Dictionary<string, double>();   // luid -> %
    public Dictionary<string, double> Procs = new Dictionary<string, double>();      // "luid|pid" -> % (moteur le plus utilise)
}

// Memoire physique instantanee (sans WMI)
public static class GBSys {
    [StructLayout(LayoutKind.Sequential)]
    struct MEMSTAT { public uint Length; public uint Load; public ulong TotalPhys; public ulong AvailPhys; public ulong TotalPage; public ulong AvailPage; public ulong TotalVirt; public ulong AvailVirt; public ulong AvailExt; }
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool GlobalMemoryStatusEx(ref MEMSTAT m);
    // [total, disponible] en octets, ou null
    public static ulong[] Memory() {
        MEMSTAT m = new MEMSTAT(); m.Length = (uint)Marshal.SizeOf(typeof(MEMSTAT));
        if (!GlobalMemoryStatusEx(ref m) || m.TotalPhys == 0) return null;
        return new ulong[] { m.TotalPhys, m.AvailPhys };
    }

    // GameBoost lui-meme en mode economie (coeurs efficaces sur les processeurs hybrides Intel 12e gen+) pendant le jeu
    [StructLayout(LayoutKind.Sequential)]
    struct PowerThrottling { public uint Version; public uint ControlMask; public uint StateMask; }
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool SetProcessInformation(IntPtr process, int infoClass, ref PowerThrottling info, uint size);
    [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
    public static bool SetSelfEco(bool on) {
        try {
            PowerThrottling p = new PowerThrottling();
            p.Version = 1; p.ControlMask = 0x1; p.StateMask = on ? 0x1u : 0x0u;   // PROCESS_POWER_THROTTLING_EXECUTION_SPEED
            return SetProcessInformation(GetCurrentProcess(), 4, ref p, (uint)Marshal.SizeOf(typeof(PowerThrottling)));
        } catch { return false; }
    }
}

// Instantane de tous les processus en UN appel systeme (nom, PID, temps processeur, memoire), comme le Gestionnaire des taches
public class GBProcInfo { public int Pid; public string Name; public long CpuTime; public long WorkingSet; }
public static class GBProcSnap {
    [DllImport("ntdll.dll")] static extern int NtQuerySystemInformation(int cls, IntPtr buf, int len, out int retLen);
    static int _valid = -1;   // -1 = pas encore verifie, 0 = invalide (repli), 1 = ok
    public static bool Valid { get { if (_valid < 0) Verify(); return _valid == 1; } }

    static GBProcInfo[] Raw() {
        int len = 512 * 1024;
        for (int tries = 0; tries < 6; tries++) {
            IntPtr buf = Marshal.AllocHGlobal(len);
            try {
                int ret;
                int st = NtQuerySystemInformation(5, buf, len, out ret);
                if (st == unchecked((int)0xC0000004)) { len = Math.Max(len * 2, ret + 65536); continue; }   // tampon trop petit
                if (st != 0) return null;
                bool x64 = IntPtr.Size == 8;
                int oNameLen = 56, oNameBuf = x64 ? 64 : 60, oPid = x64 ? 80 : 68, oWs = x64 ? 144 : 104;
                List<GBProcInfo> list = new List<GBProcInfo>(512);
                long off = 0;
                for (int n = 0; n < 100000; n++) {
                    IntPtr p = new IntPtr(buf.ToInt64() + off);
                    int next = Marshal.ReadInt32(p, 0);
                    GBProcInfo pi = new GBProcInfo();
                    pi.Pid = (int)Marshal.ReadIntPtr(p, oPid).ToInt64();
                    long user = Marshal.ReadInt64(p, 40), kern = Marshal.ReadInt64(p, 48);
                    pi.CpuTime = user + kern;
                    pi.WorkingSet = Marshal.ReadIntPtr(p, oWs).ToInt64();
                    int nl = Marshal.ReadInt16(p, oNameLen) & 0xFFFF;
                    IntPtr nb = Marshal.ReadIntPtr(p, oNameBuf);
                    string name = (nl > 0 && nl < 1024 && nb != IntPtr.Zero) ? Marshal.PtrToStringUni(nb, nl / 2) : (pi.Pid == 0 ? "Idle" : "");
                    if (name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)) name = name.Substring(0, name.Length - 4);
                    pi.Name = name;
                    list.Add(pi);
                    if (next <= 0) break;
                    off += next;
                    if (off >= len) return null;
                }
                return list.ToArray();
            } catch { return null; }
            finally { Marshal.FreeHGlobal(buf); }
        }
        return null;
    }

    // Verification au premier usage : les PID et noms doivent correspondre a ceux de .NET (sinon repli sur l'ancienne methode)
    static void Verify() {
        try {
            GBProcInfo[] a = Raw();
            if (a == null || a.Length < 5) { _valid = 0; return; }
            Dictionary<int, string> net = new Dictionary<int, string>();
            foreach (Process p in Process.GetProcesses()) { try { net[p.Id] = p.ProcessName; } catch { } finally { p.Dispose(); } }
            int match = 0, named = 0;
            foreach (GBProcInfo pi in a) {
                string n;
                if (pi.Pid > 4 && net.TryGetValue(pi.Pid, out n)) { named++; if (string.Equals(n, pi.Name, StringComparison.OrdinalIgnoreCase)) match++; }
            }
            _valid = (named >= 5 && match * 10 >= named * 8 && named * 10 >= (net.Count - 2) * 6) ? 1 : 0;
        } catch { _valid = 0; }
    }

    public static GBProcInfo[] Take() { if (!Valid) return null; return Raw(); }
}

// Ping en arriere-plan : l'interface lit la derniere valeur sans jamais attendre le reseau
public static class GBPinger {
    static volatile int _last = -1;
    static volatile bool _busy, _tcp, _switched;
    public static string Host = "1.1.1.1";
    public static int Last { get { return _last; } }          // -1 = pas de reponse / pas encore mesure
    public static bool TcpMode { get { return _tcp; } }
    public static bool TakeSwitchNotice() { if (_switched) { _switched = false; return true; } return false; }
    public static void Kick() {
        if (_busy) return;
        _busy = true;
        ThreadPool.QueueUserWorkItem(delegate {
            try { _last = Measure(); } catch { _last = -1; } finally { _busy = false; }
        });
    }
    static int Measure() {
        if (!_tcp) {
            try {
                using (Ping p = new Ping()) {
                    PingReply r = p.Send(Host, 700);
                    if (r != null && r.Status == IPStatus.Success) return (int)r.RoundtripTime;
                }
            } catch { }
            int t = Tcp();
            if (t >= 0) { _tcp = true; _switched = true; }
            return t;
        }
        return Tcp();
    }
    static int Tcp() {
        using (Socket s = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp)) {
            Stopwatch sw = Stopwatch.StartNew();
            IAsyncResult ar = s.BeginConnect(IPAddress.Parse(Host), 443, null, null);
            if (ar.AsyncWaitHandle.WaitOne(700) && s.Connected) { try { s.EndConnect(ar); } catch { return -1; } return (int)sw.ElapsedMilliseconds; }
            return -1;
        }
    }
}

// Lecture incrementale du fichier PresentMon (temps d'image de la fenetre de rendu principale)
public class GBFpsReader {
    long _pos; string _pending = ""; int _ft = -1, _sc = -1; bool _cols;
    public double[] ReadNew(string path) {
        string chunk;
        try {
            using (System.IO.FileStream fs = new System.IO.FileStream(path, System.IO.FileMode.Open, System.IO.FileAccess.Read, System.IO.FileShare.ReadWrite | System.IO.FileShare.Delete)) {
                if (fs.Length < _pos) _pos = 0;
                fs.Seek(_pos, System.IO.SeekOrigin.Begin);
                using (System.IO.StreamReader sr = new System.IO.StreamReader(fs, System.Text.Encoding.ASCII, false)) { chunk = sr.ReadToEnd(); }
                _pos += System.Text.Encoding.ASCII.GetByteCount(chunk);
            }
        } catch { return new double[0]; }
        string text = _pending + chunk;
        int lastNl = text.LastIndexOf('\n');
        if (lastNl < 0) { _pending = text; return new double[0]; }
        _pending = text.Substring(lastNl + 1);
        List<double> fts = new List<double>(4096); List<string> scs = new List<string>(4096);
        Dictionary<string, int> counts = new Dictionary<string, int>();
        System.Globalization.CultureInfo inv = System.Globalization.CultureInfo.InvariantCulture;
        foreach (string line in text.Substring(0, lastNl).Split('\n')) {
            string l = line.TrimEnd('\r');
            if (l.Length == 0) continue;
            if (l.StartsWith("Application,")) {
                string[] h = l.Split(',');
                _ft = System.Array.IndexOf(h, "msBetweenPresents"); if (_ft < 0) _ft = System.Array.IndexOf(h, "FrameTime");
                _sc = System.Array.IndexOf(h, "SwapChainAddress"); _cols = true;
                continue;
            }
            if (!_cols || _ft < 0) continue;
            string[] f = l.Split(',');
            if (f.Length <= _ft) continue;
            double v;
            if (!double.TryParse(f[_ft], System.Globalization.NumberStyles.Float, inv, out v)) continue;
            if (v <= 0 || v > 5000) continue;
            string sc = (_sc >= 0 && f.Length > _sc) ? f[_sc] : "";
            fts.Add(v); scs.Add(sc);
            int c; counts.TryGetValue(sc, out c); counts[sc] = c + 1;
        }
        if (fts.Count == 0) return new double[0];
        string main = ""; int best = -1;
        foreach (KeyValuePair<string, int> kv in counts) if (kv.Value > best) { best = kv.Value; main = kv.Key; }
        List<double> res = new List<double>(fts.Count);
        for (int i = 0; i < fts.Count; i++) if (scs[i] == main) res.Add(fts[i]);
        return res.ToArray();
    }
}
