# Auto-controle des compteurs au demarrage : nombre de processus et de coeurs coherents, sinon retour a WMI
$Script:PerfChecked = $false; $Script:PerfChecks = 0
function Test-PerfSanity {
    $ok = $true; $checked = $false
    if ($Script:Perf.Has('procs')) {
        $v = Get-PerfValue 'procs'
        if ($null -ne $v) {
            $checked = $true
            $n = 0; foreach ($p in [System.Diagnostics.Process]::GetProcesses()) { $n++; $p.Dispose() }
            if ($v -lt 0.6 * $n -or $v -gt 1.4 * $n + 10) { $ok = $false }
        }
    }
    $arr = $Script:Perf.Array('cores')
    if ($arr -and $arr.Count -gt 0) {
        $checked = $true; $nc = 0
        foreach ($kv in $arr) {
            if ($kv.Key -ne '_Total') { $nc++ }
            if ([double]::IsNaN($kv.Value) -or $kv.Value -lt -0.5 -or $kv.Value -gt 100.5) { $ok = $false }
        }
        if ($nc -lt 1 -or $nc -gt 4 * [Environment]::ProcessorCount) { $ok = $false }
    }
    if (-not $checked) { return $null }
    return $ok
}
# --- Ecrans zoomes (125 %, 150 %, 200 %...) : texte net et fenetres a la bonne taille ----------
$Script:DpiScale = 1.0
if ($Script:NativeOK) { try { [void][GBNative]::MakeDpiAware() } catch {} }
try { $gx = [System.Drawing.Graphics]::FromHwnd([IntPtr]::Zero); $Script:DpiScale = [double]$gx.DpiX / 96.0; $gx.Dispose() } catch {}
if ($Script:DpiScale -lt 1.0 -or $Script:DpiScale -gt 4.0) { $Script:DpiScale = 1.0 }
function Register-GBDpi($f) {
    # La mise a l'echelle automatique de WinForms ne s'applique pas aux controles ajoutes apres coup : on la fait nous-memes
    $f.AutoScaleMode = [System.Windows.Forms.AutoScaleMode]::None
    $f.Add_Load({
        if ([math]::Abs($Script:DpiScale - 1.0) -ge 0.01) { try { Invoke-GBDpiScale $this } catch {} }
        try { Set-GBFitToScreen $this } catch {}
    })
}
# Zone utile de l'ecran ou s'ouvre la fenetre (sans la barre des taches)
function Get-GBWorkArea($f) {
    $ref = $f; if ($f.Owner) { $ref = $f.Owner }
    try { if ($ref.IsHandleCreated) { return [System.Windows.Forms.Screen]::FromControl($ref).WorkingArea } } catch {}
    return [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea
}
# Petits ecrans (portable 1366x768, zoom 150 %...) : la fenetre ne depasse jamais, elle defile si besoin
function Set-GBFitToScreen($f) {
    $wa = Get-GBWorkArea $f
    $w = $f.Width; $h = $f.Height
    if ($h -le $wa.Height -and $w -le $wa.Width) { return }
    if (-not $f.MinimumSize.IsEmpty) {
        $f.MinimumSize = New-Object System.Drawing.Size([math]::Min($f.MinimumSize.Width, $wa.Width), [math]::Min($f.MinimumSize.Height, $wa.Height))
    }
    if ([string]$f.FormBorderStyle -ne 'Sizable') { $f.AutoScroll = $true }
    if ($h -gt $wa.Height) { $h = $wa.Height; if ($f.AutoScroll) { $w += [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth } }
    if ($w -gt $wa.Width) { $w = $wa.Width }
    $f.StartPosition = 'Manual'
    $f.Size = New-Object System.Drawing.Size($w, $h)
    $f.Location = New-Object System.Drawing.Point(($wa.X + [int](($wa.Width - $w) / 2)), ($wa.Y + [int](($wa.Height - $h) / 2)))
}
# Defilement et mises a jour sans scintillement (listes, panneaux de lignes)
$Script:DblBufProp = [System.Windows.Forms.Control].GetProperty('DoubleBuffered', [System.Reflection.BindingFlags]'NonPublic, Instance')
function Set-GBDoubleBuffered($ctl) { try { $Script:DblBufProp.SetValue($ctl, $true, $null) } catch {} }
function Invoke-GBDpiScale($f) {
    $k = [single]$Script:DpiScale
    $min = $f.MinimumSize
    if (-not $min.IsEmpty) { $f.MinimumSize = [System.Drawing.Size]::Empty }
    $f.Scale((New-Object System.Drawing.SizeF($k, $k)))
    if (-not $min.IsEmpty) { $f.MinimumSize = New-Object System.Drawing.Size([int]($min.Width * $k), [int]($min.Height * $k)) }
    $stack = New-Object System.Collections.Stack; $stack.Push($f)
    while ($stack.Count -gt 0) {
        $c = $stack.Pop()
        if ($c -is [System.Windows.Forms.ListView]) { foreach ($col in $c.Columns) { $col.Width = [int]($col.Width * $k) } }
        foreach ($ch in $c.Controls) { $stack.Push($ch) }
    }
}

function Update-Perf([switch]$Force) {
    if (-not $Script:Perf) { return $false }
    $now = [Environment]::TickCount
    if ($Force -or [math]::Abs($now - $Script:PerfLast) -ge 700) {
        if ($Script:Perf.Collect()) {
            $Script:PerfLast = $now
            if (-not $Script:PerfChecked) {
                $Script:PerfChecks++
                $r = $null; try { $r = Test-PerfSanity } catch { $r = $false }
                if ($r -eq $true) { $Script:PerfChecked = $true }
                elseif ($r -eq $false -or $Script:PerfChecks -ge 3) {
                    try { $Script:Perf.Dispose() } catch {}
                    $Script:Perf = $null
                    try { Log "Compteurs Windows incoherents sur ce PC : mesures par WMI (plus lent mais fiable)" } catch {}
                    return $false
                }
            }
        }
    }
    return [bool]$Script:Perf
}
function Test-Perf($key) { return [bool]($Script:Perf -and $Script:Perf.Has($key)) }
function Get-PerfValue($key) {
    if (-not $Script:Perf) { return $null }
    $v = $Script:Perf.Value($key)
    if ([double]::IsNaN($v)) { return $null }
    return $v
}

