function Load-Config {
    $cfg = [ordered]@{
        Games          = @()
        Whitelist      = $DefaultWhitelist
        AutoMode       = $false
        ConfigVersion  = 0
        CloseApps      = $true
        ForceClose     = $false
        PauseServices  = $true
        PowerPlan      = $true
        GamePriority   = $true
        CleanRam       = $true
        ReopenApps     = $true
        KnownGames     = $true
        NetworkTweak   = $false
        GpuPriority    = $false
        MouseAccelOff  = $false
        RestorePoint   = $true
        FpsMeasure     = $true
        MeasureOnly    = $false
        GameDvrOff     = $false
        LowerBackground = $true
        StandbyClean   = $true
        PlanTuning     = $true
        GpuPreference  = $false
        GpuPrefAdded   = @()
        CloseList      = $BackgroundHogs
        ServicesSelected = @($ServicesToPause | ForEach-Object { $_.Name })
        PowerOverlayBoost = 2
        CpuCustom      = $false
        CpuMinBoost    = 100
        CpuMaxBoost    = 100
        GamePrioLevel  = 4
        LowerList      = $LowerPrioTargets
        LowerLevel     = 1
        StandbyMinMo   = 1024
        FreeMaxMo      = 1024
        PurgeInterval  = 180
        StandbyAlways  = $false
        AppPriorities  = @{}
        LastRestorePoint = ""
        PerfScheme     = $null
        WinLevel       = -1      # dernier niveau choisi avec le curseur de Config Windows (-1 = jamais)
        UltimateName   = ""      # nom du plan "Performances optimales" (traduit par Windows) une fois ajoute
        GameProfiles   = @{}     # niveau gaming propre a un jeu : nom du jeu -> index du niveau (0 = Leger ... 4 = Extreme)
        Overlay        = $false  # petit affichage FPS / CPU / GPU / ping par-dessus le jeu pendant le boost
        OverlayCorner  = 0       # 0 haut gauche, 1 haut droite, 2 bas gauche, 3 bas droite
        TurboOnlyInGame = $false # turbo du processeur coupe hors boost (PC plus frais)
        TurboOrig      = $null   # plan et valeurs d'origine (mode de boost, frequence max) pendant que GameBoost les change
        TurboOnMhz     = 0       # GHz maximum en mode TURBO ON et en jeu (0 = sans limite)
        TurboOffMhz    = 0       # GHz maximum en mode TURBO OFF (0 = frequence de base, turbo coupe)
        CpuMaxMhz      = 0       # turbo maximum mesure du processeur (analyse de l'engrenage TURBO)
        CpuMaxName     = ""      # processeur mesure (nouvelle mesure si le processeur change)
        GpuEco         = $false  # bouton GPU : ECO = frequence de la carte graphique limitee hors jeu
        GpuOnMhz       = 0       # frequence max de la carte en mode GPU ON et en jeu (0 = sans limite)
        GpuEcoMhz      = 0       # frequence max en mode GPU ECO (0 = valeur conseillee)
        GpuPowerMax    = $false  # limite de puissance NVIDIA au maximum pendant le boost (OC autorise)
        GpuLocked      = $false  # frequence verrouillee par GameBoost (a remettre, meme apres un arret brutal)
        GpuPlSet       = $false  # limite de puissance changee par GameBoost
        GpuPlDefault   = 0       # limite de puissance d'origine (W)
        GpuNoLock      = ""      # carte qui refuse le verrouillage de frequence
        FpsCap         = 0       # limite de FPS choisie (pilote NVIDIA, toutes les applis ; 0 = aucune)
        FpsCapOrig     = -1      # limite d'origine du pilote avant GameBoost (-1 = jamais changee), pour "Tout restaurer"
        CloseToTray    = $true   # la croix range GameBoost pres de l'horloge (Quitter : menu GameBoost ou clic droit sur l'icone)
        CloseToTrayTip = $false  # bulle d'explication deja montree une fois
        Hotkeys        = @{}     # raccourcis choisis : id d'action -> touches ('Ctrl+Alt+F9'), '' = aucun, absent = touche par defaut
        LinkedApps     = @()     # lancements lies : quand A demarre, GameBoost lance B (Show-LinkedAppsPanel)
        MonitorsOff    = @()     # ecrans eteints par GameBoost (rallumes a la fermeture et apres un arret brutal)
        MonitorPrefs   = @{}     # methode choisie pour chaque ecran : ddc, detach ou veil (absent = auto)
        SensorPrefs    = @{ Unit = 'C'; Alerts = $true; CpuSource = 'auto'; NvmlAlways = $false; Cpu = @(); Gpu = @(); Ssd = @() }   # capteurs : unite C/F, alertes, source du processeur, seuils perso (vide = automatique)
        Edition        = ""      # modele : 'Nexus', 'Arena' ou 'Pure' ('' = jamais choisi : fenetre de choix au lancement)
        EditionChosen  = $false  # modele choisi par l'utilisateur (sinon NEXUS par defaut, fenetre fermee sans choix)
    }
    if (Test-Path -LiteralPath $ConfigFile) {
        try {
            $j = Get-Content -LiteralPath $ConfigFile -Raw | ConvertFrom-Json
            foreach ($k in @($cfg.Keys)) { if ($null -ne $j.$k) { $cfg[$k] = $j.$k } }
        } catch {}
    }
    # 2.4 : le boost ne se lance plus tout seul (demande : lancement manuel uniquement)
    $Script:ConfigMigrated = $false
    if ([int]$cfg.ConfigVersion -lt 24) { $cfg.AutoMode = $false; $cfg.ConfigVersion = 24; $Script:ConfigMigrated = $true }
    $cfg.Games     = @($cfg.Games)
    $cfg.Whitelist = @($cfg.Whitelist)
    $cfg.GpuPrefAdded = @($cfg.GpuPrefAdded | Where-Object { $_ })
    $cfg.CloseList = @($cfg.CloseList | Where-Object { $_ })
    $cfg.ServicesSelected = @($cfg.ServicesSelected | Where-Object { $_ })
    $cfg.LowerList = @($cfg.LowerList | Where-Object { $_ })
    # Priorites retenues par appli : objet JSON -> table
    $ap = @{}
    if ($cfg.AppPriorities -is [hashtable]) { $ap = $cfg.AppPriorities }
    elseif ($cfg.AppPriorities) { foreach ($pp in $cfg.AppPriorities.PSObject.Properties) { $ap[$pp.Name] = [int]$pp.Value } }
    $cfg.AppPriorities = $ap
    $gp = @{}
    if ($cfg.GameProfiles -is [hashtable]) { $gp = $cfg.GameProfiles }
    elseif ($cfg.GameProfiles) { foreach ($pp in $cfg.GameProfiles.PSObject.Properties) { $gp[$pp.Name] = [int]$pp.Value } }
    $cfg.GameProfiles = $gp
    # Raccourcis clavier choisis : objet JSON -> table
    $hk = @{}
    if ($cfg.Hotkeys -is [hashtable]) { $hk = $cfg.Hotkeys }
    elseif ($cfg.Hotkeys) { foreach ($pp in $cfg.Hotkeys.PSObject.Properties) { $hk[$pp.Name] = [string]$pp.Value } }
    $cfg.Hotkeys = $hk
    # Lancements lies : objets JSON -> tables (Id, Name, Source, Target, Args, Delay, CloseWith, CloseForce, Both, Enabled, AsAdmin)
    $la = @()
    foreach ($o in @($cfg.LinkedApps)) {
        if (-not $o) { continue }
        $h = @{}
        if ($o -is [hashtable]) { foreach ($k in @($o.Keys)) { $h[$k] = $o[$k] } } else { foreach ($pp in $o.PSObject.Properties) { $h[$pp.Name] = $pp.Value } }
        if (-not $h.Source -or -not $h.Target) { continue }
        $la += @{ Id = $(if ($h.Id) { [string]$h.Id } else { [guid]::NewGuid().ToString('N').Substring(0, 8) }); Name = [string]$h.Name
                  Source = [string]$h.Source; Target = [string]$h.Target; Args = [string]$h.Args; Delay = [math]::Max(0, [math]::Min(600, [int]$h.Delay))
                  CloseWith = [bool]$h.CloseWith; CloseForce = [bool]$h.CloseForce; Both = [bool]$h.Both; Enabled = ($null -eq $h.Enabled -or [bool]$h.Enabled); AsAdmin = [bool]$h.AsAdmin }
    }
    $cfg.LinkedApps = $la
    # Ecrans : methode par ecran (objet JSON -> table), ecrans laisses eteints (liste)
    $mp = @{}
    if ($cfg.MonitorPrefs -is [hashtable]) { $mp = $cfg.MonitorPrefs }
    elseif ($cfg.MonitorPrefs) { foreach ($pp in $cfg.MonitorPrefs.PSObject.Properties) { $mp[$pp.Name] = [string]$pp.Value } }
    $cfg.MonitorPrefs = $mp
    $cfg.MonitorsOff = @($cfg.MonitorsOff | Where-Object { $_ })
    # Capteurs : objet JSON -> table ; seuils = 3 entiers [chaud, tres chaud, critique] ou vide
    $sp = @{ Unit = 'C'; Alerts = $true; CpuSource = 'auto'; NvmlAlways = $false; Cpu = @(); Gpu = @(); Ssd = @() }
    if ($cfg.SensorPrefs -is [hashtable]) { foreach ($k in @($cfg.SensorPrefs.Keys)) { $sp[$k] = $cfg.SensorPrefs[$k] } }
    elseif ($cfg.SensorPrefs) { foreach ($pp in $cfg.SensorPrefs.PSObject.Properties) { $sp[$pp.Name] = $pp.Value } }
    foreach ($k in 'Cpu', 'Gpu', 'Ssd') { $sp[$k] = @(@($sp[$k]) | Where-Object { $null -ne $_ } | ForEach-Object { [int]$_ }) }
    if (@('C', 'F') -notcontains [string]$sp.Unit) { $sp.Unit = 'C' }
    $sp.Alerts = [bool]$sp.Alerts; $sp.NvmlAlways = [bool]$sp.NvmlAlways; $sp.CpuSource = [string]$sp.CpuSource; if (-not $sp.CpuSource) { $sp.CpuSource = 'auto' }
    $cfg.SensorPrefs = $sp
    return $cfg
}
function Save-Config {
    # Pendant une session "mesure seule", on sauvegarde les vrais reglages, pas la copie desactivee
    $cfg = $Script:Config
    if ($Script:RealConfig) { $cfg = $Script:RealConfig }
    $cfg | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $ConfigFile -Encoding UTF8
}
$Script:RealConfig = $null
$Script:MeasureOnlySession = $false

# Modeles de GameBoost : meme moteur, trois interfaces (NEXUS complet, ARENA gaming, PURE simple)
$Script:Editions = @('Nexus', 'Arena', 'Pure')
function Resolve-GBEdition($v) {
    $t = ([string]$v).Trim()
    foreach ($e in $Script:Editions) { if ($e -ieq $t) { return $e } }
    return ''
}
function Get-GBEditionLabel($v) { $e = Resolve-GBEdition $v; if (-not $e) { $e = 'Nexus' }; return $e.ToUpperInvariant() }
$Script:EditionArg  = Resolve-GBEdition $Edition    # argument -Edition du script (exe : /edition:arena)
