# --- Interface ---------------------------------------------------------------
# Palettes des trois modeles. Les variables $c* gardent leur sens dans toutes les fenetres :
#   $cCyan = accent principal, $cGreen = ok / actif, $cRed = danger / arret, $cYellow = attention, $cViolet = Config Windows,
#   $cDeep = champs de saisie et listes, $cRail = colonne de navigation, $cSel = ligne choisie.
# NEXUS : neo-futuriste (cyberpunk), fond nuit, neon cyan / magenta / jaune (palette d'origine, inchangee)
# ARENA : gaming, noir profond legerement teinte, cartes plus claires, rose vif + orange
# PURE  : clair facon Apple, fond F5F5F7, cartes blanches, couleurs systeme foncees (lisibles sur blanc)
function Get-GBPalette([string]$Name) {
    $C = [System.Drawing.Color]
    switch (Resolve-GBEdition $Name) {
        'Arena' {
            $p = @{ Bg = $C::FromArgb(13, 11, 18); Panel = $C::FromArgb(30, 26, 40); Deep = $C::FromArgb(9, 8, 13); Line = $C::FromArgb(54, 47, 68)
                    Text = $C::FromArgb(244, 241, 248); Muted = $C::FromArgb(152, 145, 168); Term = $C::FromArgb(236, 178, 196)
                    Cyan = $C::FromArgb(255, 51, 119); Green = $C::FromArgb(48, 230, 140); Red = $C::FromArgb(255, 69, 58); Yellow = $C::FromArgb(255, 204, 0)
                    Violet = $C::FromArgb(157, 108, 255); Rail = $C::FromArgb(18, 15, 25); Sel = $C::FromArgb(52, 30, 48)
                    Accent2 = $C::FromArgb(255, 140, 26); OnAccent = $C::FromArgb(255, 255, 255)
                    PanelHi = $C::FromArgb(44, 38, 58); Track = $C::FromArgb(48, 42, 62); Disabled = $C::FromArgb(82, 76, 96) }
            $p.MeterOk = $p.Green
        }
        'Pure' {
            $p = @{ Bg = $C::FromArgb(245, 245, 247); Panel = $C::FromArgb(255, 255, 255); Deep = $C::FromArgb(242, 242, 247); Line = $C::FromArgb(210, 210, 215)
                    Text = $C::FromArgb(29, 29, 31); Muted = $C::FromArgb(110, 110, 115); Term = $C::FromArgb(58, 58, 60)
                    Cyan = $C::FromArgb(0, 113, 227); Green = $C::FromArgb(30, 126, 52); Red = $C::FromArgb(215, 0, 21); Yellow = $C::FromArgb(201, 52, 0)
                    Violet = $C::FromArgb(137, 68, 171); Rail = $C::FromArgb(236, 236, 241); Sel = $C::FromArgb(220, 234, 252)
                    Accent2 = $C::FromArgb(88, 86, 214); OnAccent = $C::FromArgb(255, 255, 255)
                    PanelHi = $C::FromArgb(229, 229, 234); Track = $C::FromArgb(222, 222, 227); Disabled = $C::FromArgb(190, 190, 196) }
            $p.MeterOk = $p.Cyan
        }
        default {
            $p = @{ Bg = $C::FromArgb(7, 8, 15); Panel = $C::FromArgb(14, 16, 28); Deep = $C::FromArgb(4, 5, 10); Line = $C::FromArgb(40, 48, 78)
                    Text = $C::FromArgb(226, 240, 255); Muted = $C::FromArgb(118, 132, 162); Term = $C::FromArgb(92, 196, 210)
                    Cyan = $C::FromArgb(0, 240, 255); Green = $C::FromArgb(5, 255, 161); Red = $C::FromArgb(255, 42, 109); Yellow = $C::FromArgb(252, 238, 10)
                    Violet = $C::FromArgb(150, 110, 255); Rail = $C::FromArgb(11, 13, 24); Sel = $C::FromArgb(26, 32, 56)
                    Accent2 = $C::FromArgb(255, 42, 109); OnAccent = $C::FromArgb(10, 10, 18)
                    PanelHi = $C::FromArgb(22, 26, 44); Track = $C::FromArgb(26, 30, 50); Disabled = $C::FromArgb(60, 66, 90) }
            $p.MeterOk = $p.Cyan
        }
    }
    $p.Accent = $p.Cyan; $p.Card = $p.Panel; $p.Magenta = $p.Red
    return $p
}
# Forme, lueur et mouvement de chaque modele
function Get-GBThemeSpec([string]$Name) {
    switch (Resolve-GBEdition $Name) {
        'Arena' { return @{ Name = 'Arena'; IsDark = $true;  Shape = 'Round';   Radius = 10; Glow = $true;  Motion = 'punch' } }
        'Pure'  { return @{ Name = 'Pure';  IsDark = $false; Shape = 'Round';   Radius = 12; Glow = $false; Motion = 'soft' } }
        default { return @{ Name = 'Nexus'; IsDark = $true;  Shape = 'Chamfer'; Radius = 8;  Glow = $true;  Motion = 'neon' } }
    }
}
# Police : la premiere disponible (Bahnschrift existe depuis Windows 10 1709, sinon Segoe UI)
# (Windows coupe les noms longs a 31 caracteres : "Segoe UI Variable Display Semib" = "...Semibold")
function Get-GBFont($names, $size, $style = [System.Drawing.FontStyle]::Regular) {
    foreach ($n in $names) {
        try {
            $f = New-Object System.Drawing.Font($n, [single]$size, $style)
            if ($f.Name -eq $n -or ($f.Name.Length -ge 31 -and $n.StartsWith($f.Name))) { return $f }
            $f.Dispose()
        } catch {}
    }
    return (New-Object System.Drawing.Font("Microsoft Sans Serif", [single]$size, $style))
}

# Fenetre "Choisis ton GameBoost" : 3 cartes avec l'apercu des couleurs de chaque modele (renvoie 'Nexus', 'Arena', 'Pure' ou $null)
function Show-GBEditionPicker($Owner = $null) {
    $C = [System.Drawing.Color]
    $bg = $C::FromArgb(16, 16, 20); $fg = $C::FromArgb(236, 236, 240); $mu = $C::FromArgb(150, 150, 162)
    $Bold = [System.Drawing.FontStyle]::Bold
    $items = @(
        @{ Name = 'Nexus'; Tag = 'Complet'; Desc = "Tous les reglages, les temperatures, tout le kit. Look cyberpunk neon."; Font = (Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 19) },
        @{ Name = 'Arena'; Tag = 'Gaming'; Desc = "Tout pour jouer, au premier plan. Look gaming, rose et orange."; Font = (Get-GBFont @("Bahnschrift", "Segoe UI Black") 19 $Bold) },
        @{ Name = 'Pure'; Tag = 'Simple'; Desc = "L'essentiel, rien de plus. Epure et clair, facon Apple."; Font = (Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 19) }
    )
    $d = New-Object System.Windows.Forms.Form
    Register-GBDpi $d
    $d.Text = "GameBoost"; $d.FormBorderStyle = "FixedDialog"; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.BackColor = $bg; $d.ForeColor = $fg; $d.KeyPreview = $true
    $d.ClientSize = New-Object System.Drawing.Size(848, 476)
    if ($Owner) { $d.StartPosition = "CenterParent"; $d.ShowInTaskbar = $false } else { $d.StartPosition = "CenterScreen" }
    $d.Font = Get-GBFont @("Segoe UI") 9.5
    $t = New-Object System.Windows.Forms.Label; $t.Text = "Choisis ton GameBoost"; $t.Font = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 18
    $t.ForeColor = $fg; $t.Location = New-Object System.Drawing.Point(30, 22); $t.Size = New-Object System.Drawing.Size(700, 38); $d.Controls.Add($t)
    $st = New-Object System.Windows.Forms.Label; $st.ForeColor = $mu; $st.Location = New-Object System.Drawing.Point(32, 62); $st.Size = New-Object System.Drawing.Size(780, 22); $d.Controls.Add($st)
    $st.Text = "Meme moteur, trois styles. Tu pourras changer plus tard (menu Affichage > Modele)."
    $d.Tag = $null
    $x = 30
    foreach ($it in $items) {
        $p = Get-GBPalette $it.Name; $sp = Get-GBThemeSpec $it.Name
        if ($Script:UiOK) {
            $c = New-Object GBEditionCard
            $c.Title = $it.Name.ToUpperInvariant(); $c.Tagline = $it.Tag; $c.Desc = $it.Desc
            $c.TitleFont = $it.Font; $c.TagFont = Get-GBFont @("Segoe UI Semibold") 10; $c.DescFont = Get-GBFont @("Segoe UI") 9.25
            $c.CBg = $p.Bg; $c.CPanel = $p.Card; $c.CLine = $p.Line; $c.CText = $p.Text; $c.CMuted = $p.Muted
            $c.CAccent = $p.Accent; $c.CAccent2 = $p.Accent2; $c.COnAccent = $p.OnAccent
            $c.CShape = @{ Chamfer = 0; Round = 1; Pill = 2 }[$sp.Shape]; $c.CRadius = [int]$sp.Radius; $c.CGlow = [bool]$sp.Glow
            $c.Current = [bool]($Owner -and $it.Name -eq $Script:Edition)
            $c.BackColor = $bg
        } else {
            $c = New-Object System.Windows.Forms.Button
            $c.FlatStyle = "Flat"; $c.FlatAppearance.BorderColor = $p.Line; $c.BackColor = $p.Bg; $c.ForeColor = $p.Text
            $c.TextAlign = "TopLeft"; $c.Padding = New-Object System.Windows.Forms.Padding(14)
            $c.Text = $it.Name.ToUpperInvariant() + "`r`n" + $it.Tag + "`r`n`r`n" + $it.Desc
            $c.Font = Get-GBFont @("Segoe UI Semibold") 11
        }
        $c.Tag = $it.Name; $c.Cursor = [System.Windows.Forms.Cursors]::Hand
        $c.Location = New-Object System.Drawing.Point($x, 100); $c.Size = New-Object System.Drawing.Size(252, 344)
        $c.Add_Click({ $f = $this.FindForm(); $f.Tag = [string]$this.Tag; $f.Close() })
        $d.Controls.Add($c)
        $x += 266
    }
    $d.Add_KeyDown({ param($sender, $e) if ($e.KeyCode -eq 'Escape') { $sender.Close() } })
    $d.Add_HandleCreated({ if ($Script:UiOK) { try { [GBTheme]::Chrome($this.Handle, $true, $this.BackColor, [System.Drawing.Color]::FromArgb(60, 60, 72), [System.Drawing.Color]::FromArgb(236, 236, 240)) } catch {} } })
    # 1re fenetre du processus : Windows peut la garder cachee (lanceur sans fenetre) -> on la ramene devant
    $d.Add_Shown({ if ($Script:UiOK) { try { [void][GBTheme]::ShowFront($this) } catch {} }; $this.Activate() })
    if ($Script:PickerTestHook) { try { & $Script:PickerTestHook $d } catch {} }
    if ($Owner) { [void]$d.ShowDialog($Owner) } else { [void]$d.ShowDialog() }
    $r = Resolve-GBEdition $d.Tag
    $d.Dispose()
    if ($r) { return $r }
    return $null
}

# Premier lancement (modele jamais choisi) : la fenetre de choix s'ouvre AVANT la fenetre principale.
# Fermee sans choix : NEXUS. Lancement reduit au demarrage de Windows : NEXUS pour cette fois, la question reste posee.
if (-not $Script:Edition) {
    $pick = $null
    if (-not $Minimized) { try { $pick = Show-GBEditionPicker } catch {} }
    if ($pick) { $Script:Edition = $pick; $Script:Config.EditionChosen = $true } else { $Script:Edition = 'Nexus' }
    if (-not $Minimized) { $Script:Config.Edition = $Script:Edition; try { Save-Config } catch {} }
} elseif ($Script:EditionArg -and -not (Resolve-GBEdition $Script:Config.Edition)) {
    $Script:Config.Edition = $Script:EditionArg; $Script:Config.EditionChosen = $true; try { Save-Config } catch {}
}

# Theme du modele : couleurs $c*, polices $font*, $Script:Theme, puis les composants dessines (GBTheme)
function Initialize-GBTheme([string]$Name) {
    $n = Resolve-GBEdition $Name; if (-not $n) { $n = 'Nexus' }
    $p = Get-GBPalette $n
    $Script:Palette = $p
    $Script:cBg = $p.Bg; $Script:cPanel = $p.Panel; $Script:cDeep = $p.Deep; $Script:cLine = $p.Line
    $Script:cText = $p.Text; $Script:cMuted = $p.Muted; $Script:cTerm = $p.Term
    $Script:cCyan = $p.Cyan; $Script:cGreen = $p.Green; $Script:cRed = $p.Red; $Script:cYellow = $p.Yellow; $Script:cViolet = $p.Violet
    $Script:cRail = $p.Rail; $Script:cSel = $p.Sel
    $Script:cAccent = $p.Accent; $Script:cAccent2 = $p.Accent2; $Script:cOnAccent = $p.OnAccent; $Script:cCard = $p.Card
    $B = [System.Drawing.FontStyle]::Bold
    switch ($n) {
        'Arena' {
            # Gaming : Bahnschrift gras partout ou ca compte (titres, boutons, chiffres)
            $Script:fontUI    = Get-GBFont @("Segoe UI") 9.5
            $Script:fontBold  = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10
            $Script:fontHud   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10.5
            $Script:fontTitle = Get-GBFont @("Bahnschrift", "Segoe UI Black") 22 $B
            $Script:fontBoost = Get-GBFont @("Bahnschrift", "Segoe UI Black") 15 $B
            $Script:fontMono  = Get-GBFont @("Cascadia Mono", "Consolas") 9
            $Script:fontPage  = Get-GBFont @("Bahnschrift", "Segoe UI Semibold") 17 $B
            $Script:fontNav   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 11
            $Script:fontSmall = Get-GBFont @("Segoe UI") 8.75
            $Script:fontHero  = Get-GBFont @("Bahnschrift", "Segoe UI Black") 30 $B
            $Script:fontDisplay = Get-GBFont @("Bahnschrift", "Segoe UI Black") 22 $B
        }
        'Pure' {
            # Facon Apple : Segoe UI Variable (Display pour les titres, Text pour le reste), sinon Segoe UI
            $Script:fontUI    = Get-GBFont @("Segoe UI Variable Text", "Segoe UI") 9.5
            $Script:fontBold  = Get-GBFont @("Segoe UI Variable Text Semibold", "Segoe UI Semibold") 10
            $Script:fontHud   = Get-GBFont @("Segoe UI Variable Text Semibold", "Segoe UI Semibold") 10.5
            $Script:fontTitle = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 21
            $Script:fontBoost = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 14
            $Script:fontMono  = Get-GBFont @("Cascadia Mono", "Consolas") 9
            $Script:fontPage  = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 17
            $Script:fontNav   = Get-GBFont @("Segoe UI Variable Text", "Segoe UI") 10.5
            $Script:fontSmall = Get-GBFont @("Segoe UI Variable Small", "Segoe UI") 8.75
            $Script:fontHero  = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 30
            $Script:fontDisplay = Get-GBFont @("Segoe UI Variable Display Semibold", "Segoe UI Semibold") 22
        }
        default {
            $Script:fontUI    = Get-GBFont @("Segoe UI") 9.5
            $Script:fontBold  = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10
            $Script:fontHud   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10.5
            $Script:fontTitle = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 22
            $Script:fontBoost = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 15
            $Script:fontMono  = Get-GBFont @("Cascadia Mono", "Consolas") 9
            $Script:fontPage  = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 16    # titre de page / de fenetre
            $Script:fontNav   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 11
            $Script:fontSmall = Get-GBFont @("Segoe UI") 8.75
            $Script:fontHero  = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 28    # tres gros chiffres
            $Script:fontDisplay = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 20  # titres d'ecran
        }
    }
    $t = Get-GBThemeSpec $n
    $t.FontTitle = $Script:fontTitle.Name; $t.FontUI = $Script:fontUI.Name
    $Script:Theme = $t
    Set-GBUiTheme
}
# Composants dessines (C#) : memes couleurs, forme, lueur et mouvement que le modele (avant la creation des controles)
function Set-GBUiTheme {
    if (-not $Script:UiOK) { return }
    try {
        $p = $Script:Palette; $t = $Script:Theme
        [GBTheme]::Bg = $p.Bg; [GBTheme]::Panel = $p.Panel; [GBTheme]::PanelHi = $p.PanelHi; [GBTheme]::Line = $p.Line
        [GBTheme]::Text = $p.Text; [GBTheme]::Muted = $p.Muted; [GBTheme]::Cyan = $p.Cyan; [GBTheme]::Magenta = $p.Magenta
        [GBTheme]::Yellow = $p.Yellow; [GBTheme]::Green = $p.Green; [GBTheme]::Violet = $p.Violet
        [GBTheme]::Deep = $p.Deep; [GBTheme]::Sel = $p.Sel; [GBTheme]::Track = $p.Track; [GBTheme]::Disabled = $p.Disabled
        [GBTheme]::Accent = $p.Accent; [GBTheme]::Accent2 = $p.Accent2; [GBTheme]::OnAccent = $p.OnAccent; [GBTheme]::Card = $p.Card; [GBTheme]::MeterOk = $p.MeterOk
        [GBTheme]::Edition = [int]([array]::IndexOf([string[]]$Script:Editions, [string]$t.Name))
        [GBTheme]::Shape = [int](@{ Chamfer = 0; Round = 1; Pill = 2 }[[string]$t.Shape])
        [GBTheme]::Radius = [int]$t.Radius; [GBTheme]::Glow = [bool]$t.Glow; [GBTheme]::IsDarkTheme = [bool]$t.IsDark
        [GBTheme]::Motion = [int](@{ neon = 0; punch = 1; soft = 2 }[[string]$t.Motion])
    } catch { $Script:ThemeError = $_.Exception.Message }
}
Initialize-GBTheme $Script:Edition

# --- Crochets communs (socle) : mesures, verification chaque minute, fermeture, demarrage -------------
# Une erreur dans un crochet est notee une fois dans le journal, jamais fatale.
$Script:SampleHooks  = New-Object System.Collections.ArrayList
$Script:CloseHooks   = New-Object System.Collections.ArrayList
$Script:StartHooks   = New-Object System.Collections.ArrayList
$Script:MinuteChecks = [ordered]@{}
$Script:HealthState  = @{}
$Script:HookErrors   = @{}
$Script:StartHooksDone = $false
function Invoke-GBHookSafe([string]$Key, [scriptblock]$Block, $Arg) {
    try { $null = & $Block $Arg; return $true }
    catch {
        $m = $_.Exception.Message
        if ($Script:HookErrors[$Key] -ne $m) { $Script:HookErrors[$Key] = $m; try { Log ("Erreur interne (" + $Key + ", GameBoost continue) : " + $m) } catch {} }
        return $false
    }
}
# Appele a la fin de chaque mesure (toutes les 5 s) avec l'objet mesure : { param($s) ... }
function Add-GBSampleHook([scriptblock]$Hook) { if ($Hook) { [void]$Script:SampleHooks.Add($Hook) } }
# Appele a la fermeture de GameBoost, avant la remise du turbo et de la carte graphique
function Add-GBCloseHook([scriptblock]$Hook) { if ($Hook) { [void]$Script:CloseHooks.Add($Hook) } }
# Appele une fois, 700 ms apres l'affichage de la fenetre (tout de suite si c'est deja passe)
function Add-GBStartHook([scriptblock]$Hook) {
    if (-not $Hook) { return }
    if ($Script:StartHooksDone) { [void](Invoke-GBHookSafe ('demarrage#' + $Script:StartHooks.Count) $Hook $null) }
    [void]$Script:StartHooks.Add($Hook)
}
# Verification toutes les 60 s : le bloc renvoie $null si tout va bien, sinon un texte court (probleme trouve, deja corrige si possible)
function Add-GBMinuteCheck([string]$Name, [scriptblock]$Check) { if ($Name -and $Check) { $Script:MinuteChecks[$Name] = $Check } }
function Invoke-GBSampleHooks($s) {
    for ($i = 0; $i -lt $Script:SampleHooks.Count; $i++) { [void](Invoke-GBHookSafe ('mesure#' + $i) $Script:SampleHooks[$i] $s) }
}
function Invoke-GBCloseHooks {
    for ($i = 0; $i -lt $Script:CloseHooks.Count; $i++) { [void](Invoke-GBHookSafe ('fermeture#' + $i) $Script:CloseHooks[$i] $null) }
}
function Invoke-GBStartHooks {
    if ($Script:StartHooksDone) { return }
    $Script:StartHooksDone = $true
    for ($i = 0; $i -lt $Script:StartHooks.Count; $i++) { [void](Invoke-GBHookSafe ('demarrage#' + $i) $Script:StartHooks[$i] $null) }
}
# Journal sans repetition : un probleme est note quand il apparait ou change, et son retour a la normale une fois
function Invoke-GBMinuteChecks {
    foreach ($k in @($Script:MinuteChecks.Keys)) {
        $txt = ""
        try { $txt = (@(& $Script:MinuteChecks[$k]) | Where-Object { $null -ne $_ -and "$_" -ne '' } | ForEach-Object { [string]$_ }) -join ' ; ' }
        catch { $txt = "verification impossible : " + $_.Exception.Message }
        $prev = $Script:HealthState[$k]
        if ($txt) {
            if (-not $prev -or $prev.Ok -or $prev.Text -ne $txt) { try { Log ("Verification (" + $k + ") : " + $txt) } catch {} }
        } elseif ($prev -and -not $prev.Ok) { try { Log ("Verification (" + $k + ") : tout est de nouveau en ordre") } catch {} }
        $Script:HealthState[$k] = @{ Ok = (-not $txt); Text = [string]$txt; Time = (Get-Date) }
    }
}

# --- Changement de modele : enregistre le choix puis relance GameBoost (meme .exe ou meme script) ---------------
# La nouvelle instance attend la fin de celle-ci (-WaitPid) : le turbo et la carte graphique sont remis entre les deux.
function Get-GBRelaunchCommand([string]$Name) {
    $n = Resolve-GBEdition $Name; if (-not $n) { $n = 'Nexus' }
    $exe = [string]$IconPath
    # Lance par GameBoost.exe : le lanceur passe son propre chemin dans -IconPath
    if ($exe -and $exe -match '\.exe$' -and (Test-Path -LiteralPath $exe)) {
        return @{ Mode = 'exe'; File = $exe; Args = ('/edition:' + $n.ToLowerInvariant() + ' /waitpid:' + $PID) }
    }
    $a = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $PSCommandPath + '"'
    if ($exe) { $a += ' -IconPath "' + $exe + '"' }
    $a += ' -Edition ' + $n + ' -WaitPid ' + $PID
    return @{ Mode = 'script'; File = $Script:HostExe; Args = $a }
}
function Switch-GBEdition([string]$Name) {
    $n = Resolve-GBEdition $Name
    if (-not $n) { try { Log ("Modele inconnu : " + $Name) } catch {}; return $false }
    if ($n -eq $Script:Edition) { try { Log ("Modele " + (Get-GBEditionLabel $n) + " deja actif") } catch {}; return $false }
    if ($Script:Boosted -and -not $Script:EditionDryRun) {
        $r = [System.Windows.Forms.MessageBox]::Show("Le boost est actif. Changer de modele arrete le boost (tout est remis) puis relance GameBoost.`r`n`r`nContinuer ?", "GameBoost", "YesNo", "Question")
        if ($r -ne [System.Windows.Forms.DialogResult]::Yes) { return $false }
    }
    $Script:Config.Edition = $n; $Script:Config.EditionChosen = $true
    if ($Script:RealConfig) { $Script:RealConfig.Edition = $n; $Script:RealConfig.EditionChosen = $true }
    try { Save-Config } catch {}
    $cmd = Get-GBRelaunchCommand $n
    $Script:EditionLastCmd = $cmd
    if ($Script:EditionDryRun) { return $true }   # (tests : commande construite, rien n'est lance)
    try {
        if ($cmd.Mode -eq 'script') {
            # Comme le lanceur : pas de console, mais sans "fenetre cachee" (sinon la nouvelle fenetre s'ouvrirait reduite)
            $psi = New-Object System.Diagnostics.ProcessStartInfo($cmd.File, ($cmd.Args -replace ' -WindowStyle Hidden', ''))
            $psi.UseShellExecute = $false; $psi.CreateNoWindow = $true
            [void][System.Diagnostics.Process]::Start($psi)
        }
        else { Start-Process -FilePath $cmd.File -ArgumentList $cmd.Args -ErrorAction Stop }
    } catch {
        try { Log ("Changement de modele impossible : " + $_.Exception.Message) } catch {}
        return $false
    }
    try { Log ("Modele " + (Get-GBEditionLabel $n) + " : GameBoost redemarre...") } catch {}
    $Script:EditionSwitching = $true
    try { $form.Close() } catch {}
    return $true
}
# Menu Affichage : fenetre de choix, puis relance si le modele change
function Select-GBEdition {
    $p = Show-GBEditionPicker -Owner $form
    if ($p -and $p -ne $Script:Edition) { [void](Switch-GBEdition $p) }
}
# Changement de modele depuis l'interface de chaque modele : petit menu sous le controle clique
function Show-GBEditionMenu($anchor) {
    $cms = New-Object System.Windows.Forms.ContextMenuStrip
    $cms.Font = $fontUI; $cms.BackColor = $cPanel; $cms.ForeColor = $cText; $cms.ShowCheckMargin = $true; $cms.ShowImageMargin = $false
    try { if (Test-Path function:Get-GBMenuRenderer) { $rd = Get-GBMenuRenderer; if ($rd) { $cms.Renderer = $rd } } } catch {}
    foreach ($e in @(@('Nexus', 'complet : tous les reglages, temperatures, tout le kit'), @('Arena', 'gaming : tout pour jouer, look gaming'), @('Pure', 'simple : l essentiel, epure'))) {
        $it = New-Object System.Windows.Forms.ToolStripMenuItem(((Get-GBEditionLabel $e[0]) + "   " + $e[1]))
        $it.Tag = $e[0]; $it.ForeColor = $cText
        if ($e[0] -eq $Script:Edition) { $it.Checked = $true; $it.Text = (Get-GBEditionLabel $e[0]) + "   (modele actuel)" }
        $it.Add_Click({ $n = [string]$this.Tag; if ($n -ne $Script:Edition) { [void](Switch-GBEdition $n) } })
        [void]$cms.Items.Add($it)
    }
    [void]$cms.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
    $pk = New-Object System.Windows.Forms.ToolStripMenuItem("Comparer les 3 modeles..."); $pk.ForeColor = $cMuted
    $pk.Add_Click({ Select-GBEdition }); [void]$cms.Items.Add($pk)
    # Menu libere apres usage (meme si la fenetre se ferme pendant qu'il est ouvert)
    $cms.add_Closed({ param($s, $e) try { $m = $s; if ($m.IsHandleCreated -and -not $m.IsDisposed) { [void]$m.BeginInvoke([Action]({ try { $m.Dispose() } catch {} }.GetNewClosure())) } else { $m.Dispose() } } catch {} })
    $cms.Show($anchor, (New-Object System.Drawing.Point(0, $anchor.Height)))
}
# Rend un controle cliquable pour changer de modele (texte + petite fleche)
function Add-GBEditionSwitch($ctl, [string]$tipText = "") {
    $ctl.Cursor = [System.Windows.Forms.Cursors]::Hand
    $ctl.Add_Click({ Show-GBEditionMenu $this })
    if (-not $Script:EdSwitchCtls) { $Script:EdSwitchCtls = New-Object System.Collections.ArrayList }
    [void]$Script:EdSwitchCtls.Add($ctl)
    if (-not $tipText) { $tipText = "Changer de modele : NEXUS (complet), ARENA (gaming) ou PURE (simple). GameBoost redemarre, tes reglages sont gardes." }
    try { $tip.SetToolTip($ctl, $tipText) } catch {}
}

