# Barres de titre et barres de defilement du theme sur une fenetre et tous ses controles
# (theme clair PURE : barre de titre claire, barres de defilement de Windows)
function Set-GBDarkTree($ctl) {
    if (-not $Script:UiOK -or -not $Script:Theme.IsDark) { return }
    try {
        # (les panneaux sans defilement - lignes, cartes - sont ignores : un appel Windows de moins par ligne)
        if ($ctl -is [System.Windows.Forms.TextBoxBase] -or $ctl -is [System.Windows.Forms.ListBox] -or $ctl -is [System.Windows.Forms.ListView] -or
            ($ctl -is [System.Windows.Forms.ScrollableControl] -and $ctl.AutoScroll) -or $ctl -is [System.Windows.Forms.TreeView]) { [GBTheme]::DarkScrollbars($ctl) }
        foreach ($c in $ctl.Controls) { Set-GBDarkTree $c }
    } catch {}
}
function Set-GBDarkWindow($f) {
    $f.Add_HandleCreated({ if ($Script:UiOK) { if ($Script:Theme.IsDark) { [GBTheme]::DarkChrome($this.Handle) } else { [GBTheme]::LightChrome($this.Handle) } } })
    $f.Add_Shown({ Set-GBDarkTree $this })
}
