# Place les jauges selon le materiel : portable hybride = 2 jauges GPU, PC avec une seule carte = 1 jauge
function Set-GpuMeterLayout {
    if (-not $Script:Meters) { return }
    $dg = $Script:MainGpu; $ig = $Script:IGpu
    $hasD = [bool]($dg -and $dg.Kind -ne 'integree')
    $hasI = [bool]$ig
    $md = $Script:Meters['Dgpu']; $mg = $Script:Meters['Igpu']
    $Script:DgpuSubBase = $null
    if ($hasD) {
        if ($dg.Kind -eq 'dediee') { $md.Label = "GPU CARTE"; $md.LabelColor = $cCyan } else { $md.Label = "GPU"; $md.LabelColor = $cCyan }
        $t = $dg.Short; if ($dg.VramGo) { $t += " | " + $dg.VramGo + " Go" }; $md.Sub = $t; $Script:DgpuSubBase = $dg.Short
        $tip.SetToolTip($md, ("Carte graphique : " + $dg.Name + "`r`n" + $dg.KindLabel + " (" + $dg.Reason + ")`r`nC'est elle qui doit faire tourner tes jeux."))
    } elseif (-not $hasI) {
        $md.Label = "GPU"; $md.LabelColor = $cMuted; $md.Sub = "aucune carte detectee"
        $tip.SetToolTip($md, "Windows n'a donne aucune carte graphique (pilote absent ou adaptateur de base Microsoft). Ouvre 'Mises a jour pilotes'.")
    }
    if ($hasI) {
        $mg.Label = "GPU PROC"; $mg.LabelColor = $cViolet; $mg.Sub = $ig.Short
        $tt = "Puce graphique integree au processeur : " + $ig.Name + "`r`n(" + $ig.Reason + ")"
        if ($hasD) { $tt += "`r`nElle affiche le bureau et les petites applis ; si elle monte pendant un jeu, le jeu tourne sur la mauvaise puce." }
        else { $tt += "`r`nC'est la seule puce graphique de ce PC : tes jeux tournent dessus." }
        $tip.SetToolTip($mg, $tt)
    }
    if (-not $Script:Meters['Cpu'].Sub) { $Script:Meters['Cpu'].Sub = "processeur" }
    if (-not $Script:Meters['Ram'].Sub) { $Script:Meters['Ram'].Sub = "memoire" }
    if (-not $Script:Meters['Ping'].Sub) { $Script:Meters['Ping'].Sub = "latence internet" }
    $show = New-Object System.Collections.ArrayList
    [void]$show.Add($Script:Meters['Cpu'])
    if ($hasD -or -not $hasI) { [void]$show.Add($md) }
    if ($hasI) { [void]$show.Add($mg) }
    [void]$show.Add($Script:Meters['Ram']); [void]$show.Add($Script:Meters['Ping'])
    # Positions relatives a leur zone (carte "Performances") : correct a 100 %, 125 %, 150 %... meme si appele apres l'ouverture
    if ($Script:MeterHost) {
        $left = 0; $total = $Script:MeterHost.ClientSize.Width; $sc = [double]$total / [double]$Script:MeterHostW
        $top = 0; $hh = $Script:MeterHost.ClientSize.Height
    } else {
        $left = $txtLog.Left; $total = $txtLog.Width; $sc = [double]$total / 770.0
        $top = $Script:Meters['Cpu'].Top; $hh = $Script:Meters['Cpu'].Height
    }
    $gap = [int][math]::Round(12 * $sc); $w = [int][math]::Floor(($total - $gap * ($show.Count - 1)) / $show.Count)
    foreach ($k in @($Script:Meters.Keys)) { $Script:Meters[$k].Visible = $false }
    $x = $left
    foreach ($m in $show) { $m.Location = New-Object System.Drawing.Point($x, $top); $m.Size = New-Object System.Drawing.Size($w, $hh); $m.Visible = $true; $x += $w + $gap }
    $Script:MeterHasD = $hasD; $Script:MeterHasI = $hasI
}

