        $Script:Config.CloseToTrayTip = $true; try { Save-Config } catch {}
        $tray.ShowBalloonTip(4000, "GameBoost reste ouvert ici", "Clic droit sur l'icone : boost, luminosite, ecrans, ouvrir ou quitter. (Option dans le menu GameBoost.)", [System.Windows.Forms.ToolTipIcon]::Info)
    }
}
function Exit-GBApp { $Script:ReallyQuit = $true; $form.Close() }
$form.Add_FormClosing({
    param($s, $e)
    if ($Script:ReallyQuit -or $Script:EditionSwitching -or $Script:Closing) { return }
    if ($e.CloseReason -ne [System.Windows.Forms.CloseReason]::UserClosing) { return }
    if (-not [bool]$Script:Config.CloseToTray) { return }
    $e.Cancel = $true
    try { Hide-GBToTray } catch {}
})

# --- Fonctions ---------------------------------------------------------------
function Log($msg) {
    $txtLog.AppendText("[" + (Get-Date -Format "HH:mm:ss") + "] " + $msg + "`r`n")
    try { Add-Content -LiteralPath $Script:LogFile -Value ("[" + (Get-Date -Format "yyyy-MM-dd HH:mm:ss") + "] " + $msg) -Encoding UTF8 } catch {}
    [System.Windows.Forms.Application]::DoEvents()
}

# --- Mesures de performance --------------------------------------------------
# Noms des cartes graphiques a partir de leur identifiant (LUID) dans les compteurs de performance
function Get-GpuAdapterNames {
    $map = @{}
    try {
        foreach ($k in Get-ChildItem -LiteralPath 'HKLM:\SOFTWARE\Microsoft\DirectX' -ErrorAction Stop) {
            $pr = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if (-not $pr -or $null -eq $pr.AdapterLuid -or -not $pr.Description) { continue }
            $l = [long]$pr.AdapterLuid
            $hi = ($l -shr 32) -band 4294967295
            $lo = $l -band 4294967295
            $map[('luid_0x{0:x8}_0x{1:x8}' -f $hi, $lo)] = [string]$pr.Description
        }
    } catch {}
    return $map
}
$Script:GpuNames = Get-GpuAdapterNames

$Script:GpuKindLabel = @{ 'dediee' = 'carte graphique dediee'; 'integree' = 'puce graphique integree au processeur'; 'virtuel' = 'adaptateur virtuel / logiciel';
                         'npu' = 'processeur IA (NPU)'; 'inconnue' = 'type non determine' }

# Plusieurs indices, du plus fiable au moins fiable : indicateurs du pilote, fabricant/modele, emplacement PCI, memoire video
function Get-GpuKind($name, $vendor, $flags, $ded, $bus, $dev) {
    $n = [string]$name
    if ($null -ne $flags) {
        if ($flags -band 0x800) { return @('npu', "adaptateur de calcul uniquement (NPU)") }
        if ($flags -band 0x4)   { return @('virtuel', "adaptateur logiciel de Windows") }
        if ($flags -band 0x80)  { return @('virtuel', "carte virtuelle (machine virtuelle)") }
        if ($flags -band 0x40)  { return @('virtuel', "ecran virtuel / indirect") }
    }
    if ($n -match 'AI Boost|\bNPU\b|Hexagon|XDNA|Neural') { return @('npu', "processeur IA (NPU)") }
    if ($n -match 'Microsoft Basic Render|Microsoft Remote Display|Hyper-V|VMware|VirtualBox|Parsec|Virtual Display|Citrix|spacedesk|DisplayLink|IddSample|Meta Virtual|Splashtop|Sunshine|Virtual Monitor|Duet Display|Parallels|QXL|Red Hat|VirtIO|Bochs|UTM Display|Remote Desktop|RDP') {
        return @('virtuel', "adaptateur virtuel")
    }
    if ($n -match 'ASPEED|Matrox G200|\bMGA G200') { return @('virtuel', "affichage de base de carte mere serveur (pas pour jouer)") }
    if ($null -ne $flags) {
        if ($flags -band 0x20) { return @('integree', "indique par le pilote (mode hybride : puce integree)") }
        if ($flags -band 0x10) { return @('dediee', "indique par le pilote (mode hybride : carte dediee)") }
    }
    $v = ''
    if ($vendor -eq 0x8086 -or $n -match '^Intel') { $v = 'intel' }
    elseif ($vendor -eq 0x10DE -or $n -match 'NVIDIA|GeForce|Quadro|Tesla') { $v = 'nvidia' }
    elseif ($vendor -eq 0x1002 -or $vendor -eq 0x1022 -or $n -match 'AMD|Radeon|^ATI ') { $v = 'amd' }
    elseif ($vendor -eq 0x5143 -or $vendor -eq 0x4D4F4351 -or $n -match 'Qualcomm|Adreno|Snapdragon') { $v = 'qualcomm' }
    elseif ($vendor -eq 0x1414 -or $n -match '^Microsoft') { $v = 'microsoft' }
    switch ($v) {
        'intel' {
            if ($n -match 'Arc(\(TM\))?\s+(Pro\s+)?[AB]\d{2,3}|Iris(\(R\))? Xe MAX|\bDG[12]\b') { return @('dediee', "Intel Arc serie A/B (carte dediee)") }
            if ($null -ne $bus -and $bus -eq 0 -and $dev -eq 2) { return @('integree', "Intel a l'emplacement PCI 0:2, reserve a la puce du processeur") }
            return @('integree', "puce graphique Intel du processeur (UHD / Iris / Arc integre)")
        }
        'nvidia' {
            if ($n -match 'Tegra|N1X|GB10') { return @('integree', "puce NVIDIA integree") }
            return @('dediee', "carte NVIDIA")
        }
        'amd' {
            if ($n -match 'RX Vega (3|6|8|10|11) Graphics|Radeon\s*(\(TM\)\s*)?HD \d{4}[GD]\b|Radeon\s*(\(TM\)\s*)?\d{3,4}[MS]\b|Radeon\s*(\(TM\)\s*)?Graphics|Vega \d{1,2} Graphics|R[2-8] Graphics') {
                return @('integree', "puce Radeon du processeur AMD")
            }
            if ($n -match 'Radeon\s*(\(TM\)\s*)?(RX|Pro|R[579] \d{3}|HD \d{4}|VII|Vega (56|64|Frontier))|FirePro|Instinct') { return @('dediee', "carte AMD Radeon") }
        }
        'qualcomm' { return @('integree', "puce Adreno du processeur Snapdragon") }
        'microsoft' { return @('virtuel', "pilote generique Microsoft") }
    }
    if ($null -ne $ded) {
        if ($ded -ge 2GB)   { return @('dediee', "plus de 2 Go de memoire video dediee") }
        if ($ded -le 600MB) { return @('integree', "tres peu de memoire video dediee (puce integree)") }
    }
    return @('inconnue', "type non determine")
}

function Get-GpuVendorToolName($name) {
    if ($name -match 'NVIDIA|GeForce|Quadro') { return "NVIDIA App" }
    if ($name -match 'Radeon|AMD') { return "AMD Adrenalin" }
    if ($name -match 'Intel') { return "Intel Driver & Support Assistant" }
    return "Windows Update"
}

function Get-ShortGpuName($n) {
    if (-not $n) { return "GPU" }
    $t = ([string]$n) -replace '\((R|TM)\)', '' -replace '^NVIDIA GeForce ', '' -replace '^NVIDIA ', '' -replace ' Laptop GPU', '' -replace '^AMD Radeon', 'Radeon' -replace '^AMD ', '' -replace '^Qualcomm ', ''
    $t = $t -replace ' Graphics', '' -replace '\s+GPU\b', '' -replace '\s*\(\d+\s*GB\)', '' -replace '\s+', ' '
    $t = $t.Trim(); if (-not $t) { $t = ([string]$n).Trim() }
    return $t
}

# Utilisation de chaque carte graphique = moteur le plus occupe (meme calcul que le Gestionnaire des taches)
function Get-GpuUsage {
    $res = @{ Max = $null; Dedicated = $null; Integrated = $null; DedSleep = $false; Adapters = New-Object System.Collections.ArrayList; Procs = @{} }
    [void](Update-Perf)
    if (Test-Perf 'gpu') {
        # Compteurs Windows directs (rapide) : moteur le plus occupe par carte, calcule en C#
        $agg = $Script:Perf.GpuAgg('gpu')
        if ($null -eq $agg) { return $res }
        $adapt = $agg.Adapters; $procMax = $agg.Procs
    } else {
        try {
            $eng = @(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUEngine -ErrorAction Stop)
        } catch { return $res }
        $engSum = @{}      # carte|moteur -> somme des processus
        $procMax = @{}     # carte|pid -> moteur le plus utilise par ce processus
        foreach ($e in $eng) {
            if ($e.Name -notmatch '^pid_(\d+)_(luid_0x[0-9a-fA-F]+_0x[0-9a-fA-F]+)_phys_\d+_eng_(\d+)_engtype_(.*)$') { continue }
            $procId = [int]$Matches[1]; $luid = $Matches[2].ToLower(); $k = $luid + '|' + $Matches[3]
            $u = [double]$e.UtilizationPercentage
            $engSum[$k] = [double]$engSum[$k] + $u
            $pk = $luid + '|' + $procId
            if ($u -gt [double]$procMax[$pk]) { $procMax[$pk] = $u }
        }
        $adapt = @{}
        foreach ($k in $engSum.Keys) {
            $luid = $k.Split('|')[0]
            $v = [math]::Min(100, $engSum[$k])
            if (-not $adapt.ContainsKey($luid) -or $v -gt $adapt[$luid]) { $adapt[$luid] = $v }
        }
    }
    $skip = @{}
    foreach ($luid in $adapt.Keys) {
        $info = Get-GpuInfoByLuid $luid
        if ($info.Kind -eq 'virtuel' -or $info.Kind -eq 'npu') { $skip[$luid] = $true; continue }
        $u = [int][math]::Round($adapt[$luid])
        [void]$res.Adapters.Add([pscustomobject]@{ Luid = $luid; Name = $info.Name; Short = $info.Short; Kind = $info.Kind; Usage = $u })
        if ($info.Kind -eq 'integree') { if ($null -eq $res.Integrated -or $u -gt $res.Integrated) { $res.Integrated = $u } }
        else { if ($null -eq $res.Dedicated -or $u -gt $res.Dedicated) { $res.Dedicated = $u } }
    }
    # La carte qui fait tourner les jeux : la carte dediee si elle existe, sinon la puce integree
    if ($null -ne $res.Dedicated) { $res.Max = $res.Dedicated } else { $res.Max = $res.Integrated }
    foreach ($pk in $procMax.Keys) {
        if ($procMax[$pk] -lt 1) { continue }
        if ($skip.ContainsKey($pk.Split('|')[0])) { continue }
        $res.Procs[$pk] = $procMax[$pk]
    }
    return $res
}

function Format-GpuText($gu) {
    if (-not $gu -or $gu.Adapters.Count -eq 0) { return "n/d" }
    $shown = @($gu.Adapters | Where-Object { $_.Name -or $_.Usage -gt 0 })
    $parts = @()
    if ($gu.DedSleep -and $Script:MainGpu) { $parts += ($Script:MainGpu.Short + " 0% (en veille)") }
    foreach ($a in @($shown | Sort-Object @{ Expression = { if ($_.Kind -eq 'integree') { 1 } else { 0 } } }, @{ Expression = 'Usage'; Descending = $true })) {
        if ($a.Kind -eq 'integree' -and ($shown.Count -gt 1 -or $gu.DedSleep)) { $parts += ($a.Short + " (integre) " + $a.Usage + "%") }
        else { $parts += ($a.Short + " " + $a.Usage + "%") }
    }
    if ($parts.Count -eq 0) { return "0%" }
    return ($parts -join " | ")
}

function Get-SystemSnapshot {
    $snap = [ordered]@{ Cpu = $null; CpuMaxCore = $null; Gpu = $null; Igpu = $null; DgpuU = $null; IgpuU = $null; DgpuSleep = $false; GpuText = "n/d"; GpuDetail = $null; RamPct = $null; RamUsedGo = $null; RamTotalGo = $null; Procs = 0 }
    [void](Update-Perf)
    if (Test-Perf 'cpu') {
        $v = Get-PerfValue 'cpu'; if ($null -ne $v) { $snap.Cpu = [int][math]::Round([math]::Min(100, [math]::Max(0, $v))) }
        $arr = $Script:Perf.Array('cores')
        if ($arr) { foreach ($kv in $arr) { if ($kv.Key -ne '_Total') { $c = [int][math]::Round([math]::Min(100, [math]::Max(0, $kv.Value))); if ($null -eq $snap.CpuMaxCore -or $c -gt $snap.CpuMaxCore) { $snap.CpuMaxCore = $c } } } }
    } else {
        try {
            foreach ($c in @(Get-CimInstance Win32_PerfFormattedData_PerfOS_Processor -ErrorAction Stop)) {
                $v = [int]$c.PercentProcessorTime
                if ($c.Name -eq '_Total') { $snap.Cpu = $v }
                elseif ($null -eq $snap.CpuMaxCore -or $v -gt $snap.CpuMaxCore) { $snap.CpuMaxCore = $v }
            }
        } catch {}
    }
    $mem = $null; if ($Script:FastOK) { try { $mem = [GBSys]::Memory() } catch {} }
    if ($mem) {
        $tot = [double]$mem[0]; $free = [double]$mem[1]
        $snap.RamTotalGo = [math]::Round($tot / 1GB, 1)
        $snap.RamUsedGo  = [math]::Round(($tot - $free) / 1GB, 1)
        $snap.RamPct     = [int](($tot - $free) * 100 / $tot)
    } else {
        try {
            $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
            $tot = [double]$os.TotalVisibleMemorySize; $free = [double]$os.FreePhysicalMemory
            $snap.RamTotalGo = [math]::Round($tot / 1MB, 1)
            $snap.RamUsedGo  = [math]::Round(($tot - $free) / 1MB, 1)
            $snap.RamPct     = [int](($tot - $free) * 100 / $tot)
        } catch {}
    }
    # Carte graphique la plus occupee (et le detail par carte : Intel / NVIDIA / AMD)
    $gu = Get-GpuUsage
    $snap.DgpuU = $gu.Dedicated; $snap.IgpuU = $gu.Integrated
    $hasDed = [bool]($Script:MainGpu -and $Script:MainGpu.Kind -ne 'integree')
    if ($hasDed -and $null -eq $gu.Dedicated -and $gu.Adapters.Count -gt 0) {
        # Portable hybride : la carte dediee dort (aucun programme dessus) -> 0 %, pas l'usage de la puce integree
        $snap.DgpuU = 0; $snap.DgpuSleep = $true
    }
    if ($hasDed) { $snap.Gpu = $snap.DgpuU } else { $snap.Gpu = $gu.Max }
    if ($Script:GpuHybrid -and $null -ne $gu.Integrated) { $snap.Igpu = $gu.Integrated }
    $gu.DedSleep = $snap.DgpuSleep
    $snap.GpuText = Format-GpuText $gu
    $snap.GpuDetail = $gu
    $pc = Get-PerfValue 'procs'
    if ($null -ne $pc) { $snap.Procs = [int]$pc } else { $snap.Procs = @(Get-Process -ErrorAction SilentlyContinue).Count }
    return $snap
}

# Mesures supplementaires pendant le jeu
function Get-ExtendedStats {
    $x = [ordered]@{ CpuPerf = $null; VramGo = $null; DiskBusy = $null; HardFaults = $null; CommitPct = $null }
    [void](Update-Perf)
    if (Test-Perf 'pagesin') {
        $v = Get-PerfValue 'cpuperf'; if ($null -ne $v) { $x.CpuPerf = [int][math]::Round($v) }
        $mem = $Script:Perf.Array('vram')
        if ($mem) {
            $best = $null; $bestAll = $null
            $ml = $null; if ($Script:MainGpu -and $Script:MainGpu.Luid) { $ml = [string]$Script:MainGpu.Luid }
            foreach ($kv in $mem) {
                if ($null -eq $bestAll -or $kv.Value -gt $bestAll) { $bestAll = $kv.Value }
                if ($ml -and $kv.Key.ToLower().StartsWith($ml) -and ($null -eq $best -or $kv.Value -gt $best)) { $best = $kv.Value }
            }
            if ($null -eq $best) { $best = $bestAll }
            if ($null -ne $best) { $x.VramGo = [math]::Round([double]$best / 1GB, 2) }
        }
        $dk = $Script:Perf.Array('disk')
        if ($dk) {
            $minIdle = $null
            foreach ($kv in $dk) { if ($kv.Key -ne '_Total' -and ($null -eq $minIdle -or $kv.Value -lt $minIdle)) { $minIdle = $kv.Value } }
            if ($null -ne $minIdle) { $b = 100 - [int]$minIdle; if ($b -lt 0) { $b = 0 }; if ($b -gt 100) { $b = 100 }; $x.DiskBusy = $b }
        }
        $v = Get-PerfValue 'pagesin'; if ($null -ne $v) { $x.HardFaults = [int]$v }
        $v = Get-PerfValue 'commit'; if ($null -ne $v) { $x.CommitPct = [int]$v }
        return $x
    }
    try { $x.CpuPerf = [int](Get-CimInstance Win32_PerfFormattedData_Counters_ProcessorInformation -Filter "Name='_Total'" -ErrorAction Stop).PercentProcessorPerformance } catch {}
    try {
        $mem = @(Get-CimInstance Win32_PerfFormattedData_GPUPerformanceCounters_GPUAdapterMemory -ErrorAction Stop)
        if ($Script:MainGpu -and $Script:MainGpu.Luid) {
            $mine = @($mem | Where-Object { ([string]$_.Name).ToLower().StartsWith($Script:MainGpu.Luid) })
            if ($mine.Count -gt 0) { $mem = $mine }
        }
        if ($mem.Count -gt 0) { $x.VramGo = [math]::Round(([double]($mem | Measure-Object -Property DedicatedUsage -Maximum).Maximum) / 1GB, 2) }
    } catch {}
    try {
        $disks = @(Get-CimInstance Win32_PerfFormattedData_PerfDisk_PhysicalDisk -ErrorAction Stop | Where-Object { $_.Name -ne '_Total' })
        if ($disks.Count -gt 0) {
            $b = 100 - [int](($disks | Measure-Object -Property PercentIdleTime -Minimum).Minimum)
            if ($b -lt 0) { $b = 0 }; if ($b -gt 100) { $b = 100 }
            $x.DiskBusy = $b
        }
    } catch {}
    try {
        $m = Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction Stop
        $x.HardFaults = [int]$m.PagesInputPersec
        $x.CommitPct  = [int]$m.PercentCommittedBytesInUse
    } catch {}
    return $x
}

function Get-VramTotalGo {
    $best = 0.0
    try {
        $base = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
        foreach ($k in Get-ChildItem -Path $base -ErrorAction SilentlyContinue) {
            if ($k.PSChildName -notmatch '^\d{4}$') { continue }
            $pr = Get-ItemProperty -Path $k.PSPath -ErrorAction SilentlyContinue
            if (-not $pr) { continue }
            $v = $pr.'HardwareInformation.qwMemorySize'
            if (-not $v) {
                $v = $pr.'HardwareInformation.MemorySize'
                if ($v -is [byte[]] -and $v.Length -ge 4) { $v = [BitConverter]::ToUInt32($v, 0) }
            }
            if ($v -and [double]$v -gt $best) { $best = [double]$v }
        }
    } catch {}
    if ($best -gt 0) { return [math]::Round($best / 1GB, 1) }
    return $null
}
$Script:VramTotalGo = Get-VramTotalGo

# --- Inventaire des cartes graphiques : carte dediee / puce integree --------------
function Get-GpuInventory {
    $inv = New-Object System.Collections.ArrayList
    $dx = @{}
    try {
        foreach ($k in Get-ChildItem -LiteralPath 'HKLM:\SOFTWARE\Microsoft\DirectX' -ErrorAction Stop) {
            $pr = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction SilentlyContinue
            if (-not $pr -or $null -eq $pr.AdapterLuid) { continue }
            $l = [long]$pr.AdapterLuid
            $dx[('luid_0x{0:x8}_0x{1:x8}' -f (($l -shr 32) -band 4294967295), ($l -band 4294967295))] = $pr
        }
    } catch {}
    $wmi = @(); try { $wmi = @(Get-CimInstance Win32_VideoController -ErrorAction Stop) } catch {}
    $kmt = @(); try { if ($Script:NativeOK) { $kmt = @([GBGpu]::List()) } } catch {}

    $raw = New-Object System.Collections.ArrayList
    if ($kmt.Count -gt 0) {
        foreach ($a in $kmt) {
            $d = $dx[$a.Luid]
            $name = [string]$a.Name; if (-not $name -and $d) { $name = [string]$d.Description }
            $ded = $null; $shared = $null
            if ($a.MemOk) { $ded = [double]$a.DedicatedVideo; $shared = [double]$a.SharedSystem }
            elseif ($d -and $null -ne $d.DedicatedVideoMemory) { $ded = [double]$d.DedicatedVideoMemory; $shared = [double]$d.SharedSystemMemory }
            $flags = $null; if ($a.TypeOk) { $flags = [long]$a.TypeFlags }
            $bus = $null; $dev = $null; if ($a.AddrOk) { $bus = [long]$a.Bus; $dev = [long]$a.Device }
            $ven = $null; if ($d -and $null -ne $d.VendorId) { $ven = [long]$d.VendorId }
            [void]$raw.Add(@{ Luid = $a.Luid; Name = $name; Vendor = $ven; Ded = $ded; Shared = $shared; Flags = $flags; Bus = $bus; Dev = $dev; Source = 'noyau Windows' })
        }
    } else {
        # Repli : cartes vues par Windows (WMI) + registre DirectX pour l'identifiant
        foreach ($w in $wmi) {
            $cand = @($dx.GetEnumerator() | Where-Object { [string]$_.Value.Description -eq [string]$w.Name } | Sort-Object { [long]$_.Value.LastSeen } -Descending)
            $luid = $null; $d = $null
            if ($cand.Count -gt 0) { $luid = $cand[0].Key; $d = $cand[0].Value }
            $ded = $null; $shared = $null; $ven = $null
            if ($d) { if ($null -ne $d.DedicatedVideoMemory) { $ded = [double]$d.DedicatedVideoMemory }; if ($null -ne $d.SharedSystemMemory) { $shared = [double]$d.SharedSystemMemory }; if ($null -ne $d.VendorId) { $ven = [long]$d.VendorId } }
            if ($null -eq $ven -and [string]$w.PNPDeviceID -match 'VEN_([0-9A-Fa-f]{4})') { $ven = [Convert]::ToInt64($Matches[1], 16) }
            [void]$raw.Add(@{ Luid = $luid; Name = [string]$w.Name; Vendor = $ven; Ded = $ded; Shared = $shared; Flags = $null; Bus = $null; Dev = $null; Source = 'WMI' })
        }
    }
    foreach ($r in $raw) {
        $k = Get-GpuKind $r.Name $r.Vendor $r.Flags $r.Ded $r.Bus $r.Dev
        $w = @($wmi | Where-Object { [string]$_.Name -eq [string]$r.Name }) | Select-Object -First 1
        $vram = $null; if ($r.Ded) { $vram = [math]::Round($r.Ded / 1GB, 1) }
        $shared = $null; if ($r.Shared) { $shared = [math]::Round($r.Shared / 1GB, 1) }
        $drvDate = $null; if ($w -and $w.DriverDate) { try { $drvDate = [datetime]$w.DriverDate } catch {} }
        [void]$inv.Add([pscustomobject]@{
            Luid = $r.Luid; Name = $r.Name; Short = (Get-ShortGpuName $r.Name); Kind = $k[0]; KindLabel = $Script:GpuKindLabel[$k[0]]; Reason = $k[1]
            VramGo = $vram; SharedGo = $shared; Vendor = $r.Vendor; Flags = $r.Flags; Bus = $r.Bus; Dev = $r.Dev; Source = $r.Source
            Display = [bool]($w -and $w.CurrentRefreshRate); DriverVersion = $(if ($w) { [string]$w.DriverVersion } else { "" }); DriverDate = $drvDate })
    }
    return $inv   # (pas de virgule : l'appelant fait @(...), sinon la liste serait imbriquee)
}

function Initialize-GpuInventory {
    $Script:GpuInv = @(Get-GpuInventory)
    $Script:GpuByLuid = @{}
    foreach ($g in $Script:GpuInv) { if ($g.Luid) { $Script:GpuByLuid[$g.Luid] = $g } }
    $real = @($Script:GpuInv | Where-Object { $_.Kind -eq 'dediee' -or $_.Kind -eq 'integree' -or $_.Kind -eq 'inconnue' })
    $Script:MainGpu = @($real | Where-Object { $_.Kind -eq 'dediee' } | Sort-Object { [double]$_.VramGo } -Descending) | Select-Object -First 1
    if (-not $Script:MainGpu) { $Script:MainGpu = @($real | Where-Object { $_.Kind -eq 'inconnue' }) | Select-Object -First 1 }
    $Script:IGpu = @($real | Where-Object { $_.Kind -eq 'integree' }) | Select-Object -First 1
    if (-not $Script:MainGpu) { $Script:MainGpu = $Script:IGpu }
    $Script:GpuHybrid = [bool]($Script:MainGpu -and $Script:IGpu -and $Script:MainGpu -ne $Script:IGpu)
    if ($Script:MainGpu -and $Script:MainGpu.Kind -eq 'dediee' -and $Script:MainGpu.VramGo) { $Script:VramTotalGo = $Script:MainGpu.VramGo }
    try { Set-GpuMeterLayout } catch {}
}

function Get-GpuInfoByLuid($luid) {
    $i = $Script:GpuByLuid[$luid]
    if ($i) { return $i }
    $name = $Script:GpuNames[$luid]
    $k = Get-GpuKind $name $null $null $null $null $null
    $o = [pscustomobject]@{ Luid = $luid; Name = $name; Short = (Get-ShortGpuName $name); Kind = $k[0]; KindLabel = $Script:GpuKindLabel[$k[0]]; Reason = $k[1] }
    $Script:GpuByLuid[$luid] = $o
    return $o
}

function Get-GpuSpecText {
    $parts = @()
    foreach ($g in @($Script:GpuInv | Where-Object { $_.Kind -ne 'virtuel' -and $_.Kind -ne 'npu' })) {
        $t = $g.Name + " [" + $g.KindLabel
        if ($g.Kind -eq 'dediee' -and $g.VramGo) { $t += ", " + $g.VramGo + " Go" }
        if ($g.DriverVersion) { $t += ", pilote " + $g.DriverVersion }
        $t += "]"
        $parts += $t
    }
    if ($parts.Count -eq 0) { return "non detectee" }
    return ($parts -join " + ")
}

function Get-GpuDetailLines {
    $out = @()
    foreach ($g in @($Script:GpuInv)) {
        $fl = "-"; if ($null -ne $g.Flags) { $fl = '0x{0:X}' -f $g.Flags }
        $pci = "-"; if ($null -ne $g.Bus) { $pci = "" + $g.Bus + ":" + $g.Dev }
        $ven = "-"; if ($null -ne $g.Vendor) { $ven = '0x{0:X4}' -f $g.Vendor }
        $out += ("- " + $g.Name + " -> " + $g.KindLabel.ToUpper() + " (" + $g.Reason + ")")
        $out += ("    memoire dediee " + (Fmt $g.VramGo " Go") + ", partagee " + (Fmt $g.SharedGo " Go") + " | ecran branche : " + $(if ($g.Display) { "oui" } else { "non" }) +
                 " | PCI " + $pci + " | fabricant " + $ven + " | indicateurs " + $fl + " | source " + $g.Source)
    }
    if ($out.Count -eq 0) { $out = @("Aucune carte graphique detectee") }
    return $out
}

$Script:GpuInv = @(); $Script:GpuByLuid = @{}; $Script:MainGpu = $null; $Script:IGpu = $null; $Script:GpuHybrid = $false
try { Initialize-GpuInventory } catch {}
if (-not $Script:GpuHybrid) {
    $chkGpuPref.Text = "Forcer la carte puissante (inutile : 1 seule carte)"
    $chkGpuPref.Checked = $false; $chkGpuPref.Enabled = $false
}

