}
# Valeur "sur secteur" d'un reglage du plan d'alimentation (independant de la langue de Windows)
function Get-PowerSettingAC($scheme, $sub, $setting) {
    $out = (powercfg /query $scheme $sub $setting 2>$null) -join "`n"
    $hex = [regex]::Matches($out, '0x[0-9a-fA-F]{8}')
    if ($hex.Count -ge 2) { return [Convert]::ToInt32($hex[$hex.Count - 2].Value, 16) }
    return $null
}

# --- FPS avec PresentMon ------------------------------------------------------
function Read-FpsData {
    # Lit les nouvelles lignes du fichier PresentMon : renvoie les temps d'image (ms) de l'intervalle
    $new = New-Object 'System.Collections.Generic.List[double]'
    if (-not $Script:PMFile -or -not (Test-Path -LiteralPath $Script:PMFile)) { return ,$new }
    if ($Script:FpsReader) {
        try { $new.AddRange([double[]]$Script:FpsReader.ReadNew($Script:PMFile)) } catch {}
        return ,$new
    }
    $chunk = ""
    try {
        $fs = New-Object System.IO.FileStream($Script:PMFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -lt $Script:PMPos) { $Script:PMPos = 0 }
            [void]$fs.Seek($Script:PMPos, [System.IO.SeekOrigin]::Begin)
            $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::ASCII)
            $chunk = $sr.ReadToEnd()
            $Script:PMPos = $fs.Length
        } finally { $fs.Dispose() }
    } catch { return ,$new }
    $text = $Script:PMPending + $chunk
    $lastNl = $text.LastIndexOf("`n")
    if ($lastNl -lt 0) { $Script:PMPending = $text; return ,$new }
    $Script:PMPending = $text.Substring($lastNl + 1)
    $fts = New-Object 'System.Collections.Generic.List[double]'
    $scs = New-Object 'System.Collections.Generic.List[string]'
    $counts = @{}
    $inv = [System.Globalization.CultureInfo]::InvariantCulture
    $style = [System.Globalization.NumberStyles]::Float
    foreach ($line in $text.Substring(0, $lastNl).Split("`n")) {
        $l = $line.TrimEnd("`r")
        if (-not $l) { continue }
        if ($l.StartsWith('Application,')) {
            $h = $l.Split(',')
            $ft = [array]::IndexOf($h, 'msBetweenPresents')
            if ($ft -lt 0) { $ft = [array]::IndexOf($h, 'FrameTime') }
            $Script:PMCols = @{ Ft = $ft; Sc = [array]::IndexOf($h, 'SwapChainAddress') }
            continue
        }
        if (-not $Script:PMCols -or $Script:PMCols.Ft -lt 0) { continue }
        $f = $l.Split(',')
        if ($f.Length -le $Script:PMCols.Ft) { continue }
        $val = 0.0
        if (-not [double]::TryParse($f[$Script:PMCols.Ft], $style, $inv, [ref]$val)) { continue }
        if ($val -le 0 -or $val -gt 5000) { continue }
        $sc = ''
        if ($Script:PMCols.Sc -ge 0 -and $f.Length -gt $Script:PMCols.Sc) { $sc = $f[$Script:PMCols.Sc] }
        $fts.Add($val); $scs.Add($sc)
        $counts[$sc] = 1 + [int]$counts[$sc]
    }
    if ($fts.Count -eq 0) { return ,$new }
    # Si le jeu a plusieurs fenetres de rendu, on garde la principale
    $main = ''; $best = -1
    foreach ($k in $counts.Keys) { if ($counts[$k] -gt $best) { $best = $counts[$k]; $main = $k } }
    for ($i = 0; $i -lt $fts.Count; $i++) { if ($scs[$i] -eq $main) { $new.Add($fts[$i]) } }
    return ,$new
}

function Get-IntervalFps {
    if (-not $Script:PMFile) { return $null }
    $fts = Read-FpsData
    if ($fts.Count -lt 5) { return $null }
    if ($Script:FrameTimes.Count -lt 4000000) { $Script:FrameTimes.AddRange($fts) }
    $sum = 0.0
    foreach ($v in $fts) { $sum += $v }
    $arr = $fts.ToArray(); [array]::Sort($arr)
    $idx = [math]::Min($arr.Length - 1, [int][math]::Floor($arr.Length * 0.99))
    return @{ Fps = [int][math]::Round(1000.0 * $fts.Count / $sum); Low = [int][math]::Round(1000.0 / $arr[$idx]) }
}

function Start-FpsCapture {
    if (-not $Script:Config.FpsMeasure -or -not $Script:PMPath) { return }
    if ($Script:PM -and -not $Script:PM.HasExited) { return }
    # Les launchers (client Riot, Steam, Epic...) n'affichent pas le jeu : on attend le vrai processus du jeu
    $games = @(Get-GameProcesses | Where-Object { -not $Script:NotGameSet.Contains($_.ProcessName) })
    if ($games.Count -eq 0) { return }
    # Le processus principal du jeu = celui qui utilise le plus de memoire
    $target = $null; $bestWs = -1
    foreach ($gp in $games) { $ws = 0; try { $ws = $gp.WorkingSet64 } catch {}; if ($ws -gt $bestWs) { $bestWs = $ws; $target = $gp } }
    if (-not $target) { return }
    if ($Script:PMFile) { $rest = Read-FpsData; if ($rest.Count -gt 0 -and $Script:FrameTimes.Count -lt 4000000) { $Script:FrameTimes.AddRange($rest) } }
    $Script:PMFile = Join-Path $LogDir ("fps_" + (Get-Date -Format "yyyy-MM-dd_HH-mm-ss") + ".csv")
    $Script:PMPos = 0; $Script:PMCols = $null; $Script:PMPending = ""
    $Script:FpsReader = $null; if ($Script:FastOK) { try { $Script:FpsReader = New-Object GBFpsReader } catch {} }
    if ($Script:PMv1) {
        $pmArgs = @('-process_id', [string]$target.Id, '-output_file', ('"' + $Script:PMFile + '"'), '-terminate_on_proc_exit',
                    '-stop_existing_session', '-session_name', 'GameBoostFPS', '-no_top')
    } else {
        $pmArgs = @('--process_id', [string]$target.Id, '--output_file', ('"' + $Script:PMFile + '"'), '--terminate_on_proc_exit',
                    '--stop_existing_session', '--session_name', 'GameBoostFPS', '--no_console_stats', '--v1_metrics')
    }
    try {
        $Script:PM = Start-Process -FilePath $Script:PMPath -ArgumentList $pmArgs -WindowStyle Hidden -PassThru
        # GameBoost passe en priorite basse pendant le jeu : la mesure des FPS garde une priorite haute pour ne perdre aucune image
        try { $Script:PM.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::AboveNormal } catch {}
        $Script:FpsFiles = @($Script:FpsFiles + $Script:PMFile)
        Log ("Mesure des FPS demarree : " + (Get-GameLabel $target.ProcessName) + " (PID " + $target.Id + ")")
    } catch { $Script:PM = $null; Log ("Mesure des FPS impossible : " + $_.Exception.Message) }
}

function Stop-FpsCapture {
    if ($Script:PM -and -not $Script:PM.HasExited) {
        try {
            $stopArgs = @('--terminate_existing_session', '--session_name', 'GameBoostFPS')
            if ($Script:PMv1) { $stopArgs = @('-terminate_existing', '-session_name', 'GameBoostFPS') }
            $stopper = Start-Process -FilePath $Script:PMPath -ArgumentList $stopArgs -WindowStyle Hidden -PassThru
            [void]$stopper.WaitForExit(5000)
        } catch {}
        try { if (-not $Script:PM.WaitForExit(3000)) { $Script:PM.Kill() } } catch {}
    }
    if ($Script:PMFile) {
        $rest = Read-FpsData
        if ($rest.Count -gt 0 -and $Script:FrameTimes.Count -lt 4000000) { $Script:FrameTimes.AddRange($rest) }
    }
    $Script:PM = $null
}

function Get-FrameStats {
    $n = $Script:FrameTimes.Count
    if ($n -lt 200) { return $null }
    $arr = $Script:FrameTimes.ToArray()
    [array]::Sort($arr)
    $sum = 0.0
    foreach ($v in $arr) { $sum += $v }
    $median = $arr[[int][math]::Floor($n / 2)]
    $p99  = $arr[[math]::Min($n - 1, [int][math]::Floor($n * 0.99))]
    $p999 = $arr[[math]::Min($n - 1, [int][math]::Floor($n * 0.999))]
    $thr = [math]::Max(2.5 * $median, 20.0)
    $stut = 0; $freeze = 0
    for ($i = $n - 1; $i -ge 0; $i--) {
        if ($arr[$i] -le $thr) { break }
        $stut++
        if ($arr[$i] -ge 100) { $freeze++ }
    }
    return @{ Frames = $n; Fps = [math]::Round(1000.0 * $n / $sum, 1); Low1 = [math]::Round(1000.0 / $p99, 1); Low01 = [math]::Round(1000.0 / $p999, 1);
              AvgFt = [math]::Round($sum / $n, 2); MedianFt = [math]::Round($median, 2); Worst = [math]::Round($arr[$n - 1], 1);
              Stutters = $stut; Freezes = $freeze; Threshold = [math]::Round($thr, 1) }
}

# --- Programmes gourmands pendant le jeu (toutes les 30 s) --------------------
function Sample-TopProcesses {
    $now = Get-Date
    $el = 0.0
    if ($Script:ProcPrevTime) { $el = ($now - $Script:ProcPrevTime).TotalMilliseconds }
    $cur = @{}; $agg = @{}
    $fastList = $null; if ($Script:FastOK) { try { $fastList = [GBProcSnap]::Take() } catch {} }
    if ($fastList) {
        foreach ($pi in $fastList) {
            if ($pi.Pid -eq 0) { continue }
            $name = $pi.Name
            if (-not $agg.ContainsKey($name)) { $agg[$name] = @{ Cpu = 0.0; Ram = 0.0 } }
            $agg[$name].Ram += [double]$pi.WorkingSet
            $t = $pi.CpuTime / 10000.0
            $cur[$pi.Pid] = $t
            if ($el -gt 0 -and $Script:ProcPrev.ContainsKey($pi.Pid)) {
                $d = $t - $Script:ProcPrev[$pi.Pid]
                if ($d -gt 0) { $agg[$name].Cpu += $d / $el / $Script:Cores * 100 }
            }
        }
    }
    else { foreach ($p in Get-Process -ErrorAction SilentlyContinue) {
        if ($p.Id -eq 0) { continue }
        $t = $null
        try { $t = $p.TotalProcessorTime.TotalMilliseconds } catch {}
        $name = $p.ProcessName
        if (-not $agg.ContainsKey($name)) { $agg[$name] = @{ Cpu = 0.0; Ram = 0.0 } }
        try { $agg[$name].Ram += [double]$p.WorkingSet64 } catch {}
        if ($null -eq $t) { continue }
        $cur[$p.Id] = $t
        if ($el -gt 0 -and $Script:ProcPrev.ContainsKey($p.Id)) {
            $d = $t - $Script:ProcPrev[$p.Id]
            if ($d -gt 0) { $agg[$name].Cpu += $d / $el / $Script:Cores * 100 }
        }
    } }
    $Script:ProcSamples++
    foreach ($k in $agg.Keys) {
        $a = $agg[$k]
        if (-not $Script:ProcStats.ContainsKey($k)) { $Script:ProcStats[$k] = @{ Sum = 0.0; Max = 0.0; RamMax = 0.0; N = 0 } }
        $st = $Script:ProcStats[$k]
        if ($el -gt 0) { $st.Sum += $a.Cpu; $st.N++; if ($a.Cpu -gt $st.Max) { $st.Max = $a.Cpu } }
        if ($a.Ram -gt $st.RamMax) { $st.RamMax = $a.Ram }
    }
    $Script:ProcPrev = $cur
    $Script:ProcPrevTime = $now
}

function Add-SessionEvent($t) {
    if ($Script:Boosted -and $Script:SessionEvents.Count -lt 300) { [void]$Script:SessionEvents.Add((Get-Date -Format "HH:mm:ss") + "  " + $t) }
}

function Get-GameStats {
    $now = Get-Date
    $cpu = 0.0; $ram = 0.0; $found = $false; $cpuOk = $false
    foreach ($p in Get-GameProcesses) {
        $found = $true
        try { $ram += $p.WorkingSet64 } catch {}
        try {
            $t = $p.TotalProcessorTime.TotalMilliseconds
            if ($Script:PrevGameCpu.ContainsKey($p.Id) -and $Script:PrevSampleTime) {
                $el = ($now - $Script:PrevSampleTime).TotalMilliseconds
                if ($el -gt 0) { $cpu += ($t - $Script:PrevGameCpu[$p.Id]) / $el / $Script:Cores * 100; $cpuOk = $true }
            }
            $Script:PrevGameCpu[$p.Id] = $t
        } catch {}
    }
    $Script:PrevSampleTime = $now
    if (-not $found) { return $null }
    $c = $null
    if ($cpuOk) { $c = [int][math]::Min(100, [math]::Max(0, $cpu)) }
    return @{ Cpu = $c; RamMo = [int]($ram / 1MB) }
}

$Script:PingMode = 'icmp'
function Get-TcpPing {
    $c = New-Object System.Net.Sockets.TcpClient
    try {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $ar = $c.BeginConnect("1.1.1.1", 443, $null, $null)
        if ($ar.AsyncWaitHandle.WaitOne(700) -and $c.Connected) { $c.EndConnect($ar); return [int]$sw.ElapsedMilliseconds }
    } catch {} finally { try { $c.Close() } catch {} }
    return $null
}

function Get-Ping {
    # Ping en arriere-plan (l'interface n'attend jamais le reseau) ; TCP si le ping est bloque
    if ($Script:FastOK) {
        $v = -1
        try {
            $v = [GBPinger]::Last; [GBPinger]::Kick()
            if ([GBPinger]::TakeSwitchNotice()) { $Script:PingMode = 'tcp'; Log "Le ping est bloque sur ce reseau : mesure par connexion TCP a la place" }
        } catch {}
        if ($v -lt 0) { return $null }
        return $v
    }
    # Ping classique ; si le reseau (box, entreprise, VPN) bloque le ping, mesure par connexion TCP
    if ($Script:PingMode -eq 'icmp') {
        try {
            $r = $Script:Pinger.Send("1.1.1.1", 700)
            if ($r.Status -eq 'Success') { return [int]$r.RoundtripTime }
        } catch {}
        $t = Get-TcpPing
        if ($null -ne $t) { $Script:PingMode = 'tcp'; try { Log "Le ping est bloque sur ce reseau : mesure par connexion TCP a la place" } catch {} }
        return $t
    }
    return Get-TcpPing
}

function Fmt($v, $unit) { if ($null -eq $v) { return "n/d" } return ([string]$v + $unit) }

function Check-Alert($key, $cond, $msgOn, $msgOff) {
    $was = [bool]$Script:Alerts[$key]
    if ($cond -and -not $was) {
        Log ("ALERTE : " + $msgOn); $Script:Alerts[$key] = $true
        $Script:AlertCounts[$key] = 1 + [int]$Script:AlertCounts[$key]
        Add-SessionEvent ("ALERTE : " + $msgOn)
    }
    elseif (-not $cond -and $was) { Log $msgOff; $Script:Alerts[$key] = $false; Add-SessionEvent $msgOff }
}

$Script:Sampling = $false
# --- Overlay en jeu : petit cadre toujours au-dessus (FPS, 1 % bas, CPU, GPU, RAM, ping), la souris passe a travers ---
# Visible en plein ecran fenetre / sans bordure (un jeu en plein ecran exclusif passe devant toute fenetre).
$Script:Overlay = $null
function Show-GBOverlay {
    if ($Script:Overlay -and -not $Script:Overlay.IsDisposed) { return }
    $o = New-Object System.Windows.Forms.Form
    $o.FormBorderStyle = 'None'; $o.ShowInTaskbar = $false; $o.TopMost = $true; $o.StartPosition = 'Manual'
    $o.BackColor = $cDeep; $o.Opacity = 0.82
    $sc = [math]::Max(1.0, [double]$Script:DpiScale)
    $o.Size = New-Object System.Drawing.Size([int](250 * $sc), [int](92 * $sc))
    $l = New-Object System.Windows.Forms.Label; $l.Dock = 'Fill'; $l.Font = $fontMono; $l.ForeColor = $cCyan; $l.BackColor = $cDeep
    $l.Padding = New-Object System.Windows.Forms.Padding([int](8 * $sc)); $l.Text = "GameBoost`r`nmesures dans 5 s..."
    $o.Controls.Add($l); $o.Tag = $l
    # Ecran du jeu (celui ou se trouve la souris, capturee par le jeu) : utile avec plusieurs ecrans
    $wa = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).Bounds; $m = [int](12 * $sc)
    $x = $wa.Left + $m; $y = $wa.Top + $m
    switch ([int]$Script:Config.OverlayCorner) { 1 { $x = $wa.Right - $o.Width - $m } 2 { $y = $wa.Bottom - $o.Height - $m } 3 { $x = $wa.Right - $o.Width - $m; $y = $wa.Bottom - $o.Height - $m } }
    $o.Location = New-Object System.Drawing.Point($x, $y)
    $null = $o.Handle
    if ($Script:UiOK) { [GBTheme]::MakeOverlay($o); [GBTheme]::ShowNoActivate($o) } else { $o.Show() }
    $o.TopMost = $true
    $Script:Overlay = $o
}
function Update-GBOverlay($fps, $low, $s, $ping) {
    Show-GBOverlay
    $l = $Script:Overlay.Tag
    $f = "FPS  --"; if ($null -ne $fps) { $f = "FPS  " + $fps + "   (1% bas " + $low + ")" }
    $g = $s.DgpuU; if ($null -eq $g) { $g = $s.Gpu }
    $l.Text = $f + "`r`nCPU  " + (Fmt $s.Cpu "%") + "   GPU " + (Fmt $g "%") + "`r`nRAM  " + (Fmt $s.RamPct "%") + "   Ping " + (Fmt $ping " ms")
    $l.ForeColor = $cCyan
    if (($null -ne $fps -and $null -ne $low -and [double]$low -lt 0.5 * [double]$fps) -or ($null -ne $ping -and $ping -ge 150)) { $l.ForeColor = $cYellow }
}
function Hide-GBOverlay {
    if ($Script:Overlay) { try { $Script:Overlay.Close(); $Script:Overlay.Dispose() } catch {}; $Script:Overlay = $null }
}

function Take-Sample {
    if ($Script:Sampling) { return }
    $Script:Sampling = $true
    $Script:LastSample = $null
    try { Take-SampleCore } catch {} finally { $Script:Sampling = $false }
    # Crochets Add-GBSampleHook : appeles apres chaque mesure faite (pas quand la fenetre est cachee hors jeu)
    if ($Script:LastSample) { Invoke-GBSampleHooks $Script:LastSample }
}

$Script:LastPurge = [DateTime]::MinValue
function Get-StandbyInfo([switch]$Fresh) {
    [void](Update-Perf -Force:$Fresh)
    if ((Test-Perf 'sbn') -and (Test-Perf 'free')) {
        $a = Get-PerfValue 'sbn'; $b = Get-PerfValue 'sbr'; $c = Get-PerfValue 'sbc'; $f = Get-PerfValue 'free'
        if ($null -ne $a -and $null -ne $f) { return @{ FreeMo = [int]([double]$f / 1MB); StandbyMo = [int](([double]$a + [double]$b + [double]$c) / 1MB) } }
    }
    try {
        $m = Get-CimInstance Win32_PerfFormattedData_PerfOS_Memory -ErrorAction Stop
        $standby = [double]$m.StandbyCacheNormalPriorityBytes + [double]$m.StandbyCacheReserveBytes + [double]$m.StandbyCacheCoreBytes
        return @{ FreeMo = [int]([double]$m.FreeAndZeroPageListBytes / 1MB); StandbyMo = [int]($standby / 1MB) }
    } catch { return $null }
}

function Invoke-StandbyPurge($reason) {
    $before = Get-StandbyInfo -Fresh
    $rc = -1
    try { $rc = [GBMem]::PurgeStandby() } catch {}
    $Script:LastPurge = Get-Date
    $Script:LastPurgeText = ""
    if ($rc -eq 0) {
        $after = Get-StandbyInfo -Fresh
        $msg = "Memoire en attente videe"
        if ($before -and $after) { $msg += " (" + $before.StandbyMo + " Mo -> " + $after.StandbyMo + " Mo, RAM libre : " + $after.FreeMo + " Mo)" }
        Log ($msg + " - " + $reason)
        Add-SessionEvent ($msg + " - " + $reason)
        $Script:LastPurgeText = (Get-Date -Format "HH:mm:ss") + " : " + $msg
        return $true
    } else {
        Log ("Vidage de la memoire en attente impossible (code " + ('0x{0:X8}' -f $rc) + ")")
        $Script:LastPurgeText = (Get-Date -Format "HH:mm:ss") + " : echec"
        return $false
    }
}

function Check-Standby {
    if ($Script:MeasureOnlySession) { return }
    if (((Get-Date) - $Script:LastPurge).TotalSeconds -lt [int]$Script:Config.PurgeInterval) { return }
    $i = Get-StandbyInfo
    if (-not $i) { return }
    if ($i.FreeMo -lt [int]$Script:Config.FreeMaxMo -and $i.StandbyMo -gt [int]$Script:Config.StandbyMinMo) {
        [void](Invoke-StandbyPurge ("automatique : cache > " + $Script:Config.StandbyMinMo + " Mo et memoire libre < " + $Script:Config.FreeMaxMo + " Mo"))
    }
}

function Take-SampleCore {
    # Fenetre cachee et pas de jeu : rien a afficher, on ne mesure pas (sauf surveillance permanente du cache)
    if (-not $Script:Boosted -and -not $form.Visible) {
        if ($Script:Config.StandbyClean -and $Script:Config.StandbyAlways) { Check-Standby }
        return
    }
    $s = Get-SystemSnapshot
    $g = $null; $x = @{}; $fps = $null; $fpsLow = $null
    if ($Script:Boosted) {
        $g = Get-GameStats
        $x = Get-ExtendedStats
        $f = Get-IntervalFps
        if ($f) { $fps = $f.Fps; $fpsLow = $f.Low }
    }
    $ping = Get-Ping
    # Mesure complete pour les crochets (socle) : FPS, 1 % bas, ping et etat du boost avec CPU / GPU / RAM
    $s.Fps = $fps; $s.FpsLow = $fpsLow; $s.Ping = $ping; $s.Boosted = [bool]$Script:Boosted; $s.Time = Get-Date; $Script:LastSample = $s
    $gCpu = $null; $gRam = $null
    if ($g) { $gCpu = $g.Cpu; $gRam = $g.RamMo }

    $txt = ""
    if ($null -ne $fps) { $txt = "FPS " + $fps + " (1% bas " + $fpsLow + ")  |  " }
    $txt += "CPU " + (Fmt $s.Cpu "%") + " (coeur max " + (Fmt $s.CpuMaxCore "%") + ")  |  GPU " + $s.GpuText
    if ($null -ne $x.VramGo) { $txt += ", VRAM " + $x.VramGo + " Go" }
    $txt += "  |  RAM " + (Fmt $s.RamPct "%") + " (" + (Fmt $s.RamUsedGo "") + "/" + (Fmt $s.RamTotalGo " Go") + ")  |  Ping " + (Fmt $ping " ms")
    if ($g) { $txt += "  |  Jeu : CPU " + (Fmt $gCpu "%") + ", RAM " + (Fmt $gRam " Mo") }
    if ($Script:Meters) {
        # Les jauges montrent deja CPU / GPU / RAM / ping : la ligne de texte ne garde que le jeu
        $t2 = ""
        if ($null -ne $fps) { $t2 = "FPS " + $fps + "  (1% bas " + $fpsLow + ")" }
        if ($g) { if ($t2) { $t2 += "     " }; $t2 += "Jeu : CPU " + (Fmt $gCpu "%") + ", RAM " + (Fmt $gRam " Mo") }
        if (-not $t2) { if ($Script:Boosted) { $t2 = "Jeu : mesure en cours..." } else { $t2 = "Les FPS et la charge du jeu s'affichent ici pendant le boost." } }
        $txt = $t2
    }
    $lblStats.Text = $txt
    if ($Script:Boosted -and $Script:Config.Overlay) { try { Update-GBOverlay $fps $fpsLow $s $ping } catch {} }
    $Script:LastGpuDetail = $s.GpuDetail   # (tiroir des applis sur les cartes graphiques)
    if ($Script:Meters) {
        try {
            $Script:Meters.Cpu.SetValue([float](0 + $s.Cpu), (Fmt $s.Cpu " %"))
            if ($null -ne $s.CpuMaxCore) { $Script:Meters.Cpu.Sub = "coeur max " + $s.CpuMaxCore + " %" }
            if ($Script:MeterHasD -or -not $Script:MeterHasI) {
                $gTxt = Fmt $s.DgpuU " %"; if ($s.DgpuSleep) { $gTxt = "veille" }
                $Script:Meters.Dgpu.SetValue([float](0 + $s.DgpuU), $gTxt)
                if ($Script:DgpuSubBase -and $null -ne $x.VramGo) {
                    $vt = "" + $x.VramGo; if ($Script:MainGpu.VramGo) { $vt += "/" + $Script:MainGpu.VramGo }
                    $Script:Meters.Dgpu.Sub = $Script:DgpuSubBase + " | " + $vt + " Go"
                }
            }
            if ($Script:MeterHasI) { $Script:Meters.Igpu.SetValue([float](0 + $s.IgpuU), (Fmt $s.IgpuU " %")) }
            $Script:Meters.Ram.SetValue([float](0 + $s.RamPct), (Fmt $s.RamPct " %"))
            if ($null -ne $s.RamUsedGo -and $null -ne $s.RamTotalGo) { $Script:Meters.Ram.Sub = "" + $s.RamUsedGo + " / " + $s.RamTotalGo + " Go" }
            $pp = 0; if ($null -ne $ping) { $pp = [math]::Min(100, [double]$ping / 1.5) }
            $Script:Meters.Ping.SetValue([float]$pp, (Fmt $ping " ms"))
        } catch {}
    }

    if (-not $Script:Boosted) {
        if ($Script:Config.StandbyClean -and $Script:Config.StandbyAlways) { Check-Standby }   # surveillance permanente (comme ISLC)
        return
    }

    # Sur quelle carte tourne le jeu ? (alerte si c'est la puce integree alors qu'une carte dediee existe)
    $jeuGpu = $null; $gameOnIgpu = $false; $gameIgpuName = ""
    if ($s.GpuDetail -and $s.GpuDetail.Procs.Count -gt 0) {
        $gids = @{}; foreach ($gp in Get-GameProcesses) { $gids[[string]$gp.Id] = $true }
        $byAd = @{}
        foreach ($kv in $s.GpuDetail.Procs.GetEnumerator()) {
            $parts = $kv.Key.Split('|')
            if ($gids.ContainsKey($parts[1])) { $byAd[$parts[0]] = [double]$byAd[$parts[0]] + $kv.Value }
        }
        if ($byAd.Count -gt 0) {
            $best = $byAd.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 1
            $gi = Get-GpuInfoByLuid $best.Key
            $jeuGpu = $gi.Short
            if ($gi.Kind -eq 'integree' -and $Script:GpuHybrid -and $best.Value -ge 5) { $gameOnIgpu = $true; $gameIgpuName = $gi.Short }
        }
    }

    $row = [ordered]@{ Heure = (Get-Date -Format "HH:mm:ss"); T = [int]((Get-Date) - $Script:SessionStart).TotalSeconds;
                       Fps = $fps; FpsLow = $fpsLow; Cpu = $s.Cpu; CpuMaxCore = $s.CpuMaxCore; CpuPerf = $x.CpuPerf;
                       Gpu = $s.Gpu; Igpu = $s.Igpu; VramGo = $x.VramGo; Ram = $s.RamPct; RamGo = $s.RamUsedGo; CommitPct = $x.CommitPct;
                       HardFaults = $x.HardFaults; DiskBusy = $x.DiskBusy; JeuCpu = $gCpu; JeuRam = $gRam; JeuGpu = $jeuGpu; Ping = $ping }
    [void]$Script:Samples.Add($row)
    if ($Script:SessionCsv) {
        $vals = @($row.Values | ForEach-Object { if ($null -eq $_) { "" } else { ([string]$_).Replace('.', $Script:CsvDec) } })
        try { Add-Content -LiteralPath $Script:SessionCsv -Value ($vals -join $Script:CsvSep) -Encoding UTF8 } catch {}
    }

    $Script:SampleCount++
    if ($Script:SampleCount % 6 -eq 1) { Sample-TopProcesses }        # programmes gourmands toutes les 30 s
    if ($Script:SampleCount % 6 -eq 0) { Log ("Perf : " + $txt) }     # une ligne toutes les 30 s

    Check-Alert 'cpu'  ($null -ne $s.Cpu -and $s.Cpu -ge 95)       ("processeur a " + $s.Cpu + "% (il limite les performances)") "Processeur revenu a la normale"
    Check-Alert 'ram'  ($null -ne $s.RamPct -and $s.RamPct -ge 90) ("memoire pleine a " + $s.RamPct + "% (risque de saccades)") "Memoire revenue a la normale"
    Check-Alert 'ping' ($null -ne $ping -and $ping -ge 150)        ("ping eleve : " + $ping + " ms") "Ping revenu a la normale"
    Check-Alert 'net'  ($null -eq $ping)                            "pas de reponse au ping (connexion coupee ou ping bloque)" "Connexion internet retablie"
    if ($null -ne $x.VramGo -and $Script:VramTotalGo) {
        Check-Alert 'vram' ($x.VramGo -ge 0.92 * $Script:VramTotalGo) ("memoire video presque pleine : " + $x.VramGo + "/" + $Script:VramTotalGo + " Go (baisse la qualite des textures)") "Memoire video revenue a la normale"
    }
    if ($null -ne $x.HardFaults) {
        $pgWhy = "RAM insuffisante, saccades probables"
        if ($null -ne $s.RamPct -and $s.RamPct -lt 80) { $pgWhy = "la RAM n'est pas pleine : chargement du jeu ou memoire videe recemment, saccades possibles" }
        Check-Alert 'paging' ($x.HardFaults -ge 2000) ("Windows lit beaucoup sur le disque (" + $x.HardFaults + " pages/s) : " + $pgWhy) "Lectures disque revenues a la normale"
    }
    $mainName = "la carte graphique dediee"; if ($Script:MainGpu) { $mainName = $Script:MainGpu.Short }
    Check-Alert 'gameigpu' $gameOnIgpu ("le jeu tourne sur la puce integree " + $gameIgpuName + " au lieu de " + $mainName + " ! Coche 'Forcer la carte puissante' puis relance le jeu (ou regle-le dans le panneau NVIDIA / AMD).") "Le jeu utilise maintenant la carte graphique dediee"
    if ($Script:Config.StandbyClean) { Check-Standby }
}

function Log-Snapshot($title) {
    $s = Get-SystemSnapshot
    Log ($title + " -> CPU " + (Fmt $s.Cpu "%") + ", GPU " + $s.GpuText + ", RAM " + (Fmt $s.RamUsedGo "") + "/" + (Fmt $s.RamTotalGo " Go") +
         " (" + (Fmt $s.RamPct "%") + "), " + $s.Procs + " processus")
    return $s
}

function Get-Stat($key) {
    $vals = @($Script:Samples | ForEach-Object { $_[$key] } | Where-Object { $null -ne $_ })
    if ($vals.Count -eq 0) { return $null }
    $m = $vals | Measure-Object -Average -Maximum -Minimum
    return @{ Avg = [math]::Round($m.Average, 1); Max = $m.Maximum; Min = $m.Minimum; Values = $vals }
}

function Pct-Above($st, $limit) {
    if (-not $st) { return 0 }
    $n = @($st.Values | Where-Object { $_ -ge $limit }).Count
    return [int]($n * 100 / $st.Values.Count)
}

function Get-SessionIndex {
    $list = @()
    if (Test-Path -LiteralPath $SessionsFile) {
        try {
            $j = Get-Content -LiteralPath $SessionsFile -Raw | ConvertFrom-Json
            foreach ($e in $j) { if ($e) { $list += $e } }
        } catch {}
    }
    return $list
}

function Add-SessionIndex($entry) {
    $list = @(Get-SessionIndex)
    $list = @($list + [pscustomobject]$entry)
    if ($list.Count -gt 100) { $list = @($list[($list.Count - 100)..($list.Count - 1)]) }
    try { ConvertTo-Json -InputObject $list -Depth 4 | Set-Content -LiteralPath $SessionsFile -Encoding UTF8 } catch {}
}

function Get-StatValue($st, $k) { if ($st) { return $st[$k] } return $null }
function AvgK($rows, $k, $dec = 0) {
    $vals = @($rows | ForEach-Object { $_[$k] } | Where-Object { $null -ne $_ })
    if ($vals.Count -eq 0) { return "-" }
    return [string][math]::Round(($vals | Measure-Object -Average).Average, $dec)
}
function MinK($rows, $k) {
    $vals = @($rows | ForEach-Object { $_[$k] } | Where-Object { $null -ne $_ })
    if ($vals.Count -eq 0) { return "-" }
    return [string]($vals | Measure-Object -Minimum).Minimum
}
function MaxK($rows, $k) {
    $vals = @($rows | ForEach-Object { $_[$k] } | Where-Object { $null -ne $_ })
    if ($vals.Count -eq 0) { return "-" }
    return [string]($vals | Measure-Object -Maximum).Maximum
}
function Pct-Change($a, $b) {
    if (-not $a -or $null -eq $b) { return "n/d" }
    $d = [math]::Round(([double]$b - [double]$a) * 100.0 / [double]$a, 1)
    if ($d -ge 0) { return "+" + $d + " %" }
    return "" + $d + " %"
}

function Write-SessionSummary {
    if ($Script:Samples.Count -lt 2) { return }
    $dur = (Get-Date) - $Script:SessionStart
    $durMin = [math]::Round($dur.TotalMinutes, 1)
    $fs = Get-FrameStats
    $cpu = Get-Stat 'Cpu'; $core = Get-Stat 'CpuMaxCore'; $perf = Get-Stat 'CpuPerf'; $gpu = Get-Stat 'Gpu'; $vram = Get-Stat 'VramGo'
    $ram = Get-Stat 'Ram'; $commit = Get-Stat 'CommitPct'; $hf = Get-Stat 'HardFaults'; $disk = Get-Stat 'DiskBusy'
    $jc = Get-Stat 'JeuCpu'; $jr = Get-Stat 'JeuRam'; $png = Get-Stat 'Ping'

    $L = New-Object System.Collections.ArrayList
    function A($t) { [void]$L.Add($t) }
    function Line($label, $st, $unit) {
        if (-not $st) { return ("  " + $label.PadRight(20) + ": n/d") }
        return ("  " + $label.PadRight(20) + ": moyenne " + $st.Avg + $unit + "  |  min " + $st.Min + $unit + "  |  max " + $st.Max + $unit)
    }

    A ""
    A "================ RAPPORT DE SESSION ================"
    A ("  Jeu                 : " + $Script:SessionGame)
    A ("  Mode                : " + $Script:SessionMode)
    A ("  Debut               : " + $Script:SessionStart.ToString("dd/MM/yyyy HH:mm:ss"))
    A ("  Duree               : " + [math]::Floor($dur.TotalHours) + "h " + $dur.Minutes.ToString("00") + "min " + $dur.Seconds.ToString("00") + "s (" + $Script:Samples.Count + " mesures)")
    A ("  Options actives     : " + $Script:SessionOptions)
    if ($Script:BoostBilan) { A ("  Effet du boost      : " + $Script:BoostBilan) }
    A ""
    A "  -- IMAGES PAR SECONDE --"
    $spm = $null
    if ($fs) {
        if ($durMin -gt 0) { $spm = [math]::Round($fs.Stutters / $durMin, 1) }
        A ("  FPS moyen           : " + $fs.Fps)
        A ("  1% bas / 0,1% bas   : " + $fs.Low1 + " / " + $fs.Low01 + " FPS")
        A ("  Temps par image     : moyenne " + $fs.AvgFt + " ms, mediane " + $fs.MedianFt + " ms, pire " + $fs.Worst + " ms")
        A ("  Saccades            : " + $fs.Stutters + " (" + $spm + " par minute, images > " + $fs.Threshold + " ms), dont " + $fs.Freezes + " gel(s) > 100 ms")
        A ("  Images mesurees     : " + $fs.Frames)
    } elseif (-not $Script:Config.FpsMeasure) { A "  Mesure des FPS desactivee" }
    elseif (-not $Script:PMPath) { A "  PresentMon introuvable : FPS non mesures" }
    else { A "  Pas de FPS mesures (jeu non detecte, session trop courte, ou jeu qui ne passe pas par DirectX/Vulkan standard)" }
    A ""
    A "  -- MATERIEL --"
    A (Line "Processeur (total)" $cpu "%")
    A (Line "Coeur le plus charge" $core "%")
    A (Line "Frequence processeur" $perf "% de la base")
    $mainShort = "Carte graphique"; if ($Script:MainGpu) { $mainShort = $Script:MainGpu.Short }
    A (Line $mainShort $gpu "%")
    $igp = Get-Stat 'Igpu'
    if ($igp -and $Script:IGpu) { A (Line ($Script:IGpu.Short + " (integree)") $igp "%") }
    $jg = @($Script:Samples | ForEach-Object { $_['JeuGpu'] } | Where-Object { $_ })
    if ($jg.Count -gt 0) {
        $grp = @($jg | Group-Object | Sort-Object Count -Descending)
        A ("  Le jeu a tourne sur : " + (($grp | ForEach-Object { $_.Name + " (" + [int]($_.Count * 100 / $jg.Count) + " % du temps)" }) -join ", "))
    }
    A (Line "Memoire video" $vram " Go")
    if ($Script:VramTotalGo) { A ("  Memoire video totale: " + $Script:VramTotalGo + " Go") }
    A (Line "RAM" $ram "%")
    A (Line "Memoire engagee" $commit "%")
    A (Line "Lectures pagefile" $hf "/s")
    A (Line "Disque occupe" $disk "%")
    A (Line "Jeu - CPU" $jc "%")
    A (Line "Jeu - RAM" $jr " Mo")
    A (Line "Ping" $png " ms")

    # ---- Analyse
    A ""
    A "  -- ANALYSE --"
    $v = New-Object System.Collections.ArrayList
    if ($Script:GpuHybrid -and $Script:IGpu -and $jg.Count -gt 0) {
        $onIg = @($jg | Where-Object { $_ -eq $Script:IGpu.Short }).Count
        if ($onIg * 100 / $jg.Count -ge 20) {
            [void]$v.Add("PROBLEME : le jeu a tourne sur la puce integree " + $Script:IGpu.Short + " (" + [int]($onIg * 100 / $jg.Count) + " % du temps) au lieu de " + $Script:MainGpu.Short + ". Coche 'Forcer la carte puissante' dans GameBoost, ou choisis la carte dans Parametres > Affichage > Graphiques, puis relance le jeu. Gain enorme attendu.")
        }
    }
    $coreHigh = Pct-Above $core 90
    $gpuHigh = Pct-Above $gpu 95
    $gpuAvg = Get-StatValue $gpu 'Avg'
    if ($coreHigh -ge 30 -and ($null -eq $gpuAvg -or $gpuAvg -lt 85)) {
        [void]$v.Add("Limite PROCESSEUR : un coeur est au-dessus de 90 % pendant " + $coreHigh + " % du temps alors que la carte graphique n'est pas a fond. Baisse ce qui charge le CPU (distance d'affichage, foule/PNJ, physique, ombres). Monter la qualite graphique ou la resolution ne coutera presque rien.")
    }
    if ($gpuHigh -ge 50) {
        [void]$v.Add("Limite CARTE GRAPHIQUE (normal en jeu) : a fond " + $gpuHigh + " % du temps. Pour plus de FPS : DLSS/FSR/XeSS en mode Qualite, baisser ombres, reflets, eclairage volumetrique.")
    } elseif ($null -ne $gpuAvg -and $gpuAvg -lt 70 -and $coreHigh -lt 30) {
        [void]$v.Add("Ni le processeur ni la carte graphique ne sont a fond : les FPS sont probablement plafonnes (V-Sync, limite d'images du jeu ou du pilote). Normal si tu as mis une limite expres.")
    }
    if ($vram -and $Script:VramTotalGo -and $vram.Max -ge 0.9 * $Script:VramTotalGo) {
        [void]$v.Add("Memoire video presque pleine (max " + $vram.Max + " / " + $Script:VramTotalGo + " Go) : baisse la qualite des textures d'un cran, c'est une cause classique de saccades.")
    }
    $ramHigh = Pct-Above $ram 85; $comHigh = Pct-Above $commit 85
    if ($ramHigh -ge 20 -or $comHigh -ge 20) {
        [void]$v.Add("RAM saturee (au-dessus de 85 % pendant " + [math]::Max($ramHigh, $comHigh) + " % du temps) : ferme plus d'applis (surtout le navigateur) ou ajoute de la RAM.")
    }
    if ($hf -and ($hf.Avg -ge 300 -or $hf.Max -ge 3000)) {
        if ($ram -and $ram.Avg -lt 70) {
            [void]$v.Add("Beaucoup de lectures disque (moyenne " + $hf.Avg + "/s, max " + $hf.Max + "/s) alors que la RAM n'est pas pleine (" + $ram.Avg + " % en moyenne) : surtout pendant les chargements. Normal en debut de partie ; si ca dure, verifie l'espace libre du disque du jeu.")
        } else {
            [void]$v.Add("Beaucoup de lectures du fichier d'echange (moyenne " + $hf.Avg + "/s, max " + $hf.Max + "/s) : la RAM ne suffit pas, Windows va chercher sur le disque, ce qui donne des saccades.")
        }
    }
    $diskHigh = Pct-Above $disk 80
    if ($diskHigh -ge 15) {
        [void]$v.Add("Disque tres occupe " + $diskHigh + " % du temps : verifie qu'aucun telechargement/mise a jour ne tourne, et installe le jeu sur un SSD si possible.")
    }
    $perfLoad = @($Script:Samples | Where-Object { $null -ne $_['CpuPerf'] -and $null -ne $_['Cpu'] -and $_['Cpu'] -ge 40 } | ForEach-Object { $_['CpuPerf'] })
    if ($perfLoad.Count -ge 6) {
        $pa = ($perfLoad | Measure-Object -Average).Average
        if ($pa -lt 85) { [void]$v.Add("Sous charge, le processeur ne tourne qu'a " + [int]$pa + " % de sa frequence de base : surchauffe (poussiere, ventirad, pate thermique) ou limite d'energie (portable sur batterie, mode economie).") }
    }
    if ($fs) {
        if ($fs.Low1 -lt 0.6 * $fs.Fps) {
            $cap = [int]([math]::Floor($fs.Fps * 0.9 / 5) * 5)
            [void]$v.Add("Images irregulieres : le 1% bas (" + $fs.Low1 + ") est loin de la moyenne (" + $fs.Fps + "). Limiter les FPS un peu en dessous de ta moyenne (ex : " + $cap + ") dans le jeu ou le pilote rend souvent le jeu plus fluide.")
        }
        if ($spm -and $spm -ge 2) { [void]$v.Add("Saccades frequentes (" + $spm + " par minute) : regarde les evenements et les programmes gourmands ci-dessous pour trouver la cause.") }
    }
    if ($png -and ((Pct-Above $png 100) -ge 10 -or ($png.Max - $png.Min) -ge 80)) { [void]$v.Add("Ping instable ou eleve : prefere un cable Ethernet au Wi-Fi et coupe les telechargements sur le reseau.") }
    if (@($Script:Samples | Where-Object { $null -eq $_['Ping'] }).Count -gt 0 -and $png) { [void]$v.Add("Quelques pertes de connexion pendant la session.") }
    if ($v.Count -eq 0) { [void]$v.Add("Rien d'anormal : le PC a tenu sans probleme pendant la session.") }
    foreach ($item in $v) { A ("  - " + $item) }

    # ---- Comparaison avec la session precedente sur le meme jeu
    $prev = $null
    foreach ($e in (Get-SessionIndex)) { if ($e.Jeu -eq $Script:SessionGame -and $e.Fps) { $prev = $e } }
    if ($prev -and $fs) {
        A ""
        A ("  -- COMPARAISON avec ta session du " + $prev.Date + " (" + $prev.Mode + ") --")
        A ("  FPS moyen    : " + $prev.Fps + " -> " + $fs.Fps + " (" + (Pct-Change $prev.Fps $fs.Fps) + ")")
        A ("  1% bas       : " + $prev.Low1 + " -> " + $fs.Low1 + " (" + (Pct-Change $prev.Low1 $fs.Low1) + ")")
        A ("  Saccades/min : " + $prev.SaccadesMin + " -> " + $spm)
    }
    $endShort = $L.Count

    # ---- Chronologie
    A ""
    A "  -- CHRONOLOGIE --"
    $totalSec = [math]::Max(1, [int]$dur.TotalSeconds)
    $bucket = 60
    while (($totalSec / $bucket) -gt 40) { $bucket += 60 }
    $groups = @{}
    foreach ($r in $Script:Samples) {
        $b = [int][math]::Floor([double]$r['T'] / $bucket)
        if (-not $groups.ContainsKey($b)) { $groups[$b] = New-Object System.Collections.ArrayList }
        [void]$groups[$b].Add($r)
    }
    foreach ($b in ($groups.Keys | Sort-Object)) {
        $rows = $groups[$b]
        $t0 = [TimeSpan]::FromSeconds($b * $bucket); $t1 = [TimeSpan]::FromSeconds(($b + 1) * $bucket)
        $lab = "" + [int][math]::Floor($t0.TotalHours) + "h" + $t0.Minutes.ToString("00") + "-" + [int][math]::Floor($t1.TotalHours) + "h" + $t1.Minutes.ToString("00")
        A ("  " + $lab.PadRight(11) + " | FPS " + (AvgK $rows 'Fps') + " (1% " + (MinK $rows 'FpsLow') + ")" +
           " | CPU " + (AvgK $rows 'Cpu') + "% coeur " + (AvgK $rows 'CpuMaxCore') + "% | GPU " + (AvgK $rows 'Gpu') + "% | VRAM " + (MaxK $rows 'VramGo') +
           " | RAM " + (AvgK $rows 'Ram') + "% | disque " + (AvgK $rows 'DiskBusy') + "% | ping " + (AvgK $rows 'Ping'))
    }

    # ---- Programmes gourmands
    if ($Script:ProcStats.Count -gt 0) {
        A ""
        A "  -- PROGRAMMES LES PLUS GOURMANDS PENDANT LE JEU --"
        $gameNames = Get-GameNames
        $self = (Get-Process -Id $PID).ProcessName
        $top = @($Script:ProcStats.GetEnumerator() | Where-Object { $_.Key -ne 'Idle' } | ForEach-Object {
                    $n = [math]::Max(1, $_.Value.N)
                    [pscustomobject]@{ Name = $_.Key; Avg = $_.Value.Sum / $n; Max = $_.Value.Max; RamMo = $_.Value.RamMax / 1MB } } |
                 Sort-Object Avg -Descending | Select-Object -First 12)
        foreach ($t in $top) {
            $tag = ""
            if ($gameNames -contains $t.Name.ToLower()) { $tag = " (jeu)" } elseif ($t.Name -eq $self) { $tag = " (GameBoost)" } elseif ($t.Name -like 'discord*') { $tag = " (Discord)" }
            A ("  " + ($t.Name + $tag).PadRight(34) + ("CPU moy {0,5:N1} %  max {1,5:N1} %  RAM {2,6:N0} Mo" -f $t.Avg, $t.Max, $t.RamMo))
        }
        $topRam = @($Script:ProcStats.GetEnumerator() | Sort-Object { $_.Value.RamMax } -Descending | Select-Object -First 6 |
                    ForEach-Object { $_.Key + " " + [int]($_.Value.RamMax / 1MB) + " Mo" })
        A ("  Plus gros en RAM : " + ($topRam -join ", "))
    }

    # ---- Evenements
    if ($Script:SessionEvents.Count -gt 0) {
        A ""
        A "  -- EVENEMENTS --"
        foreach ($e in $Script:SessionEvents) { A ("  " + $e) }
    }
    A ""
    A ("  Mesures detaillees (Excel) : " + $Script:SessionCsv)
    A "===================================================="
    A ""

    # Fichier rapport de la session + log du jour + apercu dans la fenetre
    $rf = Join-Path $LogDir ("rapport_session_" + $Script:SessionStart.ToString("yyyy-MM-dd_HH-mm-ss") + ".txt")
    try { Set-Content -LiteralPath $rf -Value ($L -join "`r`n") -Encoding UTF8 } catch {}
    try { Add-Content -LiteralPath $Script:LogFile -Value ($L -join "`r`n") -Encoding UTF8 } catch {}
    for ($i = 0; $i -lt $endShort; $i++) { $txtLog.AppendText($L[$i] + "`r`n") }
    $txtLog.AppendText("  (rapport complet avec chronologie et programmes gourmands : bouton 'Ouvrir les logs')`r`n")

    # Historique des sessions (pour comparer)
    if ($durMin -ge 1) {
        Add-SessionIndex ([ordered]@{
            Date = $Script:SessionStart.ToString("yyyy-MM-dd HH:mm"); Jeu = $Script:SessionGame; Mode = $Script:SessionModeShort; DureeMin = $durMin
            Fps = (Get-StatValue $fs 'Fps'); Low1 = (Get-StatValue $fs 'Low1'); Low01 = (Get-StatValue $fs 'Low01'); SaccadesMin = $spm
            Cpu = (Get-StatValue $cpu 'Avg'); CoeurMax = (Get-StatValue $core 'Avg'); Gpu = (Get-StatValue $gpu 'Avg'); VramMax = (Get-StatValue $vram 'Max'); Ram = (Get-StatValue $ram 'Avg')
            Ping = (Get-StatValue $png 'Avg'); Options = $Script:SessionOptions })
    }
    foreach ($fpf in $Script:FpsFiles) { Remove-Item -LiteralPath $fpf -ErrorAction SilentlyContinue }   # fichiers bruts PresentMon (tres gros)
    $Script:FpsFiles = @()
}

function Get-OptionsText {
    $map = [ordered]@{ AutoMode = 'Mode auto'; CloseApps = 'Fermer applis'; ForceClose = 'Fermeture forcee'; PauseServices = 'Services en pause';
                       PowerPlan = 'Plan perf max'; PlanTuning = 'Plan GameBoost USB/PCIe/CPU'; GamePriority = 'Priorite CPU jeu'; CleanRam = 'Liberer RAM';
                       KnownGames = 'Jeux populaires'; GpuPriority = 'Priorite GPU'; GpuPreference = 'Carte graphique forcee'; NetworkTweak = 'Nagle off';
                       MouseAccelOff = 'Acceleration souris off'; GameDvrOff = 'Game DVR off'; LowerBackground = 'Priorite basse launchers';
                       StandbyClean = 'Anti-saccades RAM'; RestorePoint = 'Point de restauration'; FpsMeasure = 'Mesure FPS'; MeasureOnly = 'Mode comparaison' }
    $on = @(); $off = @()
    foreach ($k in $map.Keys) { if ($Script:Config[$k]) { $on += $map[$k] } else { $off += $map[$k] } }
    if ($on.Count -eq 0) { $on = @('aucune') }
    if ($off.Count -eq 0) { $off = @('aucune') }
    return @(($on -join ", "), ($off -join ", "))
}

function Start-Session {
    $Script:Samples.Clear()
    $Script:PrevGameCpu = @{}
    $Script:PrevSampleTime = $null
    $Script:SampleCount = 0
    $Script:Alerts = @{}
    $Script:AlertCounts = @{}
    $Script:SessionEvents = New-Object System.Collections.ArrayList
    $Script:FrameTimes.Clear()
    $Script:FpsFiles = @()
    $Script:PM = $null; $Script:PMFile = $null; $Script:PMPos = 0; $Script:PMCols = $null; $Script:PMPending = ""; $Script:FpsReader = $null
    $Script:ProcPrev = @{}; $Script:ProcPrevTime = $null; $Script:ProcStats = @{}; $Script:ProcSamples = 0
    $Script:SessionOptions = (Get-OptionsText)[0]
    if ($Script:MeasureOnlySession) { $Script:SessionMode = "MESURE SEULE (aucune optimisation, pour comparer)"; $Script:SessionModeShort = "MESURE" }
    else { $Script:SessionMode = "BOOST (optimisations actives)"; $Script:SessionModeShort = "BOOST" }
    $Script:SessionStart = Get-Date
    $g = @(Get-GameProcesses | Select-Object -ExpandProperty ProcessName -Unique)
    if ($g.Count -gt 0) { $Script:SessionGame = (($g | ForEach-Object { Get-GameLabel $_ }) -join ", ") } else { $Script:SessionGame = "(boost manuel, jeu pas encore lance)" }
    $Script:SessionCsv = Join-Path $LogDir ("session_" + (Get-Date -Format "yyyy-MM-dd_HH-mm-ss") + ".csv")
    $header = "Heure;Temps (s);FPS;FPS 1% bas;CPU %;Coeur max %;Frequence CPU %;GPU %;Puce integree %;VRAM (Go);RAM %;RAM utilisee (Go);Memoire engagee %;Lectures pagefile/s;Disque occupe %;Jeu CPU %;Jeu RAM (Mo);GPU du jeu;Ping (ms)"
    try { Set-Content -LiteralPath $Script:SessionCsv -Value $header.Replace(';', $Script:CsvSep) -Encoding UTF8 } catch {}
}


