function Update-BoostButton {
    if ($Script:Boosted) {
        if ($Script:MeasureOnlySession) {
            $btnBoost.Text = "ARRETER LA MESURE"; $btnBoost.BackColor = $cYellow; $btnBoost.ForeColor = [System.Drawing.Color]::Black
            $lblStatus.Text = "Mesure SANS optimisation en cours (mode comparaison)"; $lblStatus.ForeColor = $cYellow
            $tray.Text = "GameBoost - Mesure en cours"
        } else {
            $btnBoost.Text = "ARRETER LE BOOST"; $btnBoost.BackColor = $cRed; $btnBoost.ForeColor = [System.Drawing.Color]::White
            $lblStatus.Text = "Mode Jeu ACTIF"; $lblStatus.ForeColor = $cGreen
            $tray.Text = "GameBoost - Mode Jeu actif"
        }
    } else {
        $btnBoost.Text = "BOOST"; $btnBoost.BackColor = $cGreen; $btnBoost.ForeColor = [System.Drawing.Color]::Black
        if ($Script:Config.MeasureOnly) { $btnBoost.Text = "MESURER" ; $btnBoost.BackColor = $cYellow }
        if ($Script:Config.AutoMode -and $Script:ManualStop) {
            $lblStatus.Text = "Boost arrete (pas de relance tant que le jeu est ouvert)"
        } elseif ($Script:Config.AutoMode -and ($Script:Config.Games.Count -gt 0 -or $Script:Config.KnownGames)) {
            $lblStatus.Text = "En attente d'un jeu... (mode auto)"
        } else {
            $lblStatus.Text = "Mode Jeu inactif"
        }
        $lblStatus.ForeColor = $cMuted
        $tray.Text = "GameBoost"
    }
    # Balayage lumineux une seule fois, au moment ou le boost s'active
    # (lance quand l'interface est de nouveau libre : le boost bloque l'affichage ~1 s, sinon l'animation serait sautee)
    if ($Script:UiOK -and $Script:Boosted -and -not $Script:UiBoostShown) {
        try { if ($form.IsHandleCreated) { [void]$form.BeginInvoke([System.Action]{ try { $btnBoost.Sweep() } catch {} }) } } catch {}
    }
    $Script:UiBoostShown = [bool]$Script:Boosted
}

function Get-GameNames {
    $names = @($Script:Config.Games | ForEach-Object { $_.ToLower() })
    if ($Script:Config.KnownGames) { $names += @($KnownGames.Keys) }
    return $names
}

$Script:GPCache = $null; $Script:GPCacheT = 0
function Get-GameProcesses {
    # Un seul parcours des processus par seconde (detection, priorite, FPS et mesures se partagent le resultat)
    $now = [Environment]::TickCount
    if ($null -ne $Script:GPCache -and [math]::Abs($now - $Script:GPCacheT) -lt 1000) { return $Script:GPCache }
    $names = Get-GameNames
    $res = @()
    if ($names.Count -gt 0) {
        $set = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($n in $names) { [void]$set.Add([string]$n) }
        $res = @(foreach ($p in [System.Diagnostics.Process]::GetProcesses()) { if ($set.Contains($p.ProcessName)) { $p } else { $p.Dispose() } })
    }
    $Script:GPCache = $res; $Script:GPCacheT = $now
    return $res
}

function Get-GameLabel($procName) {
    $k = $procName.ToLower()
    if ($KnownGames.Contains($k)) { return $KnownGames[$k] }
    return $procName
}

# --- Type de PC (fixe / portable) -------------------------------------------
$Script:IsLaptop = $false
try {
    $chassis = @((Get-CimInstance Win32_SystemEnclosure -ErrorAction Stop).ChassisTypes)
    if ($chassis | Where-Object { @(8,9,10,11,12,14,18,21,30,31,32) -contains $_ }) { $Script:IsLaptop = $true }
} catch {}
try { if (Get-CimInstance Win32_Battery -ErrorAction Stop) { $Script:IsLaptop = $true } } catch {}

# --- Modifications du registre avec sauvegarde -------------------------------
function Read-RegValue($path, $name, $defaultType = 'DWord') {
    $existed = $false; $old = $null; $oldType = $defaultType
    try {
        $item = Get-ItemProperty -Path $path -Name $name -ErrorAction Stop
        $existed = $true; $old = $item.$name
        try { $oldType = (Get-Item -Path $path).GetValueKind($name).ToString() } catch {}
    } catch {}
    return [ordered]@{ Path = $path; Name = $name; Existed = $existed; Value = $old; Type = $oldType }
}

function Set-RegBackup($path, $name, $value, $type) {
    # Sauvegarde la valeur actuelle dans l'etat, puis ecrit la nouvelle
    $Script:State.Registry += (Read-RegValue $path $name $type)
    if (-not (Test-Path -LiteralPath $path)) { New-Item -Path $path -Force | Out-Null }
    Set-ItemProperty -Path $path -Name $name -Value $value -Type $type -ErrorAction Stop
}

function Restore-Registry($entries) {
    $list = @($entries)
    [array]::Reverse($list)
    $n = 0
    foreach ($e in $list) {
        if (-not $e) { continue }
        try {
            if ($e.Existed) { Set-ItemProperty -Path $e.Path -Name $e.Name -Value $e.Value -Type $e.Type -ErrorAction Stop }
            else { Remove-ItemProperty -Path $e.Path -Name $e.Name -ErrorAction SilentlyContinue }
            $n++
        } catch {}
    }
    return $n
}

function Apply-MouseSettings {
    # Recharge les reglages souris du registre sans redemarrer la session
    try {
        $m = Get-ItemProperty -Path 'HKCU:\Control Panel\Mouse'
        $arr = [int[]]@([int]$m.MouseThreshold1, [int]$m.MouseThreshold2, [int]$m.MouseSpeed)
        [void][GBNative]::SystemParametersInfo(0x0004, 0, $arr, 0x03)   # SPI_SETMOUSE
    } catch {}
}

function Get-ActiveScheme {
    $out = powercfg /getactivescheme 2>$null
    if ($out -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') { return $Matches[1] }
    return $null
}

function Get-PerformanceScheme {
    $list = (powercfg /list 2>$null) -join "`n"
    # 0) Plan deja cree par GameBoost ?
    if ($Script:IsLaptop -and $list -match '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c') { return '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c' }
    if ($Script:Config.PerfScheme -and $list -match [regex]::Escape($Script:Config.PerfScheme)) { return $Script:Config.PerfScheme }
    # 1) Plan "Performances optimales" (Ultimate) deja present ?
    foreach ($line in ($list -split "`n")) {
        if ($line -match '([0-9a-fA-F-]{36})' -and ($line -match 'Ultimate|optimales|ultimes|GameBoost')) { return $Matches[1] }
    }
    # 2) On essaie de le creer
    $dup = powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>$null
    if (($dup -join ' ') -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})') {
        $Script:Config.PerfScheme = $Matches[1]; Save-Config; return $Matches[1]
    }
    # 3) Sinon "Performances elevees"
    if ($list -match '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c') { return '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c' }
    return $null
}

function Set-GameBoostPlanTuning($guid) {
    # Uniquement sur le plan cree par GameBoost (il est supprime par TOUT RESTAURER)
    powercfg /changename $guid "GameBoost" "Plan de jeu cree par GameBoost" 2>$null | Out-Null
    $settings = @(
        @('2a737441-1930-4402-8d77-b2bebba308a3', '48e6b7a6-50f5-4782-a5d4-53bb8f07e226', 0),   # USB : pas de mise en veille selective
        @('501a4d13-42af-4429-9fd1-a8218c268e20', 'ee12f906-d277-404b-b6da-e5fa1a576df5', 0),   # PCI Express : pas d'economie d'energie
        @('54533251-82be-4824-96c1-47b60b740d00', '893dee8e-2bef-41e0-89c6-b55d0929964c', 100), # Processeur : etat minimal 100 %
        @('54533251-82be-4824-96c1-47b60b740d00', 'bc5038f7-23e0-4960-96da-33abaf5935ec', 100), # Processeur : etat maximal 100 %
        @('0012ee47-9041-4b5d-9b77-535fba8b1442', '6738e2c4-e8a5-4a42-b16a-e040e769756e', 0)    # Disque : jamais en veille
    )
    foreach ($st in $settings) { powercfg /setacvalueindex $guid $st[0] $st[1] $st[2] 2>$null | Out-Null }
    powercfg /setactive $guid 2>$null | Out-Null
}

# --- Carte graphique haute performance pour les jeux (PC a 2 GPU) ------------
$Script:GpuPrefPids = New-Object 'System.Collections.Generic.HashSet[int]'
function Get-ProcessPath($p) {
    $path = $null
    try { $path = $p.Path } catch {}
    if (-not $path) { try { $path = (Get-CimInstance Win32_Process -Filter ("ProcessId=" + $p.Id)).ExecutablePath } catch {} }
    return $path
}

function Apply-GpuPreference {
    if ($Script:MeasureOnlySession) { return }
    if (-not $Script:Config.GpuPreference) { return }
    foreach ($p in Get-GameProcesses) {
        if ($Script:GpuPrefPids.Contains($p.Id)) { continue }
        [void]$Script:GpuPrefPids.Add($p.Id)
        $path = Get-ProcessPath $p
        if (-not $path) { continue }
        try {
            $rk = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Software\Microsoft\DirectX\UserGpuPreferences')
            $cur = $rk.GetValue($path)
            if (-not $cur) {
                $rk.SetValue($path, 'GpuPreference=2;', [Microsoft.Win32.RegistryValueKind]::String)
                $Script:Config.GpuPrefAdded = @($Script:Config.GpuPrefAdded + $path)
                Save-Config
                Log ("Carte graphique puissante forcee pour " + (Get-GameLabel $p.ProcessName) + " (actif au prochain lancement du jeu)")
            }
            $rk.Close()
        } catch {}
    }
}

# --- Niveaux de priorite (sans "Temps reel", qui peut bloquer Windows) -------------
$Script:PrioNames = @('Basse', 'Sous la normale', 'Normale', 'Au-dessus de la normale', 'Haute')
$Script:PrioShort = @('Basse', 'Sous normale', 'Normale', 'Au-dessus', 'Haute')
$Script:PrioClasses = @([System.Diagnostics.ProcessPriorityClass]::Idle, [System.Diagnostics.ProcessPriorityClass]::BelowNormal,
                        [System.Diagnostics.ProcessPriorityClass]::Normal, [System.Diagnostics.ProcessPriorityClass]::AboveNormal,
                        [System.Diagnostics.ProcessPriorityClass]::High)
$Script:PrioColors = @($cViolet, $cCyan,
                       $cText, $cYellow,
                       $cGreen)
function Get-PrioIndex($pc) {
    switch ([string]$pc) { 'Idle' { return 0 } 'BelowNormal' { return 1 } 'Normal' { return 2 } 'AboveNormal' { return 3 } 'High' { return 4 } 'RealTime' { return 4 } }
    return 2
}
function Set-AppPriority($name, [int]$level) {
    $ok = 0; $ko = 0
    foreach ($p in @(Get-Process -Name $name -ErrorAction SilentlyContinue)) {
        try { $p.PriorityClass = $Script:PrioClasses[$level]; $ok++ } catch { $ko++ }
    }
    return @{ Ok = $ok; Ko = $ko }
}
# Priorites "retenues" : remises automatiquement a chaque lancement de l'appli
function Apply-AppPriorityRules {
    $rules = $Script:Config.AppPriorities
    if (-not $rules -or $rules.Count -eq 0) { return }
    $byName = @{}
    foreach ($k in @($rules.Keys)) { $lvl = [int]$rules[$k]; if ($lvl -ge 0 -and $lvl -le 4) { $byName[([string]$k).ToLower()] = $lvl } }
    if ($byName.Count -eq 0) { return }
    foreach ($p in [System.Diagnostics.Process]::GetProcesses()) {
        $lvl = $byName[$p.ProcessName.ToLower()]
        if ($null -ne $lvl) { try { if ($p.PriorityClass -ne $Script:PrioClasses[$lvl]) { $p.PriorityClass = $Script:PrioClasses[$lvl] } } catch {} }
        $p.Dispose()
    }
}

function Apply-GamePriority {
    if ($Script:MeasureOnlySession) { return }
    if (-not $Script:Config.GamePriority) { return }
    foreach ($p in Get-GameProcesses) {
        if ($Script:BoostedPids.Contains($p.Id)) { continue }
        try {
            $lvl = [int]$Script:Config.GamePrioLevel
            if ($Script:Config.AppPriorities.ContainsKey($p.ProcessName)) { $lvl = [int]$Script:Config.AppPriorities[$p.ProcessName] }
            if ($lvl -lt 0 -or $lvl -gt 4) { $lvl = 4 }
            $p.PriorityClass = $Script:PrioClasses[$lvl]
            [void]$Script:BoostedPids.Add($p.Id)
            Log ("Priorite " + $Script:PrioNames[$lvl] + " -> " + $p.ProcessName + " (PID " + $p.Id + ")")
        } catch {
            [void]$Script:BoostedPids.Add($p.Id)
            Log ("Priorite non modifiable pour " + $p.ProcessName + " (protege par l'anti-triche, c'est normal)")
        }
    }
}

# --- Sauvegarde d'origine (avant toute modification) -------------------------
function Get-TrackedRegistry {
    # Toutes les valeurs que GameBoost peut modifier
    $list = New-Object System.Collections.ArrayList
    [void]$list.Add((Read-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 'DWord'))
    [void]$list.Add((Read-RegValue 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 'DWord'))
    [void]$list.Add((Read-RegValue 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 'DWord'))
    $k = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
    [void]$list.Add((Read-RegValue $k 'GPU Priority' 'DWord'))
    [void]$list.Add((Read-RegValue $k 'Priority' 'DWord'))
    [void]$list.Add((Read-RegValue $k 'Scheduling Category' 'String'))
    [void]$list.Add((Read-RegValue $k 'SFIO Priority' 'String'))
    $m = 'HKCU:\Control Panel\Mouse'
    foreach ($n in 'MouseSpeed', 'MouseThreshold1', 'MouseThreshold2') { [void]$list.Add((Read-RegValue $m $n 'String')) }
    $base = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
    foreach ($iface in Get-ChildItem -Path $base -ErrorAction SilentlyContinue) {
        [void]$list.Add((Read-RegValue $iface.PSPath 'TcpAckFrequency' 'DWord'))
        [void]$list.Add((Read-RegValue $iface.PSPath 'TcpNoDelay' 'DWord'))
    }
    return @($list)
}

function New-Baseline {
    $b = [ordered]@{
        Date        = (Get-Date -Format "yyyy-MM-dd HH:mm:ss")
        PowerScheme = Get-ActiveScheme
        PowerOverlay = Get-PowerOverlay
        Registry    = Get-TrackedRegistry
        Services    = @($ServicesToPause | ForEach-Object {
                        $svc = Get-Service -Name $_.Name -ErrorAction SilentlyContinue
                        if ($svc) { [ordered]@{ Name = $_.Name; Running = ($svc.Status -eq 'Running') } } })
    }
    $b | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $BaselineFile -Encoding UTF8
    Log ("Sauvegarde d'origine enregistree (" + @($b.Registry).Count + " valeurs du registre, plan d'alimentation, services)")
}

function Ensure-Baseline {
    if (-not (Test-Path -LiteralPath $BaselineFile)) { New-Baseline; return }
    # Complete la sauvegarde avec les valeurs ajoutees par une nouvelle version (ou une nouvelle carte reseau)
    try {
        $b = Get-Content -LiteralPath $BaselineFile -Raw | ConvertFrom-Json
        $known = @{}
        foreach ($e in @($b.Registry)) { if ($e) { $known[($e.Path + '|' + $e.Name)] = $true } }
        $added = @(Get-TrackedRegistry | Where-Object { -not $known.ContainsKey($_.Path + '|' + $_.Name) })
        $changed = $false
        if ($added.Count -gt 0) { $b.Registry = @(@($b.Registry) + $added); $changed = $true }
        if ($null -eq $b.PSObject.Properties['PowerOverlay']) { $b | Add-Member -NotePropertyName PowerOverlay -NotePropertyValue (Get-PowerOverlay); $changed = $true }
        if ($changed) {
            $b | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath $BaselineFile -Encoding UTF8
            Log ("Sauvegarde d'origine completee (" + $added.Count + " nouvelle(s) valeur(s) suivie(s))")
        }
    } catch {}
}

function Get-BaselineDate {
    try { return (Get-Content -LiteralPath $BaselineFile -Raw | ConvertFrom-Json).Date } catch { return $null }
}

function Invoke-RestoreAll {
    $Script:BusyDepth++
    try { Invoke-RestoreAllCore }
    catch { Log ("ERREUR pendant la restauration complete : " + $_.Exception.Message) }
    finally { $Script:BusyDepth--; $btnRestoreAll.Enabled = $true; $btnBoost.Enabled = $true; Update-BoostButton }
}

function Invoke-RestoreAllCore {
    if (-not (Test-Path -LiteralPath $BaselineFile)) {
        [System.Windows.Forms.MessageBox]::Show("Aucune sauvegarde d'origine trouvee.", "GameBoost") | Out-Null
        return
    }
    $b = $null
    try { $b = Get-Content -LiteralPath $BaselineFile -Raw | ConvertFrom-Json } catch {}
    if (-not $b) { Log "Sauvegarde d'origine illisible"; return }

    $btnRestoreAll.Enabled = $false
    if ($Script:Boosted -or (Test-Path -LiteralPath $StateFile)) { Invoke-Restore }
    Log ("=== RESTAURATION COMPLETE (etat du " + $b.Date + ") ===")

    # Turbo seulement en jeu : option coupee, turbo d'origine remis
    if ($Script:Config.TurboOnlyInGame -or $Script:Config.TurboOrig -or [int]$Script:Config.TurboOnMhz -gt 0) {
        $Script:Config.TurboOnlyInGame = $false; $Script:Config.TurboOnMhz = 0; $Script:Config.TurboOffMhz = 0; Set-GBTurboCap $false; Save-Config
        if ($Script:BtnTurbo) { Update-GBTurboButton }
    }
    # Carte graphique : mode ECO coupe, frequence et puissance d'origine
    if ($Script:Config.GpuEco -or $Script:Config.GpuLocked -or $Script:Config.GpuPlSet -or [int]$Script:Config.GpuOnMhz -gt 0) {
        $Script:Config.GpuEco = $false; $Script:Config.GpuOnMhz = 0; $Script:Config.GpuPowerMax = $false; Save-Config
        Set-GBGpuCap $false
        if ($Script:BtnGpu) { Update-GBGpuButton }
    }
    # Limite de FPS du pilote NVIDIA : valeur d'origine
    if ([int]$Script:Config.FpsCapOrig -ge 0 -and (Test-Path function:Restore-GBFpsCap)) { Restore-GBFpsCap }

    # Registre
    $n = Restore-Registry $b.Registry
    Apply-MouseSettings
    Log ("Registre : " + $n + " valeur(s) remise(s) a l'origine")

    # Plan d'alimentation
    if ($b.PowerScheme) {
        powercfg /setactive $b.PowerScheme 2>$null | Out-Null
        if ((Get-ActiveScheme) -eq $b.PowerScheme) { Log "Plan d'alimentation d'origine restaure" }
        else { Log "Plan d'alimentation d'origine introuvable (supprime ?) : laisse tel quel" }
    }
    if ($b.PowerOverlay -and (Get-PowerOverlay) -ne $b.PowerOverlay) {
        if (Set-PowerOverlay $b.PowerOverlay) { Log "Mode d'alimentation Windows d'origine restaure" }
    }
    # Suppression du plan cree par GameBoost (s'il n'est pas celui d'origine)
    if ($Script:Config.PerfScheme -and $Script:Config.PerfScheme -ne $b.PowerScheme -and (Get-ActiveScheme) -ne $Script:Config.PerfScheme) {
        powercfg /delete $Script:Config.PerfScheme 2>$null | Out-Null
        Log "Plan 'Performances optimales' cree par GameBoost supprime"
        $Script:Config.PerfScheme = $null
        Save-Config
    }

    # Preferences de carte graphique ajoutees par GameBoost
    $gp = @($Script:Config.GpuPrefAdded | Where-Object { $_ })
    if ($gp.Count -gt 0) {
        try {
            $rk = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Microsoft\DirectX\UserGpuPreferences', $true)
            if ($rk) {
                foreach ($x in $gp) { if ($rk.GetValue($x) -eq 'GpuPreference=2;') { $rk.DeleteValue($x, $false) } }
                $rk.Close()
            }
        } catch {}
        $Script:Config.GpuPrefAdded = @(); Save-Config
        Log ("Choix de carte graphique retire pour " + $gp.Count + " jeu(x)")
    }

    # Services
    foreach ($svc in @($b.Services)) {
        if (-not $svc) { continue }
        $cur = Get-Service -Name $svc.Name -ErrorAction SilentlyContinue
        if ($cur -and $svc.Running -and $cur.Status -ne 'Running') {
            try { Start-Service -Name $svc.Name -ErrorAction Stop; Log ("Service relance : " + $svc.Name) } catch {}
        }
    }

    # Priorite des processus des jeux
    foreach ($p in Get-GameProcesses) { try { $p.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::Normal } catch {} }

    Remove-Item -LiteralPath $StateFile -ErrorAction SilentlyContinue
    Log "=== PC remis exactement comme a l'origine ==="
    $btnRestoreAll.Enabled = $true
    $tray.ShowBalloonTip(2500, "GameBoost", "Tous les reglages d'origine ont ete restaures.", [System.Windows.Forms.ToolTipIcon]::Info)
}

# --- Point de restauration Windows -------------------------------------------
function New-WindowsRestorePoint {
    $today = (Get-Date -Format "yyyy-MM-dd")
    if ($Script:Config.LastRestorePoint -eq $today) { return }
    $lblStatus.Text = "Creation d'un point de restauration Windows... (jusqu'a 1 min)"
    $lblStatus.ForeColor = $cYellow
    Log "Creation d'un point de restauration Windows..."
    $start = Get-Date
    $cmd = "try { Enable-ComputerRestore -Drive '" + $env:SystemDrive + "\' -ErrorAction SilentlyContinue } catch {}; " +
           "Checkpoint-Computer -Description 'GameBoost - avant optimisation' -RestorePointType MODIFY_SETTINGS -ErrorAction Stop"
    try {
        $proc = Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -Command `"$cmd`"" -WindowStyle Hidden -PassThru
        while (-not $proc.HasExited -and ((Get-Date) - $start).TotalSeconds -lt 180) {
            [System.Windows.Forms.Application]::DoEvents(); Start-Sleep -Milliseconds 200
        }
        if (-not $proc.HasExited) { try { $proc.Kill() } catch {} }
    } catch {}
    $created = $false
    try {
        $last = Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber | Select-Object -Last 1
        if ($last -and $last.ConvertToDateTime($last.CreationTime) -ge $start.AddSeconds(-5)) { $created = $true }
    } catch {}
    if ($created) {
        Log "Point de restauration Windows cree"
        $Script:Config.LastRestorePoint = $today; Save-Config
    } else {
        $recent = $null
        try {
            $last = Get-ComputerRestorePoint -ErrorAction Stop | Sort-Object SequenceNumber | Select-Object -Last 1
            if ($last) { $recent = $last.ConvertToDateTime($last.CreationTime) }
        } catch {}
        if ($recent -and $recent -gt (Get-Date).AddHours(-24)) {
            Log ("Windows a deja un point de restauration recent (" + $recent.ToString("dd/MM HH:mm") + ") : pas besoin d'en refaire")
            $Script:Config.LastRestorePoint = $today; Save-Config
        } else {
            Log "Point de restauration non cree (protection systeme desactivee ?). La sauvegarde d'origine GameBoost reste active."
        }
    }
}

function Save-State { $Script:State | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $StateFile -Encoding UTF8 }

function Invoke-BoostCore([bool]$auto = $false) {
    if ($Script:Boosted) { return }
    if (-not $Script:MeasureOnlySession) { Sync-ConfigFromUI }
    $btnBoost.Enabled = $false
    if ($Script:MeasureOnlySession) { Log "=== Mode comparaison : mesure SANS optimisation ===" } else { Log "=== Activation du Mode Jeu ===" }
    Ensure-Baseline
    if ($Script:Config.RestorePoint) { New-WindowsRestorePoint }
    $before = Log-Snapshot "AVANT boost"
    $Script:State = [ordered]@{ PrevScheme = $null; PrevOverlay = $null; CpuBackup = $null; ClosedApps = @(); StoppedServices = @(); GameModeWasOn = $null; Registry = @(); LoweredProcs = @() }

    $keep = @($Protected + $Script:Config.Whitelist + (Get-GameNames)) | ForEach-Object { $_.ToLower() }
    $myPid = $PID

    # 0. Turbo seulement en jeu : le turbo revient pour la partie (avant de noter le plan d'origine)
    if ($Script:Config.TurboOrig) { try { Set-GBTurboCap $false } catch {} }

    # 1. Plan d'alimentation
    if ($Script:Config.PowerPlan) {
        # Curseur "Mode d'alimentation" de Windows 10/11 -> Meilleures performances
        $ov = Get-PowerOverlay
        if ($null -ne $ov) {
            $Script:State.PrevOverlay = $ov
            $target = Get-OverlayGuid $Script:Config.PowerOverlayBoost
            if ($ov -ne $target -and (Set-PowerOverlay $target)) { Log ("Mode d'alimentation Windows : " + $Script:OverlayNames[$target]) }
        }
    }
    if ($Script:Config.PowerPlan -and $Script:ModernStandby) {
        Log "PC en veille moderne : le plan d'alimentation reste le meme (recommandation Microsoft), seul le mode 'Meilleures performances' est utilise"
    }
    elseif ($Script:Config.PowerPlan) {
        $Script:State.PrevScheme = Get-ActiveScheme
        $perf = Get-PerformanceScheme
        if ($perf) {
            powercfg /setactive $perf 2>$null | Out-Null
            Log "Plan d'alimentation : performances maximales"
            if ($Script:Config.PlanTuning -and $perf -eq $Script:Config.PerfScheme) {
                Set-GameBoostPlanTuning $perf
                Log "Plan GameBoost : USB, PCI Express, processeur et disque regles au maximum"
            }
        } else { Log "Aucun plan hautes performances disponible sur ce PC (ignore)" }
    }

    Save-State

    # 1b. Processeur : etat minimal / maximal choisis avec les curseurs (sur secteur), restaures a la fin
    if ($Script:Config.PowerPlan -and $Script:Config.CpuCustom) {
        $sch = Get-ActiveScheme
        if ($sch) {
            $oldMin = Get-PowerSettingAC $sch 'SUB_PROCESSOR' 'PROCTHROTTLEMIN'
            $oldMax = Get-PowerSettingAC $sch 'SUB_PROCESSOR' 'PROCTHROTTLEMAX'
            if ($null -ne $oldMin -and $null -ne $oldMax) {
                $Script:State.CpuBackup = @{ Scheme = $sch; Min = $oldMin; Max = $oldMax }
                Save-State
                $nMin = [int]$Script:Config.CpuMinBoost; $nMax = [int]$Script:Config.CpuMaxBoost
                if ($nMin -gt $nMax) { $nMin = $nMax }
                powercfg /setacvalueindex $sch SUB_PROCESSOR PROCTHROTTLEMIN $nMin 2>$null | Out-Null
                powercfg /setacvalueindex $sch SUB_PROCESSOR PROCTHROTTLEMAX $nMax 2>$null | Out-Null
                powercfg /setactive $sch 2>$null | Out-Null
                Log ("Processeur pendant le boost : minimum " + $nMin + " %, maximum " + $nMax + " % (avant : " + $oldMin + " % / " + $oldMax + " %)")
            }
        }
    }
    Save-State

    # 2. Mode Jeu Windows
    try {
        $key = 'HKCU:\Software\Microsoft\GameBar'
        if (-not (Test-Path $key)) { New-Item -Path $key -Force | Out-Null }
        $Script:State.GameModeWasOn = (Get-ItemProperty -Path $key -Name AutoGameModeEnabled -ErrorAction SilentlyContinue).AutoGameModeEnabled
        Set-ItemProperty -Path $key -Name AutoGameModeEnabled -Value 1 -Type DWord
        Log "Mode Jeu Windows active"
    } catch {}

    # 3. Fermeture des applications
    if ($Script:Config.CloseApps) {
        $closed = New-Object System.Collections.ArrayList
        $procs = Get-Process -ErrorAction SilentlyContinue | Where-Object {
            $_.Id -ne $myPid -and $_.SessionId -ne 0 -and ($keep -notcontains $_.ProcessName.ToLower())
        }
        foreach ($p in $procs) {
            $name = $p.ProcessName.ToLower()
            $hasWindow = $p.MainWindowHandle -ne [IntPtr]::Zero
            $isHog = @($Script:Config.CloseList) -contains $name
            if (-not ($hasWindow -or $isHog)) { continue }
            $path = $null; try { $path = $p.Path } catch {}
            try {
                if ($isHog -or $Script:Config.ForceClose) {
                    if ($hasWindow) { [void]$p.CloseMainWindow(); [void]$p.WaitForExit(1500) }
                    if (-not $p.HasExited) { $p.Kill() }
                } else {
                    [void]$p.CloseMainWindow()
                }
                if ($path -and -not ($closed | Where-Object { $_ -eq $path })) { [void]$closed.Add($path) }
                Log ("Ferme : " + $p.ProcessName)
            } catch {}
        }
        $Script:State.ClosedApps = @($closed)
    }

    Save-State

    # 4. Services
    if ($Script:Config.PauseServices) {
        foreach ($s in $ServicesToPause) {
            if (@($Script:Config.ServicesSelected) -notcontains $s.Name) { continue }
            $svc = Get-Service -Name $s.Name -ErrorAction SilentlyContinue
            if ($svc -and $svc.Status -eq 'Running') {
                try {
                    Stop-Service -Name $s.Name -Force -ErrorAction Stop -WarningAction SilentlyContinue
                    $Script:State.StoppedServices += $s.Name
                    Log ("Service en pause : " + $s.Label)
                } catch { Log ("Impossible de mettre en pause : " + $s.Label) }
            }
        }
    }

    Save-State

    # 4b. Priorite GPU / planificateur multimedia pour les jeux
    if ($Script:Config.GpuPriority) {
        try {
            $k = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games'
            Set-RegBackup $k 'GPU Priority' 8 'DWord'
            Set-RegBackup $k 'Priority' 6 'DWord'
            Set-RegBackup $k 'Scheduling Category' 'High' 'String'
            Set-RegBackup $k 'SFIO Priority' 'High' 'String'
            Log "Priorite GPU des jeux : haute"
        } catch { Log "Priorite GPU : modification impossible" }
    }

    # 4c. Reseau : algorithme de Nagle (connexions TCP)
    if ($Script:Config.NetworkTweak) {
        $count = 0
        $base = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
        foreach ($iface in Get-ChildItem -Path $base -ErrorAction SilentlyContinue) {
            $props = Get-ItemProperty -Path $iface.PSPath -ErrorAction SilentlyContinue
            # Uniquement les cartes reseau actives (avec une adresse IP)
            if (-not ($props.DhcpIPAddress -or ($props.IPAddress -and ($props.IPAddress -join '') -ne '0.0.0.0'))) { continue }
            try {
                Set-RegBackup $iface.PSPath 'TcpAckFrequency' 1 'DWord'
                Set-RegBackup $iface.PSPath 'TcpNoDelay' 1 'DWord'
                $count++
            } catch {}
        }
        Log ("Reseau : Nagle desactive sur " + $count + " carte(s) (agit sur les nouvelles connexions TCP)")
    }

    # 4d. Acceleration de la souris
    if ($Script:Config.MouseAccelOff) {
        try {
            $k = 'HKCU:\Control Panel\Mouse'
            Set-RegBackup $k 'MouseSpeed' '0' 'String'
            Set-RegBackup $k 'MouseThreshold1' '0' 'String'
            Set-RegBackup $k 'MouseThreshold2' '0' 'String'
            Apply-MouseSettings
            Log "Acceleration de la souris desactivee"
        } catch { Log "Souris : modification impossible" }
    }

    # 4e. Enregistrement Xbox en arriere-plan
    if ($Script:Config.GameDvrOff) {
        try {
            Set-RegBackup 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0 'DWord'
            Set-RegBackup 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0 'DWord'
            Log "Enregistrement Xbox en arriere-plan coupe"
        } catch { Log "Game DVR : modification impossible" }
    }
    Save-State

    # 4f. Priorite basse pour les launchers / utilitaires restes ouverts
    if ($Script:Config.LowerBackground) {
        $low = New-Object System.Collections.ArrayList
        foreach ($p in Get-Process -ErrorAction SilentlyContinue) {
            if (@($Script:Config.LowerList) -notcontains $p.ProcessName.ToLower()) { continue }
            if ($Script:Config.AppPriorities.ContainsKey($p.ProcessName)) { continue }   # priorite choisie par toi : on n'y touche pas
            try {
                $old = $p.PriorityClass
                if ($old -ne [System.Diagnostics.ProcessPriorityClass]::Normal) { continue }
                $ll = [int]$Script:Config.LowerLevel; if ($ll -lt 0 -or $ll -gt 1) { $ll = 1 }
                $p.PriorityClass = $Script:PrioClasses[$ll]
                [void]$low.Add([ordered]@{ Id = $p.Id; Name = $p.ProcessName; Prio = $old.ToString() })
            } catch {}
        }
        $Script:State.LoweredProcs = @($low)
        if ($low.Count -gt 0) {
            $names = @($low | ForEach-Object { $_.Name } | Select-Object -Unique)
            Log ("Priorite basse pour " + $low.Count + " processus : " + ($names -join ", "))
        }
    }
    Save-State

    # 5. RAM
    if ($Script:Config.CleanRam) {
        # (variables a part : $before / $after contiennent les mesures AVANT / APRES du bilan)
        $freeBefore = Get-FreeMemKo
        $gameNames = Get-GameNames
        # Vider la memoire des programmes quand la RAM n'est pas pleine ne sert a rien : Windows doit ensuite
        # la relire sur le disque (saccades). On ne le fait donc que si moins de 25 % de la RAM est disponible.
        $memNow = $null; if ($Script:FastOK) { try { $memNow = [GBSys]::Memory() } catch {} }
        $ramOk = $false
        if ($memNow -and [double]$memNow[1] -ge 0.25 * [double]$memNow[0]) { $ramOk = $true }
        if ($ramOk) { Log ("RAM suffisante (" + [math]::Round([double]$memNow[1] / 1GB, 1) + " Go disponibles) : rien a vider, cela evite des saccades") }
        if ($Script:NativeOK -and -not $ramOk) {
            $gset = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($n in $gameNames) { [void]$gset.Add([string]$n) }
            foreach ($n in @($Script:Config.Whitelist) + $Protected) { if ($n) { [void]$gset.Add([string]$n) } }
            foreach ($p in [System.Diagnostics.Process]::GetProcesses()) {
                if (-not $gset.Contains($p.ProcessName)) { try { [void][GBNative]::EmptyWorkingSet($p.Handle) } catch {} }
                $p.Dispose()
            }
        }
        $freeAfter = Get-FreeMemKo
        if ($ramOk) { }
        elseif (-not $Script:NativeOK) { Log "Liberation de la RAM indisponible (fonction Windows bloquee par l'antivirus)" }
        elseif ($null -ne $freeBefore -and $null -ne $freeAfter) {
            $gain = [math]::Round(($freeAfter - $freeBefore) / 1024)
            if ($gain -lt 0) { $gain = 0 }
            Log ("RAM liberee : ~" + $gain + " Mo")
        } else { Log "RAM des autres programmes liberee" }
    }

    Save-State
    $after = Log-Snapshot "APRES boost"
    if ($null -ne $before.RamUsedGo -and $null -ne $after.RamUsedGo) {
        $gainGo = [math]::Round($before.RamUsedGo - $after.RamUsedGo, 1)
        $Script:BoostBilan = "" + ($before.Procs - $after.Procs) + " processus en moins, " + $gainGo + " Go de RAM liberes"
        Log ("Bilan : " + $Script:BoostBilan)
    }
    Start-Session
    Start-FpsCapture
    $Script:BoostedPids.Clear()
    $Script:Boosted = $true
    $Script:AutoBoosted = $auto
    try { if (Test-Path function:Invoke-GBExtBoost) { Invoke-GBExtBoost $true } } catch {}   # macros et egaliseur du jeu
    $Script:GpuPrefPids.Clear()
    Apply-GamePriority
    Apply-GpuPreference
    $btnBoost.Enabled = $true
    Update-BoostButton
    $tray.ShowBalloonTip(2500, "GameBoost", "Mode Jeu active. Bon jeu !", [System.Windows.Forms.ToolTipIcon]::Info)
    Log "=== Mode Jeu actif ==="
}

function Invoke-RestoreCore {
    if (-not $Script:State -and (Test-Path -LiteralPath $StateFile)) {
        try { $Script:State = Get-Content -LiteralPath $StateFile -Raw | ConvertFrom-Json } catch {}
    }
    $btnBoost.Enabled = $false
    Stop-FpsCapture
    if ($Script:Boosted) { Write-SessionSummary }
    Log "=== Retour a la normale ==="
    if ($Script:State) {
        if ($Script:State.CpuBackup -and $Script:State.CpuBackup.Scheme) {
            $cb = $Script:State.CpuBackup
            powercfg /setacvalueindex $cb.Scheme SUB_PROCESSOR PROCTHROTTLEMIN ([int]$cb.Min) 2>$null | Out-Null
            powercfg /setacvalueindex $cb.Scheme SUB_PROCESSOR PROCTHROTTLEMAX ([int]$cb.Max) 2>$null | Out-Null
            powercfg /setactive $cb.Scheme 2>$null | Out-Null
            Log ("Processeur remis comme avant (" + $cb.Min + " % / " + $cb.Max + " %)")
        }
        if ($Script:State.PrevScheme) {
            powercfg /setactive $Script:State.PrevScheme 2>$null | Out-Null
            Log "Plan d'alimentation restaure"
        }
        if ($Script:State.PrevOverlay -and (Get-PowerOverlay) -ne $Script:State.PrevOverlay) {
            if (Set-PowerOverlay $Script:State.PrevOverlay) { Log "Mode d'alimentation Windows restaure" }
        }
        if ($null -ne $Script:State.GameModeWasOn) {
            try { Set-ItemProperty -Path 'HKCU:\Software\Microsoft\GameBar' -Name AutoGameModeEnabled -Value $Script:State.GameModeWasOn -Type DWord } catch {}
        }
        if ($Script:State.Registry) {
            $n = Restore-Registry $Script:State.Registry
            if ($n -gt 0) { Log ("Registre restaure (" + $n + " valeur(s))") }
            Apply-MouseSettings
        }
        $restored = 0
        foreach ($lp in @($Script:State.LoweredProcs)) {
            if (-not $lp) { continue }
            try {
                $proc = Get-Process -Id $lp.Id -ErrorAction Stop
                if ($proc.ProcessName -eq $lp.Name) { $proc.PriorityClass = [System.Diagnostics.ProcessPriorityClass]$lp.Prio; $restored++ }
            } catch {}
        }
        if ($restored -gt 0) { Log ("Priorite normale remise pour " + $restored + " processus") }
        foreach ($s in @($Script:State.StoppedServices)) {
            if (-not $s) { continue }
            try { Start-Service -Name $s -ErrorAction Stop; Log ("Service relance : " + $s) } catch {}
        }
        if ($Script:Config.ReopenApps) {
            foreach ($path in @($Script:State.ClosedApps)) {
                if (-not $path -or -not (Test-Path -LiteralPath $path)) { continue }
                $n = [IO.Path]::GetFileNameWithoutExtension($path)
                if (Get-Process -Name $n -ErrorAction SilentlyContinue) { continue }
                # Relance au niveau normal de l'utilisateur (GameBoost est admin : Start-Process relancait l'appli en admin)
                try { if (Start-GBUnelevated $path '' '') { Log ("Rouvert : " + $n) } } catch {}
            }
        }
    }
    foreach ($p in Get-GameProcesses) {
        try { $p.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::Normal } catch {}
    }
    Remove-Item -LiteralPath $StateFile -ErrorAction SilentlyContinue
    $Script:State = $null
    $Script:Boosted = $false
    $Script:AutoBoosted = $false
    try { if (Test-Path function:Invoke-GBExtBoost) { Invoke-GBExtBoost $false } } catch {}
    $Script:MeasureOnlySession = $false
    $Script:BoostedPids.Clear()
    $btnBoost.Enabled = $true
    Update-BoostButton
    Log "=== PC revenu a la normale ==="
}

# --- Protection anti-bug -----------------------------------------------------
# Empeche deux actions de se lancer en meme temps (ex : le mode auto pendant un boost en cours)
$Script:BusyDepth = 0
function Get-MeasureOnlyConfig($src) {
    $tmp = [ordered]@{}
    foreach ($k in @($src.Keys)) { $tmp[$k] = $src[$k] }
    foreach ($k in 'CloseApps', 'ForceClose', 'PauseServices', 'PowerPlan', 'PlanTuning', 'GamePriority', 'CleanRam', 'GpuPriority', 'GpuPreference',
                   'NetworkTweak', 'MouseAccelOff', 'GameDvrOff', 'LowerBackground', 'StandbyClean', 'RestorePoint') { $tmp[$k] = $false }
    return $tmp
}

# Pendant le jeu, GameBoost passe en priorite basse et en mode economie (coeurs efficaces sur les processeurs hybrides) :
# il ne prend jamais de temps processeur au jeu.
# Memoire disponible en Ko (sans WMI si possible)
function Get-FreeMemKo {
    if ($Script:FastOK) { try { $m = [GBSys]::Memory(); if ($m) { return [double]$m[1] / 1KB } } catch {} }
    try { return [double](Get-CimInstance Win32_OperatingSystem -ErrorAction Stop).FreePhysicalMemory } catch {}
    return $null
}

function Set-SelfLowImpact([bool]$on) {
    try {
        $me = [System.Diagnostics.Process]::GetCurrentProcess()
        if ($on) { $me.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::BelowNormal } else { $me.PriorityClass = [System.Diagnostics.ProcessPriorityClass]::Normal }
    } catch {}
    if ($Script:FastOK) { try { [void][GBSys]::SetSelfEco($on) } catch {} }
}

# Clic sur BOOST / ARRETER : un arret manuel n'est jamais annule par la detection automatique.
# Le mode auto ne pourra relancer le boost qu'apres la FERMETURE du jeu puis un nouveau lancement.
$Script:ManualStop = $false
function Switch-BoostManual {
    if ($Script:Boosted) {
        $Script:ManualStop = $true
        Invoke-Restore
        if ($Script:Config.AutoMode) { Log "Boost arrete a la main : pas de relance automatique tant que le jeu reste ouvert" }
    } else {
        $Script:ManualStop = $false
        Invoke-Boost $false
    }
}

function Invoke-Boost([bool]$auto = $false) {
    if ($Script:Boosted -or $Script:BusyDepth -gt 0) { return }
    $Script:BusyDepth++
    $Script:BoostBilan = ""
    try {
        Sync-ConfigFromUI
        $Script:MeasureOnlySession = [bool]$Script:Config.MeasureOnly
        if ($Script:MeasureOnlySession) {
            # Copie des reglages avec toutes les optimisations desactivees, juste pour cette session
            $Script:RealConfig = $Script:Config
            $Script:Config = Get-MeasureOnlyConfig $Script:RealConfig
        } else {
            # Profil propre au jeu lance (clic droit dans "Mes jeux") : copie des reglages au niveau choisi, juste pour ce boost
            $prof = Get-GameProfileFor
            if ($prof) {
                $Script:RealConfig = $Script:Config
                $Script:Config = New-GameProfileConfig $Script:RealConfig ([int]$prof.Level)
                Log ("Profil du jeu " + $prof.Game + " : niveau " + $Script:GameLevels[[int]$prof.Level].L)
            }
        }
        Invoke-BoostCore $auto
        Set-SelfLowImpact $true
        Update-GBTurboCap   # GHz choisis pour le mode TURBO ON pendant le jeu (rien si "sans limite")
        Update-GBGpuCap     # carte graphique : plus de limite ECO, puissance au maximum si choisie
    }
    catch {
        Log ("ERREUR pendant le boost : " + $_.Exception.Message + " -> annulation des changements")
        try { Invoke-RestoreCore } catch {}
        if ($Script:RealConfig) { $Script:Config = $Script:RealConfig; $Script:RealConfig = $null }
        Update-GBTurboCap
    }
    finally {
        if ($Script:RealConfig) { $Script:Config = $Script:RealConfig; $Script:RealConfig = $null }
        $Script:BusyDepth--; $btnBoost.Enabled = $true; Update-BoostButton
    }
}

function Invoke-Restore {
    $Script:BusyDepth++
    Set-SelfLowImpact $false
    try { Hide-GBOverlay } catch {}
    try { Invoke-RestoreCore }
    catch { Log ("ERREUR pendant la restauration : " + $_.Exception.Message + " (utilise TOUT RESTAURER)") }
    finally { $Script:BusyDepth--; $btnBoost.Enabled = $true; Update-BoostButton }
    if (-not $Script:Closing) { Update-GBTurboCap; Update-GBGpuCap }   # turbo et carte graphique de nouveau en mode hors jeu apres la partie
}

# --- Lancement au demarrage de Windows ---------------------------------------
$Script:ExePath = $null
if ($IconPath -and $IconPath.ToLower().EndsWith('.exe') -and (Test-Path -LiteralPath $IconPath)) { $Script:ExePath = $IconPath }

function Get-StartupTask {
    try { return Get-ScheduledTask -TaskName 'GameBoost' -ErrorAction Stop } catch { return $null }
}

function Set-StartupTask([bool]$enable) {
    try {
        if ($enable) {
            if (-not $Script:ExePath) { Log "Demarrage auto : lance GameBoost avec GameBoost.exe pour utiliser cette option"; return $false }
            $user = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
            $action = New-ScheduledTaskAction -Execute $Script:ExePath -Argument '-Minimized'
            $trigger = New-ScheduledTaskTrigger -AtLogOn -User $user
            $trigger.Delay = 'PT20S'
            $principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest
            $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew -Priority 4   # 4 = priorite normale (7 par defaut = ralenti)
            Register-ScheduledTask -TaskName 'GameBoost' -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Description "Lance GameBoost (reduit) a l'ouverture de session" -Force | Out-Null
            Log "GameBoost se lancera tout seul a l'ouverture de session (reduit pres de l'horloge)"
        } else {
            if (Get-StartupTask) { Unregister-ScheduledTask -TaskName 'GameBoost' -Confirm:$false; Log "Lancement automatique desactive" }
        }
        return $true
    } catch { Log ("Demarrage auto : erreur (" + $_.Exception.Message + ")"); return $false }
}

# --- Diagnostic du PC ---------------------------------------------------------
$Script:DiagIssues = 0
function Get-Diagnostic {
    $L = New-Object System.Collections.ArrayList
    $Script:DiagIssues = 0
    function Ok($t)    { [void]$L.Add("[OK]      " + $t) }
    function Warn($t)  { [void]$L.Add("[A VOIR]  " + $t); $Script:DiagIssues++ }
    function Info($t)  { [void]$L.Add("          " + $t) }
    function Title($t) { [void]$L.Add(""); [void]$L.Add("== " + $t + " ==") }

    Title "Ecran"
    try {
        foreach ($vc in @(Get-CimInstance Win32_VideoController -ErrorAction Stop)) {
            if (-not $vc.CurrentRefreshRate) { continue }
            $t = $vc.Name + " : " + $vc.CurrentHorizontalResolution + "x" + $vc.CurrentVerticalResolution + " a " + $vc.CurrentRefreshRate + " Hz"
            if ($vc.MaxRefreshRate -and $vc.MaxRefreshRate -gt ($vc.CurrentRefreshRate + 5) -and $vc.MaxRefreshRate -lt 600) {
                Warn ($t + " -> Windows indique jusqu'a " + $vc.MaxRefreshRate + " Hz. Verifie Parametres > Affichage > Affichage avance > Taux d'actualisation.")
            } else { Ok $t }
        }
    } catch { Info "Impossible de lire l'ecran" }

    Title "Carte graphique"
    try {
        foreach ($vc in @(Get-CimInstance Win32_VideoController -ErrorAction Stop)) {
            $age = $null
            if ($vc.DriverDate) { $age = [int]((Get-Date) - [datetime]$vc.DriverDate).TotalDays }
            $t = $vc.Name + " (pilote " + $vc.DriverVersion
            if ($null -ne $age) { $t += ", " + $age + " jours" }
            $t += ")"
            if ($vc.Name -match 'NVIDIA|GeForce|Radeon RX|Arc' -and $null -ne $age -and $age -gt 180) {
                Warn ($t + " -> pilote ancien : mets-le a jour (NVIDIA App / AMD Adrenalin / Intel Graphics).")
            } else { Ok $t }
        }
    } catch {}
    try { Initialize-GpuInventory } catch {}
    foreach ($gi in @($Script:GpuInv | Where-Object { $_.Kind -ne 'virtuel' -and $_.Kind -ne 'npu' })) {
        $t = $gi.Name + " = " + $gi.KindLabel
        if ($gi.Kind -eq 'dediee' -and $gi.VramGo) { $t += " (" + $gi.VramGo + " Go de memoire video)" }
        if ($gi.Display) { $t += ", l'ecran est branche dessus" }
        Info $t
    }
    $ded = $Script:MainGpu; $ig = $Script:IGpu
    if ($ig -and (-not $ded -or $ded -eq $ig)) {
        Info ("Pas de carte graphique dediee : les jeux tournent sur la puce du processeur (" + $ig.Short + "). Utilise les reglages Bas/Moyen et FSR ou XeSS pour plus de FPS.")
    } elseif ($Script:GpuHybrid -and $ig.Display -and -not $ded.Display) {
        if ($Script:IsLaptop) {
            Info ("Mode graphique hybride : l'ecran est branche sur la puce integree " + $ig.Short + " et " + $ded.Short + " calcule les jeux. " +
                  "Si ton portable a un 'MUX switch' (mode GPU 'dGPU / carte dediee' dans l'appli du fabricant), l'activer pour jouer donne souvent +5 a 15 % de FPS et moins de latence (redemarrage requis). " +
                  "Sinon, coche 'Forcer la carte puissante'.")
        } else {
            Warn ("L'ecran est branche sur la prise de la CARTE MERE (puce integree " + $ig.Short + ") et pas sur la carte graphique " + $ded.Short + ". " +
                  "Branche le cable sur les prises de la carte graphique (plus bas a l'arriere du PC, a l'horizontale) : enorme gain de FPS.")
        }
    }
    $hags = (Read-RegValue 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode').Value
    if ($hags -eq 2) { Ok "Planification GPU acceleree materiellement : activee" }
    elseif ($hags -eq 1) { Info "Planification GPU acceleree materiellement : desactivee. Avec une carte recente (RTX 20xx+ / RX 6000+), tu peux l'activer : Parametres > Affichage > Graphiques (redemarrage requis)." }
    $gm = (Read-RegValue 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled').Value
    if ($gm -eq 0) { Warn "Mode Jeu Windows desactive en dehors du boost : active-le dans Parametres > Jeux > Mode Jeu." } else { Ok "Mode Jeu Windows actif" }

    Title "Memoire (RAM)"
    try {
        $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop)
        $totalGo = [math]::Round((($mods | Measure-Object -Property Capacity -Sum).Sum) / 1GB)
        $cfgSpeed = ($mods | Where-Object { $_.ConfiguredClockSpeed } | Measure-Object -Property ConfiguredClockSpeed -Minimum).Minimum
        $type = ''
        switch ([int]$mods[0].SMBIOSMemoryType) { 24 { $type = 'DDR3' } 26 { $type = 'DDR4' } 34 { $type = 'DDR5' } }
        $t = "" + $totalGo + " Go " + $type + " en " + $mods.Count + " barrette(s)"
        if ($cfgSpeed) { $t += " a " + $cfgSpeed + " MT/s" }
        Info $t
        if ($totalGo -lt 16) { Warn ("Seulement " + $totalGo + " Go : 16 Go est le minimum conseille pour les jeux recents avec Discord ouvert.") }
        else { Ok "Quantite de RAM suffisante" }
        if ($mods.Count -eq 1) { Warn "Une seule barrette : la RAM tourne en simple canal. Une 2e barrette identique (dual channel) donne souvent +10 a 20 % de FPS dans les jeux limites par le processeur." }
        if (-not $Script:IsLaptop -and $cfgSpeed) {
            if (($type -eq 'DDR4' -and $cfgSpeed -le 2666) -or ($type -eq 'DDR5' -and $cfgSpeed -le 4800)) {
                Warn ("RAM a " + $cfgSpeed + " MT/s : si elle est vendue plus rapide (ex : 3200/3600 en DDR4, 6000 en DDR5), active le profil XMP/EXPO dans le BIOS.")
            }
        }
    } catch { Info "Impossible de lire la RAM" }

    Title "Stockage"
    try {
        # (lectures CIM directes : les modules Storage de Windows coutent ~110 Mo de memoire)
        foreach ($v in @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop | Where-Object { $_.Size -gt 10GB } | Sort-Object DeviceID)) {
            $pct = [int]([double]$v.FreeSpace * 100 / [double]$v.Size)
            $t = "Disque " + $v.DeviceID + " " + [math]::Round([double]$v.FreeSpace / 1GB) + " Go libres sur " + [math]::Round([double]$v.Size / 1GB) + " Go (" + $pct + " %)"
            if ($pct -lt 15) { Warn ($t + " -> presque plein : un SSD rempli a plus de 85 % ralentit (chargements, saccades). Libere de la place, vise 20 % libres.") } else { Ok $t }
        }
        $pdks = @(); try { $pdks = @(Get-CimInstance -Namespace 'root/Microsoft/Windows/Storage' -ClassName MSFT_PhysicalDisk -ErrorAction Stop) } catch {}
        foreach ($pdk in $pdks) {
            # SSD QLC sans cache DRAM (Crucial P3, Samsung QVO, Intel 660p...) : tres lents une fois presque pleins
            if ($pdk.FriendlyName -match 'CT\d+P3|P3 Plus|QVO|660p|670p|P1 |SN350|NV1|NV2') {
                Info ($pdk.FriendlyName + " : SSD de type QLC, il ralentit beaucoup quand il est presque plein. Garde-le sous 80 % de remplissage.")
            }
        }
        $sys = $env:SystemDrive.TrimEnd(':')
        $part = Get-CimInstance -Namespace 'root/Microsoft/Windows/Storage' -ClassName MSFT_Partition -Filter ("DriveLetter='" + $sys + "'") -ErrorAction Stop | Select-Object -First 1
        $pd = $pdks | Where-Object { [string]$_.DeviceId -eq [string]$part.DiskNumber } | Select-Object -First 1
        if ($pd) {
            $mtx = @{ 0 = 'type inconnu'; 3 = 'HDD'; 4 = 'SSD'; 5 = 'SCM' }[[int]$pd.MediaType]
            $btx = @{ 7 = 'USB'; 11 = 'SATA'; 17 = 'NVMe'; 8 = 'RAID'; 3 = 'ATA'; 10 = 'SAS' }[[int]$pd.BusType]
            if ([int]$pd.MediaType -eq 3) { Warn "Windows est installe sur un disque dur (HDD) : un SSD rendrait le PC et les chargements bien plus rapides." }
            else { Ok ("Windows est sur " + $pd.FriendlyName + " (" + $mtx + $(if ($btx) { ", " + $btx } else { "" }) + ")") }
        }
    } catch {}

    Title "Alimentation"
    $plan = ((powercfg /getactivescheme) -join ' ')
    if ($plan -match '\(([^)]+)\)') { Info ("Plan actif : " + $Matches[1]) }
    $ovNow = Get-PowerOverlay
    $onBattery = $false
    try { $bt = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1; if ($bt -and $bt.BatteryStatus -eq 1) { $onBattery = $true } } catch {}
    if ($ovNow -and $Script:OverlayNames.ContainsKey($ovNow)) {
        if (-not $onBattery -and ($ovNow -eq '961cc777-2547-4f9d-8174-7d86181b8a7a' -or $ovNow -eq '3af9b8d9-7c97-431d-ad78-34a8bfea439f')) {
            Warn ("Mode d'alimentation Windows : " + $Script:OverlayNames[$ovNow] + " alors que le PC est sur secteur. GameBoost passe en 'Meilleures performances' pendant le boost ; en dehors, change-le dans Parametres > Systeme > Alimentation.")
        } else { Info ("Mode d'alimentation Windows : " + $Script:OverlayNames[$ovNow]) }
    }
    # Portables gaming : le mode de performance du fabricant compte plus que celui de Windows
    if ($Script:IsLaptop) {
        $mk = ""
        try { $mk = [string](Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).Manufacturer } catch {}
        $tool = ""
        if ($mk -match 'Lenovo') { $tool = "Lenovo : mode Performance avec Fn+Q (voyant du bouton d'alimentation rouge/violet) ou dans Lenovo Vantage / Legion Space" }
        elseif ($mk -match 'ASUS') { $tool = "ASUS : mode Turbo/Performance dans Armoury Crate (ou Fn+F5)" }
        elseif ($mk -match 'Micro-Star|MSI') { $tool = "MSI : mode Extreme Performance dans MSI Center" }
        elseif ($mk -match 'HP') { $tool = "HP : mode Performance dans OMEN Gaming Hub / Victus" }
        elseif ($mk -match 'Dell|Alienware') { $tool = "Dell/Alienware : mode Performance dans Alienware Command Center / Dell Power Manager" }
        elseif ($mk -match 'Acer') { $tool = "Acer : mode Turbo/Performance dans PredatorSense / NitroSense" }
        elseif ($mk -match 'GIGABYTE|AORUS') { $tool = "Gigabyte : mode Performance dans Gigabyte Control Center" }
        elseif ($mk -match 'Razer') { $tool = "Razer : mode Performance dans Razer Synapse" }
        if ($tool) { Info ("Pour jouer, branche le chargeur et active le mode performance du fabricant. " + $tool + ".") }
    }
    if ($Script:ModernStandby) { Info "PC en veille moderne (S0) : GameBoost utilise le mode 'Meilleures performances' au lieu de changer de plan." }
    try {
        $bat = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1
        if ($bat) {
            if ($bat.BatteryStatus -eq 1) { Warn ("PC portable sur batterie (" + $bat.EstimatedChargeRemaining + " %) : branche le chargeur, les performances sont fortement reduites sur batterie.") }
            else { Ok "PC portable branche sur secteur" }
        }
    } catch {}

    Title "Connexion"
    try {
        # (lecture .NET : les modules NetTCPIP / NetAdapter de Windows coutent ~70 Mo de memoire)
        $ad = Get-GBInternetAdapter
        if (-not $ad) { throw "pas de carte vers internet" }
        $wifi = $ad.Wifi -or ($ad.InterfaceDescription -match 'Wi-?Fi|Wireless|WLAN|802\.11')
        $ad | Add-Member -NotePropertyName LinkSpeed -NotePropertyValue (Format-GBLinkSpeed $ad.Speed) -Force
        if ($wifi) {
            $sig = $null
            $w = (netsh wlan show interfaces) -join "`n"
            if ($w -match 'Signal\s*:\s*(\d+)\s*%') { $sig = [int]$Matches[1] }
            $t = "Connexion en Wi-Fi (" + $ad.LinkSpeed
            if ($sig) { $t += ", signal " + $sig + " %" }
            $t += ")"
            Warn ($t + " -> un cable Ethernet donne un ping plus stable (moins de pics de lag).")
        } else { Ok ("Connexion filaire : " + $ad.Name + " (" + $ad.LinkSpeed + ")") }
    } catch { Info "Impossible de lire la connexion reseau" }
    $vals = @()
    for ($i = 0; $i -lt 5; $i++) { $pg = Get-Ping; if ($null -ne $pg) { $vals += $pg } }
    if ($vals.Count -gt 0) {
        $m = $vals | Measure-Object -Average -Maximum -Minimum
        $t = "Ping vers internet : moyenne " + [int]$m.Average + " ms (min " + $m.Minimum + ", max " + $m.Maximum + ")"
        if ($m.Average -gt 60 -or ($m.Maximum - $m.Minimum) -gt 50) { Warn ($t + " -> eleve ou instable : coupe les telechargements et prefere le cable.") } else { Ok $t }
    } else { Warn "Pas de reponse au ping (connexion coupee ou ping bloque par le reseau)" }

    Title "Windows"
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $up = (Get-Date) - $os.LastBootUpTime
        if ($up.TotalDays -gt 7) { Warn ("PC sans vrai redemarrage depuis " + [int]$up.TotalDays + " jours (l'arret avec 'demarrage rapide' ne compte pas) : fais Demarrer > Redemarrer de temps en temps.") }
        else { Ok ("Dernier redemarrage il y a " + [int]$up.TotalDays + " jour(s)") }
    } catch {}
    if (Test-Path 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired') { Warn "Une mise a jour Windows attend un redemarrage : redemarre avant de jouer." }
    try {
        $st = @(Get-CimInstance Win32_StartupCommand -ErrorAction Stop)
        $stNames = @($st | ForEach-Object { [string]$_.Name } | Where-Object { $_ } | Sort-Object -Unique)
        if ($st.Count -gt 8) { Warn ("" + $st.Count + " programmes se lancent au demarrage : desactive les inutiles (Gestionnaire des taches > Applications de demarrage).") }
        else { Ok ("" + $st.Count + " programme(s) au demarrage") }
        if ($stNames.Count -gt 0) { Info ("Au demarrage : " + ($stNames -join ", ")) }
    } catch {}
    $svcNahimic = @(Get-Service -Name 'Nahimic*' -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'Running' })
    if ($svcNahimic.Count -gt 0) {
        Info "Nahimic (effets audio du fabricant) est actif : c'est une cause connue de saccades ou de plantages dans certains jeux. Si tu en as, desactive-le dans son appli ou arrete le service Nahimic."
    }

    if (-not $Script:Boosted) {
        Title "PC au repos (sans jeu)"
        $snap = Get-SystemSnapshot
        Info ("Processeur " + (Fmt $snap.Cpu " %") + " (coeur max " + (Fmt $snap.CpuMaxCore " %") + ")  |  Carte graphique " + $snap.GpuText +
              "  |  RAM " + (Fmt $snap.RamUsedGo "") + " / " + (Fmt $snap.RamTotalGo " Go") + " (" + (Fmt $snap.RamPct " %") + ")  |  " + $snap.Procs + " processus")
        if ($null -ne $snap.Cpu -and $snap.Cpu -gt 30) { Warn ("Processeur deja occupe a " + $snap.Cpu + " % sans jeu : regarde ce qui tourne dans le Gestionnaire des taches.") }
        if ($null -ne $snap.RamPct -and $snap.RamPct -gt 70) { Warn ("RAM deja utilisee a " + $snap.RamPct + " % sans jeu : ferme l'inutile ou active 'Fermer les autres applications'.") }
        # Qui utilise la carte graphique au repos ?
        $gpuUsers = @()
        if ($snap.GpuDetail) {
            $pnames = @{}
            foreach ($p in Get-Process -ErrorAction SilentlyContinue) { $pnames[$p.Id] = $p.ProcessName }
            $gpuUsers = @($snap.GpuDetail.Procs.GetEnumerator() | Sort-Object Value -Descending | Select-Object -First 8 | ForEach-Object {
                $luid, $procId = $_.Key.Split('|')
                $pn = $pnames[[int]$procId]; if (-not $pn) { $pn = "PID " + $procId }
                $pn + " " + [int]$_.Value + "% (" + (Get-ShortGpuName $Script:GpuNames[$luid]) + ")" })
        }
        if ($gpuUsers.Count -gt 0) { Info ("Programmes qui utilisent la carte graphique : " + ($gpuUsers -join ", ")) }
        if ($snap.GpuDetail) {
            foreach ($ad in @($snap.GpuDetail.Adapters)) {
                if ($ad.Usage -le 15) { continue }
                $isDedicated = ($ad.Name -match 'NVIDIA|GeForce|Radeon RX|Arc A|Arc B')
                if ($isDedicated) {
                    Warn ($ad.Short + " travaille a " + $ad.Usage + " % sans jeu. Regarde les programmes ci-dessus. Si un programme inconnu l'utilise en permanence, fais une analyse complete avec la Securite Windows (les mineurs de cryptomonnaie se cachent souvent ainsi).")
                } else {
                    Warn ($ad.Short + " (puce graphique integree) travaille a " + $ad.Usage + " % sans jeu : affichage de l'ecran 165 Hz, fond d'ecran anime, video ou navigateur. Sur un portable, elle partage la chaleur et l'energie du processeur.")
                }
            }
        }
        # Les programmes qui consomment le plus au repos (mesure sur 2 secondes)
        try {
            $t1 = @{}
            foreach ($p in Get-Process -ErrorAction SilentlyContinue) { try { $t1[$p.Id] = $p.TotalProcessorTime.TotalMilliseconds } catch {} }
            Start-Sleep -Milliseconds 2000
            $agg = @{}
            foreach ($p in Get-Process -ErrorAction SilentlyContinue) {
                if ($p.Id -eq 0) { continue }
                $n = $p.ProcessName
                if (-not $agg.ContainsKey($n)) { $agg[$n] = @{ Cpu = 0.0; Ram = 0.0 } }
                try { $agg[$n].Ram += [double]$p.WorkingSet64 } catch {}
                try { if ($t1.ContainsKey($p.Id)) { $agg[$n].Cpu += ($p.TotalProcessorTime.TotalMilliseconds - $t1[$p.Id]) / 2000.0 / $Script:Cores * 100 } } catch {}
            }
            $topCpu = @($agg.GetEnumerator() | Where-Object { $_.Value.Cpu -ge 0.3 } | Sort-Object { $_.Value.Cpu } -Descending | Select-Object -First 8 |
                        ForEach-Object { $_.Key + " " + ("{0:N1}" -f $_.Value.Cpu) + " %" })
            $topRam = @($agg.GetEnumerator() | Sort-Object { $_.Value.Ram } -Descending | Select-Object -First 10 |
                        ForEach-Object { $_.Key + " " + [int]($_.Value.Ram / 1MB) + " Mo" })
            if ($topCpu.Count -gt 0) { Info ("Plus gourmands en processeur : " + ($topCpu -join ", ")) } else { Info "Aucun programme n'utilise le processeur de facon notable." }
            Info ("Plus gourmands en RAM : " + ($topRam -join ", "))
        } catch {}
    }

    Title "Logiciels en jeu"
    $ovNames = @{ 'gameoverlayui' = 'Steam overlay'; 'gameoverlayui64' = 'Steam overlay'; 'nvidia overlay' = 'NVIDIA overlay'; 'rtss' = 'RivaTuner';
                  'msiafterburner' = 'MSI Afterburner'; 'overwolf' = 'Overwolf'; 'medal' = 'Medal'; 'gamebar' = 'Xbox Game Bar';
                  'lghub' = 'Logitech G Hub'; 'icue' = 'Corsair iCUE'; 'razercentral' = 'Razer Synapse'; 'signalrgb' = 'SignalRGB';
                  'wallpaper32' = 'Wallpaper Engine'; 'wallpaper64' = 'Wallpaper Engine' }
    $found = @(Get-Process -ErrorAction SilentlyContinue | ForEach-Object { $ovNames[$_.ProcessName.ToLower()] } | Where-Object { $_ } | Select-Object -Unique)
    if ($found.Count -ge 3) { Warn ("Beaucoup de logiciels en jeu : " + ($found -join ", ") + ". Garde seulement ceux que tu utilises.") }
    elseif ($found.Count -gt 0) { Ok ("Logiciels en jeu : " + ($found -join ", ")) }
    else { Ok "Aucun overlay lourd detecte" }
    if ($found -contains 'Wallpaper Engine') {
        Info "Wallpaper Engine : dans ses Parametres > Performances, regle 'Autre application en plein ecran' (et 'maximisee') sur 'Arreter' pour qu'il ne prenne rien pendant le jeu."
    }
    $ms = (Read-RegValue 'HKCU:\Control Panel\Mouse' 'MouseSpeed').Value
    if ($ms -eq '1') { Info "Acceleration de la souris activee : coche 'Desactiver l'acceleration de la souris' si tu joues aux FPS." }
    Info "Astuce Discord : Parametres > Avance > desactive l'acceleration materielle si ta carte graphique est deja a fond."

    $L.Insert(0, "Diagnostic du " + (Get-Date -Format "dd/MM/yyyy HH:mm") + " : " + $Script:DiagIssues + " point(s) a ameliorer")
    return $L
}

function Show-Diagnostic {
    $btnDiag.Enabled = $false
    $lblStatus.Text = "Diagnostic en cours (10 secondes environ)..."
    $lblStatus.ForeColor = $cYellow
    [System.Windows.Forms.Application]::DoEvents()
    $lines = @()
    try { $lines = @(Get-Diagnostic) } catch { $lines = @("Erreur pendant le diagnostic : " + $_.Exception.Message) }
    $text = $lines -join "`r`n"
    try { Add-Content -LiteralPath $Script:LogFile -Value ("`r`n===== DIAGNOSTIC =====`r`n" + $text + "`r`n======================`r`n") -Encoding UTF8 } catch {}
    Log ("Diagnostic termine : " + $Script:DiagIssues + " point(s) a ameliorer (detail aussi dans le fichier de log)")
    Update-BoostButton

    $f = New-Object System.Windows.Forms.Form
    Register-GBDpi $f
    $f.Text = "GameBoost - Diagnostic du PC"
    $f.Size = New-Object System.Drawing.Size(860, 600)
    $f.StartPosition = "CenterParent"
    $f.BackColor = $cBg; $f.ForeColor = $cText
    if ($form.Icon) { $f.Icon = $form.Icon }
    Set-GBDarkWindow $f
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.Multiline = $true; $tb.ReadOnly = $true; $tb.ScrollBars = "Both"; $tb.WordWrap = $true
    $tb.Dock = "Fill"; $tb.Font = New-Object System.Drawing.Font("Consolas", 10)
    $tb.BackColor = $cDeep; $tb.ForeColor = $cText
    $tb.Text = $text
    $tb.Select(0, 0)
    $f.Controls.Add($tb)
    [void]$f.ShowDialog($form)
    $f.Dispose()
    $btnDiag.Enabled = $true
}

# --- Pilotes et mises a jour --------------------------------------------------
# Analyse + recherche Windows Update dans un fil separe : la fenetre ne se fige pas
$Script:DriverReportFile = Join-Path $LogDir "pilotes_derniere_analyse.txt"
$Script:GpuCacheFile = Join-Path $AppDir "pilote_carte_graphique.json"

# Derniere version officielle du pilote de chaque carte graphique (NVIDIA, AMD, Intel).
# Texte charge dans les fils d'arriere-plan : la fenetre ne se fige jamais pendant les acces internet.
$Script:GpuLatestFn = @'
function Get-GBWeb($url, [switch]$Bytes) {
    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch {}
    $rq = [Net.HttpWebRequest]::Create($url)
    $rq.Timeout = 15000; $rq.ReadWriteTimeout = 20000
    $rq.UserAgent = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36'
    $rq.AutomaticDecompression = [Net.DecompressionMethods]'GZip, Deflate'
    try { $rq.Proxy = [Net.WebRequest]::GetSystemWebProxy(); $rq.Proxy.Credentials = [Net.CredentialCache]::DefaultCredentials } catch {}
    $rs = $rq.GetResponse()
    try { $ms = New-Object IO.MemoryStream; $rs.GetResponseStream().CopyTo($ms); $b = $ms.ToArray() } finally { $rs.Close() }
    if ($Bytes) { return ,$b }
    return [Text.Encoding]::UTF8.GetString($b)
}
function Compare-GBVer($a, $b) { try { return ([version]$a).CompareTo([version]$b) } catch { return 0 } }
# Version Windows du pilote NVIDIA (32.0.16.2101) -> version NVIDIA (621.01)
function ConvertTo-GBNvVersion($v) {
    $p = ([string]$v).Split('.'); if ($p.Count -lt 4) { return $null }
    $d = $p[2] + $p[3].PadLeft(4, '0'); if ($d.Length -lt 5) { return $null }
    $d = $d.Substring($d.Length - 5)
    return ([string][int]$d.Substring(0, 3)) + '.' + $d.Substring(3)
}
function Get-GBNvNorm($s) { return (([string]$s).ToLower() -replace '\(r\)|\(tm\)|nvidia', '' -replace '[^a-z0-9]', '') }
# "2026 octobre 21" (date renvoyee par NVIDIA en francais)
function ConvertFrom-GBFrDate($s) {
    if ([string]$s -notmatch '(\d{4})\D+?([a-zA-ZÀ-ÿ]+)\D+?(\d{1,2})') { return $null }
    $mo = $Matches[2].ToLower(); $y = [int]$Matches[1]; $d = [int]$Matches[3]
    $map = @(@('^jan', 1), @('^f', 2), @('^mar', 3), @('^avr', 4), @('^mai', 5), @('^juin', 6), @('^juil', 7), @('^ao', 8), @('^sep', 9), @('^oct', 10), @('^nov', 11), @('^d', 12))
    foreach ($m in $map) { if ($mo -match $m[0]) { try { return (Get-Date -Year $y -Month $m[1] -Day $d).Date } catch { return $null } } }
    return $null
}
# Version "Adrenalin" installee (ex. 26.10.1), lue dans la cle du pilote d'affichage
function Get-GBAmdInstalled($pnp) {
    $cls = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
    $dev = ([regex]::Match([string]$pnp, 'VEN_1002&DEV_[0-9A-Fa-f]{4}')).Value
    foreach ($k in @(Get-ChildItem -LiteralPath $cls -ErrorAction SilentlyContinue)) {
        try {
            $v = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction Stop
            if ($dev -and ([string]$v.MatchingDeviceId) -notmatch [regex]::Escape($dev)) { continue }
            if ($v.RadeonSoftwareVersion) { return [string]$v.RadeonSoftwareVersion }
        } catch {}
    }
    return $null
}
# $gpus : liste de @{ Name; Pnp; DriverVersion } ; $cache : resultats precedents (moins de 12 h) a reutiliser
function Get-GBGpuLatest($gpus, [bool]$isLaptop, [int]$build, [bool]$is64, $cache) {
    $out = New-Object System.Collections.ArrayList
    $nvProd = $null; $nvSeries = $null; $intelCat = $null; $amdLatest = $null; $amdTried = $false
    foreach ($g in $gpus) {
        $pnp = [string]$g.Pnp; $name = [string]$g.Name
        $r = [pscustomobject]@{ Vendor = ''; Name = $name; Pnp = $pnp; Installed = [string]$g.DriverVersion; Latest = $null; Date = $null
                                Kind = ''; Url = ''; File = ''; State = 'unknown'; Note = ''; Checked = (Get-Date).ToString('o') }
        if ($pnp -match 'VEN_10DE') { $r.Vendor = 'NVIDIA'; $r.Installed = ConvertTo-GBNvVersion $g.DriverVersion }
        elseif ($pnp -match 'VEN_1002') { $r.Vendor = 'AMD'; $r.Installed = Get-GBAmdInstalled $pnp }
        elseif ($pnp -match 'VEN_8086') { $r.Vendor = 'Intel' }
        else { continue }   # adaptateurs virtuels (Microsoft, bureau a distance...)
        $old = @($cache | Where-Object { $_ -and $_.Pnp -eq $pnp -and $_.Latest }) | Select-Object -First 1
        try {
            if ($old) {
                $r.Latest = $old.Latest; $r.Date = $old.Date; $r.Kind = $old.Kind; $r.Url = $old.Url; $r.File = $old.File; $r.Note = $old.Note; $r.Checked = $old.Checked
            }
            elseif ($r.Vendor -eq 'NVIDIA') {
                if (-not $nvProd) {
                    $nvProd = ([xml](Get-GBWeb 'https://www.nvidia.com/Download/API/lookupValueSearch.aspx?TypeID=3')).LookupValueSearch.LookupValues.LookupValue
                    $nvSeries = ([xml](Get-GBWeb 'https://www.nvidia.com/Download/API/lookupValueSearch.aspx?TypeID=2')).LookupValueSearch.LookupValues.LookupValue
                }
                $nb = @{}; foreach ($s in $nvSeries) { if ([string]$s.Name -match 'Notebook') { $nb[[string]$s.Value] = $true } }
                $want = Get-GBNvNorm $name
                $cands = @($nvProd | Where-Object { (Get-GBNvNorm $_.Name) -eq $want })
                if ($cands.Count -eq 0 -and $want -match 'laptopgpu$') { $w2 = $want -replace 'laptopgpu$', ''; $cands = @($nvProd | Where-Object { (Get-GBNvNorm $_.Name) -eq $w2 -and $nb[[string]$_.ParentID] }) }
                $pick = $null
                foreach ($c in $cands) { if ([bool]$nb[[string]$c.ParentID] -eq $isLaptop) { $pick = $c; break } }
                if (-not $pick -and $cands.Count -gt 0) { $pick = $cands[0] }
                if ($pick) {
                    $os = 135; if (-not $is64) { $os = 56 } elseif ($build -lt 22000) { $os = 57 }
                    $u = 'https://gfwsl.geforce.com/services_toolkit/services/com/nvidia/services/AjaxDriverService.php?func=DriverManualLookup&psid=' + $pick.ParentID +
                         '&pfid=' + $pick.Value + '&osID=' + $os + '&languageCode=1036&isWHQL=1&dch=1&sort1=0&numberOfResults=1'
                    $j = (Get-GBWeb $u) | ConvertFrom-Json
                    $i = $null; if ($j.IDS) { $i = $j.IDS[0].downloadInfo }
                    if ($i -and $i.Version) {
                        $r.Latest = [string]$i.Version; $dt = ConvertFrom-GBFrDate $i.ReleaseDateTime; if ($dt) { $r.Date = $dt.ToString('dd/MM/yyyy') }
                        $r.Kind = [uri]::UnescapeDataString([string]$i.Name); $r.Url = [string]$i.DetailsURL; $r.File = [string]$i.DownloadURL
                    }
                } else { $r.Note = "modele non trouve sur le site NVIDIA" }
            }
            elseif ($r.Vendor -eq 'Intel') {
                if (-not $intelCat) {
                    Add-Type -AssemblyName System.IO.Compression
                    $zb = Get-GBWeb 'https://dsadata.intel.com/data/en' -Bytes
                    $z = New-Object IO.Compression.ZipArchive((New-Object IO.MemoryStream(, $zb)))
                    $e = $z.Entries | Where-Object { $_.FullName -eq 'software-configurations.json' } | Select-Object -First 1
                    $sr = New-Object IO.StreamReader($e.Open()); $intelCat = $sr.ReadToEnd() | ConvertFrom-Json; $sr.Dispose(); $z.Dispose()
                }
                $dev = ([regex]::Match($pnp, 'VEN_8086&DEV_[0-9A-Fa-f]{4}')).Value
                $best = $null
                foreach ($s in $intelCat) {
                    $hit = $false
                    foreach ($c in @($s.Components)) { if ([string]$c.Category -match 'Graphics' -and (@($c.DetectionValues) -join ' ') -match [regex]::Escape($dev)) { $hit = $true; break } }
                    if ($hit -and (-not $best -or (Compare-GBVer $s.Version $best.Version) -gt 0)) { $best = $s }
                }
                if ($best) {
                    $r.Latest = [string]$best.Version; try { $r.Date = ([datetime]$best.DisplayReleaseDate).ToString('dd/MM/yyyy') } catch {}
                    $r.Kind = [string]$best.Name; $r.Url = [string]$best.Url; $f = @($best.Files) | Select-Object -First 1; if ($f) { $r.File = [string]$f.Url }
                    if ($isLaptop) { $r.Note = "sur un portable, le fabricant du PC peut imposer sa propre version" }
                } else { $r.Note = "puce absente du catalogue Intel (ancienne ou specifique au fabricant du PC)" }
            }
            elseif ($r.Vendor -eq 'AMD') {
                $r.Url = 'https://www.amd.com/fr/support/download/drivers.html'
                if ($name -match 'RX\s*[45]\d0\b|Vega|R9 |R7 |R5 |HD \d|FirePro') { $r.Note = "carte suivie par une branche de pilotes AMD separee : voir le site AMD" }
                else {
                    if (-not $amdTried) {
                        $amdTried = $true
                        $h = Get-GBWeb 'https://www.amd.com/en/support/downloads/drivers.html/graphics/radeon-rx/radeon-rx-7000-series/amd-radeon-rx-7800-xt.html'
                        $m = [regex]::Match($h, 'Adrenalin (?:Edition )?(\d{2}\.\d{1,2}\.\d{1,2})')
                        if ($m.Success) { $amdLatest = $m.Groups[1].Value }
                    }
                    if ($amdLatest) { $r.Latest = $amdLatest; $r.Kind = 'AMD Software: Adrenalin Edition' }
                }
            }
        } catch { $r.Note = "site du fabricant injoignable (" + $_.Exception.Message + ")" }
        if ($r.Latest -and $r.Installed) { if ((Compare-GBVer $r.Latest $r.Installed) -gt 0) { $r.State = 'update' } else { $r.State = 'ok' } }
        [void]$out.Add($r)
    }
    return $out.ToArray()
}
# Cartes graphiques reelles du PC (sans les adaptateurs virtuels)
function Get-GBGpuList {
    return @(Get-CimInstance Win32_VideoController -ErrorAction SilentlyContinue | Where-Object { [string]$_.PNPDeviceID -match '^PCI\\VEN_(10DE|1002|8086)' } |
             ForEach-Object { @{ Name = [string]$_.Name; Pnp = [string]$_.PNPDeviceID; DriverVersion = [string]$_.DriverVersion } })
}
'@
. ([scriptblock]::Create($Script:GpuLatestFn))

$Script:DriverScanScript = {
    param($sync)
    function Get-WUErrorText($ex) {
        $code = ''
        try { $code = '0x{0:X8}' -f $ex.HResult } catch {}
        switch ($code) {
            '0x80070422' { return "Le service Windows Update est desactive sur ce PC (Services > Windows Update > Manuel)." }
            '0x8024402C' { return "Pas de connexion a Windows Update (verifie internet)." }
            '0x80072EE2' { return "Windows Update ne repond pas (delai depasse). Reessaie plus tard." }
            '0x80072EE7' { return "Pas de connexion a Windows Update (verifie internet)." }
            '0x80072EFD' { return "Pas de connexion a Windows Update (verifie internet / pare-feu)." }
            '0x8024001E' { return "Windows Update est occupe ou un redemarrage est en attente. Redemarre puis reessaie." }
            '0x8024002E' { return "Windows Update est bloque par une regle (PC d'entreprise ou d'ecole)." }
            '0x8024401F' { return "Le serveur de mises a jour de l'entreprise/ecole refuse la demande." }
        }
        return ($ex.Message + " (" + $code + ")")
    }
    try {
        # 1. Tous les peripheriques et leurs identifiants materiels (pour relier chaque mise a jour a son composant)
        $sync.Status = "Analyse des composants..."
        $classes = @{ 'DISPLAY' = 'Carte graphique'; 'NET' = 'Reseau'; 'MEDIA' = 'Audio'; 'BLUETOOTH' = 'Bluetooth'; 'HDC' = 'Stockage';
                      'SCSIADAPTER' = 'Stockage'; 'USB' = 'USB'; 'SYSTEM' = 'Chipset'; 'MONITOR' = 'Ecran'; 'CAMERA' = 'Camera'; 'IMAGE' = 'Camera' }
        $extraTypes = @{ 'FIRMWARE' = 'Firmware / BIOS'; 'SOFTWARECOMPONENT' = 'Logiciel du fabricant'; 'EXTENSION' = 'Extension de pilote'; 'SYSTEM' = 'Systeme / chipset';
                         'HIDCLASS' = 'Peripherique (HID)'; 'BIOMETRIC' = 'Biometrie'; 'SENSOR' = 'Capteurs'; 'BATTERY' = 'Batterie'; 'SECURITYDEVICES' = 'Securite (TPM)';
                         'KEYBOARD' = 'Clavier'; 'MOUSE' = 'Souris / pave tactile'; 'AUDIOENDPOINT' = 'Audio'; 'PRINTER' = 'Imprimante'; 'NET' = 'Reseau'; 'MEDIA' = 'Audio';
                         'DISPLAY' = 'Carte graphique'; 'BLUETOOTH' = 'Bluetooth'; 'USB' = 'USB'; 'CAMERA' = 'Camera'; 'IMAGE' = 'Camera'; 'HDC' = 'Stockage'; 'SCSIADAPTER' = 'Stockage' }
        $devById = @{}; $hwToDev = @{}; $compToDev = @{}
        $allDevs = @(Get-CimInstance Win32_PnPEntity -ErrorAction SilentlyContinue)
        foreach ($pe in $allDevs) {
            $did = ([string]$pe.DeviceID).ToUpper()
            if (-not $did) { continue }
            $devById[$did] = $pe
            foreach ($hid in @($pe.HardwareID)) {
                if (-not $hid) { continue }; $k = ([string]$hid).ToLower()
                if (-not $hwToDev.ContainsKey($k)) { $hwToDev[$k] = New-Object System.Collections.ArrayList }
                if (-not $hwToDev[$k].Contains($did)) { [void]$hwToDev[$k].Add($did) }
            }
            foreach ($cid in @($pe.CompatibleID)) {
                if (-not $cid) { continue }; $k = ([string]$cid).ToLower()
                if (-not $compToDev.ContainsKey($k)) { $compToDev[$k] = New-Object System.Collections.ArrayList }
                if (-not $compToDev[$k].Contains($did)) { [void]$compToDev[$k].Add($did) }
            }
        }
        $seen = @{}; $sdByDev = @{}
        $comps = New-Object System.Collections.ArrayList
        foreach ($d in @(Get-CimInstance Win32_PnPSignedDriver -ErrorAction Stop)) {
            $did = ([string]$d.DeviceID).ToUpper()
            if ($did) { $sdByDev[$did] = $d }
            if (-not $d.DeviceName -or -not $d.DriverVersion) { continue }
            $cls = ([string]$d.DeviceClass).ToUpper()
            if (-not $classes.ContainsKey($cls)) { continue }
            if ($cls -eq 'USB' -and $d.DeviceName -notmatch 'xHCI|eXtensible|USB 3|USB4|Thunderbolt') { continue }
            if ($cls -eq 'SYSTEM' -and $d.DeviceName -notmatch 'Chipset|SMBus|Management Engine|Serial IO|GPIO|PSP|Platform Security|Dynamic Tuning|Thunderbolt|PCI Express Root|GNA|NPU|Neural') { continue }
            $key = $d.DeviceName + '|' + $d.DriverVersion
            if ($seen.ContainsKey($key)) { $seen[$key].Count++; if ($did) { [void]$seen[$key].DevIds.Add($did) }; continue }
            $date = $null; try { $date = [datetime]$d.DriverDate } catch {}
            $ids = New-Object System.Collections.ArrayList; if ($did) { [void]$ids.Add($did) }
            $c = [pscustomobject]@{ Type = $classes[$cls]; Name = [string]$d.DeviceName; Maker = [string]$d.Manufacturer; Version = [string]$d.DriverVersion;
                                    Date = $date; HwId = [string]$d.HardWareID; Class = $cls; Count = 1; DevIds = $ids;
                                    Updates = (New-Object System.Collections.ArrayList); Problem = $null }
            $seen[$key] = $c
            [void]$comps.Add($c)
        }
        $codes = @{ 1 = 'Non configure'; 3 = 'Pilote corrompu'; 10 = 'Ne demarre pas'; 12 = 'Ressources en conflit'; 18 = 'A reinstaller'; 19 = 'Registre endommage';
                    21 = 'En cours de suppression'; 22 = 'Desactive'; 28 = 'Aucun pilote installe'; 31 = 'Ne fonctionne pas'; 32 = 'Service desactive';
                    37 = 'Echec du pilote'; 39 = 'Pilote manquant ou corrompu'; 40 = 'Erreur de registre'; 41 = 'Materiel introuvable'; 43 = 'Arrete par Windows (erreur)';
                    48 = 'Pilote bloque (incompatible)'; 52 = 'Pilote non signe' }
        $probs = New-Object System.Collections.ArrayList
        foreach ($pe in $allDevs) {
            $code = [int]$pe.ConfigManagerErrorCode
            if ($code -eq 0 -or $code -eq 24 -or $code -eq 45) { continue }   # 24/45 = appareils debranches
            $txt = $codes[$code]; if (-not $txt) { $txt = 'Probleme' }
            $nm = [string]$pe.Name; if (-not $nm) { $nm = [string]$pe.DeviceID }
            $pc = ([string]$pe.PNPClass).ToUpper()
            $ptype = $extraTypes[$pc]; if (-not $ptype) { $ptype = 'Peripherique' }
            $ids = New-Object System.Collections.ArrayList; [void]$ids.Add(([string]$pe.DeviceID).ToUpper())
            [void]$probs.Add([pscustomobject]@{ Type = $ptype; Name = $nm; Maker = [string]$pe.Manufacturer; Version = ''; Date = $null; HwId = [string]@($pe.HardwareID)[0];
                                                Class = $pc; Count = 1; DevIds = $ids; Updates = (New-Object System.Collections.ArrayList);
                                                Problem = ("PROBLEME : " + $txt); Code = $code })
        }
        $bios = ""
        try {
            $bi = Get-CimInstance Win32_BIOS; $bb = Get-CimInstance Win32_BaseBoard
            $bd = ""; try { $bd = ([datetime]$bi.ReleaseDate).ToString('dd/MM/yyyy') } catch {}
            $bios = "Carte mere : " + $bb.Manufacturer + " " + $bb.Product + "  |  BIOS " + $bi.SMBIOSBIOSVersion + " du " + $bd
        } catch {}
        $sync.Bios = $bios
        $sync.Probs = $probs.ToArray()
        $sync.Comps = $comps.ToArray()

        # 1b. Derniere version officielle du pilote de chaque carte graphique (sites NVIDIA / AMD / Intel)
        $sync.Status = "Recherche du dernier pilote de la carte graphique..."
        try { . ([scriptblock]::Create($sync.Fn)); $sync.Gpu = @(Get-GBGpuLatest (Get-GBGpuList) $sync.IsLaptop $sync.Build $sync.Is64 $null) } catch {}

        # 2. Pilotes disponibles sur Windows Update (valides par Microsoft pour ce materiel exact)
        $sync.Status = "Recherche des pilotes sur Windows Update (1 a 3 minutes)..."
        $session = New-Object -ComObject Microsoft.Update.Session
        $session.ClientApplicationID = 'GameBoost'
        $searcher = $session.CreateUpdateSearcher()
        $searcher.Online = $true
        try { $searcher.ServerSelection = 2 } catch {}
        $res = $searcher.Search("IsInstalled=0 and IsHidden=0")
        $drv = New-Object System.Collections.ArrayList
        $soft = 0
        for ($i = 0; $i -lt $res.Updates.Count; $i++) {
            $u = $res.Updates.Item($i)
            if ([int]$u.Type -ne 2) { $soft++; continue }
            $vd = $null; try { $vd = [datetime]$u.DriverVerDate } catch {}
            # A quel composant s'applique ce pilote ? (identifiant materiel exact, puis compatible, puis nom du modele)
            $hw = ([string]$u.DriverHardwareID).ToLower()
            $targets = @()
            if ($hw -and $hwToDev.ContainsKey($hw)) { $targets = @($hwToDev[$hw]) }
            elseif ($hw -and $compToDev.ContainsKey($hw)) { $targets = @($compToDev[$hw]) }
            $model = [string]$u.DriverModel
            if ($targets.Count -eq 0 -and $model) { $targets = @($devById.Keys | Where-Object { [string]$devById[$_].Name -eq $model }) }
            $tname = ''; $tclass = ''
            if ($targets.Count -gt 0) {
                $d0 = $devById[$targets[0]]; $tname = [string]$d0.Name; $tclass = ([string]$d0.PNPClass).ToUpper()
                if ($targets.Count -gt 1) { $tname += " (x" + $targets.Count + ")" }
            } elseif ($model) { $tname = $model }
            $ver = ''; if ([string]$u.Title -match '(\d+(\.\d+){2,3})') { $ver = $Matches[1] }
            [void]$drv.Add([pscustomobject]@{ Id = [string]$u.Identity.UpdateID; Title = [string]$u.Title; Class = [string]$u.DriverClass;
                                               Maker = [string]$u.DriverManufacturer; HwId = [string]$u.DriverHardwareID; Date = $vd;
                                               SizeMo = [math]::Round([double]$u.MaxDownloadSize / 1MB, 1); Model = $model;
                                               Targets = $targets; TargetName = $tname; TargetClass = $tclass; Version = $ver })
        }
        # Rattache chaque mise a jour a son composant (ou cree la ligne si le composant n'etait pas affiche)
        $byDev = @{}
        foreach ($c in $comps) { foreach ($did in $c.DevIds) { $byDev[$did] = $c } }
        foreach ($pr in $probs) { foreach ($did in $pr.DevIds) { $byDev[$did] = $pr } }
        foreach ($upd in $drv) {
            $linked = @{}
            foreach ($did in $upd.Targets) {
                $c = $byDev[$did]
                if ($c -and -not $linked.ContainsKey($c.Name)) { [void]$c.Updates.Add($upd); $linked[$c.Name] = $true }
            }
            if ($linked.Count -eq 0 -and $upd.Targets.Count -gt 0) {
                $d0 = $devById[$upd.Targets[0]]
                $cls = ([string]$d0.PNPClass).ToUpper()
                $type = $extraTypes[$cls]; if (-not $type) { if ($cls) { $type = $cls } else { $type = 'Autre' } }
                $sd = $sdByDev[$upd.Targets[0]]
                $cv = ''; $cd = $null
                if ($sd) { $cv = [string]$sd.DriverVersion; try { $cd = [datetime]$sd.DriverDate } catch {} }
                $ids = New-Object System.Collections.ArrayList; foreach ($t in $upd.Targets) { [void]$ids.Add($t) }
                $ups = New-Object System.Collections.ArrayList; [void]$ups.Add($upd)
                $c = [pscustomobject]@{ Type = $type; Name = [string]$d0.Name; Maker = [string]$d0.Manufacturer; Version = $cv; Date = $cd; HwId = $upd.HwId;
                                        Class = $cls; Count = $upd.Targets.Count; DevIds = $ids; Updates = $ups; Problem = $null }
                [void]$comps.Add($c)
                foreach ($t in $upd.Targets) { $byDev[$t] = $c }
            }
        }
        $sync.Comps = $comps.ToArray()
        $sync.Probs = $probs.ToArray()
        $sync.Drivers = $drv.ToArray()
        $sync.SoftCount = $soft
        $sync.Status = "Analyse terminee"
    } catch {
        $sync.Error = Get-WUErrorText $_.Exception
    } finally { $sync.Done = $true }
}

$Script:DriverInstallScript = {
    param($sync, $ids)
    try {
        $sync.Status = "Preparation de l'installation..."
        $session = New-Object -ComObject Microsoft.Update.Session
        $session.ClientApplicationID = 'GameBoost'
        $searcher = $session.CreateUpdateSearcher()
        $searcher.Online = $true
        try { $searcher.ServerSelection = 2 } catch {}
        $res = $searcher.Search("IsInstalled=0 and Type='Driver' and IsHidden=0")
        $coll = New-Object -ComObject Microsoft.Update.UpdateColl
        for ($i = 0; $i -lt $res.Updates.Count; $i++) {
            $u = $res.Updates.Item($i)
            if ($ids -notcontains [string]$u.Identity.UpdateID) { continue }
            if (-not $u.EulaAccepted) { [void]$sync.Lines.Add("Ignore (licence a accepter dans Windows Update) : " + $u.Title); continue }
            [void]$coll.Add($u)
        }
        if ($coll.Count -eq 0) { $sync.Error = "Aucun des pilotes choisis n'est encore a installer (deja installe ?)."; return }
        $sync.Status = "Telechargement de " + $coll.Count + " pilote(s)..."
        $dl = $session.CreateUpdateDownloader()
        $dl.Updates = $coll
        [void]$dl.Download()
        $sync.Status = "Installation de " + $coll.Count + " pilote(s) - n'eteins pas le PC..."
        $inst = $session.CreateUpdateInstaller()
        $inst.Updates = $coll
        $ir = $inst.Install()
        $txtCodes = @{ 2 = 'installe'; 3 = 'installe (avec avertissements)'; 4 = 'ECHEC'; 5 = 'annule' }
        for ($i = 0; $i -lt $coll.Count; $i++) {
            $r = $ir.GetUpdateResult($i)
            $t = $txtCodes[[int]$r.ResultCode]; if (-not $t) { $t = 'code ' + $r.ResultCode }
            if ([int]$r.ResultCode -ge 4) { try { $t += ' (0x{0:X8})' -f $r.HResult } catch {} }
            if ([int]$r.ResultCode -le 3) { $sync.OkCount++ } else { $sync.FailCount++ }
            [void]$sync.Lines.Add($coll.Item($i).Title + " : " + $t)
        }
        $sync.Reboot = [bool]$ir.RebootRequired
    } catch {
        $code = ''; try { $code = ' (0x{0:X8})' -f $_.Exception.HResult } catch {}
        $sync.Error = $_.Exception.Message + $code
    } finally { $sync.Done = $true }
}

function Start-BackgroundTask($sb, $sync, $arg2) {
    $ps = [powershell]::Create()
    [void]$ps.AddScript($sb).AddArgument($sync)
    if ($null -ne $arg2) { [void]$ps.AddArgument($arg2) }
    return @{ PS = $ps; Handle = $ps.BeginInvoke() }
}

function Stop-BackgroundTask($task) {
    if (-not $task) { return }
    try { [void]$task.PS.EndInvoke($task.Handle) } catch {}
    try { $task.PS.Dispose() } catch {}
}

# --- Verifications au demarrage, en arriere-plan ------------------------------------
$Script:StartupCheckScript = {
    param($sync)
    try {
        $cpu = (Get-CimInstance Win32_Processor | Select-Object -First 1).Name.Trim()
        $gpu = (@(Get-CimInstance Win32_VideoController | Select-Object -ExpandProperty Name) -join " + ")
        $os = Get-CimInstance Win32_OperatingSystem
        $ram = [math]::Round([double]$os.TotalVisibleMemorySize / 1MB, 1)
        $sync.SysLine = "PC : " + $sync.PcType + " | " + $cpu + " (" + $sync.Cores + " threads) | " + $gpu + " | " + $ram + " Go RAM | " + $os.Caption + " " + $os.BuildNumber
    } catch {}
    try { $t = Get-ScheduledTask -TaskName 'GameBoost' -ErrorAction Stop; $sync.TaskExists = $true; $sync.TaskExe = [string](@($t.Actions)[0].Execute) } catch { $sync.TaskExists = $false }
    $sync.InfoDone = $true
    try {
        . ([scriptblock]::Create($sync.Fn))
        $sync.Gpu = @(Get-GBGpuLatest (Get-GBGpuList) $sync.IsLaptop $sync.Build $sync.Is64 $sync.Cache)
    } catch { $sync.GpuError = $_.Exception.Message }
    $sync.Done = $true
}

# Resultats precedents de moins de 12 h (pas d'acces internet a chaque lancement)
function Get-GpuLatestCache {
    try {
        if (-not (Test-Path -LiteralPath $Script:GpuCacheFile)) { return $null }
        $c = Get-Content -LiteralPath $Script:GpuCacheFile -Raw -Encoding UTF8 | ConvertFrom-Json
        if (((Get-Date) - [datetime]::Parse([string]$c.Time, [Globalization.CultureInfo]::InvariantCulture)).TotalHours -lt 12) { return @($c.Items) }
    } catch {}
    return $null
}
function Save-GpuLatestCache($items) {
    if (@($items | Where-Object { $_.Latest }).Count -eq 0) { return }
    try { @{ Time = (Get-Date).ToString('o'); Items = @($items) } | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $Script:GpuCacheFile -Encoding UTF8 } catch {}
}

# Affiche le resultat : journal + bouton "Mises a jour pilotes" en jaune si un nouveau pilote existe
function Set-GpuLatestResult($items, [bool]$announce) {
    $Script:GpuLatest = @($items)
    $upd = @($Script:GpuLatest | Where-Object { $_.State -eq 'update' })
    if ($upd.Count -gt 0) {
        $u = $upd[0]
        $btnDrivers.Text = "NOUVEAU PILOTE GPU !"; $btnDrivers.ForeColor = $cYellow
        $tip.SetToolTip($btnDrivers, ("Nouveau pilote " + $u.Vendor + " " + $u.Latest + " disponible pour " + $u.Name + " (tu as la " + $u.Installed + "). Clique pour le telecharger depuis le site officiel."))
        Set-GBDriverNotice ("Pilote " + $u.Vendor + " " + $u.Latest + " pour " + $u.Name + " (tu as la " + $u.Installed + "). Clique pour l'installer.")
        if ($announce) { Log ("Carte graphique : nouveau pilote " + $u.Vendor + " " + $u.Latest + $(if ($u.Date) { " du " + $u.Date } else { "" }) + " disponible (installe : " + $u.Installed + ") -> Outils > Pilotes") }
    } else {
        $btnDrivers.Text = "PILOTES"; $btnDrivers.ForeColor = $cCyan
        Set-GBDriverNotice ""
        if ($announce) {
            foreach ($g in @($Script:GpuLatest | Where-Object { $_.State -eq 'ok' })) { Log ("Carte graphique : pilote " + $g.Vendor + " a jour (" + $g.Installed + ", derniere version " + $g.Latest + ") - " + $g.Name) }
        }
    }
}

function Get-GpuLatestFor($name) { return (@($Script:GpuLatest | Where-Object { $_ -and $_.Name -eq $name }) | Select-Object -First 1) }

# Telechargement du pilote officiel (installeur du fabricant) ou de sa page
function Open-GpuLatestDriver($gl) {
    $msg = "Nouveau pilote " + $gl.Vendor + " " + $gl.Latest + $(if ($gl.Date) { " du " + $gl.Date } else { "" }) + " pour :`r`n" + $gl.Name +
           "`r`n`r`nTu as la version " + $gl.Installed + "." + $(if ($gl.Kind) { "`r`n(" + $gl.Kind + ")" } else { "" })
    if ($gl.Note) { $msg += "`r`n`r`nA savoir : " + $gl.Note + "." }
    if ($gl.File) {
        $msg += "`r`n`r`nOui = telecharger l'installeur officiel (dans ton navigateur), puis lance-le.`r`nNon = ouvrir la page du pilote sur le site du fabricant."
        $r = [System.Windows.Forms.MessageBox]::Show($msg, "GameBoost - Pilote de la carte graphique", "YesNoCancel", "Information")
        if ($r -eq "Yes") { Start-Process $gl.File; Log ("Telechargement du pilote " + $gl.Vendor + " " + $gl.Latest + " : " + $gl.File) }
        elseif ($r -eq "No" -and $gl.Url) { Start-Process $gl.Url }
    } else {
        $msg += "`r`n`r`nOuvrir la page officielle des pilotes " + $gl.Vendor + " ?"
        if ([System.Windows.Forms.MessageBox]::Show($msg, "GameBoost - Pilote de la carte graphique", "YesNo", "Information") -eq "Yes") { Start-Process $gl.Url }
    }
}

function Start-StartupChecks {
    $cache = Get-GpuLatestCache
    $type = "PC fixe"; if ($Script:IsLaptop) { $type = "PC portable" }
    $Script:StartSync = [hashtable]::Synchronized(@{ Fn = $Script:GpuLatestFn; PcType = $type; Cores = $Script:Cores; IsLaptop = [bool]$Script:IsLaptop
                                                     Build = [int]$Script:WinBuild; Is64 = [Environment]::Is64BitOperatingSystem; Cache = $cache
                                                     InfoDone = $false; Done = $false; InfoShown = $false })
    $Script:StartTask = Start-BackgroundTask $Script:StartupCheckScript $Script:StartSync $null
    $Script:StartPoll = New-Object System.Windows.Forms.Timer
    $Script:StartPoll.Interval = 400
    $Script:StartPoll.Add_Tick({
        $s = $Script:StartSync
        if ($s.InfoDone -and -not $s.InfoShown) {
            $s.InfoShown = $true
            if ($s.SysLine) { Log $s.SysLine }
            # Lancement automatique : etat reel + mise a jour si GameBoost.exe a ete deplace
            if ($s.TaskExists) {
                $Script:InitUI = $true; $chkStartup.Checked = $true; $Script:InitUI = $false
                if ($Script:ExePath -and $s.TaskExe -ne $Script:ExePath) { [void](Set-StartupTask $true) }
            }
        }
        if (-not $s.Done) { return }
        $Script:StartPoll.Stop(); $Script:StartPoll.Dispose()
        Stop-BackgroundTask $Script:StartTask; $Script:StartTask = $null
        if ($s.Gpu) {
            if (-not $s.Cache) { Save-GpuLatestCache $s.Gpu }
            Set-GpuLatestResult $s.Gpu $true
        }
    })
    $Script:StartPoll.Start()
}

function Open-GpuVendorTool($comps, [switch]$Exact) {
    $gpus = @($comps | Where-Object { $_.Class -eq 'DISPLAY' } | ForEach-Object { $_.Name + ' ' + $_.Maker })
    $all = $gpus -join ' '
    # Par defaut : l'appli du fabricant de la carte dediee (celle des jeux)
    if (-not $Exact -and $Script:MainGpu -and $Script:MainGpu.Kind -eq 'dediee') { $all = $Script:MainGpu.Name }
    $pf = $env:ProgramFiles
    if ($all -match 'NVIDIA') {
        $app = Join-Path $pf 'NVIDIA Corporation\NVIDIA app\CEF\NVIDIA app.exe'
        if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app; Log "Ouverture de NVIDIA App"; return }
        Start-Process "https://www.nvidia.com/fr-fr/software/nvidia-app/"; Log "Ouverture de la page officielle NVIDIA App"; return
    }
    if ($all -match 'Radeon|AMD') {
        $app = Join-Path $pf 'AMD\CNext\CNext\RadeonSoftware.exe'
        if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app; Log "Ouverture d'AMD Software Adrenalin"; return }
        Start-Process "https://www.amd.com/fr/support/downloads/drivers.html"; Log "Ouverture de la page officielle des pilotes AMD"; return
    }
    if ($all -match 'Intel') { Start-Process "https://www.intel.com/content/www/fr/fr/support/detect.html"; Log "Ouverture d'Intel Driver & Support Assistant"; return }
    [System.Windows.Forms.MessageBox]::Show("Carte graphique non reconnue : utilise Windows Update.", "GameBoost") | Out-Null
}

function Show-DriverCenter {
    if ($Script:Boosted) {
        [System.Windows.Forms.MessageBox]::Show("Arrete d'abord le boost : Windows Update est mis en pause pendant le jeu.", "GameBoost") | Out-Null
        return
    }
    $dc = @{ Task = $null; Sync = $null; Mode = ''; Comps = @(); Drivers = @() }
    $f = New-Object System.Windows.Forms.Form
    Register-GBDpi $f
    $f.Text = "GameBoost - Composants et mises a jour des pilotes"
    $f.Size = New-Object System.Drawing.Size(956, 720)
    $f.StartPosition = "CenterParent"; $f.BackColor = $cBg; $f.ForeColor = $cText; $f.Font = $fontUI
    $f.FormBorderStyle = "FixedSingle"; $f.MaximizeBox = $false
    Set-GBDarkWindow $f
    if ($form.Icon) { $f.Icon = $form.Icon }

    function Add-Ctl($c) { $f.Controls.Add($c); return $c }
    function New-Lbl($t, $x, $y, $w, $h, $font, $color) {
        $l = New-Object System.Windows.Forms.Label; $l.Text = $t; $l.Location = New-Object System.Drawing.Point($x, $y)
        $l.Size = New-Object System.Drawing.Size($w, $h); $l.Font = $font; $l.ForeColor = $color; [void](Add-Ctl $l); return $l
    }
    function New-Btn($t, $x, $y, $w) {
        $b = New-GBButtonCtl; $b.Text = $t; $b.Location = New-Object System.Drawing.Point($x, $y)
        $b.Size = New-Object System.Drawing.Size($w, 30); [void](Add-Ctl $b); return $b
    }
    function New-LV($x, $y, $w, $h, $cols, $checks) {
        $lv = New-Object System.Windows.Forms.ListView
        $lv.Location = New-Object System.Drawing.Point($x, $y); $lv.Size = New-Object System.Drawing.Size($w, $h)
        $lv.View = "Details"; $lv.FullRowSelect = $true; $lv.CheckBoxes = $checks; $lv.HideSelection = $false
        $lv.BackColor = $cPanel; $lv.ForeColor = $cText; $lv.BorderStyle = "FixedSingle"
        foreach ($c in $cols) { [void]$lv.Columns.Add($c[0], $c[1]) }
        if ($Script:UiOK) {
            # En-tetes de colonnes sombres (theme neon) ; les lignes gardent le dessin Windows
            [GBTheme]::StyleList($lv, $fontBold, $cDeep, $cLine, $cCyan, $true)
            $lv.Columns[$lv.Columns.Count - 1].Width = -2   # derniere colonne jusqu'au bord (pas de zone blanche)
        } else { Set-GBDoubleBuffered $lv }
        [void](Add-Ctl $lv); return $lv
    }

    $null = New-Lbl "Composants et pilotes" 16 10 400 26 $fontBold $cGreen
    $lblD = New-Lbl "Demarrage de l'analyse..." 16 38 640 22 $fontUI $cText
    $pb = New-Object System.Windows.Forms.ProgressBar
    $pb.Location = New-Object System.Drawing.Point(670, 40); $pb.Size = New-Object System.Drawing.Size(254, 16); $pb.Style = "Marquee"
    [void](Add-Ctl $pb)
    $lvC = New-LV 16 64 908 248 @(@('Etat', 128), @('Type', 150), @('Composant', 262), @('Version actuelle', 112), @('Mise a jour proposee', 178), @('Date', 74)) $false
    $lblBios = New-Lbl "" 16 320 590 20 $fontUI $cMuted
    $btnComp = New-Btn "Mettre a jour ce composant" 614 316 310
    $btnComp.ForeColor = $cCyan
    $null = New-Lbl "Mises a jour disponibles (Windows Update, validees pour ton materiel) - double-clic sur un composant en haut = sa mise a jour" 16 350 908 20 $fontBold $cText
    $lvU = New-LV 16 372 908 198 @(@('Pilote', 300), @('Composant concerne', 285), @('Type', 135), @('Date', 85), @('Taille', 75)) $true
    $btnInst = New-Btn "Installer la selection" 16 580 190
    $btnInst.ForeColor = $cGreen; $btnInst.Enabled = $false
    $btnGpuV = New-Btn "Carte graphique : appli officielle" 214 580 240
    $btnWU   = New-Btn "Ouvrir Windows Update" 462 580 180
    $btnRe   = New-Btn "Relancer l'analyse" 650 580 140
    $btnCl   = New-Btn "Fermer" 798 580 126
    $null = New-Lbl ("Avant toute installation, un point de restauration Windows est cree. Windows Update ne propose que des pilotes testes pour ton materiel " +
                     "et plus recents que ceux installes. Pour la carte graphique, GameBoost compare aussi ta version a la derniere publiee sur le site de NVIDIA, AMD ou Intel. " +
                     "Les mises a jour de BIOS / firmware ne sont jamais cochees d'office : a choisir toi-meme, PC branche, sans l'eteindre pendant le redemarrage.") 16 618 908 56 $fontUI $cMuted

    $wuClassNames = @{ 'display' = 'Carte graphique'; 'net' = 'Reseau'; 'media' = 'Audio'; 'system' = 'Systeme / chipset'; 'firmware' = 'Firmware / BIOS';
                       'softwarecomponent' = 'Logiciel du fabricant'; 'extension' = 'Extension de pilote'; 'bluetooth' = 'Bluetooth'; 'camera' = 'Camera';
                       'image' = 'Camera'; 'usb' = 'USB'; 'hidclass' = 'Peripherique (HID)'; 'scsiadapter' = 'Stockage'; 'hdc' = 'Stockage';
                       'biometric' = 'Biometrie'; 'sensor' = 'Capteurs'; 'monitor' = 'Ecran'; 'printer' = 'Imprimante' }

    $fillComponents = {
        $lvC.BeginUpdate(); $lvC.Items.Clear()
        $rows = @(@($dc.Sync.Probs) + @($dc.Comps) | Where-Object { $_ })
        $gpuUpd = @{}; foreach ($g in @($Script:GpuLatest)) { if ($g -and $g.State -eq 'update') { $gpuUpd[$g.Name] = $true } }
        $sorted = @($rows | Sort-Object @{ Expression = { if ($_.Problem) { 0 } elseif (($_.Updates -and $_.Updates.Count -gt 0) -or $gpuUpd[$_.Name]) { 1 } else { 2 } } }, Type, Name)
        foreach ($c in $sorted) {
            $state = "OK"; $color = $cGreen; $prop = ""
            $nUpd = 0; if ($c.Updates) { $nUpd = $c.Updates.Count }
            $type = $c.Type
            $gi = $null; $gl = $null; $ver = $c.Version
            if ($c.Class -eq 'DISPLAY') {
                $gi = @($Script:GpuInv | Where-Object { $_.Name -eq $c.Name }) | Select-Object -First 1
                if ($gi -and $gi.Kind -eq 'dediee') { $type = 'Carte graphique dediee' } elseif ($gi -and $gi.Kind -eq 'integree') { $type = 'Puce graphique integree' }
                $gl = Get-GpuLatestFor $c.Name
                if ($gl -and $gl.Installed -and $gl.Installed -ne $c.Version) { $ver = $gl.Installed + "  (" + $c.Version + ")" }
            }
            $age = $null; if ($c.Date) { $age = [int]((Get-Date) - $c.Date).TotalDays }
            if ($nUpd -gt 0) {
                $u0 = $c.Updates[0]
                $prop = $u0.Version; if (-not $prop) { $prop = "nouvelle version" }
                if ($u0.Date) { $prop += " (" + $u0.Date.ToString('dd/MM/yyyy') + ")" }
                if ($nUpd -gt 1) { $prop += " +" + ($nUpd - 1) }
            }
            if ($c.Problem) {
                $state = $c.Problem; $color = $cRed
                if ($c.Code -eq 22) { $color = $cMuted }
                if ($nUpd -gt 0) { $prop = "Pilote dispo : " + $prop } elseif ($dc.Sync.Done) { $prop = "aucun pilote sur Windows Update" }
            }
            elseif ($c.Name -match 'Basic Display|de base Microsoft|Microsoft Basic Render') { $state = "Pilote generique !"; $color = $cRed; if (-not $prop) { $prop = "Installer le pilote du fabricant" } }
            elseif ($nUpd -gt 0) { $state = "Mise a jour dispo"; $color = $cYellow }
            elseif ($gl -and $gl.State -eq 'update') {
                $state = "Nouveau pilote"; $color = $cYellow
                $prop = $gl.Vendor + " " + $gl.Latest; if ($gl.Date) { $prop += " (" + $gl.Date + ")" }
            }
            elseif ($gl -and $gl.State -eq 'ok') { $prop = "A jour (derniere : " + $gl.Latest + ")" }
            elseif ($c.Class -eq 'DISPLAY') {
                $prop = "Verifier : " + (Get-GpuVendorToolName $c.Name)
                if ($gl -and $gl.Latest) { $prop = "Derniere " + $gl.Vendor + " : " + $gl.Latest }
                elseif (-not $dc.GpuShown -and -not $dc.Sync.Done) { $prop = "recherche du dernier pilote..." }
                if ($null -ne $age -and $age -gt 180 -and $gi -and $gi.Kind -eq 'dediee') { $state = "Ancien (" + $age + " j)"; $color = $cYellow }
            }
            elseif (-not $dc.Sync.Done) { $state = "..."; $color = $cMuted; $prop = "recherche en cours..." }
            elseif ($dc.Sync.Error) { $prop = "Windows Update indisponible" }
            else { $prop = "A jour" }
            $nm = $c.Name; if ($c.Count -gt 1) { $nm += " (x" + $c.Count + ")" }
            $it = New-Object System.Windows.Forms.ListViewItem($state)
            [void]$it.SubItems.Add($type); [void]$it.SubItems.Add($nm); [void]$it.SubItems.Add($ver); [void]$it.SubItems.Add($prop)
            $ds = ""; if ($c.Date) { $ds = $c.Date.ToString('dd/MM/yyyy') }
            [void]$it.SubItems.Add($ds)
            $it.ForeColor = $color
            $it.Tag = $c
            [void]$lvC.Items.Add($it)
        }
        $lvC.EndUpdate()
        $lblBios.Text = $dc.Sync.Bios
    }

    $fillUpdates = {
        $lvU.BeginUpdate(); $lvU.Items.Clear()
        foreach ($u in @($dc.Drivers)) {
            if (-not $u) { continue }
            $it = New-Object System.Windows.Forms.ListViewItem($u.Title)
            $tn = $u.TargetName; if (-not $tn) { $tn = "(composant non identifie)" }
            $cn = $wuClassNames[([string]$u.Class).ToLower()]; if (-not $cn) { $cn = $u.Class }
            [void]$it.SubItems.Add($tn); [void]$it.SubItems.Add($cn)
            $ds = ""; if ($u.Date) { $ds = $u.Date.ToString('dd/MM/yyyy') }
            [void]$it.SubItems.Add($ds); [void]$it.SubItems.Add([string]$u.SizeMo + " Mo")
            $it.Tag = $u.Id
            $isFw = ($u.Class -match 'Firmware' -or $u.Title -match 'Firmware|BIOS|UEFI')
            if ($isFw) { $it.Text = "[BIOS / FIRMWARE] " + $u.Title; $it.ForeColor = $cYellow }
            # Carte graphique (appli du fabricant plus recente) et firmware/BIOS (a choisir soi-meme) : decoches par defaut
            $it.Checked = ($u.Class -ne 'Display' -and -not $isFw)
            [void]$lvU.Items.Add($it)
        }
        $lvU.EndUpdate()
        $btnInst.Enabled = ($lvU.Items.Count -gt 0)
    }

    $writeReport = {
        $lines = New-Object System.Collections.ArrayList
        [void]$lines.Add("Analyse des pilotes du " + (Get-Date -Format "dd/MM/yyyy HH:mm"))
        if ($dc.Sync.Bios) { [void]$lines.Add($dc.Sync.Bios) }
        [void]$lines.Add("Etat | Type | Composant | Version actuelle | Mise a jour proposee | Date")
        foreach ($it in $lvC.Items) {
            [void]$lines.Add(("{0} | {1} | {2} | {3} | {4} | {5}" -f $it.Text, $it.SubItems[1].Text, $it.SubItems[2].Text, $it.SubItems[3].Text, $it.SubItems[4].Text, $it.SubItems[5].Text))
        }
        [void]$lines.Add("Mises a jour proposees par Windows Update : " + @($dc.Drivers).Count)
        foreach ($u in @($dc.Drivers)) { if ($u) { [void]$lines.Add("  - " + $u.Title + "  ->  " + $u.TargetName + "  [" + $u.Class + "]") } }
        if ($dc.Sync.SoftCount) { [void]$lines.Add("Autres mises a jour Windows en attente : " + $dc.Sync.SoftCount) }
        if ($dc.Sync.Error) { [void]$lines.Add("Erreur Windows Update : " + $dc.Sync.Error) }
        try { Set-Content -LiteralPath $Script:DriverReportFile -Value ($lines -join "`r`n") -Encoding UTF8 } catch {}
    }

    $startScan = {
        $btnInst.Enabled = $false; $btnRe.Enabled = $false
        $lvU.Items.Clear(); $pb.Style = "Marquee"; $pb.Visible = $true
        $dc.Comps = @(); $dc.Drivers = @(); $dc.Shown = $false; $dc.GpuShown = $false
        $dc.Sync = [hashtable]::Synchronized(@{ Status = "Demarrage..."; Done = $false; Error = $null; Comps = $null; Probs = $null; Drivers = $null; Bios = ""; SoftCount = 0
                                                 Fn = $Script:GpuLatestFn; IsLaptop = [bool]$Script:IsLaptop; Build = [int]$Script:WinBuild; Is64 = [Environment]::Is64BitOperatingSystem; Gpu = $null })
        $dc.Mode = 'scan'
        $dc.Task = Start-BackgroundTask $Script:DriverScanScript $dc.Sync $null
    }

    $poll = New-Object System.Windows.Forms.Timer
    $poll.Interval = 400
    $poll.Add_Tick({
        if (-not $dc.Sync) { return }
        $lblD.Text = $dc.Sync.Status
        if ($dc.Mode -eq 'scan') {
            if ($dc.Sync.Comps -and -not $dc.Shown) { $dc.Comps = @($dc.Sync.Comps); $dc.Shown = $true; & $fillComponents }
            if ($dc.Sync.Gpu -and $dc.Shown -and -not $dc.GpuShown) { $dc.GpuShown = $true; Set-GpuLatestResult $dc.Sync.Gpu $false; & $fillComponents }
            if ($dc.Sync.Done) {
                Stop-BackgroundTask $dc.Task; $dc.Task = $null; $dc.Mode = ''
                $pb.Style = "Blocks"; $pb.Value = 0; $pb.Visible = $false; $btnRe.Enabled = $true
                if ($dc.Sync.Comps) { $dc.Comps = @($dc.Sync.Comps) }
                if ($dc.Sync.Drivers) { $dc.Drivers = @($dc.Sync.Drivers) }
                if ($dc.Sync.Gpu) { Save-GpuLatestCache $dc.Sync.Gpu; Set-GpuLatestResult $dc.Sync.Gpu $false }
                & $fillComponents
                & $fillUpdates
                $nProb = @($dc.Sync.Probs | Where-Object { $_ -and $_.Code -ne 22 }).Count
                if ($dc.Sync.Error) {
                    $lblD.Text = "Composants analyses. Windows Update : " + $dc.Sync.Error
                    $lblD.ForeColor = $cYellow
                } else {
                    $msg = "" + @($dc.Comps).Count + " composants analyses, " + $nProb + " probleme(s), " + @($dc.Drivers).Count + " pilote(s) a mettre a jour"
                    if ($dc.Sync.SoftCount -gt 0) { $msg += " (+ " + $dc.Sync.SoftCount + " mise(s) a jour Windows : bouton 'Ouvrir Windows Update')" }
                    if (@($dc.Drivers).Count -eq 0 -and $nProb -eq 0) { $msg = "Tout est a jour selon Windows Update (" + @($dc.Comps).Count + " composants analyses)" }
                    $lblD.Text = $msg; $lblD.ForeColor = $cGreen
                }
                Log ("Pilotes : " + $lblD.Text)
                & $writeReport
            }
        } elseif ($dc.Mode -eq 'install') {
            if ($dc.Sync.Done) {
                Stop-BackgroundTask $dc.Task; $dc.Task = $null; $dc.Mode = ''
                $pb.Visible = $false
                foreach ($l in @($dc.Sync.Lines)) { Log ("Pilote : " + $l) }
                $res = ""
                if ($dc.Sync.Error) { $res = "Probleme : " + $dc.Sync.Error }
                else { $res = "" + $dc.Sync.OkCount + " pilote(s) installe(s), " + $dc.Sync.FailCount + " echec(s)." }
                if ($dc.Sync.Lines.Count -gt 0) { $res += "`r`n`r`n" + (@($dc.Sync.Lines) -join "`r`n") }
                if ($dc.Sync.Reboot) { $res += "`r`n`r`nRedemarre le PC pour terminer l'installation." }
                Log ("Installation des pilotes terminee : " + $dc.Sync.OkCount + " ok, " + $dc.Sync.FailCount + " echec(s)")
                [System.Windows.Forms.MessageBox]::Show($res, "GameBoost - Pilotes") | Out-Null
                $btnGpuV.Enabled = $true; $btnWU.Enabled = $true; $btnCl.Enabled = $true; $btnComp.Enabled = $true
                & $startScan
            }
        }
    })

    $installIds = {
        param($ids, $names)
        if (@($ids).Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un pilote.", "GameBoost") | Out-Null; return }
        $hasFw = @($dc.Drivers | Where-Object { $_ -and ($ids -contains $_.Id) -and ($_.Class -match 'Firmware' -or $_.Title -match 'Firmware|BIOS|UEFI') }).Count -gt 0
        if ($hasFw) {
            $onBat = $false
            try { $bt = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1; if ($bt -and $bt.BatteryStatus -eq 1) { $onBat = $true } } catch {}
            if ($onBat) { [System.Windows.Forms.MessageBox]::Show("Une mise a jour de BIOS/firmware est choisie : branche d'abord le chargeur.", "GameBoost") | Out-Null; return }
            $fwq = "Tu as choisi une mise a jour de BIOS / FIRMWARE fournie par le fabricant via Windows Update.`r`n`r`n" +
                   "Elle s'installe pendant le prochain redemarrage (ecran noir ou logo pendant quelques minutes). " +
                   "Il ne faut SURTOUT PAS eteindre ni debrancher le PC pendant ce temps.`r`n`r`nContinuer ?"
            if ([System.Windows.Forms.MessageBox]::Show($fwq, "GameBoost - BIOS / Firmware", "YesNo", "Warning") -ne "Yes") { return }
        }
        $q = "Installer " + @($ids).Count + " pilote(s) depuis Windows Update ?`r`n`r`n- " + (@($names) -join "`r`n- ") +
             "`r`n`r`nUn point de restauration Windows sera cree avant. N'eteins pas le PC pendant l'installation."
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Pilotes", "YesNo", "Question") -ne "Yes") { return }
        $btnInst.Enabled = $false; $btnComp.Enabled = $false; $btnRe.Enabled = $false; $btnGpuV.Enabled = $false; $btnWU.Enabled = $false; $btnCl.Enabled = $false
        $lblD.Text = "Creation du point de restauration..."; $lblD.ForeColor = $cText
        $pb.Style = "Marquee"; $pb.Visible = $true
        [System.Windows.Forms.Application]::DoEvents()
        $Script:Config.LastRestorePoint = ""
        New-WindowsRestorePoint
        Log ("Installation de " + @($ids).Count + " pilote(s) via Windows Update : " + (@($names) -join ", "))
        $dc.Sync = [hashtable]::Synchronized(@{ Status = "Preparation..."; Done = $false; Error = $null; Reboot = $false; OkCount = 0; FailCount = 0;
                                                 Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
        $dc.Mode = 'install'
        $dc.Task = Start-BackgroundTask $Script:DriverInstallScript $dc.Sync @($ids)
    }

    $btnInst.Add_Click({
        $ids = @(); $names = @()
        foreach ($it in $lvU.Items) { if ($it.Checked) { $ids += [string]$it.Tag; $names += $it.Text } }
        & $installIds $ids $names
    })

    # Mettre a jour UN composant : sa ou ses mises a jour, ou l'appli du fabricant pour une carte graphique
    $updateComponent = {
        if ($lvC.SelectedItems.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Selectionne d'abord un composant dans la liste du haut.", "GameBoost") | Out-Null; return }
        if ($dc.Mode -ne '') { return }
        $c = $lvC.SelectedItems[0].Tag
        if (-not $c) { return }
        if ($c.Updates -and $c.Updates.Count -gt 0) {
            $ids = @(); $names = @()
            foreach ($u in $c.Updates) { $ids += [string]$u.Id; $names += ($u.Title + "  ->  " + $c.Name) }
            foreach ($it in $lvU.Items) { $it.Checked = ($ids -contains [string]$it.Tag); if ($it.Checked) { $it.EnsureVisible() } }
            & $installIds $ids $names
        } elseif ($c.Class -eq 'DISPLAY') {
            $gl = Get-GpuLatestFor $c.Name
            if ($gl -and $gl.State -eq 'update' -and ($gl.File -or $gl.Url)) { Open-GpuLatestDriver $gl }
            else { Open-GpuVendorTool @($c) -Exact }
        } elseif (-not $dc.Sync.Done) {
            [System.Windows.Forms.MessageBox]::Show("La recherche Windows Update n'est pas terminee, patiente quelques instants.", "GameBoost") | Out-Null
        } else {
            [System.Windows.Forms.MessageBox]::Show(($c.Name + "`r`n`r`nAucune mise a jour proposee par Windows Update : son pilote est a jour."), "GameBoost") | Out-Null
        }
    }
    $btnComp.Add_Click({ & $updateComponent })
    $lvC.Add_DoubleClick({ & $updateComponent })
    $lvC.Add_SelectedIndexChanged({
        if ($lvC.SelectedItems.Count -eq 0) { $btnComp.Text = "Mettre a jour ce composant"; return }
        $c = $lvC.SelectedItems[0].Tag
        if ($c -and $c.Updates -and $c.Updates.Count -gt 0) { $btnComp.Text = "Installer la mise a jour de ce composant" }
        elseif ($c -and $c.Class -eq 'DISPLAY') {
            $gl = Get-GpuLatestFor $c.Name
            if ($gl -and $gl.State -eq 'update') { $btnComp.Text = "Telecharger le pilote " + $gl.Vendor + " " + $gl.Latest }
            else { $btnComp.Text = "Ouvrir " + (Get-GpuVendorToolName $c.Name) }
        }
        else { $btnComp.Text = "Mettre a jour ce composant" }
    })
    $btnGpuV.Add_Click({ Open-GpuVendorTool $dc.Comps })
    $btnWU.Add_Click({ try { Start-Process "ms-settings:windowsupdate" } catch {} })
    $btnRe.Add_Click({ & $startScan })
    $btnCl.Add_Click({ $f.Close() })
    $f.Add_FormClosing({
        param($sender, $e)
        if ($dc.Mode -eq 'install') {
            [System.Windows.Forms.MessageBox]::Show("Installation en cours : patiente jusqu'a la fin.", "GameBoost") | Out-Null
            $e.Cancel = $true
        }
    })
    $f.Add_Shown({ & $startScan; $poll.Start() })
    $Script:BusyDepth++     # pas de boost automatique pendant l'analyse ou l'installation
    try { [void]$f.ShowDialog($form) }
    finally {
        $poll.Stop(); $poll.Dispose()
        if ($dc.Task) { try { $dc.Task.PS.Stop() } catch {}; Stop-BackgroundTask $dc.Task }
        $f.Dispose()
        $Script:BusyDepth--
        Update-BoostButton
    }
}

# --- Fenetres de reglages (engrenages) -------------------------------------------
$Script:LastPurgeText = ""
function New-GBDialog($title, $w, $h) {
    $d = New-Object System.Windows.Forms.Form
    Register-GBDpi $d
    $d.Text = "GameBoost - " + $title
    $d.Size = New-Object System.Drawing.Size($w, $h)
    $d.StartPosition = "CenterParent"; $d.FormBorderStyle = "FixedDialog"; $d.MaximizeBox = $false; $d.MinimizeBox = $false
    $d.BackColor = $cBg; $d.ForeColor = $cText; $d.Font = $fontUI; $d.ShowInTaskbar = $false
    if ($form.Icon) { $d.Icon = $form.Icon }
    Set-GBDarkWindow $d
    return $d
}
function Add-DlgLabel($d, $t, $x, $y, $w, $h, $font = $fontUI, $color = $cText) {
    $l = New-Object System.Windows.Forms.Label; $l.Text = $t; $l.Location = New-Object System.Drawing.Point($x, $y)
    $l.Size = New-Object System.Drawing.Size($w, $h); $l.Font = $font; $l.ForeColor = $color
    $d.Controls.Add($l); return $l
}
function Add-DlgButton($d, $t, $x, $y, $w, $h = 30) {
    $b = New-GBButtonCtl; $b.Text = $t; $b.Location = New-Object System.Drawing.Point($x, $y)
    $b.Size = New-Object System.Drawing.Size($w, $h)
    $d.Controls.Add($b); return $b
}
function Add-DlgCheck($d, $t, $x, $y, $w, $checked) {
    $c = New-GBToggleCtl $t $checked; $c.Location = New-Object System.Drawing.Point($x, $y)
    $c.Size = New-Object System.Drawing.Size($w, 24)
    $d.Controls.Add($c); return $c
}
function Add-DlgOkCancel($d, $y, $w) {
    $ok = Add-DlgButton $d "Enregistrer" ($w - 260) $y 120
    $ok.ForeColor = $cGreen; $ok.DialogResult = [System.Windows.Forms.DialogResult]::OK
    $ca = Add-DlgButton $d "Annuler" ($w - 132) $y 100
    $ca.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $d.AcceptButton = $ok; $d.CancelButton = $ca
}
function Normalize-NameList($text) {
    return @($text -split "`r?`n" | ForEach-Object { $_.Trim().ToLower() -replace '\.exe$', '' } | Where-Object { $_ } | Select-Object -Unique)
}

# Curseur : composant GameBoost dessine, ou curseur Windows standard si la compilation est bloquee
function New-GBSlider($parent, $min, $max, $value, $labels, $colors, $suffix, $x, $y, $w) {
    if ($Script:SliderOK) {
        $s = New-Object GBSlider
        $s.Minimum = [int]$min; $s.Maximum = [int]$max; $s.SetValueSilently([int]$value)
        if ($labels) { $s.Labels = [string[]]$labels }
        if ($colors) { $s.LabelColors = [System.Drawing.Color[]]$colors }
        if ($suffix) { $s.Suffix = [string]$suffix }
        $s.Font = $fontUI
        $s.BackColor = $parent.BackColor
        $s.Size = New-Object System.Drawing.Size($w, 30)
    } else {
        $s = New-Object System.Windows.Forms.TrackBar
        $s.Minimum = [int]$min; $s.Maximum = [int]$max; $s.Value = [math]::Max([int]$min, [math]::Min([int]$max, [int]$value))
        $s.TickStyle = "None"; $s.AutoSize = $false; $s.BackColor = $parent.BackColor
        $s.Size = New-Object System.Drawing.Size($w, 30)
    }
    $s.Location = New-Object System.Drawing.Point($x, $y)
    $parent.Controls.Add($s)
    return $s
}
function Add-SliderCommit($s, [scriptblock]$sb) {
    if ($s -is [System.Windows.Forms.TrackBar]) { $s.add_MouseUp($sb); $s.add_KeyUp($sb) } else { $s.add_ValueCommitted($sb) }
}
function Set-SliderValue($s, $v) {
    if ($s -is [System.Windows.Forms.TrackBar]) { $s.Value = [math]::Max($s.Minimum, [math]::Min($s.Maximum, [int]$v)) } else { $s.SetValueSilently([int]$v) }
}

