    $btnNow = Add-DlgButton $d "Vider le cache maintenant" 16 68 230 32
    $btnNow.ForeColor = $cGreen
    $lblLast = Add-DlgLabel $d "" 256 75 320 20 $fontUI $cMuted
    $null = Add-DlgLabel $d "Vider quand le cache en attente depasse" 16 116 560 20
    $sl1 = New-GBSlider $d 256 8192 ([int]$Script:Config.StandbyMinMo) $null $null " Mo" 16 138 560
    $null = Add-DlgLabel $d "... et que la memoire libre descend sous" 16 180 560 20
    $sl2 = New-GBSlider $d 256 8192 ([int]$Script:Config.FreeMaxMo) $null $null " Mo" 16 202 560
    $null = Add-DlgLabel $d "Attendre au moins entre deux vidages" 16 244 560 20
    $sl3 = New-GBSlider $d 30 600 ([int]$Script:Config.PurgeInterval) $null $null " s" 16 266 560
    if ($Script:SliderOK) { $sl1.Snap = 128; $sl2.Snap = 128; $sl3.Snap = 10 }
    $chkAlw = Add-DlgCheck $d "Surveiller aussi en dehors du jeu (en permanence, comme ISLC)" 16 308 560 $Script:Config.StandbyAlways
    $null = Add-DlgLabel $d ("Windows garde en 'attente' des fichiers deja lus pour les rouvrir plus vite. Dans certains jeux, quand la memoire libre devient trop basse, " +
                             "ca provoque des micro-saccades : le vidage libere cette memoire. Reglage conseille : 1024 / 1024 Mo pour 16 Go de RAM, " +
                             "2048 / 2048 Mo pour 32 Go. Ne vide pas trop souvent : les chargements seraient un peu plus longs.") 16 340 560 96 $fontUI $cMuted
    Add-DlgOkCancel $d 470 588
    $upd = {
        $i = Get-StandbyInfo
        if ($i) {
            $os = $null; try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch {}
            $tot = ""; if ($os) { $tot = "   |   RAM totale : " + [math]::Round([double]$os.TotalVisibleMemorySize / 1MB, 1) + " Go" }
            $lblMem.Text = "Cache en attente : " + $i.StandbyMo + " Mo   |   Memoire libre : " + $i.FreeMo + " Mo" + $tot
        } else { $lblMem.Text = "Mesure indisponible sur ce PC" }
        if ($Script:LastPurgeText) { $lblLast.Text = "Dernier vidage : " + $Script:LastPurgeText }
    }
    $btnNow.Add_Click({
        $btnNow.Enabled = $false
        $ok = Invoke-StandbyPurge "vidage manuel"
        & $upd
        if (-not $ok) { [System.Windows.Forms.MessageBox]::Show("Le vidage a echoue (fonction bloquee par un antivirus ?). Detail dans le journal.", "GameBoost") | Out-Null }
        $btnNow.Enabled = $true
    })
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1000; $tm.Add_Tick({ & $upd }); $tm.Start()
    $d.Add_Shown({ & $upd })
    $res = $d.ShowDialog($form)
    $tm.Stop(); $tm.Dispose()
    if ($res -eq "OK") {
        $Script:Config.StandbyMinMo = [int]$sl1.Value; $Script:Config.FreeMaxMo = [int]$sl2.Value; $Script:Config.PurgeInterval = [int]$sl3.Value
        $Script:Config.StandbyAlways = $chkAlw.Checked
        Save-Config
        Log ("Anti-saccades : vidage si cache > " + $sl1.Value + " Mo et memoire libre < " + $sl2.Value + " Mo, " + $sl3.Value + " s minimum entre deux" +
             $(if ($chkAlw.Checked) { ", surveillance permanente" } else { ", pendant le jeu seulement" }))
    }
    $d.Dispose()
}

# --- Applications en cours (pour les priorites et les apps autorisees) ---------------
function Get-RunningAppGroups([bool]$includeBg) {
    $groups = @{}
    $games = Get-GameNames
    foreach ($p in Get-Process -ErrorAction SilentlyContinue) {
        if ($p.Id -eq $PID -or $p.Id -le 4 -or $p.SessionId -eq 0) { continue }
        $n = $p.ProcessName
        if ($Protected -contains $n.ToLower()) { continue }
        if (-not $groups.ContainsKey($n)) { $groups[$n] = @{ Name = $n; Procs = (New-Object System.Collections.ArrayList); HasWin = $false; Path = $null; Ram = 0.0 } }
        $g = $groups[$n]
        [void]$g.Procs.Add($p)
        if ($p.MainWindowHandle -ne [IntPtr]::Zero) { $g.HasWin = $true }
        if (-not $g.Path) { try { $g.Path = $p.Path } catch {} }
        try { $g.Ram += [double]$p.WorkingSet64 } catch {}
    }
    $list = @($groups.Values | Where-Object { $includeBg -or $_.HasWin -or $Script:Config.AppPriorities.ContainsKey($_.Name) -or ($games -contains $_.Name.ToLower()) })
    return @($list | Sort-Object @{ Expression = { if ($_.HasWin) { 0 } else { 1 } } }, @{ Expression = { $_.Name } })
}
function Get-AppDescription($g) {
    $desc = $g.Name
    if ($g.Path) { try { $fd = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($g.Path).FileDescription; if ($fd -and $fd.Trim()) { $desc = $fd.Trim() } } catch {} }
    return $desc
}

function Show-AddAllowedApps {
    $d = New-GBDialog "Ajouter des applications autorisees" 540 560
    $null = Add-DlgLabel $d "Coche les applications a ne jamais fermer ni ralentir pendant le boost :" 16 12 500 22
    $cl = New-Object System.Windows.Forms.CheckedListBox
    $cl.Location = New-Object System.Drawing.Point(16, 40); $cl.Size = New-Object System.Drawing.Size(496, 380)
    $cl.BackColor = $cPanel; $cl.ForeColor = $cText; $cl.BorderStyle = "FixedSingle"; $cl.CheckOnClick = $true
    $d.Controls.Add($cl)
    $existing = @(Normalize-NameList $txtWhite.Text)
    $names = New-Object System.Collections.ArrayList
    foreach ($g in @(Get-RunningAppGroups $true)) {
        $ln = $g.Name.ToLower()
        if ($existing -contains $ln) { continue }
        $desc = Get-AppDescription $g
        $t = $g.Name; if ($desc -ne $g.Name) { $t += "   -   " + $desc }
        if ($g.HasWin) { $t += "   (fenetre ouverte)" }
        [void]$cl.Items.Add($t, $false); [void]$names.Add($ln)
    }
    $btnBrowse2 = Add-DlgButton $d "Parcourir un .exe..." 16 430 170
    $btnBrowse2.Add_Click({
        $ofd = New-Object System.Windows.Forms.OpenFileDialog
        $ofd.Filter = "Programme (*.exe)|*.exe"; $ofd.Title = "Choisis le programme a autoriser"
        if ($ofd.ShowDialog() -eq "OK") {
            $n = [IO.Path]::GetFileNameWithoutExtension($ofd.FileName).ToLower()
            if ($names -notcontains $n -and $existing -notcontains $n) { [void]$cl.Items.Add(($n + "   (choisi a la main)"), $true); [void]$names.Add($n) }
        }
    })
    Add-DlgOkCancel $d 470 528
    if ($d.ShowDialog($form) -eq "OK") {
        $added = @(); for ($i = 0; $i -lt $cl.Items.Count; $i++) { if ($cl.GetItemChecked($i)) { $added += $names[$i] } }
        if ($added.Count -gt 0) {
            $txtWhite.Text = ((@($existing) + $added) -join "`r`n")
            Sync-ConfigFromUI
            Log ("Apps autorisees ajoutees : " + ($added -join ", "))
        }
    }
    $d.Dispose()
}

function Show-RemoveAllowedApps {
    $existing = @(Normalize-NameList $txtWhite.Text)
    if ($existing.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("La liste des applications autorisees est vide.", "GameBoost") | Out-Null; return }
    # Lignes selectionnees dans la liste (ou ligne du curseur) : deja cochees
    $pre = @()
    try {
        $a = $txtWhite.GetLineFromCharIndex($txtWhite.SelectionStart)
        $b = $txtWhite.GetLineFromCharIndex($txtWhite.SelectionStart + [math]::Max(0, $txtWhite.SelectionLength - 1))
        if ($txtWhite.Focused -or $txtWhite.SelectionLength -gt 0) {
            for ($i = $a; $i -le $b -and $i -lt $txtWhite.Lines.Count; $i++) { $pre += @(Normalize-NameList $txtWhite.Lines[$i]) }
        }
    } catch {}
    $d = New-GBDialog "Retirer des applications autorisees" 540 560
    $null = Add-DlgLabel $d "Coche les applications a retirer : pendant le boost, elles pourront etre fermees ou ralenties comme les autres." 16 12 500 40
    $cl = New-Object System.Windows.Forms.CheckedListBox
    $cl.Location = New-Object System.Drawing.Point(16, 56); $cl.Size = New-Object System.Drawing.Size(496, 350)
    $cl.BackColor = $cPanel; $cl.ForeColor = $cText; $cl.BorderStyle = "FixedSingle"; $cl.CheckOnClick = $true
    foreach ($n in $existing) {
        $t = $n; if ($n -like 'discord*') { $t += "   (vocal en jeu : deconseille de retirer)" }
        [void]$cl.Items.Add($t, ($pre -contains $n))
    }
    $d.Controls.Add($cl)
    $btnAll = Add-DlgButton $d "Tout cocher" 16 416 120
    $btnAll.Add_Click({ for ($i = 0; $i -lt $cl.Items.Count; $i++) { $cl.SetItemChecked($i, $true) } })
    $btnNone = Add-DlgButton $d "Tout decocher" 144 416 120
    $btnNone.Add_Click({ for ($i = 0; $i -lt $cl.Items.Count; $i++) { $cl.SetItemChecked($i, $false) } })
    Add-DlgOkCancel $d 470 528
    if ($d.ShowDialog($form) -eq "OK") {
        $removed = @(); $kept = @()
        for ($i = 0; $i -lt $existing.Count; $i++) { if ($cl.GetItemChecked($i)) { $removed += $existing[$i] } else { $kept += $existing[$i] } }
        if ($removed.Count -gt 0) {
            $txtWhite.Text = ($kept -join "`r`n")
            Sync-ConfigFromUI
            Log ("Apps autorisees retirees : " + ($removed -join ", "))
        }
    }
    $d.Dispose()
}

# --- Fenetre : priorite de chaque logiciel ouvert (curseurs) -------------------------
function Show-AppPriorities {
    $d = New-GBDialog "Priorite des applications" 840 660
    $d.FormBorderStyle = "Sizable"; $d.MaximizeBox = $true; $d.MinimumSize = New-Object System.Drawing.Size(760, 420)
    $null = Add-DlgLabel $d "Priorite des applications en cours" 16 10 500 26 $fontBold $cGreen
    $btnRef = Add-DlgButton $d "Actualiser" 16 40 110 28
    $chkAutoR = Add-DlgCheck $d "Actualisation automatique" 140 43 200 $true
    $chkBgP = Add-DlgCheck $d "Afficher aussi les programmes en arriere-plan" 346 43 284 $false
    $btnReset = Add-DlgButton $d "Tout remettre en Normale" 640 40 170 28
    $btnReset.Anchor = "Top, Right"
    $info = Add-DlgLabel $d ("Haute = plus de temps processeur pour l'appli (ideal pour le jeu). Basse = l'appli passe apres tout le reste. " +
                             "'Retenir' = GameBoost remet cette priorite a chaque lancement. Les applis protegees (anti-triche, systeme) ne peuvent pas etre modifiees.") 16 74 794 36 $fontUI $cMuted
    $info.Anchor = "Top, Left, Right"
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel; Set-GBDoubleBuffered $flow
    $flow.Location = New-Object System.Drawing.Point(16, 114); $flow.Size = New-Object System.Drawing.Size(794, 470)
    $flow.FlowDirection = "TopDown"; $flow.WrapContents = $false; $flow.AutoScroll = $true; $flow.BackColor = $cBg
    $flow.Anchor = "Top, Bottom, Left, Right"
    $d.Controls.Add($flow)
    $lblCount = Add-DlgLabel $d "" 16 592 600 20 $fontUI $cMuted
    $lblCount.Anchor = "Bottom, Left"
    $rows = @{}

    $onCommit = {
        param($sender, $e)
        $info = $sender.Tag
        $lvl = [int]$sender.Value
        $r = Set-AppPriority $info.Name $lvl
        $extra = ""; if ($r.Ko -gt 0) { $extra = ", " + $r.Ko + " protege(s)" }
        Log ("Priorite " + $Script:PrioNames[$lvl] + " -> " + $info.Name + " (" + $r.Ok + " processus" + $extra + ")")
        if ($r.Ok -eq 0 -and $r.Ko -gt 0) { $info.Sub.ForeColor = $cRed; $info.Sub.Text = $info.SubText + "  |  modification refusee (appli protegee)" }
        if ($info.Chk.Checked) { $Script:Config.AppPriorities[$info.Name] = $lvl; Save-Config }
    }
    $onRemember = {
        param($sender, $e)
        $info = $sender.Tag
        if ($sender.Checked) { $Script:Config.AppPriorities[$info.Name] = [int]$info.Slider.Value; Log ("Priorite retenue pour " + $info.Name + " : " + $Script:PrioNames[[int]$info.Slider.Value]) }
        else { [void]$Script:Config.AppPriorities.Remove($info.Name); Log ("Priorite oubliee pour " + $info.Name) }
        Save-Config
    }
    $makeRow = {
        param($g)
        $row = New-Object System.Windows.Forms.Panel
        $row.Size = New-Object System.Drawing.Size(768, 52); $row.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, 3); $row.BackColor = $cPanel
        $pic = New-Object System.Windows.Forms.PictureBox
        $pic.Location = New-Object System.Drawing.Point(10, 12); $pic.Size = New-Object System.Drawing.Size(28, 28); $pic.SizeMode = "Zoom"
        if ($g.Path) { try { $pic.Image = ([System.Drawing.Icon]::ExtractAssociatedIcon($g.Path)).ToBitmap() } catch {} }
        $desc = Get-AppDescription $g
        $lblN = New-Object System.Windows.Forms.Label
        $lblN.Text = $desc; $lblN.Location = New-Object System.Drawing.Point(48, 7); $lblN.Size = New-Object System.Drawing.Size(300, 20)
        $lblN.Font = $fontBold; $lblN.ForeColor = $cText; $lblN.AutoEllipsis = $true
        $cur = 2; $locked = $false
        try { $cur = Get-PrioIndex $g.Procs[0].PriorityClass } catch { $locked = $true }
        $isGame = (Get-GameNames) -contains $g.Name.ToLower()
        $subText = $g.Name + ".exe  |  " + $g.Procs.Count + " processus  |  " + [int]($g.Ram / 1MB) + " Mo"
        if ($isGame) { $subText += "  |  JEU" }
        if ($locked) { $subText += "  |  protege" }
        $lblS = New-Object System.Windows.Forms.Label
        $lblS.Text = $subText; $lblS.Location = New-Object System.Drawing.Point(48, 28); $lblS.Size = New-Object System.Drawing.Size(300, 18)
        $lblS.ForeColor = $cMuted; $lblS.AutoEllipsis = $true
        $sl = New-GBSlider $row 0 4 $cur $Script:PrioShort $Script:PrioColors "" 356 11 300
        if ($locked) { $sl.Enabled = $false }
        $chk = New-GBToggleCtl "Retenir" ($Script:Config.AppPriorities.ContainsKey($g.Name))
        $chk.Location = New-Object System.Drawing.Point(670, 15); $chk.Size = New-Object System.Drawing.Size(92, 22)
        if ($locked) { $chk.Enabled = $false }
        $sl.Tag = @{ Name = $g.Name; Chk = $chk; Sub = $lblS; SubText = $subText }
        $chk.Tag = @{ Name = $g.Name; Slider = $sl }
        Add-SliderCommit $sl $onCommit
        $chk.add_CheckedChanged($onRemember)
        $row.Controls.Add($pic); $row.Controls.Add($lblN); $row.Controls.Add($lblS); $row.Controls.Add($chk)
        # Ligne creee apres l'ouverture de la fenetre : on applique nous-memes le zoom de l'ecran (125 %, 150 %...)
        try { $sf = [double]$Script:DpiScale; if ([math]::Abs($sf - 1.0) -gt 0.01) { $row.Scale((New-Object System.Drawing.SizeF([single]$sf, [single]$sf))) } } catch {}
        return $row
    }
    $refresh = {
        param([bool]$full)
        $list = @(Get-RunningAppGroups $chkBgP.Checked)
        $names = @{}; foreach ($g in $list) { $names[$g.Name] = $true }
        $flow.SuspendLayout()
        if ($full) { foreach ($c in @($flow.Controls)) { $flow.Controls.Remove($c); $c.Dispose() }; $rows.Clear() }
        foreach ($k in @($rows.Keys)) { if (-not $names.ContainsKey($k)) { $flow.Controls.Remove($rows[$k]); $rows[$k].Dispose(); $rows.Remove($k) } }
        foreach ($g in $list) { if (-not $rows.ContainsKey($g.Name)) { $r = & $makeRow $g; $rows[$g.Name] = $r; $flow.Controls.Add($r) } }
        $flow.ResumeLayout()
        $lblCount.Text = "" + $rows.Count + " application(s)  |  " + $Script:Config.AppPriorities.Count + " priorite(s) retenue(s)  |  mise a jour " + (Get-Date -Format "HH:mm:ss")
    }
    $btnRef.Add_Click({ & $refresh $true })
    $chkBgP.Add_CheckedChanged({ & $refresh $true })
    $btnReset.Add_Click({
        if ([System.Windows.Forms.MessageBox]::Show("Remettre toutes les applis en priorite Normale et oublier les priorites retenues ?", "GameBoost", "YesNo", "Question") -ne "Yes") { return }
        foreach ($k in @($rows.Keys)) { [void](Set-AppPriority $k 2) }
        $Script:Config.AppPriorities = @{}; Save-Config
        Log "Priorites des applis remises en Normale"
        & $refresh $true
    })
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 2000
    $tm.Add_Tick({ if ($chkAutoR.Checked) { try { & $refresh $false } catch {} } })
    $d.Add_Shown({ & $refresh $true; $tm.Start() })
    try { [void]$d.ShowDialog($form) } finally { $tm.Stop(); $tm.Dispose(); $d.Dispose() }
}

# En-tetes de colonnes sombres (theme neon) pour les listes des fenetres Config Windows / Desinstallation
function Set-GBListViewStyle($lv) {
    $lv.View = "Details"; $lv.FullRowSelect = $true; $lv.HideSelection = $false
    $lv.BackColor = $cPanel; $lv.ForeColor = $cText; $lv.BorderStyle = "FixedSingle"
    if (-not $Script:UiOK) { Set-GBDoubleBuffered $lv; return }
    [GBTheme]::StyleList($lv, $fontBold, $cDeep, $cLine, $cCyan, $false)
}
function Set-GBDarkCombo($cb) {
    $cb.BackColor = $cDeep; $cb.ForeColor = $cText
    if ($cb.GetType().Name -eq 'GBCombo') { return }   # deja sombre (dessine par GameBoost)
    if ($Script:UiOK) { try { [GBTheme]::StyleCombo($cb, $cDeep, $cText, $cLine) } catch {} }
}
Set-GBDarkCombo $cmbRunning

# Ligne creee apres l'ouverture d'une fenetre : on applique nous-memes le zoom de l'ecran (125 %, 150 %...)
function Invoke-GBRowScale($ctl) {
    try { $sf = [double]$Script:DpiScale; if ([math]::Abs($sf - 1.0) -gt 0.01) { $ctl.Scale((New-Object System.Drawing.SizeF([single]$sf, [single]$sf))) } } catch {}
}

function Restart-GBExplorer {
    Log "Redemarrage de l'Explorateur Windows"
    try { Get-Process explorer -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch {}
    $t0 = Get-Date
    while (((Get-Date) - $t0).TotalSeconds -lt 5) {
        Start-Sleep -Milliseconds 250; [System.Windows.Forms.Application]::DoEvents()
        if (Get-Process explorer -ErrorAction SilentlyContinue) { return }
    }
    try { Start-Process explorer.exe } catch {}
}

# --- Config Windows : centre de reglages Windows (applis, optimisations, personnalisation, outils) -----------------
# Sections : Logiciels et applis / Optimisations / Personnalisation / Outils.
# Chaque reglage lit l'etat REEL du PC et s'applique tout de suite, UNE fois : rien n'est reapplique en arriere-plan
# si Windows ou toi changez d'avis ensuite (seule exception : la suppression persistante des applis Windows,
# activee uniquement si tu la demandes, visible et arretable a tout moment).
# La premiere fois qu'une valeur est changee, sa valeur d'origine est gardee dans config_windows_origine.json :
# "Tout annuler" remet Windows comme avant. (Separe de TOUT RESTAURER, qui ne concerne que le boost.)
$Script:WinCfgBackupFile = Join-Path $AppDir "config_windows_origine.json"
$Script:WinCfgBackup = $null
$Script:WinCfgSaveDir = Join-Path $AppDir "sauvegardes_config"
$Script:ClassicMenuKey = 'HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}'
$Script:IsWin11 = ($Script:WinBuild -ge 22000)
$Script:IsHomeEd = $false
try { $Script:IsHomeEd = ([string](Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop).EditionID -match '^Core') } catch {}

function Get-WinCfgBackup {
    if ($null -ne $Script:WinCfgBackup) { return $Script:WinCfgBackup }
    $Script:WinCfgBackup = @{}
    if (Test-Path -LiteralPath $Script:WinCfgBackupFile) {
        try {
            $j = Get-Content -LiteralPath $Script:WinCfgBackupFile -Raw | ConvertFrom-Json
            foreach ($p in $j.PSObject.Properties) { $Script:WinCfgBackup[$p.Name] = $p.Value }
        } catch {}
        # Valeurs gardees alors que rien n'a change (ecriture refusee par Windows...) : inutiles, on les retire
        $drop = @()
        foreach ($k in @($Script:WinCfgBackup.Keys)) {
            if ($k -like 'custom|*' -or $k -like 'power|*' -or $k -like 'dns|*') { continue }
            $i = $k.LastIndexOf('|'); $b = $Script:WinCfgBackup[$k]
            try {
                $r = Read-GBRegFast $k.Substring(0, $i) $k.Substring($i + 1)
                if ((-not $b.Existed -and -not $r.Existed) -or ($b.Existed -and $r.Existed -and [string]$b.Value -eq [string]$r.Value)) { $drop += $k }
            } catch {}
        }
        if ($drop.Count -gt 0) { foreach ($k in $drop) { [void]$Script:WinCfgBackup.Remove($k) }; Save-WinCfgBackup }
    }
    return $Script:WinCfgBackup
}
function Save-WinCfgBackup {
    try { (Get-WinCfgBackup) | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $Script:WinCfgBackupFile -Encoding UTF8 } catch {}
}

# Entree de registre d'un interrupteur : P = cle, N = valeur, On = valeur "active", Off = valeur Windows par defaut ($null = valeur absente)
function New-WinReg($p, $n, $on, $off, $t = 'DWord') { return @{ P = $p; N = $n; On = $on; Off = $off; T = $t } }
# Valeur d'une option de reglage a choix : V = valeur ($null = absente), D = valeur qu'utilise Windows quand elle est absente
function New-WinVal($p, $n, $v, $t = 'DWord', $d = $null) { return @{ P = $p; N = $n; V = $v; T = $t; D = $d } }

# Lecture directe du registre (.NET) : environ 100 fois plus rapide que Get-ItemProperty, la fenetre reste fluide
function Read-GBRegFast($p, $n) {
    $r = @{ Existed = $false; Value = $null }
    $root = $null; $sub = ''
    if ($p -like 'HKCU:\*') { $root = [Microsoft.Win32.Registry]::CurrentUser; $sub = $p.Substring(6) }
    elseif ($p -like 'HKLM:\*') { $root = [Microsoft.Win32.Registry]::LocalMachine; $sub = $p.Substring(6) }
    else { $x = Read-RegValue $p $n; $r.Existed = $x.Existed; $r.Value = $x.Value; return $r }
    try {
        $k = $root.OpenSubKey($sub)
        if ($k) {
            try {
                $v = $k.GetValue($n, $null, [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                if ($null -ne $v -or (@($k.GetValueNames()) -contains $n)) { $r.Existed = $true; $r.Value = $v }
            } finally { $k.Close() }
        }
    } catch {}
    return $r
}
function Test-WinCfgRegMatch($e, $want) {
    $r = Read-GBRegFast $e.P $e.N
    if ($null -eq $want) { return (-not $r.Existed) }
    if (-not $r.Existed) { return $false }
    if ($e.T -eq 'DWord') { try { return ([int64]$r.Value -eq [int64]$want) } catch { return $false } }
    return ([string]$r.Value -eq [string]$want)
}
function Test-WinValMatch($v) {
    $r = Read-GBRegFast $v.P $v.N
    $cur = $null
    if ($r.Existed) { $cur = $r.Value } elseif ($null -ne $v.D) { $cur = $v.D }
    if ($null -eq $v.V) { return ($null -eq $cur -or ($r.Existed -and $null -ne $v.D -and [string]$r.Value -eq [string]$v.D)) }
    if ($null -eq $cur) { return $false }
    if ($v.T -eq 'DWord') { try { return ([int64]$cur -eq [int64]$v.V) } catch { return $false } }
    return ([string]$cur -eq [string]$v.V)
}
function Write-WinCfgReg($path, $name, $value, $type) {
    if ($null -eq $value) { Remove-ItemProperty -LiteralPath $path -Name $name -ErrorAction SilentlyContinue; return }
    if (-not (Test-Path -LiteralPath $path)) { New-Item -Path $path -Force -ErrorAction Stop | Out-Null }
    New-ItemProperty -LiteralPath $path -Name $name -Value $value -PropertyType $type -Force -ErrorAction Stop | Out-Null
}
# Ecrit une valeur en gardant l'originale une seule fois (pour "Tout annuler")
function Set-WinCfgValue($p, $n, $v, $t) {
    $key = $p + '|' + $n; $bk = Get-WinCfgBackup; $new = $false
    if (-not $bk.ContainsKey($key)) { $bk[$key] = Read-RegValue $p $n $t; Save-WinCfgBackup; $new = $true }
    # Ecriture refusee par Windows : on ne garde pas une "valeur d'origine" pour rien
    try { Write-WinCfgReg $p $n $v $t } catch { if ($new) { [void]$bk.Remove($key); Save-WinCfgBackup }; throw }
}
function Set-WinCfgReg($e, [bool]$on) {
    $key = $e.P + '|' + $e.N
    $bk = Get-WinCfgBackup
    if ($on) {
        if (Test-WinCfgRegMatch $e $e.On) { return }
        $new = $false
        if (-not $bk.ContainsKey($key)) { $bk[$key] = Read-RegValue $e.P $e.N $e.T; Save-WinCfgBackup; $new = $true }
        # Ecriture refusee par Windows : on ne garde pas une "valeur d'origine" pour rien
        try { Write-WinCfgReg $e.P $e.N $e.On $e.T } catch { if ($new) { [void]$bk.Remove($key); Save-WinCfgBackup }; throw }
        return
    }
    if ($bk.ContainsKey($key)) {
        # Retour a la valeur d'origine du PC (avant GameBoost)
        $b = $bk[$key]
        if ($b.Existed) { Write-WinCfgReg $e.P $e.N $b.Value $b.Type } else { Write-WinCfgReg $e.P $e.N $null $e.T }
        [void]$bk.Remove($key); Save-WinCfgBackup
        if (-not (Test-WinCfgRegMatch $e $e.On)) { return }
    }
    if (Test-WinCfgRegMatch $e $e.On) { Write-WinCfgReg $e.P $e.N $e.Off $e.T }
}

function Test-WinCfgVisible($t) { return (-not $t.Only -or [bool](& $t.Only)) }
function Get-WinCfgState($t) {
    if ($t.Get) { return [bool](& $t.Get) }
    foreach ($e in $t.Reg) { if (-not (Test-WinCfgRegMatch $e $e.On)) { return $false } }
    return $true
}
function Set-WinCfgTweak($t, [bool]$on) {
    if ($t.Set) {
        $bk = Get-WinCfgBackup; $ck = 'custom|' + $t.Id
        if (-not $bk.ContainsKey($ck)) { $bk[$ck] = @{ WasOn = [bool](Get-WinCfgState $t) }; Save-WinCfgBackup }
        & $t.Set $on
        if ([bool]$bk[$ck].WasOn -eq $on) { [void]$bk.Remove($ck); Save-WinCfgBackup }
    } else {
        foreach ($e in $t.Reg) { Set-WinCfgReg $e $on }
    }
    if ($t.After) { try { & $t.After } catch {} }
}
# Reglage a choix : index de l'option active, -1 = reglage de Windows hors des options proposees
function Get-WinCfgChoice($t) {
    if ($t.Get) { return [int](& $t.Get) }
    for ($i = 0; $i -lt $t.Opts.Count; $i++) {
        $all = $true
        foreach ($v in @($t.Opts[$i].V)) { if (-not (Test-WinValMatch $v)) { $all = $false; break } }
        if ($all) { return $i }
    }
    return -1
}
function Set-WinCfgChoice($t, [int]$i) {
    if ($t.Set) {
        $bk = Get-WinCfgBackup; $ck = 'custom|' + $t.Id
        if (-not $bk.ContainsKey($ck)) { $bk[$ck] = @{ Was = [int](Get-WinCfgChoice $t) }; Save-WinCfgBackup }
        & $t.Set $i
        if ([int]$bk[$ck].Was -eq $i) { [void]$bk.Remove($ck); Save-WinCfgBackup }
    } else {
        foreach ($v in @($t.Opts[$i].V)) { Set-WinCfgValue $v.P $v.N $v.V $v.T }
    }
    if ($t.Svc -and $i -eq 0) { try { Stop-Service -Name $t.Svc -Force -ErrorAction SilentlyContinue } catch {} }
    if ($t.After) { try { & $t.After } catch {} }
}
# Valeur actuelle pour la sauvegarde / l'import (interrupteur : $true/$false, choix : index)
function Get-WinCfgCurrent($t) {
    if ($t.Type -eq 'choice') { return [int](Get-WinCfgChoice $t) }
    return [bool](Get-WinCfgState $t)
}

# Reglages du plan d'alimentation : sauvegarde de la valeur d'origine (secteur / batterie)
function Get-GBPowerPlans {
    $list = New-Object System.Collections.ArrayList
    foreach ($l in @(powercfg /list 2>$null)) {
        if ([string]$l -match '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\s+\((.+)\)\s*(\*)?\s*$') {
            [void]$list.Add([pscustomobject]@{ Guid = $Matches[1].ToLower(); Name = $Matches[2].Trim(); Active = [bool]$Matches[3] })
        }
    }
    return $list.ToArray()
}
function Get-GBPowerValue($scheme, $sub, $set) {
    # /qh : lit aussi les reglages caches par Windows (boost du processeur, parking des coeurs, EPP...)
    $out = (powercfg /qh $scheme $sub $set 2>$null) -join "`n"
    $hex = [regex]::Matches($out, '0x[0-9a-fA-F]{8}')
    if ($hex.Count -ge 2) { return @{ AC = [Convert]::ToInt32($hex[$hex.Count - 2].Value, 16); DC = [Convert]::ToInt32($hex[$hex.Count - 1].Value, 16) } }
    return $null
}
function Set-GBPowerValue($scheme, $sub, $set, [int]$ac, [int]$dc) {
    $bk = Get-WinCfgBackup; $key = 'power|' + $scheme + '|' + $sub + '|' + $set
    if (-not $bk.ContainsKey($key)) { $o = Get-GBPowerValue $scheme $sub $set; if ($o) { $bk[$key] = $o; Save-WinCfgBackup } }
    powercfg /setacvalueindex $scheme $sub $set $ac 2>$null | Out-Null
    powercfg /setdcvalueindex $scheme $sub $set $dc 2>$null | Out-Null
    $act = Get-ActiveScheme
    if ($act -and $act -eq $scheme) { powercfg /setactive $scheme 2>$null | Out-Null }
}

# --- Vitesse du processeur : bouton TURBO ON / OFF + engrenage (GHz choisis pour chaque mode) ---
# OFF (hors jeu) : "mode de boost du processeur" desactive = frequence de base (mesure sur i7-13650HX : 4,3 GHz -> 2,4 GHz),
#   ou la frequence maximale choisie (Windows : "frequence maximale du processeur", coeurs performants et economes).
# ON et pendant le boost : turbo normal, ou plafonne aux GHz choisis (moins chaud en jeu).
# Valeurs d'origine gardees (par plan) et remises a la fermeture de GameBoost et avec TOUT RESTAURER.
function Get-GBCpuBaseMhz {
    if ($Script:CpuBaseMhz) { return $Script:CpuBaseMhz }
    # Frequence de base officielle (Win32_Processor ; le registre donne une valeur mesuree, un peu au-dessus)
    $m = 0
    try { $m = [int](Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1).MaxClockSpeed } catch {}
    if ($m -lt 500) { try { $m = [int](Read-GBRegFast 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' '~MHz').Value } catch {} }
    if ($m -lt 500) { $m = 2500 }
    $Script:CpuBaseMhz = [int]([math]::Round($m / 100.0) * 100)
    return $Script:CpuBaseMhz
}
# Fiche du processeur : marque, modele, gamme, coeurs, hybride, turbo maximum (mesure une fois, garde dans les reglages)
function Get-GBCpuInfo {
    if ($Script:CpuInfo) { return $Script:CpuInfo }
    $name = ''; $vend = ''
    try { $name = ([string](Read-GBRegFast 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' 'ProcessorNameString').Value).Trim() } catch {}
    try { $vend = [string](Read-GBRegFast 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' 'VendorIdentifier').Value } catch {}
    $cores = 0; $threads = [Environment]::ProcessorCount
    try {
        $p = @(Get-CimInstance Win32_Processor -ErrorAction Stop); $cores = [int](($p | Measure-Object NumberOfCores -Sum).Sum)
        $lt = [int](($p | Measure-Object NumberOfLogicalProcessors -Sum).Sum); if ($lt -gt 0) { $threads = $lt }
        if (-not $name) { $name = ([string]$p[0].Name).Trim() }
    } catch {}
    $name = ($name -replace '\(R\)|\(TM\)', '' -replace '\s+', ' ').Trim()
    $brand = 'autre'
    if ($vend -match 'Intel' -or $name -match 'Intel') { $brand = 'Intel' }
    elseif ($vend -match 'AMD' -or $name -match 'AMD|Ryzen|Athlon') { $brand = 'AMD' }
    elseif ($name -match 'Snapdragon|Qualcomm' -or $Script:NativeArch -eq 'ARM64') { $brand = 'Qualcomm (ARM)' }
    # Gamme d'apres le suffixe du modele : 13650HX, 7840HS, 1235U, 14700K, 9800X3D, 155H...
    # (la puce graphique " w/ Radeon 890M Graphics" n'est pas le modele du processeur)
    $core = $name -replace '\s+(w/|with)\s+.*$', '' -replace '\s+Radeon.*$', ''
    $suf = ''
    if ($core -cmatch '\b(HX|HS|H)\s+\d{3}\b') { $suf = $Matches[1] }   # ex. Ryzen AI 9 HX 370
    if (-not $suf) { foreach ($tok in ($core -split '[\s\-]+')) { if ($tok -cmatch '^\d{3,5}([A-Z][A-Z0-9]{0,3})$') { $suf = $Matches[1]; break } } }
    if ($suf -cmatch '^(HX|HK|HS|H)$') { $class = 'portable gaming' }
    elseif ($suf -cmatch '^(U|P|Y|V|G\d)$' -or $brand -eq 'Qualcomm (ARM)') { $class = 'portable basse consommation' }
    elseif ($Script:IsLaptop) { $class = 'portable' }
    else { $class = 'PC fixe' }
    if ($Script:IsLaptop -and $class -eq 'PC fixe') { $class = 'portable' }
    $hybrid = ($cores -gt 0 -and $threads -ne $cores -and $threads -ne 2 * $cores)   # coeurs performants + economes (Intel 12e gen et +)
    $max = 0
    if ([string]$Script:Config.CpuMaxName -eq $name -and [int]$Script:Config.CpuMaxMhz -gt 0) { $max = [int]$Script:Config.CpuMaxMhz }
    $Script:CpuInfo = @{ Name = $name; Brand = $brand; Suffix = $suf; Class = $class; Cores = $cores; Threads = $threads; Hybrid = $hybrid; Base = (Get-GBCpuBaseMhz); Max = $max }
    return $Script:CpuInfo
}
# Turbo maximum reel : 2 fils de calcul pendant la mesure (~3 s), frequence du coeur le plus rapide (turbo d'origine remis le temps de la mesure)
function Measure-GBCpuMaxMhz {
    $info = Get-GBCpuInfo
    # Le temps de la mesure : turbo autorise a fond sur le plan actif (meme s'il etait coupe par GameBoost, par toi ou par un autre logiciel),
    # puis les valeurs exactes d'avant sont remises
    $sch = Get-ActiveScheme; $prev = @{}
    if ($sch) {
        foreach ($s in 'PERFBOOSTMODE', 'PROCFREQMAX', 'PROCFREQMAX1') { $v = Get-GBPowerValue $sch 'SUB_PROCESSOR' $s; if ($v) { $prev[$s] = $v } }
        if ($prev['PERFBOOSTMODE']) { Write-GBProcVal $sch PERFBOOSTMODE 2 2 }
        foreach ($s in 'PROCFREQMAX', 'PROCFREQMAX1') { if ($prev[$s]) { Write-GBProcVal $sch $s 0 0 } }
        if ($prev.Count -gt 0) { powercfg /setactive $sch 2>$null | Out-Null }
    }
    $best = 0.0; $pss = @()
    try {
        for ($i = 0; $i -lt 2; $i++) { $p = [powershell]::Create(); [void]$p.AddScript({ $e = [DateTime]::Now.AddSeconds(6); $x = 0; while ([DateTime]::Now -lt $e) { $x++ } }); $pss += @{ P = $p; H = $p.BeginInvoke() } }
        Start-Sleep -Milliseconds 500
        for ($k = 0; $k -lt 3; $k++) {
            foreach ($c in @(Get-CimInstance Win32_PerfFormattedData_Counters_ProcessorInformation -ErrorAction Stop)) {
                if ([string]$c.Name -match '_Total') { continue }
                $v = [double]$c.ProcessorFrequency * [double]$c.PercentProcessorPerformance / 100; if ($v -gt $best) { $best = $v }
            }
            Start-Sleep -Milliseconds 200
        }
    } catch {}
    finally {
        foreach ($x in $pss) { try { $x.P.Stop() } catch {}; try { $x.P.Dispose() } catch {} }
        if ($sch -and $prev.Count -gt 0) {
            foreach ($s in @($prev.Keys)) { Write-GBProcVal $sch $s $prev[$s].AC $prev[$s].DC }
            powercfg /setactive $sch 2>$null | Out-Null
        }
    }
    $m = [int]([math]::Round($best / 100.0) * 100)
    if ($m -lt $info.Base -or $m -gt $info.Base * 4) { return [int]$info.Max }   # compteurs absents ou incoherents (PC virtuel...) : valeur d'avant gardee
    # Processeur deja chaud ou occupe : il monte moins haut. On garde la valeur la plus haute jamais mesuree pour ce processeur.
    if ([string]$Script:Config.CpuMaxName -eq $info.Name -and [int]$Script:Config.CpuMaxMhz -gt $m) { $m = [int]$Script:Config.CpuMaxMhz }
    $Script:Config.CpuMaxMhz = $m; $Script:Config.CpuMaxName = $info.Name; Save-Config
    $info.Max = $m
    Log ("Processeur analyse : " + $info.Name + " - base " + ("{0:N1}" -f ($info.Base / 1000.0)) + " GHz, turbo maximum mesure " + ("{0:N1}" -f ($m / 1000.0)) + " GHz")
    return $m
}
# Valeurs conseillees selon le processeur et le PC
#  - hors jeu : frequence de base (turbo coupe) ; si la base est tres basse (processeurs basse consommation), 2,4 GHz pour rester fluide
#  - en jeu : PC fixe = sans limite ; portable = 86 a 90 % du turbo maximum (les derniers GHz chauffent beaucoup pour tres peu d'images en plus)
function Get-GBTurboReco {
    $i = Get-GBCpuInfo; $b = [int]$i.Base
    $g = { param($m) ("{0:N1}" -f ($m / 1000.0)) + " GHz" }
    $known = ([int]$i.Max -gt 0); $max = [int]$i.Max
    if (-not $known) { $max = [int]([math]::Round($b * 1.7 / 100.0) * 100) }
    if ($b -ge 2000) { $off = $b; $whyOff = "frequence de base, turbo coupe : fluide au quotidien et bien plus frais." }
    else { $off = [int][math]::Min([math]::Max($max, $b), 2400); $whyOff = "ta frequence de base est basse (" + (& $g $b) + ") : turbo coupe = PC lent. " + (& $g $off) + " reste fluide et frais." }
    if ($i.Class -eq 'PC fixe') {
        $on = 0; $whyOn = "PC fixe : le refroidissement suit, garde le turbo sans limite. Limite-le seulement si le PC chauffe ou fait du bruit."
    } else {
        $pct = 0.88; if ($i.Class -eq 'portable gaming') { $pct = 0.86 } elseif ($i.Class -eq 'portable basse consommation') { $pct = 0.9 }
        $on = [int]([math]::Round($max * $pct / 100.0) * 100)
        $on = [math]::Max($on, $b + 200)
        if ($on -ge $max) { $on = 0; $whyOn = "turbo proche de la base sur ce processeur : garde-le sans limite." }
        else { $whyOn = (& $g $on) + " = " + [int]($pct * 100) + " % du turbo maximum (" + (& $g $max) + $(if ($known) { "" } else { ", estime" }) + ") : presque autant d'images par seconde, nettement moins chaud." }
    }
    return @{ On = [int]$on; Off = [int]$off; WhyOn = $whyOn; WhyOff = $whyOff; Max = $max; Known = $known }
}
# Ce PC laisse-t-il regler la vitesse du processeur ? (PC virtuels, certains PC d'entreprise ou ARM : non)
function Test-GBTurboSupported {
    $sch = Get-ActiveScheme; if (-not $sch) { return $false }
    return [bool]((Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PERFBOOSTMODE') -or (Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PROCFREQMAX'))
}
function Write-GBProcVal($scheme, $set, $ac, $dc) {
    powercfg /setacvalueindex $scheme SUB_PROCESSOR $set ([int]$ac) 2>$null | Out-Null
    powercfg /setdcvalueindex $scheme SUB_PROCESSOR $set ([int]$dc) 2>$null | Out-Null
}
# (valeurs d'origine gardees dans les vrais reglages, meme pendant un boost avec profil de jeu)
function Set-GBTurboOrig($v) { $Script:Config.TurboOrig = $v; if ($Script:RealConfig) { $Script:RealConfig.TurboOrig = $v }; Save-Config }
# Etat voulu maintenant ($null = rien a changer, reglages d'origine)
function Get-GBTurboWant {
    $base = Get-GBCpuBaseMhz
    if ($Script:Config.TurboOnlyInGame -and -not $Script:Boosted) {
        $m = [int]$Script:Config.TurboOffMhz
        if ($m -le 0 -or $m -eq $base) { return @{ BoostOff = $true; Mhz = 0; Txt = "turbo coupe hors jeu (frequence de base)" } }
        return @{ BoostOff = ($m -lt $base); Mhz = $m; Txt = ("hors jeu limite a " + ("{0:N1}" -f ($m / 1000.0)) + " GHz") }
    }
    $m = [int]$Script:Config.TurboOnMhz
    if ($m -gt 0) { return @{ BoostOff = ($m -le $base); Mhz = $m; Txt = ("turbo limite a " + ("{0:N1}" -f ($m / 1000.0)) + " GHz") } }
    return $null
}
function Set-GBTurboCap([bool]$apply) {
    $o = $Script:Config.TurboOrig
    $want = $null; if ($apply) { $want = Get-GBTurboWant }
    $sch = $null; if ($want) { $sch = Get-ActiveScheme }
    # Valeurs d'origine remises : plus rien a appliquer, ou plan d'alimentation change depuis
    if ($o -and $o.Scheme -and (-not $want -or $o.Scheme -ne $sch)) {
        $bac = $o.BAC; $bdc = $o.BDC; if ($null -eq $bac -and $null -ne $o.AC) { $bac = $o.AC; $bdc = $o.DC }   # (format de la 1re version : mode de boost seul)
        if ($null -ne $bac) { Write-GBProcVal $o.Scheme PERFBOOSTMODE $bac $bdc }
        if ($null -ne $o.FAC) { Write-GBProcVal $o.Scheme PROCFREQMAX $o.FAC $o.FDC }
        if ($null -ne $o.F1AC) { Write-GBProcVal $o.Scheme PROCFREQMAX1 $o.F1AC $o.F1DC }
        if ((Get-ActiveScheme) -eq $o.Scheme) { powercfg /setactive $o.Scheme 2>$null | Out-Null }
        Set-GBTurboOrig $null; $o = $null
        if (-not $want) { if ($Script:TurboLastTxt) { Log "Processeur : turbo et frequence d'origine remis" }; $Script:TurboLastTxt = ""; return }
    }
    if (-not $want -or -not $sch) { return }
    if (-not $o) {
        $b = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PERFBOOSTMODE'
        $f = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PROCFREQMAX'
        $f1 = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PROCFREQMAX1'
        if (-not $b -and -not $f) {   # reglages absents (PC virtuel, PC verrouille...) : rien a faire
            if (-not $Script:TurboNoSupportLogged) { $Script:TurboNoSupportLogged = $true; Log "Vitesse du processeur : ce PC ne permet pas de la regler (PC virtuel ou plan d'alimentation verrouille)" }
            return
        }
        $o = @{ Scheme = $sch; BAC = $(if ($b) { [int]$b.AC } else { $null }); BDC = $(if ($b) { [int]$b.DC } else { $null })
                FAC = $(if ($f) { [int]$f.AC } else { $null }); FDC = $(if ($f) { [int]$f.DC } else { $null })
                F1AC = $(if ($f1) { [int]$f1.AC } else { $null }); F1DC = $(if ($f1) { [int]$f1.DC } else { $null }) }
        Set-GBTurboOrig $o
    }
    $bTarget = $o.BAC; if ($want.BoostOff) { $bTarget = 0 }
    if ($null -ne $o.BAC) { if ($want.BoostOff) { Write-GBProcVal $sch PERFBOOSTMODE 0 0 } else { Write-GBProcVal $sch PERFBOOSTMODE $o.BAC $o.BDC } }
    $mhz = [int]$want.Mhz
    # Pas de "mode de boost" sur ce PC : la frequence maximale fait le travail (frequence de base)
    if ($want.BoostOff -and $null -eq $o.BAC -and $mhz -le 0) { $mhz = Get-GBCpuBaseMhz }
    $fa = $o.FAC; $fd = $o.FDC; $f1a = $o.F1AC; $f1d = $o.F1DC
    if ($mhz -gt 0) { $fa = $mhz; $fd = $mhz; $f1a = $mhz; $f1d = $mhz }
    if ($null -ne $o.FAC) { Write-GBProcVal $sch PROCFREQMAX $fa $fd }
    if ($null -ne $o.F1AC) { Write-GBProcVal $sch PROCFREQMAX1 $f1a $f1d }
    powercfg /setactive $sch 2>$null | Out-Null
    # Verification : Windows a-t-il garde les valeurs ? (PC d'entreprise, plan verrouille par une strategie)
    $ok = $true
    if ($null -ne $o.BAC) { $vb = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PERFBOOSTMODE'; if (-not $vb -or [int]$vb.AC -ne [int]$bTarget) { $ok = $false } }
    if ($null -ne $o.FAC) { $vf = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PROCFREQMAX'; if (-not $vf -or [int]$vf.AC -ne [int]$fa) { $ok = $false } }
    $Script:TurboRefused = (-not $ok)
    if (-not $ok) { if ($Script:TurboLastTxt -ne 'refuse') { $Script:TurboLastTxt = 'refuse'; Log "Vitesse du processeur : Windows a refuse le changement (PC d'entreprise ou plan d'alimentation verrouille)" }; return }
    $txt = $want.Txt
    if ([int]$want.Mhz -gt 0 -and $null -eq $o.FAC) { $txt += " (limite en GHz non disponible sur ce PC : turbo " + $(if ($want.BoostOff) { "coupe" } else { "normal" }) + ")" }
    if ($txt -ne $Script:TurboLastTxt) { $Script:TurboLastTxt = $txt; Log ("Processeur : " + $txt) }
}
function Update-GBTurboCap {
    try { Set-GBTurboCap $true }
    catch { Log ("Vitesse du processeur : " + $_.Exception.Message) }
}

# Engrenage du bouton TURBO : GHz maximum en mode TURBO ON (et en jeu) et en mode TURBO OFF (hors jeu)
function Show-TurboSettings {
    # 1re ouverture (ou nouveau processeur) : analyse et mesure du turbo maximum reel (~2 s)
    $info = Get-GBCpuInfo
    if ([int]$info.Max -le 0) {
        Log "Analyse du processeur (quelques secondes)..."
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor; try { [void](Measure-GBCpuMaxMhz) } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
    }
    $base = [int]$info.Base; $reco = Get-GBTurboReco; $sup = Test-GBTurboSupported
    $fmt = { param($m) ("{0:N1}" -f ($m / 1000.0)) + " GHz" }
    # Plages des curseurs selon le processeur : jusqu'au turbo maximum (+ un peu de marge)
    $top = [int]([math]::Ceiling(([math]::Max([int]$reco.Max, $base + 500) + 300) / 100.0) * 100)
    $onMin = [int]([math]::Max(800, [math]::Min(1500, $base - 500)))
    $vOn = @(); for ($m = $onMin; $m -le $top; $m += 100) { $vOn += $m }
    $recoOnShow = [int]$reco.On; if ($recoOnShow -le 0) { $recoOnShow = [int]$reco.Max }
    $lOn = @(); $cOn = @()
    foreach ($m in $vOn) {
        $t = & $fmt $m; if ($m -eq [int]$reco.On) { $t += " (conseille)" } elseif ($m -eq $base) { $t += " (base)" }
        $lOn += $t
        if ($m -lt $base) { $cOn += $cRed } elseif ([math]::Abs($m - $recoOnShow) -le 300) { $cOn += $cGreen } elseif ($m -lt $recoOnShow) { $cOn += $cCyan } else { $cOn += $cYellow }
    }
    $vOff = @(); for ($m = 800; $m -le $top; $m += 100) { $vOff += $m }
    foreach ($x in @($base, [int]$reco.Off)) { if ($vOff -notcontains $x) { $vOff = @(@($vOff) + $x | Sort-Object -Unique) } }
    $lOff = @(); $cOff = @()
    foreach ($m in $vOff) {
        $t = & $fmt $m; if ($m -eq [int]$reco.Off) { $t += " (conseille)" } elseif ($m -eq $base) { $t += " (base)" }
        $lOff += $t
        if ($m -lt 1200) { $cOff += $cRed } elseif ([math]::Abs($m - [int]$reco.Off) -le 300) { $cOff += $cGreen } elseif ($m -lt [int]$reco.Off) { $cOff += $cCyan } else { $cOff += $cYellow }
    }
    $onCur = [int]$Script:Config.TurboOnMhz; $onFree = ($onCur -le 0)
    if ($onFree) { $onCur = $recoOnShow }
    $onCur = [math]::Max($vOn[0], [math]::Min($vOn[-1], $onCur))
    $iOn = [array]::IndexOf([int[]]$vOn, [int]$onCur); if ($iOn -lt 0) { $iOn = 0 }
    $offCur = [int]$Script:Config.TurboOffMhz; if ($offCur -le 0) { $offCur = $base }
    $offCur = [math]::Max($vOff[0], [math]::Min($vOff[-1], $offCur))
    $iOff = [array]::IndexOf([int[]]$vOff, [int]$offCur); if ($iOff -lt 0) { $iOff = [array]::IndexOf([int[]]$vOff, $base) }

    $d = New-GBDialog "Vitesse du processeur" 640 580
    $null = Add-DlgLabel $d "Vitesse du processeur" 16 8 400 30 $fontPage $cCyan
    # Fiche du processeur analyse
    $fiche = New-Object System.Windows.Forms.Panel; $fiche.BackColor = $cPanel
    $fiche.Location = New-Object System.Drawing.Point(16, 42); $fiche.Size = New-Object System.Drawing.Size(596, 72); $d.Controls.Add($fiche)
    $l1 = $info.Brand + "  |  " + $info.Name
    $l2 = $info.Class + $(if ($info.Suffix) { " (" + $info.Suffix + ")" } else { "" }) + "  |  " + $(if ($info.Cores -gt 0) { "" + $info.Cores + " coeurs / " } else { "" }) + $info.Threads + " threads" + $(if ($info.Hybrid) { ", hybride (performants + economes)" } else { "" })
    $l3 = "Frequence de base " + (& $fmt $base) + "  |  turbo maximum " + $(if ($reco.Known) { (& $fmt $reco.Max) + " (mesure)" } else { "~" + (& $fmt $reco.Max) + " (estime, clique sur Analyser)" })
    $null = Add-DlgLabel $fiche $l1 10 6 470 20 $fontBold $cText
    $null = Add-DlgLabel $fiche $l2 10 27 580 20 $fontSmall $cMuted
    $null = Add-DlgLabel $fiche $l3 10 47 580 20 $fontSmall $cMuted
    $bAna = Add-DlgButton $fiche "Analyser" 490 4 96 24
    $tip.SetToolTip($bAna, "Mesure de nouveau le turbo maximum de ton processeur (2 secondes de calcul).")
    $bAna.Add_Click({ $d.Tag = 'again'; $d.DialogResult = [System.Windows.Forms.DialogResult]::Cancel })
    $null = Add-DlgLabel $d ("Glisse le curseur ou tape la valeur en GHz : moins de GHz = moins chaud et moins de bruit.") 16 120 600 20 $fontUI $cMuted
    $now = Add-DlgLabel $d "En ce moment : ..." 16 142 600 20 $fontBold $cText
    if (-not $sup) { $now.ForeColor = $cRed }
    # Case GHz a taper a la main (meme pas de 0,1 GHz que le curseur)
    $newNum = {
        param($y, $minMhz, $maxMhz, $valMhz)
        $n = New-Object System.Windows.Forms.NumericUpDown
        $n.DecimalPlaces = 1; $n.Increment = [decimal]0.1; $n.Minimum = [decimal]($minMhz / 1000.0); $n.Maximum = [decimal]($maxMhz / 1000.0)
        $n.Value = [decimal]($valMhz / 1000.0); $n.BackColor = $cDeep; $n.ForeColor = $cText; $n.BorderStyle = "FixedSingle"; $n.Font = $fontBold; $n.TextAlign = "Center"
        $n.Location = New-Object System.Drawing.Point(470, $y); $n.Size = New-Object System.Drawing.Size(80, 26)
        $d.Controls.Add($n)
        $null = Add-DlgLabel $d "GHz" 556 ($y + 3) 50 22 $fontBold $cMuted
        return $n
    }
    $ts = @{ Busy = $false }
    $hd1 = New-GBHeader $d "Turbo : ON" "et pendant le boost (jeux)" 16 174 600 22; if ($Script:UiOK) { $hd1.Accent = $cYellow }
    $chkFree = Add-DlgCheck $d "Sans limite (turbo d'origine, le plus rapide et le plus chaud)" 16 202 600 $onFree
    $sOn = New-GBSlider $d 0 ($vOn.Count - 1) $iOn $lOn $cOn "" 16 232 440
    if ($sOn -isnot [System.Windows.Forms.TrackBar]) { $sOn.ValueWidth = 170 }
    $nOn = & $newNum 234 $vOn[0] $vOn[-1] $vOn[$iOn]
    $null = Add-DlgLabel $d ("Conseille : " + $(if ([int]$reco.On -gt 0) { & $fmt $reco.On } else { "sans limite" }) + " - " + $reco.WhyOn) 16 266 600 36 $fontUI $cMuted
    $hd2 = New-GBHeader $d "Turbo : OFF" "hors jeu (internet, Discord, videos)" 16 308 600 22; if ($Script:UiOK) { $hd2.Accent = $cCyan }
    $sOff = New-GBSlider $d 0 ($vOff.Count - 1) $iOff $lOff $cOff "" 16 338 440
    if ($sOff -isnot [System.Windows.Forms.TrackBar]) { $sOff.ValueWidth = 170 }
    $nOff = & $newNum 340 $vOff[0] $vOff[-1] $vOff[$iOff]
    $null = Add-DlgLabel $d ("Conseille : " + (& $fmt $reco.Off) + " - " + $reco.WhyOff + " Sous 1,2 GHz le PC devient lent.") 16 372 600 36 $fontUI $cMuted
    $null = Add-DlgLabel $d "Vert = conseille   Bleu = plus frais, un peu moins rapide   Jaune = plus chaud   Rouge = trop lent" 16 414 600 20 $fontSmall $cMuted
    # Curseur <-> case GHz
    $sOn.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $nOn.Value = [decimal]($vOn[[int]$sOn.Value] / 1000.0); $ts.Busy = $false })
    $sOff.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $nOff.Value = [decimal]($vOff[[int]$sOff.Value] / 1000.0); $ts.Busy = $false })
    $nOn.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $i = [array]::IndexOf([int[]]$vOn, [int][math]::Round([double]$nOn.Value * 1000)); if ($i -ge 0) { Set-SliderValue $sOn $i; $sOn.Invalidate() }; $ts.Busy = $false })
    $nOff.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $i = [array]::IndexOf([int[]]$vOff, [int][math]::Round([double]$nOff.Value * 1000)); if ($i -ge 0) { Set-SliderValue $sOff $i; $sOff.Invalidate() }; $ts.Busy = $false })
    $setFree = { $sOn.Enabled = -not $chkFree.Checked; $nOn.Enabled = -not $chkFree.Checked }
    $chkFree.Add_CheckedChanged($setFree); & $setFree
    $bReco = Add-DlgButton $d "Valeurs conseillees" 16 468 200
    $bReco.ForeColor = $cGreen
    $bReco.Add_Click({
        if ([int]$reco.On -gt 0) { $chkFree.Checked = $false; $nOn.Value = [decimal]($reco.On / 1000.0) } else { $chkFree.Checked = $true }
        $nOff.Value = [decimal]($reco.Off / 1000.0)
    })
    Add-DlgOkCancel $d 468 628
    # PC qui ne permet pas de regler la vitesse du processeur : tout est grise, explication claire
    if (-not $sup) {
        foreach ($c in @($chkFree, $sOn, $nOn, $sOff, $nOff, $bReco, $d.AcceptButton)) { $c.Enabled = $false }
        $now.Text = "Reglage impossible sur ce PC (PC virtuel, PC d'entreprise ou plan verrouille)."
    }
    # Frequence reelle, mise a jour chaque seconde
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1000
    $upd = {
        if (-not $sup) { return }
        try {
            $t = Get-CimInstance Win32_PerfFormattedData_Counters_ProcessorInformation -Filter "Name='_Total'" -ErrorAction Stop
            $mhz = [double]$t.ProcessorFrequency * [double]$t.PercentProcessorPerformance / 100
            $mode = "TURBO : ON"; if ($Script:Config.TurboOnlyInGame -and -not $Script:Boosted) { $mode = "TURBO : OFF" }; if ($Script:Boosted) { $mode = "BOOST en cours" }
            $now.Text = "En ce moment : " + ("{0:N1}" -f ($mhz / 1000.0)) + " GHz  (" + $mode + ")"
        } catch { $now.Text = "" }
    }
    $tm.Add_Tick($upd)
    $d.Add_Shown({ & $upd; $tm.Start() })
    try {
        if ($d.ShowDialog($form) -eq "OK") {
            # La case GHz fait foi (valeur tapee a la main ou suivie du curseur)
            if ($chkFree.Checked) { $Script:Config.TurboOnMhz = 0 } else { $Script:Config.TurboOnMhz = [int][math]::Round([double]$nOn.Value * 10) * 100 }
            $off = [int][math]::Round([double]$nOff.Value * 10) * 100; if ($off -eq $base) { $off = 0 }
            $Script:Config.TurboOffMhz = $off
            Save-Config
            Log ("Vitesse du processeur : TURBO ON = " + $(if ($Script:Config.TurboOnMhz -gt 0) { & $fmt $Script:Config.TurboOnMhz } else { "sans limite" }) +
                 ", TURBO OFF = " + $(if ($off -gt 0) { & $fmt $off } else { "frequence de base (" + (& $fmt $base) + ")" }))
            Update-GBTurboCap
        }
    } finally { $tm.Stop(); $tm.Dispose(); $again = ($d.Tag -eq 'again'); $d.Dispose() }
    # "Analyser" : nouvelle mesure puis la fenetre se rouvre avec les nouvelles valeurs conseillees
    if ($again) {
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try { [void](Measure-GBCpuMaxMhz) } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
        Show-TurboSettings
    }
}

# --- Carte graphique : bouton GPU ON / ECO + engrenage (meme principe que TURBO) ---
# NVIDIA : outil officiel nvidia-smi (installe avec le pilote) : frequence maximale de la carte verrouillee (-lgc / -rgc)
#   et limite de puissance relevee au maximum autorise par NVIDIA pendant le boost (-pl), si la carte le permet.
# AMD, Intel, autres : pas d'outil officiel en ligne de commande -> analyse de la carte + leur logiciel officiel (reglage auto).
# Tout est remis a la fermeture de GameBoost, avec TOUT RESTAURER, et au demarrage suivant apres un arret brutal.
function Find-GBNvidiaSmi {
    if ($null -ne $Script:NvSmi) { return $Script:NvSmi }
    $Script:NvSmi = ''
    foreach ($p in @((Join-Path $env:SystemRoot 'System32\nvidia-smi.exe'), (Join-Path $env:ProgramFiles 'NVIDIA Corporation\NVSMI\nvidia-smi.exe'))) {
        if (Test-Path -LiteralPath $p) { $Script:NvSmi = $p; break }
    }
    return $Script:NvSmi
}
function Invoke-GBSmi([string[]]$a) {
    $smi = Find-GBNvidiaSmi; if (-not $smi) { return @{ Code = -1; Out = 'nvidia-smi absent' } }
    $o = @(& $smi @a 2>&1 | ForEach-Object { [string]$_ })
    return @{ Code = $LASTEXITCODE; Out = ($o -join ' ').Trim() }
}
function ConvertTo-GBNum($s) { $v = 0.0; if ([double]::TryParse(([string]$s).Trim(), [Globalization.NumberStyles]::Float, [Globalization.CultureInfo]::InvariantCulture, [ref]$v)) { return $v }; return $null }
# Fiche de la carte des jeux : marque, modele, memoire, pilote, horloges, puissance, temperature, et ce que GameBoost peut regler
function Get-GBGpuCtlInfo([switch]$Fresh) {
    if ($Script:GpuCtlInfo -and -not $Fresh) { return $Script:GpuCtlInfo }
    $g = $Script:MainGpu
    $name = ''; if ($g) { $name = [string]$g.Name }
    $vendor = 'autre'
    if ($name -match 'NVIDIA|GeForce|Quadro|RTX|GTX') { $vendor = 'NVIDIA' } elseif ($name -match 'AMD|Radeon') { $vendor = 'AMD' } elseif ($name -match 'Intel|Arc') { $vendor = 'Intel' } elseif ($name -match 'Qualcomm|Adreno') { $vendor = 'Qualcomm' }
    $i = @{ Name = $name; Vendor = $vendor; Kind = $(if ($g) { [string]$g.KindLabel } else { '' }); Vram = $(if ($g) { $g.VramGo } else { $null }); Driver = $(if ($g) { [string]$g.DriverVersion } else { '' })
            Smi = $false; MaxMhz = 0; CurMhz = $null; MemMhz = $null; Watts = $null; PlCur = $null; PlDef = $null; PlMax = $null; Temp = $null
            CanLock = $false; CanPower = $false; Why = '' }
    if (-not $name) { $i.Why = "Aucune carte graphique reconnue par Windows (pilote absent ?)."; $Script:GpuCtlInfo = $i; return $i }
    if ($vendor -eq 'NVIDIA' -and (Find-GBNvidiaSmi)) {
        $r = Invoke-GBSmi @('--query-gpu=name,clocks.max.gr,clocks.gr,clocks.max.mem,power.draw,power.limit,power.default_limit,power.max_limit,temperature.gpu,driver_version', '--format=csv,noheader,nounits')
        if ($r.Code -eq 0 -and $r.Out) {
            $f = @(($r.Out -split "`n")[0].Split(',') | ForEach-Object { $_.Trim() })
            if ($f.Count -ge 10) {
                $i.Smi = $true; $i.MaxMhz = [int](ConvertTo-GBNum $f[1]); $i.CurMhz = ConvertTo-GBNum $f[2]; $i.MemMhz = ConvertTo-GBNum $f[3]; $i.Watts = ConvertTo-GBNum $f[4]
                $i.PlCur = ConvertTo-GBNum $f[5]; $i.PlDef = ConvertTo-GBNum $f[6]; $i.PlMax = ConvertTo-GBNum $f[7]; $i.Temp = ConvertTo-GBNum $f[8]; if ($f[9]) { $i.Driver = $f[9] }
            }
        }
        if ($i.Smi -and $i.MaxMhz -gt 0) {
            # Verrouillage refuse par une ancienne carte : note pour ne plus essayer
            $i.CanLock = ([string]$Script:Config.GpuNoLock -ne $name)
            $i.CanPower = ($null -ne $i.PlCur -and $null -ne $i.PlDef -and $null -ne $i.PlMax -and $i.PlMax -gt $i.PlDef + 1)
            if (-not $i.CanLock) { $i.Why = "Cette carte NVIDIA n'accepte pas le verrouillage de frequence (carte trop ancienne ou pilote)." }
        } else { $i.Why = "L'outil officiel NVIDIA (nvidia-smi) ne repond pas : mets a jour le pilote NVIDIA." }
    } elseif ($vendor -eq 'NVIDIA') { $i.Why = "L'outil officiel NVIDIA (nvidia-smi) est absent : installe le pilote NVIDIA complet." }
    else { $i.Why = "Les cartes " + $vendor + " ne se reglent qu'avec le logiciel officiel du fabricant (bouton ci-dessous) : GameBoost n'installe aucun pilote d'overclocking." }
    $Script:GpuCtlInfo = $i
    return $i
}
# Valeurs conseillees : en jeu sans limite (la carte fabrique les images : la brider = moins d'images) ;
# mode ECO hors jeu = ~45 % de la frequence maximale (bureau, videos, navigation), jamais sous 600 MHz
function Get-GBGpuReco {
    $i = Get-GBGpuCtlInfo; $max = [int]$i.MaxMhz
    $eco = 0; if ($max -gt 0) { $eco = [int]([math]::Max(600, [math]::Min($max - 300, [math]::Round($max * 0.45 / 100.0) * 100))) }
    $quiet = 0; if ($max -gt 0) { $quiet = [int]([math]::Round($max * 0.85 / 100.0) * 100) }
    return @{ On = 0; Eco = $eco; Quiet = $quiet; Max = $max }
}
function Get-GBGpuWant {
    $i = Get-GBGpuCtlInfo
    $mhz = 0; $txt = ""
    if ($Script:Config.GpuEco -and -not $Script:Boosted) {
        $mhz = [int]$Script:Config.GpuEcoMhz; if ($mhz -le 0) { $mhz = [int](Get-GBGpuReco).Eco }
        $txt = "mode ECO hors jeu, " + ("{0:N2}" -f ($mhz / 1000.0)) + " GHz maximum"
    } elseif ([int]$Script:Config.GpuOnMhz -gt 0) {
        $mhz = [int]$Script:Config.GpuOnMhz; $txt = "limitee a " + ("{0:N2}" -f ($mhz / 1000.0)) + " GHz"
    }
    if ($mhz -gt 0 -and $i.MaxMhz -gt 0 -and $mhz -ge $i.MaxMhz) { $mhz = 0; $txt = "" }   # = maximum : pas de verrou
    $pow = [bool]($Script:Boosted -and $Script:Config.GpuPowerMax -and $i.CanPower)
    if ($pow) { if ($txt) { $txt += ", " }; $txt += "puissance au maximum (" + [int]$i.PlMax + " W)" }
    return @{ Mhz = $mhz; Power = $pow; Txt = $txt }
}
function Set-GBGpuCap([bool]$apply) {
    $locked = [bool]$Script:Config.GpuLocked; $plSet = [bool]$Script:Config.GpuPlSet
    # Aucun reglage de carte choisi et rien d'applique : rien a faire (pas d'appel a nvidia-smi)
    if (-not $locked -and -not $plSet -and -not ($apply -and ($Script:Config.GpuEco -or [int]$Script:Config.GpuOnMhz -gt 0 -or ($Script:Config.GpuPowerMax -and $Script:Boosted)))) { return }
    $i = Get-GBGpuCtlInfo
    if (-not $i.Smi) { return }
    $want = @{ Mhz = 0; Power = $false; Txt = "" }; if ($apply) { $want = Get-GBGpuWant }
    $key = "" + $want.Mhz + "|" + $want.Power
    if ($key -eq $Script:GpuLastKey -and ($want.Mhz -gt 0) -eq $locked -and $want.Power -eq $plSet) { return }
    $changed = $false
    # Frequence maximale
    if ($want.Mhz -gt 0 -and $i.CanLock) {
        $ok = $false; $last = $null
        foreach ($mn in @(0, 210, 300)) {   # plus basse frequence acceptee selon les cartes
            $last = Invoke-GBSmi @('-lgc', ("" + $mn + "," + $want.Mhz))
            if ($last.Code -eq 0 -and $last.Out -notmatch 'not supported|Not Supported') { $ok = $true; break }
            if ($last.Out -match 'permission|not supported|Not Supported') { break }
        }
        if ($ok) { $Script:Config.GpuLocked = $true; $changed = $true }
        else {
            if ($last.Out -match 'not supported|Not Supported') { $Script:Config.GpuNoLock = $i.Name; $i.CanLock = $false }
            Log ("Carte graphique : frequence non modifiable (" + $last.Out + ")")
        }
    } elseif ($locked) {
        $r = Invoke-GBSmi @('-rgc'); if ($r.Code -eq 0) { $Script:Config.GpuLocked = $false; $changed = $true } else { Log ("Carte graphique : remise de la frequence impossible (" + $r.Out + ")") }
    }
    # Limite de puissance (OC autorise par NVIDIA, pendant le boost)
    if ($want.Power) {
        if (-not $plSet) { $Script:Config.GpuPlDefault = [double]$i.PlDef }
        $r = Invoke-GBSmi @('-pl', ("" + [int]$i.PlMax))
        # (nvidia-smi repond "All done" avec le code 0 meme quand il refuse : le texte fait foi)
        if ($r.Code -eq 0 -and $r.Out -notmatch 'not supported|Not Supported') { $Script:Config.GpuPlSet = $true; $changed = $true }
        else { $Script:Config.GpuPowerMax = $false; Log ("Carte graphique : puissance non modifiable sur ce PC (" + $r.Out + ")") }
    } elseif ($plSet) {
        $dw = [double]$Script:Config.GpuPlDefault; if ($dw -le 0 -and $i.PlDef) { $dw = [double]$i.PlDef }
        $r = Invoke-GBSmi @('-pl', ("" + [int]$dw)); if ($r.Code -eq 0) { $Script:Config.GpuPlSet = $false; $changed = $true }
    }
    $Script:GpuLastKey = $key
    if ($changed) {
        if ($Script:RealConfig) { foreach ($k in 'GpuLocked', 'GpuPlSet', 'GpuPlDefault', 'GpuNoLock') { $Script:RealConfig[$k] = $Script:Config[$k] } }
        Save-Config
        if ($want.Txt) { Log ("Carte graphique : " + $want.Txt) } else { Log "Carte graphique : frequence et puissance d'origine" }
    }
}
function Update-GBGpuCap {
    try { Set-GBGpuCap $true } catch { Log ("Carte graphique : " + $_.Exception.Message) }
}
# Logiciel officiel du fabricant (reglage automatique / overclocking officiel)
function Open-GBGpuTuning {
    $i = Get-GBGpuCtlInfo; $pf = $env:ProgramFiles
    if ($i.Vendor -eq 'NVIDIA') {
        $app = Join-Path $pf 'NVIDIA Corporation\NVIDIA app\CEF\NVIDIA app.exe'
        if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app; Log "Ouverture de NVIDIA App (Systeme > Performances > Reglage automatique)"; return }
        Start-Process "https://www.nvidia.com/fr-fr/software/nvidia-app/"; return
    }
    if ($i.Vendor -eq 'AMD') {
        $app = Join-Path $pf 'AMD\CNext\CNext\RadeonSoftware.exe'
        if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app; Log "Ouverture d'AMD Adrenalin (Performances > Reglage)"; return }
        Start-Process "https://www.amd.com/fr/support/downloads/drivers.html"; return
    }
    if ($i.Vendor -eq 'Intel') {
        $app = Join-Path $pf 'Intel\Intel Graphics Software\IntelGraphicsSoftware.exe'
        if (Test-Path -LiteralPath $app) { Start-Process -FilePath $app; Log "Ouverture d'Intel Graphics Software (Performances)"; return }
        Start-Process "https://www.intel.com/content/www/fr/fr/support/detect.html"; return
    }
    [System.Windows.Forms.MessageBox]::Show("Pas de logiciel de reglage connu pour cette carte graphique.", "GameBoost") | Out-Null
}

# --- Applis sur la carte graphique (comme Parametres Windows > Affichage > Graphiques), toutes marques ---
# HKCU\Software\Microsoft\DirectX\UserGpuPreferences : valeur = chemin de l'exe, donnee "GpuPreference=0/1/2;"
# (0 = Windows decide, 1 = economie d'energie, 2 = hautes performances). Les autres reglages Windows de la meme appli sont gardes.
$Script:AppGpuNames = @{ 0 = "Windows decide"; 1 = "Economie d'energie"; 2 = "Hautes performances" }
function Get-GBAppGpuList {
    $list = New-Object System.Collections.ArrayList
    try {
        $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Microsoft\DirectX\UserGpuPreferences')
        if ($k) {
            try {
                foreach ($n in $k.GetValueNames()) {
                    if (-not $n -or $n -eq 'DirectXUserGlobalSettings') { continue }
                    $raw = [string]$k.GetValue($n)
                    $pref = $null; if ($raw -match 'GpuPreference=(\d)') { $pref = [int]$Matches[1] }
                    if ($null -eq $pref) { continue }
                    [void]$list.Add(@{ Path = $n; Pref = $pref; Raw = $raw })
                }
            } finally { $k.Close() }
        }
    } catch {}
    return $list.ToArray()
}
# $pref = 0, 1 ou 2 ; -1 = retirer le choix (l'appli revient au choix automatique de Windows)
function Set-GBAppGpuPref([string]$path, [int]$pref) {
    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey('Software\Microsoft\DirectX\UserGpuPreferences')
    try {
        $parts = @(([string]$k.GetValue($path)).Split(';') | Where-Object { $_ -and $_ -notmatch '^GpuPreference=' })
        if ($pref -ge 0) { $parts = @("GpuPreference=" + $pref) + $parts }
        if ($parts.Count -eq 0) { $k.DeleteValue($path, $false) } else { $k.SetValue($path, (($parts -join ';') + ';'), [Microsoft.Win32.RegistryValueKind]::String) }
    } finally { $k.Close() }
    # Choix fait a la main : permanent (TOUT RESTAURER ne le retire pas, comme dans les Parametres de Windows)
    $Script:Config.GpuPrefAdded = @($Script:Config.GpuPrefAdded | Where-Object { $_ -and $_ -ne $path }); Save-Config
}
function Show-AppGpuSettings {
    $d = New-GBDialog "Applis sur la carte graphique" 820 560
    $d.FormBorderStyle = "Sizable"; $d.MaximizeBox = $true; $d.MinimumSize = New-Object System.Drawing.Size(700, 420)
    $null = Add-DlgLabel $d "Applis sur la carte graphique" 16 6 600 30 $fontPage $cGreen
    $hi = $Script:MainGpu; $lo = $Script:IGpu
    $txt = "Comme dans Parametres Windows > Affichage > Graphiques : choisis sur quelle carte tourne chaque appli.`r`nPrend effet au prochain lancement de l'appli. Selectionne une ou plusieurs lignes puis choisis la carte."
    if ($Script:GpuHybrid) { $txt += "`r`nHautes performances = " + $hi.Short + "   |   Economie d'energie = " + $lo.Short }
    else { $txt += "`r`nCe PC n'a qu'une carte graphique : le choix est enregistre mais ne change rien." }
    $info = Add-DlgLabel $d $txt 16 38 780 56 $fontUI $cMuted; $info.Anchor = "Top, Left, Right"
    $lv = New-Object System.Windows.Forms.ListView
    $lv.View = "Details"; $lv.FullRowSelect = $true; $lv.MultiSelect = $true; $lv.HideSelection = $false
    $lv.Location = New-Object System.Drawing.Point(16, 98); $lv.Size = New-Object System.Drawing.Size(772, 316); $lv.Anchor = "Top, Bottom, Left, Right"
    foreach ($c in @(@('Appli', 200), @('Carte graphique', 220), @('Emplacement', 340))) { [void]$lv.Columns.Add($c[0], $c[1]) }
    Set-GBListViewStyle $lv; $d.Controls.Add($lv)
    $st = @{ Lv = $lv }
    $st.Fill = {
        $st.Lv.BeginUpdate(); $st.Lv.Items.Clear()
        foreach ($a in @(Get-GBAppGpuList | Sort-Object { [IO.Path]::GetFileName($_.Path) })) {
            $nm = [IO.Path]::GetFileNameWithoutExtension($a.Path); $lbl = Get-GameLabel $nm; if ($lbl -ne $nm) { $nm = $lbl + " (" + [IO.Path]::GetFileName($a.Path) + ")" } else { $nm = [IO.Path]::GetFileName($a.Path) }
            $it = New-Object System.Windows.Forms.ListViewItem($nm)
            [void]$it.SubItems.Add($Script:AppGpuNames[[int]$a.Pref]); [void]$it.SubItems.Add([IO.Path]::GetDirectoryName($a.Path))
            if ([int]$a.Pref -eq 2) { $it.ForeColor = $cGreen } elseif ([int]$a.Pref -eq 1) { $it.ForeColor = $cCyan } else { $it.ForeColor = $cText }
            if (-not (Test-Path -LiteralPath $a.Path)) { $it.ForeColor = $cMuted; $it.SubItems[1].Text += " (appli absente)" }
            $it.Tag = $a.Path; [void]$st.Lv.Items.Add($it)
        }
        $st.Lv.EndUpdate()
    }
    $st.Set = {
        param($pref)
        $paths = @($st.Lv.SelectedItems | ForEach-Object { [string]$_.Tag })
        if ($paths.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Selectionne une ou plusieurs applis dans la liste.", "GameBoost") | Out-Null; return }
        foreach ($p in $paths) { try { Set-GBAppGpuPref $p $pref; Log ("Carte graphique pour " + [IO.Path]::GetFileName($p) + " : " + $(if ($pref -ge 0) { $Script:AppGpuNames[$pref] } else { "choix retire" })) } catch { Log ("Carte graphique pour " + $p + " : echec (" + $_.Exception.Message + ")") } }
        & $st.Fill
    }
    $st.Add = {
        param($path)
        if (-not $path -or -not (Test-Path -LiteralPath $path)) { return }
        $exist = @(Get-GBAppGpuList | Where-Object { $_.Path -ieq $path })
        if ($exist.Count -eq 0) { Set-GBAppGpuPref $path 2; Log ("Carte graphique pour " + [IO.Path]::GetFileName($path) + " : Hautes performances") }
        & $st.Fill
        foreach ($it in $st.Lv.Items) { $it.Selected = ([string]$it.Tag -ieq $path); if ($it.Selected) { $it.EnsureVisible() } }
    }
    $y = 424
    $bExe = Add-DlgButton $d "Ajouter un .exe..." 16 $y 160; $bExe.ForeColor = $cGreen
    $bRun = Add-DlgButton $d "Ajouter une appli ouverte..." 184 $y 210; $bRun.ForeColor = $cGreen
    $bHi = Add-DlgButton $d "Hautes performances" 16 ($y + 38) 180; $bHi.ForeColor = $cGreen
    $bLo = Add-DlgButton $d "Economie d'energie" 204 ($y + 38) 170; $bLo.ForeColor = $cCyan
    $bAuto = Add-DlgButton $d "Windows decide" 382 ($y + 38) 150
    $bDel = Add-DlgButton $d "Retirer" 540 ($y + 38) 110; $bDel.ForeColor = $cRed
    $bClose = Add-DlgButton $d "Fermer" 672 ($y + 38) 116
    foreach ($b in @($bExe, $bRun, $bHi, $bLo, $bAuto, $bDel)) { $b.Anchor = "Bottom, Left" }
    $bClose.Anchor = "Bottom, Right"; $d.CancelButton = $bClose; $bClose.Add_Click({ $d.Close() })
    $bHi.Add_Click({ & $st.Set 2 }); $bLo.Add_Click({ & $st.Set 1 }); $bAuto.Add_Click({ & $st.Set 0 }); $bDel.Add_Click({ & $st.Set (-1) })
    $bExe.Add_Click({
        $o = New-Object System.Windows.Forms.OpenFileDialog; $o.Filter = "Programme (*.exe)|*.exe"; $o.Title = "Choisis le programme"; $o.Multiselect = $true
        if ($o.ShowDialog() -eq 'OK') { foreach ($fn in $o.FileNames) { & $st.Add $fn } }
        $o.Dispose()
    })
    $bRun.Add_Click({
        # Programmes ouverts avec une fenetre (chemin complet connu)
        $menu = New-Object System.Windows.Forms.ContextMenuStrip
        $seen = @{}
        foreach ($p in @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne [IntPtr]::Zero -and $_.Id -ne $PID } | Sort-Object ProcessName)) {
            $path = $null; try { $path = Get-ProcessPath $p } catch {}
            if (-not $path -or $seen.ContainsKey($path) -or $path -match '\\Windows\\(System32|SystemApps|explorer)') { continue }
            $seen[$path] = $true
            $mi = $menu.Items.Add($p.ProcessName + "   (" + $path + ")"); $mi.Tag = $path
        }
        if ($menu.Items.Count -eq 0) { [void]$menu.Items.Add("Aucune appli ouverte trouvee") }
        $menu.add_ItemClicked({ param($s, $e) if ($e.ClickedItem.Tag) { & $st.Add ([string]$e.ClickedItem.Tag) } })
        # Menu libere apres usage (un nouveau est cree a chaque clic)
        # (apres sa fermeture, meme si la fenetre a ete fermee entre-temps)
        $menu.add_Closed({ param($s, $e) try { $m = $s; if ($m.IsHandleCreated -and -not $m.IsDisposed) { [void]$m.BeginInvoke([Action]({ try { $m.Dispose() } catch {} }.GetNewClosure())) } else { $m.Dispose() } } catch {} })
        $menu.Show($bRun, (New-Object System.Drawing.Point(0, $bRun.Height)))
    })
    $lv.add_KeyDown({ param($s, $e) if ($e.KeyCode -eq 'Delete') { & $st.Set (-1) } })
    & $st.Fill
    try { [void]$d.ShowDialog($form) } finally { $d.Dispose() }
}

# Engrenage du bouton GPU : frequence maximale en jeu et en mode ECO, puissance au maximum pendant le boost
function Show-GpuSettings {
    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
    try { $i = Get-GBGpuCtlInfo -Fresh } finally { $form.Cursor = [System.Windows.Forms.Cursors]::Default }
    $reco = Get-GBGpuReco
    $ctl = ($i.Smi -and $i.CanLock -and $i.MaxMhz -gt 0)
    $g2 = { param($m) ("{0:N2}" -f ($m / 1000.0)) + " GHz" }
    $tool = Get-GpuVendorToolName $i.Name; if ($i.Vendor -eq 'Intel') { $tool = "Intel Graphics Software" }
    $d = New-GBDialog "Carte graphique" 640 600
    $null = Add-DlgLabel $d "Carte graphique" 16 8 400 30 $fontPage $cGreen
    $fiche = New-Object System.Windows.Forms.Panel; $fiche.BackColor = $cPanel
    $fiche.Location = New-Object System.Drawing.Point(16, 42); $fiche.Size = New-Object System.Drawing.Size(596, 72); $d.Controls.Add($fiche)
    $l1 = $i.Vendor + "  |  " + $(if ($i.Name) { $i.Name } else { "carte non reconnue" })
    $l2 = $(if ($i.Kind) { $i.Kind } else { "" }) + $(if ($i.Vram) { "  |  " + $i.Vram + " Go de memoire video" } else { "" }) + $(if ($i.Driver) { "  |  pilote " + $i.Driver } else { "" })
    $l3 = ""
    if ($i.Smi) {
        $l3 = "Frequence maximale " + (& $g2 $i.MaxMhz) + $(if ($i.MemMhz) { "  |  memoire " + [int]$i.MemMhz + " MHz" } else { "" }) +
              $(if ($null -ne $i.PlCur) { "  |  puissance " + [int]$i.PlCur + " W (max " + [int]$i.PlMax + " W)" } elseif ($null -ne $i.PlMax) { "  |  puissance geree par le PC (max " + [int]$i.PlMax + " W)" } else { "" })
    } else { $l3 = "Reglage direct : non disponible pour cette carte" }
    $null = Add-DlgLabel $fiche $l1 10 6 580 20 $fontBold $cText
    $null = Add-DlgLabel $fiche $l2 10 27 580 20 $fontSmall $cMuted
    $null = Add-DlgLabel $fiche $l3 10 47 580 20 $fontSmall $cMuted
    $now = Add-DlgLabel $d "" 16 122 600 20 $fontBold $cText
    if (-not $ctl) { $now.Text = $i.Why; $now.ForeColor = $cYellow; $now.Size = New-Object System.Drawing.Size(600, 40) }

    # Plages : 300 MHz ... frequence maximale (pas de 50 MHz)
    $max = [int]$i.MaxMhz; if ($max -le 0) { $max = 3000 }
    $vals = @(); for ($m = 300; $m -le $max; $m += 50) { $vals += $m }; if ($vals[-1] -ne $max) { $vals += $max }
    foreach ($x in @([int]$reco.Eco, [int]$reco.Quiet)) { if ($x -gt 0 -and $vals -notcontains $x) { $vals = @(@($vals) + $x | Sort-Object -Unique) } }
    $mkLabels = {
        param($recoV)
        $l = @(); $c = @()
        foreach ($m in $vals) {
            $t = & $g2 $m; if ($m -eq $recoV) { $t += " (conseille)" } elseif ($m -eq $max) { $t += " (max)" }
            $l += $t
            if ($m -lt 600) { $c += $cRed } elseif ([math]::Abs($m - $recoV) -le 200) { $c += $cGreen } elseif ($m -lt $recoV) { $c += $cCyan } else { $c += $cYellow }
        }
        return @{ L = $l; C = $c }
    }
    $lbOn = & $mkLabels $max; $lbEco = & $mkLabels ([int]$reco.Eco)
    $onCur = [int]$Script:Config.GpuOnMhz; $onFree = ($onCur -le 0); if ($onFree) { $onCur = [int]$reco.Quiet }
    $iOn = [array]::IndexOf([int[]]$vals, [int]$onCur); if ($iOn -lt 0) { $iOn = $vals.Count - 1 }
    $ecoCur = [int]$Script:Config.GpuEcoMhz; if ($ecoCur -le 0) { $ecoCur = [int]$reco.Eco }
    $iEco = [array]::IndexOf([int[]]$vals, [int]$ecoCur); if ($iEco -lt 0) { $iEco = 0 }
    $newNum = {
        param($y, $valMhz)
        $n = New-Object System.Windows.Forms.NumericUpDown
        $n.DecimalPlaces = 2; $n.Increment = [decimal]0.05; $n.Minimum = [decimal]($vals[0] / 1000.0); $n.Maximum = [decimal]($vals[-1] / 1000.0)
        $n.Value = [decimal]($valMhz / 1000.0); $n.BackColor = $cDeep; $n.ForeColor = $cText; $n.BorderStyle = "FixedSingle"; $n.Font = $fontBold; $n.TextAlign = "Center"
        $n.Location = New-Object System.Drawing.Point(470, $y); $n.Size = New-Object System.Drawing.Size(80, 26)
        $d.Controls.Add($n); $null = Add-DlgLabel $d "GHz" 556 ($y + 3) 50 22 $fontBold $cMuted
        return $n
    }
    $toIdx = { param($v) $best = 0; $bd = [int]::MaxValue; for ($k = 0; $k -lt $vals.Count; $k++) { $dd = [math]::Abs($vals[$k] - $v); if ($dd -lt $bd) { $bd = $dd; $best = $k } }; return $best }
    $ts = @{ Busy = $false }
    $hd1 = New-GBHeader $d "GPU : ON" "et pendant le boost (jeux)" 16 166 600 22; if ($Script:UiOK) { $hd1.Accent = $cGreen }
    $chkFree = Add-DlgCheck $d "Sans limite (conseille en jeu : c'est la carte qui fabrique les images)" 16 194 600 $onFree
    $sOn = New-GBSlider $d 0 ($vals.Count - 1) $iOn $lbOn.L $lbOn.C "" 16 224 440
    if ($sOn -isnot [System.Windows.Forms.TrackBar]) { $sOn.ValueWidth = 170 }
    $nOn = & $newNum 226 $vals[$iOn]
    $null = Add-DlgLabel $d ("Limiter = moins d'images par seconde mais moins chaud et moins de bruit. Pour un portable plus silencieux : " + (& $g2 $reco.Quiet) + " (85 %).") 16 258 600 36 $fontUI $cMuted
    $hd2 = New-GBHeader $d "GPU : ECO" "hors jeu (bureau, videos, internet)" 16 300 600 22; if ($Script:UiOK) { $hd2.Accent = $cCyan }
    $sEco = New-GBSlider $d 0 ($vals.Count - 1) $iEco $lbEco.L $lbEco.C "" 16 330 440
    if ($sEco -isnot [System.Windows.Forms.TrackBar]) { $sEco.ValueWidth = 170 }
    $nEco = & $newNum 332 $vals[$iEco]
    $null = Add-DlgLabel $d ("Conseille : " + $(if ($reco.Eco -gt 0) { & $g2 $reco.Eco } else { "-" }) + " (45 % du maximum) : largement assez hors jeu (les videos ont leur propre circuit), carte plus froide et ventilateurs plus calmes.") 16 364 600 36 $fontUI $cMuted
    $hd3 = New-GBHeader $d "OC" "overclocking autorise" 16 406 600 22; if ($Script:UiOK) { $hd3.Accent = $cYellow }
    $chkPow = Add-DlgCheck $d "Puissance au maximum pendant le boost" 16 434 380 ([bool]$Script:Config.GpuPowerMax)
    if ($i.CanPower) { $powTxt = "" + [int]$i.PlDef + " W -> " + [int]$i.PlMax + " W (limite NVIDIA, sans risque)" }
    else { $chkPow.Enabled = $false; $chkPow.Checked = $false; $powTxt = "puissance verrouillee par le fabricant du PC (normal sur les portables)" }
    $null = Add-DlgLabel $d $powTxt 400 437 220 36 $fontSmall $cMuted
    $bApps = Add-DlgButton $d "Applis sur la carte graphique..." 386 470 226 28
    $bApps.ForeColor = $cGreen
    $tip.SetToolTip($bApps, "Choisis sur quelle carte tourne chaque appli (comme Parametres Windows > Affichage > Graphiques).")
    $bApps.Add_Click({ Show-AppGpuSettings })
    $bTool = Add-DlgButton $d ("Reglage auto / OC dans " + $tool) 16 470 360 28
    $bTool.ForeColor = $cYellow
    $tip.SetToolTip($bTool, "Overclocking ou undervolt automatique officiel du fabricant (teste par sa propre appli). GameBoost n'installe aucun pilote d'overclocking.")
    $bTool.Add_Click({ Open-GBGpuTuning })
    # Curseurs <-> cases GHz
    $sOn.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $nOn.Value = [decimal]($vals[[int]$sOn.Value] / 1000.0); $ts.Busy = $false })
    $sEco.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; $nEco.Value = [decimal]($vals[[int]$sEco.Value] / 1000.0); $ts.Busy = $false })
    $nOn.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; Set-SliderValue $sOn (& $toIdx ([double]$nOn.Value * 1000)); $sOn.Invalidate(); $ts.Busy = $false })
    $nEco.add_ValueChanged({ if ($ts.Busy) { return }; $ts.Busy = $true; Set-SliderValue $sEco (& $toIdx ([double]$nEco.Value * 1000)); $sEco.Invalidate(); $ts.Busy = $false })
    $setFree = { $sOn.Enabled = ($ctl -and -not $chkFree.Checked); $nOn.Enabled = ($ctl -and -not $chkFree.Checked) }
    $chkFree.Add_CheckedChanged($setFree); & $setFree
    $bReco = Add-DlgButton $d "Valeurs conseillees" 16 516 200
    $bReco.ForeColor = $cGreen
    $bReco.Add_Click({ $chkFree.Checked = $true; if ($reco.Eco -gt 0) { $nEco.Value = [decimal]($reco.Eco / 1000.0) } })
    Add-DlgOkCancel $d 516 628
    if (-not $ctl) { foreach ($c in @($chkFree, $sOn, $nOn, $sEco, $nEco, $bReco)) { $c.Enabled = $false } }
    if (-not $ctl -and -not $i.CanPower) { $d.AcceptButton.Enabled = $false }
    # Etat reel de la carte, chaque 1,5 s (NVIDIA)
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1500
    $upd = {
        if (-not $ctl) { return }
        $r = Invoke-GBSmi @('--query-gpu=clocks.gr,power.draw,temperature.gpu', '--format=csv,noheader,nounits')
        if ($r.Code -ne 0) { return }
        $f = @($r.Out.Split(',') | ForEach-Object { $_.Trim() })
        $mode = "GPU : ON"; if ($Script:Config.GpuEco -and -not $Script:Boosted) { $mode = "GPU : ECO" }; if ($Script:Boosted) { $mode = "BOOST en cours" }
        $now.Text = "En ce moment : " + $f[0] + " MHz" + $(if ((ConvertTo-GBNum $f[1]) -ne $null) { ", " + [int](ConvertTo-GBNum $f[1]) + " W" } else { "" }) + $(if ($f.Count -gt 2 -and $f[2] -match '^\d') { ", " + [int][math]::Round([double](ConvertTo-GBNum $f[2])) + " C" } else { "" }) + "  (" + $mode + ")"
    }
    $tm.Add_Tick($upd)
    $d.Add_Shown({ & $upd; $tm.Start() })
    try {
        if ($d.ShowDialog($form) -eq "OK") {
            if ($ctl) {
                if ($chkFree.Checked) { $Script:Config.GpuOnMhz = 0 } else { $Script:Config.GpuOnMhz = [int]$vals[(& $toIdx ([double]$nOn.Value * 1000))] }
                $Script:Config.GpuEcoMhz = [int]$vals[(& $toIdx ([double]$nEco.Value * 1000))]
            }
            $Script:Config.GpuPowerMax = [bool]($chkPow.Enabled -and $chkPow.Checked)
            Save-Config
            Log ("Carte graphique : GPU ON = " + $(if ($Script:Config.GpuOnMhz -gt 0) { & $g2 $Script:Config.GpuOnMhz } else { "sans limite" }) + ", GPU ECO = " + (& $g2 $Script:Config.GpuEcoMhz) +
                 $(if ($Script:Config.GpuPowerMax) { ", puissance au maximum pendant le boost" } else { "" }))
            $Script:GpuLastKey = $null
            Update-GBGpuCap
        }
    } finally { $tm.Stop(); $tm.Dispose(); $d.Dispose() }
}

# "Tout annuler" : seulement ce que GameBoost a change (rien d'autre n'est touche)
function Undo-WinCfgAll {
    $bk = Get-WinCfgBackup; $n = 0; $fail = 0
    foreach ($k in @($bk.Keys)) {
        $b = $bk[$k]
        try {
            if ($k -like 'custom|*') {
                $id = $k.Substring(7)
                $t = @($Script:WinTweaks | Where-Object { $_.Id -eq $id }) | Select-Object -First 1
                if ($t -and $t.Type -eq 'choice') { if ([int]$b.Was -ge 0) { & $t.Set ([int]$b.Was) } }
                elseif ($t) { & $t.Set ([bool]$b.WasOn) }
            } elseif ($k -like 'dns|*') {
                Restore-GBDns $k.Substring(4) $b
            } elseif ($k -like 'power|*') {
                $p = $k.Split('|')
                powercfg /setacvalueindex $p[1] $p[2] $p[3] ([int]$b.AC) 2>$null | Out-Null
                powercfg /setdcvalueindex $p[1] $p[2] $p[3] ([int]$b.DC) 2>$null | Out-Null
                if ((Get-ActiveScheme) -eq $p[1]) { powercfg /setactive $p[1] 2>$null | Out-Null }
            } else {
                $i = $k.LastIndexOf('|')
                $p = $k.Substring(0, $i); $nm = $k.Substring($i + 1)
                if ($b.Existed) { Write-WinCfgReg $p $nm $b.Value $b.Type } else { Write-WinCfgReg $p $nm $null 'DWord' }
            }
            [void]$bk.Remove($k); $n++
        } catch { $fail++; Log ("Config Windows : annulation impossible pour " + $k + " : " + $_.Exception.Message) }
    }
    Save-WinCfgBackup
    try { Apply-MouseSettings } catch {}
    return @{ Ok = $n; Fail = $fail }
}

# Dossier de sauvegarde d'une action (barre des taches, fond d'ecran...)
function New-WinCfgSaveDir($name) {
    $d = Join-Path $Script:WinCfgSaveDir ($name + '_' + (Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'))
    New-Item -ItemType Directory -Path $d -Force | Out-Null
    return $d
}

# Commande "Prendre possession" au clic droit (fichiers et dossiers ; jamais les disques entiers)
$Script:TakeOwnKeys = @(
    @{ K = 'SOFTWARE\Classes\*\shell\runas'; Cmd = 'cmd.exe /c icacls "%1" /setowner *S-1-5-32-544 /c /q && icacls "%1" /grant *S-1-5-32-544:F /c /q' },
    @{ K = 'SOFTWARE\Classes\Directory\shell\runas'; Cmd = 'cmd.exe /c icacls "%1" /setowner *S-1-5-32-544 /t /c /q && icacls "%1" /grant *S-1-5-32-544:F /t /c /q' }
)
function Test-GBTakeOwn {
    foreach ($k in $Script:TakeOwnKeys) {
        $rk = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($k.K)
        if (-not $rk) { return $false }
        $mine = [string]$rk.GetValue('GameBoost'); $rk.Close()
        if ($mine -ne '1') { return $false }
    }
    return $true
}
function Set-GBTakeOwn([bool]$on) {
    foreach ($k in $Script:TakeOwnKeys) {
        $rk = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($k.K)
        $exists = [bool]$rk; $mine = $false
        if ($rk) { $mine = ([string]$rk.GetValue('GameBoost') -eq '1'); $rk.Close() }
        if ($on) {
            if ($exists -and -not $mine) { throw ("une autre commande existe deja a cet endroit (" + $k.K + ") : GameBoost ne la remplace pas") }
            $w = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($k.K)
            $w.SetValue('', 'Prendre possession'); $w.SetValue('HasLUAShield', ''); $w.SetValue('NoWorkingDirectory', ''); $w.SetValue('GameBoost', '1'); $w.Close()
            $c = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($k.K + '\command')
            $c.SetValue('', $k.Cmd); $c.SetValue('IsolatedCommand', $k.Cmd); $c.Close()
        } elseif ($mine) {
            [Microsoft.Win32.Registry]::LocalMachine.DeleteSubKeyTree($k.K, $false)
        }
    }
}

# Fond d'ecran Windows assorti au theme (clair / sombre)
function Set-GBWallpaperForTheme {
    $dark = $false
    try { $dark = ([int](Get-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize' -Name SystemUsesLightTheme -ErrorAction Stop).SystemUsesLightTheme -eq 0) } catch {}
    $w = $env:windir
    $cands = @()
    if ($Script:IsWin11) {
        if ($dark) { $cands += (Join-Path $w 'Web\Wallpaper\Windows\img19.jpg') }
        $cands += (Join-Path $w 'Web\Wallpaper\Windows\img0.jpg')
    } else {
        $cands += (Join-Path $w 'Web\4K\Wallpaper\Windows\img0_3840x2160.jpg'); $cands += (Join-Path $w 'Web\Wallpaper\Windows\img0.jpg')
    }
    $file = @($cands | Where-Object { Test-Path -LiteralPath $_ }) | Select-Object -First 1
    if (-not $file) { throw "aucun fond d'ecran Windows trouve sur ce PC" }
    $bk = Get-WinCfgBackup; $key = 'HKCU:\Control Panel\Desktop|Wallpaper'
    if (-not $bk.ContainsKey($key)) { $bk[$key] = Read-RegValue 'HKCU:\Control Panel\Desktop' 'Wallpaper' 'String'; Save-WinCfgBackup }
    if (-not ('GBWall' -as [type])) {
        Add-Type -TypeDefinition 'using System.Runtime.InteropServices; public static class GBWall { [DllImport("user32.dll", CharSet = CharSet.Unicode)] public static extern int SystemParametersInfo(int a, int b, string c, int d); }'
    }
    if ([GBWall]::SystemParametersInfo(20, 0, $file, 3) -eq 0) { throw "Windows a refuse le changement de fond d'ecran" }
    $mode = "clair"; if ($dark) { $mode = "sombre" }
    return ("Fond d'ecran Windows " + $mode + " applique : " + $file)
}

# --- Programmes lances au demarrage : meme mecanisme que le Gestionnaire des taches (rien n'est supprime, reactivable) ---
$Script:StartupSources = @(
    @{ Hive = 'HKCU'; Run = 'Software\Microsoft\Windows\CurrentVersion\Run'; Appr = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'; L = 'Registre (ton compte)' },
    @{ Hive = 'HKLM'; Run = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Run'; Appr = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run'; L = 'Registre (tout le PC)' },
    @{ Hive = 'HKLM'; Run = 'SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run'; Appr = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32'; L = 'Registre (tout le PC, 32 bits)' }
)
function Get-GBRegRoot($hive) { if ($hive -eq 'HKCU') { return [Microsoft.Win32.Registry]::CurrentUser } else { return [Microsoft.Win32.Registry]::LocalMachine } }
# Active si la valeur "StartupApproved" est absente ou si son 1er octet est pair (02 / 06) ; 03 / 07 = desactive
function Test-GBStartupEnabled($hive, $appr, $name) {
    try {
        $k = (Get-GBRegRoot $hive).OpenSubKey($appr); if (-not $k) { return $true }
        try { $v = $k.GetValue($name) } finally { $k.Close() }
        if ($v -is [byte[]] -and $v.Length -gt 0) { return (($v[0] -band 1) -eq 0) }
    } catch {}
    return $true
}
function Set-GBStartupEnabled($hive, $appr, $name, [bool]$enabled) {
    $k = (Get-GBRegRoot $hive).CreateSubKey($appr)
    try {
        $b = New-Object byte[] 12
        if ($enabled) { $b[0] = 2 } else { $b[0] = 3; [Array]::Copy([BitConverter]::GetBytes([DateTime]::Now.ToFileTime()), 0, $b, 4, 8) }
        $k.SetValue($name, $b, [Microsoft.Win32.RegistryValueKind]::Binary)
    } finally { $k.Close() }
}
function Get-GBStartupItems {
    $list = New-Object System.Collections.ArrayList
    foreach ($s in $Script:StartupSources) {
        try {
            $k = (Get-GBRegRoot $s.Hive).OpenSubKey($s.Run); if (-not $k) { continue }
            try {
                foreach ($n in $k.GetValueNames()) {
                    if (-not $n) { continue }
                    $cmd = [string]$k.GetValue($n, '', [Microsoft.Win32.RegistryValueOptions]::DoNotExpandEnvironmentNames)
                    [void]$list.Add([pscustomobject]@{ Name = $n; Cmd = $cmd; Where = $s.L; Hive = $s.Hive; Appr = $s.Appr; Enabled = (Test-GBStartupEnabled $s.Hive $s.Appr $n)
                                                       File = [Environment]::ExpandEnvironmentVariables([string]((Split-GBCommand $cmd)[0])) })
                }
            } finally { $k.Close() }
        } catch {}
    }
    $sh = $null; try { $sh = New-Object -ComObject WScript.Shell } catch {}
    foreach ($f in @(@{ P = [Environment]::GetFolderPath('Startup'); Hive = 'HKCU'; L = 'Dossier Demarrage (ton compte)' }, @{ P = [Environment]::GetFolderPath('CommonStartup'); Hive = 'HKLM'; L = 'Dossier Demarrage (tout le PC)' })) {
        if (-not $f.P -or -not (Test-Path -LiteralPath $f.P)) { continue }
        foreach ($fi in @(Get-ChildItem -LiteralPath $f.P -File -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne 'desktop.ini' })) {
            $target = $fi.FullName
            if ($fi.Extension -eq '.lnk' -and $sh) { try { $t = $sh.CreateShortcut($fi.FullName).TargetPath; if ($t) { $target = $t } } catch {} }
            $appr = 'Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder'; if ($f.Hive -eq 'HKLM') { $appr = 'SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\StartupFolder' }
            [void]$list.Add([pscustomobject]@{ Name = $fi.Name; Cmd = $target; Where = $f.L; Hive = $f.Hive; Appr = $appr; Enabled = (Test-GBStartupEnabled $f.Hive $appr $fi.Name); File = $target })
        }
    }
    return @($list | Sort-Object @{ Expression = { -not $_.Enabled } }, Name)
}

# --- Nettoyage : emplacements surs (caches et fichiers temporaires que Windows et les jeux recreent tout seuls) ---
$Script:CleanTargets = @(
    @{ Id = 'usertemp'; L = 'Fichiers temporaires (ton compte)'; P = @('%TEMP%'); Reco = $true; N = "Laisses par les installations et les programmes." },
    @{ Id = 'wintemp'; L = 'Fichiers temporaires de Windows'; P = @('%windir%\Temp'); Reco = $true; N = "Laisses par Windows et les installations." },
    @{ Id = 'wucache'; L = 'Telechargements de Windows Update'; P = @('%windir%\SoftwareDistribution\Download'); Reco = $true; Svc = @('wuauserv', 'bits'); N = "Mises a jour deja installees : Windows les retelecharge si besoin." },
    @{ Id = 'docache'; L = "Cache d'optimisation de la distribution"; P = @('%windir%\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache'); Reco = $true; DO = $true; N = "Morceaux de mises a jour partages entre PC." },
    @{ Id = 'wer'; L = "Rapports d'erreurs et vidages memoire"; P = @('%ProgramData%\Microsoft\Windows\WER\ReportArchive', '%ProgramData%\Microsoft\Windows\WER\ReportQueue', '%LOCALAPPDATA%\CrashDumps', '%windir%\Minidump', '%windir%\MEMORY.DMP'); Reco = $true; N = "Utiles seulement pour analyser un plantage passe." },
    @{ Id = 'thumbs'; L = 'Cache des miniatures'; P = @('%LOCALAPPDATA%\Microsoft\Windows\Explorer'); Filter = 'thumbcache_*.db'; Reco = $false; N = "Recree automatiquement (dossiers d'images un peu plus lents a s'afficher la 1re fois)." },
    @{ Id = 'dxcache'; L = 'Cache de shaders DirectX'; P = @('%LOCALAPPDATA%\D3DSCache'); Reco = $false; N = "A vider si un jeu saccade ou plante apres une mise a jour de pilote. Les jeux recompilent les shaders." },
    @{ Id = 'nvcache'; L = 'Cache de shaders NVIDIA'; P = @('%LOCALAPPDATA%\NVIDIA\DXCache', '%LOCALAPPDATA%\NVIDIA\GLCache', '%ProgramData%\NVIDIA Corporation\NV_Cache'); Reco = $false; N = "A vider apres une mise a jour du pilote NVIDIA si des saccades apparaissent." },
    @{ Id = 'amdcache'; L = 'Cache de shaders AMD'; P = @('%LOCALAPPDATA%\AMD\DxCache', '%LOCALAPPDATA%\AMD\DxcCache', '%LOCALAPPDATA%\AMD\VkCache', '%LOCALAPPDATA%\AMD\GLCache'); Reco = $false; N = "A vider apres une mise a jour du pilote AMD si des saccades apparaissent." },
    @{ Id = 'intelcache'; L = 'Cache de shaders Intel'; P = @('%LOCALAPPDATA%\Intel\ShaderCache'); Reco = $false; N = "A vider apres une mise a jour du pilote Intel." },
    @{ Id = 'recycle'; L = 'Corbeille'; Recycle = $true; Reco = $false; N = "Les fichiers supprimes ne pourront plus etre recuperes." }
)
# Taille et nettoyage en arriere-plan (dossiers parfois enormes)
$Script:CleanScript = {
    param($sync, $job)
    function Get-Paths($t) {
        $out = @()
        foreach ($p in @($t.P)) {
            $x = [Environment]::ExpandEnvironmentVariables([string]$p)
            # Securite : jamais une racine de disque, le dossier Windows ou un chemin non developpe
            if (-not $x -or $x -match '%' -or $x.Length -lt 8 -or $x.TrimEnd('\') -eq $env:windir -or $x.TrimEnd('\') -match '^[A-Za-z]:$') { continue }
            if (Test-Path -LiteralPath $x -ErrorAction SilentlyContinue) { $out += $x }
        }
        return $out
    }
    function Get-Size($t) {
        $sum = [int64]0
        if ($t.Recycle) {
            $sid = [Security.Principal.WindowsIdentity]::GetCurrent().User.Value
            # Disques internes prets seulement (un lecteur reseau deconnecte bloquerait longtemps)
            foreach ($d in @([IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady })) {
                $rb = Join-Path $d.RootDirectory.FullName ('$Recycle.Bin\' + $sid)
                if (Test-Path -LiteralPath $rb) { foreach ($f in @(Get-ChildItem -LiteralPath $rb -Recurse -Force -File -ErrorAction SilentlyContinue)) { $sum += $f.Length } }
            }
            return $sum
        }
        foreach ($x in (Get-Paths $t)) {
            if (Test-Path -LiteralPath $x -PathType Leaf) { $sum += (Get-Item -LiteralPath $x -Force).Length; continue }
            $files = @(); if ($t.Filter) { $files = @(Get-ChildItem -LiteralPath $x -Filter $t.Filter -Force -File -ErrorAction SilentlyContinue) } else { $files = @(Get-ChildItem -LiteralPath $x -Recurse -Force -File -ErrorAction SilentlyContinue) }
            foreach ($f in $files) { $sum += $f.Length }
        }
        return $sum
    }
    try {
        if ($job.Op -eq 'scan') {
            $sizes = @{}
            foreach ($t in $job.Targets) { $sync.Status = "Analyse : " + $t.L + "..."; try { $sizes[$t.Id] = Get-Size $t } catch { $sizes[$t.Id] = [int64]0 } }
            $sync.Sizes = $sizes
        } else {
            foreach ($t in $job.Targets) {
                $sync.Status = "Nettoyage : " + $t.L + "..."
                $before = [int64]0; try { $before = Get-Size $t } catch {}
                $err = ""
                try {
                    if ($t.Recycle) { Clear-RecycleBin -Force -ErrorAction SilentlyContinue }
                    elseif ($t.DO -and (Get-Command Delete-DeliveryOptimizationCache -ErrorAction SilentlyContinue)) { Delete-DeliveryOptimizationCache -Force -ErrorAction SilentlyContinue | Out-Null }
                    else {
                        $stopped = @()
                        foreach ($s in @($t.Svc)) { if (-not $s) { continue }; $sv = Get-Service -Name $s -ErrorAction SilentlyContinue; if ($sv -and $sv.Status -eq 'Running') { Stop-Service -Name $s -Force -ErrorAction SilentlyContinue; $stopped += $s } }
                        try {
                            foreach ($x in (Get-Paths $t)) {
                                if (Test-Path -LiteralPath $x -PathType Leaf) { Remove-Item -LiteralPath $x -Force -ErrorAction SilentlyContinue; continue }
                                $items = @(); if ($t.Filter) { $items = @(Get-ChildItem -LiteralPath $x -Filter $t.Filter -Force -ErrorAction SilentlyContinue) } else { $items = @(Get-ChildItem -LiteralPath $x -Force -ErrorAction SilentlyContinue) }
                                foreach ($i in $items) { Remove-Item -LiteralPath $i.FullName -Recurse -Force -ErrorAction SilentlyContinue }
                            }
                        } finally { foreach ($s in $stopped) { Start-Service -Name $s -ErrorAction SilentlyContinue } }
                    }
                } catch { $err = $_.Exception.Message }
                $after = [int64]0; try { $after = Get-Size $t } catch {}
                [void]$sync.Lines.Add(@{ Id = $t.Id; L = $t.L; Freed = [math]::Max([int64]0, $before - $after); Left = $after; Err = $err })
            }
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}

# --- DNS des cartes reseau actives (la valeur d'origine est gardee pour "Tout annuler") ---
$Script:DnsProviders = @(
    @{ L = 'Automatique (box / fournisseur)'; S = @() },
    @{ L = 'Cloudflare (1.1.1.1) - le plus rapide'; S = @('1.1.1.1', '1.0.0.1') },
    @{ L = 'Google (8.8.8.8)'; S = @('8.8.8.8', '8.8.4.4') },
    @{ L = 'Quad9 (9.9.9.9) - bloque les sites malveillants'; S = @('9.9.9.9', '149.112.112.112') },
    @{ L = 'Cloudflare Familles - bloque malwares et adultes'; S = @('1.1.1.3', '1.0.0.3') }
)
# Cartes reseau connectees, lues par .NET (le module NetAdapter de Windows coute ~70 Mo de memoire, garde jusqu'a la fermeture)
function Get-GBNetAdapters {
    $virt = 'Loopback|VPN|TAP-|WireGuard|Hyper-V|vEthernet|VMware|VirtualBox|Virtual Adapter|Npcap|Bluetooth|Teredo|isatap|Pseudo|Kernel Debug|Wintun|ZeroTier|Tailscale|OpenVPN|Fortinet|Cisco AnyConnect'
    $all = @(); try { $all = @([System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) } catch {}
    $mk = {
        param($ni)
        $idx = $null; try { $idx = $ni.GetIPProperties().GetIPv4Properties().Index } catch {}
        $wifi = ($ni.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Wireless80211)
        [pscustomobject]@{ Name = $ni.Name; InterfaceGuid = $ni.Id; ifIndex = $idx; InterfaceDescription = $ni.Description; Status = 'Up'; Wifi = $wifi; Speed = [int64]$ni.Speed }
    }
    $up = @($all | Where-Object { $_.OperationalStatus -eq 'Up' -and $_.NetworkInterfaceType -ne 'Loopback' -and $_.NetworkInterfaceType -ne 'Tunnel' })
    $a = @($up | Where-Object { $_.Description -notmatch $virt } | ForEach-Object { & $mk $_ } | Where-Object { $null -ne $_.ifIndex })
    # Machines virtuelles : leur carte est "virtuelle" mais c'est la seule qui sort sur internet
    if ($a.Count -eq 0) { $a = @($up | Where-Object { $_.Description -notmatch 'Loopback|Teredo|isatap|Kernel Debug' } | ForEach-Object { & $mk $_ } | Where-Object { $null -ne $_.ifIndex }) }
    return $a
}
# Carte reseau qui sort sur internet (passerelle par defaut), ou $null
function Get-GBInternetAdapter {
    $best = $null
    try {
        foreach ($ni in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
            if ($ni.OperationalStatus -ne 'Up' -or $ni.NetworkInterfaceType -eq 'Loopback') { continue }
            $gw = @($ni.GetIPProperties().GatewayAddresses | Where-Object { $_.Address.AddressFamily -eq 'InterNetwork' -and [string]$_.Address -ne '0.0.0.0' })
            if ($gw.Count -eq 0) { continue }
            $o = [pscustomobject]@{ Name = $ni.Name; InterfaceDescription = $ni.Description; Wifi = ($ni.NetworkInterfaceType -eq 'Wireless80211'); Speed = [int64]$ni.Speed }
            if (-not $best -or ($best.Wifi -and -not $o.Wifi)) { $best = $o }   # (filaire prefere s'il y en a deux)
        }
    } catch {}
    return $best
}
function Format-GBLinkSpeed([int64]$bps) {
    if ($bps -le 0) { return "vitesse inconnue" }
    if ($bps -ge 1000000000) { return ("{0:N1}" -f ($bps / 1e9)) + " Gbit/s" }
    return ("" + [int]($bps / 1e6)) + " Mbit/s"
}
# Sante du PC : disques, espace libre, memoire, batterie, Windows (requetes lentes : lues en arriere-plan a l'ouverture de Config Windows)
$Script:HealthDataScript = {
    param([bool]$isLaptop)
    $r = @{ Disks = @(); Vols = @(); Mods = @(); IsVm = $false; Bat = $null; Design = $null; Full = $null; Cyc = $null; Os = $null }
    # Disques lus directement par CIM (le module Storage de Windows coute ~110 Mo de memoire) ; valeurs traduites comme Get-PhysicalDisk
    $mt = @{ 0 = 'Unspecified'; 3 = 'HDD'; 4 = 'SSD'; 5 = 'SCM' }
    $bt = @{ 1 = 'SCSI'; 3 = 'ATA'; 6 = 'Fibre Channel'; 7 = 'USB'; 8 = 'RAID'; 9 = 'iSCSI'; 10 = 'SAS'; 11 = 'SATA'; 12 = 'SD'; 13 = 'MMC'; 15 = 'File Backed Virtual'; 16 = 'Storage Spaces'; 17 = 'NVMe' }
    $hs = @{ 0 = 'Healthy'; 1 = 'Warning'; 2 = 'Unhealthy'; 5 = 'Unknown' }
    $pds = @(); try { $pds = @(Get-CimInstance -Namespace 'root/Microsoft/Windows/Storage' -ClassName MSFT_PhysicalDisk -ErrorAction Stop) } catch {}
    $r.Disks = @(foreach ($pd in $pds) {
        $rc = $null; try { $rc = Get-CimAssociatedInstance -InputObject $pd -ResultClassName MSFT_StorageReliabilityCounter -ErrorAction Stop | Select-Object -First 1 } catch {}
        $m = $mt[[int]$pd.MediaType]; if (-not $m) { $m = 'Unspecified' }
        $b = $bt[[int]$pd.BusType]; if (-not $b) { $b = 'Unknown' }
        $h = $hs[[int]$pd.HealthStatus]; if (-not $h) { $h = 'Unknown' }
        @{ Pd = [pscustomobject]@{ FriendlyName = [string]$pd.FriendlyName; MediaType = $m; BusType = $b; HealthStatus = $h; Size = [double]$pd.Size }; Rc = $rc }
    })
    try {
        $r.Vols = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop | Where-Object { $_.Size -gt 0 } | Sort-Object DeviceID |
            ForEach-Object { [pscustomobject]@{ DriveLetter = ([string]$_.DeviceID).TrimEnd(':'); SizeRemaining = [double]$_.FreeSpace; Size = [double]$_.Size } })
    } catch {}
    try { $r.Mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop) } catch {}
    # Machine virtuelle : la memoire et ses vitesses sont simulees, pas de conseil
    try { $r.IsVm = ([string](Get-CimInstance Win32_ComputerSystem -ErrorAction Stop).Model -match 'Virtual|VMware|VirtualBox|KVM|QEMU|HVM domU|Parallels') } catch {}
    # Portables seulement (sur un PC fixe, un onduleur USB apparait aussi comme "batterie")
    if ($isLaptop) {
        try { $r.Bat = Get-CimInstance Win32_Battery -ErrorAction Stop | Select-Object -First 1 } catch {}
        if ($r.Bat) {
            try { $r.Design = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryStaticData -ErrorAction Stop)[0].DesignedCapacity) } catch {}
            try { $r.Full = [double](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryFullChargedCapacity -ErrorAction Stop)[0].FullChargedCapacity) } catch {}
            try { $r.Cyc = [int](@(Get-CimInstance -Namespace root\wmi -ClassName BatteryCycleCount -ErrorAction Stop)[0].CycleCount) } catch {}
        }
    }
    try { $r.Os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch {}
    return $r
}
# Fil d'arriere-plan lance a l'ouverture de Config Windows : cartes reseau, puis sante du PC
$Script:CfgPrefetchScript = {
    param($sync, $isLaptop)
    try { $net = [scriptblock]::Create($sync.NetSrc); $sync.Adapters = @(& $net) } catch {}
    $sync.NetDone = $true
    try { $h = [scriptblock]::Create($sync.HealthSrc); $sync.Health = & $h $isLaptop } catch {}
    $sync.HealthDone = $true
    $sync.Done = $true
}
function Get-GBDnsState($guid) {
    $r = Read-GBRegFast ('HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces\' + $guid) 'NameServer'
    $s = @(([string]$r.Value) -split '[ ,;]+' | Where-Object { $_ })
    return @{ Auto = ($s.Count -eq 0); Servers = $s }
}
function Set-GBDns($adapter, $servers) {
    $guid = [string]$adapter.InterfaceGuid
    $bk = Get-WinCfgBackup; $key = 'dns|' + $guid
    if (-not $bk.ContainsKey($key)) { $st = Get-GBDnsState $guid; $bk[$key] = @{ Auto = $st.Auto; Servers = ($st.Servers -join ',') }; Save-WinCfgBackup }
    Write-GBDnsServers $adapter.ifIndex @($servers)
}
# Serveurs DNS d'une carte (par son numero) avec netsh, outil integre a Windows (le module DnsClient coute de la memoire)
function Write-GBDnsServers($ifIndex, $servers) {
    if ($null -eq $ifIndex) { throw "carte reseau sans numero IPv4" }
    $servers = @($servers | Where-Object { $_ })
    if ($servers.Count -eq 0) { $o = & netsh.exe interface ipv4 set dnsservers ("name=" + $ifIndex) source=dhcp 2>&1 }
    else {
        $o = & netsh.exe interface ipv4 set dnsservers ("name=" + $ifIndex) static $servers[0] primary validate=no 2>&1
        for ($n = 1; $n -lt $servers.Count -and $LASTEXITCODE -eq 0; $n++) { $o = & netsh.exe interface ipv4 add dnsservers ("name=" + $ifIndex) $servers[$n] ("index=" + ($n + 1)) validate=no 2>&1 }
    }
    if ($LASTEXITCODE -ne 0) { throw ("Windows a refuse : " + (($o | ForEach-Object { [string]$_ }) -join ' ').Trim()) }
    & ipconfig.exe /flushdns 2>&1 | Out-Null
}
function Restore-GBDns($guid, $b) {
    $a = @(Get-GBNetAdapters | Where-Object { [string]$_.InterfaceGuid -eq $guid }) | Select-Object -First 1
    if (-not $a) {
        # Carte deconnectee en ce moment : on la retrouve quand meme par .NET
        try { foreach ($ni in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) { if ($ni.Id -eq $guid) { $a = [pscustomobject]@{ ifIndex = $ni.GetIPProperties().GetIPv4Properties().Index } } } } catch {}
    }
    if (-not $a) { return }
    if ($b.Auto -or -not $b.Servers) { Write-GBDnsServers $a.ifIndex @() }
    else { Write-GBDnsServers $a.ifIndex @(([string]$b.Servers).Split(',')) }
}

# --- Reglages DirectX de Windows 11 (optimisations des jeux en fenetre, VRR) : une seule chaine "Cle=1;Cle=0;" ---
$Script:DxKey = 'HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'
function Get-GBDxSetting($name) { $r = Read-GBRegFast $Script:DxKey 'DirectXUserGlobalSettings'; return ([string]$r.Value -match ('(^|;)' + $name + '=1(;|$)')) }
function Set-GBDxSetting($name, [bool]$on) {
    $cur = [string](Read-GBRegFast $Script:DxKey 'DirectXUserGlobalSettings').Value
    $parts = @($cur.Split(';') | Where-Object { $_ -and $_ -notmatch ('^' + $name + '=') })
    if ($on) { $parts += ($name + '=1') }
    if ($parts.Count -eq 0) { Write-WinCfgReg $Script:DxKey 'DirectXUserGlobalSettings' $null 'String' }
    else { Write-WinCfgReg $Script:DxKey 'DirectXUserGlobalSettings' (($parts -join ';') + ';') 'String' }
}

# --- Mises a jour des logiciels (WinGet) : lecture du tableau "winget upgrade" (colonnes reperees sur l'en-tete) ---
$Script:WingetUpgradeScanScript = {
    param($sync, $wg)
    try {
        $tmp = Join-Path $env:TEMP ('gb_wgup_' + [guid]::NewGuid().ToString('N') + '.txt')
        $a = @('upgrade', '--include-unknown', '--accept-source-agreements', '--disable-interactivity')
        if ($sync.Modern -eq $false) { $a = @($a | Where-Object { $_ -ne '--disable-interactivity' -and $_ -ne '--include-unknown' }) }
        $p = Start-Process -FilePath $wg -ArgumentList $a -Wait -PassThru -WindowStyle Hidden -RedirectStandardOutput $tmp
        $raw = ''; if (Test-Path -LiteralPath $tmp) { $raw = [IO.File]::ReadAllText($tmp, [Text.Encoding]::UTF8); Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
        $lines = @($raw -split "`r?`n" | ForEach-Object { ($_ -split "`r")[-1] })
        $items = New-Object System.Collections.ArrayList
        $starts = $null
        for ($i = 0; $i -lt $lines.Count; $i++) {
            $l = $lines[$i]
            if ($null -eq $starts) {
                # En-tete = ligne suivie d'une ligne de tirets
                if ($i + 1 -lt $lines.Count -and $lines[$i + 1] -match '^-{10,}') { $starts = @([regex]::Matches($l, '\S+') | ForEach-Object { $_.Index }); $i++ }
                continue
            }
            if (-not $l.Trim() -or $l.Length -lt $starts[-1]) { $starts = $null; continue }   # fin du tableau
            $col = @(); for ($c = 0; $c -lt $starts.Count; $c++) { $a = $starts[$c]; $b = $(if ($c + 1 -lt $starts.Count) { $starts[$c + 1] } else { $l.Length }); if ($a -lt $l.Length) { $col += $l.Substring($a, [math]::Min($b, $l.Length) - $a).Trim() } else { $col += '' } }
            if ($col.Count -lt 4 -or -not $col[1] -or -not $col[3]) { continue }
            [void]$items.Add(@{ Name = $col[0]; Id = $col[1]; Ver = $col[2]; New = $col[3]; Src = $(if ($col.Count -gt 4) { $col[4] } else { '' }); Cut = ($col[1] -match [char]0x2026) })
        }
        $sync.Items = $items.ToArray()
        if ($p.ExitCode -ne 0 -and $items.Count -eq 0 -and -not ($raw -match '(?i)aucun|no (installed package|available upgrade)')) { $sync.Error = "WinGet a renvoye le code " + $p.ExitCode }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}
$Script:WingetUpgradeRunScript = {
    param($sync, $job)
    try {
        foreach ($id in @($job.Ids)) {
            $sync.Current = $id
            $a = @('upgrade', '--id', $id, '-e', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity')
            if ($id -eq '*') { $a = @('upgrade', '--all', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') }
            if ($job.Modern -eq $false) { $a = @($a | Where-Object { $_ -ne '--disable-interactivity' -and $_ -ne '--include-unknown' }) }
            $code = -1; $err = ""
            try { $p = Start-Process -FilePath $job.Wg -ArgumentList $a -Wait -PassThru -WindowStyle Hidden; $code = $p.ExitCode } catch { $err = $_.Exception.Message }
            [void]$sync.Lines.Add(@{ Id = $id; Ok = ($code -eq 0 -or $code -eq -1978335189); Code = $code; Err = $err })
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}

# --- Ecrans : frequence actuelle et maximale a la resolution actuelle (et passage au maximum) ---
function Initialize-GBDisplay {
    if ('GBDisplay' -as [type]) { return $true }
    try {
        Add-Type -TypeDefinition @'
using System; using System.Collections.Generic; using System.Runtime.InteropServices;
public static class GBDisplay {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct DEVMODE {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName; public short dmSpecVersion, dmDriverVersion, dmSize, dmDriverExtra; public int dmFields;
        public int dmPositionX, dmPositionY, dmDisplayOrientation, dmDisplayFixedOutput; public short dmColor, dmDuplex, dmYResolution, dmTTOption, dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName; public short dmLogPixels; public int dmBitsPerPel, dmPelsWidth, dmPelsHeight, dmDisplayFlags, dmDisplayFrequency,
        dmICMMethod, dmICMIntent, dmMediaType, dmDitherType, dmReserved1, dmReserved2, dmPanningWidth, dmPanningHeight; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct DISPLAY_DEVICE { public int cb;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string DeviceName; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceString;
        public int StateFlags; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceID; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceKey; }
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool EnumDisplayDevices(string dev, int i, ref DISPLAY_DEVICE dd, int flags);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool EnumDisplaySettings(string dev, int mode, ref DEVMODE dm);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int ChangeDisplaySettingsEx(string dev, ref DEVMODE dm, IntPtr hwnd, int flags, IntPtr p);
    // Renvoie "nom|carte|largeur|hauteur|Hz actuel|Hz max" pour chaque ecran actif
    public static string[] List() {
        List<string> r = new List<string>();
        for (int i = 0; ; i++) {
            DISPLAY_DEVICE d = new DISPLAY_DEVICE(); d.cb = Marshal.SizeOf(d);
            if (!EnumDisplayDevices(null, i, ref d, 0)) break;
            if ((d.StateFlags & 1) == 0) continue;
            DEVMODE cur = new DEVMODE(); cur.dmSize = (short)Marshal.SizeOf(cur);
            if (!EnumDisplaySettings(d.DeviceName, -1, ref cur)) continue;
            int max = cur.dmDisplayFrequency;
            for (int m = 0; ; m++) {
                DEVMODE x = new DEVMODE(); x.dmSize = (short)Marshal.SizeOf(x);
                if (!EnumDisplaySettings(d.DeviceName, m, ref x)) break;
                if (x.dmPelsWidth == cur.dmPelsWidth && x.dmPelsHeight == cur.dmPelsHeight && x.dmBitsPerPel == cur.dmBitsPerPel && x.dmDisplayFrequency > max) max = x.dmDisplayFrequency;
            }
            r.Add(d.DeviceName + "|" + d.DeviceString + "|" + cur.dmPelsWidth + "|" + cur.dmPelsHeight + "|" + cur.dmDisplayFrequency + "|" + max);
        }
        return r.ToArray();
    }
    // Passe l'ecran a la frequence donnee (meme resolution), enregistre pour les prochains demarrages
    public static int SetHz(string dev, int hz) {
        DEVMODE cur = new DEVMODE(); cur.dmSize = (short)Marshal.SizeOf(cur);
        if (!EnumDisplaySettings(dev, -1, ref cur)) return -99;
        cur.dmDisplayFrequency = hz; cur.dmFields = 0x400000;
        return ChangeDisplaySettingsEx(dev, ref cur, IntPtr.Zero, 1, IntPtr.Zero);
    }
}
'@ -ErrorAction Stop
        return $true
    } catch { return $false }
}

# --- Nettoyage automatique chaque semaine (tache visible \GameBoost\NettoyageHebdo, elements conseilles seulement) ---
$Script:WeeklyCleanTask = 'NettoyageHebdo'
# Une tache planifiee existe ? (service des taches en direct : ~1 ms, contre ~0,5 s pour Get-ScheduledTask)
function Test-GBTask([string]$path, [string]$name) {
    $p = $path.TrimEnd('\'); if (-not $p) { $p = '\' }
    try { if (-not $Script:TaskSvc) { $Script:TaskSvc = New-Object -ComObject Schedule.Service; $Script:TaskSvc.Connect() } }
    catch { try { return [bool](Get-ScheduledTask -TaskPath $path -TaskName $name -ErrorAction Stop) } catch { return $false } }
    try { return [bool]$Script:TaskSvc.GetFolder($p).GetTask($name) } catch { return $false }
}
function Get-GBWeeklyCleanTask { return (Test-GBTask '\GameBoost\' $Script:WeeklyCleanTask) }
function Set-GBWeeklyClean([bool]$on) {
    if (-not $on) {
        try { Unregister-ScheduledTask -TaskPath '\GameBoost\' -TaskName $Script:WeeklyCleanTask -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        $d0 = Join-Path $env:ProgramData 'GameBoost\Scripts'; Remove-Item -LiteralPath (Join-Path $d0 'NettoyageHebdo.ps1') -Force -ErrorAction SilentlyContinue
        return
    }
    $dir = Get-GBScriptsDir
    if (-not $dir) { throw "dossier protege C:\ProgramData\GameBoost\Scripts impossible a creer (droits administrateur ?)" }
    $ps1 = Join-Path $dir 'NettoyageHebdo.ps1'
    $targets = @($Script:CleanTargets | Where-Object { $_.Reco -and -not $_.DO -and -not $_.Recycle })
    $body = New-Object System.Collections.ArrayList
    [void]$body.Add("# Script cree par GameBoost (Config Windows > Nettoyage). Lance chaque semaine par la tache \GameBoost\NettoyageHebdo.")
    [void]$body.Add("# Pour l'arreter : GameBoost > Config Windows > Nettoyage > decocher 'Nettoyage automatique chaque semaine'.")
    [void]$body.Add('$log = Join-Path $PSScriptRoot ''NettoyageHebdo.log''')
    [void]$body.Add('function Clean($p, [string[]]$svc) {')
    [void]$body.Add('    $x = [Environment]::ExpandEnvironmentVariables($p); if (-not $x -or $x -match ''%'' -or $x.Length -lt 8 -or $x.TrimEnd(''\'') -eq $env:windir -or $x.TrimEnd(''\'') -match ''^[A-Za-z]:$'') { return }')
    [void]$body.Add('    if (-not (Test-Path -LiteralPath $x -ErrorAction SilentlyContinue)) { return }')
    [void]$body.Add('    $stopped = @(); foreach ($s in $svc) { if (-not $s) { continue }; $sv = Get-Service -Name $s -ErrorAction SilentlyContinue; if ($sv -and $sv.Status -eq ''Running'') { Stop-Service -Name $s -Force -ErrorAction SilentlyContinue; $stopped += $s } }')
    [void]$body.Add('    try { if (Test-Path -LiteralPath $x -PathType Leaf) { Remove-Item -LiteralPath $x -Force -ErrorAction SilentlyContinue } else { Get-ChildItem -LiteralPath $x -Force -ErrorAction SilentlyContinue | ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue } } }')
    [void]$body.Add('    finally { foreach ($s in $stopped) { Start-Service -Name $s -ErrorAction SilentlyContinue } }')
    [void]$body.Add('}')
    foreach ($t in $targets) { foreach ($p in @($t.P)) { [void]$body.Add("Clean '" + ([string]$p).Replace("'", "''") + "' @(" + ((@($t.Svc) | Where-Object { $_ } | ForEach-Object { "'" + $_ + "'" }) -join ',') + ")") } }
    [void]$body.Add('try { Add-Content -LiteralPath $log -Value ((Get-Date -Format ''yyyy-MM-dd HH:mm'') + '' nettoyage fait'') } catch {}')
    Set-Content -LiteralPath $ps1 -Value ($body -join "`r`n") -Encoding UTF8
    $user = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
    $act = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $ps1 + '"')
    $trg = New-ScheduledTaskTrigger -Weekly -DaysOfWeek Sunday -At '13:00'
    $pri = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -StartWhenAvailable -ExecutionTimeLimit (New-TimeSpan -Minutes 30)
    Register-ScheduledTask -TaskPath '\GameBoost\' -TaskName $Script:WeeklyCleanTask -Action $act -Trigger $trg -Principal $pri -Settings $set `
        -Description "GameBoost : nettoyage hebdomadaire (fichiers temporaires, telechargements de Windows Update, rapports d'erreurs)." -Force -ErrorAction Stop | Out-Null
}

# --- Taches planifiees de telemetrie de Windows (lecture rapide par le service du Planificateur) ---
$Script:TelemetryTasks = @(
    @('\Microsoft\Windows\Application Experience', 'Microsoft Compatibility Appraiser'), @('\Microsoft\Windows\Application Experience', 'ProgramDataUpdater'),
    @('\Microsoft\Windows\Application Experience', 'MareBackup'), @('\Microsoft\Windows\Customer Experience Improvement Program', 'Consolidator'),
    @('\Microsoft\Windows\Customer Experience Improvement Program', 'UsbCeip'), @('\Microsoft\Windows\DiskDiagnostic', 'Microsoft-Windows-DiskDiagnosticDataCollector'),
    @('\Microsoft\Windows\Feedback\Siuf', 'DmClient'), @('\Microsoft\Windows\Feedback\Siuf', 'DmClientOnScenarioDownload'),
    @('\Microsoft\Windows\Windows Error Reporting', 'QueueReporting')
)
function Get-GBTelemetryTasks {
    if (-not $Script:TaskSvc) { $Script:TaskSvc = New-Object -ComObject Schedule.Service; $Script:TaskSvc.Connect() }
    $out = @()
    foreach ($t in $Script:TelemetryTasks) { try { $out += $Script:TaskSvc.GetFolder($t[0]).GetTask($t[1]) } catch {} }
    return $out
}
function Test-GBTelemetryTasksOff { foreach ($tk in @(Get-GBTelemetryTasks)) { if ($tk.Enabled) { return $false } }; return $true }
function Set-GBTelemetryTasksOff([bool]$off) {
    $fail = @()
    foreach ($tk in @(Get-GBTelemetryTasks)) { try { $tk.Enabled = (-not $off) } catch { $fail += $tk.Name } }
    if ($fail.Count -gt 0) { throw ("Windows a refuse pour : " + ($fail -join ", ")) }
}

# Widgets de Windows 11 : strategie officielle, ou (si la protection UCPD de Windows la bloque) desinstallation du composant Widgets
$Script:WidgetsPkg = 'MicrosoftWindows.Client.WebExperience'
$Script:WidgetsPolicy = 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh'
function Test-GBWidgetsInstalled {
    try {
        $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey('Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\Repository\Packages')
        if (-not $k) { return $true }
        try { return (@($k.GetSubKeyNames() | Where-Object { $_ -like ($Script:WidgetsPkg + '_*') }).Count -gt 0) } finally { $k.Close() }
    } catch { return $true }
}
function Test-GBWidgetsOff {
    $r = Read-GBRegFast $Script:WidgetsPolicy 'AllowNewsAndInterests'
    if ($r.Existed -and [int]$r.Value -eq 0) { return $true }
    return (-not (Test-GBWidgetsInstalled))
}
function Set-GBWidgetsOff([bool]$on) {
    if ($on) {
        try { Write-WinCfgReg $Script:WidgetsPolicy 'AllowNewsAndInterests' 0 'DWord'; return } catch {}
        Log "Config Windows : strategie Widgets bloquee par Windows (protection UCPD) -> desinstallation du composant Widgets"
        $pk = @(); try { $pk = @(Get-AppxPackage -AllUsers -Name $Script:WidgetsPkg -ErrorAction Stop) } catch { $pk = @(Get-AppxPackage -Name $Script:WidgetsPkg -ErrorAction SilentlyContinue) }
        foreach ($p in $pk) {
            try { Remove-AppxPackage -Package $p.PackageFullName -AllUsers -ErrorAction Stop } catch { Remove-AppxPackage -Package $p.PackageFullName -ErrorAction Stop }
        }
        try { Get-AppxProvisionedPackage -Online -ErrorAction Stop | Where-Object { $_.DisplayName -eq $Script:WidgetsPkg } | ForEach-Object { Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName -ErrorAction SilentlyContinue | Out-Null } } catch {}
        Get-Process Widgets, WidgetService -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        if (Test-GBWidgetsInstalled) { throw "Windows a refuse de retirer les Widgets" }
        return
    }
    try { Remove-ItemProperty -LiteralPath $Script:WidgetsPolicy -Name 'AllowNewsAndInterests' -ErrorAction SilentlyContinue } catch {}
    if (Test-GBWidgetsInstalled) { return }
    # Composant retire : reinstallation depuis le Microsoft Store (WinGet, sinon page du Store)
    $wg = Find-GBWinget
    if ($wg) {
        try {
            $p = Start-Process -FilePath $wg -ArgumentList (Get-GBWingetArgs @('install', '--id', '9MSSGKG348SP', '-s', 'msstore', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') (Get-GBWingetModern $wg)) -PassThru -WindowStyle Hidden
            [void]$p.WaitForExit(180000)
        } catch {}
    }
    if (-not (Test-GBWidgetsInstalled)) {
        try { Start-Process 'ms-windows-store://pdp/?productid=9MSSGKG348SP' } catch {}
        throw "le Microsoft Store s'ouvre sur 'Windows Web Experience Pack' : clique 'Obtenir' pour remettre les Widgets"
    }
}

# Nettoyer la barre des taches : retire les icones epinglees (sauvegardees avant)
function Clear-GBTaskbarPins {
    $bdir = New-WinCfgSaveDir 'barre_des_taches'
    & reg.exe export 'HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' (Join-Path $bdir 'Taskband.reg') /y 2>$null | Out-Null
    $pin = Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar'
    if (Test-Path -LiteralPath $pin) {
        Copy-Item -LiteralPath $pin -Destination (Join-Path $bdir 'TaskBar') -Recurse -Force
        Get-ChildItem -LiteralPath $pin -Filter '*.lnk' -ErrorAction SilentlyContinue | Remove-Item -Force -ErrorAction SilentlyContinue
    }
    Remove-Item -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband' -Recurse -Force -ErrorAction SilentlyContinue
    Restart-GBExplorer
    return ("Icones epinglees retirees. Sauvegarde (double-clic sur Taskband.reg + copie du dossier TaskBar pour revenir) :`r`n" + $bdir)
}

