$wuUx = 'HKLM:\SOFTWARE\Microsoft\WindowsUpdate\UX\Settings'
$svcRoot = 'HKLM:\SYSTEM\CurrentControlSet\Services'
$uacKey = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System'
$mmKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile'

# Service Windows : Desactive / Manuel / Automatique (ecrit dans la cle du service, pris en compte au redemarrage)
function New-GBSvcTweak($svc, $name, $desc, $reco, $warn) {
    $k = $svcRoot + '\' + $svc
    return @{ Id = 'svc_' + $svc; Page = 'gaming'; Group = 'Services en arriere-plan'; Type = 'choice'; Name = $name; Desc = $desc; R = 'reboot'; Svc = $svc
              RecoIdx = $reco; Warns = $warn; Only = [scriptblock]::Create("Test-Path -LiteralPath '" + $k + "'")
              Opts = @(@{ L = 'Desactive'; V = @((New-WinVal $k 'Start' 4)) }, @{ L = 'Manuel (au besoin)'; V = @((New-WinVal $k 'Start' 3)) },
                       @{ L = 'Automatique'; V = @((New-WinVal $k 'Start' 2)) }) }
}

# Pause des mises a jour jusqu'en 2051 (valeurs lues par Parametres > Windows Update)
$wuPause = @('PauseFeatureUpdatesStartTime', 'PauseFeatureUpdatesEndTime', 'PauseQualityUpdatesStartTime', 'PauseQualityUpdatesEndTime', 'PauseUpdatesStartTime', 'PauseUpdatesExpiryTime')
function New-GBWuOpt($label, [bool]$defer, [bool]$pause, [bool]$off) {
    $v = @()
    if ($defer) { $v += (New-WinVal $wuPol 'DeferFeatureUpdates' 1); $v += (New-WinVal $wuPol 'DeferFeatureUpdatesPeriodInDays' 365) }
    else { $v += (New-WinVal $wuPol 'DeferFeatureUpdates' $null); $v += (New-WinVal $wuPol 'DeferFeatureUpdatesPeriodInDays' $null) }
    if ($off) { $v += (New-WinVal ($wuPol + '\AU') 'NoAutoUpdate' 1) } else { $v += (New-WinVal ($wuPol + '\AU') 'NoAutoUpdate' $null) }
    foreach ($n in $wuPause) {
        $val = $null
        if ($pause) { if ($n -like '*StartTime') { $val = '2024-01-01T00:00:00Z' } else { $val = '2051-12-31T00:00:00Z' } }
        $v += (New-WinVal $wuUx $n $val 'String')
    }
    if ($pause) { $v += (New-WinVal $wuUx 'FlightSettingsMaxPauseDays' 10023) } else { $v += (New-WinVal $wuUx 'FlightSettingsMaxPauseDays' $null) }
    return @{ L = $label; V = $v }
}

