    # ================= JEU ET PERFORMANCES =================
    @{ Id = 'gamemode'; Page = 'gaming'; Group = 'General'; Reco = $true; Name = "Mode Jeu de Windows active"
       Desc = "Windows donne la priorite au jeu au premier plan et evite d'installer des pilotes pendant que tu joues."
       Reg = @((New-WinReg 'HKCU:\Software\Microsoft\GameBar' 'AutoGameModeEnabled' 1 0), (New-WinReg 'HKCU:\Software\Microsoft\GameBar' 'AllowAutoGameMode' 1 0)) },
    @{ Id = 'hags'; Page = 'gaming'; Group = 'General'; Reco = $true; R = 'reboot'; Only = { $Script:WinBuild -ge 19041 }; Name = "Planification GPU acceleree par le materiel (HAGS)"
       Desc = "La carte graphique gere elle-meme sa memoire : un peu moins de latence, et obligatoire pour la generation d'images DLSS 3/4."
       Reg = @((New-WinReg 'HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers' 'HwSchMode' 2 1)) },
    @{ Id = 'dvr'; Page = 'gaming'; Group = 'General'; Reco = $true; Name = "Couper l'enregistrement Xbox en arriere-plan (toujours)"
       Desc = "La Game Bar n'enregistre plus en permanence tes parties (moins de charge GPU et disque). Les captures manuelles marchent toujours."
       Reg = @((New-WinReg 'HKCU:\System\GameConfigStore' 'GameDVR_Enabled' 0 1), (New-WinReg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR' 'AppCaptureEnabled' 0 1)) },
    @{ Id = 'fse'; Page = 'gaming'; Group = 'General'; Reco = $false; Name = "Desactiver les optimisations plein ecran (tous les jeux)"
       Desc = "Les jeux en plein ecran exclusif le restent vraiment : parfois moins de latence sur les anciens jeux DirectX 9/11. Sans effet sur les jeux recents."
       Reg = @((New-WinReg 'HKCU:\System\GameConfigStore' 'GameDVR_FSEBehaviorMode' 2 0), (New-WinReg 'HKCU:\System\GameConfigStore' 'GameDVR_HonorUserFSEBehaviorMode' 1 0),
               (New-WinReg 'HKCU:\System\GameConfigStore' 'GameDVR_DXGIHonorFSEWindowsCompatible' 1 0)) },
    @{ Id = 'gamesprio'; Page = 'gaming'; Group = 'General'; Reco = $false; R = 'reboot'; Name = "Priorite haute des jeux dans le planificateur multimedia"
       Desc = "Windows place les jeux dans la categorie de planification 'Haute' (processeur et acces disque) au lieu de 'Moyenne'."
       Reg = @((New-WinReg ($mmKey + '\Tasks\Games') 'Priority' 6 2), (New-WinReg ($mmKey + '\Tasks\Games') 'Scheduling Category' 'High' 'Medium' 'String'),
               (New-WinReg ($mmKey + '\Tasks\Games') 'SFIO Priority' 'High' 'Normal' 'String')) },
    @{ Id = 'sysresp'; Page = 'gaming'; Group = 'General'; Reco = $false; R = 'reboot'; Name = "Reserver moins de processeur aux taches de fond"
       Desc = "Windows garde 10 % du processeur pour les taches de fond pendant le multimedia au lieu de 20 %."
       Reg = @((New-WinReg $mmKey 'SystemResponsiveness' 10 20)) },
    @{ Id = 'mouse'; Page = 'gaming'; Group = 'Souris et clavier'; Reco = $true; Name = "Pas d'acceleration de la souris (toujours)"
       Desc = "Desactive 'Ameliorer la precision du pointeur' : le curseur bouge toujours de la meme distance, visee plus constante."
       Reg = @((New-WinReg 'HKCU:\Control Panel\Mouse' 'MouseSpeed' '0' '1' 'String'), (New-WinReg 'HKCU:\Control Panel\Mouse' 'MouseThreshold1' '0' '6' 'String'),
               (New-WinReg 'HKCU:\Control Panel\Mouse' 'MouseThreshold2' '0' '10' 'String'))
       After = { Apply-MouseSettings } },
    @{ Id = 'sticky'; Page = 'gaming'; Group = 'Souris et clavier'; Reco = $true; Name = "Desactiver le raccourci Touches remanentes (Maj x5)"
       Desc = "Appuyer 5 fois sur Maj (ou garder Verr. Num / Maj droite) ne fait plus sortir du jeu avec une fenetre d'accessibilite."
       Reg = @((New-WinReg 'HKCU:\Control Panel\Accessibility\StickyKeys' 'Flags' '506' '510' 'String'),
               (New-WinReg 'HKCU:\Control Panel\Accessibility\ToggleKeys' 'Flags' '58' '62' 'String'),
               (New-WinReg 'HKCU:\Control Panel\Accessibility\Keyboard Response' 'Flags' '122' '126' 'String')) },
    @{ Id = 'menudelay'; Page = 'gaming'; Group = 'Interface'; Reco = $false; Name = "Menus instantanes"
       Desc = "Les sous-menus s'ouvrent tout de suite au survol (au lieu d'attendre 0,4 s)."
       Reg = @((New-WinReg 'HKCU:\Control Panel\Desktop' 'MenuShowDelay' '0' '400' 'String')) },
    @{ Id = 'startupdelay'; Page = 'gaming'; Group = 'Interface'; Reco = $false; Name = "Pas de delai pour les applis lancees au demarrage"
       Desc = "Windows lance les applis de demarrage tout de suite au lieu d'attendre quelques secondes apres l'ouverture de session."
       Reg = @((New-WinReg ($expl + '\Serialize') 'StartupDelayInMSec' 0 $null)) },
    @{ Id = 'edgebg'; Page = 'gaming'; Group = 'Applis en arriere-plan'; Reco = $true; Name = "Microsoft Edge ne tourne plus en arriere-plan"
       Desc = "Edge ne se precharge plus au demarrage et se ferme vraiment quand tu le fermes (memoire et processeur liberes)."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'StartupBoostEnabled' 0 $null), (New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'BackgroundModeEnabled' 0 $null)) },
    @{ Id = 'bgapps'; Page = 'gaming'; Group = 'Applis en arriere-plan'; Reco = $false; Name = "Interdire aux applis du Store de tourner en arriere-plan"
       Desc = "Les applis du Microsoft Store ne tournent plus quand elles sont fermees."; Warn = "Les applis du Store (WhatsApp, Courrier, Teams...) ne t'enverront plus de notifications quand elles sont fermees."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppPrivacy' 'LetAppsRunInBackground' 2 $null)) },
    (New-GBSvcTweak 'DiagTrack' "Telemetrie (Experiences des utilisateurs connectes)" "Envoie les donnees de diagnostic a Microsoft. Le desactiver ne casse rien d'utile." 0 $null),
    (New-GBSvcTweak 'dmwappushservice' "Routage des messages WAP (telemetrie)" "Sert surtout a la telemetrie et aux PC d'entreprise geres a distance." 1 $null),
    (New-GBSvcTweak 'PcaSvc' "Assistant compatibilite des programmes" "Surveille les vieux programmes pour proposer des correctifs de compatibilite." 1 @{ 0 = "Les anciens programmes ne beneficieront plus des correctifs de compatibilite automatiques." }),
    (New-GBSvcTweak 'WerSvc' "Rapports d'erreurs Windows" "Collecte les plantages pour les envoyer a Microsoft." 1 @{ 0 = "Plus aucun rapport de plantage ne sera cree : plus dur de comprendre un plantage." }),
    (New-GBSvcTweak 'lfsvc' "Service de geolocalisation" "Donne ta position aux applis (Meteo, Cartes, fuseau horaire auto)." 1 @{ 0 = "La localisation et le fuseau horaire automatique ne marcheront plus." }),
    (New-GBSvcTweak 'RetailDemo' "Mode demo des magasins" "Utile seulement aux PC d'exposition en magasin." 0 $null),
    (New-GBSvcTweak 'MapsBroker' "Gestionnaire des cartes telechargees" "Met a jour les cartes hors connexion de l'appli Cartes." 1 $null),
    (New-GBSvcTweak 'Fax' "Telecopie (fax)" "Envoi et reception de fax depuis le PC." 0 $null),
    (New-GBSvcTweak 'SysMain' "SysMain (prechargement des applis)" "Precharge en memoire les applis que tu utilises souvent : utile sur disque dur, peu utile sur SSD." 2 @{ 0 = "Sur un disque dur (pas SSD), les applis se lanceront plus lentement." }),
    (New-GBSvcTweak 'WSearch' "Indexation de la recherche Windows" "Indexe tes fichiers pour une recherche instantanee." 2 @{ 0 = "La recherche de fichiers (menu Demarrer, Explorateur, Outlook) deviendra tres lente." }),

    # ================= WINDOWS UPDATE =================
    @{ Id = 'wupolicy'; Page = 'update'; Group = 'Politique de mise a jour'; Type = 'choice'; Name = "Mode de mise a jour"
       Desc = $(if ($Script:IsHomeEd) { "Sur Windows Famille, 'Securite seulement' n'a pas d'effet (reserve a Pro/Entreprise) : utilise la pause si besoin." } else { "Securite seulement : correctifs de securite tout de suite, nouvelles versions de Windows repoussees d'un an." })
       RecoIdx = 1
       Warns = @{ 2 = "Les mises a jour (securite comprise) sont en pause jusqu'en 2051. Tu peux les reprendre dans Parametres > Windows Update."
                  3 = "Plus aucune mise a jour automatique, meme de securite : ton PC sera expose aux failles connues. Fortement deconseille." }
       Opts = @((New-GBWuOpt 'Normal (Windows par defaut)' $false $false $false), (New-GBWuOpt 'Securite seulement (conseille)' $true $false $false),
                (New-GBWuOpt 'Pause tres longue (2051)' $false $true $false), (New-GBWuOpt 'Mises a jour automatiques coupees' $false $false $true)) },
    @{ Id = 'noreboot'; Page = 'update'; Group = 'Options'; Reco = $true; Name = "Pas de redemarrage automatique quand tu es connecte"
       Desc = "Windows Update ne redemarre plus le PC tout seul pendant une partie : il attend que tu le fasses."
       Reg = @((New-WinReg ($wuPol + '\AU') 'NoAutoRebootWithLoggedOnUsers' 1 $null)) },
    @{ Id = 'p2p'; Page = 'update'; Group = 'Options'; Reco = $true; Name = "Pas de partage des mises a jour avec d'autres PC"
       Desc = "Ton PC n'envoie plus de morceaux de mises a jour a d'autres PC sur internet (economise ta connexion montante)."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DeliveryOptimization' 'DODownloadMode' 0 $null)) },
    @{ Id = 'nodrivers'; Page = 'update'; Group = 'Options'; Reco = $false; Name = "Windows Update ne remplace plus tes pilotes"
       Desc = "Garde le pilote que tu as choisi (ex : pilote graphique NVIDIA/AMD installe a la main). Les pilotes se mettent alors a jour via GameBoost ou le fabricant."
       Reg = @((New-WinReg $wuPol 'ExcludeWUDriversInQualityUpdate' 1 $null)) },
    @{ Id = 'msupdate'; Page = 'update'; Group = 'Options'; Reco = $false; Name = "Mettre aussi a jour les autres produits Microsoft (Office...)"
       Desc = "Windows Update installe aussi les mises a jour d'Office et des autres logiciels Microsoft."
       Reg = @((New-WinReg $wuUx 'AllowMUUpdateService' 1 $null)) },
    @{ Id = 'storeauto'; Page = 'update'; Group = 'Options'; Reco = $false; Name = "Pas de mise a jour automatique des applis du Store"
       Desc = "Les applis du Microsoft Store ne se mettent plus a jour toutes seules (pratique pendant une partie en ligne)."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\WindowsStore' 'AutoDownload' 2 $null)) },

    # ================= NOTIFICATIONS =================
    @{ Id = 'toasts'; Page = 'notif'; Group = 'Notifications'; Reco = $false; Name = "Couper toutes les notifications"
       Desc = "Plus aucune bulle de notification (applis, Windows). Les alarmes et rappels importants peuvent aussi etre caches."
       Reg = @((New-WinReg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\PushNotifications' 'ToastEnabled' 0 1)) },
    @{ Id = 'toastsound'; Page = 'notif'; Group = 'Notifications'; Reco = $false; Name = "Notifications sans son"
       Desc = "Les notifications s'affichent toujours mais ne font plus de bruit (pratique en jeu ou en vocal)."
       Reg = @((New-WinReg $noti 'NOC_GLOBAL_SETTING_ALLOW_NOTIFICATION_SOUND' 0 $null)) },
    @{ Id = 'bell'; Page = 'notif'; Group = 'Notifications'; Reco = $false; Only = { $Script:WinBuild -ge 22621 }; R = 'explorer'; Name = "Masquer la cloche de notifications"
       Desc = "Retire l'icone de cloche a cote de l'horloge (les notifications restent accessibles avec Win + N)."
       Reg = @((New-WinReg $adv 'ShowNotificationIcon' 0 $null)) },
    @{ Id = 'locktoast'; Page = 'notif'; Group = 'Ecran de verrouillage'; Reco = $false; Name = "Pas de notifications sur l'ecran de verrouillage"
       Desc = "Personne ne voit tes messages quand le PC est verrouille."
       Reg = @((New-WinReg $noti 'NOC_GLOBAL_SETTING_ALLOW_TOASTS_ABOVE_LOCK' 0 $null)) },
    @{ Id = 'lockcrit'; Page = 'notif'; Group = 'Ecran de verrouillage'; Reco = $false; Name = "Pas de rappels ni d'appels sur l'ecran de verrouillage"
       Desc = "Masque aussi les notifications importantes (rappels, appels) quand le PC est verrouille."
       Reg = @((New-WinReg $noti 'NOC_GLOBAL_SETTING_ALLOW_CRITICAL_TOASTS_ABOVE_LOCK' 0 $null)) },
    @{ Id = 'tips'; Page = 'notif'; Group = 'Suggestions de Windows'; Reco = $true; Name = "Pas de conseils ni d'astuces Windows"
       Desc = "Plus de notifications 'Astuces et suggestions' pendant que tu utilises le PC."
       Reg = @((New-WinReg $cdm 'SubscribedContent-338389Enabled' 0 1), (New-WinReg $cdm 'SoftLandingEnabled' 0 1)) },
    @{ Id = 'welcome'; Page = 'notif'; Group = 'Suggestions de Windows'; Reco = $true; Name = "Pas d'ecran de bienvenue apres les mises a jour"
       Desc = "Windows ne te montre plus ses nouveautes en plein ecran apres une mise a jour."
       Reg = @((New-WinReg $cdm 'SubscribedContent-310093Enabled' 0 1)) },
    @{ Id = 'scoobe'; Page = 'notif'; Group = 'Suggestions de Windows'; Reco = $true; Name = "Pas d'ecran 'Terminons la configuration de ton PC'"
       Desc = "Windows ne te pousse plus OneDrive, Microsoft 365 et Game Pass apres les mises a jour."
       Reg = @((New-WinReg 'HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement' 'ScoobeSystemSettingEnabled' 0 $null)) },

    # ================= SON =================
    @{ Id = 'bootsound'; Page = 'sound'; Group = 'Son'; Reco = $false; Name = "Pas de son au demarrage de Windows"
       Desc = "Windows ne joue plus sa musique a l'ouverture de session."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI\BootAnimation' 'DisableStartupSound' 1 0),
               (New-WinReg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\EditionOverrides' 'UserSetting_DisableStartupSound' 1 0)) },
    @{ Id = 'ducking'; Page = 'sound'; Group = 'Son'; Type = 'choice'; Name = "Pendant un appel vocal, les autres sons..."
       Desc = "Quand Windows detecte une communication (Discord, Teams...), il peut baisser le son du jeu. 'Ne rien faire' garde le son du jeu intact."; RecoIdx = 3
       Opts = @(@{ L = 'sont coupes'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Multimedia\Audio' 'UserDuckingPreference' 0 'DWord' 1)) },
                @{ L = 'baissent de 80 % (defaut)'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Multimedia\Audio' 'UserDuckingPreference' 1 'DWord' 1)) },
                @{ L = 'baissent de 50 %'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Multimedia\Audio' 'UserDuckingPreference' 2 'DWord' 1)) },
                @{ L = 'ne changent pas (conseille)'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Multimedia\Audio' 'UserDuckingPreference' 3 'DWord' 1)) }) },
    @{ Id = 'voiceact'; Page = 'sound'; Group = 'Son'; Reco = $false; Name = "Interdire l'activation vocale des applis"
       Desc = "Les applis (assistants vocaux) n'ecoutent plus le micro en permanence pour un mot-cle."
       Reg = @((New-WinReg 'HKCU:\Software\Microsoft\Speech_OneCore\Settings\VoiceActivation\UserPreferenceForAllApps' 'AgentActivationEnabled' 0 $null)) },

    # ================= THEME WINDOWS =================
    @{ Id = 'thememode'; Page = 'theme'; Group = 'Couleurs'; Type = 'choice'; R = 'explorer'; Name = "Mode de couleur"
       Desc = "Theme clair ou sombre pour la barre des taches, le menu Demarrer, l'Explorateur et les applis compatibles."
       Opts = @(@{ L = 'Sombre'; V = @((New-WinVal $pers 'AppsUseLightTheme' 0 'DWord' 1), (New-WinVal $pers 'SystemUsesLightTheme' 0 'DWord' 1)) },
                @{ L = 'Clair (defaut)'; V = @((New-WinVal $pers 'AppsUseLightTheme' 1 'DWord' 1), (New-WinVal $pers 'SystemUsesLightTheme' 1 'DWord' 1)) },
                @{ L = 'Windows sombre, applis claires'; V = @((New-WinVal $pers 'AppsUseLightTheme' 1 'DWord' 1), (New-WinVal $pers 'SystemUsesLightTheme' 0 'DWord' 1)) }) },
    @{ Id = 'transparency'; Page = 'theme'; Group = 'Couleurs'; Reco = $false; Name = "Desactiver les effets de transparence"
       Desc = "Barre des taches et menus opaques (Acrylic / Mica coupes) : un peu moins de travail pour la carte graphique."
       Reg = @((New-WinReg $pers 'EnableTransparency' 0 1)) },
    @{ Id = 'wallpaper'; Page = 'theme'; Group = 'Couleurs'; Type = 'action'; Btn = "Appliquer"; Name = "Fond d'ecran Windows assorti au theme"
       Desc = "Met le fond d'ecran officiel de Windows correspondant au mode clair ou sombre actuel."
       Tech = "Windows 11 : C:\Windows\Web\Wallpaper\Windows\img0.jpg (clair) / img19.jpg (sombre). Windows 10 : C:\Windows\Web\4K\Wallpaper\Windows\img0_3840x2160.jpg"
       Do = { Set-GBWallpaperForTheme } },
    @{ Id = 'minanimate'; Page = 'theme'; Group = 'Effets visuels'; Reco = $false; R = 'session'; Name = "Pas d'animation a l'ouverture / reduction des fenetres"
       Desc = "Les fenetres apparaissent et se reduisent instantanement."
       Reg = @((New-WinReg 'HKCU:\Control Panel\Desktop\WindowMetrics' 'MinAnimate' '0' '1' 'String')) },
    @{ Id = 'taskanim'; Page = 'theme'; Group = 'Effets visuels'; Reco = $false; R = 'explorer'; Name = "Pas d'animations dans la barre des taches"
       Desc = "Les icones de la barre des taches ne s'animent plus."
       Reg = @((New-WinReg $adv 'TaskbarAnimations' 0 1)) },
    @{ Id = 'iconshadow'; Page = 'theme'; Group = 'Effets visuels'; Reco = $false; R = 'explorer'; Name = "Pas d'ombre sous le texte des icones du bureau"
       Desc = "Texte des icones du bureau sans ombre portee."
       Reg = @((New-WinReg $adv 'ListviewShadow' 0 1)) },

    # ================= BARRE DES TACHES =================
    @{ Id = 'taskalign'; Page = 'taskbar'; Group = 'Disposition'; Type = 'choice'; Only = { $Script:IsWin11 }; Name = "Alignement des icones"
       Desc = "Centre (Windows 11) ou a gauche comme sur Windows 10."
       Opts = @(@{ L = 'Au centre (defaut)'; V = @((New-WinVal $adv 'TaskbarAl' 1 'DWord' 1)) }, @{ L = 'A gauche'; V = @((New-WinVal $adv 'TaskbarAl' 0 'DWord' 1)) }) },
    @{ Id = 'searchmode'; Page = 'taskbar'; Group = 'Disposition'; Type = 'choice'; R = 'explorer'; Name = "Recherche dans la barre des taches"
       Desc = "Taille de la zone de recherche (Win + S marche toujours)."
       Opts = @(@{ L = 'Masquee'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'SearchboxTaskbarMode' 0)) },
                @{ L = 'Icone seule'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'SearchboxTaskbarMode' 1)) },
                @{ L = 'Zone de recherche'; V = @((New-WinVal 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Search' 'SearchboxTaskbarMode' 2)) }) },
    @{ Id = 'glom'; Page = 'taskbar'; Group = 'Disposition'; Type = 'choice'; Only = { $Script:WinBuild -ge 22621 -or -not $Script:IsWin11 }; R = 'explorer'; Name = "Regrouper les fenetres d'une meme appli"
       Desc = "Combiner les boutons de la barre des taches et masquer les noms."
       Opts = @(@{ L = 'Toujours (defaut)'; V = @((New-WinVal $adv 'TaskbarGlomLevel' 0 'DWord' 0)) }, @{ L = 'Quand la barre est pleine'; V = @((New-WinVal $adv 'TaskbarGlomLevel' 1 'DWord' 0)) },
                @{ L = 'Jamais'; V = @((New-WinVal $adv 'TaskbarGlomLevel' 2 'DWord' 0)) }) },
    @{ Id = 'seconds'; Page = 'taskbar'; Group = 'Disposition'; Reco = $false; R = 'explorer'; Name = "Afficher les secondes dans l'horloge"
       Desc = "L'horloge de la barre des taches affiche aussi les secondes (utile pour chronometrer)."
       Reg = @((New-WinReg $adv 'ShowSecondsInSystemClock' 1 $null)) },
    @{ Id = 'taskview'; Page = 'taskbar'; Group = 'Boutons'; Reco = $false; Name = "Masquer le bouton Vue des taches"
       Desc = "Retire le bouton des bureaux virtuels de la barre des taches (Win + Tab marche toujours)."
       Reg = @((New-WinReg $adv 'ShowTaskViewButton' 0 $null)) },
    @{ Id = 'widgets'; Page = 'taskbar'; Group = 'Boutons'; Reco = $true; R = 'explorer'; Only = { $Script:IsWin11 }; Name = "Desactiver les Widgets (actualites et meteo)"
       Desc = "Retire le panneau Widgets : moins de processus en arriere-plan (msedgewebview2) et plus d'actualites en survol de la barre des taches."
       Tech = ("Strategie HKLM\SOFTWARE\Policies\Microsoft\Dsh > AllowNewsAndInterests = 0. Si Windows la bloque (protection UCPD de Windows 11), " +
               "GameBoost desinstalle le composant Widgets (MicrosoftWindows.Client.WebExperience), reinstallable depuis le Microsoft Store.")
       Get = { Test-GBWidgetsOff }; Set = { param($on) Set-GBWidgetsOff $on } },
    @{ Id = 'feeds'; Page = 'taskbar'; Group = 'Boutons'; Reco = $true; R = 'explorer'; Only = { -not $Script:IsWin11 }; Name = "Desactiver 'Actualites et centres d'interet'"
       Desc = "Retire la meteo et les actualites de la barre des taches de Windows 10."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Feeds' 'EnableFeeds' 0 $null)) },
    @{ Id = 'chat'; Page = 'taskbar'; Group = 'Boutons'; Reco = $false; Only = { $Script:IsWin11 -and $Script:WinBuild -lt 26100 }; Name = "Masquer le bouton Conversation (Teams)"
       Desc = "Retire l'icone Teams/Conversation de la barre des taches."
       Reg = @((New-WinReg $adv 'TaskbarMn' 0 $null)) },
    @{ Id = 'copilotbtn'; Page = 'taskbar'; Group = 'Boutons'; Reco = $false; R = 'explorer'; Only = { $Script:WinBuild -ge 22621 -and $Script:WinBuild -lt 26100 }; Name = "Masquer le bouton Copilot (apercu)"
       Desc = "Retire le bouton Copilot de la barre des taches."
       Reg = @((New-WinReg $adv 'ShowCopilotButton' 0 $null)) },
    @{ Id = 'meetnow'; Page = 'taskbar'; Group = 'Boutons'; Reco = $false; R = 'explorer'; Only = { -not $Script:IsWin11 }; Name = "Masquer 'Conversation instantanee' (Meet Now)"
       Desc = "Retire le bouton camera de la zone de notification de Windows 10."
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\Explorer' 'HideSCAMeetNow' 1 $null)) },
    @{ Id = 'endtask'; Page = 'taskbar'; Group = 'Boutons'; Reco = $true; Only = { $Script:WinBuild -ge 22631 }; Name = "Ajouter 'Fin de tache' au clic droit de la barre des taches"
       Desc = "Clic droit sur un jeu bloque dans la barre des taches > Fin de tache : il est ferme de force sans ouvrir le Gestionnaire."
       Reg = @((New-WinReg ($adv + '\TaskbarDeveloperSettings') 'TaskbarEndTask' 1 $null)) },
    @{ Id = 'cleantaskbar'; Page = 'taskbar'; Group = 'Nettoyage'; Type = 'action'; Btn = "Nettoyer"; Name = "Retirer toutes les icones epinglees"
       Desc = "Desepingle les applis par defaut (Edge, Store, Courrier...). Sauvegarde faite avant ; l'Explorateur redemarre."
       Confirm = "Retirer TOUTES les icones epinglees de la barre des taches ?`r`n`r`nUne sauvegarde est faite avant, et l'Explorateur va redemarrer (la barre des taches clignote quelques secondes)."
       Tech = "Supprime HKCU\Software\Microsoft\Windows\CurrentVersion\Explorer\Taskband et les raccourcis de %APPDATA%\Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar (sauvegardes dans le dossier de GameBoost)."
       Do = { Clear-GBTaskbarPins } },

    # ================= MENU DEMARRER =================
    @{ Id = 'startrecos'; Page = 'start'; Group = 'Recommandations'; Reco = $true; R = 'explorer'; Only = { $Script:IsWin11 }; Name = "Pas de recommandations d'applis dans le menu Demarrer"
       Desc = "Retire les applis 'recommandees' (pubs) de la section Recommandations du menu Demarrer."
       Reg = @((New-WinReg $adv 'Start_IrisRecommendations' 0 $null)) },
    @{ Id = 'startrecent'; Page = 'start'; Group = 'Recommandations'; Reco = $false; R = 'explorer'; Name = "Pas de fichiers recents dans le menu Demarrer"
       Desc = "Le menu Demarrer et les listes de raccourcis n'affichent plus les fichiers ouverts recemment."
       Reg = @((New-WinReg $adv 'Start_TrackDocs' 0 1)) },
    @{ Id = 'starthide'; Page = 'start'; Group = 'Recommandations'; Reco = $false; R = 'explorer'; Only = { $Script:IsWin11 }; Name = "Masquer toute la section Recommande"
       Desc = $(if ($Script:IsHomeEd) { "Sur Windows Famille la section reste visible mais vide (combine-le avec les deux reglages au-dessus)." } else { "Supprime la section Recommande du menu Demarrer (Windows 11 Pro et superieur)." })
       Reg = @((New-WinReg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer' 'HideRecommendedSection' 1 $null),
