    @{ L = 'Avant GameBoost';  C = $cMuted;  D = "Tout ce que le curseur a change revient comme avant GameBoost. Tes propres reglages ne sont jamais touches." },
    @{ L = 'Leger';            C = $cGreen;  D = "Pubs, suggestions et astuces coupees, Mode Jeu, Maj x5, pas de redemarrage auto. Aucun risque." },
    @{ L = 'Equilibre';        C = $cCyan;   D = "+ telemetrie au minimum, historique d'activite, Bing, Widgets, souris sans acceleration, son pendant les appels." },
    @{ L = 'Conseille';        C = $cViolet; D = "+ HAGS, jeux en fenetre optimises, taches et service de telemetrie coupes, Windows Update 'securite seulement'. Le bon choix pour la plupart." },
    @{ L = 'Pousse';           C = $cYellow; D = "+ priorite processeur et reseau aux jeux, menus instantanes, transparence coupee, Copilot, services inutiles desactives." },
    @{ L = 'Maximum';          C = $cRed;    D = "+ applis du Store bloquees en arriere-plan, bridage d'alimentation et SysMain coupes, effets visuels au minimum. Pour PC de jeu dedie." }
)
