    powerthrottle = 5
    fse = 4; gamesprio = 4; sysresp = 4; menudelay = 4; startupdelay = 4; trackprogs = 4; wer = 4; transparency = 4; taskanim = 4; copilot = 4
    bgapps = 5; minanimate = 5; iconshadow = 5; fastboot = 5
