# Remet un reglage a choix a sa valeur d'avant GameBoost (si GameBoost l'avait change)
function Restore-WinCfgChoiceOriginal($t) {
    if ($t.Set -or -not $t.Opts) { return $false }
    $bk = Get-WinCfgBackup; $done = $false; $seen = @{}
    foreach ($o in $t.Opts) {
        foreach ($v in @($o.V)) {
            $key = $v.P + '|' + $v.N
            if ($seen.ContainsKey($key) -or -not $bk.ContainsKey($key)) { continue }
            $seen[$key] = $true; $b = $bk[$key]
            if ($b.Existed) { Write-WinCfgReg $v.P $v.N $b.Value $b.Type } else { Write-WinCfgReg $v.P $v.N $null $v.T }
            [void]$bk.Remove($key); $done = $true
        }
    }
    if ($done) { Save-WinCfgBackup }
    return $done
}
# Ce reglage a-t-il ete change par GameBoost ? (sinon c'est ton reglage d'avant : le curseur ne le remet jamais)
function Test-WinCfgChangedByGB($t) {
    $bk = Get-WinCfgBackup
    if ($t.Set) { return $bk.ContainsKey('custom|' + $t.Id) }
    foreach ($e in @($t.Reg)) { if ($e -and $bk.ContainsKey($e.P + '|' + $e.N)) { return $true } }
    foreach ($o in @($t.Opts)) { foreach ($v in @($o.V)) { if ($v -and $bk.ContainsKey($v.P + '|' + $v.N)) { return $true } } }
    return $false
}
# Niveau actuel du PC : Exact = niveau dont tous les reglages correspondent (-1 = personnalise), AtLeast = niveau atteint
function Get-WinCfgLevel {
    $st = @{}
    foreach ($t in $Script:WinTweaks) {
        if (-not (Test-WinCfgVisible $t)) { continue }
        try {
            if ($Script:WinLevelMap.ContainsKey($t.Id)) { $st[$t.Id] = @{ T = $t; Lv = [int]$Script:WinLevelMap[$t.Id]; On = [bool](Get-WinCfgState $t) } }
            elseif ($Script:WinLevelChoice.ContainsKey($t.Id)) { $c = $Script:WinLevelChoice[$t.Id]; $st[$t.Id] = @{ T = $t; Lv = [int]$c[0]; Idx = [int]$c[1]; On = ((Get-WinCfgChoice $t) -eq [int]$c[1]) } }
        } catch {}
    }
    $atLeast = 0
    for ($l = 1; $l -lt $Script:WinLevels.Count; $l++) {
        $ok = $true; foreach ($s in $st.Values) { if ($s.Lv -le $l -and -not $s.On) { $ok = $false; break } }
        if ($ok) { $atLeast = $l } else { break }
    }
    # Niveaux possibles : tout ce qui est en dessous est actif, et rien de ce que GameBoost a active au-dessus
    # (les reglages que tu avais deja faits toi-meme ne comptent pas)
    $cands = @()
    for ($l = 0; $l -le $atLeast; $l++) {
        $ok = $true
        foreach ($s in $st.Values) { if ($s.Lv -gt $l -and $s.On -and (Test-WinCfgChangedByGB $s.T)) { $ok = $false; break } }
        if ($ok) { $cands += $l }
    }
    # Plusieurs niveaux possibles : on garde celui que tu as choisi avec le curseur, sinon le plus haut
    $exact = -1
    $chosen = -1; try { $chosen = [int]$Script:Config.WinLevel } catch {}
    if ($cands.Count -gt 0) { if ($cands -contains $chosen) { $exact = $chosen } else { $exact = $cands[-1] } }
    return @{ Exact = $exact; AtLeast = $atLeast; States = $st }
}
# Changements necessaires pour passer au niveau $lvl
function Get-WinCfgLevelPlan([int]$lvl) {
    $info = Get-WinCfgLevel; $plan = New-Object System.Collections.ArrayList
    foreach ($s in $info.States.Values) {
        $t = $s.T
        if ($null -ne $s.Idx) {
            if ($s.Lv -le $lvl -and -not $s.On) { [void]$plan.Add(@{ T = $t; Op = 'choice'; Idx = $s.Idx; Txt = ($t.Name + " : " + $t.Opts[$s.Idx].L); Warn = $(if ($t.Warns) { $t.Warns[$s.Idx] }) }) }
            elseif ($s.Lv -gt $lvl -and $s.On -and (Test-WinCfgChangedByGB $t)) { [void]$plan.Add(@{ T = $t; Op = 'restore'; Txt = ($t.Name + " : valeur d'origine") }) }
        } else {
            if ($s.Lv -le $lvl -and -not $s.On) { [void]$plan.Add(@{ T = $t; Op = 'on'; Txt = ("Activer : " + $t.Name); Warn = $t.Warn }) }
            elseif ($s.Lv -gt $lvl -and $s.On -and (Test-WinCfgChangedByGB $t)) { [void]$plan.Add(@{ T = $t; Op = 'off'; Txt = ("Remettre comme avant : " + $t.Name) }) }
        }
    }
    return @($plan | Sort-Object { $_.T.Page }, { $_.Txt })
}

