# Suppression persistante : script + tache planifiee au demarrage (compte SYSTEM), dans un dossier protege
$Script:PersistTaskPath = '\GameBoost\'
$Script:PersistTaskName = 'SuppressionApplis'
function Get-GBScriptsDir {
    try {
        if (-not $env:ProgramData) { return $null }
        $root = Join-Path $env:ProgramData 'GameBoost'
        if (-not (New-GBSecureDir $root)) { return $null }
        $d = Join-Path $root 'Scripts'
        if (New-GBSecureDir $d) { return $d }
    } catch {}
    return $null
}
function Get-GBPersistList {
    $f = Join-Path (Join-Path $env:ProgramData 'GameBoost\Scripts') 'SuppressionApplis.json'
    try { if (Test-Path -LiteralPath $f) { return @(Get-Content -LiteralPath $f -Raw | ConvertFrom-Json) } } catch {}
    return @()
}
function Get-GBPersistTask { return (Test-GBTask $Script:PersistTaskPath $Script:PersistTaskName) }
function Set-GBPersistList($names) {
    $names = @($names | Where-Object { $_ -match '^[A-Za-z0-9][A-Za-z0-9._\-]*$' } | Sort-Object -Unique)
    $dir = Get-GBScriptsDir
    if (-not $dir) { throw "dossier protege C:\ProgramData\GameBoost\Scripts impossible a creer (droits administrateur ?)" }
    $ps1 = Join-Path $dir 'SuppressionApplis.ps1'; $json = Join-Path $dir 'SuppressionApplis.json'
    if ($names.Count -eq 0) {
        try { Unregister-ScheduledTask -TaskPath $Script:PersistTaskPath -TaskName $Script:PersistTaskName -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        Remove-Item -LiteralPath $ps1, $json -Force -ErrorAction SilentlyContinue
        return
    }
    $list = ($names | ForEach-Object { "'" + $_ + "'" }) -join ', '
    $body = @(
        "# Script cree par GameBoost (Config Windows > Applis Windows)."
        "# Lance au demarrage de Windows par la tache planifiee \GameBoost\SuppressionApplis (compte SYSTEM) :"
        "# il supprime de nouveau ces applis si Windows les a reinstallees."
        "# Pour l'arreter : GameBoost > Config Windows > Applis Windows > 'Arreter la suppression persistante'."
        ('$names = @(' + $list + ')')
        '$log = Join-Path $PSScriptRoot ''SuppressionApplis.log'''
        'function W($m) { try { Add-Content -LiteralPath $log -Value ((Get-Date -Format ''yyyy-MM-dd HH:mm:ss'') + '' '' + $m) } catch {} }'
        '$prov = @(); try { $prov = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop) } catch {}'
        'foreach ($n in $names) {'
        '    foreach ($p in @(Get-AppxPackage -AllUsers -Name $n -ErrorAction SilentlyContinue)) {'
        '        try { Remove-AppxPackage -Package $p.PackageFullName -AllUsers -ErrorAction Stop; W (''supprimee : '' + $p.Name) } catch { W (''echec '' + $p.Name + '' : '' + $_.Exception.Message) }'
        '    }'
        '    foreach ($pp in @($prov | Where-Object { $_.DisplayName -eq $n })) { try { Remove-AppxProvisionedPackage -Online -PackageName $pp.PackageName -ErrorAction Stop | Out-Null; W (''version provisionnee retiree : '' + $n) } catch {} }'
        '}'
    ) -join "`r`n"
    Set-Content -LiteralPath $ps1 -Value $body -Encoding UTF8
    ConvertTo-Json @($names) | Set-Content -LiteralPath $json -Encoding UTF8
    $act = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ('-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $ps1 + '"')
    $trg = New-ScheduledTaskTrigger -AtStartup
    $pri = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $set = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -ExecutionTimeLimit (New-TimeSpan -Minutes 15)
    Register-ScheduledTask -TaskPath $Script:PersistTaskPath -TaskName $Script:PersistTaskName -Action $act -Trigger $trg -Principal $pri -Settings $set `
        -Description "GameBoost : supprime de nouveau les applis Windows choisies si elles reviennent (Config Windows > Applis Windows)." -Force -ErrorAction Stop | Out-Null
}

# Suppression d'applis du Store (utilise aussi par la desinstallation profonde)
$Script:AppxRemoveScript = {
    param($sync, $names)
    try {
        $prov = @(); try { $prov = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop) } catch {}
        foreach ($n in @($names)) {
            $sync.Status = "Suppression : " + $n + "..."
            $ok = $false; $err = ""
            $pk = @()
            try { $pk = @(Get-AppxPackage -AllUsers -Name $n -ErrorAction Stop) } catch { try { $pk = @(Get-AppxPackage -Name $n -ErrorAction Stop) } catch {} }
            foreach ($p in $pk) {
                try { Remove-AppxPackage -Package $p.PackageFullName -AllUsers -ErrorAction Stop; $ok = $true }
                catch { try { Remove-AppxPackage -Package $p.PackageFullName -ErrorAction Stop; $ok = $true } catch { $err = $_.Exception.Message } }
            }
            foreach ($pp in @($prov | Where-Object { $_.DisplayName -eq $n })) {
                try { Remove-AppxProvisionedPackage -Online -PackageName $pp.PackageName -ErrorAction Stop | Out-Null; $ok = $true } catch {}
            }
            if (@($pk).Count -eq 0 -and -not $ok) { $err = "deja absente" }
            [void]$sync.Lines.Add(@{ Name = $n; Ok = $ok; Err = $err })
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}

# Inventaire des applis / capacites / fonctionnalites (lent : en arriere-plan)
$Script:WinAppsScanScript = {
    param($sync, $mode)
    try {
        if ($mode -eq 'apps') {
            $pk = @(); try { $pk = @(Get-AppxPackage -AllUsers -ErrorAction Stop) } catch { $pk = @(Get-AppxPackage -ErrorAction SilentlyContinue) }
            $seen = @{}; $items = New-Object System.Collections.ArrayList
            foreach ($p in $pk) {
                if ($p.IsFramework -or $p.NonRemovable -or [string]$p.SignatureKind -eq 'System' -or $seen.ContainsKey($p.Name)) { continue }
                $seen[$p.Name] = $true
                [void]$items.Add(@{ Name = [string]$p.Name; Ver = [string]$p.Version })
            }
            $sync.Items = $items.ToArray()
            try { $sync.Prov = @(Get-AppxProvisionedPackage -Online -ErrorAction Stop | ForEach-Object { [string]$_.DisplayName }) } catch { $sync.Prov = @() }
        } elseif ($mode -eq 'caps') {
            $sync.Items = @(Get-WindowsCapability -Online -ErrorAction Stop | ForEach-Object { @{ Name = [string]$_.Name; State = [string]$_.State } })
        } elseif ($mode -eq 'feats') {
            $sync.Items = @(Get-WindowsOptionalFeature -Online -ErrorAction Stop | ForEach-Object { @{ Name = [string]$_.FeatureName; State = [string]$_.State } })
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}
# Actions sur les capacites / fonctionnalites / OneDrive
$Script:WinAppsActionScript = {
    param($sync, $job)
    try {
        foreach ($n in @($job.Names)) {
            $sync.Status = $job.Verb + " : " + $n + "..."
            $ok = $false; $err = ""; $reboot = $false
            try {
                switch ($job.Kind + '|' + $job.Op) {
                    'caps|remove' { $r = Remove-WindowsCapability -Online -Name $n -ErrorAction Stop; $reboot = [bool]$r.RestartNeeded; $ok = $true }
                    'caps|add'    { $r = Add-WindowsCapability -Online -Name $n -ErrorAction Stop; $reboot = [bool]$r.RestartNeeded; $ok = $true }
                    'feats|remove' { $r = Disable-WindowsOptionalFeature -Online -FeatureName $n -NoRestart -ErrorAction Stop; $reboot = [bool]$r.RestartNeeded; $ok = $true }
                    'feats|add'    { $r = Enable-WindowsOptionalFeature -Online -FeatureName $n -NoRestart -All -ErrorAction Stop; $reboot = [bool]$r.RestartNeeded; $ok = $true }
                    'onedrive|remove' {
                        Get-Process OneDrive -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
                        $cands = @((Join-Path $env:SystemRoot 'System32\OneDriveSetup.exe'), (Join-Path $env:SystemRoot 'SysWOW64\OneDriveSetup.exe'))
                        $cands += @(Get-ChildItem -Path (Join-Path $env:LOCALAPPDATA 'Microsoft\OneDrive\*\OneDriveSetup.exe'), (Join-Path ${env:ProgramFiles} 'Microsoft OneDrive\*\OneDriveSetup.exe') -ErrorAction SilentlyContinue | ForEach-Object { $_.FullName })
                        $setup = @($cands | Where-Object { $_ -and (Test-Path -LiteralPath $_) }) | Select-Object -Last 1
                        if (-not $setup) { throw "programme de desinstallation de OneDrive introuvable (deja supprime ?)" }
                        $a = '/uninstall'; if ($setup -like (Join-Path ${env:ProgramFiles} '*')) { $a = '/uninstall /allusers' }
                        $p = Start-Process -FilePath $setup -ArgumentList $a -Wait -PassThru -WindowStyle Hidden
                        if ($p.ExitCode -ne 0) { throw ("code " + $p.ExitCode) }
                        $ok = $true
                    }
                }
            } catch { $err = $_.Exception.Message }
            [void]$sync.Lines.Add(@{ Name = $n; Ok = $ok; Err = $err; Reboot = $reboot })
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}

