# Options recentes de WinGet (--disable-interactivity, --include-unknown : version 1.4 et plus) : lues une fois
function Get-GBWingetModern($wg) {
    if ($null -ne $Script:WgModern) { return $Script:WgModern }
    $Script:WgModern = $true
    try {
        $v = [string](& $wg --version 2>$null | Select-Object -First 1)
        $m = [regex]::Match($v, '(\d+)\.(\d+)')
        if ($m.Success -and ([int]$m.Groups[1].Value -lt 1 -or ([int]$m.Groups[1].Value -eq 1 -and [int]$m.Groups[2].Value -lt 4))) { $Script:WgModern = $false }
    } catch {}
    return $Script:WgModern
}
# Retire les options inconnues des anciennes versions de WinGet
function Get-GBWingetArgs($list, [bool]$modern) {
    if ($modern) { return @($list) }
    return @($list | Where-Object { $_ -ne '--disable-interactivity' -and $_ -ne '--include-unknown' })
}
function Find-GBWinget {
    $c = Get-Command winget.exe -ErrorAction SilentlyContinue
    if ($c) { return $c.Source }
    $p = Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps\winget.exe'
    if (Test-Path -LiteralPath $p) { return $p }
    try { $a = Get-AppxPackage -Name Microsoft.DesktopAppInstaller -ErrorAction Stop | Select-Object -First 1; $e = Join-Path $a.InstallLocation 'winget.exe'; if (Test-Path -LiteralPath $e) { return $e } } catch {}
    return $null
}
# Etat installe : export WinGet (liste des paquets reconnus par leur identifiant)
$Script:WingetScanScript = {
    param($sync, $wg)
    try {
        $tmp = Join-Path $env:TEMP ('gb_winget_' + [guid]::NewGuid().ToString('N') + '.json')
        $a = @('export', '-o', ('"' + $tmp + '"'), '--accept-source-agreements', '--disable-interactivity')
        if ($sync.Modern -eq $false) { $a = @($a | Where-Object { $_ -ne '--disable-interactivity' }) }
        $p = Start-Process -FilePath $wg -ArgumentList $a -Wait -PassThru -WindowStyle Hidden
        $ids = @()
        if (Test-Path -LiteralPath $tmp) {
            $j = Get-Content -LiteralPath $tmp -Raw | ConvertFrom-Json
            foreach ($s in @($j.Sources)) { foreach ($pk in @($s.Packages)) { $ids += [string]$pk.PackageIdentifier } }
            Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue
        } elseif ($p.ExitCode -ne 0) { throw ("WinGet a renvoye le code " + $p.ExitCode) }
        $sync.Ids = $ids
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}
$Script:WingetRunScript = {
    param($sync, $job)
    try {
        foreach ($id in @($job.Ids)) {
            $sync.Current = $id
            if ($job.Op -eq 'install') { $a = @('install', '--id', $id, '-e', '--silent', '--accept-package-agreements', '--accept-source-agreements', '--disable-interactivity') }
            else { $a = @('uninstall', '--id', $id, '-e', '--silent', '--accept-source-agreements', '--disable-interactivity') }
            if ($job.Modern -eq $false) { $a = @($a | Where-Object { $_ -ne '--disable-interactivity' }) }
            $code = -1; $err = ""
            try { $p = Start-Process -FilePath $job.Wg -ArgumentList $a -Wait -PassThru -WindowStyle Hidden; $code = $p.ExitCode } catch { $err = $_.Exception.Message }
            # 0x8A15002B : deja installe / rien a mettre a jour
            $ok = ($code -eq 0 -or $code -eq -1978335189)
            [void]$sync.Lines.Add(@{ Id = $id; Ok = $ok; Code = $code; Err = $err })
        }
    } catch { $sync.Error = $_.Exception.Message }
    finally { $sync.Done = $true }
}
function Get-GBWingetErrorText([int]$code) {
    switch ($code) {
        -1978335212 { return "paquet introuvable dans WinGet" }
        -1978335216 { return "pas de version compatible avec ce PC" }
        -1978334975 { return "le programme est ouvert : ferme-le puis reessaie" }
        -1978335230 { return "pas de connexion a la source WinGet (internet ?)" }
        -1978334967 { return "un redemarrage est necessaire" }
    }
    return ("code " + $code)
}

# --- Fichier d'installation automatique de Windows (autounattend.xml) ---
function New-GBAutounattendXml([bool]$bypass, [bool]$skipOobe, [bool]$localAcct, $apps, $arch) {
    $sb = New-Object System.Text.StringBuilder
    $comp = 'processorArchitecture="' + $arch + '" publicKeyToken="31bf3856ad364e35" language="neutral" versionScope="nonSxS"'
    [void]$sb.AppendLine('<?xml version="1.0" encoding="utf-8"?>')
    [void]$sb.AppendLine('<!-- Cree par GameBoost (Config Windows > Outils avances). A copier a la racine de la cle USB d''installation de Windows. -->')
    [void]$sb.AppendLine('<unattend xmlns="urn:schemas-microsoft-com:unattend" xmlns:wcm="http://schemas.microsoft.com/WMIConfig/2002/State">')
    if ($bypass -or $skipOobe) {
        [void]$sb.AppendLine('  <settings pass="windowsPE">')
        [void]$sb.AppendLine('    <component name="Microsoft-Windows-Setup" ' + $comp + '>')
        if ($skipOobe) { [void]$sb.AppendLine('      <UserData><AcceptEula>true</AcceptEula></UserData>') }
        if ($bypass) {
            [void]$sb.AppendLine('      <RunSynchronous>')
            $o = 1
            foreach ($v in @('BypassTPMCheck', 'BypassSecureBootCheck', 'BypassRAMCheck', 'BypassCPUCheck', 'BypassStorageCheck')) {
                [void]$sb.AppendLine('        <RunSynchronousCommand wcm:action="add"><Order>' + $o + '</Order><Path>reg.exe add "HKLM\SYSTEM\Setup\LabConfig" /v ' + $v + ' /t REG_DWORD /d 1 /f</Path></RunSynchronousCommand>')
                $o++
            }
            [void]$sb.AppendLine('      </RunSynchronous>')
        }
        [void]$sb.AppendLine('    </component>')
        [void]$sb.AppendLine('  </settings>')
    }
    $cmds = @()
    if ($localAcct) { $cmds += 'reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE" /v BypassNRO /t REG_DWORD /d 1 /f' }
    $apps = @($apps | Where-Object { $_ -match '^[A-Za-z0-9][A-Za-z0-9._\-]*$' })
    if ($apps.Count -gt 0) {
        $list = ($apps | ForEach-Object { "'" + $_ + "'" }) -join ','
        $cmds += ('powershell.exe -NoProfile -Command "Get-AppxProvisionedPackage -Online | Where-Object { @(' + $list + ') -contains $_.DisplayName } | Remove-AppxProvisionedPackage -Online"')
    }
    if ($cmds.Count -gt 0) {
        [void]$sb.AppendLine('  <settings pass="specialize">')
        [void]$sb.AppendLine('    <component name="Microsoft-Windows-Deployment" ' + $comp + '>')
        [void]$sb.AppendLine('      <RunSynchronous>')
        $o = 1
        foreach ($c in $cmds) { [void]$sb.AppendLine('        <RunSynchronousCommand wcm:action="add"><Order>' + $o + '</Order><Path>' + [System.Security.SecurityElement]::Escape($c) + '</Path></RunSynchronousCommand>'); $o++ }
        [void]$sb.AppendLine('      </RunSynchronous>')
        [void]$sb.AppendLine('    </component>')
        [void]$sb.AppendLine('  </settings>')
    }
    if ($skipOobe -or $localAcct) {
        [void]$sb.AppendLine('  <settings pass="oobeSystem">')
        [void]$sb.AppendLine('    <component name="Microsoft-Windows-Shell-Setup" ' + $comp + '>')
        [void]$sb.AppendLine('      <OOBE>')
        if ($skipOobe) { [void]$sb.AppendLine('        <HideEULAPage>true</HideEULAPage>'); [void]$sb.AppendLine('        <ProtectYourPC>3</ProtectYourPC>') }
        if ($localAcct) { [void]$sb.AppendLine('        <HideOnlineAccountScreens>true</HideOnlineAccountScreens>') }
        [void]$sb.AppendLine('      </OOBE>')
        [void]$sb.AppendLine('    </component>')
        [void]$sb.AppendLine('  </settings>')
    }
    [void]$sb.AppendLine('</unattend>')
    $xml = $sb.ToString()
    [void][xml]$xml   # verifie que le fichier est bien forme
    return $xml
}

# Lisible pour les details techniques : HKCU:\... -> HKCU\...
function Format-GBRegPath($p) { return ([string]$p -replace '^(HK[A-Z]+):\\', '$1\') }
function Format-GBRegVal($v, $t) { if ($null -eq $v) { return "(absente)" }; if ($t -eq 'String') { return '"' + $v + '"' }; return [string]$v }
function Get-WinCfgTech($t) {
    $lines = New-Object System.Collections.ArrayList
    if ($t.Tech) { [void]$lines.Add([string]$t.Tech) }
    if ($t.Reg) {
        foreach ($e in $t.Reg) {
            $r = Read-RegValue $e.P $e.N $e.T
            $cur = "(absente)"; if ($r.Existed) { $cur = Format-GBRegVal $r.Value $e.T }
            [void]$lines.Add((Format-GBRegPath $e.P) + "  >  " + $e.N + " (" + $e.T + ")  |  active : " + (Format-GBRegVal $e.On $e.T) +
                             "  |  Windows par defaut : " + (Format-GBRegVal $e.Off $e.T) + "  |  actuelle : " + $cur)
        }
    }
    if ($t.Type -eq 'choice' -and $t.Opts -and -not $t.Get) {
        $keys = @{}
        foreach ($o in $t.Opts) { foreach ($v in @($o.V)) { $keys[$v.P + '|' + $v.N] = $v } }
        foreach ($k in $keys.Keys) {
            $v = $keys[$k]; $r = Read-RegValue $v.P $v.N $v.T
            $cur = "(absente)"; if ($r.Existed) { $cur = Format-GBRegVal $r.Value $v.T }
            [void]$lines.Add((Format-GBRegPath $v.P) + "  >  " + $v.N + " (" + $v.T + ")  |  actuelle : " + $cur)
        }
        foreach ($o in $t.Opts) { [void]$lines.Add("  - " + $o.L + " : " + ((@($o.V) | ForEach-Object { $_.N + " = " + (Format-GBRegVal $_.V $_.T) }) -join ", ")) }
    }
    if ($t.Svc) { [void]$lines.Add("Service : " + $t.Svc + " (cle Start : 4 = desactive, 3 = manuel, 2 = automatique ; pris en compte au redemarrage)") }
    $scope = @()
    foreach ($p in @(@($t.Reg | ForEach-Object { $_.P }) + @($t.Opts | ForEach-Object { @($_.V) | ForEach-Object { $_.P } }))) {
        if ($p -like 'HKCU:*') { $scope += 'ton compte' } elseif ($p -like 'HKLM:*') { $scope += 'tout le PC' }
    }
    $scope = @($scope | Select-Object -Unique)
    if ($scope.Count -gt 0) { [void]$lines.Add("Portee : " + ($scope -join " + ") + "  |  applique une fois (rien n'est reapplique en arriere-plan)") }
    return @($lines)
}

function Show-WindowsConfig {
    if ($Script:Boosted) {
        [System.Windows.Forms.MessageBox]::Show("Arrete d'abord le boost : il modifie lui aussi certains de ces reglages pendant le jeu.", "GameBoost") | Out-Null
        return
    }
    $wc = @{ Silent = $false; Rp = $false; Need = @{}; Page = $null; Task = $null; Sync = $null; Mode = ''; PowerUnlocked = $false
             Apps = @{ Tab = 'apps'; Data = @{}; Persist = $false }; Wg = @{ Path = $null; Ids = $null; Cat = 'Toutes' }; Clean = @{ Sizes = $null } }
    $d = New-GBDialog "Config Windows" 1100 740
    $d.FormBorderStyle = "Sizable"; $d.MaximizeBox = $true; $d.MinimumSize = New-Object System.Drawing.Size(900, 560)
    $null = Add-DlgLabel $d "Config Windows" 16 6 400 30 $fontPage $cViolet
    $sub = Add-DlgLabel $d ("Tous les reglages de Windows au meme endroit. Chaque reglage montre l'etat REEL du PC et s'applique tout de suite, une seule fois. " +
                            "La premiere modification garde la valeur d'origine : 'Tout annuler' remet Windows exactement comme avant.") 16 36 1052 36 $fontUI $cMuted
    $sub.Anchor = "Top, Left, Right"

    # --- Curseur : niveau d'optimisation Windows (de "Avant GameBoost" a "Maximum")
    $lvBand = New-Object System.Windows.Forms.Panel
    $lvBand.Location = New-Object System.Drawing.Point(16, 76); $lvBand.Size = New-Object System.Drawing.Size(1052, 46); $lvBand.BackColor = $cPanel; $lvBand.Anchor = "Top, Left, Right"
    $d.Controls.Add($lvBand)
    $null = Add-DlgLabel $lvBand "NIVEAU D'OPTIMISATION" 10 4 220 20 $fontHud $cViolet
    $lvCur = Add-DlgLabel $lvBand "" 10 24 230 18 $fontUI $cMuted
    $lvSlider = New-GBSlider $lvBand 0 ($Script:WinLevels.Count - 1) 3 @($Script:WinLevels | ForEach-Object { $_.L }) @($Script:WinLevels | ForEach-Object { $_.C }) "" 240 8 470
    if ($lvSlider -isnot [System.Windows.Forms.TrackBar]) { $lvSlider.ValueWidth = 150 }
    $tip.SetToolTip($lvSlider, "Glisse puis lache : GameBoost te montre la liste des changements avant de les appliquer.")
    $lvDesc = Add-DlgLabel $lvBand "" 720 3 326 40 $fontUI $cMuted
    $lvDesc.Anchor = "Top, Left, Right"
    $showLevelDesc = { param($v) $lvDesc.Text = $Script:WinLevels[[int]$v].D; $lvDesc.ForeColor = $Script:WinLevels[[int]$v].C }
    $lvSlider.add_ValueChanged({ & $showLevelDesc $lvSlider.Value })
    # Etat reel du PC : niveau exact, ou "personnalise" si des reglages ont ete changes a la main
    $refreshLevel = {
        $li = Get-WinCfgLevel
        $v = $li.Exact; if ($v -lt 0) { $v = $li.AtLeast }
        Set-SliderValue $lvSlider $v
        if ($li.Exact -ge 0) { $lvCur.Text = "Etat actuel : " + $Script:WinLevels[$li.Exact].L; $lvCur.ForeColor = $Script:WinLevels[$li.Exact].C }
        else { $lvCur.Text = "Etat actuel : personnalise (" + $Script:WinLevels[$li.AtLeast].L + " +)"; $lvCur.ForeColor = $cYellow }
        & $showLevelDesc $v
    }

    # --- Recherche + navigation a gauche
    $txtSearch = New-Object System.Windows.Forms.TextBox
    $txtSearch.Location = New-Object System.Drawing.Point(16, 130); $txtSearch.Size = New-Object System.Drawing.Size(240, 24)
    $txtSearch.BackColor = $cPanel; $txtSearch.ForeColor = $cText; $txtSearch.BorderStyle = "FixedSingle"
    $d.Controls.Add($txtSearch)
    $tip.SetToolTip($txtSearch, "Cherche un reglage dans toutes les pages (nom ou description)")
    $lblSearchHint = Add-DlgLabel $d "Rechercher un reglage..." 20 133 200 18 $fontUI $cMuted
    $lblSearchHint.BackColor = $cPanel; $lblSearchHint.BringToFront()
    $lblSearchHint.Add_Click({ $txtSearch.Focus() })

    $nav = New-Object System.Windows.Forms.ListBox
    $nav.Location = New-Object System.Drawing.Point(16, 160); $nav.Size = New-Object System.Drawing.Size(240, 446)
    $nav.BackColor = $cPanel; $nav.ForeColor = $cText; $nav.BorderStyle = "FixedSingle"; $nav.IntegralHeight = $false
    $nav.DrawMode = "OwnerDrawVariable"; $nav.Anchor = "Top, Bottom, Left"
    foreach ($p in $Script:WinCfgPages) { [void]$nav.Items.Add($p) }
    if ($Script:UiOK) { [GBTheme]::StyleNav($nav, $fontHud, $fontBold, $cPanel, $cDeep, $cCyan, $cText, $cViolet, [single][math]::Max(1.0, [double]$Script:DpiScale)) }
    else {
    $nav.add_MeasureItem({
        param($sender, $e)
        $p = $sender.Items[$e.Index]
        $h = 30; if ($p.H) { $h = 30; if ($e.Index -gt 0) { $h = 36 } }
        $e.ItemHeight = [int]($h * [math]::Max(1.0, [double]$Script:DpiScale))
    })
    $nav.add_DrawItem({
        param($sender, $e)
        if ($e.Index -lt 0) { return }
        $p = $sender.Items[$e.Index]
        $br = New-Object System.Drawing.SolidBrush($cPanel); $e.Graphics.FillRectangle($br, $e.Bounds); $br.Dispose()
        $flags = ([System.Windows.Forms.TextFormatFlags]::Bottom -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix)
        if ($p.H) {
            $tr = New-Object System.Drawing.Rectangle(($e.Bounds.X + 10), $e.Bounds.Y, ($e.Bounds.Width - 12), ($e.Bounds.Height - 6))
            [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, ('// ' + $p.H), $fontHud, $tr, $cCyan, $flags)
            return
        }
        $sel = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
        if ($sel) {
            $bb = New-Object System.Drawing.SolidBrush($cDeep); $e.Graphics.FillRectangle($bb, $e.Bounds); $bb.Dispose()
            $bv = New-Object System.Drawing.SolidBrush($cViolet); $e.Graphics.FillRectangle($bv, $e.Bounds.X, $e.Bounds.Y + 5, 3, $e.Bounds.Height - 10); $bv.Dispose()
        }
        $fg = $cText; if ($sel) { $fg = $cViolet }
        $tr = New-Object System.Drawing.Rectangle(($e.Bounds.X + 22), $e.Bounds.Y, ($e.Bounds.Width - 24), $e.Bounds.Height)
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, [string]$p.T, $fontBold, $tr, $fg,
            ([System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix))
    })
    }
    $d.Controls.Add($nav)

    # --- Zone de droite : lignes de reglages (flow) ou page a liste (panel)
    $flow = New-Object System.Windows.Forms.FlowLayoutPanel; Set-GBDoubleBuffered $flow
    $flow.Location = New-Object System.Drawing.Point(268, 130); $flow.Size = New-Object System.Drawing.Size(800, 476)
    $flow.FlowDirection = "TopDown"; $flow.WrapContents = $false; $flow.AutoScroll = $true; $flow.BackColor = $cBg
    $flow.Anchor = "Top, Bottom, Left, Right"
    $d.Controls.Add($flow)
    $panel = New-Object System.Windows.Forms.Panel; Set-GBDoubleBuffered $panel
    $panel.Location = $flow.Location; $panel.Size = $flow.Size; $panel.BackColor = $cBg; $panel.Anchor = "Top, Bottom, Left, Right"; $panel.Visible = $false
    $d.Controls.Add($panel)

    $lblSt = Add-DlgLabel $d "" 16 614 1052 22 $fontUI $cMuted
    $lblSt.Anchor = "Bottom, Left, Right"
    $btnReco = Add-DlgButton $d "Appliquer les reglages conseilles" 16 644 250
    $btnReco.ForeColor = $cGreen; $btnReco.Anchor = "Bottom, Left"
    $btnUndo = Add-DlgButton $d "Tout annuler (valeurs d'origine)" 274 644 240
    $btnUndo.ForeColor = $cRed; $btnUndo.Anchor = "Bottom, Left"
    $btnExp = Add-DlgButton $d "Relancer l'Explorateur" 522 644 190
    $btnExp.Anchor = "Bottom, Left"
    $btnClose = Add-DlgButton $d "Fermer" 952 644 116
    $btnClose.Anchor = "Bottom, Right"; $d.CancelButton = $btnClose
    $btnClose.Add_Click({ $d.Close() })

    $updateStatus = {
        $all = @($Script:WinTweaks | Where-Object { $_.Type -ne 'action' -and (Test-WinCfgVisible $_) })
        $reco = 0; $recoTot = 0
        foreach ($t in $all) {
            try {
                if ($t.Type -eq 'choice') { if ($null -ne $t.RecoIdx) { $recoTot++; if ((Get-WinCfgChoice $t) -eq [int]$t.RecoIdx) { $reco++ } } }
                elseif ($t.Reco) { $recoTot++; if (Get-WinCfgState $t) { $reco++ } }
            } catch {}
        }
        $txt = "" + $all.Count + " reglages  |  conseilles appliques : " + $reco + " / " + $recoTot
        $chg = @((Get-WinCfgBackup).Keys).Count
        if ($chg -gt 0) { $txt += "  |  " + $chg + " valeur(s) d'origine gardee(s) pour 'Tout annuler'" }
        $todo = @()
        if ($wc.Need['explorer']) { $todo += "relance l'Explorateur (bouton)" }
        if ($wc.Need['session']) { $todo += "ferme ta session" }
        if ($wc.Need['reboot']) { $todo += "redemarre le PC" }
        if ($todo.Count -gt 0) { $txt += "  |  Pour finir : " + ($todo -join " et ") }
        $lblSt.Text = $txt; $lblSt.ForeColor = $cMuted
        if ($todo.Count -gt 0) { $lblSt.ForeColor = $cYellow }
        try { & $refreshLevel } catch {}
    }
    $setStatus ={ param($text, $color) $lblSt.Text = $text; $lblSt.ForeColor = $color }

    $ensureRp = {
        if ($wc.Rp) { return }
        $wc.Rp = $true
        & $setStatus "Point de restauration Windows avant la premiere modification (jusqu'a 1 min)..." $cYellow
        $d.Enabled = $false; [System.Windows.Forms.Application]::DoEvents()
        try { New-WindowsRestorePoint } catch {} finally { $d.Enabled = $true }
        Update-BoostButton
    }

    # --- Lignes
    $rowW = 760
    $newRowPanel = {
        param($h)
        $row = New-Object System.Windows.Forms.Panel
        $row.Size = New-Object System.Drawing.Size($rowW, $h); $row.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, 4); $row.BackColor = $cPanel
        return $row
    }
    $addBadge = {
        param($row, $t, $x, $w)
        $badge = New-Object System.Windows.Forms.Label
        $badge.Location = New-Object System.Drawing.Point($x, 8); $badge.Size = New-Object System.Drawing.Size($w, 20); $badge.TextAlign = "MiddleRight"; $badge.Anchor = "Top, Right"
        $parts = @()
        if ($t.Reco) { $parts += "conseille" }
        if ($t.Warn) { $parts += "attention" }
        switch ($t.R) { 'explorer' { $parts += "+ Explorateur" } 'reboot' { $parts += "+ redemarrage" } 'session' { $parts += "+ session" } }
        $badge.Text = ($parts -join "  ")
        $badge.ForeColor = $cMuted
        if ($parts -contains "conseille") { $badge.ForeColor = $cGreen }
        if ($t.R -eq 'reboot' -or $t.Warn) { $badge.ForeColor = $cYellow }
        $row.Controls.Add($badge)
    }
    # Description + "details techniques" depliables
    $addDescTech = {
        param($row, $t, $y)
        $lblD = New-Object System.Windows.Forms.Label
        $lblD.Text = [string]$t.Desc; $lblD.Location = New-Object System.Drawing.Point(12, $y); $lblD.Size = New-Object System.Drawing.Size(($rowW - 160), 20)
        $lblD.ForeColor = $cMuted; $lblD.AutoEllipsis = $true; $lblD.Anchor = "Top, Left, Right"
        $tipText = [string]$t.Desc; if ($t.Warn) { $tipText += "`r`n`r`nAttention : " + $t.Warn }
        $tip.SetToolTip($lblD, $tipText)
        $row.Controls.Add($lblD)
        $lnk = New-Object System.Windows.Forms.Label
        $lnk.Text = "+ details"; $lnk.Location = New-Object System.Drawing.Point(($rowW - 140), $y); $lnk.Size = New-Object System.Drawing.Size(128, 20)
        $lnk.TextAlign = "MiddleRight"; $lnk.ForeColor = $cCyan; $lnk.Cursor = [System.Windows.Forms.Cursors]::Hand; $lnk.Anchor = "Top, Right"
        $row.Controls.Add($lnk)
        # Zone des details creee seulement au premier clic (une page s'affiche plus vite)
        $lnk.Tag = @{ Row = $row; Tech = $null; TechY = ($y + 22); T = $t; Open = $false; Base = 0 }
        $lnk.Add_Click({
            $s = $this.Tag
            if (-not $s.Tech) {
                $k = [math]::Max(1.0, [double]$Script:DpiScale)
                $tech = New-Object System.Windows.Forms.Label
                $tech.Location = New-Object System.Drawing.Point([int](12 * $k), [int]($s.TechY * $k)); $tech.Size = New-Object System.Drawing.Size(($s.Row.ClientSize.Width - [int](24 * $k)), [int](20 * $k))
                $tech.ForeColor = $cTerm; $tech.Font = $fontMono; $tech.Anchor = "Top, Left, Right"; $tech.Visible = $false
                $s.Row.Controls.Add($tech); $s.Tech = $tech
            }
            if (-not $s.Open) {
                $lines = @(Get-WinCfgTech $s.T)
                if ($s.T.Warn) { $lines = @("Attention : " + $s.T.Warn) + $lines }
                if ($lines.Count -eq 0) { $lines = @("Pas de detail technique pour ce reglage.") }
                $s.Tech.Text = ($lines -join "`r`n")
                $s.Base = $s.Row.Height
                $sz = [System.Windows.Forms.TextRenderer]::MeasureText($s.Tech.Text, $s.Tech.Font, (New-Object System.Drawing.Size($s.Tech.Width, 0)), [System.Windows.Forms.TextFormatFlags]::WordBreak)
                $h = [int]($sz.Height + 8)
                $s.Tech.Height = $h; $s.Tech.Visible = $true
                $s.Row.Height = $s.Base + $h + 4
                $this.Text = "- details"; $s.Open = $true
            } else {
                $s.Tech.Visible = $false; $s.Row.Height = $s.Base; $this.Text = "+ details"; $s.Open = $false
            }
        })
    }

    $onToggle = {
        param($sender, $e)
        if ($wc.Silent) { return }
        $t = $sender.Tag; $want = [bool]$sender.Checked
        if ($want -and $t.Warn) {
            if ([System.Windows.Forms.MessageBox]::Show(($t.Name + "`r`n`r`nAttention : " + $t.Warn + "`r`n`r`nActiver quand meme ?"), "GameBoost - Config Windows", "YesNo", "Warning") -ne "Yes") {
                $wc.Silent = $true; $sender.Checked = $false; $wc.Silent = $false; return
            }
        }
        & $ensureRp
        $msg = ""
        try {
            Set-WinCfgTweak $t $want
            $etat = "desactive"; if ($want) { $etat = "active" }
            Log ("Config Windows : " + $t.Name + " -> " + $etat)
        } catch { $msg = $_.Exception.Message; Log ("Config Windows : echec '" + $t.Name + "' : " + $msg) }
        $real = $want; try { $real = [bool](Get-WinCfgState $t) } catch {}
        if ($real -ne [bool]$sender.Checked) { $wc.Silent = $true; $sender.Checked = $real; $wc.Silent = $false }
        if ($msg) { & $setStatus ("Echec : " + $msg) $cRed; return }
        if ($real -ne $want) { & $setStatus "Windows a refuse ce changement (bloque par une strategie d'entreprise ou par ton edition de Windows)." $cYellow; return }
        if ($t.R) { $wc.Need[$t.R] = $true }
        & $updateStatus
    }
    $onChoice = {
        param($sender, $e)
        if ($wc.Silent) { return }
        $t = $sender.Tag; $i = [int]$sender.SelectedIndex
        if ($i -lt 0 -or $i -ge $t.Opts.Count) { return }
        $prev = -1; try { $prev = [int](Get-WinCfgChoice $t) } catch {}
        if ($i -eq $prev) { return }
        $revert = { $wc.Silent = $true; if ($prev -ge 0) { $sender.SelectedIndex = $prev } else { $sender.SelectedIndex = -1 }; $wc.Silent = $false }
        if ($t.Warns -and $t.Warns.ContainsKey($i)) {
            if ([System.Windows.Forms.MessageBox]::Show(($t.Name + " : " + $t.Opts[$i].L + "`r`n`r`nAttention : " + $t.Warns[$i] + "`r`n`r`nAppliquer quand meme ?"), "GameBoost - Config Windows", "YesNo", "Warning") -ne "Yes") { & $revert; return }
        }
        & $ensureRp
        try { Set-WinCfgChoice $t $i; Log ("Config Windows : " + $t.Name + " -> " + $t.Opts[$i].L) }
        catch { Log ("Config Windows : echec '" + $t.Name + "' : " + $_.Exception.Message); & $setStatus ("Echec : " + $_.Exception.Message) $cRed; & $revert; return }
        $real = -1; try { $real = [int](Get-WinCfgChoice $t) } catch {}
        if ($real -ne $i) { & $setStatus "Windows a refuse ce changement (strategie d'entreprise ou edition de Windows)." $cYellow; $wc.Silent = $true; $sender.SelectedIndex = $real; $wc.Silent = $false; return }
        if ($t.R) { $wc.Need[$t.R] = $true }
        & $updateStatus
    }

    $makeRow = {
        param($t)
        if ($t.Type -eq 'choice') {
            $row = & $newRowPanel 60
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $t.Name; $lbl.Location = New-Object System.Drawing.Point(12, 8); $lbl.Size = New-Object System.Drawing.Size(($rowW - 470), 22); $lbl.Font = $fontBold
            $lbl.ForeColor = $cText; $lbl.AutoEllipsis = $true; $lbl.Anchor = "Top, Left, Right"
            $row.Controls.Add($lbl)
            & $addBadge $row $t ($rowW - 456) 180
            $cb = New-GBComboCtl
            $cb.DropDownStyle = "DropDownList"; $cb.FlatStyle = "Flat"; $cb.BackColor = $cDeep; $cb.ForeColor = $cText; Set-GBDarkCombo $cb
            $cb.Location = New-Object System.Drawing.Point(($rowW - 268), 5); $cb.Size = New-Object System.Drawing.Size(256, 24); $cb.Anchor = "Top, Right"
            for ($oi = 0; $oi -lt $t.Opts.Count; $oi++) {
                $ol = [string]$t.Opts[$oi].L
                if ($null -ne $t.RecoIdx -and $oi -eq [int]$t.RecoIdx -and $ol -notmatch 'conseille') { $ol += "  (conseille)" }
                [void]$cb.Items.Add($ol)
            }
            $cur = -1; try { $cur = [int](Get-WinCfgChoice $t) } catch {}
            $wc.Silent = $true; $cb.SelectedIndex = $cur; $wc.Silent = $false
            if ($cur -lt 0) { $tip.SetToolTip($cb, "Reglage actuel : valeur personnalisee ou par defaut de Windows (aucune des options).") }
            $cb.Tag = $t
            $cb.add_SelectedIndexChanged($onChoice)
            $row.Controls.Add($cb)
            & $addDescTech $row $t 34
        } elseif ($t.Type -eq 'action') {
            $row = & $newRowPanel 60
            $lbl = New-Object System.Windows.Forms.Label
            $lbl.Text = $t.Name; $lbl.Location = New-Object System.Drawing.Point(12, 8); $lbl.Size = New-Object System.Drawing.Size(($rowW - 230), 22); $lbl.Font = $fontBold
            $lbl.ForeColor = $cText; $lbl.AutoEllipsis = $true; $lbl.Anchor = "Top, Left, Right"
            $row.Controls.Add($lbl)
            $b = New-GBButtonCtl; $b.Text = $t.Btn; $b.Location = New-Object System.Drawing.Point(($rowW - 172), 4); $b.Size = New-Object System.Drawing.Size(160, 26); $b.Anchor = "Top, Right"
            $b.Tag = $t
            $b.Add_Click({
                $t = $this.Tag
                if ($t.Confirm -and [System.Windows.Forms.MessageBox]::Show($t.Confirm, "GameBoost - Config Windows", "YesNo", "Question") -ne "Yes") { return }
                & $ensureRp
                $this.Enabled = $false
                try { $r = & $t.Do; Log ("Config Windows : " + $t.Name + " -> fait"); if ($r) { [System.Windows.Forms.MessageBox]::Show([string]$r, "GameBoost - Config Windows") | Out-Null } }
                catch { Log ("Config Windows : echec '" + $t.Name + "' : " + $_.Exception.Message); [System.Windows.Forms.MessageBox]::Show(("Echec : " + $_.Exception.Message), "GameBoost") | Out-Null }
                finally { $this.Enabled = $true }
                if ($t.R) { $wc.Need[$t.R] = $true }
                & $updateStatus
            })
            $row.Controls.Add($b)
            & $addDescTech $row $t 34
        } else {
            $row = & $newRowPanel 60
            $on = $false; try { $on = [bool](Get-WinCfgState $t) } catch {}
            $tg = New-GBToggleCtl $t.Name $on
            $tg.Location = New-Object System.Drawing.Point(10, 6); $tg.Size = New-Object System.Drawing.Size(($rowW - 210), 24); $tg.Font = $fontBold; $tg.Anchor = "Top, Left, Right"
            $tg.Tag = $t
            $tg.add_CheckedChanged($onToggle)
            $row.Controls.Add($tg)
            & $addBadge $row $t ($rowW - 196) 184
            & $addDescTech $row $t 34
        }
        Invoke-GBRowScale $row
        return $row
    }
    $makeHeader = {
        param($title, $desc, $note)
        $h = 30; if ($desc) { $h += 38 }; if ($note) { $h += 22 }
        $p = New-Object System.Windows.Forms.Panel
        $p.Size = New-Object System.Drawing.Size($rowW, $h); $p.Margin = New-Object System.Windows.Forms.Padding(0, 0, 0, 6); $p.BackColor = $cBg
        $l = New-Object System.Windows.Forms.Label; $l.Text = $title; $l.Font = $fontHud; $l.ForeColor = $cViolet
        $l.Location = New-Object System.Drawing.Point(0, 2); $l.Size = New-Object System.Drawing.Size($rowW, 24); $l.Anchor = "Top, Left, Right"; $p.Controls.Add($l)
        $y = 28
        if ($desc) {
            $l2 = New-Object System.Windows.Forms.Label; $l2.Text = $desc; $l2.ForeColor = $cMuted
            $l2.Location = New-Object System.Drawing.Point(0, $y); $l2.Size = New-Object System.Drawing.Size($rowW, 36); $l2.Anchor = "Top, Left, Right"; $p.Controls.Add($l2); $y += 38
        }
        if ($note) {
            $l3 = New-Object System.Windows.Forms.Label; $l3.Text = $note; $l3.ForeColor = $cTerm
            $l3.Location = New-Object System.Drawing.Point(0, $y); $l3.Size = New-Object System.Drawing.Size($rowW, 20); $l3.Anchor = "Top, Left, Right"; $p.Controls.Add($l3)
        }
        Invoke-GBRowScale $p
        return $p
    }
    $makeGroup = {
        param($text)
        if ($Script:UiOK) { $g = New-Object GBHeader; $g.Text = $text; $g.Hint = ""; $g.HintFont = $fontUI; $g.Font = $fontHud }
        else { $g = New-Object System.Windows.Forms.Label; $g.Text = $text; $g.Font = $fontBold; $g.ForeColor = $cCyan }
        $g.Size = New-Object System.Drawing.Size($rowW, 22); $g.Margin = New-Object System.Windows.Forms.Padding(0, 8, 0, 4)
        Invoke-GBRowScale $g
        return $g
    }
    $fitRows = {
        $w = $flow.Width - [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth - [int](12 * [math]::Max(1.0, [double]$Script:DpiScale))
        foreach ($c in @($flow.Controls)) { if ($c.Width -ne $w) { $c.Width = $w } }
    }
    $flow.Add_SizeChanged({ $flow.SuspendLayout(); & $fitRows; $flow.ResumeLayout() })
    # Pages de reglages deja construites : gardees de cote (pas detruites) pour reapparaitre instantanement
    $wc.PageCache = @{}; $wc.FlowKey = $null
    $clearFlow = {
        $flow.SuspendLayout()
        $keep = $wc.FlowKey; $wc.FlowKey = $null
        $ctls = @($flow.Controls)
        if ($keep) { $flow.Controls.Clear(); $wc.PageCache[$keep] = $ctls }
        else { foreach ($c in $ctls) { $flow.Controls.Remove($c); $c.Dispose() } }
    }
    # Page reprise du cache : interrupteurs et listes remis sur l'etat reel de Windows (il a pu changer)
    $resyncRows = {
        param($ctls)
        $wc.Silent = $true
        try {
            foreach ($row in $ctls) {
                foreach ($c in $row.Controls) {
                    $t = $c.Tag
                    if (-not ($t -is [hashtable]) -or -not $t.Id -or $t.Type -eq 'action') { continue }
                    try {
                        if ($c -is [System.Windows.Forms.ComboBox]) { $v = [int](Get-WinCfgChoice $t); if ($c.SelectedIndex -ne $v) { $c.SelectedIndex = $v } }
                        elseif ($c -is [System.Windows.Forms.CheckBox]) { $v = [bool](Get-WinCfgState $t); if ($c.Checked -ne $v) { $c.Checked = $v } }
                    } catch {}
                }
            }
        } finally { $wc.Silent = $false }
    }
    $clearPanel = { foreach ($c in @($panel.Controls)) { $panel.Controls.Remove($c); $c.Dispose() } }
    $addTweakRows = {
        param($items)
        $grp = $null
        foreach ($t in $items) {
            if (-not (Test-WinCfgVisible $t)) { continue }
            if ($t.Group -and $t.Group -ne $grp) { $grp = $t.Group; $flow.Controls.Add((& $makeGroup $grp)) }
            $flow.Controls.Add((& $makeRow $t))
        }
    }
    $persistNote = "Applique une fois : GameBoost ne reapplique rien en arriere-plan si tu changes d'avis dans Windows."

    # ====================== Page : reglages (generique) ======================
    $renderTweaks = {
        param($pg)
        & $addTweakRows @($Script:WinTweaks | Where-Object { $_.Page -eq $pg.K })
    }

    # ====================== Page : alimentation ======================
    $powerAdv = @(
        @{ L = 'Mode de boost du processeur'; Sub = 'SUB_PROCESSOR'; S = 'PERFBOOSTMODE'; Opts = @('Desactive', 'Active', 'Agressif', 'Efficace active', 'Efficace agressif', 'Agressif garanti', 'Efficace agressif garanti') },
        @{ L = 'Etat minimal du processeur (%)'; Sub = 'SUB_PROCESSOR'; S = 'PROCTHROTTLEMIN'; Min = 0; Max = 100 },
        @{ L = 'Etat maximal du processeur (%)'; Sub = 'SUB_PROCESSOR'; S = 'PROCTHROTTLEMAX'; Min = 0; Max = 100 },
        @{ L = 'Coeurs actifs minimum - parking (%)'; Sub = 'SUB_PROCESSOR'; S = 'CPMINCORES'; Min = 0; Max = 100 },
        @{ L = 'Preference energie / perf. (EPP, 0 = perf.)'; Sub = 'SUB_PROCESSOR'; S = 'PERFEPP'; Min = 0; Max = 100 },
        @{ L = 'Suspension selective USB'; Sub = '2a737441-1930-4402-8d77-b2bebba308a3'; S = '48e6b7a6-50f5-4782-a5d4-53bb8f07e226'; Opts = @('Desactivee', 'Activee') },
        @{ L = 'Economie d energie PCI Express'; Sub = 'SUB_PCIEXPRESS'; S = 'ASPM'; Opts = @('Desactivee', 'Moderee', 'Maximale') },
        @{ L = 'Carte sans fil (Wi-Fi)'; Sub = '19cbb8fa-5279-450e-9fac-8a3d5fedd0c1'; S = '12bbebe6-58d6-4636-95bb-3217ef867c1a'; Opts = @('Performances max', 'Economie faible', 'Economie moyenne', 'Economie max') },
        @{ L = "Eteindre l'ecran apres (min, 0 = jamais)"; Sub = 'SUB_VIDEO'; S = 'VIDEOIDLE'; Min = 0; Max = 999; Scale = 60 },
        @{ L = 'Mise en veille apres (min, 0 = jamais)'; Sub = 'SUB_SLEEP'; S = 'STANDBYIDLE'; Min = 0; Max = 999; Scale = 60 },
        @{ L = 'Arreter le disque dur apres (min, 0 = jamais)'; Sub = 'SUB_DISK'; S = 'DISKIDLE'; Min = 0; Max = 999; Scale = 60 }
    )
    $renderPower = {
        param($pg)
        $plans = @(Get-GBPowerPlans)
        $flow.Controls.Add((& $makeGroup "Plans d'alimentation"))
        foreach ($pl in $plans) {
            $row = & $newRowPanel 40
            $l = New-Object System.Windows.Forms.Label; $l.Text = $pl.Name; $l.Font = $fontBold; $l.ForeColor = $cText
            if ($pl.Active) { $l.Text += "   (actif)"; $l.ForeColor = $cGreen }
            $l.Location = New-Object System.Drawing.Point(12, 10); $l.Size = New-Object System.Drawing.Size(($rowW - 300), 22); $l.AutoEllipsis = $true; $l.Anchor = "Top, Left, Right"
            $row.Controls.Add($l)
            $ba = New-GBButtonCtl; $ba.Text = "Activer"; $ba.Location = New-Object System.Drawing.Point(($rowW - 276), 6); $ba.Size = New-Object System.Drawing.Size(120, 26); $ba.Anchor = "Top, Right"
            $ba.Enabled = -not $pl.Active; $ba.Tag = $pl
            $ba.Add_Click({ $p = $this.Tag; powercfg /setactive $p.Guid 2>$null | Out-Null; Log ("Config Windows : plan d'alimentation actif -> " + $p.Name); & $render })
            $row.Controls.Add($ba)
            $bd = New-GBButtonCtl; $bd.Text = "Supprimer"; $bd.ForeColor = $cRed; $bd.Location = New-Object System.Drawing.Point(($rowW - 148), 6); $bd.Size = New-Object System.Drawing.Size(136, 26); $bd.Anchor = "Top, Right"
            $bd.Enabled = -not $pl.Active; $bd.Tag = $pl
            $bd.Add_Click({
                $p = $this.Tag
                if ([System.Windows.Forms.MessageBox]::Show(("Supprimer le plan '" + $p.Name + "' ?`r`n`r`nLes plans Windows de base peuvent etre restaures avec le bouton 'Restaurer les plans Windows'."), "GameBoost", "YesNo", "Question") -ne "Yes") { return }
                $out = (powercfg /delete $p.Guid 2>&1) -join ' '
                if ($LASTEXITCODE -ne 0) { [System.Windows.Forms.MessageBox]::Show(("Windows a refuse : " + $out), "GameBoost") | Out-Null } else { Log ("Config Windows : plan supprime -> " + $p.Name) }
                & $render
            })
            $row.Controls.Add($bd)
            Invoke-GBRowScale $row
            $flow.Controls.Add($row)
        }
        $row = & $newRowPanel 40
        $b1 = New-GBButtonCtl; $b1.Text = "Ajouter 'Performances optimales'"; $b1.ForeColor = $cGreen; $b1.Location = New-Object System.Drawing.Point(10, 6); $b1.Size = New-Object System.Drawing.Size(250, 26)
        # Deja ajoute (nom retenu lors du premier ajout) : pas de 2e copie
        $ultName = [string]$Script:Config.UltimateName
        if ($ultName -and @($plans | Where-Object { $_.Name -eq $ultName }).Count -gt 0) { $b1.Text = "'" + $ultName + "' deja ajoute"; $b1.Enabled = $false }
        $b1.Add_Click({
            $before = @(Get-GBPowerPlans)
            $out = (powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61 2>&1) -join ' '
            $new = @(Get-GBPowerPlans | Where-Object { $g = $_.Guid; -not (@($before | Where-Object { $_.Guid -eq $g }).Count) }) | Select-Object -First 1
            if (-not $new) { & $setStatus ("Windows a refuse de creer le plan : " + $out) $cYellow; & $render; return }
            $Script:Config.UltimateName = $new.Name; Save-Config
            $same = @($before | Where-Object { $_.Name -eq $new.Name })
            if ($same.Count -gt 0) {
                # Il existait deja : on retire la copie qui vient d'etre creee
                powercfg /delete $new.Guid 2>$null | Out-Null
                & $setStatus ("Le plan '" + $new.Name + "' existe deja : clique 'Activer' sur sa ligne.") $cYellow
            } else {
                Log ("Config Windows : plan '" + $new.Name + "' ajoute")
                & $setStatus ("Plan '" + $new.Name + "' ajoute : clique 'Activer' pour l'utiliser. Il consomme plus et chauffe plus.") $cGreen
            }
            & $render
        })
        $row.Controls.Add($b1)
        # Plans en double (meme nom) : bouton pour garder un seul exemplaire
        $dups = New-Object System.Collections.ArrayList
        foreach ($grp in @($plans | Group-Object Name | Where-Object { $_.Count -gt 1 })) {
            $keep = @($grp.Group | Where-Object { $_.Active }) | Select-Object -First 1
            if (-not $keep) { $keep = $grp.Group[0] }
            foreach ($pl in $grp.Group) { if ($pl.Guid -ne $keep.Guid -and -not $pl.Active) { [void]$dups.Add($pl) } }
        }
        if ($dups.Count -gt 0) {
            $b3 = New-GBButtonCtl; $b3.Text = "Supprimer les doublons (" + $dups.Count + ")"; $b3.ForeColor = $cYellow
            $b3.Location = New-Object System.Drawing.Point(496, 6); $b3.Size = New-Object System.Drawing.Size(220, 26); $b3.Tag = $dups.ToArray()
            $b3.Add_Click({
                $list = @($this.Tag)
                $q = "Supprimer " + $list.Count + " plan(s) en double ?`r`n`r`n- " + (@($list | ForEach-Object { $_.Name + "  (" + $_.Guid + ")" }) -join "`r`n- ") + "`r`n`r`nUn exemplaire de chaque plan est garde (celui qui est actif s'il y en a un)."
                if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Question") -ne "Yes") { return }
                $n = 0; foreach ($pl in $list) { powercfg /delete $pl.Guid 2>$null | Out-Null; if ($LASTEXITCODE -eq 0) { $n++ } }
                Log ("Config Windows : " + $n + " plan(s) d'alimentation en double supprime(s)")
                & $setStatus ("" + $n + " plan(s) en double supprime(s).") $cGreen
                & $render
            })
            $row.Controls.Add($b3)
        }
        $b2 = New-GBButtonCtl; $b2.Text = "Restaurer les plans Windows"; $b2.Location = New-Object System.Drawing.Point(268, 6); $b2.Size = New-Object System.Drawing.Size(220, 26)
        $b2.Add_Click({
            $q = "Remettre les plans d'alimentation de Windows par defaut ?`r`n`r`nATTENTION : Windows supprime alors TOUS les plans personnalises (y compris celui de GameBoost, recree au prochain boost) et remet les reglages de base."
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Warning") -ne "Yes") { return }
            powercfg -restoredefaultschemes 2>$null | Out-Null
            Log "Config Windows : plans d'alimentation Windows restaures"
            & $render
        })
        $row.Controls.Add($b2)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)

        & $addTweakRows @($Script:WinTweaks | Where-Object { $_.Page -eq 'power' })

        # Reglages caches du plan actif (verrouilles par defaut)
        $flow.Controls.Add((& $makeGroup "Reglages avances du plan actif"))
        $act = Get-ActiveScheme
        if (-not $wc.PowerUnlocked) {
            $row = & $newRowPanel 64
            $l = New-Object System.Windows.Forms.Label
            $l.Text = "Boost du processeur, parking des coeurs, preference energie/performances, USB, PCI Express, Wi-Fi, mise en veille. Des valeurs extremes peuvent faire chauffer le PC ou le rendre instable."
            $l.ForeColor = $cMuted; $l.Location = New-Object System.Drawing.Point(12, 6); $l.Size = New-Object System.Drawing.Size(($rowW - 230), 50); $l.Anchor = "Top, Left, Right"
            $row.Controls.Add($l)
            $bu = New-GBButtonCtl; $bu.Text = "Deverrouiller"; $bu.ForeColor = $cYellow; $bu.Location = New-Object System.Drawing.Point(($rowW - 192), 16); $bu.Size = New-Object System.Drawing.Size(180, 28); $bu.Anchor = "Top, Right"
            $bu.Add_Click({
                $q = "Ces reglages sont caches par Windows parce qu'une valeur incorrecte peut faire chauffer le PC, vider la batterie ou le rendre instable.`r`n`r`nLes valeurs d'origine sont gardees pour 'Tout annuler'. Continuer ?"
                if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Reglages avances", "YesNo", "Warning") -ne "Yes") { return }
                $wc.PowerUnlocked = $true; & $render
            })
            $row.Controls.Add($bu)
            Invoke-GBRowScale $row
            $flow.Controls.Add($row)
            return
        }
        if (-not $act) { $flow.Controls.Add((& $makeHeader "Plan actif introuvable" "" "")); return }
        $hasDc = [bool]$Script:IsLaptop
        $hdr = & $newRowPanel 26; $hdr.BackColor = $cBg
        $h1 = New-Object System.Windows.Forms.Label; $h1.Text = "Sur secteur"; $h1.ForeColor = $cCyan; $h1.Location = New-Object System.Drawing.Point(($rowW - 360), 4); $h1.Size = New-Object System.Drawing.Size(170, 20); $h1.Anchor = "Top, Right"; $hdr.Controls.Add($h1)
        if ($hasDc) { $h2 = New-Object System.Windows.Forms.Label; $h2.Text = "Sur batterie"; $h2.ForeColor = $cCyan; $h2.Location = New-Object System.Drawing.Point(($rowW - 182), 4); $h2.Size = New-Object System.Drawing.Size(170, 20); $h2.Anchor = "Top, Right"; $hdr.Controls.Add($h2) }
        Invoke-GBRowScale $hdr; $flow.Controls.Add($hdr)
        $wc.PowerCtl = New-Object System.Collections.ArrayList
        foreach ($s in $powerAdv) {
            $v = Get-GBPowerValue $act $s.Sub $s.S
            if (-not $v) { continue }
            $row = & $newRowPanel 36
            $l = New-Object System.Windows.Forms.Label; $l.Text = $s.L; $l.ForeColor = $cText
            $l.Location = New-Object System.Drawing.Point(12, 8); $l.Size = New-Object System.Drawing.Size(($rowW - 380), 22); $l.AutoEllipsis = $true; $l.Anchor = "Top, Left, Right"
            $row.Controls.Add($l)
            $ctls = @()
            foreach ($side in @('AC', 'DC')) {
                if ($side -eq 'DC' -and -not $hasDc) { continue }
                $x = $rowW - 360; if ($side -eq 'DC') { $x = $rowW - 182 }
                $val = [int]$v[$side]
                if ($s.Opts) {
                    $c = New-GBComboCtl; $c.DropDownStyle = "DropDownList"; $c.FlatStyle = "Flat"; $c.BackColor = $cDeep; $c.ForeColor = $cText; Set-GBDarkCombo $c
                    foreach ($o in $s.Opts) { [void]$c.Items.Add($o) }
                    if ($val -ge 0 -and $val -lt $s.Opts.Count) { $c.SelectedIndex = $val }
                } else {
                    $c = New-Object System.Windows.Forms.NumericUpDown; $c.BackColor = $cDeep; $c.ForeColor = $cText; $c.BorderStyle = "FixedSingle"
                    $sc = 1; if ($s.Scale) { $sc = [int]$s.Scale }
                    $c.Minimum = $s.Min; $c.Maximum = $s.Max; $c.Value = [math]::Min([decimal]$s.Max, [math]::Max([decimal]$s.Min, [decimal][math]::Round($val / $sc)))
                }
                $c.Location = New-Object System.Drawing.Point($x, 5); $c.Size = New-Object System.Drawing.Size(170, 24); $c.Anchor = "Top, Right"
                $row.Controls.Add($c); $ctls += $c
            }
            [void]$wc.PowerCtl.Add(@{ S = $s; Ctl = $ctls; Old = $v })
            Invoke-GBRowScale $row
            $flow.Controls.Add($row)
        }
        $row = & $newRowPanel 40; $row.BackColor = $cBg
        $bap = New-GBButtonCtl; $bap.Text = "Appliquer ces valeurs"; $bap.ForeColor = $cGreen; $bap.Location = New-Object System.Drawing.Point(0, 6); $bap.Size = New-Object System.Drawing.Size(220, 28)
        $bap.Add_Click({
            & $ensureRp
            $act = Get-ActiveScheme; $n = 0; $fail = @()
            foreach ($pc in $wc.PowerCtl) {
                $s = $pc.S; $vals = @()
                foreach ($c in $pc.Ctl) {
                    if ($s.Opts) { $vals += [int]$c.SelectedIndex } else { $sc = 1; if ($s.Scale) { $sc = [int]$s.Scale }; $vals += ([int]$c.Value * $sc) }
                }
                $ac = $vals[0]; $dc = [int]$pc.Old.DC; if ($vals.Count -gt 1) { $dc = $vals[1] }
                if ($ac -lt 0) { continue }
                if ($ac -eq [int]$pc.Old.AC -and $dc -eq [int]$pc.Old.DC) { continue }
                try { Set-GBPowerValue $act $s.Sub $s.S $ac $dc; $n++ } catch { $fail += $s.L }
            }
            Log ("Config Windows : " + $n + " reglage(s) avance(s) d'alimentation applique(s)")
            & $render
            if ($fail.Count -gt 0) { & $setStatus ("Non appliques : " + ($fail -join ", ")) $cYellow } else { & $setStatus ("" + $n + " valeur(s) appliquee(s) au plan actif.") $cGreen }
        })
        $row.Controls.Add($bap)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
    }

    # ====================== Page : outils avances ======================
    # ====================== Page : programmes au demarrage ======================
    $renderStartup = {
        param($pg)
        $null = & $mkPanelLbl ("Comme le Gestionnaire des taches > Demarrage : rien n'est supprime, un programme desactive ne se lance simplement plus avec Windows " +
                               "(tu peux le reactiver a tout moment). Coche puis choisis l'action.") 0 0 780 40 $cMuted "Top, Left, Right"
        $lv = & $mkList @(@('Etat', 110), @('Programme', 230), @('Commande', 360), @('Emplacement', 200)) ([int](44 * $sc)) ([int](90 * $sc))
        $wc.Su = @{ Lv = $lv }
        $wc.Su.Fill = {
            $lv = $wc.Su.Lv; $items = @(Get-GBStartupItems)
            $lv.BeginUpdate(); $lv.Items.Clear()
            foreach ($it in $items) {
                $st = "* Actif"; $col = $cText; if (-not $it.Enabled) { $st = "o Desactive"; $col = $cMuted }
                $li = New-Object System.Windows.Forms.ListViewItem($st)
                [void]$li.SubItems.Add($it.Name); [void]$li.SubItems.Add($it.Cmd); [void]$li.SubItems.Add($it.Where)
                $li.ForeColor = $col; $li.Tag = $it
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
            $on = @($items | Where-Object { $_.Enabled }).Count
            & $setStatus ("" + $items.Count + " programme(s) au demarrage, dont " + $on + " actif(s).") $cMuted
        }
        $bOff = & $mkPanelBtn "Desactiver la selection" 0 82 200 $cYellow
        $bOn = & $mkPanelBtn "Reactiver la selection" 208 82 200 $cGreen
        $bLoc = & $mkPanelBtn "Ouvrir l'emplacement" 416 82 170 $null
        $bRef = & $mkPanelBtn "Actualiser" 594 82 120 $null
        $null = & $mkPanelLbl ("Ne desactive pas ton antivirus ni les utilitaires de ta carte son / pave tactile si tu t'en sers. Pour enlever un programme pour de bon : " +
                               "Desinstallation profonde (fenetre principale).") 0 ($panel.ClientSize.Height - [int](46 * $sc)) 780 44 $cMuted "Bottom, Left, Right"
        $wc.Su.Set = {
            param([bool]$enable)
            $sel = @($wc.Su.Lv.CheckedItems | ForEach-Object { $_.Tag } | Where-Object { $_.Enabled -ne $enable })
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un programme a changer.", "GameBoost") | Out-Null; return }
            if (-not $enable) {
                $av = @($sel | Where-Object { $_.Name -match 'SecurityHealth|Defender' })
                if ($av.Count -gt 0) { $sel = @($sel | Where-Object { $_.Name -notmatch 'SecurityHealth|Defender' }); [System.Windows.Forms.MessageBox]::Show("L'icone de securite Windows (antivirus) est laissee active.", "GameBoost") | Out-Null }
                if ($sel.Count -eq 0) { return }
            }
            $fail = @()
            foreach ($it in $sel) { try { Set-GBStartupEnabled $it.Hive $it.Appr $it.Name $enable } catch { $fail += ($it.Name + " : " + $_.Exception.Message) } }
            $verb = "desactive(s)"; if ($enable) { $verb = "reactive(s)" }
            Log ("Demarrage de Windows : " + ($sel.Count - $fail.Count) + " programme(s) " + $verb + " -> " + (@($sel | ForEach-Object { $_.Name }) -join ", "))
            & $wc.Su.Fill
            if ($fail.Count -gt 0) { [System.Windows.Forms.MessageBox]::Show(("Non modifies :`r`n" + ($fail -join "`r`n")), "GameBoost") | Out-Null }
            else { & $setStatus ("" + $sel.Count + " programme(s) " + $verb + ". Effet au prochain demarrage de Windows.") $cGreen }
        }
        $bOff.Add_Click({ & $wc.Su.Set $false })
        $bOn.Add_Click({ & $wc.Su.Set $true })
        $bRef.Add_Click({ & $wc.Su.Fill })
        $bLoc.Add_Click({
            $it = @(@($wc.Su.Lv.SelectedItems) + @($wc.Su.Lv.CheckedItems) | ForEach-Object { $_.Tag }) | Select-Object -First 1
            if (-not $it) { return }
            if ($it.File -and (Test-GBPathExists $it.File)) { Start-Process explorer.exe ('/select,"' + $it.File + '"') }
            else { [System.Windows.Forms.MessageBox]::Show(("Fichier introuvable :`r`n" + $it.Cmd + "`r`n`r`n(le programme a peut-etre ete desinstalle : tu peux desactiver cette entree)."), "GameBoost") | Out-Null }
        })
        & $wc.Su.Fill
    }

    # ====================== Page : nettoyage ======================
    $renderClean = {
        param($pg)
        $null = & $mkPanelLbl ("Supprime des fichiers que Windows et les jeux recreent tout seuls. Les fichiers utilises en ce moment sont gardes. " +
                               "Rien dans tes documents, tes jeux ou tes sauvegardes n'est touche.") 0 0 480 40 $cMuted "Top, Left, Right"
        $chkWeekly = New-GBToggleCtl "Nettoyage automatique chaque semaine" ([bool](Get-GBWeeklyCleanTask))
        $chkWeekly.Size = New-Object System.Drawing.Size([int](300 * $sc), [int](24 * $sc)); $chkWeekly.Location = New-Object System.Drawing.Point(($panel.ClientSize.Width - [int](300 * $sc)), [int](8 * $sc)); $chkWeekly.Anchor = "Top, Right"
        $tip.SetToolTip($chkWeekly, "Tache visible \GameBoost\NettoyageHebdo : le dimanche (ou au prochain demarrage), vide les elements conseilles (temporaires, Windows Update, rapports d'erreurs). Jamais la Corbeille ni les caches de shaders.")
        $chkWeekly.Add_CheckedChanged({
            if ($wc.Silent) { return }
            try { Set-GBWeeklyClean ([bool]$this.Checked); $m = "desactive"; if ($this.Checked) { $m = "active (chaque dimanche)" }; Log ("Nettoyage automatique " + $m); & $setStatus ("Nettoyage automatique " + $m + ".") $cGreen }
            catch { [System.Windows.Forms.MessageBox]::Show(("Impossible : " + $_.Exception.Message), "GameBoost") | Out-Null; $wc.Silent = $true; $this.Checked = [bool](Get-GBWeeklyCleanTask); $wc.Silent = $false }
        })
        $panel.Controls.Add($chkWeekly)
        $lv = & $mkList @(@('Element', 300), @('Taille', 110), @('Remarque', 470)) ([int](44 * $sc)) ([int](90 * $sc))
        $wc.Clean.Lv = $lv
        $wc.Clean.LblTot = & $mkPanelLbl "" 0 ($panel.ClientSize.Height - [int](46 * $sc)) 780 22 $cText "Bottom, Left, Right"
        $null = & $mkPanelLbl "Vert = conseille. Les caches de shaders sont a vider seulement si un jeu saccade ou plante apres une mise a jour de pilote." 0 ($panel.ClientSize.Height - [int](24 * $sc)) 780 22 $cMuted "Bottom, Left, Right"
        $wc.Clean.Total = {
            $tot = [int64]0; $n = 0
            foreach ($li in $wc.Clean.Lv.CheckedItems) { $n++; if ($wc.Clean.Sizes) { $tot += [int64]$wc.Clean.Sizes[$li.Tag.Id] } }
            if ($wc.Clean.Sizes) { $wc.Clean.LblTot.Text = "" + $n + " element(s) coche(s) : " + (Format-GBSize $tot) + " a liberer" } else { $wc.Clean.LblTot.Text = "Calcul des tailles en cours..." }
        }
        $wc.Clean.Fill = {
            $lv = $wc.Clean.Lv; $lv.BeginUpdate(); $lv.Items.Clear()
            foreach ($t in $Script:CleanTargets) {
                $li = New-Object System.Windows.Forms.ListViewItem($t.L)
                $sz = "..."; if ($wc.Clean.Sizes) { $sz = Format-GBSize ([int64]$wc.Clean.Sizes[$t.Id]) }
                [void]$li.SubItems.Add($sz); [void]$li.SubItems.Add($t.N)
                $li.ForeColor = $cText; if ($t.Reco) { $li.ForeColor = $cGreen }
                $li.Checked = [bool]$t.Reco; $li.Tag = $t
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
            & $wc.Clean.Total
        }
        $lv.Add_ItemChecked({ if ($wc.Clean.Total) { & $wc.Clean.Total } })
        $bReco = & $mkPanelBtn "Cocher les conseilles" 0 82 180 $null
        $bNone = & $mkPanelBtn "Tout decocher" 188 82 130 $null
        $bGo = & $mkPanelBtn "Nettoyer la selection" 326 82 200 $cRed
        $bScan = & $mkPanelBtn "Recalculer" 534 82 130 $null
        $bReco.Add_Click({ foreach ($li in $wc.Clean.Lv.Items) { $li.Checked = [bool]$li.Tag.Reco } })
        $bNone.Add_Click({ foreach ($li in $wc.Clean.Lv.Items) { $li.Checked = $false } })
        $scan = {
            if ($wc.Task) { return }
            $wc.Clean.Sizes = $null; & $wc.Clean.Fill
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Status = "Analyse..."; Sizes = $null })
            $wc.Mode = 'cleanscan'; $wc.Task = Start-BackgroundTask $Script:CleanScript $wc.Sync @{ Op = 'scan'; Targets = $Script:CleanTargets }; $poll.Start()
        }
        $bScan.Add_Click($scan)
        $bGo.Add_Click({
            if ($wc.Task) { return }
            $sel = @($wc.Clean.Lv.CheckedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un element.", "GameBoost") | Out-Null; return }
            $tot = [int64]0; if ($wc.Clean.Sizes) { foreach ($t in $sel) { $tot += [int64]$wc.Clean.Sizes[$t.Id] } }
            $q = "Nettoyer " + $sel.Count + " element(s)" + $(if ($wc.Clean.Sizes) { " (" + (Format-GBSize $tot) + ")" } else { "" }) + " ?`r`n`r`n- " + (@($sel | ForEach-Object { $_.L }) -join "`r`n- ")
            if (@($sel | Where-Object { $_.Recycle }).Count -gt 0) { $q += "`r`n`r`nAttention : les fichiers de la Corbeille ne pourront plus etre recuperes." }
            if (@($sel | Where-Object { $_.Id -like '*cache' -and $_.Id -ne 'wucache' -and $_.Id -ne 'docache' }).Count -gt 0) { $q += "`r`n`r`nCaches de shaders : le prochain lancement de tes jeux sera un peu plus long (ils les recompilent)." }
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Nettoyage", "YesNo", "Question") -ne "Yes") { return }
            Log ("Nettoyage : " + (@($sel | ForEach-Object { $_.L }) -join ", "))
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Status = "Nettoyage..."; Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
            $wc.Mode = 'cleanrun'; $panel.Enabled = $false; $nav.Enabled = $false
            $wc.Task = Start-BackgroundTask $Script:CleanScript $wc.Sync @{ Op = 'clean'; Targets = $sel }; $poll.Start()
        })
        & $wc.Clean.Fill
        if (-not $wc.Clean.Sizes) { & $scan }
    }

    # ====================== Page : mises a jour des logiciels ======================
    $renderUpdates = {
        param($pg)
        if (-not $wc.Wg.Path) { $wc.Wg.Path = Find-GBWinget }
        if (-not $wc.Wg.Path) {
            $null = & $mkPanelLbl "WinGet (Gestionnaire de paquets Windows) n'est pas installe : installe 'Programme d'installation d'application' depuis le Microsoft Store (page Logiciels externes)." 0 0 760 60 $cYellow "Top, Left, Right"
            return
        }
        $null = & $mkPanelLbl ("Logiciels installes sur ce PC qui ont une version plus recente (reconnus par WinGet, l'outil officiel de Microsoft). " +
                               "La mise a jour se fait en arriere-plan, depuis la source officielle de l'editeur.") 0 0 780 40 $cMuted "Top, Left, Right"
        $lv = & $mkList @(@('Logiciel', 300), @('Version actuelle', 150), @('Nouvelle version', 150), @('Identifiant', 260)) ([int](44 * $sc)) ([int](90 * $sc))
        if (-not $wc.Up) { $wc.Up = @{ Items = $null; State = @{} } }
        $wc.Up.Lv = $lv
        $wc.Up.Fill = {
            $lv = $wc.Up.Lv; $lv.BeginUpdate(); $lv.Items.Clear()
            foreach ($u in @($wc.Up.Items)) {
                if (-not $u) { continue }
                $li = New-Object System.Windows.Forms.ListViewItem($u.Name)
                [void]$li.SubItems.Add($u.Ver); [void]$li.SubItems.Add($u.New); [void]$li.SubItems.Add($u.Id)
                $li.ForeColor = $cText; if ($wc.Up.State.ContainsKey($u.Id)) { $li.SubItems[2].Text = $wc.Up.State[$u.Id]; $li.ForeColor = $cYellow } elseif ($u.Cut) { $li.ForeColor = $cMuted }
                $li.Checked = (-not $u.Cut); $li.Tag = $u
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
            if ($null -eq $wc.Up.Items) { & $setStatus "Recherche des mises a jour (10 a 40 s)..." $cText }
            elseif (@($wc.Up.Items).Count -eq 0) { & $setStatus "Tous tes logiciels reconnus par WinGet sont a jour." $cGreen }
            else { & $setStatus ("" + @($wc.Up.Items).Count + " mise(s) a jour disponible(s).") $cYellow }
        }
        $bUp = & $mkPanelBtn "Mettre a jour la selection" 0 82 220 $cGreen
        $bAll = & $mkPanelBtn "Tout mettre a jour" 228 82 180 $null
        $bRef = & $mkPanelBtn "Rechercher a nouveau" 416 82 180 $null
        $null = & $mkPanelLbl ("Ferme les logiciels a mettre a jour avant (sinon WinGet peut echouer). Les jeux se mettent a jour par leur launcher (Steam, Epic...). " +
                               "Les pilotes : bouton 'Mises a jour pilotes'.") 0 ($panel.ClientSize.Height - [int](46 * $sc)) 780 44 $cMuted "Bottom, Left, Right"
        $wc.Up.Scan = {
            if ($wc.Task) { return }
            $wc.Up.Items = $null; $wc.Up.State = @{}; & $wc.Up.Fill
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Items = $null; Modern = (Get-GBWingetModern $wc.Wg.Path) })
            $wc.Mode = 'upscan'; $wc.Task = Start-BackgroundTask $Script:WingetUpgradeScanScript $wc.Sync $wc.Wg.Path; $poll.Start()
        }
        $wc.Up.Run = {
            param([bool]$all)
            if ($wc.Task) { return }
            $ids = @()
            if ($all) { $ids = @('*') } else { $ids = @($wc.Up.Lv.CheckedItems | ForEach-Object { $_.Tag } | Where-Object { -not $_.Cut } | ForEach-Object { $_.Id }) }
            if ($ids.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un logiciel (les identifiants tronques '...' se mettent a jour avec 'Tout mettre a jour').", "GameBoost") | Out-Null; return }
            $what = "tous les logiciels"; if (-not $all) { $what = "" + $ids.Count + " logiciel(s)" }
            if ([System.Windows.Forms.MessageBox]::Show(("Mettre a jour " + $what + " ?`r`n`r`nFerme-les avant si possible. Tu acceptes les conditions d'utilisation de leurs editeurs."), "GameBoost - Mises a jour", "YesNo", "Question") -ne "Yes") { return }
            foreach ($i in $ids) { if ($i -ne '*') { $wc.Up.State[$i] = "en attente..." } }
            & $wc.Up.Fill
            Log ("Mises a jour des logiciels : " + ($ids -join ", "))
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Current = $null; Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
            $wc.Mode = 'uprun'; $nav.Enabled = $false
            & $setStatus "Mise a jour en cours (peut prendre plusieurs minutes)..." $cYellow
            $wc.Task = Start-BackgroundTask $Script:WingetUpgradeRunScript $wc.Sync @{ Ids = $ids; Wg = $wc.Wg.Path; Modern = (Get-GBWingetModern $wc.Wg.Path) }; $poll.Start()
        }
        $bUp.Add_Click({ & $wc.Up.Run $false })
        $bAll.Add_Click({ & $wc.Up.Run $true })
        $bRef.Add_Click({ & $wc.Up.Scan })
        & $wc.Up.Fill
        if ($null -eq $wc.Up.Items) { & $wc.Up.Scan }
    }

    # ====================== Page : sante du PC ======================
    $healthRow = {
        param($title, $text, $color, $btn)
        $lines = @(([string]$text) -split "`n")
        # Hauteur selon le texte reel (les longues lignes passent a la ligne)
        $sz = [System.Windows.Forms.TextRenderer]::MeasureText(($lines -join "`r`n"), $fontUI, (New-Object System.Drawing.Size([int](($rowW - 240) * [math]::Max(1.0, [double]$Script:DpiScale)), 0)), [System.Windows.Forms.TextFormatFlags]::WordBreak)
        $h = 40 + [int]($sz.Height / [math]::Max(1.0, [double]$Script:DpiScale)); if ($btn) { $h = [math]::Max($h, 70) }
        $row = & $newRowPanel $h
        $l = New-Object System.Windows.Forms.Label; $l.Text = $title; $l.Font = $fontBold; $l.ForeColor = $color; $l.AutoEllipsis = $true
        $l.Location = New-Object System.Drawing.Point(12, 8); $l.Size = New-Object System.Drawing.Size(($rowW - 240), 22); $l.Anchor = "Top, Left, Right"; $row.Controls.Add($l)
        $t = New-Object System.Windows.Forms.Label; $t.Text = ($lines -join "`r`n"); $t.ForeColor = $cMuted
        $t.Location = New-Object System.Drawing.Point(12, 30); $t.Size = New-Object System.Drawing.Size(($rowW - 240), ($h - 32)); $t.Anchor = "Top, Left, Right"; $row.Controls.Add($t)
        if ($btn) { $btn.Location = New-Object System.Drawing.Point(($rowW - 222), 10); $btn.Size = New-Object System.Drawing.Size(210, 28); $btn.Anchor = "Top, Right"; $row.Controls.Add($btn) }
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
    }
    $renderHealth = {
        param($pg)
        $d.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            # Donnees lues en arriere-plan a l'ouverture (sinon lues maintenant)
            $hd = $null
            if ($wc.PreSync) {
                $sw = [Diagnostics.Stopwatch]::StartNew()
                while (-not $wc.PreSync.HealthDone -and $sw.ElapsedMilliseconds -lt 5000) { Start-Sleep -Milliseconds 25 }
                $hd = $wc.PreSync.Health
            }
            if (-not $hd) { $hd = & $Script:HealthDataScript ([bool]$Script:IsLaptop); if ($wc.PreSync) { $wc.PreSync.Health = $hd } }
            # Disques : etat SMART, usure, temperature
            $flow.Controls.Add((& $makeGroup "Disques"))
            foreach ($dk in @($hd.Disks)) {
                $pd = $dk.Pd; $rc = $dk.Rc
                $kind = [string]$pd.MediaType; if ($kind -eq 'SSD' -and [string]$pd.BusType -eq 'NVMe') { $kind = 'SSD NVMe' } elseif ($kind -eq 'Unspecified') { $kind = [string]$pd.BusType }
                $hs = switch ([string]$pd.HealthStatus) { 'Healthy' { 'bon' } 'Warning' { 'a surveiller' } 'Unhealthy' { 'defaillant' } default { [string]$pd.HealthStatus } }
                $info = @("Etat Windows : " + $hs + "  |  " + $kind + "  |  " + [math]::Round([double]$pd.Size / 1GB) + " Go")
                $col = $cGreen
                if ($rc) {
                    $parts = @()
                    if ($null -ne $rc.Wear) { $parts += ("usure " + $rc.Wear + " %"); if ([int]$rc.Wear -ge 80) { $col = $cRed } elseif ([int]$rc.Wear -ge 50) { $col = $cYellow } }
                    if ($rc.Temperature) { $parts += ("temperature " + $rc.Temperature + " C"); if ([int]$rc.Temperature -ge 70) { $col = $cYellow } }
                    if ($rc.PowerOnHours) { $parts += ("allume " + $rc.PowerOnHours + " h") }
                    if ($rc.ReadErrorsUncorrected) { $parts += ("erreurs de lecture : " + $rc.ReadErrorsUncorrected); $col = $cRed }
                    if ($parts.Count -gt 0) { $info += ($parts -join "  |  ") }
                }
                if ([string]$pd.HealthStatus -ne 'Healthy' -and [string]$pd.HealthStatus) { $col = $cRed; $info += "Windows signale un probleme : sauvegarde tes fichiers importants." }
                elseif ($col -eq $cYellow) { $info += "A surveiller." }
                & $healthRow ([string]$pd.FriendlyName) ($info -join "`n") $col $null
            }
            # Espace libre
            $vols = @($hd.Vols)
            if ($vols.Count -gt 0) {
                $txt = @(); $col = $cGreen
                foreach ($v in $vols) {
                    $pct = [math]::Round(100 * [double]$v.SizeRemaining / [double]$v.Size)
                    $txt += ([string]$v.DriveLetter + ": " + (Format-GBSize ([int64]$v.SizeRemaining)) + " libres sur " + (Format-GBSize ([int64]$v.Size)) + " (" + $pct + " %)")
                    if ($pct -lt 10) { $col = $cRed } elseif ($pct -lt 20 -and $col -ne $cRed) { $col = $cYellow }
                }
                if ($col -ne $cGreen) { $txt += "Peu d'espace : les jeux et Windows ralentissent sous 10-15 % libres. Page Nettoyage pour liberer de la place." }
                $bc = New-GBButtonCtl; $bc.Text = "Aller au Nettoyage"; $bc.Add_Click({ & $navTo 'clean' })
                & $healthRow "Espace libre" ($txt -join "`n") $col $bc
            }
            # Memoire : vitesse reelle vs vitesse du kit (XMP / EXPO)
            $flow.Controls.Add((& $makeGroup "Memoire et ecrans"))
            $mods = @($hd.Mods)
            $isVm = [bool]$hd.IsVm
            if ($mods.Count -gt 0 -and $isVm) { & $healthRow "Memoire vive (RAM)" ("Machine virtuelle : " + [math]::Round((($mods | Measure-Object Capacity -Sum).Sum) / 1GB) + " Go attribues.") $cGreen $null; $mods = @() }
            if ($mods.Count -gt 0) {
                $tot = 0; foreach ($m in $mods) { $tot += [double]$m.Capacity }
                $rated = [int](@($mods | ForEach-Object { [int]$_.Speed } | Measure-Object -Maximum).Maximum)
                $conf = [int](@($mods | ForEach-Object { [int]$_.ConfiguredClockSpeed } | Measure-Object -Minimum).Minimum)
                $txt = @("" + [math]::Round($tot / 1GB) + " Go en " + $mods.Count + " barrette(s)  |  vitesse actuelle " + $conf + " MT/s  |  vitesse du kit " + $rated + " MT/s")
                $col = $cGreen
                # Portables : memoire souvent soudee (une "barrette" peut deja etre en double canal) -> pas de conseil
                if ($mods.Count -eq 1 -and -not $Script:IsLaptop) { $txt += "Une seule barrette : en ajouter une identique (double canal) donne souvent +10 a 20 % d'images par seconde."; $col = $cYellow }
                if ($conf -gt 0 -and $rated -gt $conf + 100) {
                    $col = $cYellow
                    if ($Script:IsLaptop) { $txt += "La memoire tourne moins vite que son maximum : sur un portable, c'est le fabricant qui fixe la vitesse." }
                    else { $txt += "La memoire tourne moins vite que son maximum : active le profil XMP (Intel) ou EXPO (AMD) dans le BIOS pour gagner des images par seconde." }
                }
                & $healthRow "Memoire vive (RAM)" ($txt -join "`n") $col $null
            }
            # Ecrans : frequence actuelle vs maximale
            if (Initialize-GBDisplay) {
                foreach ($s in @([GBDisplay]::List())) {
                    $p = $s.Split('|'); $cur = [int]$p[4]; $max = [int]$p[5]
                    $txt = "" + $p[2] + " x " + $p[3] + "  |  " + $cur + " Hz (maximum a cette resolution : " + $max + " Hz)  |  " + $p[1]
                    if ($cur -lt $max) {
                        $b = New-GBButtonCtl; $b.Text = "Passer a " + $max + " Hz"; $b.ForeColor = $cGreen; $b.Tag = @{ Dev = $p[0]; Hz = $max }
                        $b.Add_Click({
                            $o = $this.Tag
                            $r = [GBDisplay]::SetHz($o.Dev, [int]$o.Hz)
                            if ($r -eq 0) { Log ("Ecran " + $o.Dev + " -> " + $o.Hz + " Hz"); & $setStatus ("Ecran regle a " + $o.Hz + " Hz (reglable aussi dans Parametres > Affichage).") $cGreen }
                            else { [System.Windows.Forms.MessageBox]::Show(("Windows a refuse ce changement (code " + $r + ")."), "GameBoost") | Out-Null }
                            & $render
                        })
                        & $healthRow ("Ecran " + $p[0].Replace('\\.\', '')) ($txt + "`nL'ecran ne tourne pas a sa frequence maximale : tout parait moins fluide en jeu.") $cYellow $b
                    } else { & $healthRow ("Ecran " + $p[0].Replace('\\.\', '')) $txt $cGreen $null }
                }
            }
            # Batterie (portables)
            # Portables seulement (sur un PC fixe, un onduleur USB apparait aussi comme "batterie")
            $bat = $hd.Bat
            if ($bat) {
                $flow.Controls.Add((& $makeGroup "Batterie"))
                $design = $hd.Design; $full = $hd.Full; $cyc = $hd.Cyc
                $txt = @("Charge : " + $bat.EstimatedChargeRemaining + " %"); $col = $cGreen
                if ($design -gt 0 -and $full -gt 0) {
                    $hp = [math]::Round(100 * $full / $design)
                    $txt += ("Sante : " + $hp + " % de la capacite d'origine (" + [math]::Round($full / 1000, 1) + " Wh sur " + [math]::Round($design / 1000, 1) + " Wh)")
                    if ($hp -lt 60) { $col = $cRed } elseif ($hp -lt 80) { $col = $cYellow }
                }
                if ($cyc) { $txt += ("Cycles de charge : " + $cyc) }
                $txt += "Pour jouer : branche le chargeur (le processeur et la carte graphique sont brides sur batterie)."
                $bb = New-GBButtonCtl; $bb.Text = "Rapport batterie complet"
                $bb.Add_Click({
                    $f = Join-Path $env:TEMP 'GameBoost_rapport_batterie.html'
                    & powercfg.exe /batteryreport /output $f 2>$null | Out-Null
                    if (Test-Path -LiteralPath $f) { Start-Process $f } else { [System.Windows.Forms.MessageBox]::Show("Windows n'a pas pu creer le rapport.", "GameBoost") | Out-Null }
                })
                & $healthRow "Batterie" ($txt -join "`n") $col $bb
            }
            # Systeme
            $flow.Controls.Add((& $makeGroup "Systeme"))
            $os = $hd.Os
            if ($os) {
                $up = (Get-Date) - $os.LastBootUpTime
                $txt = @("Allume depuis " + [int]$up.TotalDays + " j " + $up.Hours + " h  |  " + $os.Caption + " (build " + $os.BuildNumber + ")")
                $col = $cGreen
                if ($up.TotalDays -ge 7) { $txt += "Pas redemarre depuis plus d'une semaine : un redemarrage libere la memoire et termine les mises a jour."; $col = $cYellow }
                & $healthRow "Windows" ($txt -join "`n") $col $null
            }
        } finally { $d.Cursor = [System.Windows.Forms.Cursors]::Default }
    }

    # ====================== Page : reseau ======================
    $renderNetwork = {
        param($pg)
        $flow.Controls.Add((& $makeGroup "Serveurs DNS"))
        if ($wc.PreSync -and $wc.PreSync.NetDone -and $null -ne $wc.PreSync.Adapters) { $ads = @($wc.PreSync.Adapters) }
        else { $ads = @(Get-GBNetAdapters); if ($wc.PreSync) { $wc.PreSync.Adapters = $ads } }
        $row = & $newRowPanel 96
        if ($ads.Count -eq 0) {
            $l = New-Object System.Windows.Forms.Label; $l.Text = "Aucune carte reseau connectee."; $l.ForeColor = $cYellow
            $l.Location = New-Object System.Drawing.Point(12, 10); $l.Size = New-Object System.Drawing.Size(($rowW - 24), 22); $row.Controls.Add($l)
        } else {
            $cur = @(); $firstSet = $null
            foreach ($a in $ads) {
                $st = Get-GBDnsState ([string]$a.InterfaceGuid)
                $txt = "Automatique (box)"; if (-not $st.Auto) { $txt = $st.Servers -join ", " }
                $cur += ($a.Name + " : " + $txt)
                if ($null -eq $firstSet) { $firstSet = $st }
            }
            $l = New-Object System.Windows.Forms.Label; $l.Text = "Actuel - " + ($cur -join "   |   "); $l.Font = $fontBold; $l.ForeColor = $cText; $l.AutoEllipsis = $true
            $l.Location = New-Object System.Drawing.Point(12, 8); $l.Size = New-Object System.Drawing.Size(($rowW - 24), 22); $l.Anchor = "Top, Left, Right"; $row.Controls.Add($l)
            $cb = New-GBComboCtl; $cb.DropDownStyle = "DropDownList"; Set-GBDarkCombo $cb
            foreach ($p in $Script:DnsProviders) { [void]$cb.Items.Add($p.L) }
            $sel = -1
            for ($i = 0; $i -lt $Script:DnsProviders.Count; $i++) {
                $ps = @($Script:DnsProviders[$i].S)
                if (($ps.Count -eq 0 -and $firstSet.Auto) -or ($ps.Count -gt 0 -and -not $firstSet.Auto -and (($ps -join ',') -eq ($firstSet.Servers -join ',')))) { $sel = $i }
            }
            $cb.SelectedIndex = $sel
            $cb.Location = New-Object System.Drawing.Point(12, 36); $cb.Size = New-Object System.Drawing.Size(380, 24); $row.Controls.Add($cb)
            $b = New-GBButtonCtl; $b.Text = "Appliquer"; $b.ForeColor = $cGreen; $b.Location = New-Object System.Drawing.Point(402, 35); $b.Size = New-Object System.Drawing.Size(140, 26)
            $b.Tag = @{ Cb = $cb; Ads = $ads }
            $b.Add_Click({
                $o = $this.Tag; $i = $o.Cb.SelectedIndex
                if ($i -lt 0) { [System.Windows.Forms.MessageBox]::Show("Choisis un serveur DNS dans la liste.", "GameBoost") | Out-Null; return }
                & $ensureRp
                $fail = @()
                foreach ($a in $o.Ads) { try { Set-GBDns $a $Script:DnsProviders[$i].S } catch { $fail += ($a.Name + " : " + $_.Exception.Message) } }
                Log ("Reseau : DNS -> " + $Script:DnsProviders[$i].L + " (" + (@($o.Ads | ForEach-Object { $_.Name }) -join ", ") + ")")
                & $render
                if ($fail.Count -gt 0) { [System.Windows.Forms.MessageBox]::Show(("Non applique :`r`n" + ($fail -join "`r`n")), "GameBoost") | Out-Null }
                else { & $setStatus ("DNS change : " + $Script:DnsProviders[$i].L + ". 'Tout annuler' remet tes DNS d'origine.") $cGreen }
            })
            $row.Controls.Add($b)
            $d2 = New-Object System.Windows.Forms.Label
            $d2.Text = "Un DNS rapide accelere l'ouverture des sites, des launchers et le debut des telechargements. Il ne change pas le ping en jeu."
            $d2.ForeColor = $cMuted; $d2.Location = New-Object System.Drawing.Point(12, 68); $d2.Size = New-Object System.Drawing.Size(($rowW - 24), 22); $d2.AutoEllipsis = $true; $d2.Anchor = "Top, Left, Right"
            $row.Controls.Add($d2)
        }
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
        & $addTweakRows @($Script:WinTweaks | Where-Object { $_.Page -eq 'network' })
    }

    $renderTools = {
        param($pg)
        $flow.Controls.Add((& $makeGroup "Reparation et maintenance"))
        $row = & $newRowPanel 86
        $br = New-GBButtonCtl; $br.Text = "Reparer les fichiers de Windows"; $br.ForeColor = $cGreen; $br.Location = New-Object System.Drawing.Point(10, 8); $br.Size = New-Object System.Drawing.Size(260, 28)
        $tip.SetToolTip($br, "DISM /RestoreHealth puis sfc /scannow : repare les fichiers systeme abimes (plantages, bugs bizarres, mises a jour qui echouent).")
        $br.Add_Click({
            $q = "Verifier et reparer les fichiers de Windows (DISM puis SFC) ?`r`n`r`nUne fenetre noire s'ouvre : laisse-la travailler (10 a 30 minutes, internet conseille) et ne la ferme pas avant le message 'Termine'."
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Reparation", "YesNo", "Question") -ne "Yes") { return }
            Start-Process cmd.exe -ArgumentList '/k title GameBoost - Reparation de Windows && DISM /Online /Cleanup-Image /RestoreHealth && sfc /scannow & echo. & echo Termine : tu peux fermer cette fenetre.'
            Log "Outils : reparation de Windows lancee (DISM + SFC)"
        })
        $row.Controls.Add($br)
        $bp = New-GBButtonCtl; $bp.Text = "Creer un point de restauration"; $bp.Location = New-Object System.Drawing.Point(278, 8); $bp.Size = New-Object System.Drawing.Size(250, 28)
        $bp.Add_Click({
            $d.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
            try { $Script:Config.LastRestorePoint = ""; New-WindowsRestorePoint } catch {} finally { $d.Cursor = [System.Windows.Forms.Cursors]::Default }
            Update-BoostButton
            & $setStatus "Point de restauration : resultat dans le journal de la fenetre principale." $cText
        })
        $row.Controls.Add($bp)
        $bs = New-GBButtonCtl; $bs.Text = "Restaurer le systeme..."; $bs.Location = New-Object System.Drawing.Point(536, 8); $bs.Size = New-Object System.Drawing.Size(200, 28)
        $tip.SetToolTip($bs, "Ouvre l'outil Windows pour revenir a un point de restauration.")
        $bs.Add_Click({ try { Start-Process rstrui.exe } catch {} })
        $row.Controls.Add($bs)
        $lr = New-Object System.Windows.Forms.Label
        $lr.Text = "Reparation : pour un Windows qui plante ou bugue. Point de restauration : a faire avant de gros changements (GameBoost en cree un tout seul avant ses modifications)."
        $lr.ForeColor = $cMuted; $lr.Location = New-Object System.Drawing.Point(12, 42); $lr.Size = New-Object System.Drawing.Size(($rowW - 24), 40); $lr.Anchor = "Top, Left, Right"
        $row.Controls.Add($lr)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
        $flow.Controls.Add((& $makeGroup "Installation automatique de Windows (autounattend.xml)"))
        $row = & $newRowPanel 250
        $l = New-Object System.Windows.Forms.Label
        $l.Text = ("Cree un fichier de reponses pour une installation propre de Windows : place-le a la racine de la cle USB d'installation (creee avec l'outil " +
                   "officiel 'Media Creation Tool' de Microsoft ou avec Rufus). Windows l'applique tout seul pendant l'installation.")
        $l.ForeColor = $cMuted; $l.Location = New-Object System.Drawing.Point(12, 8); $l.Size = New-Object System.Drawing.Size(($rowW - 24), 40); $l.Anchor = "Top, Left, Right"
        $row.Controls.Add($l)
        $c1 = New-GBToggleCtl "Contourner les verifications de Windows 11 (TPM, Secure Boot, RAM, processeur)" $false
        $c1.Location = New-Object System.Drawing.Point(10, 52); $c1.Size = New-Object System.Drawing.Size(($rowW - 24), 24); $c1.Anchor = "Top, Left, Right"; $row.Controls.Add($c1)
        $c2 = New-GBToggleCtl "Passer les ecrans de licence et de confidentialite (reglages au minimum)" $true
        $c2.Location = New-Object System.Drawing.Point(10, 80); $c2.Size = New-Object System.Drawing.Size(($rowW - 24), 24); $c2.Anchor = "Top, Left, Right"; $row.Controls.Add($c2)
        $c3 = New-GBToggleCtl "Permettre un compte local (sans compte Microsoft ni internet)" $true
        $c3.Location = New-Object System.Drawing.Point(10, 108); $c3.Size = New-Object System.Drawing.Size(($rowW - 24), 24); $c3.Anchor = "Top, Left, Right"; $row.Controls.Add($c3)
        $c4 = New-GBToggleCtl "Ne pas installer les applis preinstallees conseillees (News, Solitaire, Clipchamp...)" $true
        $c4.Location = New-Object System.Drawing.Point(10, 136); $c4.Size = New-Object System.Drawing.Size(($rowW - 24), 24); $c4.Anchor = "Top, Left, Right"; $row.Controls.Add($c4)
        $warn = New-Object System.Windows.Forms.Label
        $warn.Text = "Contourner les verifications de Windows 11 installe Windows sur un PC non pris en charge par Microsoft : mises a jour non garanties."
        $warn.ForeColor = $cYellow; $warn.Location = New-Object System.Drawing.Point(12, 168); $warn.Size = New-Object System.Drawing.Size(($rowW - 24), 36); $warn.Anchor = "Top, Left, Right"
        $row.Controls.Add($warn)
        $bg = New-GBButtonCtl; $bg.Text = "Creer autounattend.xml..."; $bg.ForeColor = $cGreen; $bg.Location = New-Object System.Drawing.Point(10, 210); $bg.Size = New-Object System.Drawing.Size(230, 28)
        $bg.Tag = @{ C1 = $c1; C2 = $c2; C3 = $c3; C4 = $c4 }
        $bg.Add_Click({
            $o = $this.Tag
            $apps = @(); if ($o.C4.Checked) { $apps = @($Script:BloatApps | Where-Object { $_.Reco -and $_.N -notmatch '\*' } | ForEach-Object { $_.N }) }
            $arch = 'amd64'; if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { $arch = 'arm64' }
            try { $xml = New-GBAutounattendXml $o.C1.Checked $o.C2.Checked $o.C3.Checked $apps $arch }
            catch { [System.Windows.Forms.MessageBox]::Show(("Fichier invalide : " + $_.Exception.Message), "GameBoost") | Out-Null; return }
            $sfd = New-Object System.Windows.Forms.SaveFileDialog
            $sfd.FileName = 'autounattend.xml'; $sfd.Filter = 'Fichier de reponses (*.xml)|*.xml'; $sfd.InitialDirectory = [Environment]::GetFolderPath('Desktop')
            if ($sfd.ShowDialog() -ne 'OK') { return }
            [System.IO.File]::WriteAllText($sfd.FileName, $xml, (New-Object System.Text.UTF8Encoding($false)))
            Log ("Config Windows : autounattend.xml cree -> " + $sfd.FileName)
            [System.Windows.Forms.MessageBox]::Show(("Fichier cree :`r`n" + $sfd.FileName + "`r`n`r`nCopie-le a la racine de ta cle USB d'installation de Windows (a cote du dossier 'sources'). " +
                "Il n'a AUCUN effet sur ce PC."), "GameBoost") | Out-Null
        })
        $row.Controls.Add($bg)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
        $flow.Controls.Add((& $makeGroup "Dossiers de GameBoost"))
        $row = & $newRowPanel 44
        $bs = New-GBButtonCtl; $bs.Text = "Scripts (suppression persistante)"; $bs.Location = New-Object System.Drawing.Point(10, 8); $bs.Size = New-Object System.Drawing.Size(260, 28)
        $bs.Add_Click({ $p = Join-Path $env:ProgramData 'GameBoost\Scripts'; if (Test-Path -LiteralPath $p) { Start-Process explorer.exe $p } else { [System.Windows.Forms.MessageBox]::Show("Aucun script : la suppression persistante n'a jamais ete activee.", "GameBoost") | Out-Null } })
        $row.Controls.Add($bs)
        $bk = New-GBButtonCtl; $bk.Text = "Sauvegardes des reglages"; $bk.Location = New-Object System.Drawing.Point(278, 8); $bk.Size = New-Object System.Drawing.Size(230, 28)
        $bk.Add_Click({ if (-not (Test-Path -LiteralPath $Script:WinCfgSaveDir)) { New-Item -ItemType Directory -Path $Script:WinCfgSaveDir -Force | Out-Null }; Start-Process explorer.exe $Script:WinCfgSaveDir })
        $row.Controls.Add($bk)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
    }

    # ====================== Page : sauvegarde / import ======================
    $renderBackup = {
        param($pg)
        $flow.Controls.Add((& $makeGroup "Exporter"))
        $row = & $newRowPanel 70
        $l = New-Object System.Windows.Forms.Label
        $l.Text = "Enregistre l'etat de tous les reglages de Config Windows dans un fichier (aucune donnee personnelle). Pratique avant une reinstallation ou pour configurer un autre PC pareil."
        $l.ForeColor = $cMuted; $l.Location = New-Object System.Drawing.Point(12, 6); $l.Size = New-Object System.Drawing.Size(($rowW - 220), 56); $l.Anchor = "Top, Left, Right"; $row.Controls.Add($l)
        $be = New-GBButtonCtl; $be.Text = "Exporter..."; $be.ForeColor = $cGreen; $be.Location = New-Object System.Drawing.Point(($rowW - 192), 18); $be.Size = New-Object System.Drawing.Size(180, 28); $be.Anchor = "Top, Right"
        $be.Add_Click({
            $set = [ordered]@{}
            foreach ($t in @($Script:WinTweaks | Where-Object { $_.Type -ne 'action' -and (Test-WinCfgVisible $_) })) { try { $set[$t.Id] = Get-WinCfgCurrent $t } catch {} }
            $doc = [ordered]@{ Format = 1; App = 'GameBoost'; Version = $AppVersion; Date = (Get-Date).ToString('yyyy-MM-dd HH:mm'); Windows = $Script:WinBuild; Settings = $set; PersistentApps = @(Get-GBPersistList) }
            $sfd = New-Object System.Windows.Forms.SaveFileDialog
            $sfd.FileName = 'GameBoost_config_windows.json'; $sfd.Filter = 'Configuration GameBoost (*.json)|*.json'; $sfd.InitialDirectory = [Environment]::GetFolderPath('Desktop')
            if ($sfd.ShowDialog() -ne 'OK') { return }
            $doc | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath $sfd.FileName -Encoding UTF8
            Log ("Config Windows : configuration exportee -> " + $sfd.FileName)
            & $setStatus ("Configuration exportee : " + $sfd.FileName) $cGreen
        })
        $row.Controls.Add($be)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
        $flow.Controls.Add((& $makeGroup "Importer"))
        $row = & $newRowPanel 70
        $l = New-Object System.Windows.Forms.Label
        $l.Text = "Lit un fichier exporte par GameBoost, te montre la liste des changements, puis les applique seulement si tu confirmes."
        $l.ForeColor = $cMuted; $l.Location = New-Object System.Drawing.Point(12, 6); $l.Size = New-Object System.Drawing.Size(($rowW - 220), 56); $l.Anchor = "Top, Left, Right"; $row.Controls.Add($l)
        $bi = New-GBButtonCtl; $bi.Text = "Importer..."; $bi.Location = New-Object System.Drawing.Point(($rowW - 192), 18); $bi.Size = New-Object System.Drawing.Size(180, 28); $bi.Anchor = "Top, Right"
        $bi.Add_Click({
            $ofd = New-Object System.Windows.Forms.OpenFileDialog
            $ofd.Filter = 'Configuration GameBoost (*.json)|*.json'; $ofd.InitialDirectory = [Environment]::GetFolderPath('Desktop')
            if ($ofd.ShowDialog() -ne 'OK') { return }
            try { $doc = Get-Content -LiteralPath $ofd.FileName -Raw -Encoding UTF8 | ConvertFrom-Json } catch { [System.Windows.Forms.MessageBox]::Show("Fichier illisible (JSON invalide).", "GameBoost") | Out-Null; return }
            if ([string]$doc.App -ne 'GameBoost' -or [int]$doc.Format -ne 1 -or -not $doc.Settings) { [System.Windows.Forms.MessageBox]::Show("Ce fichier n'est pas une configuration GameBoost (format 1).", "GameBoost") | Out-Null; return }
            $changes = New-Object System.Collections.ArrayList
            foreach ($p in $doc.Settings.PSObject.Properties) {
                $t = @($Script:WinTweaks | Where-Object { $_.Id -eq $p.Name }) | Select-Object -First 1
                if (-not $t -or $t.Type -eq 'action' -or -not (Test-WinCfgVisible $t)) { continue }
                $cur = Get-WinCfgCurrent $t
                if ($t.Type -eq 'choice') {
                    $want = [int]$p.Value
                    if ($want -lt 0 -or $want -ge $t.Opts.Count -or $want -eq $cur) { continue }
                    [void]$changes.Add(@{ T = $t; V = $want; Txt = ($t.Name + " : " + $t.Opts[$want].L) })
                } else {
                    $want = [bool]$p.Value
                    if ($want -eq $cur) { continue }
                    $e = "desactive"; if ($want) { $e = "active" }
                    [void]$changes.Add(@{ T = $t; V = $want; Txt = ($t.Name + " : " + $e) })
                }
            }
            if ($changes.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Ce PC a deja exactement ces reglages : rien a changer.", "GameBoost") | Out-Null; return }
            $q = "Fichier du " + $doc.Date + " (GameBoost " + $doc.Version + "). " + $changes.Count + " changement(s) :`r`n`r`n- " + ((@($changes | ForEach-Object { $_.Txt }) | Select-Object -First 30) -join "`r`n- ")
            if ($changes.Count -gt 30) { $q += "`r`n... et " + ($changes.Count - 30) + " autre(s)" }
            $q += "`r`n`r`nAppliquer ? (les valeurs d'origine sont gardees pour 'Tout annuler')"
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Import", "YesNo", "Question") -ne "Yes") { return }
            & $ensureRp
            $ok = 0; $fail = @()
            foreach ($c in $changes) {
                try { if ($c.T.Type -eq 'choice') { Set-WinCfgChoice $c.T $c.V } else { Set-WinCfgTweak $c.T $c.V }; $ok++; if ($c.T.R) { $wc.Need[$c.T.R] = $true } }
                catch { $fail += ($c.T.Name + " : " + $_.Exception.Message) }
            }
            Log ("Config Windows : import -> " + $ok + " reglage(s) applique(s), " + $fail.Count + " echec(s)")
            if ($fail.Count -gt 0) { [System.Windows.Forms.MessageBox]::Show(("Non appliques :`r`n" + ($fail -join "`r`n")), "GameBoost") | Out-Null }
            & $updateStatus
        })
        $row.Controls.Add($bi)
        Invoke-GBRowScale $row
        $flow.Controls.Add($row)
    }

    # ====================== Pages a liste : applis Windows / logiciels externes ======================
    $lvBox = $null
    $mkList = {
        param($cols, $y, $bottom)
        $lv = New-Object System.Windows.Forms.ListView
        $lv.Location = New-Object System.Drawing.Point(0, $y); $lv.Size = New-Object System.Drawing.Size($panel.ClientSize.Width, ($panel.ClientSize.Height - $y - $bottom))
        $lv.Anchor = "Top, Bottom, Left, Right"; $lv.CheckBoxes = $true
        foreach ($c in $cols) { [void]$lv.Columns.Add($c[0], $c[1]) }
        Set-GBListViewStyle $lv
        $panel.Controls.Add($lv)
        if ([math]::Abs($Script:DpiScale - 1.0) -gt 0.01) { foreach ($col in $lv.Columns) { $col.Width = [int]($col.Width * $Script:DpiScale) } }
        return $lv
    }
    $mkPanelBtn = {
        param($text, $x, $yFromBottom, $w, $color)
        $b = New-GBButtonCtl; $b.Text = $text; if ($color) { $b.ForeColor = $color }
        $s = [math]::Max(1.0, [double]$Script:DpiScale)
        $b.Size = New-Object System.Drawing.Size([int]($w * $s), [int](28 * $s))
        $b.Location = New-Object System.Drawing.Point([int]($x * $s), ($panel.ClientSize.Height - [int]($yFromBottom * $s)))
        $b.Anchor = "Bottom, Left"
        $panel.Controls.Add($b); return $b
    }
    $mkPanelLbl = {
        param($text, $x, $y, $w, $h, $color, $anchor)
        $l = New-Object System.Windows.Forms.Label; $l.Text = $text; $l.ForeColor = $color
        $s = [math]::Max(1.0, [double]$Script:DpiScale)
        $l.Location = New-Object System.Drawing.Point([int]($x * $s), $y); $l.Size = New-Object System.Drawing.Size([int]($w * $s), [int]($h * $s))
        if ($anchor) { $l.Anchor = $anchor }
        $panel.Controls.Add($l); return $l
    }
    $sc = [math]::Max(1.0, [double]$Script:DpiScale)

    $appsFill = $null
    $renderApps = {
        param($pg)
        $tabs = @(@('apps', 'Applis du Store', 150), @('caps', 'Capacites', 120), @('feats', 'Fonctionnalites', 140), @('od', 'OneDrive / Edge', 140))
        $x = 0
        foreach ($tb in $tabs) {
            $b = New-GBButtonCtl; $b.Text = $tb[1]; $b.Tag = $tb[0]
            $b.Location = New-Object System.Drawing.Point([int]($x * $sc), 0); $b.Size = New-Object System.Drawing.Size([int]($tb[2] * $sc), [int](28 * $sc))
            if ($wc.Apps.Tab -eq $tb[0]) { $b.ForeColor = $cViolet } else { $b.ForeColor = $cMuted }
            $b.Add_Click({ if ($wc.Task) { return }; $wc.Apps.Tab = $this.Tag; & $render })
            $panel.Controls.Add($b); $x += $tb[2] + 8
        }
        $tab = $wc.Apps.Tab
        $search = New-Object System.Windows.Forms.TextBox
        $search.Location = New-Object System.Drawing.Point(0, [int](36 * $sc)); $search.Size = New-Object System.Drawing.Size([int](260 * $sc), [int](24 * $sc))
        $search.BackColor = $cPanel; $search.ForeColor = $cText; $search.BorderStyle = "FixedSingle"
        $tip.SetToolTip($search, "Filtrer la liste")
        $panel.Controls.Add($search)
        $hint = & $mkPanelLbl "<- filtrer" 268 ([int](39 * $sc)) 300 20 $cMuted $null
        $cols = @(@('Etat', 120), @('Nom', 270), @('Paquet / identifiant', 250), @('Reinstallation', 150))
        if ($tab -eq 'od') { $cols = @(@('Etat', 120), @('Nom', 220), @('Remarque', 500)) }
        $lv = & $mkList $cols ([int](66 * $sc)) ([int](136 * $sc))
        $wc.Apps.Lv = $lv
        $btnRec = & $mkPanelBtn "Cocher les conseillees" 0 128 180 $null
        $btnNone = & $mkPanelBtn "Tout decocher" 188 128 130 $null
        $btnDel = & $mkPanelBtn "Supprimer la selection" 326 128 200 $cRed
        $btnAdd = & $mkPanelBtn "Reinstaller la selection" 534 128 200 $cGreen
        $persistLbl = & $mkPanelLbl "" 0 ($panel.ClientSize.Height - [int](92 * $sc)) 540 40 $cMuted "Bottom, Left"
        $btnStop = & $mkPanelBtn "Arreter la persistance" 556 88 190 $cYellow
        $chkPersist = $null
        if ($tab -eq 'apps') {
            $chkPersist = New-GBToggleCtl "Empecher Windows de les reinstaller" $wc.Apps.Persist
            $chkPersist.Location = New-Object System.Drawing.Point([int](560 * $sc), [int](36 * $sc)); $chkPersist.Size = New-Object System.Drawing.Size([int](300 * $sc), [int](24 * $sc)); $chkPersist.Anchor = "Top, Right"
            $chkPersist.Left = $panel.ClientSize.Width - $chkPersist.Width
            $tip.SetToolTip($chkPersist, "Cree une tache planifiee visible (\GameBoost\SuppressionApplis, compte SYSTEM) qui supprime de nouveau ces applis a chaque demarrage si Windows les a remises.")
            $chkPersist.Add_CheckedChanged({ $wc.Apps.Persist = [bool]$this.Checked })
            $panel.Controls.Add($chkPersist)
        }
        $note = & $mkPanelLbl "" 0 ($panel.ClientSize.Height - [int](46 * $sc)) 780 44 $cMuted "Bottom, Left, Right"
        $hint.Text = "<- filtrer"

        # Etat de la suppression persistante
        $task = Get-GBPersistTask; $plist = @(Get-GBPersistList)
        if ($task -and $plist.Count -gt 0) {
            $persistLbl.Text = "Suppression persistante ACTIVE : " + $plist.Count + " appli(s) supprimee(s) de nouveau a chaque demarrage (tache \GameBoost\SuppressionApplis)."
            $persistLbl.ForeColor = $cGreen; $btnStop.Enabled = $true
        } else { $persistLbl.Text = "Suppression persistante : inactive (les applis supprimees peuvent revenir avec une grosse mise a jour de Windows)."; $btnStop.Enabled = $false }
        $btnStop.Add_Click({
            $q = "Arreter la suppression persistante ?`r`n`r`nGameBoost supprime le script et la tache planifiee \GameBoost\SuppressionApplis. Tu pourras ensuite reinstaller ces applis normalement."
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Question") -ne "Yes") { return }
            try { Set-GBPersistList @(); Log "Config Windows : suppression persistante arretee (tache et script supprimes)" } catch { [System.Windows.Forms.MessageBox]::Show(("Echec : " + $_.Exception.Message), "GameBoost") | Out-Null }
            & $render
        })

        # Remplissage de la liste selon l'onglet
        $fill = {
            $lv = $wc.Apps.Lv; $q = ([string]$wc.Apps.Filter).ToLower()
            $lv.BeginUpdate(); $lv.Items.Clear()
            foreach ($it in @($wc.Apps.Rows)) {
                if ($q -and (($it.Label + ' ' + $it.Name).ToLower().IndexOf($q) -lt 0)) { continue }
                $li = New-Object System.Windows.Forms.ListViewItem($it.StateTxt)
                foreach ($s in $it.Cols) { [void]$li.SubItems.Add([string]$s) }
                $li.ForeColor = $it.Color; $li.Tag = $it
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
        }
        $wc.Apps.Fill = $fill
        $search.Text = [string]$wc.Apps.Filter
        $search.Add_TextChanged({ $wc.Apps.Filter = $this.Text; & $wc.Apps.Fill })

        $buildRows = {
            $tab = $wc.Apps.Tab; $data = $wc.Apps.Data[$tab]; $rows = New-Object System.Collections.ArrayList
            $plist = @(Get-GBPersistList)
            if ($tab -eq 'apps') {
                $inst = @{}; foreach ($a in @($data.Items)) { $inst[$a.Name] = $a }
                $prov = @{}; foreach ($p in @($data.Prov)) { $prov[$p] = $true }
                $known = @{}; $absent = New-Object System.Collections.ArrayList
                foreach ($b in $Script:BloatApps) {
                    $names = @($inst.Keys | Where-Object { $_ -like $b.N })
                    if ($names.Count -eq 0 -and $b.N -notmatch '\*') { $names = @() }
                    foreach ($n in $names) { $known[$n] = $b }
                    if ($names.Count -eq 0 -and $b.N -notmatch '\*') {
                        $st = "o Non installee"; if ($plist -contains $b.N) { $st = "o Bloquee" }
                        $re = "Microsoft Store"; if ($b.Store -eq $false) { $re = "impossible" }
                        [void]$absent.Add(@{ Name = $b.N; Label = $b.L; Installed = $false; Reco = $false; StateTxt = $st; Color = $cMuted; Cols = @($b.L, $b.N, $re); Store = ($b.Store -ne $false); Kind = 'apps' })
                    }
                }
                foreach ($n in @($inst.Keys | Sort-Object)) {
                    if (-not $known.ContainsKey($n) -and $n -match $Script:AppxProtected) { continue }
                    $b = $known[$n]; $label = $n -replace '^[^\.]+\.', '' -creplace '([a-z])([A-Z])', '$1 $2'; $reco = $false; $store = $true
                    if ($b) { $label = $b.L; $reco = [bool]$b.Reco; $store = ($b.Store -ne $false) }
                    $re = "Microsoft Store"; if (-not $store) { $re = "impossible" }
                    $st = "* Installee"; $col = $cText; if ($reco) { $col = $cGreen }
                    if ($plist -contains $n) { $st = "* Revenue"; $col = $cYellow }
                    [void]$rows.Add(@{ Name = $n; Label = $label; Installed = $true; Reco = $reco; StateTxt = $st; Color = $col; Cols = @($label, $n, $re); Store = $store; Kind = 'apps' })
                }
                foreach ($a in $absent) { [void]$rows.Add($a) }
            } elseif ($tab -eq 'caps' -or $tab -eq 'feats') {
                $cat = $Script:WinCaps; if ($tab -eq 'feats') { $cat = $Script:WinFeats }
                foreach ($c in $cat) {
                    $m = @($data.Items | Where-Object { $_.Name -eq $c.N -or $_.Name -like ($c.N + '~*') })
                    if ($m.Count -eq 0) { continue }
                    $on = @($m | Where-Object { $_.State -in @('Installed', 'Enabled', 'EnablePending', 'InstallPending') }).Count -gt 0
                    $st = "o Absente"; $col = $cMuted; if ($on) { $st = "* Installee"; $col = $cText; if ($c.Reco) { $col = $cGreen } }
                    $nm = @($m | ForEach-Object { $_.Name })
                    [void]$rows.Add(@{ Name = $nm[0]; Names = $nm; Label = $c.L; Installed = $on; Reco = [bool]$c.Reco; Warn = $c.Warn; StateTxt = $st; Color = $col; Cols = @($c.L, ($nm -join ', '), "Windows Update"); Kind = $tab })
                }
            } else {
                $od = (Test-Path -LiteralPath (Join-Path $env:LOCALAPPDATA 'Microsoft\OneDrive\OneDrive.exe')) -or (Test-Path -LiteralPath (Join-Path ${env:ProgramFiles} 'Microsoft OneDrive\OneDrive.exe'))
                $st = "o Absent"; if ($od) { $st = "* Installe" }
                [void]$rows.Add(@{ Name = 'OneDrive'; Label = 'Microsoft OneDrive'; Installed = $od; Reco = $false; StateTxt = $st; Color = $cText; Kind = 'onedrive'
                                   Cols = @('Microsoft OneDrive', "Desinstalle OneDrive (tes fichiers deja telecharges restent dans ton dossier OneDrive). Reinstallation : WinGet.") })
                $edge = Test-Path -LiteralPath (Join-Path ${env:ProgramFiles(x86)} 'Microsoft\Edge\Application\msedge.exe')
                $st = "o Absent"; if ($edge) { $st = "* Installe" }
                [void]$rows.Add(@{ Name = 'Edge'; Label = 'Microsoft Edge'; Installed = $edge; Reco = $false; StateTxt = $st; Color = $cMuted; Kind = 'edge'
                                   Cols = @('Microsoft Edge', "Non supprime par GameBoost : Windows, les Widgets, l'aide et de nombreuses applis (WebView) en dependent. Voir 'Jeu et performances' > Edge en arriere-plan.") })
            }
            $wc.Apps.Rows = $rows.ToArray()
        }
        $wc.Apps.Build = $buildRows

        $infos = @{ apps = "Vert = conseillee a la suppression. 'Non installee' coche + persistance = Windows ne pourra plus l'installer. Reinstallation : ouvre le Microsoft Store."
                    caps = "Capacites Windows installables a la demande. La reinstallation passe par Windows Update (internet necessaire)."
                    feats = "Fonctionnalites facultatives de Windows. Un redemarrage peut etre necessaire."
                    od = "OneDrive : ferme la synchronisation avant. Edge reste installe (dependance de Windows) mais peut etre empeche de tourner en arriere-plan." }
        $note.Text = $infos[$tab]
        if ($tab -eq 'od') { $btnRec.Enabled = $false; $btnStop.Visible = $false; $persistLbl.Visible = $false }

        $loadData = {
            $tab = $wc.Apps.Tab
            if ($tab -eq 'od') { & $wc.Apps.Build; & $wc.Apps.Fill; return }
            if ($wc.Apps.Data.ContainsKey($tab)) { & $wc.Apps.Build; & $wc.Apps.Fill; return }
            $msg = @{ apps = "Lecture des applis installees..."; caps = "Lecture des capacites Windows (jusqu'a 30 s)..."; feats = "Lecture des fonctionnalites Windows (jusqu'a 30 s)..." }
            & $setStatus $msg[$tab] $cText
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Items = $null; Prov = $null })
            $wc.Mode = 'scan|' + $tab
            $wc.Task = Start-BackgroundTask $Script:WinAppsScanScript $wc.Sync $tab
            $poll.Start()
        }
        $wc.Apps.Load = $loadData

        $btnRec.Add_Click({ foreach ($li in $wc.Apps.Lv.Items) { $li.Checked = ([bool]$li.Tag.Reco -and [bool]$li.Tag.Installed) } })
        $btnNone.Add_Click({ foreach ($li in $wc.Apps.Lv.Items) { $li.Checked = $false } })
        $btnDel.Add_Click({
            if ($wc.Task) { return }
            $sel = @($wc.Apps.Lv.CheckedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un element.", "GameBoost") | Out-Null; return }
            $tab = $wc.Apps.Tab
            if ($tab -eq 'od') {
                if (@($sel | Where-Object { $_.Kind -eq 'edge' }).Count -gt 0) { [System.Windows.Forms.MessageBox]::Show("Microsoft Edge n'est pas supprime par GameBoost : Windows et beaucoup d'applis en dependent (WebView, Widgets, aide). Tu peux l'empecher de tourner en arriere-plan dans 'Jeu et performances'.", "GameBoost") | Out-Null; return }
                $q = "Desinstaller OneDrive ?`r`n`r`nLa synchronisation s'arrete. Tes fichiers deja presents sur le PC restent dans ton dossier OneDrive ; les fichiers 'en ligne uniquement' restent dans le cloud (onedrive.live.com).`r`n`r`nReinstallation possible plus tard via 'Logiciels externes' (WinGet)."
                if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Warning") -ne "Yes") { return }
                & $ensureRp
                & $startAction @{ Kind = 'onedrive'; Op = 'remove'; Verb = 'Desinstallation'; Names = @('OneDrive') }
                return
            }
            $todo = @($sel | Where-Object { $_.Installed -or ($tab -eq 'apps' -and $wc.Apps.Persist) })
            if ($todo.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Les elements coches ne sont pas installes. (Pour empecher une appli absente d'etre installee, active 'Empecher Windows de les reinstaller'.)", "GameBoost") | Out-Null; return }
            $warns = @($todo | Where-Object { $_.Warn } | ForEach-Object { "- " + $_.Label + " : " + $_.Warn })
            $q = "Supprimer " + $todo.Count + " element(s) pour tous les comptes du PC ?`r`n`r`n- " + ((@($todo | ForEach-Object { $_.Label }) | Select-Object -First 25) -join "`r`n- ")
            if ($warns.Count -gt 0) { $q += "`r`n`r`nAttention :`r`n" + ($warns -join "`r`n") }
            if ($tab -eq 'apps' -and $wc.Apps.Persist) { $q += "`r`n`r`nPersistance activee : une tache planifiee visible (\GameBoost\SuppressionApplis, compte SYSTEM) les supprimera de nouveau a chaque demarrage. Tu peux l'arreter ici a tout moment." }
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Applis Windows", "YesNo", "Question") -ne "Yes") { return }
            & $ensureRp
            if ($tab -eq 'apps') {
                if ($wc.Apps.Persist) {
                    try { Set-GBPersistList (@(Get-GBPersistList) + @($todo | ForEach-Object { $_.Name })); Log ("Config Windows : suppression persistante -> " + (@($todo | ForEach-Object { $_.Name }) -join ", ")) }
                    catch { [System.Windows.Forms.MessageBox]::Show(("Suppression persistante impossible : " + $_.Exception.Message), "GameBoost") | Out-Null }
                }
                $names = @($todo | Where-Object { $_.Installed } | ForEach-Object { $_.Name })
                if ($names.Count -eq 0) { & $render; return }
                Log ("Config Windows : suppression des applis " + ($names -join ", "))
                $wc.Sync = [hashtable]::Synchronized(@{ Status = "Preparation..."; Done = $false; Error = $null; Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
                $wc.Mode = 'appsremove'; $wc.Task = Start-BackgroundTask $Script:AppxRemoveScript $wc.Sync @($names); $poll.Start()
            } else {
                & $startAction @{ Kind = $tab; Op = 'remove'; Verb = 'Suppression'; Names = @($todo | ForEach-Object { $_.Names } | Select-Object -Unique) }
            }
        })
        $btnAdd.Add_Click({
            if ($wc.Task) { return }
            $sel = @($wc.Apps.Lv.CheckedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un element.", "GameBoost") | Out-Null; return }
            $tab = $wc.Apps.Tab
            if ($tab -eq 'od') {
                if (@($sel | Where-Object { $_.Kind -eq 'onedrive' }).Count -eq 0) { return }
                $wc.Page = $null; & $navTo 'winget'; & $setStatus "Coche OneDrive dans la liste puis 'Installer la selection'." $cText; return
            }
            if ($tab -eq 'apps') {
                $plist = @(Get-GBPersistList)
                $rm = @($sel | ForEach-Object { $_.Name })
                if (@($plist | Where-Object { $rm -contains $_ }).Count -gt 0) {
                    try { Set-GBPersistList @($plist | Where-Object { $rm -notcontains $_ }); Log ("Config Windows : retire de la suppression persistante -> " + ($rm -join ", ")) } catch {}
                }
                $noStore = @($sel | Where-Object { -not $_.Store })
                $ok = @($sel | Where-Object { $_.Store })
                foreach ($a in @($ok | Select-Object -First 5)) { try { Start-Process ("ms-windows-store://search/?query=" + [uri]::EscapeDataString($a.Label)) } catch {} }
                $m = ""
                if ($ok.Count -gt 0) { $m += "Le Microsoft Store s'ouvre sur : " + (@($ok | ForEach-Object { $_.Label }) -join ", ") + ". Clique 'Obtenir' pour la reinstaller." }
                if ($noStore.Count -gt 0) { $m += "`r`n`r`nImpossible a reinstaller (retirees du Store par Microsoft) : " + (@($noStore | ForEach-Object { $_.Label }) -join ", ") }
                if ($m) { [System.Windows.Forms.MessageBox]::Show($m, "GameBoost") | Out-Null }
                $wc.Apps.Data.Remove('apps'); & $render
                return
            }
            $todo = @($sel | Where-Object { -not $_.Installed })
            if ($todo.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Les elements coches sont deja installes.", "GameBoost") | Out-Null; return }
            $q = "Reinstaller " + $todo.Count + " element(s) ? (telechargement via Windows Update, internet necessaire, quelques minutes)`r`n`r`n- " + (@($todo | ForEach-Object { $_.Label }) -join "`r`n- ")
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Question") -ne "Yes") { return }
            & $startAction @{ Kind = $tab; Op = 'add'; Verb = 'Installation'; Names = @($todo | ForEach-Object { $_.Names[0] }) }
        })
        & $loadData
    }
    $startAction = {
        param($job)
        Log ("Config Windows : " + $job.Verb + " (" + $job.Kind + ") -> " + (@($job.Names) -join ", "))
        $wc.Sync = [hashtable]::Synchronized(@{ Status = "Preparation..."; Done = $false; Error = $null; Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
        $wc.Mode = 'action|' + $job.Kind
        $panel.Enabled = $false; $nav.Enabled = $false
        $wc.Task = Start-BackgroundTask $Script:WinAppsActionScript $wc.Sync $job
        $poll.Start()
    }

    $renderWinget = {
        param($pg)
        if (-not $wc.Wg.Path) { $wc.Wg.Path = Find-GBWinget }
        if (-not $wc.Wg.Path) {
            $l = & $mkPanelLbl ("WinGet (Gestionnaire de paquets Windows) n'est pas installe sur ce PC. Il fait partie de 'Programme d'installation d'application' du Microsoft Store " +
                                "(deja present sur Windows 10 recent et Windows 11).") 0 0 760 60 $cYellow "Top, Left, Right"
            $b = & $mkPanelBtn "Installer depuis le Microsoft Store" 0 ([int]($panel.ClientSize.Height / $sc) - 70) 280 $cGreen
            $b.Anchor = "Top, Left"
            $b.Add_Click({ Start-Process 'ms-windows-store://pdp/?productid=9NBLGGH4NNS1' })
            return
        }
        $cats = @('Toutes') + @($Script:WingetCatalog | ForEach-Object { $_.C } | Select-Object -Unique)
        $cb = New-GBComboCtl; $cb.DropDownStyle = "DropDownList"; $cb.FlatStyle = "Flat"; $cb.BackColor = $cDeep; $cb.ForeColor = $cText; Set-GBDarkCombo $cb
        $cb.Location = New-Object System.Drawing.Point(0, 0); $cb.Size = New-Object System.Drawing.Size([int](230 * $sc), [int](24 * $sc))
        foreach ($c in $cats) { [void]$cb.Items.Add($c) }
        $cb.SelectedItem = $wc.Wg.Cat; if ($cb.SelectedIndex -lt 0) { $cb.SelectedIndex = 0 }
        $panel.Controls.Add($cb)
        $search = New-Object System.Windows.Forms.TextBox
        $search.Location = New-Object System.Drawing.Point([int](240 * $sc), 0); $search.Size = New-Object System.Drawing.Size([int](240 * $sc), [int](24 * $sc))
        $search.BackColor = $cPanel; $search.ForeColor = $cText; $search.BorderStyle = "FixedSingle"; $search.Text = [string]$wc.Wg.Filter
        $tip.SetToolTip($search, "Filtrer par nom")
        $panel.Controls.Add($search)
        $bRef = New-GBButtonCtl; $bRef.Text = "Actualiser l'etat"; $bRef.Size = New-Object System.Drawing.Size([int](150 * $sc), [int](26 * $sc))
        $bRef.Location = New-Object System.Drawing.Point(($panel.ClientSize.Width - $bRef.Width), 0); $bRef.Anchor = "Top, Right"
        $panel.Controls.Add($bRef)
        $lv = & $mkList @(@('Etat', 120), @('Logiciel', 260), @('Categorie', 190), @('Identifiant WinGet', 230)) ([int](34 * $sc)) ([int](94 * $sc))
        $wc.Wg.Lv = $lv
        $bIns = & $mkPanelBtn "Installer la selection" 0 86 200 $cGreen
        $bUn = & $mkPanelBtn "Desinstaller la selection" 208 86 200 $cRed
        $bSite = & $mkPanelBtn "Site officiel" 416 86 140 $null
        $lblW = & $mkPanelLbl "Les logiciels sont telecharges depuis les sources officielles des editeurs, en arriere-plan (sans assistant quand c'est possible). Double-clic = site officiel." 0 ($panel.ClientSize.Height - [int](48 * $sc)) 780 44 $cMuted "Bottom, Left, Right"
        $null = & $mkPanelLbl "<- filtrer" 490 ([int](3 * $sc)) 120 20 $cMuted $null
        $fillW = {
            $lv = $wc.Wg.Lv; $q = ([string]$wc.Wg.Filter).ToLower(); $cat = $wc.Wg.Cat
            $lv.BeginUpdate(); $lv.Items.Clear()
            foreach ($a in $Script:WingetCatalog) {
                if ($cat -ne 'Toutes' -and $a.C -ne $cat) { continue }
                if ($q -and ($a.N.ToLower().IndexOf($q) -lt 0) -and ($a.Id.ToLower().IndexOf($q) -lt 0)) { continue }
                $st = "..."; $col = $cMuted
                if ($null -ne $wc.Wg.Ids) { if ($wc.Wg.Ids -contains $a.Id) { $st = "* Installe"; $col = $cGreen } else { $st = "o Non installe"; $col = $cText } }
                if ($wc.Wg.State -and $wc.Wg.State.ContainsKey($a.Id)) { $st = $wc.Wg.State[$a.Id]; $col = $cYellow }
                $li = New-Object System.Windows.Forms.ListViewItem($st)
                [void]$li.SubItems.Add($a.N); [void]$li.SubItems.Add($a.C); [void]$li.SubItems.Add($a.Id)
                $li.ForeColor = $col; $li.Tag = $a
                [void]$lv.Items.Add($li)
            }
            $lv.EndUpdate()
        }
        $wc.Wg.Fill = $fillW
        $cb.Add_SelectedIndexChanged({ $wc.Wg.Cat = [string]$this.SelectedItem; & $wc.Wg.Fill })
        $search.Add_TextChanged({ $wc.Wg.Filter = $this.Text; & $wc.Wg.Fill })
        $openSite = { $sel = @($wc.Wg.Lv.SelectedItems) + @($wc.Wg.Lv.CheckedItems); if ($sel.Count -gt 0) { Start-Process $sel[0].Tag.U } }
        $lv.Add_DoubleClick($openSite)
        $bSite.Add_Click($openSite)
        $scanW = {
            if ($wc.Task) { return }
            & $setStatus "Lecture des logiciels installes avec WinGet (10 a 30 s)..." $cText
            $wc.Wg.Ids = $null; & $wc.Wg.Fill
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Ids = $null; Modern = (Get-GBWingetModern $wc.Wg.Path) })
            $wc.Mode = 'wgscan'; $wc.Task = Start-BackgroundTask $Script:WingetScanScript $wc.Sync $wc.Wg.Path; $poll.Start()
        }
        $bRef.Add_Click($scanW)
        $wc.Wg.Run = {
            param($op)
            if ($wc.Task) { return }
            $sel = @($wc.Wg.Lv.CheckedItems | ForEach-Object { $_.Tag })
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un logiciel.", "GameBoost") | Out-Null; return }
            if ($null -ne $wc.Wg.Ids) {
                if ($op -eq 'install') { $sel = @($sel | Where-Object { $wc.Wg.Ids -notcontains $_.Id }) } else { $sel = @($sel | Where-Object { $wc.Wg.Ids -contains $_.Id }) }
            }
            if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Rien a faire : les logiciels coches sont deja dans cet etat.", "GameBoost") | Out-Null; return }
            $verb = "Installer"; if ($op -ne 'install') { $verb = "Desinstaller" }
            $q = $verb + " " + $sel.Count + " logiciel(s) ?`r`n`r`n- " + (@($sel | ForEach-Object { $_.N + "  (" + $_.Id + ")" }) -join "`r`n- ")
            if ($op -eq 'install') { $q += "`r`n`r`nTelechargement depuis la source officielle de chaque editeur (WinGet). Tu acceptes leurs conditions d'utilisation." }
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Logiciels", "YesNo", "Question") -ne "Yes") { return }
            $wc.Wg.State = @{}; foreach ($a in $sel) { $wc.Wg.State[$a.Id] = "en attente..." }
            & $wc.Wg.Fill
            Log ("Config Windows : WinGet " + $op + " -> " + (@($sel | ForEach-Object { $_.Id }) -join ", "))
            $wc.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Current = $null; Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
            $wc.Mode = 'wgrun'; $nav.Enabled = $false
            $wc.Task = Start-BackgroundTask $Script:WingetRunScript $wc.Sync @{ Op = $op; Ids = @($sel | ForEach-Object { $_.Id }); Wg = $wc.Wg.Path; Modern = (Get-GBWingetModern $wc.Wg.Path) }
            $poll.Start()
        }
        $bIns.Add_Click({ & $wc.Wg.Run 'install' })
        $bUn.Add_Click({ & $wc.Wg.Run 'uninstall' })
        & $fillW
        if ($null -eq $wc.Wg.Ids) { & $scanW }
    }

    # ====================== Fil d'arriere-plan : suivi ======================
    $poll = New-Object System.Windows.Forms.Timer
    $poll.Interval = 400
    $poll.Add_Tick({
        if (-not $wc.Sync) { $poll.Stop(); return }
        $s = $wc.Sync
        if ($wc.Mode -eq 'wgrun') {
            if ($s.Current -and $wc.Wg.State) { $wc.Wg.State[$s.Current] = "en cours..." }
            foreach ($l in @($s.Lines)) { if ($wc.Wg.State.ContainsKey($l.Id)) { $wc.Wg.State.Remove($l.Id) } }
            & $setStatus ("WinGet : " + $s.Lines.Count + " termine(s)" + $(if ($s.Current) { " - en cours : " + $s.Current } else { "" })) $cText
            if (-not $s.Done) { if ($wc.Wg.Fill) { & $wc.Wg.Fill }; return }
        } elseif ($s.Status) { & $setStatus $s.Status $cText }
        if (-not $s.Done) { return }
        $poll.Stop()
        Stop-BackgroundTask $wc.Task; $wc.Task = $null; $wc.Sync = $null
        $mode = $wc.Mode; $wc.Mode = ''
        $panel.Enabled = $true; $nav.Enabled = $true
        if ($mode -like 'scan|*') {
            $tab = $mode.Substring(5)
            if ($s.Error) { & $setStatus ("Lecture impossible : " + $s.Error) $cRed; return }
            $wc.Apps.Data[$tab] = @{ Items = $s.Items; Prov = $s.Prov }
            if ($wc.Page.K -eq 'apps' -and $wc.Apps.Tab -eq $tab) { & $wc.Apps.Build; & $wc.Apps.Fill }
            & $setStatus ("" + @($wc.Apps.Rows).Count + " element(s)") $cMuted
        } elseif ($mode -eq 'appsremove' -or $mode -like 'action|*') {
            $ok = @($s.Lines | Where-Object { $_.Ok }).Count
            $bad = @($s.Lines | Where-Object { -not $_.Ok })
            $reboot = @($s.Lines | Where-Object { $_.Reboot }).Count -gt 0
            foreach ($l in $s.Lines) { $r = "ok"; if (-not $l.Ok) { $r = "echec : " + $l.Err }; Log ("Config Windows : " + $l.Name + " -> " + $r) }
            $res = "" + $ok + " element(s) traite(s)."
            if ($bad.Count -gt 0) { $res += "`r`n`r`nEchecs :`r`n" + (@($bad | ForEach-Object { "- " + $_.Name + " (" + $_.Err + ")" }) -join "`r`n") }
            if ($s.Error) { $res += "`r`n`r`nProbleme : " + $s.Error }
            if ($reboot) { $res += "`r`n`r`nRedemarre le PC pour terminer."; $wc.Need['reboot'] = $true }
            [System.Windows.Forms.MessageBox]::Show($res, "GameBoost - Config Windows") | Out-Null
            $k = 'apps'; if ($mode -like 'action|*') { $k = $mode.Substring(7) }
            [void]$wc.Apps.Data.Remove($k)
            & $render
        } elseif ($mode -eq 'upscan') {
            if ($s.Error) { & $setStatus ("WinGet : " + $s.Error) $cRed; $wc.Up.Items = @() } else { $wc.Up.Items = @($s.Items) }
            if ($wc.Page.K -eq 'updates' -and $wc.Up.Fill) { & $wc.Up.Fill }
        } elseif ($mode -eq 'uprun') {
            $bad = @($s.Lines | Where-Object { -not $_.Ok })
            foreach ($l in $s.Lines) { $r = "ok"; if (-not $l.Ok) { $r = Get-GBWingetErrorText $l.Code; if ($l.Err) { $r = $l.Err } }; Log ("Mise a jour " + $l.Id + " -> " + $r) }
            $res = "" + @($s.Lines | Where-Object { $_.Ok }).Count + " mise(s) a jour terminee(s)."
            if ($bad.Count -gt 0) { $res += "`r`n`r`nEchecs :`r`n" + (@($bad | ForEach-Object { "- " + $_.Id + " : " + $(if ($_.Err) { $_.Err } else { Get-GBWingetErrorText $_.Code }) }) -join "`r`n") }
            [System.Windows.Forms.MessageBox]::Show($res, "GameBoost - Mises a jour") | Out-Null
            $wc.Up.Items = $null
            if ($wc.Page.K -eq 'updates') { & $render }
        } elseif ($mode -eq 'cleanscan') {
            $wc.Clean.Sizes = $s.Sizes
            if ($wc.Page.K -eq 'clean' -and $wc.Clean.Fill) { & $wc.Clean.Fill }
            & $setStatus "Analyse terminee : coche ce que tu veux nettoyer." $cMuted
        } elseif ($mode -eq 'cleanrun') {
            $freed = [int64]0; foreach ($l in $s.Lines) { $freed += [int64]$l.Freed; Log ("Nettoyage : " + $l.L + " -> " + (Format-GBSize $l.Freed) + " liberes" + $(if ($l.Left -gt 0) { " (" + (Format-GBSize $l.Left) + " en cours d'utilisation, gardes)" } else { "" })) }
            $res = (Format-GBSize $freed) + " liberes."
            $kept = @($s.Lines | Where-Object { $_.Left -gt 1MB })
            if ($kept.Count -gt 0) { $res += "`r`n`r`nCertains fichiers sont utilises en ce moment et ont ete gardes (normal) :`r`n" + (@($kept | ForEach-Object { "- " + $_.L + " : " + (Format-GBSize $_.Left) }) -join "`r`n") }
            if ($s.Error) { $res += "`r`n`r`nProbleme : " + $s.Error }
            [System.Windows.Forms.MessageBox]::Show($res, "GameBoost - Nettoyage") | Out-Null
            $wc.Clean.Sizes = $null
            if ($wc.Page.K -eq 'clean') { & $render }
        } elseif ($mode -eq 'wgscan') {
            if ($s.Error) { & $setStatus ("WinGet : " + $s.Error) $cRed; $wc.Wg.Ids = @() } else { $wc.Wg.Ids = @($s.Ids); & $setStatus ("" + @($Script:WingetCatalog | Where-Object { $wc.Wg.Ids -contains $_.Id }).Count + " logiciel(s) du catalogue deja installe(s).") $cMuted }
            if ($wc.Page.K -eq 'winget' -and $wc.Wg.Fill) { & $wc.Wg.Fill }
        } elseif ($mode -eq 'wgrun') {
            $wc.Wg.State = @{}
            $bad = @($s.Lines | Where-Object { -not $_.Ok })
            foreach ($l in $s.Lines) { $r = "ok"; if (-not $l.Ok) { $r = Get-GBWingetErrorText $l.Code; if ($l.Err) { $r = $l.Err } }; Log ("Config Windows : WinGet " + $l.Id + " -> " + $r) }
            $res = "" + @($s.Lines | Where-Object { $_.Ok }).Count + " logiciel(s) traite(s)."
            if ($bad.Count -gt 0) { $res += "`r`n`r`nEchecs :`r`n" + (@($bad | ForEach-Object { "- " + $_.Id + " : " + $(if ($_.Err) { $_.Err } else { Get-GBWingetErrorText $_.Code }) }) -join "`r`n") }
            [System.Windows.Forms.MessageBox]::Show($res, "GameBoost - Logiciels") | Out-Null
            $wc.Wg.Ids = $null
            if ($wc.Page.K -eq 'winget') { & $render }
        }
    })

    # ====================== Affichage d'une page / recherche ======================
    $render = {
        $pg = $wc.Page
        if ($wc.SearchMode) { $pg = @{ K = 'search'; T = 'Resultats de recherche' } }
        if (-not $pg) { return }
        $listPage = (@('apps', 'winget', 'startup', 'clean', 'updates') -contains $pg.Kind)
        & $clearFlow
        & $clearPanel
        $flow.Visible = -not $listPage; $panel.Visible = $listPage
        if ($listPage) {
            $flow.ResumeLayout()
            $panel.SuspendLayout()
            switch ($pg.Kind) {
                'apps' { & $renderApps $pg }
                'winget' { & $renderWinget $pg }
                'startup' { & $renderStartup $pg }
                'clean' { & $renderClean $pg }
                'updates' { & $renderUpdates $pg }
            }
            $panel.ResumeLayout()
            Set-GBDarkTree $panel
            return
        }
        if ($pg.K -eq 'search') {
            $q = Get-GBNorm $txtSearch.Text
            $hits = @($Script:WinTweaks | Where-Object { (Test-WinCfgVisible $_) -and ((Get-GBNorm ($_.Name + ' ' + $_.Desc + ' ' + $_.Group)) -like ('*' + $q + '*')) })
            $flow.Controls.Add((& $makeHeader ("Recherche : '" + $txtSearch.Text + "'") ("" + $hits.Count + " reglage(s) trouve(s) dans toutes les pages.") ""))
            $byPage = @{}; foreach ($p in $Script:WinCfgPages) { if ($p.K) { $byPage[$p.K] = $p.T } }
            $cur = $null
            foreach ($t in $hits) {
                if ($t.Page -ne $cur) { $cur = $t.Page; $flow.Controls.Add((& $makeGroup ([string]$byPage[$cur]))) }
                $flow.Controls.Add((& $makeRow $t))
            }
        } elseif (-not $pg.Kind -and $wc.PageCache.ContainsKey($pg.K)) {
            # Deja construite : on la remet telle quelle (quelques millisecondes au lieu de plusieurs centaines)
            $ctls = $wc.PageCache[$pg.K]; [void]$wc.PageCache.Remove($pg.K)
            $flow.Controls.AddRange([System.Windows.Forms.Control[]]$ctls)
            & $resyncRows $ctls
            $wc.FlowKey = $pg.K
        } else {
            $note = $persistNote; if (@('tools', 'backup', 'health') -contains $pg.Kind) { $note = "" }
            $flow.Controls.Add((& $makeHeader $pg.T $pg.D $note))
            switch ($pg.Kind) {
                'power' { & $renderPower $pg }
                'network' { & $renderNetwork $pg }
                'health' { & $renderHealth $pg }
                'tools' { & $renderTools $pg }
                'backup' { & $renderBackup $pg }
                default { & $renderTweaks $pg }
            }
            if (-not $pg.Kind) { $wc.FlowKey = $pg.K }
        }
        & $fitRows
        $flow.ResumeLayout()
        Set-GBDarkTree $flow
        $flow.AutoScrollPosition = New-Object System.Drawing.Point(0, 0)
        # Simple changement de page : rien n'a change dans Windows, le bilan du bas reste valable
        if (-not $wc.NavOnly) { & $updateStatus }
    }
    $navTo = { param($key) for ($i = 0; $i -lt $nav.Items.Count; $i++) { if ($nav.Items[$i].K -eq $key) { $nav.SelectedIndex = $i; return } } }
    $nav.add_SelectedIndexChanged({
        $i = $nav.SelectedIndex
        if ($i -lt 0) { return }
        $p = $nav.Items[$i]
        if ($p.H) { if ($i + 1 -lt $nav.Items.Count) { $nav.SelectedIndex = $i + 1 }; return }
        if ($wc.Task) { & $setStatus "Une operation est en cours : patiente jusqu'a la fin." $cYellow; return }
        $wc.SearchMode = $false
        if ($txtSearch.Text) { $wc.NoSearch = $true; $txtSearch.Text = ""; $wc.NoSearch = $false }
        $wc.Page = $p
        $wc.NavOnly = $true
        try { & $render } finally { $wc.NavOnly = $false }
    })
    # Recherche : petite pause apres la frappe pour ne pas tout redessiner a chaque lettre
    $searchTimer = New-Object System.Windows.Forms.Timer; $searchTimer.Interval = 300
    $searchTimer.Add_Tick({
        $searchTimer.Stop()
        if ($wc.Task) { return }
        $wc.NavOnly = $true
        try {
            if ((Get-GBNorm $txtSearch.Text).Length -ge 2) { $wc.SearchMode = $true; $nav.ClearSelected(); & $render }
            elseif ($wc.SearchMode) { $wc.SearchMode = $false; if (-not $wc.Page) { $wc.Page = @($Script:WinCfgPages | Where-Object { $_.K -eq 'privacy' })[0] }; & $render }
        } finally { $wc.NavOnly = $false }
    })
    $txtSearch.Add_TextChanged({ $lblSearchHint.Visible = ($txtSearch.Text.Length -eq 0); if ($wc.NoSearch) { return }; $searchTimer.Stop(); $searchTimer.Start() })

    # Curseur lache : liste des changements, confirmation, puis application
    Add-SliderCommit $lvSlider {
        if ($wc.Task) { & $refreshLevel; return }
        $lvl = [int]$lvSlider.Value
        $plan = @(Get-WinCfgLevelPlan $lvl)
        if ($plan.Count -eq 0) { $Script:Config.WinLevel = $lvl; Save-Config; & $setStatus ("Windows est deja au niveau '" + $Script:WinLevels[$lvl].L + "'.") $cGreen; & $refreshLevel; return }
        $q = "Passer Windows au niveau '" + $Script:WinLevels[$lvl].L + "' ?`r`n`r`n" + $Script:WinLevels[$lvl].D + "`r`n`r`n" + $plan.Count + " changement(s) :`r`n- " +
             ((@($plan | ForEach-Object { $_.Txt }) | Select-Object -First 28) -join "`r`n- ")
        if ($plan.Count -gt 28) { $q += "`r`n... et " + ($plan.Count - 28) + " autre(s)" }
        $warns = @($plan | Where-Object { $_.Warn } | ForEach-Object { "- " + $_.T.Name + " : " + $_.Warn })
        if ($warns.Count -gt 0) { $q += "`r`n`r`nAttention :`r`n" + ($warns -join "`r`n") }
        $q += "`r`n`r`nLes valeurs d'origine sont gardees : 'Tout annuler' ou le niveau 'Avant GameBoost' les remettent."
        $icon = "Question"; if ($warns.Count -gt 0) { $icon = "Warning" }
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Niveau d'optimisation Windows", "YesNo", $icon) -ne "Yes") { & $refreshLevel; return }
        & $ensureRp
        $d.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        $fail = @()
        foreach ($c in $plan) {
            try {
                switch ($c.Op) {
                    'on' { Set-WinCfgTweak $c.T $true }
                    'off' { Set-WinCfgTweak $c.T $false }
                    'choice' { Set-WinCfgChoice $c.T ([int]$c.Idx) }
                    'restore' { [void](Restore-WinCfgChoiceOriginal $c.T) }
                }
                if ($c.T.R) { $wc.Need[$c.T.R] = $true }
            } catch { $fail += ($c.T.Name + " : " + $_.Exception.Message) }
        }
        $d.Cursor = [System.Windows.Forms.Cursors]::Default
        $Script:Config.WinLevel = $lvl; Save-Config
        Log ("Config Windows : niveau '" + $Script:WinLevels[$lvl].L + "' -> " + ($plan.Count - $fail.Count) + " changement(s), " + $fail.Count + " echec(s)")
        foreach ($f in $fail) { Log ("Config Windows : echec " + $f) }
        & $render
        if ($fail.Count -gt 0) { [System.Windows.Forms.MessageBox]::Show(("Certains reglages n'ont pas pu etre appliques :`r`n`r`n" + ($fail -join "`r`n")), "GameBoost") | Out-Null }
    }

    $btnReco.Add_Click({
        $todo = New-Object System.Collections.ArrayList
        foreach ($t in @($Script:WinTweaks | Where-Object { $_.Type -ne 'action' -and (Test-WinCfgVisible $_) })) {
            try {
                if ($t.Type -eq 'choice') { if ($null -ne $t.RecoIdx -and (Get-WinCfgChoice $t) -ne [int]$t.RecoIdx) { [void]$todo.Add($t) } }
                elseif ($t.Reco -and -not (Get-WinCfgState $t)) { [void]$todo.Add($t) }
            } catch {}
        }
        if ($todo.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Tous les reglages conseilles sont deja appliques.", "GameBoost") | Out-Null; return }
        $q = "Appliquer " + $todo.Count + " reglage(s) conseille(s) ?`r`n`r`n- " + (@($todo | ForEach-Object { if ($_.Type -eq 'choice') { $_.Name + " : " + $_.Opts[[int]$_.RecoIdx].L } else { $_.Name } }) -join "`r`n- ") +
             "`r`n`r`nRien d'autre n'est touche. 'Tout annuler' remet les valeurs d'origine."
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Config Windows", "YesNo", "Question") -ne "Yes") { return }
        & $ensureRp
        $fail = @()
        foreach ($t in $todo) {
            try {
                if ($t.Type -eq 'choice') { Set-WinCfgChoice $t ([int]$t.RecoIdx) } else { Set-WinCfgTweak $t $true }
                if ($t.R) { $wc.Need[$t.R] = $true }
            } catch { $fail += ($t.Name + " : " + $_.Exception.Message) }
        }
        Log ("Config Windows : " + ($todo.Count - $fail.Count) + " reglage(s) conseille(s) applique(s)")
        foreach ($f in $fail) { Log ("Config Windows : echec " + $f) }
        & $render
        if ($fail.Count -gt 0) { [System.Windows.Forms.MessageBox]::Show(("Certains reglages n'ont pas pu etre appliques :`r`n`r`n" + ($fail -join "`r`n")), "GameBoost") | Out-Null }
    })
    $btnUndo.Add_Click({
        $n = @((Get-WinCfgBackup).Keys).Count
        if ($n -eq 0) { [System.Windows.Forms.MessageBox]::Show("Aucun reglage Windows n'a ete modifie par GameBoost : rien a annuler.", "GameBoost") | Out-Null; return }
        $q = "Remettre les " + $n + " valeur(s) modifiee(s) par Config Windows exactement comme avant ?`r`n`r`n(Les applis supprimees ne sont pas reinstallees : utilise le Microsoft Store. La suppression persistante s'arrete dans 'Applis Windows'.)"
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Config Windows", "YesNo", "Question") -ne "Yes") { return }
        $r = Undo-WinCfgAll
        $wc.Need['explorer'] = $true
        Log ("Config Windows : " + $r.Ok + " valeur(s) d'origine remise(s), " + $r.Fail + " echec(s)")
        & $render
    })
    $btnExp.Add_Click({ $btnExp.Enabled = $false; Restart-GBExplorer; [void]$wc.Need.Remove('explorer'); $btnExp.Enabled = $true; & $updateStatus })
    $d.Add_FormClosing({
        param($sender, $e)
        if ($wc.Task) { [System.Windows.Forms.MessageBox]::Show("Une operation est en cours : patiente jusqu'a la fin.", "GameBoost") | Out-Null; $e.Cancel = $true }
    })
    $d.Add_Shown({
        # Cartes reseau et sante du PC (requetes lentes) lues en arriere-plan pendant que tu regardes la 1re page
        $wc.PreSync = [hashtable]::Synchronized(@{ Done = $false; NetDone = $false; HealthDone = $false
                                                   NetSrc = ${function:Get-GBNetAdapters}.ToString(); HealthSrc = $Script:HealthDataScript.ToString() })
        $wc.Pre = Start-BackgroundTask $Script:CfgPrefetchScript $wc.PreSync ([bool]$Script:IsLaptop)
        & $navTo 'privacy'
        $d.Refresh()
        & $updateStatus
        foreach ($p in $Script:WinCfgPages) { if ($p.K -and -not $p.Kind -and $p.K -ne 'privacy') { $wc.Warm.Pages.Enqueue($p) } }
        $warmTimer.Start()
    })
    # Pages de reglages preparees a l'avance, 2 lignes a la fois quand tu ne cliques pas : la 1re visite est instantanee
    $wc.Warm = @{ Pages = New-Object System.Collections.Queue; Cur = $null; Items = $null; I = 0; Grp = $null; List = $null }
    $warmTimer = New-Object System.Windows.Forms.Timer; $warmTimer.Interval = 60
    $warmTimer.Add_Tick({
        if ($wc.Task -or [System.Windows.Forms.Control]::MouseButtons -ne [System.Windows.Forms.MouseButtons]::None) { return }
        $w = $wc.Warm
        try {
            if (-not $w.Scrolled) {
                # 1er defilement de la liste de gauche (~0,25 s chez Windows) fait ici, invisible : la suite reste instantanee
                $w.Scrolled = $true; $top = $nav.TopIndex
                $nav.TopIndex = $nav.Items.Count - 1; $nav.TopIndex = $top
                return
            }
            if (-not $w.Cur) {
                while ($w.Pages.Count -gt 0) { $p = $w.Pages.Dequeue(); if (-not $wc.PageCache.ContainsKey($p.K) -and $wc.FlowKey -ne $p.K) { $w.Cur = $p; break } }
                if (-not $w.Cur) { $warmTimer.Stop(); return }
                $w.Items = @($Script:WinTweaks | Where-Object { $_.Page -eq $w.Cur.K -and (Test-WinCfgVisible $_) })
                $w.I = 0; $w.Grp = $null; $w.List = New-Object System.Collections.ArrayList
                [void]$w.List.Add((& $makeHeader $w.Cur.T $w.Cur.D $persistNote))
            }
            $n = 0
            while ($w.I -lt $w.Items.Count -and $n -lt 2) {
                $t = $w.Items[$w.I]
                if ($t.Group -and $t.Group -ne $w.Grp) { $w.Grp = $t.Group; [void]$w.List.Add((& $makeGroup $w.Grp)) }
                $r = & $makeRow $t; $r.CreateControl(); [void]$w.List.Add($r); $w.I++; $n++   # fenetres Windows creees maintenant, pas au 1er affichage
            }
            if ($w.I -ge $w.Items.Count) {
                # Page ouverte entre-temps (deja construite par l'affichage) : la copie preparee est liberee
                if ($wc.FlowKey -eq $w.Cur.K -or $wc.PageCache.ContainsKey($w.Cur.K)) { foreach ($c in $w.List) { $c.Dispose() } }
                else { $wc.PageCache[$w.Cur.K] = $w.List.ToArray() }
                $w.Cur = $null; $w.List = $null
            }
        } catch { $warmTimer.Stop(); Log ("Config Windows : preparation des pages arretee (" + $_.Exception.Message + " @ " + $_.InvocationInfo.ScriptLineNumber + ")") }
    })
    $Script:BusyDepth++
    try { [void]$d.ShowDialog($form) }
    finally {
        $poll.Stop(); $poll.Dispose(); $searchTimer.Stop(); $searchTimer.Dispose(); $warmTimer.Stop(); $warmTimer.Dispose()
        if ($wc.Warm.List) { foreach ($c in $wc.Warm.List) { try { $c.Dispose() } catch {} } }
        if ($wc.Task) { Stop-BackgroundTask $wc.Task }
        if ($wc.Pre) { if (-not $wc.PreSync.Done) { try { $wc.Pre.PS.Stop() } catch {} }; try { $wc.Pre.PS.Dispose() } catch {} }
        # Pages gardees en cache (hors fenetre) : liberees avec elle
        foreach ($ctls in @($wc.PageCache.Values)) { foreach ($c in @($ctls)) { try { $c.Dispose() } catch {} } }
        $wc.PageCache = @{}
        $d.Dispose()
        $Script:BusyDepth--
        Update-BoostButton
        if ($wc.Need['reboot']) { Log "Config Windows : redemarre le PC pour que tous les reglages prennent effet" }
    }
}

# --- Desinstallation profonde (desinstalleur officiel + recherche de tous les restes) ----
# 1. point de restauration, 2. desinstalleur officiel du programme, 3. recherche des restes (dossiers, registre, raccourcis,
# services, taches planifiees, demarrage auto, pare-feu), 4. tu choisis ce qui est supprime.
# Fichiers -> Corbeille ; registre, services et taches -> sauvegardes dans %APPDATA%\GameBoost\desinstallations.
$Script:UninstallDir = Join-Path $AppDir "desinstallations"
$Script:GenericExe = @('uninstall', 'uninst', 'unins000', 'unins001', 'uninstaller', 'update', 'updater', 'setup', 'install', 'installer', 'helper',
    'crashreporter', 'crashpad_handler', 'crashhandler', 'launcher', 'elevate', 'elevation_service', 'notification_helper', 'maintenanceservice',
    'squirrel', 'createdump', 'vc_redist.x64', 'vc_redist.x86', 'dxsetup', 'cmd', 'unitycrashhandler64', 'unitycrashhandler32', 'ue4prereqsetup_x64',
    'cefsharp.browsersubprocess', 'qtwebengineprocess', 'svchost', 'rundll32', 'msiexec', 'explorer', 'conhost', 'dllhost',
    # executables embarques par beaucoup de programmes : ne designent jamais UN programme
    'python', 'pythonw', 'python3', 'py', 'pyw', 'java', 'javaw', 'node', 'electron', 'ffmpeg', 'ffprobe', '7z', '7za', 'curl', 'wget', 'git',
    'bash', 'sh', 'perl', 'ruby', 'php', 'dotnet', 'nw', 'chrome', 'msedge', 'msedgewebview2', 'crashpad', 'vulkaninfo', 'powershell', 'pwsh', 'regsvr32')
$Script:GenericNames = @('microsoft', 'windows', 'common', 'commonfiles', 'program', 'programs', 'programfiles', 'programfilesx86', 'programdata', 'temp',
    'tmp', 'cache', 'caches', 'data', 'user', 'users', 'app', 'apps', 'application', 'applications', 'software', 'tools', 'tool', 'games', 'game',
    'packages', 'package', 'local', 'roaming', 'locallow', 'google', 'intel', 'nvidia', 'nvidiacorporation', 'amd', 'realtek', 'apple', 'adobe',
    'default', 'public', 'system', 'system32', 'drivers', 'driver', 'installer', 'installers', 'setup', 'update', 'updates', 'logs', 'log', 'config',
    'settings', 'documents', 'downloads', 'desktop', 'music', 'videos', 'pictures', 'mygames', 'savedgames', 'crashdumps', 'd3dscache',
    'packagecache', 'classes', 'policies', 'wow6432node', 'clients', 'registeredapplications', 'odbc', 'partner', 'launcher', 'client', 'service',
    'services', 'helper', 'uninstall', 'runtime', 'redist', 'redistributable', 'plugins', 'plugin', 'shared', 'microsoftcorporation', 'gamebar')
$Script:SensitiveApps = '(?i)visual c\+\+|redistributable|\.net (framework|runtime|desktop)|directx|webview2|runtime|driver|pilote|chipset|nvidia|amd software|radeon|realtek|intel\(r\)|microsoft edge|windows sdk|vanguard|easy ?anti.?cheat|battleye|faceit|gaming services'

function Get-GBNorm($s) { return ([string]$s).ToLower() -replace '[^a-z0-9]', '' }
function Get-GBCleanName($n) {
    $s = [string]$n
    $s = $s -replace '\(.*?\)|\[.*?\]', ' '
    $s = $s -replace '(?i)\b(x64|x86|64-bit|32-bit|amd64|arm64)\b', ' '
    $s = $s -replace '\s+v?\d+([\.\-_]\d+)*\b.*$', ''
    return $s.Trim(' -_.,'.ToCharArray())
}
function Get-GBCleanPublisher($p) {
    $s = ([string]$p) -replace '[,\.]', ' '
    $s = $s -replace '(?i)\b(inc|llc|ltd|limited|corporation|corp|gmbh|sa|sas|sarl|co|company|ag|bv|srl|ab|oy|plc)\b', ' '
    return ($s -replace '\s+', ' ').Trim()
}
function Test-GBPathExists($p) {
    if (-not $p) { return $false }
    try { return [bool](Test-Path -LiteralPath $p) } catch { return $false }
}
function Test-GBUnder($child, $parent) {
    if (-not $child -or -not $parent) { return $false }
    $c = ([string]$child).TrimEnd('\'); $p = ([string]$parent).TrimEnd('\')
    return ($c -ieq $p -or $c.StartsWith($p + '\', [StringComparison]::OrdinalIgnoreCase))
}
function Split-GBCommand($cmd) {
    $c = ([string]$cmd).Trim()
    if ($c.StartsWith('"')) { $i = $c.IndexOf('"', 1); if ($i -gt 0) { return @($c.Substring(1, $i - 1), $c.Substring($i + 1).Trim()) } }
    $m = [regex]::Match($c, '^(.+?\.exe)(\s+.*)?$', 'IgnoreCase')
    if ($m.Success) { return @($m.Groups[1].Value, $m.Groups[2].Value.Trim()) }
    return @($c, '')
}

# Dossiers qu'on ne supprime JAMAIS (ni eux, ni un dossier qui les contient)
function Get-GBForbiddenPaths {
    if ($Script:GBForbidden) { return $Script:GBForbidden }
    $docs = [Environment]::GetFolderPath('MyDocuments')
    $l = New-Object System.Collections.ArrayList
    foreach ($p in @($env:windir, ($env:SystemDrive + '\'), $env:ProgramFiles, ${env:ProgramFiles(x86)}, $env:ProgramW6432, $env:ProgramData, $env:APPDATA, $env:LOCALAPPDATA,
                     (Join-Path $env:LOCALAPPDATA 'Programs'), (Join-Path $env:LOCALAPPDATA 'Packages'), (Join-Path $env:LOCALAPPDATA 'Microsoft'), (Join-Path $env:APPDATA 'Microsoft'),
                     (Join-Path $env:ProgramData 'Microsoft'), (Join-Path $env:USERPROFILE 'AppData'), (Join-Path $env:USERPROFILE 'AppData\LocalLow'), $env:USERPROFILE, $env:PUBLIC,
                     (Split-Path -Parent $env:USERPROFILE), $env:TEMP, $env:TMP, $docs, (Join-Path $docs 'My Games'), (Join-Path $env:USERPROFILE 'Saved Games'),
                     [Environment]::GetFolderPath('Desktop'), [Environment]::GetFolderPath('CommonDesktopDirectory'), [Environment]::GetFolderPath('CommonDocuments'),
                     [Environment]::GetFolderPath('StartMenu'), [Environment]::GetFolderPath('Programs'), [Environment]::GetFolderPath('CommonStartMenu'),
                     [Environment]::GetFolderPath('CommonPrograms'), [Environment]::GetFolderPath('CommonProgramFiles'), [Environment]::GetFolderPath('CommonProgramFilesX86'),
                     $AppDir, $PSScriptRoot, (Join-Path $env:ProgramData 'GameBoost'))) {
        if ($p) { try { [void]$l.Add(([IO.Path]::GetFullPath($p)).TrimEnd('\')) } catch {} }
    }
    $Script:GBForbidden = $l
    return $l
}
function Test-GBProtectedPath($p, $otherDirs) {
    try { $full = ([IO.Path]::GetFullPath([string]$p)).TrimEnd('\') } catch { return $true }
    if ($full.Length -le 3) { return $true }
    if ($env:windir -and (Test-GBUnder $full $env:windir)) { return $true }
    foreach ($f in (Get-GBForbiddenPaths)) {
        if ($full -ieq $f -or $f.StartsWith($full + '\', [StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    foreach ($o in @($otherDirs)) { if ($o -and (Test-GBUnder $o $full)) { return $true } }   # contient un AUTRE programme installe
    return $false
}

# Dossier d'installation : InstallLocation, sinon dossier de l'icone ou du desinstalleur (jamais un dossier systeme)
function Get-GBAppFolder($app) {
    $cands = @()
    if ($app.InstallLocation) { $cands += [string]$app.InstallLocation }
    foreach ($s in @($app.Icon, $app.Uninstall)) {
        if (-not $s) { continue }
        $exe = ((Split-GBCommand $s)[0]) -replace ',\s*-?\d+$', ''
        if ($exe -and $exe -notmatch '(?i)msiexec|rundll32') {
            $dir = Split-Path -Parent $exe
            if (-not $dir) { continue }
            if ((Split-Path -Leaf $dir) -match '(?i)^_?(uninst|uninstall|uninstaller)$') { $dir = Split-Path -Parent $dir }
            $cands += $dir
        }
    }
    foreach ($c in $cands) {
        try { $c = [Environment]::ExpandEnvironmentVariables(([string]$c).Trim().Trim('"')) } catch { continue }
        if (-not $c -or $c.Length -lt 4 -or $c -notmatch '^[A-Za-z]:\\') { continue }
        try { $c = ([IO.Path]::GetFullPath($c)).TrimEnd('\') } catch { continue }
        if ($c -match '(?i)\\(Installer|Package Cache|Temp|InstallShield Installation Information)(\\|$)') { continue }
        if (Test-GBProtectedPath $c @()) { continue }
        return $c
    }
    return $null
}

function Get-GBInstalledPrograms {
    $roots = @(
        @{ P = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall'; Scope = 'Tous les comptes' },
        @{ P = 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall'; Scope = 'Tous (32 bits)' },
        @{ P = 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall'; Scope = 'Ce compte' }
    )
    $list = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($r in $roots) {
        if (-not (Test-Path -LiteralPath $r.P)) { continue }
        foreach ($k in @(Get-ChildItem -LiteralPath $r.P -ErrorAction SilentlyContinue)) {
            try {
                $v = Get-ItemProperty -LiteralPath $k.PSPath -ErrorAction Stop
                $name = [string]$v.DisplayName
                if (-not $name) { continue }
                if ($v.SystemComponent -eq 1 -or $v.ParentKeyName -or ([string]$v.ReleaseType) -match 'Update|Hotfix') { continue }
                $un = [string]$v.UninstallString; $qu = [string]$v.QuietUninstallString
                if (-not $un -and -not $qu) { continue }
                $id = ($name + '|' + [string]$v.DisplayVersion).ToLower()
                if ($seen.ContainsKey($id)) { continue }
                $seen[$id] = $true
                $date = $null
                if ($v.InstallDate -match '^\d{8}$') { try { $date = [datetime]::ParseExact([string]$v.InstallDate, 'yyyyMMdd', $null) } catch {} }
                $size = 0; try { if ($v.EstimatedSize) { $size = [math]::Round([double]$v.EstimatedSize / 1024, 0) } } catch {}
                $app = [pscustomobject]@{
                    Kind = 'Win32'; Name = $name; Publisher = [string]$v.Publisher; Version = [string]$v.DisplayVersion; SizeMo = $size; Date = $date
                    InstallLocation = [string]$v.InstallLocation; Uninstall = $un; Quiet = $qu; Icon = [string]$v.DisplayIcon; Msi = ($v.WindowsInstaller -eq 1)
                    Key = $k.PSPath; NativeKey = $k.Name; KeyName = $k.PSChildName; Scope = $r.Scope; Dir = $null
                }
                $app.Dir = Get-GBAppFolder $app
                [void]$list.Add($app)
            } catch {}
        }
    }
    return $list
}

function Get-GBStoreApps {
    $skip = '^(Microsoft\.(WindowsStore|StorePurchaseApp|DesktopAppInstaller|GamingApp|GamingServices|Xbox.*|VCLibs.*|UI\.Xaml.*|NET\..*|WindowsAppRuntime.*|' +
            'Services\.Store.*|SecHealthUI|Windows\..*Experience.*|AAD\..*|AccountsControl|LockApp|Win32WebViewHost|.*Extension.*|.*Extensions|' +
            'ApplicationCompatibilityEnhancements|WidgetsPlatformRuntime|StartExperiencesApp|WindowsCalculator|Windows\.Photos|Paint|ScreenSketch|' +
            'WindowsNotepad|WindowsTerminal|Edge.*|MicrosoftEdge.*|Winget.*|OneDriveSync|CrossDevice|ZuneMusic)|' +
            'MicrosoftWindows\..*|windows\..*|.*WinAppRuntime.*|.*LanguageExperiencePack.*|NcsiUwpApp|c5e2524a-.*|E2A4F912-.*|F46D4000-.*|1527c705-.*)$'
    $friendly = @{}; foreach ($b in $Script:BloatApps) { $friendly[$b.N] = $b.L }
    $list = New-Object System.Collections.ArrayList
    foreach ($p in @(Get-AppxPackage -ErrorAction SilentlyContinue)) {
        try {
            if ($p.IsFramework -or $p.NonRemovable -or [string]$p.SignatureKind -eq 'System') { continue }
            if ($p.Name -match $skip) { continue }
            $nm = $friendly[$p.Name]
            if (-not $nm) { foreach ($k in $friendly.Keys) { if ($p.Name -like $k) { $nm = $friendly[$k]; break } } }
            if (-not $nm) { $nm = ($p.Name -replace '^[^\.]+\.', '') -creplace '([a-z])([A-Z])', '$1 $2' }
            $pub = [string]$p.Publisher; $m = [regex]::Match($pub, 'CN=([^,]+)'); if ($m.Success) { $pub = $m.Groups[1].Value.Trim('"') }
            if ($pub -match '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-') {
                # Certificat sans nom lisible : le nom de l'editeur est dans le manifeste de l'appli
                try { $mx = [xml](Get-Content -LiteralPath (Join-Path $p.InstallLocation 'AppxManifest.xml') -Raw -ErrorAction Stop); $dn = [string]$mx.Package.Properties.PublisherDisplayName
                      if ($dn -and $dn -notmatch '^ms-resource:') { $pub = $dn } else { $pub = '' } } catch { $pub = '' }
            }
            [void]$list.Add([pscustomobject]@{ Kind = 'Store'; Name = $nm; Publisher = $pub; Version = [string]$p.Version; SizeMo = 0; Date = $null
                                                PkgName = $p.Name; PkgFamily = $p.PackageFamilyName; Dir = [string]$p.InstallLocation; Scope = 'Microsoft Store' })
        } catch {}
    }
    return $list
}

# Tout ce qu'il faut savoir du programme AVANT de le desinstaller (apres, son dossier n'existe plus)
function New-GBUninstallContext($app, $allPrograms) {
    $ctx = @{ App = $app; Dir = $app.Dir; Sensitive = ($app.Name -match $Script:SensitiveApps -or $app.Publisher -match '(?i)^(NVIDIA|Advanced Micro|Intel|Realtek)') }
    $exes = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    $top = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    if ($ctx.Dir -and (Test-Path -LiteralPath $ctx.Dir)) {
        $n = 0
        foreach ($f in @(Get-ChildItem -LiteralPath $ctx.Dir -Filter *.exe -File -Recurse -Depth 2 -Force -ErrorAction SilentlyContinue)) {
            $b = $f.BaseName.ToLower()
            if ($Script:GenericExe -contains $b -or $b -match '^(unins\d+|uninst.*|vc_?redist.*|dxsetup|.*setup.*)$') { continue }
            [void]$exes.Add($b)
            if ($f.DirectoryName.TrimEnd('\') -ieq $ctx.Dir) { [void]$top.Add($b) }
            if (++$n -ge 60) { break }
        }
    }
    foreach ($s in @($app.Icon)) {
        if (-not $s) { continue }
        $e = ((Split-GBCommand $s)[0]) -replace ',\s*-?\d+$', ''
        if ($e -match '(?i)\.exe$') { $b = [IO.Path]::GetFileNameWithoutExtension($e).ToLower(); if ($Script:GenericExe -notcontains $b) { [void]$exes.Add($b); [void]$top.Add($b) } }
    }
    $ctx.Exes = $exes
    $v = New-Object 'System.Collections.Generic.HashSet[string]'
    $short = New-Object 'System.Collections.Generic.HashSet[string]'
    $clean = Get-GBCleanName $app.Name
    $pub = Get-GBCleanPublisher $app.Publisher
    $names = @($clean, $app.Name)
    if ($pub) {
        $pw = @($pub -split '\s+' | ForEach-Object { $_.ToLower() })
        $names += (@($clean -split '\s+' | Where-Object { $pw -notcontains $_.ToLower() }) -join ' ')
    }
    foreach ($c in $names) { $nn = Get-GBNorm $c; if ($nn.Length -ge 4 -and $Script:GenericNames -notcontains $nn) { [void]$v.Add($nn) } }
    $leafs = @(); if ($ctx.Dir) { $leafs += (Split-Path -Leaf $ctx.Dir) }
    $leafs += @($top)
    foreach ($c in $leafs) {
        $nn = Get-GBNorm $c
        if ($Script:GenericNames -contains $nn) { continue }
        if ($nn.Length -ge 3) { [void]$v.Add($nn) }
    }
    foreach ($x in $v) { [void]$short.Add($x) }
    foreach ($c in $names) { $nn = Get-GBNorm $c; if ($nn.Length -eq 3) { [void]$short.Add($nn) } }
    $ctx.Variants = $v; $ctx.Short = $short
    $pv = New-Object 'System.Collections.Generic.HashSet[string]'
    if ($pub) {
        foreach ($c in @($pub, ($pub -split '\s+')[0])) { $nn = Get-GBNorm $c; if ($nn.Length -ge 3 -and @('microsoft', 'windows', 'the') -notcontains $nn) { [void]$pv.Add($nn) } }
    }
    $ctx.PubVariants = $pv
    # Ce qui appartient aux AUTRES programmes installes : jamais supprime / jamais coche d'office
    $od = New-Object System.Collections.ArrayList
    $ov = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($o in @($allPrograms)) {
        if (-not $o -or $o.Kind -ne 'Win32' -or $o.Key -eq $app.Key) { continue }
        if ($o.Dir -and -not ($ctx.Dir -and ($o.Dir -ieq $ctx.Dir))) { [void]$od.Add($o.Dir.TrimEnd('\')) }
        [void]$ov.Add((Get-GBNorm (Get-GBCleanName $o.Name)))
        if ($o.Dir) { [void]$ov.Add((Get-GBNorm (Split-Path -Leaf $o.Dir))) }
    }
    $ctx.OtherDirs = $od; $ctx.OtherVariants = $ov
    $ctx.ExeRegex = $null
    if ($exes.Count -gt 0) { $ctx.ExeRegex = '(?i)\\(' + ((@($exes) | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')\.exe' }
    return $ctx
}
function Test-GBRefersTo($text, $ctx) {
    if (-not $text) { return $false }
    $t = [Environment]::ExpandEnvironmentVariables([string]$text)
    if ($ctx.Dir -and $t.IndexOf($ctx.Dir, [StringComparison]::OrdinalIgnoreCase) -ge 0) { return $true }
    if ($ctx.ExeRegex -and $t -match $ctx.ExeRegex) { return $true }
    return $false
}

function Get-GBDirSize($p) {
    $s = [int64]0
    try { foreach ($f in [IO.Directory]::EnumerateFiles($p, '*', [IO.SearchOption]::AllDirectories)) { try { $s += (New-Object IO.FileInfo($f)).Length } catch {} } }
    catch {
        $s = 0
        try { $s = [int64](Get-ChildItem -LiteralPath $p -Recurse -Force -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum).Sum } catch {}
    }
    return $s
}
function Format-GBSize([int64]$b) {
    if ($b -ge 1GB) { return ("{0:N1} Go" -f ($b / 1GB)) }
    if ($b -ge 1MB) { return ("{0:N0} Mo" -f ($b / 1MB)) }
    if ($b -gt 0) { return ("{0:N0} Ko" -f [math]::Max(1, $b / 1KB)) }
    return "vide"
}

# Recherche des restes. $status : scriptblock qui affiche l'avancement.
function Find-GBLeftovers($ctx, [bool]$stillInstalled, $status) {
    $items = New-Object System.Collections.ArrayList
    $seen = @{}
    $add = {
        param($kind, $path, $type, $detail, [bool]$sure, $extra, $cleanParent)
        $k = ($kind + '|' + $path + '|' + $extra).ToLower()
        if ($seen.ContainsKey($k)) { return }
        $seen[$k] = $true
        if ($ctx.Sensitive -or $stillInstalled) { $sure = $false }
        [void]$items.Add([pscustomobject]@{ Kind = $kind; Path = $path; Type = $type; Detail = $detail; Sure = $sure; Extra = $extra; CleanParent = $cleanParent; Size = [int64]0 })
    }
    $tryDir = {
        param($path, [bool]$sure, $note, $nn, $parent)
        if (Test-GBProtectedPath $path $ctx.OtherDirs) { return }
        if ($ctx.OtherVariants.Contains($nn)) { $sure = $false; $note = "meme nom qu'un autre programme installe : verifie" }
        & $add 'dir' $path 'Dossier' $note $sure $null $parent
    }

    # 1. Dossiers
    & $status "Recherche des dossiers..."
    if ($ctx.Dir -and (Test-Path -LiteralPath $ctx.Dir) -and -not (Test-GBProtectedPath $ctx.Dir $ctx.OtherDirs)) {
        & $add 'dir' $ctx.Dir 'Dossier' "dossier d'installation encore present" $true $null $null
    }
    $docs = [Environment]::GetFolderPath('MyDocuments')
    $roots = @(
        @{ P = $env:ProgramFiles; Sure = $true; Note = "Program Files" }, @{ P = ${env:ProgramFiles(x86)}; Sure = $true; Note = "Program Files (x86)" },
        @{ P = $env:ProgramData; Sure = $true; Note = "donnees communes (ProgramData)" }, @{ P = $env:APPDATA; Sure = $true; Note = "donnees du compte (AppData\Roaming)" },
        @{ P = $env:LOCALAPPDATA; Sure = $true; Note = "donnees locales (AppData\Local)" }, @{ P = (Join-Path $env:LOCALAPPDATA 'Programs'); Sure = $true; Note = "AppData\Local\Programs" },
        @{ P = (Join-Path $env:USERPROFILE 'AppData\LocalLow'); Sure = $true; Note = "AppData\LocalLow" },
        @{ P = [Environment]::GetFolderPath('CommonProgramFiles'); Sure = $true; Note = "Common Files" }, @{ P = [Environment]::GetFolderPath('CommonProgramFilesX86'); Sure = $true; Note = "Common Files (x86)" },
        @{ P = $env:TEMP; Sure = $true; Note = "fichiers temporaires" },
        @{ P = ($env:SystemDrive + '\'); Sure = $false; Note = "a la racine du disque : verifie" },
        @{ P = $docs; Sure = $false; Note = "dans tes Documents : peut contenir tes sauvegardes" },
        @{ P = (Join-Path $docs 'My Games'); Sure = $false; Note = "Documents\My Games : sauvegardes de jeu ?" },
        @{ P = (Join-Path $env:USERPROFILE 'Saved Games'); Sure = $false; Note = "Parties sauvegardees : sauvegardes de jeu ?" }
    )
    $done = @{}
    foreach ($r in $roots) {
        if (-not $r.P -or $done.ContainsKey($r.P.ToLower()) -or -not (Test-Path -LiteralPath $r.P)) { continue }
        $done[$r.P.ToLower()] = $true
        foreach ($child in @(Get-ChildItem -LiteralPath $r.P -Directory -Force -ErrorAction SilentlyContinue)) {
            $nc = Get-GBNorm $child.Name
            if ($ctx.Variants.Contains($nc)) { & $tryDir $child.FullName $r.Sure $r.Note $nc $null }
            elseif ($ctx.PubVariants.Contains($nc)) {
                foreach ($gc in @(Get-ChildItem -LiteralPath $child.FullName -Directory -Force -ErrorAction SilentlyContinue)) {
                    $ng = Get-GBNorm $gc.Name
                    if ($ctx.Short.Contains($ng)) { & $tryDir $gc.FullName $r.Sure ($r.Note + ", dossier de l'editeur") $ng $child.FullName }
                }
            }
        }
    }

    # 2. Raccourcis (menu Demarrer, Bureau, barre des taches)
    & $status "Recherche des raccourcis..."
    $sh = $null; try { $sh = New-Object -ComObject WScript.Shell } catch {}
    $lnkDirs = @(
        @{ P = [Environment]::GetFolderPath('Programs'); Rec = $true }, @{ P = [Environment]::GetFolderPath('CommonPrograms'); Rec = $true },
        @{ P = [Environment]::GetFolderPath('Desktop'); Rec = $false }, @{ P = [Environment]::GetFolderPath('CommonDesktopDirectory'); Rec = $false },
        @{ P = (Join-Path $env:APPDATA 'Microsoft\Internet Explorer\Quick Launch\User Pinned\TaskBar'); Rec = $false }
    )
    foreach ($ld in $lnkDirs) {
        if (-not $ld.P -or -not (Test-Path -LiteralPath $ld.P)) { continue }
        if ($ld.Rec) {
            foreach ($sd in @(Get-ChildItem -LiteralPath $ld.P -Directory -Force -ErrorAction SilentlyContinue)) {
                $ns = Get-GBNorm $sd.Name
                if ($ctx.Variants.Contains($ns) -and -not $ctx.OtherVariants.Contains($ns)) { & $add 'dir' $sd.FullName 'Dossier du menu Demarrer' "" $true $null $null }
            }
        }
        $files = @(); if ($ld.Rec) { $files = @(Get-ChildItem -LiteralPath $ld.P -Filter *.lnk -File -Recurse -Force -ErrorAction SilentlyContinue) } else { $files = @(Get-ChildItem -LiteralPath $ld.P -Filter *.lnk -File -Force -ErrorAction SilentlyContinue) }
        foreach ($lf in $files) {
            $target = ""
            try { if ($sh) { $target = [string]$sh.CreateShortcut($lf.FullName).TargetPath } } catch {}
            $hit = $false
            if ($target) {
                if ($ctx.Dir -and (Test-GBUnder $target $ctx.Dir)) { $hit = $true }
                elseif ($ctx.Exes.Contains([IO.Path]::GetFileNameWithoutExtension($target)) -and -not (Test-GBPathExists $target)) { $hit = $true }
            } elseif ($ctx.Variants.Contains((Get-GBNorm $lf.BaseName)) -and -not $ctx.OtherVariants.Contains((Get-GBNorm $lf.BaseName))) { $hit = $true }
            if ($hit) {
                $dt = "raccourci"; if ($target) { $dt = "vers " + $target }
                $par = $null; if ($ld.Rec -and $lf.DirectoryName.TrimEnd('\') -ine $ld.P.TrimEnd('\')) { $par = $lf.DirectoryName }   # sous-dossier du menu Demarrer devenu vide
                & $add 'file' $lf.FullName 'Raccourci' $dt $true $null $par
            }
        }
    }
    if ($sh) { try { [void][Runtime.InteropServices.Marshal]::ReleaseComObject($sh) } catch {} }

    # 3. Registre : cles du logiciel (HKCU / HKLM \Software\<Editeur>\<Programme>)
    & $status "Recherche dans le registre..."
    $noTouch = @('microsoft', 'classes', 'policies', 'wow6432node', 'clients', 'registeredapplications', 'windows', 'odbc', 'intel', 'nvidiacorporation',
                 'nvidia', 'amd', 'ati', 'realtek', 'partner', 'oem', 'description', 'setup', 'system', 'hardware', 'sam', 'security', 'drivers')
    foreach ($root in @('HKEY_CURRENT_USER\Software', 'HKEY_LOCAL_MACHINE\SOFTWARE', 'HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node')) {
        $rk = Get-Item -LiteralPath ('Registry::' + $root) -ErrorAction SilentlyContinue
        if (-not $rk) { continue }
        foreach ($sn in @($rk.GetSubKeyNames())) {
            $ns = Get-GBNorm $sn
            if ($noTouch -contains $ns) { continue }
            if ($ctx.Variants.Contains($ns)) {
                $sure = -not $ctx.OtherVariants.Contains($ns)
                $dt = "parametres du programme"; if (-not $sure) { $dt = "meme nom qu'un autre programme installe : verifie" }
                & $add 'regkey' ($root + '\' + $sn) 'Cle de registre' $dt $sure $null $null
            } elseif ($ctx.PubVariants.Contains($ns)) {
                $pk = Get-Item -LiteralPath ('Registry::' + $root + '\' + $sn) -ErrorAction SilentlyContinue
                if (-not $pk) { continue }
                foreach ($gn in @($pk.GetSubKeyNames())) {
                    $ng = Get-GBNorm $gn
                    if ($ctx.Short.Contains($ng)) {
                        $sure = -not $ctx.OtherVariants.Contains($ng)
                        & $add 'regkey' ($root + '\' + $sn + '\' + $gn) 'Cle de registre' "parametres du programme (dossier de l'editeur)" $sure $null ($root + '\' + $sn)
                    }
                }
            }
        }
    }
    # Entree "Programmes et fonctionnalites" restee apres la desinstallation
    if ($ctx.App.NativeKey -and (Test-Path -LiteralPath ('Registry::' + $ctx.App.NativeKey))) {
        & $add 'regkey' $ctx.App.NativeKey 'Entree de desinstallation' "le programme apparait encore dans la liste des programmes" $true $null $null
    }
    # App Paths et "Ouvrir avec"
    foreach ($e in @($ctx.Exes)) {
        foreach ($base in @('HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths', 'HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\App Paths',
                            'HKEY_LOCAL_MACHINE\SOFTWARE\Classes\Applications', 'HKEY_CURRENT_USER\Software\Classes\Applications')) {
            $kp = $base + '\' + $e + '.exe'
            if (-not (Test-Path -LiteralPath ('Registry::' + $kp))) { continue }
            $def = $null; try { $def = (Get-Item -LiteralPath ('Registry::' + $kp)).GetValue('') } catch {}
            if ($def) { $def = ([string]$def).Trim('"'); if ((Test-GBPathExists $def) -and -not ($ctx.Dir -and (Test-GBUnder $def $ctx.Dir))) { continue } }
            $ty = 'Chemin d''application'; if ($base -like '*Applications') { $ty = 'Association "Ouvrir avec"' }
            & $add 'regkey' $kp $ty ($e + '.exe') $true $null $null
        }
    }
    # Lancement au demarrage de Windows
    foreach ($rk in @('HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Run', 'HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\RunOnce',
                      'HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Run', 'HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce',
                      'HKEY_LOCAL_MACHINE\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Run')) {
        $k = Get-Item -LiteralPath ('Registry::' + $rk) -ErrorAction SilentlyContinue
        if (-not $k) { continue }
        foreach ($vn in @($k.GetValueNames())) {
            if (-not $vn) { continue }
            $data = [string]$k.GetValue($vn)
            if ((Test-GBRefersTo $data $ctx) -or ($ctx.Variants.Contains((Get-GBNorm $vn)) -and -not $ctx.OtherVariants.Contains((Get-GBNorm $vn)) -and -not (Test-GBPathExists ((Split-GBCommand $data)[0])))) {
                & $add 'regvalue' $rk 'Lancement au demarrage' ($vn + " = " + $data) $true $vn $null
            }
        }
    }

    # 4. Services Windows installes par le programme
    & $status "Recherche des services et taches planifiees..."
    if ($ctx.Dir -or $ctx.ExeRegex) {
        try {
            $svcRoot = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SYSTEM\CurrentControlSet\Services')
            foreach ($sn in @($svcRoot.GetSubKeyNames())) {
                try {
                    $sk = $svcRoot.OpenSubKey($sn); if (-not $sk) { continue }
                    $ip = [string]$sk.GetValue('ImagePath'); $sk.Close()
                    if ($ip -and $ip -notmatch '(?i)\\(system32|syswow64)\\' -and (Test-GBRefersTo $ip $ctx)) { & $add 'service' $sn 'Service Windows' $ip $true $null $null }
                } catch {}
            }
            $svcRoot.Close()
        } catch {}
    }
    # 5. Taches planifiees
    try {
        foreach ($t in @(Get-ScheduledTask -ErrorAction Stop)) {
            if ([string]$t.TaskPath -like '\Microsoft\*') { continue }
            $acts = (@($t.Actions) | ForEach-Object { [string]$_.Execute + ' ' + [string]$_.Arguments }) -join ' '
            $nt = Get-GBNorm $t.TaskName
            if (Test-GBRefersTo $acts $ctx) { & $add 'task' $t.TaskName 'Tache planifiee' $acts $true $t.TaskPath $null }
            else {
                foreach ($vv in $ctx.Variants) {
                    if ($vv.Length -ge 5 -and $nt.StartsWith($vv) -and -not $ctx.OtherVariants.Contains($vv)) { & $add 'task' $t.TaskName 'Tache planifiee' ("nom proche : " + $acts) $false $t.TaskPath $null; break }
                }
            }
        }
    } catch {}
    # 6. Regles du pare-feu Windows
    if ($ctx.Dir) {
        & $status "Recherche des regles du pare-feu..."
        try {
            $fw = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\FirewallRules')
            if ($fw) {
                foreach ($vn in @($fw.GetValueNames())) {
                    $data = [string]$fw.GetValue($vn)
                    $m = [regex]::Match($data, '\|App=([^|]+)')
                    if (-not $m.Success) { continue }
                    $appPath = [Environment]::ExpandEnvironmentVariables($m.Groups[1].Value)
                    if (Test-GBUnder $appPath $ctx.Dir) {
                        $rn = [regex]::Match($data, '\|Name=([^|]*)').Groups[1].Value
                        & $add 'fw' $vn 'Regle du pare-feu' ($rn + " (" + $appPath + ")") $true $null $null
                    }
                }
                $fw.Close()
            }
        } catch {}
    }

    # Un element deja dans un dossier propose n'est pas liste deux fois
    $dirs = @($items | Where-Object { $_.Kind -eq 'dir' } | ForEach-Object { $_.Path })
    $final = New-Object System.Collections.ArrayList
    foreach ($it in $items) {
        if ($it.Kind -eq 'dir' -or $it.Kind -eq 'file') {
            $inside = $false
            foreach ($dd in $dirs) { if ($dd -ne $it.Path -and (Test-GBUnder $it.Path $dd)) { $inside = $true; break } }
            if ($inside) { continue }
        }
        [void]$final.Add($it)
    }
    # Taille des dossiers
    foreach ($it in $final) {
        if ($it.Kind -eq 'dir') {
            & $status ("Calcul de la taille : " + $it.Path)
            $it.Size = Get-GBDirSize $it.Path
        } elseif ($it.Kind -eq 'file') { try { $it.Size = (Get-Item -LiteralPath $it.Path -Force).Length } catch {} }
    }
    return $final
}

# Suppression des elements coches (fichiers -> Corbeille, le reste sauvegarde avant)
function Remove-GBLeftovers($items, $ctx) {
    $stamp = Get-Date -Format "yyyy-MM-dd_HHmmss"
    $safe = (($ctx.App.Name -replace '[^A-Za-z0-9 _\-\.]', '') -replace '\s+', '_'); if ($safe.Length -gt 40) { $safe = $safe.Substring(0, 40) }
    $bdir = Join-Path $Script:UninstallDir ($stamp + "_" + $safe)
    New-Item -ItemType Directory -Path $bdir -Force | Out-Null
    try { Add-Type -AssemblyName Microsoft.VisualBasic -ErrorAction Stop } catch {}
    $lines = New-Object System.Collections.ArrayList
    $values = New-Object System.Collections.ArrayList
    $ok = 0; $fail = 0; $n = 0; $freed = [int64]0
    $parents = New-Object System.Collections.ArrayList
    # Programme encore ouvert depuis un dossier a supprimer : ferme
    foreach ($it in @($items | Where-Object { $_.Kind -eq 'dir' })) {
        try { Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.Id -ne $PID -and $_.Path -and (Test-GBUnder $_.Path $it.Path) } | Stop-Process -Force -ErrorAction SilentlyContinue } catch {}
    }
    foreach ($it in $items) {
        $res = "OK"
        try {
            switch ($it.Kind) {
                { $_ -eq 'dir' -or $_ -eq 'file' } {
                    if (Test-GBProtectedPath $it.Path $ctx.OtherDirs) { throw "dossier protege (systeme ou autre programme)" }
                    if (Test-Path -LiteralPath $it.Path) {
                        try {
                            if ($it.Kind -eq 'dir') { [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($it.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin) }
                            else { [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteFile($it.Path, [Microsoft.VisualBasic.FileIO.UIOption]::OnlyErrorDialogs, [Microsoft.VisualBasic.FileIO.RecycleOption]::SendToRecycleBin) }
                        } catch {}
                        if (Test-Path -LiteralPath $it.Path) { Remove-Item -LiteralPath $it.Path -Recurse -Force -ErrorAction SilentlyContinue }
                        if (Test-Path -LiteralPath $it.Path) { throw "fichier utilise par un programme : redemarre le PC puis relance 'Nettoyer les restes'" }
                        $freed += $it.Size
                    }
                }
                'regkey' {
                    $n++; & reg.exe export $it.Path (Join-Path $bdir ("registre_" + $n + ".reg")) /y 2>$null | Out-Null
                    Remove-Item -LiteralPath ('Registry::' + $it.Path) -Recurse -Force -ErrorAction Stop
                }
                'regvalue' {
                    $k = Get-Item -LiteralPath ('Registry::' + $it.Path) -ErrorAction Stop
                    [void]$values.Add(@{ Key = $it.Path; Name = $it.Extra; Data = [string]$k.GetValue($it.Extra); Kind = [string]$k.GetValueKind($it.Extra) })
                    Remove-ItemProperty -LiteralPath ('Registry::' + $it.Path) -Name $it.Extra -ErrorAction Stop
                }
                'service' {
                    $n++; & reg.exe export ('HKLM\SYSTEM\CurrentControlSet\Services\' + $it.Path) (Join-Path $bdir ("service_" + $n + ".reg")) /y 2>$null | Out-Null
                    & sc.exe stop $it.Path 2>$null | Out-Null
                    Start-Sleep -Milliseconds 800
                    & sc.exe delete $it.Path 2>$null | Out-Null
                    if ($LASTEXITCODE -ne 0 -and $LASTEXITCODE -ne 1072) { throw ("sc delete a echoue (code " + $LASTEXITCODE + ")") }
                }
                'task' {
                    $n++
                    try { Export-ScheduledTask -TaskName $it.Path -TaskPath $it.Extra -ErrorAction Stop | Set-Content -LiteralPath (Join-Path $bdir ("tache_" + $n + ".xml")) -Encoding Unicode } catch {}
                    Unregister-ScheduledTask -TaskName $it.Path -TaskPath $it.Extra -Confirm:$false -ErrorAction Stop
                }
                'fw' {
                    $fwKey = 'HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\SharedAccess\Parameters\FirewallPolicy\FirewallRules'
                    $k = Get-Item -LiteralPath ('Registry::' + $fwKey) -ErrorAction Stop
                    [void]$values.Add(@{ Key = $fwKey; Name = $it.Path; Data = [string]$k.GetValue($it.Path); Kind = 'String' })
                    try { Remove-NetFirewallRule -Name $it.Path -ErrorAction Stop } catch { Remove-ItemProperty -LiteralPath ('Registry::' + $fwKey) -Name $it.Path -ErrorAction Stop }
                }
            }
            $ok++
            if ($it.CleanParent) { [void]$parents.Add(@{ Path = $it.CleanParent; Reg = ($it.Kind -eq 'regkey') }) }
        } catch { $res = "ECHEC : " + $_.Exception.Message; $fail++ }
        $desc = $it.Path; if ($it.Extra -and $it.Kind -eq 'regvalue') { $desc += " -> " + $it.Extra }
        [void]$lines.Add(($it.Type + " | " + $desc + " | " + $res))
    }
    # Dossier / cle de l'editeur devenu vide : supprime aussi
    foreach ($p in $parents) {
        try {
            if ($p.Reg) {
                $k = Get-Item -LiteralPath ('Registry::' + $p.Path) -ErrorAction Stop
                if ($k.SubKeyCount -eq 0 -and $k.ValueCount -eq 0) { Remove-Item -LiteralPath ('Registry::' + $p.Path) -Force -ErrorAction Stop; [void]$lines.Add("Cle de l'editeur vide | " + $p.Path + " | OK") }
            } elseif ((Test-Path -LiteralPath $p.Path) -and -not (Test-GBProtectedPath $p.Path $ctx.OtherDirs) -and @(Get-ChildItem -LiteralPath $p.Path -Force -ErrorAction SilentlyContinue).Count -eq 0) {
                Remove-Item -LiteralPath $p.Path -Force -ErrorAction Stop; [void]$lines.Add("Dossier de l'editeur vide | " + $p.Path + " | OK")
            }
        } catch {}
    }
    if ($values.Count -gt 0) { try { $values | ConvertTo-Json -Depth 3 | Set-Content -LiteralPath (Join-Path $bdir "valeurs_supprimees.json") -Encoding UTF8 } catch {} }
    $head = @("Desinstallation profonde : " + $ctx.App.Name + " " + $ctx.App.Version + " (" + $ctx.App.Publisher + ")",
              "Date : " + (Get-Date -Format "dd/MM/yyyy HH:mm"), "Dossier d'installation : " + $ctx.Dir,
              "Fichiers et dossiers : envoyes dans la Corbeille. Registre : fichiers .reg (double-clic pour le remettre). Taches : fichiers .xml.", "")
    try { Set-Content -LiteralPath (Join-Path $bdir "rapport.txt") -Value (($head + @($lines)) -join "`r`n") -Encoding UTF8 } catch {}
    return @{ Ok = $ok; Fail = $fail; Freed = $freed; Dir = $bdir; Lines = $lines }
}

# Fenetre de choix des restes : rien n'est supprime sans ton accord
function Show-GBLeftovers($ctx, $items) {
    $d = New-GBDialog ("Restes de " + $ctx.App.Name) 980 640
    $d.FormBorderStyle = "Sizable"; $d.MaximizeBox = $true; $d.MinimumSize = New-Object System.Drawing.Size(760, 420)
    $total = [int64]0; foreach ($it in $items) { $total += $it.Size }
    $null = Add-DlgLabel $d ("Restes trouves : " + @($items).Count + " element(s), " + (Format-GBSize $total)) 16 10 700 26 $fontBold $cYellow
    $inf = Add-DlgLabel $d ("Coches = surement laisses par " + $ctx.App.Name + ". En jaune = a verifier (nom proche, Documents, autre programme du meme editeur) : decoches par defaut. " +
                            "Les fichiers vont dans la Corbeille ; le registre, les services et les taches sont sauvegardes avant.") 16 38 932 36 $fontUI $cMuted
    $inf.Anchor = "Top, Left, Right"
    if ($ctx.Sensitive) { $inf.Text = "ATTENTION : composant partage (pilote, runtime, anti-triche...). Rien n'est coche d'office : ne coche que ce que tu reconnais. " + $inf.Text; $inf.ForeColor = $cYellow }
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(16, 78); $lv.Size = New-Object System.Drawing.Size(932, 448); $lv.CheckBoxes = $true
    $lv.Anchor = "Top, Bottom, Left, Right"
    [void]$lv.Columns.Add("Type", 170); [void]$lv.Columns.Add("Element", 470); [void]$lv.Columns.Add("Taille", 80); [void]$lv.Columns.Add("Detail", 200)
    Set-GBListViewStyle $lv
    $order = @{ 'dir' = 0; 'file' = 1; 'regkey' = 2; 'regvalue' = 3; 'service' = 4; 'task' = 5; 'fw' = 6 }
    foreach ($it in @($items | Sort-Object @{ Expression = { $order[$_.Kind] } }, Path)) {
        $li = New-Object System.Windows.Forms.ListViewItem($it.Type)
        $shown = $it.Path; if ($it.Kind -eq 'regvalue') { $shown = $it.Path + "  ->  " + $it.Extra } elseif ($it.Kind -eq 'task') { $shown = $it.Extra + $it.Path }
        [void]$li.SubItems.Add($shown)
        $sz = ""; if ($it.Kind -eq 'dir' -or $it.Kind -eq 'file') { $sz = Format-GBSize $it.Size }
        [void]$li.SubItems.Add($sz); [void]$li.SubItems.Add([string]$it.Detail)
        $li.Checked = [bool]$it.Sure
        if (-not $it.Sure) { $li.ForeColor = $cYellow }
        $li.Tag = $it
        [void]$lv.Items.Add($li)
    }
    if ($Script:UiOK) { $lv.Columns[$lv.Columns.Count - 1].Width = -2 }
    $d.Controls.Add($lv)
    $bAll = Add-DlgButton $d "Tout cocher" 16 536 110
    $bSure = Add-DlgButton $d "Seulement les surs" 134 536 150
    $bNone = Add-DlgButton $d "Tout decocher" 292 536 120
    $bOpen = Add-DlgButton $d "Ouvrir l'emplacement" 420 536 160
    $bDel = Add-DlgButton $d "SUPPRIMER LA SELECTION" 588 536 200
    $bDel.ForeColor = $cRed; $bDel.Font = $fontHud
    $bNo = Add-DlgButton $d "Ne rien supprimer" 800 536 148
    foreach ($b in @($bAll, $bSure, $bNone, $bOpen, $bDel)) { $b.Anchor = "Bottom, Left" }
    $bNo.Anchor = "Bottom, Right"
    $lblR = Add-DlgLabel $d "" 16 572 932 20 $fontUI $cMuted
    $lblR.Anchor = "Bottom, Left, Right"
    $updCount = {
        $c = 0; $s = [int64]0
        foreach ($li in $lv.Items) { if ($li.Checked) { $c++; $s += $li.Tag.Size } }
        $lblR.Text = "" + $c + " element(s) coche(s), " + (Format-GBSize $s) + " a liberer"
    }
    $lv.add_ItemChecked({ & $updCount })
    $bAll.Add_Click({ foreach ($li in $lv.Items) { $li.Checked = $true } })
    $bSure.Add_Click({ foreach ($li in $lv.Items) { $li.Checked = [bool]$li.Tag.Sure } })
    $bNone.Add_Click({ foreach ($li in $lv.Items) { $li.Checked = $false } })
    $bOpen.Add_Click({
        if ($lv.SelectedItems.Count -eq 0) { return }
        $it = $lv.SelectedItems[0].Tag
        try {
            if ($it.Kind -eq 'dir') { Start-Process explorer.exe -ArgumentList ("`"" + $it.Path + "`"") }
            elseif ($it.Kind -eq 'file') { Start-Process explorer.exe -ArgumentList ("/select,`"" + $it.Path + "`"") }
            elseif ($it.Kind -eq 'regkey' -or $it.Kind -eq 'regvalue') {
                Set-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Applets\Regedit' -Name 'LastKey' -Value ("Ordinateur\" + $it.Path) -ErrorAction SilentlyContinue
                Start-Process regedit.exe -ArgumentList '-m'
            }
            elseif ($it.Kind -eq 'task') { Start-Process taskschd.msc }
            elseif ($it.Kind -eq 'service') { Start-Process services.msc }
            elseif ($it.Kind -eq 'fw') { Start-Process wf.msc }
        } catch {}
    })
    $bNo.Add_Click({ $d.Close() })
    $bDel.Add_Click({
        $sel = @(); foreach ($li in $lv.Items) { if ($li.Checked) { $sel += $li.Tag } }
        if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un element (ou clique 'Ne rien supprimer').", "GameBoost") | Out-Null; return }
        $warn = @($sel | Where-Object { -not $_.Sure }).Count
        $q = "Supprimer " + $sel.Count + " element(s) ?"
        if ($warn -gt 0) { $q += "`r`n`r`nDont " + $warn + " element(s) 'a verifier' (en jaune) que tu as coche(s) toi-meme." }
        $q += "`r`n`r`nLes fichiers vont dans la Corbeille. Le registre, les services et les taches sont sauvegardes dans :`r`n" + $Script:UninstallDir
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Desinstallation profonde", "YesNo", "Warning") -ne "Yes") { return }
        $d.Enabled = $false; $d.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        $lblR.Text = "Suppression en cours..."; [System.Windows.Forms.Application]::DoEvents()
        $r = Remove-GBLeftovers $sel $ctx
        $d.Cursor = [System.Windows.Forms.Cursors]::Default; $d.Enabled = $true
        Log ("Desinstallation profonde de " + $ctx.App.Name + " : " + $r.Ok + " reste(s) supprime(s), " + $r.Fail + " echec(s), " + (Format-GBSize $r.Freed) + " liberes")
        $msg = "" + $r.Ok + " element(s) supprime(s), " + (Format-GBSize $r.Freed) + " liberes."
        if ($r.Fail -gt 0) { $msg += "`r`n`r`n" + $r.Fail + " echec(s) :`r`n" + (@($r.Lines | Where-Object { $_ -like '*ECHEC*' } | Select-Object -First 8) -join "`r`n") }
        $msg += "`r`n`r`nRapport et sauvegardes : " + $r.Dir
        [System.Windows.Forms.MessageBox]::Show($msg, "GameBoost - Desinstallation profonde") | Out-Null
        $d.Close()
    })
    $d.Add_Shown({ & $updCount })
    try { [void]$d.ShowDialog($form) } finally { $d.Dispose() }
}

function Show-DeepUninstall {
    if ($Script:Boosted) {
        [System.Windows.Forms.MessageBox]::Show("Arrete d'abord le boost (un desinstalleur a besoin de Windows Installer et des services).", "GameBoost") | Out-Null
        return
    }
    $du = @{ All = @(); Progs = @(); Mode = ''; Proc = $null; Pre = $null; Ctx = $null; Quiet = 0; Task = $null; Sync = $null; Started = $null; Icons = @{} }
    $f = New-GBDialog "Desinstallation profonde" 1000 700
    $f.FormBorderStyle = "Sizable"; $f.MaximizeBox = $true; $f.MinimizeBox = $true; $f.MinimumSize = New-Object System.Drawing.Size(860, 520)
    $null = Add-DlgLabel $f "Desinstallation profonde" 16 6 400 30 $fontPage $cYellow
    $inf = Add-DlgLabel $f ("Lance le desinstalleur officiel du programme, puis cherche tout ce qu'il laisse derriere lui : dossiers caches (AppData, ProgramData...), " +
                            "registre, raccourcis, services, taches planifiees, demarrage automatique, regles du pare-feu. Tu choisis ce qui est supprime.") 16 38 952 36 $fontUI $cMuted
    $inf.Anchor = "Top, Left, Right"
    $cmbKind = New-GBComboCtl
    $cmbKind.Location = New-Object System.Drawing.Point(16, 80); $cmbKind.Size = New-Object System.Drawing.Size(250, 26)
    $cmbKind.DropDownStyle = "DropDownList"; $cmbKind.FlatStyle = "Flat"; $cmbKind.BackColor = $cPanel; $cmbKind.ForeColor = $cText; Set-GBDarkCombo $cmbKind
    [void]$cmbKind.Items.Add("Programmes installes"); [void]$cmbKind.Items.Add("Applis Windows / Microsoft Store")
    $f.Controls.Add($cmbKind)
    $null = Add-DlgLabel $f "Rechercher :" 280 84 90 20 $fontUI $cMuted
    $txtFind = New-Object System.Windows.Forms.TextBox
    $txtFind.Location = New-Object System.Drawing.Point(372, 80); $txtFind.Size = New-Object System.Drawing.Size(300, 26)
    $txtFind.BackColor = $cPanel; $txtFind.ForeColor = $cText; $txtFind.BorderStyle = "FixedSingle"
    $f.Controls.Add($txtFind)
    $btnRef = Add-DlgButton $f "Actualiser" 852 78 116 28
    $btnRef.Anchor = "Top, Right"
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(16, 114); $lv.Size = New-Object System.Drawing.Size(952, 456); $lv.MultiSelect = $false
    $lv.Anchor = "Top, Bottom, Left, Right"
    foreach ($c in @(@('Nom', 330), @('Editeur', 200), @('Version', 110), @('Taille', 80), @('Installe le', 90), @('Pour', 120))) { [void]$lv.Columns.Add($c[0], $c[1]) }
    Set-GBListViewStyle $lv
    $il = New-Object System.Windows.Forms.ImageList
    $il.ColorDepth = "Depth32Bit"; $isz = [int](18 * [math]::Max(1.0, [double]$Script:DpiScale)); $il.ImageSize = New-Object System.Drawing.Size($isz, $isz)
    $lv.SmallImageList = $il
    $f.Controls.Add($lv)
    $lblSt = Add-DlgLabel $f "" 16 578 700 22 $fontUI $cMuted
    $lblSt.Anchor = "Bottom, Left, Right"
    $pb = New-Object System.Windows.Forms.ProgressBar
    $pb.Location = New-Object System.Drawing.Point(728, 582); $pb.Size = New-Object System.Drawing.Size(240, 14); $pb.Style = "Marquee"; $pb.Visible = $false
    $pb.Anchor = "Bottom, Right"
    $f.Controls.Add($pb)
    $btnDeep = Add-DlgButton $f "DESINSTALLER EN PROFONDEUR" 16 610 280
    $btnDeep.ForeColor = $cYellow; $btnDeep.Font = $fontHud; $btnDeep.Anchor = "Bottom, Left"
    $btnLeft = Add-DlgButton $f "Nettoyer les restes seulement" 304 610 230
    $btnLeft.Anchor = "Bottom, Left"
    $btnDone = Add-DlgButton $f "J'ai fini : chercher les restes" 542 610 230
    $btnDone.ForeColor = $cGreen; $btnDone.Anchor = "Bottom, Left"; $btnDone.Visible = $false
    $btnClose = Add-DlgButton $f "Fermer" 852 610 116
    $btnClose.Anchor = "Bottom, Right"
    $tip.SetToolTip($btnLeft, "Pour un programme deja desinstalle (il reste dans la liste) ou dont le desinstalleur est casse : cherche et supprime ses restes sans lancer son desinstalleur.")
    $tip.SetToolTip($btnDeep, "1. Point de restauration  2. Desinstalleur officiel  3. Recherche des restes  4. Tu choisis ce qui est supprime")

    $getIcon = {
        param($a)
        $p = $null
        if ($a.Icon) { $p = ((Split-GBCommand $a.Icon)[0]) -replace ',\s*-?\d+$', ''; try { $p = [Environment]::ExpandEnvironmentVariables($p) } catch {} }
        if (-not (Test-GBPathExists $p)) { return $null }
        $key = $p.ToLower()
        if ($du.Icons.ContainsKey($key)) { return $du.Icons[$key] }
        $du.Icons[$key] = $null
        try {
            $ic = $null
            if ($p -match '(?i)\.ico$') { $ic = New-Object System.Drawing.Icon($p) } else { $ic = [System.Drawing.Icon]::ExtractAssociatedIcon($p) }
            if ($ic) { $il.Images.Add($key, $ic.ToBitmap()); $du.Icons[$key] = $key }
        } catch {}
        return $du.Icons[$key]
    }
    $fill = {
        $q = $txtFind.Text.Trim().ToLower()
        $lv.BeginUpdate(); $lv.Items.Clear()
        foreach ($a in $du.All) {
            if ($q -and ($a.Name + ' ' + $a.Publisher).ToLower().IndexOf($q) -lt 0) { continue }
            $it = New-Object System.Windows.Forms.ListViewItem($a.Name)
            [void]$it.SubItems.Add($a.Publisher); [void]$it.SubItems.Add($a.Version)
            $sz = ""; if ($a.SizeMo -gt 0) { if ($a.SizeMo -ge 1024) { $sz = ("{0:N1} Go" -f ($a.SizeMo / 1024)) } else { $sz = [string]$a.SizeMo + " Mo" } }
            [void]$it.SubItems.Add($sz)
            $ds = ""; if ($a.Date) { $ds = $a.Date.ToString('dd/MM/yyyy') }
            [void]$it.SubItems.Add($ds); [void]$it.SubItems.Add($a.Scope)
            if ($a.Kind -eq 'Win32') { $ik = & $getIcon $a; if ($ik) { $it.ImageKey = $ik } }
            if ($a.Name -match $Script:SensitiveApps) { $it.ForeColor = $cMuted }
            $it.Tag = $a
            [void]$lv.Items.Add($it)
        }
        $lv.EndUpdate()
        if ($Script:UiOK -and $lv.Columns.Count -gt 0) { $lv.Columns[$lv.Columns.Count - 1].Width = -2 }
        $lblSt.Text = "" + $lv.Items.Count + " / " + @($du.All).Count + " programme(s). Gris = composant partage (pilote, runtime, anti-triche) : a ne desinstaller que si tu sais pourquoi."
        $lblSt.ForeColor = $cMuted
    }
    $load = {
        $lblSt.Text = "Lecture des programmes installes..."; $lblSt.ForeColor = $cText
        $lv.Items.Clear(); [System.Windows.Forms.Application]::DoEvents()
        $du.Progs = @(Get-GBInstalledPrograms)
        if ($cmbKind.SelectedIndex -eq 1) { $du.All = @(Get-GBStoreApps | Sort-Object Name) }
        else { $du.All = @($du.Progs | Sort-Object Name) }
        & $fill
    }
    $setBusy = {
        param([bool]$busy)
        foreach ($c in @($btnDeep, $btnLeft, $btnRef, $cmbKind, $txtFind, $lv)) { $c.Enabled = -not $busy }
        $pb.Visible = $busy
    }

    $scanAndClean = {
        param([bool]$leftoversOnly)
        $ctx = $du.Ctx
        $still = $false
        if ($ctx.App.Kind -eq 'Win32' -and $ctx.App.Key) { $still = Test-Path -LiteralPath $ctx.App.Key }
        if ($still -and -not $leftoversOnly) {
            # Le desinstalleur a peut-etre ete annule : on ne coche rien d'office
            $q = $ctx.App.Name + " est toujours dans la liste des programmes (desinstallation annulee, ou finie au prochain redemarrage).`r`n`r`n" +
                 "Chercher quand meme ses restes ? Rien ne sera coche d'office."
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Desinstallation profonde", "YesNo", "Question") -ne "Yes") { & $setBusy $false; & $load; return }
        }
        if ($leftoversOnly) { $still = $false }
        $status = { param($t) $lblSt.Text = $t; $lblSt.ForeColor = $cText; [System.Windows.Forms.Application]::DoEvents() }
        $items = @()
        if ($ctx.App.Kind -eq 'Store') {
            $pf = Join-Path $env:LOCALAPPDATA ('Packages\' + $ctx.App.PkgFamily)
            if ($ctx.App.PkgFamily -and (Test-Path -LiteralPath $pf)) {
                $items = @([pscustomobject]@{ Kind = 'dir'; Path = $pf; Type = 'Dossier'; Detail = "donnees de l'appli"; Sure = $true; Extra = $null; CleanParent = $null; Size = (Get-GBDirSize $pf) })
            }
        } else {
            $items = @(Find-GBLeftovers $ctx $still $status)
        }
        & $setBusy $false
        if ($items.Count -eq 0) {
            Log ("Desinstallation profonde de " + $ctx.App.Name + " : aucun reste trouve")
            [System.Windows.Forms.MessageBox]::Show(("Aucun reste trouve pour " + $ctx.App.Name + " : tout est propre."), "GameBoost - Desinstallation profonde") | Out-Null
        } else {
            Show-GBLeftovers $ctx $items
        }
        & $load
    }

    $isHelper = {
        param($p)
        # Desinstalleurs qui se relancent depuis un dossier temporaire (NSIS Au_.exe, Inno Setup, InstallShield...).
        # Pas msiexec : le service Windows Installer garde un msiexec ouvert ~10 min apres la fin.
        if ($du.Pre.Contains($p.Id)) { return $false }
        if ($p.ProcessName -match '(?i)^(unins\d*|uninst.*|.*uninstall.*|au_|un_a|_iu14d2n|.*setup.*|update)$') { return $true }
        $path = $null; try { $path = $p.Path } catch {}
        if ($path -and ((Test-GBUnder $path $env:TEMP) -or ($du.Ctx.Dir -and (Test-GBUnder $path $du.Ctx.Dir)))) { return $true }
        return $false
    }

    $poll = New-Object System.Windows.Forms.Timer
    $poll.Interval = 1000
    $poll.Add_Tick({
        if ($du.Mode -eq 'wait') {
            $mainDone = $true
            if ($du.Proc) { try { $mainDone = $du.Proc.HasExited } catch {} }
            $helpers = @()
            if ($mainDone) { $helpers = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { & $isHelper $_ }) }
            if ($mainDone -and $helpers.Count -eq 0) { $du.Quiet++ } else { $du.Quiet = 0 }
            $sec = [int]((Get-Date) - $du.Started).TotalSeconds
            $lblSt.Text = "Desinstalleur de " + $du.Ctx.App.Name + " en cours (" + $sec + " s) : reponds a ses questions dans sa fenetre. GameBoost cherchera les restes juste apres."
            $lblSt.ForeColor = $cYellow
            if ($du.Quiet -ge 3) { $du.Mode = ''; $poll.Stop(); $btnDone.Visible = $false; & $scanAndClean $false }
        } elseif ($du.Mode -eq 'appx') {
            $lblSt.Text = $du.Sync.Status
            if (-not $du.Sync.Done) { return }
            $du.Mode = ''; $poll.Stop()
            Stop-BackgroundTask $du.Task; $du.Task = $null
            $l = @($du.Sync.Lines) | Select-Object -First 1
            if ($du.Sync.Error -or -not $l -or -not $l.Ok) {
                $why = $du.Sync.Error; if (-not $why -and $l) { $why = $l.Err }
                Log ("Desinstallation de " + $du.Ctx.App.Name + " : echec (" + $why + ")")
                [System.Windows.Forms.MessageBox]::Show(("Windows a refuse de supprimer " + $du.Ctx.App.Name + " :`r`n" + $why), "GameBoost") | Out-Null
                & $setBusy $false; & $load; return
            }
            Log ("Appli " + $du.Ctx.App.Name + " (" + $du.Ctx.App.PkgName + ") supprimee pour tous les comptes")
            & $scanAndClean $false
        }
    })

    $startDeep = {
        param([bool]$leftoversOnly)
        if ($du.Mode -ne '') { return }
        if ($lv.SelectedItems.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Selectionne d'abord un programme dans la liste.", "GameBoost") | Out-Null; return }
        $app = $lv.SelectedItems[0].Tag
        if ($app.Kind -eq 'Store' -and $leftoversOnly) { [System.Windows.Forms.MessageBox]::Show("Pour une appli du Store, utilise 'Desinstaller en profondeur'.", "GameBoost") | Out-Null; return }
        $warn = ""
        if ($app.Name -match $Script:SensitiveApps) {
            $warn = "`r`n`r`nATTENTION : c'est un composant partage (pilote, runtime, anti-triche...). Des jeux ou d'autres programmes peuvent en avoir besoin. " +
                    "Aucun reste ne sera coche d'office."
        }
        if ($leftoversOnly) {
            $q = "Chercher et nettoyer les restes de :`r`n" + $app.Name + "`r`n`r`nSon desinstalleur ne sera PAS lance. A utiliser si le programme est deja desinstalle " +
                 "ou si son desinstalleur ne marche plus. Tu verras la liste avant toute suppression." + $warn
        } elseif ($app.Kind -eq 'Store') {
            $q = "Supprimer l'appli " + $app.Name + " (" + $app.PkgName + ") pour tous les comptes du PC, puis ses donnees ?" + $warn +
                 "`r`n`r`nTu pourras la reinstaller depuis le Microsoft Store."
        } else {
            $q = "Desinstallation profonde de :`r`n" + $app.Name + " " + $app.Version + "`r`n`r`n" +
                 "1. Point de restauration Windows (si pas deja fait aujourd'hui)`r`n2. Fermeture du programme s'il est ouvert`r`n" +
                 "3. Son desinstalleur officiel se lance : reponds a ses questions`r`n" +
                 "4. GameBoost cherche tout ce qu'il a laisse et te montre la liste AVANT de supprimer quoi que ce soit." + $warn
        }
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Desinstallation profonde", "YesNo", "Question") -ne "Yes") { return }
        & $setBusy $true
        $lblSt.Text = "Point de restauration Windows (jusqu'a 1 min)..."; $lblSt.ForeColor = $cYellow; [System.Windows.Forms.Application]::DoEvents()
        try { New-WindowsRestorePoint } catch {}
        Update-BoostButton
        $lblSt.Text = "Preparation..."; [System.Windows.Forms.Application]::DoEvents()
        $du.Ctx = New-GBUninstallContext $app $du.Progs
        $ctx = $du.Ctx
        Log ("Desinstallation profonde : " + $app.Name + " " + $app.Version + " (dossier : " + $ctx.Dir + ")")

        if ($app.Kind -eq 'Store') {
            $du.Sync = [hashtable]::Synchronized(@{ Status = "Suppression de l'appli..."; Done = $false; Error = $null;
                                                     Lines = [System.Collections.ArrayList]::Synchronized((New-Object System.Collections.ArrayList)) })
            $du.Task = Start-BackgroundTask $Script:AppxRemoveScript $du.Sync @($app.PkgName)
            $du.Mode = 'appx'; $poll.Start()
            return
        }
        # Programme encore ouvert : ferme (sinon le desinstalleur echoue ou des fichiers restent bloques)
        if ($ctx.Dir) {
            foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) {
                try { if ($p.Id -ne $PID -and $p.Path -and (Test-GBUnder $p.Path $ctx.Dir)) { Log ("Fermeture de " + $p.ProcessName + " avant desinstallation"); $p.Kill() } } catch {}
            }
        }
        if ($leftoversOnly) { & $scanAndClean $true; return }

        $cmd = $app.Uninstall; if (-not $cmd) { $cmd = $app.Quiet }
        $exe = $null; $uArgs = ""
        $guid = [regex]::Match([string]$cmd, '\{[0-9A-Fa-f\-]{36}\}')
        if ($cmd -match '(?i)msiexec' -and $guid.Success) { $exe = Join-Path $env:windir 'System32\msiexec.exe'; $uArgs = "/x " + $guid.Value }
        else {
            $parts = Split-GBCommand $cmd
            $exe = [Environment]::ExpandEnvironmentVariables($parts[0]); $uArgs = $parts[1]
        }
        if (-not (Test-GBPathExists $exe)) {
            $q = "Le desinstalleur de " + $app.Name + " est introuvable :`r`n" + $exe + "`r`n`r`nChercher et nettoyer directement ses restes ?"
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Desinstallation profonde", "YesNo", "Question") -eq "Yes") { & $scanAndClean $true } else { & $setBusy $false }
            return
        }
        $du.Pre = New-Object 'System.Collections.Generic.HashSet[int]'
        foreach ($p in @(Get-Process -ErrorAction SilentlyContinue)) { [void]$du.Pre.Add($p.Id) }
        try {
            if ($uArgs) { $du.Proc = Start-Process -FilePath $exe -ArgumentList $uArgs -PassThru -ErrorAction Stop }
            else { $du.Proc = Start-Process -FilePath $exe -PassThru -ErrorAction Stop }
        } catch {
            Log ("Desinstalleur impossible a lancer : " + $_.Exception.Message)
            $q = "Le desinstalleur n'a pas pu demarrer :`r`n" + $_.Exception.Message + "`r`n`r`nChercher et nettoyer directement les restes ?"
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Question") -eq "Yes") { & $scanAndClean $true } else { & $setBusy $false }
            return
        }
        Log ("Desinstalleur lance : " + $exe + " " + $uArgs)
        $du.Started = Get-Date; $du.Quiet = 0; $du.Mode = 'wait'
        $btnDone.Visible = $true
        $poll.Start()
    }

    $btnDeep.Add_Click({ & $startDeep $false })
    $btnLeft.Add_Click({ & $startDeep $true })
    $lv.Add_DoubleClick({ & $startDeep $false })
    $btnDone.Add_Click({ if ($du.Mode -eq 'wait') { $du.Mode = ''; $poll.Stop(); $btnDone.Visible = $false; & $scanAndClean $false } })
    $btnRef.Add_Click({ & $load })
    $cmbKind.Add_SelectedIndexChanged({ & $load })
    $txtFind.Add_TextChanged({ & $fill })
    $btnClose.Add_Click({ $f.Close() })
    $f.Add_FormClosing({
        param($sender, $e)
        if ($du.Mode -ne '') { [System.Windows.Forms.MessageBox]::Show("Desinstallation en cours : termine-la d'abord.", "GameBoost") | Out-Null; $e.Cancel = $true }
    })
    $f.Add_Shown({ $cmbKind.SelectedIndex = 0 })
    $Script:BusyDepth++     # pas de boost automatique pendant une desinstallation
    try { [void]$f.ShowDialog($form) }
    finally {
        $poll.Stop(); $poll.Dispose()
        if ($du.Task) { Stop-BackgroundTask $du.Task }
        $il.Dispose(); $f.Dispose()
        $Script:BusyDepth--
        Update-BoostButton
    }
}

# --- Mes parties : historique, overlay, sauvegarde des sauvegardes de jeux ------------------------
# Copie zip en arriere-plan (les fichiers ouverts par un jeu sont sautes)
$Script:SaveBackupScript = {
    param($sync, $job)
    $fs = $null; $zip = $null
    try {
        Add-Type -AssemblyName System.IO.Compression, System.IO.Compression.FileSystem
        $fs = [IO.File]::Open($job.Zip, [IO.FileMode]::CreateNew)
        $zip = New-Object IO.Compression.ZipArchive($fs, [IO.Compression.ZipArchiveMode]::Create)
        $n = 0; $skip = 0; $bytes = [int64]0
        foreach ($src in $job.Sources) {
            $root = ([string]$src.P).TrimEnd('\')
            foreach ($f in @(Get-ChildItem -LiteralPath $root -Recurse -File -Force -ErrorAction SilentlyContinue)) {
                $rel = $src.Z + '\' + $f.FullName.Substring($root.Length + 1)
                try { [void][IO.Compression.ZipFileExtensions]::CreateEntryFromFile($zip, $f.FullName, $rel, [IO.Compression.CompressionLevel]::Optimal); $n++; $bytes += $f.Length }
                catch { $skip++ }
                if (($n + $skip) % 100 -eq 0) { $sync.Status = "Sauvegarde : " + $n + " fichier(s)..." }
            }
        }
        $sync.Files = $n; $sync.Skipped = $skip; $sync.Bytes = $bytes
    } catch { $sync.Error = $_.Exception.Message }
    finally { if ($zip) { $zip.Dispose() }; if ($fs) { $fs.Dispose() }; $sync.Done = $true }
}
function Get-GBSaveSources {
    $list = New-Object System.Collections.ArrayList
    [void]$list.Add(@{ L = "Documents\My Games"; Z = 'My Games'; P = (Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'My Games'); On = $true })
    [void]$list.Add(@{ L = "Parties enregistrees (Saved Games)"; Z = 'Saved Games'; P = (Join-Path $env:USERPROFILE 'Saved Games'); On = $true })
    $steam = $null; try { $steam = [string](Get-ItemProperty -LiteralPath 'HKCU:\Software\Valve\Steam' -Name SteamPath -ErrorAction Stop).SteamPath } catch {}
    if ($steam) { [void]$list.Add(@{ L = "Steam : sauvegardes locales (userdata)"; Z = 'Steam userdata'; P = (Join-Path ($steam -replace '/', '\') 'userdata'); On = $true }) }
    [void]$list.Add(@{ L = "AppData\LocalLow (jeux Unity : peut etre gros)"; Z = 'LocalLow'; P = (Join-Path $env:USERPROFILE 'AppData\LocalLow'); On = $false })
    return @($list | Where-Object { Test-Path -LiteralPath $_.P })
}

function Show-GameHub {
    $gh = @{ Task = $null; Sync = $null }
    $d = New-GBDialog "Mes parties" 1000 740
    # Petits ecrans : la fenetre defile au lieu de couper son contenu
    $d.FormBorderStyle = "Sizable"; $d.MaximizeBox = $true; $d.MinimumSize = New-Object System.Drawing.Size(860, 480); $d.AutoScroll = $true
    $null = Add-DlgLabel $d "Mes parties" 16 6 300 30 $fontPage $cCyan
    $info = Add-DlgLabel $d "Chaque boost est enregistre : compare tes parties, l'effet du boost (mode comparaison = mesure SANS optimiser) et repere les baisses de FPS." 16 36 960 22 $fontUI $cMuted
    $info.Anchor = "Top, Left, Right"
    $null = Add-DlgLabel $d "Jeu :" 16 66 40 22 $fontUI $cText
    $cb = New-GBComboCtl; $cb.DropDownStyle = "DropDownList"; $cb.Location = New-Object System.Drawing.Point(60, 63); $cb.Size = New-Object System.Drawing.Size(260, 24)
    Set-GBDarkCombo $cb; $d.Controls.Add($cb)
    $lv = New-Object System.Windows.Forms.ListView
    $lv.Location = New-Object System.Drawing.Point(16, 94); $lv.Size = New-Object System.Drawing.Size(952, 210); $lv.Anchor = "Top, Left, Right"
    foreach ($c in @(@('Date', 125), @('Jeu', 160), @('Duree', 70), @('FPS', 60), @('1% bas', 70), @('CPU', 60), @('GPU', 60), @('RAM', 60), @('Ping', 70), @('Mode', 110))) { [void]$lv.Columns.Add($c[0], $c[1]) }
    Set-GBListViewStyle $lv; $d.Controls.Add($lv)
    # Graphique : barres des dernieres parties (FPS moyen, ou CPU si les FPS ne sont pas mesures)
    $chart = New-Object System.Windows.Forms.Panel; Set-GBDoubleBuffered $chart
    $chart.Location = New-Object System.Drawing.Point(16, 312); $chart.Size = New-Object System.Drawing.Size(952, 150); $chart.BackColor = $cPanel; $chart.Anchor = "Top, Left, Right"
    $chart.Add_Paint({
        param($sender, $e)
        $data = @($sender.Tag); $g = $e.Graphics
        $W = $sender.ClientSize.Width; $H = $sender.ClientSize.Height
        if ($data.Count -eq 0) { [System.Windows.Forms.TextRenderer]::DrawText($g, "Pas encore de partie enregistree pour ce jeu.", $fontUI, (New-Object System.Drawing.Point(12, 12)), $cMuted); return }
        $useFps = @($data | Where-Object { $null -ne $_.Fps }).Count -gt 0
        $vals = @($data | ForEach-Object { if ($useFps) { $_.Fps } else { $_.Cpu } })
        $max = [double](@($vals | Where-Object { $null -ne $_ } | Measure-Object -Maximum).Maximum); if ($max -le 0) { $max = 1 }
        $title = "FPS moyen par partie (cyan = boost, jaune = sans optimiser)"; if (-not $useFps) { $title = "Processeur moyen par partie en % (FPS non mesures : PresentMon)" }
        $k = [math]::Max(1.0, [double]$g.DpiX / 96.0)
        [System.Windows.Forms.TextRenderer]::DrawText($g, $title, $fontUI, (New-Object System.Drawing.Point([int](10 * $k), [int](6 * $k))), $cMuted)
        $top = [int](34 * $k); $bot = $H - [int](22 * $k); $left = [int](10 * $k); $n = $data.Count
        $slot = [double]($W - 2 * $left) / $n; $bw = [int][math]::Max(4, [math]::Min($slot * 0.55, 46 * $k))
        # Lignes de repere (25 / 50 / 75 / 100 % du maximum)
        $grid = New-Object System.Drawing.Pen($cLine, 1); $grid.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dot
        foreach ($q in 0.25, 0.5, 0.75, 1.0) { $gy = [int]($bot - $q * ($bot - $top)); $g.DrawLine($grid, $left, $gy, $W - $left, $gy) }
        $grid.Dispose()
        $base = New-Object System.Drawing.Pen($cMuted, 1); $g.DrawLine($base, $left, $bot, $W - $left, $bot); $base.Dispose()
        $fl = [System.Windows.Forms.TextFormatFlags]::HorizontalCenter -bor [System.Windows.Forms.TextFormatFlags]::NoPadding -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix
        for ($i = 0; $i -lt $n; $i++) {
            $v = $vals[$i]; $cx = [int]($left + $i * $slot + $slot / 2); $x = [int]($cx - $bw / 2)
            if ($slot -ge 40 * $k) {
                $dt = [string]$data[$i].Date; if ($dt -match '^\d{4}-(\d\d)-(\d\d)') { $dt = $Matches[2] + "/" + $Matches[1] }
                [System.Windows.Forms.TextRenderer]::DrawText($g, $dt, $fontSmall, (New-Object System.Drawing.Rectangle(($cx - [int](30 * $k)), ($bot + [int](4 * $k)), [int](60 * $k), [int](16 * $k))), $cMuted, $fl)
            }
            if ($null -eq $v) { continue }
            $h = [int][math]::Max(2, ([double]$v / $max) * ($bot - $top))
            $col = $cCyan; if ([string]$data[$i].Mode -match 'MESURE|COMPAR') { $col = $cYellow }
            $br = New-Object System.Drawing.SolidBrush([System.Drawing.Color]::FromArgb(70, $col)); $g.FillRectangle($br, $x, $bot - $h, $bw, $h); $br.Dispose()
            $cap = New-Object System.Drawing.SolidBrush($col); $g.FillRectangle($cap, $x, $bot - $h, $bw, [int][math]::Max(2, 3 * $k)); $cap.Dispose()
            if ($slot -ge 26 * $k) { [System.Windows.Forms.TextRenderer]::DrawText($g, ([string][math]::Round([double]$v)), $fontSmall, (New-Object System.Drawing.Rectangle(($cx - [int](30 * $k)), ($bot - $h - [int](17 * $k)), [int](60 * $k), [int](16 * $k))), $cText, $fl) }
        }
    })
    $d.Controls.Add($chart)
    $lblCmp = Add-DlgLabel $d "" 16 468 952 22 $fontBold $cText
    $lblCmp.Anchor = "Top, Left, Right"
    $all = @(Get-SessionIndex)
    $cb.Items.Add("Tous les jeux") | Out-Null
    foreach ($j in @($all | ForEach-Object { [string]$_.Jeu } | Where-Object { $_ } | Sort-Object -Unique)) { [void]$cb.Items.Add($j) }
    $gh.All = $all; $gh.Lv = $lv; $gh.Chart = $chart; $gh.Cmp = $lblCmp; $gh.Cb = $cb
    $gh.Fill = {
        $sel = [string]$gh.Cb.SelectedItem
        $rows = @($gh.All | Where-Object { $sel -eq 'Tous les jeux' -or [string]$_.Jeu -eq $sel })
        $gh.Lv.BeginUpdate(); $gh.Lv.Items.Clear()
        foreach ($r in @($rows | Sort-Object { [string]$_.Date } -Descending)) {
            $li = New-Object System.Windows.Forms.ListViewItem([string]$r.Date)
            foreach ($v in @($r.Jeu, ("" + $r.DureeMin + " min"), $r.Fps, $r.Low1, (Fmt $r.Cpu "%"), (Fmt $r.Gpu "%"), (Fmt $r.Ram "%"), (Fmt $r.Ping " ms"), $r.Mode)) { [void]$li.SubItems.Add([string]$v) }
            if ([string]$r.Mode -match 'MESURE|COMPAR') { $li.ForeColor = $cYellow }
            [void]$gh.Lv.Items.Add($li)
        }
        $gh.Lv.EndUpdate()
        if ($Script:UiOK) { $gh.Lv.Columns[$gh.Lv.Columns.Count - 1].Width = -2 }   # derniere colonne jusqu'au bord
        $gh.Chart.Tag = @($rows | Sort-Object { [string]$_.Date } | Select-Object -Last 30)
        $gh.Chart.Invalidate()
        # Effet du boost : FPS moyen des parties boostees vs parties en mode comparaison
        $b = @($rows | Where-Object { $null -ne $_.Fps -and [string]$_.Mode -notmatch 'MESURE|COMPAR' } | ForEach-Object { [double]$_.Fps })
        $m = @($rows | Where-Object { $null -ne $_.Fps -and [string]$_.Mode -match 'MESURE|COMPAR' } | ForEach-Object { [double]$_.Fps })
        if ($b.Count -gt 0 -and $m.Count -gt 0) {
            $ab = ($b | Measure-Object -Average).Average; $am = ($m | Measure-Object -Average).Average
            $gain = [math]::Round(100 * ($ab - $am) / [math]::Max(1, $am), 1)
            $gh.Cmp.Text = "Effet du boost : " + [math]::Round($ab) + " FPS en moyenne contre " + [math]::Round($am) + " sans optimiser (" + $(if ($gain -ge 0) { "+" } else { "" }) + $gain + " %)"
            $gh.Cmp.ForeColor = $(if ($gain -ge 0) { $cGreen } else { $cYellow })
        } elseif ($rows.Count -gt 0) {
            $gh.Cmp.Text = "" + $rows.Count + " partie(s). Pour mesurer l'effet du boost : coche 'Mode comparaison' pour une partie, puis rejoue normalement avec le boost."
            $gh.Cmp.ForeColor = $cMuted
        } else { $gh.Cmp.Text = "Aucune partie enregistree : lance un boost pendant que tu joues."; $gh.Cmp.ForeColor = $cMuted }
    }
    $cb.Add_SelectedIndexChanged({ & $gh.Fill })

    # --- Overlay en jeu
    $pnl = New-Object System.Windows.Forms.Panel
    $pnl.Location = New-Object System.Drawing.Point(16, 498); $pnl.Size = New-Object System.Drawing.Size(952, 150); $pnl.BackColor = $cBg; $pnl.Anchor = "Top, Left, Right"
    $d.Controls.Add($pnl)
    $null = New-GBHeader $pnl "Overlay en jeu" "petit cadre FPS / CPU / GPU / ping par-dessus le jeu" 0 0 952
    $chkOv = New-GBToggleCtl "Afficher l'overlay pendant le boost" ([bool]$Script:Config.Overlay)
    $chkOv.Location = New-Object System.Drawing.Point(0, 26); $chkOv.Size = New-Object System.Drawing.Size(330, 24); $pnl.Controls.Add($chkOv)
    $cbCorner = New-GBComboCtl; $cbCorner.DropDownStyle = "DropDownList"; Set-GBDarkCombo $cbCorner
    foreach ($c in @('En haut a gauche', 'En haut a droite', 'En bas a gauche', 'En bas a droite')) { [void]$cbCorner.Items.Add($c) }
    $cbCorner.SelectedIndex = [math]::Max(0, [math]::Min(3, [int]$Script:Config.OverlayCorner))
    $cbCorner.Location = New-Object System.Drawing.Point(340, 26); $cbCorner.Size = New-Object System.Drawing.Size(200, 24); $pnl.Controls.Add($cbCorner)
    $null = Add-DlgLabel $pnl "Mis a jour toutes les 5 s, la souris passe a travers. Visible en plein ecran fenetre / sans bordure (pas en plein ecran exclusif)." 550 28 400 36 $fontUI $cMuted
    $chkOv.Add_CheckedChanged({ $Script:Config.Overlay = [bool]$this.Checked; Save-Config; if (-not $this.Checked) { Hide-GBOverlay }; Log ("Overlay en jeu : " + $(if ($this.Checked) { "active" } else { "desactive" })) })
    $cbCorner.Add_SelectedIndexChanged({ $Script:Config.OverlayCorner = [int]$this.SelectedIndex; Save-Config; if ($Script:Overlay) { Hide-GBOverlay } })
    # --- Sauvegarde des sauvegardes de jeux
    $null = New-GBHeader $pnl "Sauvegarde de tes sauvegardes de jeux" "copie zip a mettre sur un autre disque ou une cle USB" 0 70 952
    $srcs = @(Get-GBSaveSources); $gh.Src = New-Object System.Collections.ArrayList
    $x = 0
    foreach ($s in $srcs) {
        $t = New-GBToggleCtl $s.L ([bool]$s.On); $t.Tag = $s
        $t.Location = New-Object System.Drawing.Point($x, 94); $t.Size = New-Object System.Drawing.Size(306, 24); $pnl.Controls.Add($t); [void]$gh.Src.Add($t)
        $tip.SetToolTip($t, $s.P); $x += 312
    }
    $bSave = New-GBButtonCtl; $bSave.Text = "Creer la sauvegarde..."; $bSave.ForeColor = $cGreen
    $bSave.Location = New-Object System.Drawing.Point(0, 122); $bSave.Size = New-Object System.Drawing.Size(220, 26); $pnl.Controls.Add($bSave)
    $lblSave = Add-DlgLabel $pnl "Les jeux Steam / Epic / Ubisoft ont souvent une sauvegarde dans le cloud, mais pas tous (et pas les mods)." 230 126 720 22 $fontUI $cMuted
    $lblSave.Anchor = "Top, Left, Right"
    $gh.LblSave = $lblSave; $gh.BSave = $bSave
    $bSave.Add_Click({
        if ($gh.Task) { return }
        $sel = @($gh.Src | Where-Object { $_.Checked } | ForEach-Object { $_.Tag })
        if ($sel.Count -eq 0) { [System.Windows.Forms.MessageBox]::Show("Coche au moins un dossier.", "GameBoost") | Out-Null; return }
        $fb = New-Object System.Windows.Forms.FolderBrowserDialog
        $fb.Description = "Ou enregistrer la sauvegarde ? (de preference un autre disque ou une cle USB)"
        if ($fb.ShowDialog() -ne 'OK') { return }
        $zipPath = Join-Path $fb.SelectedPath ('GameBoost_sauvegardes_jeux_' + (Get-Date -Format 'yyyy-MM-dd_HHmm') + '.zip')
        if ($fb.SelectedPath.Substring(0, 1) -ieq $env:SystemDrive.Substring(0, 1)) {
            if ([System.Windows.Forms.MessageBox]::Show("Ce dossier est sur le meme disque que Windows : si ce disque tombe en panne, la sauvegarde est perdue aussi. Continuer quand meme ?", "GameBoost", "YesNo", "Warning") -ne "Yes") { return }
        }
        $gh.Sync = [hashtable]::Synchronized(@{ Done = $false; Error = $null; Status = "Preparation..."; Files = 0; Skipped = 0; Bytes = 0 })
        $gh.Zip = $zipPath; $gh.BSave.Enabled = $false
        Log ("Sauvegarde des sauvegardes de jeux -> " + $zipPath)
        $gh.Task = Start-BackgroundTask $Script:SaveBackupScript $gh.Sync @{ Zip = $zipPath; Sources = $sel }
        $gh.Poll.Start()
    })
    $poll = New-Object System.Windows.Forms.Timer; $poll.Interval = 500; $gh.Poll = $poll
    $poll.Add_Tick({
        if (-not $gh.Sync) { $gh.Poll.Stop(); return }
        $gh.LblSave.Text = $gh.Sync.Status; $gh.LblSave.ForeColor = $cText
        if (-not $gh.Sync.Done) { return }
        $gh.Poll.Stop(); Stop-BackgroundTask $gh.Task; $gh.Task = $null; $s = $gh.Sync; $gh.Sync = $null; $gh.BSave.Enabled = $true
        if ($s.Error) { $gh.LblSave.Text = "Echec : " + $s.Error; $gh.LblSave.ForeColor = $cRed; Log ("Sauvegarde des jeux : echec " + $s.Error); return }
        $zs = 0; try { $zs = (Get-Item -LiteralPath $gh.Zip).Length } catch {}
        $gh.LblSave.Text = "Sauvegarde creee : " + $s.Files + " fichier(s), " + (Format-GBSize ([int64]$zs)) + $(if ($s.Skipped -gt 0) { " (" + $s.Skipped + " fichier(s) ouverts sautes)" } else { "" })
        $gh.LblSave.ForeColor = $cGreen
        Log ("Sauvegarde des jeux terminee : " + $s.Files + " fichier(s) -> " + $gh.Zip)
        try { Start-Process explorer.exe ('/select,"' + $gh.Zip + '"') } catch {}
    })
    $btnClose = Add-DlgButton $d "Fermer" 852 660 116; $btnClose.Anchor = "Top, Right"; $d.CancelButton = $btnClose
    $btnClose.Add_Click({ $d.Close() })
    $d.Add_FormClosing({ param($sender, $e) if ($gh.Task) { [System.Windows.Forms.MessageBox]::Show("Sauvegarde en cours : patiente jusqu'a la fin.", "GameBoost") | Out-Null; $e.Cancel = $true } })
    $d.Add_Shown({ $gh.Cb.SelectedIndex = 0 })
    try { [void]$d.ShowDialog($form) }
    finally { $poll.Stop(); $poll.Dispose(); if ($gh.Task) { Stop-BackgroundTask $gh.Task }; $d.Dispose() }
}

# --- Optimisations permanentes d'un jeu (clic droit dans "Mes jeux") : restent actives meme sans GameBoost ---
$Script:GpuPrefKey = 'Software\Microsoft\DirectX\UserGpuPreferences'
$Script:LayersKey = 'Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers'
$Script:IfeoKey = 'SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options'
function Find-GBGameExe($name) {
    $p = @(Get-Process -Name $name -ErrorAction SilentlyContinue) | Select-Object -First 1
    if ($p) { $x = Get-ProcessPath $p; if ($x) { return $x } }
    foreach ($x in @($Script:Config.GpuPrefAdded)) { if ($x -and [IO.Path]::GetFileNameWithoutExtension([string]$x) -ieq $name -and (Test-Path -LiteralPath $x)) { return [string]$x } }
    try { $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($Script:GpuPrefKey); if ($k) { try { foreach ($v in $k.GetValueNames()) { if ([IO.Path]::GetFileNameWithoutExtension($v) -ieq $name) { return $v } } } finally { $k.Close() } } } catch {}
    return $null
}
function Get-GBLayerFlags($path) {
    try { $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($Script:LayersKey); if ($k) { try { return @(([string]$k.GetValue($path)).Split(' ') | Where-Object { $_ -and $_ -ne '~' }) } finally { $k.Close() } } } catch {}
    return @()
}
function Set-GBLayerFlag($path, $flag, [bool]$on) {
    $flags = @(Get-GBLayerFlags $path | Where-Object { $_ -ne $flag }); if ($on) { $flags += $flag }
    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($Script:LayersKey)
    try { if ($flags.Count -eq 0) { $k.DeleteValue($path, $false) } else { $k.SetValue($path, ('~ ' + ($flags -join ' ')), [Microsoft.Win32.RegistryValueKind]::String) } } finally { $k.Close() }
}
function Test-GBGameGpu($path) { try { $k = [Microsoft.Win32.Registry]::CurrentUser.OpenSubKey($Script:GpuPrefKey); if ($k) { try { return ([string]$k.GetValue($path) -match 'GpuPreference=2') } finally { $k.Close() } } } catch {}; return $false }
function Set-GBGameGpu($path, [bool]$on) {
    $k = [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey($Script:GpuPrefKey)
    try { if ($on) { $k.SetValue($path, 'GpuPreference=2;', [Microsoft.Win32.RegistryValueKind]::String) } else { $k.DeleteValue($path, $false) } } finally { $k.Close() }
    # Reglage permanent choisi a la main : TOUT RESTAURER ne doit plus le retirer
    $Script:Config.GpuPrefAdded = @($Script:Config.GpuPrefAdded | Where-Object { $_ -and $_ -ne $path }); Save-Config
}
function Test-GBGamePrio($exe) {
    try { $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($Script:IfeoKey + '\' + $exe + '\PerfOptions'); if ($k) { try { return ([int]$k.GetValue('CpuPriorityClass', 0) -eq 3) } finally { $k.Close() } } } catch {}
    return $false
}
function Set-GBGamePrio($exe, [bool]$on) {
    $kp = $Script:IfeoKey + '\' + $exe + '\PerfOptions'
    if ($on) { $k = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($kp); try { $k.SetValue('CpuPriorityClass', 3, [Microsoft.Win32.RegistryValueKind]::DWord) } finally { $k.Close() }; return }
    $k = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($kp, $true)
    if ($k) { try { $k.DeleteValue('CpuPriorityClass', $false); $empty = ($k.ValueCount -eq 0 -and $k.SubKeyCount -eq 0) } finally { $k.Close() }
              if ($empty) { [Microsoft.Win32.Registry]::LocalMachine.DeleteSubKey($kp, $false) } }
    # La cle du jeu n'est supprimee que si elle est vide (d'autres reglages peuvent y exister)
    $kg = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($Script:IfeoKey + '\' + $exe)
    if ($kg) { $e2 = ($kg.ValueCount -eq 0 -and $kg.SubKeyCount -eq 0); $kg.Close(); if ($e2) { [Microsoft.Win32.Registry]::LocalMachine.DeleteSubKey($Script:IfeoKey + '\' + $exe, $false) } }
}
function Show-GameTweaks($name) {
    $gt = @{ Path = (Find-GBGameExe $name); Silent = $false }
    $d = New-GBDialog ("Optimisations de " + $name) 620 380
    $null = Add-DlgLabel $d ("Optimisations permanentes : " + $name) 16 10 580 24 $fontBold $cCyan
    $null = Add-DlgLabel $d "Elles restent actives meme quand GameBoost est ferme. Decoche pour revenir au reglage normal de Windows." 16 36 580 36 $fontUI $cMuted
    $null = Add-DlgLabel $d "Programme du jeu :" 16 78 140 22 $fontUI $cText
    $tb = New-Object System.Windows.Forms.TextBox; $tb.ReadOnly = $true; $tb.Location = New-Object System.Drawing.Point(16, 100); $tb.Size = New-Object System.Drawing.Size(460, 24)
    $tb.BackColor = $cPanel; $tb.ForeColor = $cText; $tb.BorderStyle = "FixedSingle"; $d.Controls.Add($tb)
    $bBr = Add-DlgButton $d "Parcourir..." 484 98 112 28
    $c1 = Add-DlgCheck $d "Toujours sur la carte graphique puissante" 16 140 580 $false
    $c2 = Add-DlgCheck $d "Desactiver les optimisations plein ecran (latence, anciens jeux DX9/11)" 16 172 580 $false
    $c3 = Add-DlgCheck $d "Priorite processeur haute a chaque lancement" 16 204 580 $false
    $null = Add-DlgLabel $d ("Carte puissante : utile sur les PC a 2 cartes graphiques (portables). Priorite haute : le jeu passe avant tout le reste, meme sans boost " +
                             "(sans risque ; si un anti-triche refuse de se lancer, decoche).") 16 238 580 52 $fontUI $cMuted
    $bOk = Add-DlgButton $d "Fermer" 480 300 116; $d.CancelButton = $bOk; $bOk.Add_Click({ $d.Close() })
    $gt.Tb = $tb; $gt.C1 = $c1; $gt.C2 = $c2; $gt.C3 = $c3
    $gt.Exe = $name + '.exe'
    $gt.Load = {
        $gt.Silent = $true
        if ($gt.Path) { $gt.Tb.Text = $gt.Path; $gt.Exe = [IO.Path]::GetFileName($gt.Path) } else { $gt.Tb.Text = "(lance le jeu une fois, ou clique Parcourir pour choisir son .exe)" }
        $gt.C1.Enabled = [bool]$gt.Path; $gt.C2.Enabled = [bool]$gt.Path
        if ($gt.Path) { $gt.C1.Checked = Test-GBGameGpu $gt.Path; $gt.C2.Checked = (@(Get-GBLayerFlags $gt.Path) -contains 'DISABLEDXMAXIMIZEDWINDOWEDMODE') }
        $gt.C3.Checked = Test-GBGamePrio $gt.Exe
        $gt.Silent = $false
    }
    $bBr.Add_Click({
        $o = New-Object System.Windows.Forms.OpenFileDialog; $o.Filter = 'Programme (*.exe)|*.exe'; $o.Title = "Choisis le .exe du jeu"
        if ($o.ShowDialog() -eq 'OK') { $gt.Path = $o.FileName; & $gt.Load }
    })
    $apply = {
        param($what, $on)
        if ($gt.Silent) { return }
        try {
            switch ($what) {
                'gpu' { Set-GBGameGpu $gt.Path $on }
                'fse' { Set-GBLayerFlag $gt.Path 'DISABLEDXMAXIMIZEDWINDOWEDMODE' $on }
                'prio' { Set-GBGamePrio $gt.Exe $on }
            }
            Log ("Optimisation permanente de " + $gt.Exe + " : " + $what + " -> " + $(if ($on) { "active" } else { "retire" }) + " (au prochain lancement du jeu)")
        } catch { [System.Windows.Forms.MessageBox]::Show(("Impossible : " + $_.Exception.Message), "GameBoost") | Out-Null; & $gt.Load }
    }
    $gt.Apply = $apply
    $c1.Add_CheckedChanged({ & $gt.Apply 'gpu' ([bool]$this.Checked) })
    $c2.Add_CheckedChanged({ & $gt.Apply 'fse' ([bool]$this.Checked) })
    $c3.Add_CheckedChanged({ & $gt.Apply 'prio' ([bool]$this.Checked) })
    & $gt.Load
    try { [void]$d.ShowDialog($form) } finally { $d.Dispose() }
}

# --- Capteurs : temperatures CPU / GPU / SSD, ventilateurs, puissance (sans pilote ni telechargement) ---
# Sources, de la plus directe a la moins sure : noyau graphique de Windows (D3DKMT, toutes marques, comme le Gestionnaire des taches),
# nvml.dll du pilote NVIDIA, BIOS du constructeur en LECTURE seule (Lenovo, ASUS, MSI), zones thermiques de Windows, disques (NVMe / stockage).
# Les lectures lentes (WMI, disques) tournent en arriere-plan : Get-GBSensors ne bloque jamais l'interface.
$Script:SensOK = $false; $Script:SensError = ""
try {
$sensSrc = @'
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Management;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Windows.Forms;
using Microsoft.Win32.SafeHandles;

// ======================= GameBoost : capteurs (temperatures, ventilateurs, puissance), sans pilote =======================

// Carte graphique vue par le noyau de Windows (comme le Gestionnaire des taches) : temperature, ventilateur, frequences
public class GBKmtData {
    public string Luid = ""; public string Name = "";
    public double TempC = double.NaN, TempMax = double.NaN, FanRpm = double.NaN, PowerPct = double.NaN, CoreMhz = double.NaN, MemMhz = double.NaN;
    public uint Bus; public bool BusOk; public bool PerfOk;
}
public static class GBSensKmt {
    [StructLayout(LayoutKind.Sequential)] struct LUID { public uint Low; public int High; }
    [StructLayout(LayoutKind.Sequential)] struct ADAPTERINFO { public uint hAdapter; public LUID AdapterLuid; public uint NumOfSources; public int bPrecise; }
    [StructLayout(LayoutKind.Sequential)] struct ENUMADAPTERS2 { public uint NumAdapters; public IntPtr pAdapters; }
    [StructLayout(LayoutKind.Sequential)] struct QUERYADAPTERINFO { public uint hAdapter; public int Type; public IntPtr pData; public uint Size; }
    [StructLayout(LayoutKind.Sequential)] struct CLOSEADAPTER { public uint hAdapter; }
    [DllImport("gdi32.dll")] static extern int D3DKMTEnumAdapters2(ref ENUMADAPTERS2 e);
    [DllImport("gdi32.dll")] static extern int D3DKMTQueryAdapterInfo(ref QUERYADAPTERINFO q);
    [DllImport("gdi32.dll")] static extern int D3DKMTCloseAdapter(ref CLOSEADAPTER c);
    const int Q_ADDRESS = 6, Q_REGINFO = 8, Q_NODEPERF = 61, Q_PERF = 62, Q_PERFCAPS = 63;
    public static bool Disabled;            // test : simule un Windows sans cette fonction
    public static string LastError = "";
    static readonly Dictionary<string, GBKmtData> _fixed = new Dictionary<string, GBKmtData>();   // nom, PCI et maximum : lus une fois
    static readonly byte[] _zero = new byte[512];

    static int Query(uint h, int type, IntPtr buf, int size) {
        Marshal.Copy(_zero, 0, buf, size);
        QUERYADAPTERINFO q = new QUERYADAPTERINFO(); q.hAdapter = h; q.Type = type; q.pData = buf; q.Size = (uint)size;
        return D3DKMTQueryAdapterInfo(ref q);
    }

    public static GBKmtData[] ReadAll() {
        List<GBKmtData> res = new List<GBKmtData>();
        if (Disabled) { LastError = "desactive (test)"; return res.ToArray(); }
        ENUMADAPTERS2 e = new ENUMADAPTERS2();
        try { if (D3DKMTEnumAdapters2(ref e) != 0 || e.NumAdapters == 0) { LastError = "D3DKMTEnumAdapters2"; return res.ToArray(); } }
        catch (Exception ex) { LastError = ex.Message; return res.ToArray(); }
        int sz = Marshal.SizeOf(typeof(ADAPTERINFO)); uint count = e.NumAdapters;
        e.pAdapters = Marshal.AllocHGlobal(sz * (int)count);
        IntPtr buf = Marshal.AllocHGlobal(512);
        try {
            if (D3DKMTEnumAdapters2(ref e) != 0) return res.ToArray();
            for (int i = 0; i < e.NumAdapters && i < count; i++) {
                ADAPTERINFO a = (ADAPTERINFO)Marshal.PtrToStructure(new IntPtr(e.pAdapters.ToInt64() + (long)i * sz), typeof(ADAPTERINFO));
                try {
                    GBKmtData d = new GBKmtData();
                    d.Luid = string.Format("luid_0x{0:x8}_0x{1:x8}", (uint)a.AdapterLuid.High, a.AdapterLuid.Low);
                    GBKmtData f;
                    if (!_fixed.TryGetValue(d.Luid, out f)) {
                        f = new GBKmtData(); f.Luid = d.Luid;
                        IntPtr nb = Marshal.AllocHGlobal(2200);
                        try {
                            byte[] z = new byte[2200]; Marshal.Copy(z, 0, nb, 2200);
                            QUERYADAPTERINFO q = new QUERYADAPTERINFO(); q.hAdapter = a.hAdapter; q.Type = Q_REGINFO; q.pData = nb; q.Size = 2080;
                            if (D3DKMTQueryAdapterInfo(ref q) == 0) f.Name = Marshal.PtrToStringUni(nb) ?? "";
                        } finally { Marshal.FreeHGlobal(nb); }
                        if (Query(a.hAdapter, Q_ADDRESS, buf, 12) == 0) { f.Bus = (uint)Marshal.ReadInt32(buf, 0); f.BusOk = true; }
                        if (Query(a.hAdapter, Q_PERFCAPS, buf, 40) == 0) { int tm = Marshal.ReadInt32(buf, 28); if (tm > 300 && tm < 1500) f.TempMax = tm / 10.0; }
                        _fixed[d.Luid] = f;
                    }
                    d.Name = f.Name; d.Bus = f.Bus; d.BusOk = f.BusOk; d.TempMax = f.TempMax;
                    // KMTQAITYPE_ADAPTERPERFDATA : temperature en dixiemes de degre, ventilateur (tr/min), puissance (dixiemes de %), memoire (Hz)
                    if (Query(a.hAdapter, Q_PERF, buf, 64) == 0) {
                        d.PerfOk = true;
                        long mem = Marshal.ReadInt64(buf, 8); if (mem > 0) d.MemMhz = Math.Round(mem / 1000000.0);
                        int fan = Marshal.ReadInt32(buf, 48); if (fan > 0 && fan < 20000) d.FanRpm = fan;
                        int pw = Marshal.ReadInt32(buf, 52); if (pw > 0 && pw <= 1500) d.PowerPct = pw / 10.0;
                        int t = Marshal.ReadInt32(buf, 56); if (t > 50 && t < 1500) d.TempC = Math.Round(t / 10.0, 1);
                    }
                    // KMTQAITYPE_NODEPERFDATA : frequence du moteur le plus rapide
                    for (int n = 0; n < 8; n++) {
                        Marshal.Copy(_zero, 0, buf, 56); Marshal.WriteInt32(buf, 0, n);
                        QUERYADAPTERINFO q = new QUERYADAPTERINFO(); q.hAdapter = a.hAdapter; q.Type = Q_NODEPERF; q.pData = buf; q.Size = 56;
                        if (D3DKMTQueryAdapterInfo(ref q) != 0) break;
                        long hz = Marshal.ReadInt64(buf, 8);
                        if (hz > 0) { double mhz = Math.Round(hz / 1000000.0); if (double.IsNaN(d.CoreMhz) || mhz > d.CoreMhz) d.CoreMhz = mhz; }
                    }
                    res.Add(d);
                } catch (Exception ex) { LastError = ex.Message; }
                finally { CLOSEADAPTER c = new CLOSEADAPTER(); c.hAdapter = a.hAdapter; try { D3DKMTCloseAdapter(ref c); } catch { } }
            }
        } finally { Marshal.FreeHGlobal(buf); Marshal.FreeHGlobal(e.pAdapters); }
        return res.ToArray();
    }
}

// NVIDIA : nvml.dll (installee avec le pilote), chargee seulement si elle existe ; aucune ecriture
public static class GBNvml {
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)] static extern IntPtr LoadLibraryW(string path);
    [DllImport("kernel32.dll", CharSet = CharSet.Ansi, SetLastError = true)] static extern IntPtr GetProcAddress(IntPtr h, string name);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnVoid();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnCount(out uint c);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnHandle(uint i, out IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnU(IntPtr h, out uint v);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnTU(IntPtr h, int t, out uint v);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnPci(IntPtr h, IntPtr buf);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int FnName(IntPtr h, StringBuilder sb, uint n);
    static FnVoid _init, _shutdown; static FnCount _count; static FnHandle _handle; static FnTU _temp, _clock; static FnU _power, _fan; static FnPci _pci; static FnName _name;
    static IntPtr _lib = IntPtr.Zero;
    static int _state;          // 0 = pas essaye, 1 = pret, -1 = indisponible
    static IntPtr[] _dev = new IntPtr[0]; static uint[] _bus = new uint[0]; static string[] _names = new string[0];
    public static bool Disabled;            // test : simule un PC sans NVIDIA
    public static string LastError = "";
    public static string DllPath = "";
    public static bool Ready { get { return _state == 1; } }
    public static int Count { get { return _dev.Length; } }

    static T Fn<T>(string name) where T : class {
        IntPtr p = GetProcAddress(_lib, name);
        if (p == IntPtr.Zero) return null;
        return Marshal.GetDelegateForFunctionPointer(p, typeof(T)) as T;
    }
    public static bool Init() {
        if (_state != 0) return _state == 1;
        _state = -1;
        if (Disabled) { LastError = "pas de NVIDIA (test)"; return false; }
        try {
            string[] paths = new string[] {
                System.IO.Path.Combine(Environment.SystemDirectory, "nvml.dll"),
                System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles), @"NVIDIA Corporation\NVSMI\nvml.dll") };
            foreach (string p in paths) {
                if (!System.IO.File.Exists(p)) continue;
                _lib = LoadLibraryW(p);
                if (_lib != IntPtr.Zero) { DllPath = p; break; }
            }
            if (_lib == IntPtr.Zero) { LastError = "nvml.dll absente (pas de carte NVIDIA ou pilote sans NVML)"; return false; }
            _init = Fn<FnVoid>("nvmlInit_v2"); _shutdown = Fn<FnVoid>("nvmlShutdown");
            _count = Fn<FnCount>("nvmlDeviceGetCount_v2"); _handle = Fn<FnHandle>("nvmlDeviceGetHandleByIndex_v2");
            _temp = Fn<FnTU>("nvmlDeviceGetTemperature"); _clock = Fn<FnTU>("nvmlDeviceGetClockInfo");
            _power = Fn<FnU>("nvmlDeviceGetPowerUsage"); _fan = Fn<FnU>("nvmlDeviceGetFanSpeed");
            _pci = Fn<FnPci>("nvmlDeviceGetPciInfo_v3"); _name = Fn<FnName>("nvmlDeviceGetName");
            if (_init == null || _count == null || _handle == null || _temp == null) { LastError = "nvml.dll incomplete"; return false; }
            int rc = _init();
            if (rc != 0) { LastError = "nvmlInit " + rc; return false; }
            uint n; if (_count(out n) != 0) n = 0;
            List<IntPtr> devs = new List<IntPtr>(); List<uint> buses = new List<uint>(); List<string> names = new List<string>();
            IntPtr pci = Marshal.AllocHGlobal(256);
            try {
                for (uint i = 0; i < n && i < 16; i++) {
                    IntPtr h; if (_handle(i, out h) != 0) continue;
                    uint bus = uint.MaxValue;
                    if (_pci != null && _pci(h, pci) == 0) bus = (uint)Marshal.ReadInt32(pci, 20);   // nvmlPciInfo_t : busIdLegacy[16], domain, bus
                    StringBuilder sb = new StringBuilder(96); string nm = "";
                    if (_name != null && _name(h, sb, 96) == 0) nm = sb.ToString();
                    devs.Add(h); buses.Add(bus); names.Add(nm);
                }
            } finally { Marshal.FreeHGlobal(pci); }
            _dev = devs.ToArray(); _bus = buses.ToArray(); _names = names.ToArray();
            if (_dev.Length == 0) { LastError = "aucune carte NVIDIA"; return false; }
            _state = 1; LastError = "";
            return true;
        } catch (Exception ex) { LastError = ex.Message; return false; }
    }
    // Index de la carte pour un bus PCI (ou la seule carte NVIDIA)
    public static int Find(uint bus, bool busKnown) {
        if (_state != 1) return -1;
        if (busKnown) for (int i = 0; i < _bus.Length; i++) if (_bus[i] == bus) return i;
        return _dev.Length == 1 ? 0 : -1;
    }
    public static string Name(int i) { return (i >= 0 && i < _names.Length) ? _names[i] : ""; }
    // [temperature C, puissance W, ventilateur %, frequence MHz, memoire MHz] ; NaN = non disponible
    public static double[] Read(int i) {
        double[] r = new double[] { double.NaN, double.NaN, double.NaN, double.NaN, double.NaN };
        if (_state != 1 || i < 0 || i >= _dev.Length) return r;
        try {
            IntPtr h = _dev[i]; uint v;
            if (_temp(h, 0, out v) == 0 && v > 0 && v < 150) r[0] = v;
            if (_power != null && _power(h, out v) == 0 && v > 0 && v < 1000000) r[1] = Math.Round(v / 1000.0, 1);
            if (_fan != null && _fan(h, out v) == 0 && v <= 100) r[2] = v;
            if (_clock != null && _clock(h, 0, out v) == 0 && v > 0) r[3] = v;
            if (_clock != null && _clock(h, 2, out v) == 0 && v > 0) r[4] = v;
        } catch (Exception ex) { LastError = ex.Message; }
        return r;
    }
    public static void Reset() { Shutdown(); _state = 0; }
    public static void Shutdown() {
        try { if (_state == 1 && _shutdown != null) _shutdown(); } catch { }
        _state = 0; _dev = new IntPtr[0]; _bus = new uint[0]; _names = new string[0];
        // nvml.dll et ses dependances pesent ~20 Mo : dechargees quand on n'en a plus besoin
        _init = null; _shutdown = null; _count = null; _handle = null; _temp = null; _clock = null; _power = null; _fan = null; _pci = null; _name = null;
        try { if (_lib != IntPtr.Zero) FreeLibrary(_lib); } catch { }
        _lib = IntPtr.Zero;
    }
}

// Disques : temperature lue par le pilote de stockage de Windows (NVMe : journal SMART ; autres : propriete temperature), sans droits
public class GBDiskInfo {
    public int Index; public string Name = ""; public int Bus;
    public double TempC = double.NaN, Warn = double.NaN, Crit = double.NaN;
    public string Src = ""; public string Err = "";
}
public static class GBDiskTemp {
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)] static extern SafeFileHandle CreateFileW(string n, uint acc, uint share, IntPtr sa, uint disp, uint flags, IntPtr t);
    [DllImport("kernel32.dll", SetLastError = true)] static extern bool DeviceIoControl(SafeFileHandle h, uint code, byte[] inb, int inl, byte[] outb, int outl, out int ret, IntPtr ov);
    const uint IOCTL_STORAGE_QUERY_PROPERTY = 0x2D1400;
    public static bool Disabled;
    static bool Internal(int bus) { return bus == 17 || bus == 11 || bus == 3 || bus == 8 || bus == 1 || bus == 10 || bus == 0; }   // NVMe, SATA, ATA, RAID, SCSI, SAS

    public static GBDiskInfo[] ReadAll() {
        List<GBDiskInfo> res = new List<GBDiskInfo>();
        if (Disabled) return res.ToArray();
        for (int i = 0; i < 16; i++) {
            try {
                using (SafeFileHandle h = CreateFileW(@"\\.\PhysicalDrive" + i, 0, 3, IntPtr.Zero, 3, 0, IntPtr.Zero)) {   // acces 0 : interrogation seulement
                    if (h.IsInvalid) continue;
                    GBDiskInfo d = new GBDiskInfo(); d.Index = i;
                    byte[] q = new byte[12]; byte[] o = new byte[1024]; int ret;
                    if (DeviceIoControl(h, IOCTL_STORAGE_QUERY_PROPERTY, q, 12, o, o.Length, out ret, IntPtr.Zero) && ret >= 32) {
                        int po = BitConverter.ToInt32(o, 16); d.Bus = BitConverter.ToInt32(o, 28);
                        if (po > 0 && po < ret) { int e = po; while (e < ret && o[e] != 0) e++; d.Name = Encoding.ASCII.GetString(o, po, e - po).Trim(); }
                    }
                    if (!Internal(d.Bus)) continue;   // cles USB, cartes SD, disques virtuels : ignores
                    if (d.Bus == 17) Nvme(h, d);
                    if (double.IsNaN(d.TempC)) Prop(h, d);
                    res.Add(d);
                }
            } catch { }
        }
        return res.ToArray();
    }
    // Journal SMART / sante NVMe (page 02h) : temperature composite en Kelvin
    static void Nvme(SafeFileHandle h, GBDiskInfo d) {
        byte[] q = new byte[8 + 40 + 512];
        BitConverter.GetBytes(50).CopyTo(q, 0);                // StorageDeviceProtocolSpecificProperty
        BitConverter.GetBytes(3).CopyTo(q, 8);                 // ProtocolTypeNvme
        BitConverter.GetBytes(2).CopyTo(q, 12);                // NVMeDataTypeLogPage
        BitConverter.GetBytes(2).CopyTo(q, 16);                // NVME_LOG_PAGE_HEALTH_INFO
        BitConverter.GetBytes(40).CopyTo(q, 24); BitConverter.GetBytes(512).CopyTo(q, 28);
        byte[] o = new byte[q.Length]; int ret;
        if (!DeviceIoControl(h, IOCTL_STORAGE_QUERY_PROPERTY, q, q.Length, o, o.Length, out ret, IntPtr.Zero)) { d.Err = "NVMe " + Marshal.GetLastWin32Error(); return; }
        int off = 8 + BitConverter.ToInt32(o, 24);
        if (off < 8 || off + 4 > ret) return;
        int k = BitConverter.ToUInt16(o, off + 1);
        if (k > 263 && k < 400) { d.TempC = k - 273; d.Src = "NVMe (SMART)"; }
    }
    // StorageDeviceTemperatureProperty : capteurs du disque + seuils
    static void Prop(SafeFileHandle h, GBDiskInfo d) {
        byte[] q = new byte[12]; BitConverter.GetBytes(52).CopyTo(q, 0);
        byte[] o = new byte[1024]; int ret;
        if (!DeviceIoControl(h, IOCTL_STORAGE_QUERY_PROPERTY, q, 12, o, o.Length, out ret, IntPtr.Zero) || ret < 24) { if (d.Err == "") d.Err = "temp " + Marshal.GetLastWin32Error(); return; }
        int crit = BitConverter.ToInt16(o, 8), warn = BitConverter.ToInt16(o, 10), cnt = BitConverter.ToUInt16(o, 12);
        if (crit > 30 && crit < 150) d.Crit = crit; if (warn > 30 && warn < 150) d.Warn = warn;
        double best = double.NaN;
        for (int i = 0; i < cnt && 24 + i * 16 + 4 <= ret; i++) {
            int t = BitConverter.ToInt16(o, 24 + i * 16 + 2);
            if (t > -10 && t < 130 && (double.IsNaN(best) || i == 0)) best = t;   // capteur 0 = temperature generale
        }
        if (!double.IsNaN(best) && best > 0) { d.TempC = best; d.Src = "Windows (stockage)"; }
    }
}

// Lectures lentes (WMI des constructeurs, zones ACPI, disques) : en arriere-plan, l'interface lit seulement la derniere valeur
public static class GBSensWmi {
    public static bool Disabled;                       // test : simule GameBoost lance sans droits administrateur
    static volatile bool _busy;
    public static volatile int Runs;
    public static string Vendor = "";                  // "Lenovo", "ASUS", "MSI" ou "" (aucun)
    public static double CpuTemp = double.NaN, GpuTemp = double.NaN, CpuFan = double.NaN, GpuFan = double.NaN;
    public static double AcpiTemp = double.NaN; public static bool AcpiFrozen; static int _acpiSame; static double _acpiPrev = double.NaN;
    public static long Stamp, DiskStamp;              // Environment.TickCount de la derniere lecture
    public static string LastError = "";
    public static GBDiskInfo[] Disks = new GBDiskInfo[0];
    public static bool Busy { get { return _busy; } }
    static bool _detected; static ManagementObject _lgz, _lom, _asus; static ManagementObject[] _msi; static bool _lomOk = true, _acpiOk = true, _relOk = true;
    static InvokeMethodOptions _opt = new InvokeMethodOptions(null, TimeSpan.FromSeconds(4));

    public static void Kick(bool disks) {
        if (_busy) return;
        _busy = true;
        ThreadPool.QueueUserWorkItem(delegate {
            try { Run(disks); } catch (Exception ex) { LastError = ex.Message; } finally { Stamp = Environment.TickCount; Runs++; _busy = false; }
        });
    }
    public static void Reset() { _detected = false; _lgz = null; _lom = null; _asus = null; _msi = null; _lomOk = true; _acpiOk = true; _relOk = true; }

    static ManagementObject First(string ns, string cls) {
        using (ManagementObjectSearcher s = new ManagementObjectSearcher(new ManagementScope(ns), new ObjectQuery("SELECT * FROM " + cls))) {
            s.Options.Timeout = TimeSpan.FromSeconds(4);
            foreach (ManagementObject m in s.Get()) return m;
        }
        return null;
    }
    static double U(ManagementBaseObject o, string name) { try { object v = o[name]; if (v == null) return double.NaN; return Convert.ToDouble(v); } catch { return double.NaN; } }
    static double Ok(double t) { return (t >= 5 && t <= 115) ? t : double.NaN; }

    static void Run(bool disks) {
        double cpu = double.NaN, gpu = double.NaN, cf = double.NaN, gf = double.NaN;
        if (!Disabled) {
            if (!_detected) {
                _detected = true; Vendor = "";
                try { _lgz = First(@"root\WMI", "LENOVO_GAMEZONE_DATA"); if (_lgz != null) Vendor = "Lenovo"; } catch { _lgz = null; }
                if (_lgz != null) { try { _lom = First(@"root\WMI", "LENOVO_OTHER_METHOD"); } catch { _lom = null; } }
                if (Vendor == "") { try { _asus = First(@"root\WMI", "AsusAtkWmi_WMNB"); if (_asus != null) Vendor = "ASUS"; } catch { _asus = null; } }
                if (Vendor == "") {
                    try {
                        List<ManagementObject> l = new List<ManagementObject>();
                        using (ManagementObjectSearcher s = new ManagementObjectSearcher(new ManagementScope(@"root\WMI"), new ObjectQuery("SELECT * FROM MSI_CPU"))) { foreach (ManagementObject m in s.Get()) l.Add(m); }
                        if (l.Count > 0) { _msi = l.ToArray(); Vendor = "MSI"; }
                    } catch { _msi = null; }
                }
            }
            // Lenovo (Legion, LOQ, IdeaPad Gaming) : methodes de LECTURE du BIOS (Get*), jamais Set*
            if (_lgz != null) {
                try { cpu = Ok(U(_lgz.InvokeMethod("GetCPUTemp", null, _opt), "Data")); } catch (Exception ex) { LastError = "Lenovo CPU : " + ex.Message; }
                try { gpu = Ok(U(_lgz.InvokeMethod("GetGPUTemp", null, _opt), "Data")); } catch { }
                if (_lom != null && _lomOk) {
                    cf = LenovoFeature(0x04030001); gf = LenovoFeature(0x04030002);     // vitesse actuelle des ventilateurs CPU / GPU (tr/min)
                    if (double.IsNaN(cpu)) cpu = Ok(LenovoFeature(0x05040000));          // temperature CPU (Legion recents)
                    if (double.IsNaN(gpu)) gpu = Ok(LenovoFeature(0x05050000));
                    if (double.IsNaN(cf) && double.IsNaN(gf) && double.IsNaN(cpu)) _lomOk = false;
                }
            }
            // ASUS (ROG, TUF) : DSTS = lecture d'un etat du BIOS (bit 16 = valeur presente)
            if (_asus != null) {
                cpu = AsusGet(0x00120094); gpu = AsusGet(0x00120097);
                cf = AsusFan(0x00110013); gf = AsusFan(0x00110014);
            }
            if (_msi != null) {
                foreach (ManagementObject m in _msi) { try { double v = Ok(U(m, "CPU")); if (!double.IsNaN(v)) { cpu = v; break; } } catch { } }
            }
            // Zones thermiques ACPI (souvent la carte mere ou une valeur figee : utilisee en dernier)
            if (_acpiOk) {
                try {
                    double best = double.NaN;
                    using (ManagementObjectSearcher s = new ManagementObjectSearcher(new ManagementScope(@"root\WMI"), new ObjectQuery("SELECT CurrentTemperature FROM MSAcpi_ThermalZoneTemperature"))) {
                        s.Options.Timeout = TimeSpan.FromSeconds(4);
                        foreach (ManagementObject m in s.Get()) { double t = Ok(U(m, "CurrentTemperature") / 10.0 - 273.15); if (!double.IsNaN(t) && (double.IsNaN(best) || t > best)) best = t; }
                    }
                    if (!double.IsNaN(best)) {
                        best = Math.Round(best, 1);
                        if (best == _acpiPrev) _acpiSame++; else _acpiSame = 0;
                        _acpiPrev = best; AcpiFrozen = _acpiSame >= 60;            // 5 min sans le moindre changement : capteur fige
                    }
                    AcpiTemp = best;
                } catch (ManagementException ex) { AcpiTemp = double.NaN; if (ex.ErrorCode == ManagementStatus.NotSupported || ex.ErrorCode == ManagementStatus.InvalidClass) _acpiOk = false; }
                catch { AcpiTemp = double.NaN; }
            }
        } else { Vendor = ""; AcpiTemp = double.NaN; }
        CpuTemp = cpu; GpuTemp = gpu; CpuFan = cf; GpuFan = gf;
        if (disks) {
            GBDiskInfo[] d = GBDiskTemp.ReadAll();
            bool miss = false; foreach (GBDiskInfo x in d) if (double.IsNaN(x.TempC)) miss = true;
            if (miss && _relOk && !Disabled) Reliability(d);
            Disks = d; DiskStamp = Environment.TickCount;
        }
    }
    static double LenovoFeature(uint id) {
        try {
            ManagementBaseObject inp = _lom.GetMethodParameters("GetFeatureValue"); inp["IDs"] = id;
            double v = U(_lom.InvokeMethod("GetFeatureValue", inp, _opt), "value");
            return (v >= 0 && v < 10000) ? v : double.NaN;
        } catch { return double.NaN; }
    }
    static double AsusRaw(uint id) {
        try {
            ManagementBaseObject inp = _asus.GetMethodParameters("DSTS"); inp["Device_ID"] = id;
            double v = U(_asus.InvokeMethod("DSTS", inp, _opt), "device_status");
            if (double.IsNaN(v)) return v;
            long l = (long)v; if ((l & 0x10000) == 0) return double.NaN;
            return l & 0xFFFF;
        } catch { return double.NaN; }
    }
    static double AsusGet(uint id) { return Ok(AsusRaw(id)); }
    static double AsusFan(uint id) { double v = AsusRaw(id); return (v >= 0 && v < 200) ? v * 100 : double.NaN; }   // centaines de tr/min
    // Dernier recours pour un disque muet : compteur de fiabilite de Windows (lent, une fois par minute au plus)
    static void Reliability(GBDiskInfo[] d) {
        try {
            using (ManagementObjectSearcher s = new ManagementObjectSearcher(new ManagementScope(@"root\Microsoft\Windows\Storage"), new ObjectQuery("SELECT DeviceId, Temperature FROM MSFT_StorageReliabilityCounter"))) {
                s.Options.Timeout = TimeSpan.FromSeconds(8);
                foreach (ManagementObject m in s.Get()) {
                    int id; if (!int.TryParse(Convert.ToString(m["DeviceId"]), out id)) continue;
                    double t = U(m, "Temperature");
                    foreach (GBDiskInfo x in d) if (x.Index == id && double.IsNaN(x.TempC) && t > 0 && t < 130) { x.TempC = t; x.Src = "Windows (fiabilite)"; }
                }
            }
        } catch (ManagementException ex) { if (ex.ErrorCode == ManagementStatus.InvalidClass || ex.ErrorCode == ManagementStatus.NotSupported) _relOk = false; }
        catch { }
    }
}

// Lecture du theme GameBoost (GBTheme) par reflexion : suit le modele (NEXUS, ARENA, PURE) sans dependre de son assembly
static class GBSensTheme {
    static Type _t;
    static object Get(string name) {
        if (_t == null) foreach (Assembly a in AppDomain.CurrentDomain.GetAssemblies()) { Type t = a.GetType("GBTheme", false); if (t != null) { _t = t; break; } }
        if (_t == null) return null;
        try {
            FieldInfo f = _t.GetField(name, BindingFlags.Public | BindingFlags.Static); if (f != null) return f.GetValue(null);
            PropertyInfo p = _t.GetProperty(name, BindingFlags.Public | BindingFlags.Static); if (p != null) return p.GetValue(null, null);
        } catch { }
        return null;
    }
    public static Color C(string n, Color d) { object o = Get(n); return o is Color ? (Color)o : d; }
    public static bool B(string n, bool d) { object o = Get(n); return o is bool ? (bool)o : d; }
    public static int I(string n, int d) { object o = Get(n); if (o is int) return (int)o; if (o != null && o.GetType().IsEnum) return Convert.ToInt32(o); return d; }
    public static Color Text { get { return C("Text", Color.FromArgb(226, 240, 255)); } }
    public static Color Muted { get { return C("Muted", Color.FromArgb(118, 132, 162)); } }
    public static Color Line { get { return C("Line", Color.FromArgb(40, 48, 78)); } }
    public static Color Bg { get { return C("Bg", Color.FromArgb(7, 8, 15)); } }
    public static bool Glow { get { return B("Glow", true); } }
    public static int Shape { get { return I("Shape", 0); } }
    public static bool Dark { get { object o = Get("IsDarkTheme"); if (o is bool) return (bool)o; return IsDark(Bg); } }
    public static bool IsDark(Color c) { return (c.R * 299 + c.G * 587 + c.B * 114) / 1000 < 140; }
}

// Petite courbe des 10 dernieres minutes : valeur en gros, min / max discrets, zone remplie en degrade leger.
// Pas d'animation : une mesure toutes les 5 s, la courbe se redessine simplement.
public class GBSpark : Control {
    double[] _v = new double[0];
    public int Capacity = 120;                 // points sur la largeur (120 x 5 s = 10 min)
    public int MinPoints = 24;                 // largeur minimale (2 min) quand l'historique est encore court
    public Color LineColor = Color.FromArgb(5, 255, 161);
    public string Caption = "", Sub = "", ValueText = "", MinMaxText = "";
    public double Threshold = double.NaN;      // ligne pointillee discrete (seuil "chaud") si elle tombe dans l'echelle
    public double MinSpan = 8;                 // ecart minimum de l'echelle (evite d'exagerer 1 degre)
    public Font BigFont, SmallFont;
    public bool Compact;                       // seulement la courbe + la valeur (bandeaux, PURE)
    public GBSpark() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
        TabStop = false;
    }
    public void SetData(double[] values) { _v = values ?? new double[0]; Invalidate(); }
    public int Count { get { return _v.Length; } }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color back = BackColor.A == 255 ? BackColor : (Parent != null ? Parent.BackColor : GBSensTheme.Bg);
        g.Clear(back);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        Color txt = GBSensTheme.Text, muted = GBSensTheme.Muted;
        bool dark = GBSensTheme.IsDark(back), glow = GBSensTheme.Glow && dark;
        Font small = SmallFont ?? Font, big = BigFont ?? Font;
        TextFormatFlags nf = TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine;
        int capH = 0;
        if (!Compact && Caption.Length > 0) {
            capH = TextRenderer.MeasureText(g, "Ag", small, Size.Empty, nf).Height + (int)(2 * s);
            TextRenderer.DrawText(g, Caption, small, new Rectangle(0, 0, Width, capH), muted, nf | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
            if (MinMaxText.Length > 0) TextRenderer.DrawText(g, MinMaxText, small, new Rectangle(0, 0, Width, capH), muted, nf | TextFormatFlags.Right);
        }
        // Valeur en gros a gauche (couleur du niveau), source dessous
        string vt = ValueText.Length > 0 ? ValueText : "n/d";
        Size vs = TextRenderer.MeasureText(g, vt, big, Size.Empty, nf);
        int valW = vs.Width + (int)(10 * s);
        Color vc = (vt == "n/d") ? muted : LineColor;
        TextRenderer.DrawText(g, vt, big, new Point(0, capH), vc, nf);
        int subH = 0;
        if (!Compact && Sub.Length > 0) {
            subH = TextRenderer.MeasureText(g, "Ag", small, Size.Empty, nf).Height;
            int sy = Math.Min(Height - subH, capH + vs.Height);
            TextRenderer.DrawText(g, Sub, small, new Rectangle(0, sy, Math.Max(valW, Width / 2), subH), muted, nf | TextFormatFlags.Left | TextFormatFlags.EndEllipsis);
        }
        // Zone de la courbe : a droite de la valeur
        RectangleF area = new RectangleF(valW, capH + 4 * s, Width - valW - 3 * s, Height - capH - 8 * s);
        if (area.Width < 20 * s || area.Height < 10 * s) return;
        double lo = double.MaxValue, hi = double.MinValue; int n = 0;
        foreach (double v in _v) if (!double.IsNaN(v)) { if (v < lo) lo = v; if (v > hi) hi = v; n++; }
        using (Pen basePen = new Pen(Color.FromArgb(dark ? 70 : 90, GBSensTheme.Line), 1f)) g.DrawLine(basePen, area.Left, area.Bottom, area.Right, area.Bottom);
        if (n == 0) return;
        double span = Math.Max(MinSpan, hi - lo), mid = (hi + lo) / 2;
        lo = mid - span * 0.6; hi = mid + span * 0.6;
        int cap = Math.Max(MinPoints, Math.Min(Capacity, _v.Length));   // debut de session : la courbe s'etire, puis fenetre fixe de 10 min
        float step = area.Width / Math.Max(1, cap - 1);
        Func<int, double, PointF> P = delegate(int i, double v) {
            float x = area.Right - (float)(_v.Length - 1 - i) * step;
            float y = area.Bottom - (float)((v - lo) / (hi - lo)) * area.Height;
            return new PointF(x, y);
        };
        if (!double.IsNaN(Threshold) && Threshold > lo && Threshold < hi) {
            float ty = P(0, Threshold).Y;
            using (Pen tp = new Pen(Color.FromArgb(dark ? 90 : 110, muted), 1f)) { tp.DashStyle = DashStyle.Dot; g.DrawLine(tp, area.Left, ty, area.Right, ty); }
        }
        // Segments continus (un trou = mesure manquante)
        List<PointF> seg = new List<PointF>();
        PointF last = PointF.Empty; bool hasLast = false;
        for (int i = 0; i <= _v.Length; i++) {
            bool end = (i == _v.Length) || double.IsNaN(_v[i]);
            if (!end) { PointF p = P(i, _v[i]); seg.Add(p); last = p; hasLast = true; continue; }
            if (seg.Count > 0) DrawSeg(g, seg.ToArray(), area, s, dark, glow);
            seg.Clear();
        }
        if (hasLast && !double.IsNaN(_v[_v.Length - 1])) {
            float r = 2.6f * s;
            if (glow) using (SolidBrush gb = new SolidBrush(Color.FromArgb(70, LineColor))) g.FillEllipse(gb, last.X - r * 2, last.Y - r * 2, r * 4, r * 4);
            using (SolidBrush b = new SolidBrush(LineColor)) g.FillEllipse(b, last.X - r, last.Y - r, r * 2, r * 2);
        }
    }
    void DrawSeg(Graphics g, PointF[] pts, RectangleF area, float s, bool dark, bool glow) {
        if (pts.Length == 1) { using (SolidBrush b = new SolidBrush(LineColor)) g.FillEllipse(b, pts[0].X - 1.5f * s, pts[0].Y - 1.5f * s, 3 * s, 3 * s); return; }
        using (GraphicsPath line = new GraphicsPath()) {
            line.AddCurve(pts, 0.35f);
            using (GraphicsPath fill = (GraphicsPath)line.Clone()) {
                fill.AddLine(pts[pts.Length - 1].X, pts[pts.Length - 1].Y, pts[pts.Length - 1].X, area.Bottom);
                fill.AddLine(pts[pts.Length - 1].X, area.Bottom, pts[0].X, area.Bottom);
                fill.CloseFigure();
                RectangleF fr = new RectangleF(area.Left, area.Top - 1, area.Width, area.Height + 2);
                using (LinearGradientBrush lb = new LinearGradientBrush(fr, Color.FromArgb(dark ? 64 : 44, LineColor), Color.FromArgb(0, LineColor), LinearGradientMode.Vertical)) g.FillPath(lb, fill);
            }
            if (glow) using (Pen gp = new Pen(Color.FromArgb(46, LineColor), 5f * s)) { gp.LineJoin = LineJoin.Round; g.DrawPath(gp, line); }
            using (Pen p = new Pen(LineColor, 1.8f * s)) { p.LineJoin = LineJoin.Round; p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; g.DrawPath(p, line); }
        }
    }
}

// Jauge circulaire (ARENA, PURE) : anneau de progression ouvert en bas, valeur au centre. Pas d'animation sur les mesures.
public class GBRing : Control {
    float _f;
    public Color RingColor = Color.FromArgb(5, 255, 161);
    public string Caption = "", Sub = "";
    public float Thickness = 0;                // 0 = automatique (8 % de la taille)
    public Font BigFont, SmallFont;
    public GBRing() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
        TabStop = false;
    }
    public float Fraction { get { return _f; } set { float v = float.IsNaN(value) ? 0f : Math.Max(0f, Math.Min(1f, value)); if (v != _f) { _f = v; Invalidate(); } } }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color back = BackColor.A == 255 ? BackColor : (Parent != null ? Parent.BackColor : GBSensTheme.Bg);
        g.Clear(back);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        bool dark = GBSensTheme.IsDark(back), glow = GBSensTheme.Glow && dark;
        float size = Math.Min(Width, Height) - 2 * s;
        float th = Thickness > 0 ? Thickness * s : Math.Max(3 * s, size * 0.08f);
        float pad = th / 2 + (glow ? th * 0.6f : 1 * s);
        RectangleF r = new RectangleF((Width - size) / 2 + pad, (Height - size) / 2 + pad, size - 2 * pad, size - 2 * pad);
        if (r.Width < 4) return;
        LineCap cap = GBSensTheme.Shape == 0 ? LineCap.Flat : LineCap.Round;   // NEXUS : bouts nets ; ARENA / PURE : bouts arrondis
        using (Pen track = new Pen(Color.FromArgb(dark ? 110 : 140, GBSensTheme.Line), th)) { track.StartCap = cap; track.EndCap = cap; g.DrawArc(track, r, 135, 270); }
        float sweep = 270f * _f;
        if (sweep > 0.5f) {
            if (glow) using (Pen gp = new Pen(Color.FromArgb(50, RingColor), th * 1.9f)) { gp.StartCap = cap; gp.EndCap = cap; g.DrawArc(gp, r, 135, sweep); }
            using (Pen p = new Pen(RingColor, th)) { p.StartCap = cap; p.EndCap = cap; g.DrawArc(p, r, 135, sweep); }
        }
        TextFormatFlags cf = TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter;
        Font big = BigFont ?? Font, small = SmallFont ?? Font;
        string t = string.IsNullOrEmpty(Text) ? "n/d" : Text;
        Size ts = TextRenderer.MeasureText(g, t, big, Size.Empty, cf);
        int sh = TextRenderer.MeasureText(g, "Ag", small, Size.Empty, cf).Height;
        // Libelle et valeur empiles au centre de l'anneau (le libelle ne chevauche jamais les chiffres)
        int capH = Caption.Length > 0 ? sh + (int)(4 * s) : 0;
        int top = (int)(r.Top + r.Height / 2 - (capH + ts.Height) / 2f);
        if (capH > 0) TextRenderer.DrawText(g, Caption, small, new Rectangle((int)r.Left, top, (int)r.Width, sh), GBSensTheme.Muted, cf);
        Rectangle tr = new Rectangle((int)r.Left, top + capH, (int)r.Width, ts.Height);
        TextRenderer.DrawText(g, t, big, tr, t == "n/d" ? GBSensTheme.Muted : RingColor, cf);
        if (Sub.Length > 0) TextRenderer.DrawText(g, Sub, small, new Rectangle(0, (int)(r.Bottom - sh * 0.9f), Width, sh), GBSensTheme.Muted, cf | TextFormatFlags.EndEllipsis);
    }
}
'@
    $sensRefs = @('System.Windows.Forms', 'System.Drawing', 'System.Management')
    if ($PSVersionTable.PSEdition -eq 'Core') {
        try { Add-Type -AssemblyName System.Management } catch {}
        $sensRefs = @(@($uiRefs) + @([System.Management.ManagementObject].Assembly.Location))
    }
    if (-not (Add-GBCompiled 'GBSens' $sensSrc $sensRefs 'GBSensKmt')) { throw $Script:GBCompileError }
    $Script:SensOK = $true
} catch { $Script:SensError = $_.Exception.Message }

$Script:SensorHistory = New-Object System.Collections.ArrayList   # 120 dernieres mesures (10 min a 5 s)
$Script:SensLast = $null; $Script:SensLastTick = 0; $Script:SensRecTick = 0; $Script:SensDiskTick = 0
$Script:SensMinMax = @{}; $Script:SensFrozen = @{}
$Script:SensCost = @{ N = 0; Ms = 0.0; Max = 0.0 }
$Script:SensTherm = $null; $Script:SensThermState = 0                  # 0 pas essaye, 1 actif, -1 aucune zone thermique
$Script:SensInit = $false; $Script:SensTimer = $null; $Script:SensHooked = $false; $Script:SensHasMinute = $false
$Script:SensBusy = $false; $Script:SensTicks = 0; $Script:SensAlertText = ""; $Script:SensUi = $null; $Script:SensPick = $null
$Script:SensIsAdmin = $false
try { $Script:SensIsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch {}

# Reglages des capteurs (cle SensorPrefs) : unite C/F, alertes, source du processeur, seuils personnalises (vide = automatique)
function Get-GBSensorPrefs {
    $p = $Script:Config.SensorPrefs
    if (-not ($p -is [hashtable])) { $p = @{}; $Script:Config.SensorPrefs = $p; if ($Script:RealConfig) { $Script:RealConfig.SensorPrefs = $p } }
    if (@('C', 'F') -notcontains [string]$p.Unit) { $p.Unit = 'C' }
    if ($null -eq $p.Alerts) { $p.Alerts = $true }
    if (-not $p.CpuSource) { $p.CpuSource = 'auto' }
    if ($null -eq $p.NvmlAlways) { $p.NvmlAlways = $false }
    return $p
}
# Seuils [chaud, tres chaud, critique] par defaut : processeur portable (HX : prevu pour tourner a 90-95 C, limite 100 C), carte graphique, SSD
function Get-GBTempDefaults([string]$Kind) {
    if ($Kind -eq 'cpu') { if ($Script:IsLaptop) { return @(80.0, 90.0, 97.0) }; return @(75.0, 85.0, 95.0) }
    if ($Kind -eq 'gpu') {
        $c = 88.0
        if ($Script:SensLast -and $Script:SensLast.GpuTempMax) { $c = [math]::Max(84.0, [math]::Min(88.0, [double]$Script:SensLast.GpuTempMax - 1)) }
        return @(75.0, 83.0, $c)
    }
    return @(55.0, 65.0, 75.0)
}
function Get-GBTempThresholds([string]$Kind = 'cpu') {
    $p = Get-GBSensorPrefs; $k = $Kind.ToLower()
    $c = @(); if ($k -eq 'cpu') { $c = @($p.Cpu) } elseif ($k -eq 'gpu') { $c = @($p.Gpu) } else { $c = @($p.Ssd) }
    $c = @($c | Where-Object { $null -ne $_ })
    if ($c.Count -eq 3 -and [double]$c[0] -lt [double]$c[1] -and [double]$c[1] -lt [double]$c[2]) { return @([double]$c[0], [double]$c[1], [double]$c[2]) }
    return (Get-GBTempDefaults $k)
}
# Niveau d'une temperature : 'ok' | 'warm' | 'hot' | 'crit' ('na' si inconnue)
function Get-GBTempLevel($t, [string]$Kind = 'cpu') {
    if ($null -eq $t) { return 'na' }
    $th = Get-GBTempThresholds $Kind; $v = [double]$t
    if ($v -ge $th[2]) { return 'crit' }
    if ($v -ge $th[1]) { return 'hot' }
    if ($v -ge $th[0]) { return 'warm' }
    return 'ok'
}
# Couleur du theme pour un niveau (vert, jaune, orange = melange jaune/rouge, rouge ; gris si inconnu)
function Get-GBTempColor([string]$Level) {
    if ($Level -eq 'ok') { return $cGreen }
    if ($Level -eq 'warm') { return $cYellow }
    if ($Level -eq 'hot') { return [System.Drawing.Color]::FromArgb(255, [int](($cYellow.R + $cRed.R) / 2), [int](($cYellow.G + $cRed.G) / 2), [int](($cYellow.B + $cRed.B) / 2)) }
    if ($Level -eq 'crit') { return $cRed }
    return $cMuted
}
function ConvertTo-GBTempUnit($t) {
    if ($null -eq $t) { return $null }
    if ((Get-GBSensorPrefs).Unit -eq 'F') { return [double]$t * 9 / 5 + 32 }
    return [double]$t
}
# "53 C" ou "127 F" (avec le signe degre) selon les reglages ; "n/d" si inconnue
function Format-GBTemp($t, [switch]$NoUnit) {
    if ($null -eq $t) { return "n/d" }
    $s = [string][int][math]::Round([double](ConvertTo-GBTempUnit $t))
    if ($NoUnit) { return $s }
    return ($s + " " + [char]0xB0 + (Get-GBSensorPrefs).Unit)
}
# Valeur affichee selon son type : temperature, puissance, frequence, ventilateur
function Format-GBSensorValue($v, [string]$Kind) {
    if ($null -eq $v) { return "n/d" }
    switch ($Kind) {
        'power' { if ([double]$v -lt 10) { return ("{0:N1} W" -f [double]$v) }; return ("" + [int][math]::Round([double]$v) + " W") }
        'mhz'   { if ([double]$v -ge 1000) { return ("{0:N2} GHz" -f ([double]$v / 1000.0)) }; return ("" + [int]$v + " MHz") }
        'rpm'   { return ("" + [int]$v + " tr/min") }
    }
    return (Format-GBTemp $v)
}

# Zones thermiques de Windows (compteurs PDH, sans droits) : temperature la plus haute, en Kelvin ou dixiemes de Kelvin
function Get-GBThermalZoneTemp {
    if ($Script:SensThermState -lt 0 -or -not $Script:FastOK) { return $null }
    try {
        if ($Script:SensThermState -eq 0) {
            $Script:SensThermState = -1
            $pd = New-Object GBPdh; $pd.RefreshEvery = 120
            $pd.Add('hp', '\Thermal Zone Information(*)\High Precision Temperature', $true)
            $pd.Add('k', '\Thermal Zone Information(*)\Temperature', $true)
            if (-not $pd.Open()) { return $null }
            $Script:SensTherm = $pd; $Script:SensThermState = 1; $Script:SensThermEmpty = 0
        }
        $best = $null
        $ok = $Script:SensTherm.Collect()
        $arr = $null; $div = 10.0; if ($ok) { $arr = $Script:SensTherm.Array('hp') }
        if ($ok -and (-not $arr -or $arr.Count -eq 0)) { $arr = $Script:SensTherm.Array('k'); $div = 1.0 }
        foreach ($kv in @($arr)) {
            $t = [double]$kv.Value / $div - 273.15
            if ($t -ge 5 -and $t -le 115 -and ($null -eq $best -or $t -gt $best)) { $best = [math]::Round($t, 1) }
        }
        if ($null -eq $best) {
            # Aucune zone sur ce PC (le cas de nombreux portables) : on arrete d'interroger apres 3 essais
            $Script:SensThermEmpty++
            if ($Script:SensThermEmpty -ge 3) { $Script:SensThermState = -1; try { $Script:SensTherm.Dispose() } catch {}; $Script:SensTherm = $null }
        }
        else { $Script:SensThermEmpty = 0 }
        return $best
    } catch { return $null }
}
# Capteur fige (meme valeur pendant 5 min) : ignore, souvent une valeur fixe du BIOS
function Test-GBSensorFrozen([string]$Name, $v, [bool]$Count) {
    $f = $Script:SensFrozen[$Name]
    if (-not $f) { $f = @{ V = $null; N = 0 }; $Script:SensFrozen[$Name] = $f }
    if ($Count) { if ($null -ne $v -and $f.V -eq $v) { $f.N++ } else { $f.N = 0 }; $f.V = $v }
    return ($f.N -ge 60)
}

# Lecture complete (rapide : ~1 a 3 ms ; les sources lentes viennent du dernier passage en arriere-plan)
function Update-GBSensors([switch]$Record) {
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $o = @{ CpuTemp = $null; CpuTempSrc = ''; GpuTemp = $null; GpuTempSrc = ''; GpuName = ''; GpuHotspot = $null; SsdTemps = @(); GpuPowerW = $null; GpuFanPct = $null; CpuMhz = $null; Time = (Get-Date)
            GpuClockMhz = $null; GpuMemMhz = $null; GpuTempMax = $null; GpuFanRpm = $null; GpuSleep = $false; IGpuTemp = $null; IGpuName = ''; IGpuClockMhz = $null
            CpuFanRpm = $null; SsdMax = $null; CpuSources = @(); Why = @{} }
    $why = $o.Why
    $bgOk = $false; $vendor = ''
    if ($Script:SensOK) {
        try { $bgOk = ([GBSensWmi]::Runs -gt 0 -and [math]::Abs([Environment]::TickCount - [GBSensWmi]::Stamp) -lt 45000); $vendor = [string][GBSensWmi]::Vendor } catch {}
    }
    # --- Cartes graphiques : dediee ($Script:MainGpu) et integree ($Script:IGpu), reperees par leur LUID
    $main = $Script:MainGpu; $ig = $Script:IGpu
    if ($ig -and $main -and [string]$ig.Luid -eq [string]$main.Luid) { $ig = $null }
    if ($main) { $o.GpuName = [string]$main.Short }
    if ($ig) { $o.IGpuName = [string]$ig.Short }
    $kd = $null; $ki = $null
    if ($Script:SensOK) {
        $all = @(); try { $all = @([GBSensKmt]::ReadAll()) } catch {}
        foreach ($a in $all) {
            if ($main -and $a.Luid -eq [string]$main.Luid) { $kd = $a }
            elseif ($ig -and $a.Luid -eq [string]$ig.Luid) { $ki = $a }
        }
        if (-not $main) { $kd = @($all | Where-Object { -not [double]::IsNaN($_.TempC) }) | Select-Object -First 1; if ($kd) { $o.GpuName = Get-ShortGpuName $kd.Name } }
    }
    $gt = $null
    if ($kd) {
        if (-not [double]::IsNaN($kd.TempC)) { $gt = [double]$kd.TempC; $o.GpuTempSrc = 'Windows (D3DKMT)' }
        if (-not [double]::IsNaN($kd.TempMax)) { $o.GpuTempMax = [double]$kd.TempMax }
        if (-not [double]::IsNaN($kd.CoreMhz)) { $o.GpuClockMhz = [double]$kd.CoreMhz }
        if (-not [double]::IsNaN($kd.MemMhz)) { $o.GpuMemMhz = [double]$kd.MemMhz }
        if (-not [double]::IsNaN($kd.FanRpm)) { $o.GpuFanRpm = [double]$kd.FanRpm }
    }
    # Portable hybride : carte dediee en veille = aucune mesure (NVML la reveillerait et viderait la batterie)
    $sleep = [bool]($null -eq $gt -and $Script:GpuHybrid -and $Script:LastGpuDetail -and $Script:LastGpuDetail.DedSleep)
    $o.GpuSleep = $sleep
    $isNv = [bool]($main -and ([string]$main.Name -match 'NVIDIA' -or $main.Vendor -eq 0x10DE))
    # nvml.dll pese ~20 Mo de memoire (jamais rendus) : chargee seulement si Windows ne donne pas la temperature,
    # a l'ouverture de la fenetre des capteurs, ou toujours si SensorPrefs.NvmlAlways
    $wantNv = $false
    if ($isNv -and $Script:SensOK -and -not $sleep) { $wantNv = ($null -eq $gt -or [bool]$Script:SensUi -or [GBNvml]::Ready -or [bool](Get-GBSensorPrefs).NvmlAlways) }
    if ($wantNv) {
        $nv = $null
        try {
            if ([GBNvml]::Init()) {
                $busOk = ($null -ne $main.Bus); $bus = [uint32]0; if ($busOk) { $bus = [uint32]$main.Bus }
                $ix = [GBNvml]::Find($bus, $busOk); if ($ix -ge 0) { $nv = [GBNvml]::Read($ix) }
            }
        } catch {}
        if ($nv) {
            if ($null -eq $gt -and -not [double]::IsNaN($nv[0])) { $gt = [double]$nv[0]; $o.GpuTempSrc = 'NVIDIA (NVML)' }
            if (-not [double]::IsNaN($nv[1])) { $o.GpuPowerW = [double]$nv[1] }
            if (-not [double]::IsNaN($nv[2])) { $o.GpuFanPct = [double]$nv[2] }
            if (-not [double]::IsNaN($nv[3])) { $o.GpuClockMhz = [double]$nv[3] }
            if (-not [double]::IsNaN($nv[4])) { $o.GpuMemMhz = [double]$nv[4] }
        }
    }
    if ($null -eq $gt -and -not $sleep -and $bgOk -and -not [double]::IsNaN([GBSensWmi]::GpuTemp)) { $gt = [double][GBSensWmi]::GpuTemp; $o.GpuTempSrc = $vendor + ' (BIOS)' }
    $o.GpuTemp = $gt
    if ($null -eq $o.GpuFanRpm -and $bgOk -and -not [double]::IsNaN([GBSensWmi]::GpuFan)) { $o.GpuFanRpm = [double][GBSensWmi]::GpuFan }
    if ($null -eq $gt) {
        if ($sleep) { $why.GpuTemp = "Carte en veille (economie d'energie) : GameBoost ne la reveille pas pour la mesurer." }
        elseif (-not $Script:SensOK) { $why.GpuTemp = "Composants de mesure bloques (antivirus ?) : " + $Script:SensError }
        elseif (-not $main) { $why.GpuTemp = "Aucune carte graphique dediee detectee." }
        else { $why.GpuTemp = "Le pilote de cette carte ne publie pas sa temperature." }
    }
    $why.GpuHotspot = "Point chaud non publie par Windows ni par NVML (il faut le logiciel du fabricant)."
    if ($null -eq $o.GpuPowerW) { if ($isNv -and -not $wantNv -and -not $sleep) { $why.GpuPowerW = "Puissance lue par NVML (pilote NVIDIA, ~20 Mo de memoire) : chargee a la premiere ouverture de la fenetre des capteurs." } elseif ($isNv) { $why.GpuPowerW = "Puissance non publiee par le pilote (ou carte en veille)." } else { $why.GpuPowerW = "Puissance publiee seulement par les cartes NVIDIA (NVML)." } }
    if ($null -eq $o.GpuFanPct) { if ($Script:IsLaptop) { $why.GpuFanPct = "Sur un portable, les ventilateurs sont pilotes par le BIOS, pas par la carte." } else { $why.GpuFanPct = "Vitesse du ventilateur non publiee par le pilote." } }
    if ($ki) {
        if (-not [double]::IsNaN($ki.TempC)) { $o.IGpuTemp = [double]$ki.TempC }
        if (-not [double]::IsNaN($ki.CoreMhz)) { $o.IGpuClockMhz = [double]$ki.CoreMhz }
    }
    if ($null -eq $o.IGpuTemp) { if ($ig) { $why.IGpuTemp = "La puce integree ne publie pas sa temperature : elle est dans le processeur et suit sa temperature." } else { $why.IGpuTemp = "Pas de puce graphique integree." } }

    # --- Processeur : BIOS du constructeur, puis zones thermiques de Windows, puis ACPI (souvent fige ou carte mere)
    $cands = New-Object System.Collections.ArrayList
    if ($bgOk -and -not [double]::IsNaN([GBSensWmi]::CpuTemp)) { [void]$cands.Add(@{ Name = ($vendor + ' (BIOS)'); T = [math]::Round([double][GBSensWmi]::CpuTemp, 1) }) }
    $tz = Get-GBThermalZoneTemp
    if ($null -ne $tz -and -not (Test-GBSensorFrozen 'tz' $tz $Record)) { [void]$cands.Add(@{ Name = 'Windows (zone thermique)'; T = $tz }) }
    if ($bgOk -and -not [double]::IsNaN([GBSensWmi]::AcpiTemp) -and -not [GBSensWmi]::AcpiFrozen) { [void]$cands.Add(@{ Name = 'ACPI (WMI)'; T = [math]::Round([double][GBSensWmi]::AcpiTemp, 1) }) }
    $o.CpuSources = @($cands)
    $pick = $null; $want = [string](Get-GBSensorPrefs).CpuSource
    if ($want -and $want -ne 'auto') { $pick = @($cands | Where-Object { $_.Name -eq $want }) | Select-Object -First 1 }
    if (-not $pick -and $cands.Count -gt 0) { $pick = $cands[0] }
    if ($pick) { $o.CpuTemp = $pick.T; $o.CpuTempSrc = [string]$pick.Name }
    else {
        if (-not $Script:SensOK) { $why.CpuTemp = "Composants de mesure bloques (antivirus ?) : " + $Script:SensError }
        elseif ([GBSensWmi]::Runs -eq 0) { $why.CpuTemp = "Premiere mesure en cours..." }
        elseif (-not $Script:SensIsAdmin) { $why.CpuTemp = "Lecture du BIOS reservee a l'administrateur, et Windows ne publie aucune zone thermique sur ce PC." }
        else { $why.CpuTemp = "Aucun capteur du processeur lisible sans pilote sur ce PC (ni BIOS Lenovo / ASUS / MSI, ni zone thermique de Windows)." }
    }
    if ($bgOk -and -not [double]::IsNaN([GBSensWmi]::CpuFan)) { $o.CpuFanRpm = [double][GBSensWmi]::CpuFan }
    if ($null -eq $o.CpuFanRpm) { $why.CpuFanRpm = "Vitesse lue seulement dans le BIOS des portables Lenovo / ASUS (droits administrateur)." }
    if ($null -eq $o.GpuFanRpm) { $why.GpuFanRpm = $why.CpuFanRpm }
    # Frequence reelle du processeur : compteur "% Processor Performance" x frequence de base (comme l'engrenage TURBO)
    try {
        if ($Script:Perf -and [math]::Abs([Environment]::TickCount - $Script:PerfLast) -ge 6000) { [void](Update-Perf) }
        $pp = Get-PerfValue 'cpuperf'
        if ($null -ne $pp -and $Script:CpuBaseMhz) { $o.CpuMhz = [int]([math]::Round([double]$pp * $Script:CpuBaseMhz / 1000.0) * 10) }
    } catch {}
    if ($null -eq $o.CpuMhz) { $why.CpuMhz = "Compteur de performance du processeur indisponible." }

    # --- Disques (lus toutes les 60 s en arriere-plan)
    $list = New-Object System.Collections.ArrayList
    if ($Script:SensOK) {
        foreach ($dk in @([GBSensWmi]::Disks)) {
            $t = $null; if (-not [double]::IsNaN($dk.TempC)) { $t = [double]$dk.TempC }
            $nm = ([string]$dk.Name -replace '_', ' ').Trim(); if (-not $nm) { $nm = "Disque " + $dk.Index }
            $wn = $null; if (-not [double]::IsNaN($dk.Warn)) { $wn = [double]$dk.Warn }
            [void]$list.Add(@{ Name = $nm; Temp = $t; Src = [string]$dk.Src; Index = [int]$dk.Index; Warn = $wn })
            if ($null -ne $t -and ($null -eq $o.SsdMax -or $t -gt $o.SsdMax)) { $o.SsdMax = $t }
        }
    }
    $o.SsdTemps = @($list)
    if ($null -eq $o.SsdMax) { if ($list.Count -gt 0) { $why.SsdMax = "Ces disques ne publient pas leur temperature sans droits administrateur." } elseif ($Script:SensOK -and [GBSensWmi]::DiskStamp -eq 0) { $why.SsdMax = "Premiere mesure en cours..." } else { $why.SsdMax = "Aucun disque interne lisible." } }

    $Script:SensLast = $o; $Script:SensLastTick = [Environment]::TickCount
    if ($Record) {
        [void]$Script:SensorHistory.Add($o)
        while ($Script:SensorHistory.Count -gt 120) { $Script:SensorHistory.RemoveAt(0) }
        $Script:SensRecTick = $Script:SensLastTick
        foreach ($k in 'CpuTemp', 'GpuTemp', 'IGpuTemp', 'SsdMax', 'GpuPowerW', 'CpuMhz', 'GpuClockMhz', 'CpuFanRpm', 'GpuFanRpm') {
            $v = $o[$k]; if ($null -eq $v) { continue }
            $mm = $Script:SensMinMax[$k]
            if (-not $mm) { $Script:SensMinMax[$k] = @([double]$v, [double]$v) }
            else { if ($v -lt $mm[0]) { $mm[0] = [double]$v }; if ($v -gt $mm[1]) { $mm[1] = [double]$v } }
        }
    }
    $ms = $sw.Elapsed.TotalMilliseconds
    $Script:SensCost.N++; $Script:SensCost.Ms += $ms; if ($ms -gt $Script:SensCost.Max) { $Script:SensCost.Max = $ms }
    return $o
}

# Dernieres valeurs des capteurs (cache de moins de 6 s ; -Fresh force une lecture)
function Get-GBSensors([switch]$Fresh) {
    if (-not $Fresh -and $Script:SensLast -and [math]::Abs([Environment]::TickCount - $Script:SensLastTick) -lt 6000) { return $Script:SensLast }
    try { return (Update-GBSensors) } catch { return $Script:SensLast }
}
# Serie d'une valeur sur l'historique (double[], NaN = mesure manquante), pour une courbe
function Get-GBSensorSeries([string]$Key, [switch]$Display) {
    $n = $Script:SensorHistory.Count; $a = New-Object 'double[]' $n
    $f = ($Display -and (Get-GBSensorPrefs).Unit -eq 'F')
    for ($i = 0; $i -lt $n; $i++) {
        $v = $Script:SensorHistory[$i][$Key]
        if ($null -eq $v) { $a[$i] = [double]::NaN } elseif ($f) { $a[$i] = [double]$v * 9 / 5 + 32 } else { $a[$i] = [double]$v }
    }
    return ,$a
}

# Une mesure (crochet de 5 s du socle, ou minuteur de secours) : relance les lectures de fond, lit, enregistre, alerte
function Invoke-GBSensorTick {
    if ($Script:SensBusy) { return }
    $Script:SensBusy = $true
    try {
        $now = [Environment]::TickCount
        if ($Script:SensOK -and -not [GBSensWmi]::Busy) {
            $disks = ($Script:SensDiskTick -eq 0 -or [math]::Abs($now - $Script:SensDiskTick) -ge 60000)
            if ($disks) { $Script:SensDiskTick = $now }
            [GBSensWmi]::Kick($disks)
        }
        $o = Update-GBSensors -Record
        $Script:SensTicks++
        if (-not $Script:SensHasMinute -and $Script:SensTicks % 12 -eq 0) {
            $t = Test-GBSensorHealth
            if ($t -and $t -ne $Script:SensAlertText) { Log $t }
            $Script:SensAlertText = [string]$t
        }
        if ($Script:Boosted -and (Get-GBSensorPrefs).Alerts) {
            Check-Alert 'tempcpu' ((Get-GBTempLevel $o.CpuTemp 'cpu') -eq 'crit') ("processeur a " + (Format-GBTemp $o.CpuTemp) + " : il va ralentir pour se proteger (baisse le TURBO ou aere le PC)") "Temperature du processeur revenue a la normale"
            Check-Alert 'tempgpu' ((Get-GBTempLevel $o.GpuTemp 'gpu') -eq 'crit') ("carte graphique a " + (Format-GBTemp $o.GpuTemp) + " : elle va baisser sa frequence (aere le PC, limite les FPS)") "Temperature de la carte graphique revenue a la normale"
        }
        if ($Script:SensUi) { Update-GBSensorsPanel }
    } catch {
        if ($_.Exception.Message -ne $Script:SensLastErr) { $Script:SensLastErr = $_.Exception.Message; try { Log ("Capteurs : " + $Script:SensLastErr) } catch {} }
    } finally { $Script:SensBusy = $false }
}

# Verification toutes les 60 s : composant critique, sources bloquees (relancees si possible). $null = tout va bien.
function Test-GBSensorHealth {
    $msgs = @()
    $o = $Script:SensLast
    if ($o -and (Get-GBSensorPrefs).Alerts) {
        $crit = @()
        if ((Get-GBTempLevel $o.CpuTemp 'cpu') -eq 'crit') { $crit += ("processeur " + (Format-GBTemp $o.CpuTemp)) }
        if ((Get-GBTempLevel $o.GpuTemp 'gpu') -eq 'crit') { $crit += ("carte graphique " + (Format-GBTemp $o.GpuTemp)) }
        if ((Get-GBTempLevel $o.SsdMax 'ssd') -eq 'crit') { $crit += ("SSD " + (Format-GBTemp $o.SsdMax)) }
        if ($crit.Count -gt 0) { $msgs += ("ALERTE temperature critique : " + ($crit -join ", ") + " (aere le PC, baisse le TURBO ou les reglages graphiques)") }
    }
    if ($Script:SensOK) {
        $age = [math]::Abs([Environment]::TickCount - [GBSensWmi]::Stamp)
        if ([GBSensWmi]::Busy -and [GBSensWmi]::Runs -gt 0 -and $age -gt 120000) { $msgs += "lecture du BIOS bloquee depuis plus de 2 min (WMI)" }
        elseif ([GBSensWmi]::Runs -gt 0 -and -not [GBSensWmi]::Vendor -and $Script:SensIsAdmin -and $Script:SensTicks % 120 -eq 0) { [GBSensWmi]::Reset() }   # nouvelle detection toutes les ~10 min
        # Pilote NVIDIA mis a jour ou redemarre : NVML ne repond plus alors que Windows voit la carte -> relance
        if ($o -and [GBNvml]::Ready -and $o.GpuTempSrc -eq 'Windows (D3DKMT)' -and $null -eq $o.GpuPowerW -and -not $o.GpuSleep) { [GBNvml]::Reset(); $msgs += "capteurs NVIDIA relances" }
    }
    if ($Script:SensTimer -and -not $Script:SensTimer.Enabled) { $Script:SensTimer.Start(); $msgs += "surveillance des temperatures relancee" }
    if ($o -and [math]::Abs([Environment]::TickCount - $Script:SensRecTick) -gt 90000 -and ($form.Visible -or $Script:Boosted)) { $Script:SensBusy = $false; $msgs += "mesures des temperatures relancees" }
    if ($msgs.Count -eq 0) { return $null }
    return ("Capteurs : " + ($msgs -join " ; "))
}

# Branche les mesures : crochet de 5 s du socle s'il existe, sinon minuteur ; idempotent
function Initialize-GBSensors {
    if ($Script:SensInit) { return }
    $Script:SensInit = $true
    try { [void](Get-GBCpuBaseMhz) } catch {}
    if ($Script:SensOK) { try { [GBSensWmi]::Kick($true); $Script:SensDiskTick = [Environment]::TickCount } catch {} }
    try { if (Get-Command Add-GBSampleHook -ErrorAction SilentlyContinue) { Add-GBSampleHook { param($s) Invoke-GBSensorTick }; $Script:SensHooked = $true } } catch {}
    try { if (Get-Command Add-GBMinuteCheck -ErrorAction SilentlyContinue) { Add-GBMinuteCheck 'capteurs' { Test-GBSensorHealth }; $Script:SensHasMinute = $true } } catch {}
    $closed = $false
    try { if (Get-Command Add-GBCloseHook -ErrorAction SilentlyContinue) { Add-GBCloseHook { Stop-GBSensors }; $closed = $true } } catch {}
    if (-not $closed) { $form.Add_FormClosed({ Stop-GBSensors }) }
    # Minuteur de secours : mesure si le crochet ne tourne pas (fenetre cachee en jeu, panneau ouvert...) ;
    # fenetre cachee hors jeu : une mesure toutes les 30 s seulement (alertes)
    $Script:SensTimer = New-Object System.Windows.Forms.Timer
    $Script:SensTimer.Interval = 5000
    $Script:SensTimer.Add_Tick({
        $age = [math]::Abs([Environment]::TickCount - $Script:SensRecTick)
        $active = ($form.Visible -or $Script:Boosted -or $Script:SensUi)
        if ($active) { if (-not $Script:SensHooked -or $age -ge 9000) { Invoke-GBSensorTick } }
        elseif ($age -ge 29000) { Invoke-GBSensorTick }
    })
    $Script:SensTimer.Start()
    Invoke-GBSensorTick
}
function Stop-GBSensors {
    try { if ($Script:SensTimer) { $Script:SensTimer.Stop(); $Script:SensTimer.Dispose(); $Script:SensTimer = $null } } catch {}
    try { if ($Script:SensUi) { $Script:SensUi.Form.Close() } } catch {}
    if ($Script:SensOK) { try { [GBNvml]::Shutdown() } catch {} }
    try { if ($Script:SensTherm) { $Script:SensTherm.Dispose(); $Script:SensTherm = $null } } catch {}
}

# Petite courbe (GBSpark) ou, sans composants C#, une simple etiquette
function New-GBSparkCtl {
    if ($Script:SensOK) {
        $c = New-Object GBSpark
        $c.Font = $fontSmall; $c.SmallFont = $fontSmall
        $c.BigFont = $fontTitle; if ($fontHero) { $c.BigFont = $fontHero }
    } else {
        $c = New-Object System.Windows.Forms.Label; $c.Font = $fontUI; $c.ForeColor = $cText
    }
    return $c
}
# Met a jour une courbe avec une cle de Get-GBSensors : 'CpuTemp', 'GpuTemp', 'IGpuTemp', 'SsdMax' (Kind cpu/gpu/ssd), 'GpuPowerW' (power), 'CpuMhz' (mhz), 'CpuFanRpm' (rpm)
function Update-GBSparkCtl($Ctl, [string]$Key, [string]$Kind = 'cpu', [string]$Caption = '', [string]$Sub = '') {
    if (-not $Ctl -or $Ctl.IsDisposed) { return }
    $o = Get-GBSensors; $v = $null; if ($o) { $v = $o[$Key] }
    $temp = @('cpu', 'gpu', 'ssd') -contains $Kind
    if ($temp) { $col = Get-GBTempColor (Get-GBTempLevel $v $Kind) } elseif ($null -eq $v) { $col = $cMuted } else { $col = $cCyan }
    $mm = $Script:SensMinMax[$Key]; $mmt = ""
    if ($mm) {
        if ($temp) { $mmt = "min " + (Format-GBTemp $mm[0] -NoUnit) + "   max " + (Format-GBTemp $mm[1] -NoUnit) }
        else { $mmt = "min " + (Format-GBSensorValue $mm[0] $Kind) + "   max " + (Format-GBSensorValue $mm[1] $Kind) }
    }
    $vt = Format-GBSensorValue $v $Kind
    if ($Ctl -is [System.Windows.Forms.Label]) {
        $t = ""; if ($Caption) { $t = $Caption + " : " }
        $t += $vt; if ($mmt) { $t += "   (" + $mmt + ")" }; if ($Sub) { $t += "`r`n" + $Sub }
        $Ctl.Text = $t; $Ctl.ForeColor = $(if ($null -eq $v) { $cMuted } else { $col })
        return
    }
    $Ctl.Caption = $Caption; $Ctl.Sub = $Sub; $Ctl.ValueText = $vt; $Ctl.MinMaxText = $mmt; $Ctl.LineColor = $col
    $Ctl.Threshold = [double]::NaN; $Ctl.MinSpan = 8
    if ($temp) { $th = Get-GBTempThresholds $Kind; $Ctl.Threshold = [double](ConvertTo-GBTempUnit $th[1]) }
    elseif ($Kind -eq 'power') { $Ctl.MinSpan = 10 } elseif ($Kind -eq 'mhz') { $Ctl.MinSpan = 500 } elseif ($Kind -eq 'rpm') { $Ctl.MinSpan = 800 }
    $Ctl.SetData((Get-GBSensorSeries $Key -Display:$temp))
}
# Jauge circulaire (GBRing) ou etiquette de secours
function New-GBRingCtl {
    if ($Script:SensOK) {
        $c = New-Object GBRing
        $c.Font = $fontSmall; $c.SmallFont = $fontSmall
        $c.BigFont = $fontBoost; if ($fontHero) { $c.BigFont = $fontHero }
    } else {
        $c = New-Object System.Windows.Forms.Label; $c.Font = $fontBold; $c.ForeColor = $cText; $c.TextAlign = 'MiddleCenter'
    }
    return $c
}
# Anneau : de 30 C (vide) au seuil critique (plein), couleur du niveau
function Update-GBRingCtl($Ctl, [string]$Key = 'CpuTemp', [string]$Kind = 'cpu', [string]$Caption = '', [string]$Sub = '') {
    if (-not $Ctl -or $Ctl.IsDisposed) { return }
    $o = Get-GBSensors; $v = $null; if ($o) { $v = $o[$Key] }
    $col = Get-GBTempColor (Get-GBTempLevel $v $Kind)
    if ($Ctl -is [System.Windows.Forms.Label]) {
        $Ctl.Text = $(if ($Caption) { $Caption + " " } else { "" }) + (Format-GBTemp $v); $Ctl.ForeColor = $(if ($null -eq $v) { $cMuted } else { $col }); return
    }
    $f = 0.0
    if ($null -ne $v) { $th = Get-GBTempThresholds $Kind; $f = ([double]$v - 30.0) / ([double]$th[2] - 30.0) }
    $Ctl.Fraction = [single][math]::Max(0.0, [math]::Min(1.0, $f))   # (0.0 / 1.0 : sinon [math] arrondit en entier); $Ctl.RingColor = $col
    $Ctl.Text = Format-GBTemp $v; $Ctl.Caption = $Caption; $Ctl.Sub = $Sub
}

# Comparaison des sources du processeur sous charge : 10 s de calcul (runspaces, comme l'analyse du turbo), puis arret.
# La source qui monte le plus (et reste plausible) suit la vraie temperature du processeur.
function Test-GBCpuTempSources([int]$Seconds = 10, [switch]$Apply) {
    $read = {
        $h = @{}
        if ($Script:SensOK) {
            [GBSensWmi]::Kick($false)
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            while ([GBSensWmi]::Busy -and $sw.ElapsedMilliseconds -lt 900) { Start-Sleep -Milliseconds 20 }
            if (-not [double]::IsNaN([GBSensWmi]::CpuTemp)) { $h[[GBSensWmi]::Vendor + ' (BIOS)'] = [double][GBSensWmi]::CpuTemp }
            if (-not [double]::IsNaN([GBSensWmi]::AcpiTemp)) { $h['ACPI (WMI)'] = [double][GBSensWmi]::AcpiTemp }
        }
        $tz = Get-GBThermalZoneTemp; if ($null -ne $tz) { $h['Windows (zone thermique)'] = [double]$tz }
        return $h
    }
    $rows = New-Object System.Collections.ArrayList
    $n = [math]::Max(2, [int]([Environment]::ProcessorCount / 2))
    $pss = @(); $mhzMax = $null
    [void]$rows.Add(@{ T = 0; V = (& $read) })
    try {
        for ($i = 0; $i -lt $n; $i++) {
            $p = [powershell]::Create()
            [void]$p.AddScript({ param($sec) $e = [DateTime]::Now.AddSeconds($sec); $x = 0; while ([DateTime]::Now -lt $e) { $x++ } }).AddArgument($Seconds)
            $pss += @{ P = $p; H = $p.BeginInvoke() }
        }
        $t0 = [System.Diagnostics.Stopwatch]::StartNew()
        for ($k = 1; $k -le $Seconds; $k++) {
            while ($t0.ElapsedMilliseconds -lt $k * 1000) { Start-Sleep -Milliseconds 50; try { [System.Windows.Forms.Application]::DoEvents() } catch {} }
            [void]$rows.Add(@{ T = $k; V = (& $read) })
            try { [void](Update-Perf -Force); $pp = Get-PerfValue 'cpuperf'; if ($null -ne $pp -and $Script:CpuBaseMhz) { $m = [double]$pp * $Script:CpuBaseMhz / 100; if ($null -eq $mhzMax -or $m -gt $mhzMax) { $mhzMax = $m } } } catch {}
        }
    } finally { foreach ($x in $pss) { try { $x.P.Stop() } catch {}; try { $x.P.Dispose() } catch {} } }
    $res = @{}
    foreach ($r in $rows) { foreach ($k in $r.V.Keys) { if (-not $res[$k]) { $res[$k] = @{ Start = $r.V[$k]; Peak = $r.V[$k]; N = 0 } }; $res[$k].N++; if ($r.V[$k] -gt $res[$k].Peak) { $res[$k].Peak = $r.V[$k] } } }
    $best = $null; $bestRise = 0.0
    foreach ($k in $res.Keys) { $rise = $res[$k].Peak - $res[$k].Start; $res[$k].Rise = $rise; if ($res[$k].Peak -le 110 -and $rise -gt $bestRise) { $bestRise = $rise; $best = $k } }
    $out = @{ Sources = $res; Best = $best; Rise = $bestRise; Threads = $n; Seconds = $Seconds; MaxMhz = $mhzMax; Rows = @($rows) }
    $Script:SensPick = $out
    $txt = @(foreach ($k in $res.Keys) { $k + " " + [math]::Round($res[$k].Start) + " -> " + [math]::Round($res[$k].Peak) + " C" }) -join ", "
    if (-not $txt) { $txt = "aucune source de temperature du processeur lisible" }
    Log ("Capteurs : test de charge " + $Seconds + " s (" + $n + " fils) : " + $txt + $(if ($best) { " - source retenue : " + $best } else { "" }))
    if ($Apply -and $best -and $res.Count -ge 2 -and $bestRise -ge 3) { (Get-GBSensorPrefs).CpuSource = $best; try { Save-Config } catch {} }
    return $out
}

# Reglages : unite, alertes, seuils personnalises
function Show-SensorSettings($Owner) {
    $p = Get-GBSensorPrefs
    $d = New-GBDialog "Reglages des capteurs" 520 360
    $null = Add-DlgLabel $d "Reglages des capteurs" 16 8 400 30 $fontPage $cCyan
    $null = Add-DlgLabel $d "Unite" 16 50 120 22 $fontBold $cText
    $cbU = New-GBComboCtl; $cbU.Location = New-Object System.Drawing.Point(140, 48); $cbU.Size = New-Object System.Drawing.Size(180, 24)
    [void]$cbU.Items.Add("Celsius (" + [char]0xB0 + "C)"); [void]$cbU.Items.Add("Fahrenheit (" + [char]0xB0 + "F)"); $cbU.SelectedIndex = $(if ($p.Unit -eq 'F') { 1 } else { 0 }); $d.Controls.Add($cbU)
    $chkA = Add-DlgCheck $d "Alerter si un composant atteint le seuil critique (journal, une fois par minute au plus)" 16 82 480 ([bool]$p.Alerts)
    $null = Add-DlgLabel $d "Seuils en degres Celsius :" 16 118 300 20 $fontBold $cText
    $null = Add-DlgLabel $d "chaud" 170 140 90 18 $fontSmall $cYellow
    $null = Add-DlgLabel $d "tres chaud" 270 140 90 18 $fontSmall (Get-GBTempColor 'hot')
    $null = Add-DlgLabel $d "critique" 370 140 90 18 $fontSmall $cRed
    $nums = @{}; $y = 162
    foreach ($row in @(@('cpu', 'Processeur'), @('gpu', 'Carte graphique'), @('ssd', 'SSD'))) {
        $null = Add-DlgLabel $d $row[1] 16 ($y + 3) 150 22 $fontUI $cText
        $th = Get-GBTempThresholds $row[0]; $list = @()
        for ($i = 0; $i -lt 3; $i++) {
            $n = New-Object System.Windows.Forms.NumericUpDown; $n.Minimum = 30; $n.Maximum = 110; $n.Value = [decimal][math]::Round($th[$i])
            $n.BackColor = $cDeep; $n.ForeColor = $cText; $n.BorderStyle = "FixedSingle"; $n.TextAlign = "Center"
            $n.Location = New-Object System.Drawing.Point((170 + 100 * $i), $y); $n.Size = New-Object System.Drawing.Size(80, 24); $d.Controls.Add($n); $list += $n
        }
        $nums[$row[0]] = $list; $y += 32
    }
    $bDef = Add-DlgButton $d "Valeurs par defaut" 16 282 170
    $bDef.Add_Click({ foreach ($k in @($nums.Keys)) { $df = Get-GBTempDefaults $k; for ($i = 0; $i -lt 3; $i++) { $nums[$k][$i].Value = [decimal][math]::Round($df[$i]) } } })
    Add-DlgOkCancel $d 282 508
    $own = $Owner; if (-not $own) { $own = $form }
    try {
        if ($d.ShowDialog($own) -eq 'OK') {
            $p.Unit = $(if ($cbU.SelectedIndex -eq 1) { 'F' } else { 'C' }); $p.Alerts = [bool]$chkA.Checked
            foreach ($k in @('cpu', 'gpu', 'ssd')) {
                $v = @($nums[$k] | ForEach-Object { [int]$_.Value }); $df = @(Get-GBTempDefaults $k | ForEach-Object { [int][math]::Round($_) })
                if ($v[0] -ge $v[1] -or $v[1] -ge $v[2] -or (($v -join ',') -eq ($df -join ','))) { $v = @() }   # incoherent ou egal au defaut : automatique
                if ($k -eq 'cpu') { $p.Cpu = $v } elseif ($k -eq 'gpu') { $p.Gpu = $v } else { $p.Ssd = $v }
            }
            Save-Config
            Log ("Capteurs : unite " + [char]0xB0 + $p.Unit + ", seuils CPU " + ((Get-GBTempThresholds 'cpu') -join '/') + ", GPU " + ((Get-GBTempThresholds 'gpu') -join '/') + ", SSD " + ((Get-GBTempThresholds 'ssd') -join '/'))
            if ($Script:SensUi) { Update-GBSensorsPanel }
        }
    } finally { $d.Dispose() }
}

# Fenetre detaillee des capteurs (non modale, une seule a la fois) : une carte par composant avec sa courbe sur 10 min
function Show-SensorsPanel {
    if ($Script:SensUi -and -not $Script:SensUi.Form.IsDisposed) {
        $f = $Script:SensUi.Form; if ($f.WindowState -eq 'Minimized') { $f.WindowState = 'Normal' }; $f.Activate(); return
    }
    if (-not $Script:SensInit) { try { Initialize-GBSensors } catch {} }
    $card = $cPanel; if ($cCard) { $card = $cCard }
    $d = New-GBDialog "Temperatures et capteurs" 776 612
    $d.ShowInTaskbar = $true; $d.MinimizeBox = $true; $d.KeyPreview = $true
    $null = Add-DlgLabel $d "Temperatures et capteurs" 16 8 500 30 $fontPage $cCyan
    $sub = Add-DlgLabel $d "Mesure toutes les 5 s, courbes sur les 10 dernieres minutes, min / max depuis l'ouverture de GameBoost." 16 40 740 20 $fontSmall $cMuted
    $ui = @{ Form = $d; Cards = @{}; Sub = $sub }
    # Une carte : panneau au fond du theme, bordure fine, courbe dedans ; texte complementaire en bas
    $mk = {
        param($key, $x, $y)
        $pn = New-Object System.Windows.Forms.Panel; $pn.BackColor = $card
        $pn.Location = New-Object System.Drawing.Point($x, $y); $pn.Size = New-Object System.Drawing.Size(364, 128)
        $pn.Add_Paint({ param($sd, $e) $r = $sd.ClientRectangle; $r.Width -= 1; $r.Height -= 1; $pe = New-Object System.Drawing.Pen($cLine); $e.Graphics.DrawRectangle($pe, $r); $pe.Dispose() })
        $sp = New-GBSparkCtl; $sp.BackColor = $card
        $sp.Location = New-Object System.Drawing.Point(12, 8); $sp.Size = New-Object System.Drawing.Size(340, 92)
        $ex = New-Object System.Windows.Forms.Label; $ex.Font = $fontSmall; $ex.ForeColor = $cMuted; $ex.BackColor = $card; $ex.AutoEllipsis = $true
        $ex.Location = New-Object System.Drawing.Point(12, 102); $ex.Size = New-Object System.Drawing.Size(340, 20)
        $pn.Controls.Add($sp); $pn.Controls.Add($ex); $d.Controls.Add($pn)
        $ui.Cards[$key] = @{ Panel = $pn; Spark = $sp; Extra = $ex }
    }
    & $mk 'cpu' 16 68; & $mk 'gpu' 392 68
    & $mk 'igpu' 16 206; & $mk 'ssd' 392 206
    & $mk 'fan' 16 344; & $mk 'power' 392 344
    # Pourquoi c'est chaud : un i7 HX de portable est concu pour monter a 90-95 C en charge ; le TURBO decide de cette chaleur
    $why = Add-DlgLabel $d "" 16 482 560 36 $fontSmall $cMuted
    $ui.Why = $why
    $bWhy = Add-DlgButton $d "Pourquoi c'est chaud ?" 16 524 190
    $tipW = "Le processeur accelere (turbo) tant qu'il reste sous sa limite de temperature : 90 C en jeu est normal sur un portable HX. " +
            "Pour le refroidir, baisse les GHz du TURBO (meme 10 % de moins = beaucoup moins chaud, presque autant d'images par seconde)."
    if ($tip) { $tip.SetToolTip($bWhy, $tipW) }
    $bWhy.Add_Click({ try { Show-TurboSettings } catch { Log ("Reglage du turbo indisponible : " + $_.Exception.Message) } })
    $bTest = Add-DlgButton $d "Tester les sources (10 s)" 214 524 200
    if ($tip) { $tip.SetToolTip($bTest, "Fait chauffer le processeur 10 secondes et compare les capteurs : celui qui monte suit la vraie temperature.") }
    # (fenetre non modale : les gestionnaires utilisent $this et $Script:SensUi, les variables de la fonction n'existent plus)
    $bTest.Add_Click({
        $b = $this; $ui = $Script:SensUi; if (-not $ui) { return }
        $b.Enabled = $false; $old = $b.Text; $b.Text = "Test en cours..."; $ui.Form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
        try {
            $r = Test-GBCpuTempSources 10 -Apply
            $parts = @(foreach ($k in $r.Sources.Keys) { $k + " : " + (Format-GBTemp $r.Sources[$k].Start) + " -> " + (Format-GBTemp $r.Sources[$k].Peak) })
            if ($parts.Count -eq 0) { $ui.Sub.Text = "Test : aucune source de temperature du processeur lisible sur ce PC." }
            else { $ui.Sub.Text = "Test : " + ($parts -join "  |  ") + $(if ($r.Best) { "  ->  retenue : " + $r.Best } else { "" }) }
            $ui.Sub.ForeColor = $cText
        } finally { $b.Text = $old; $b.Enabled = $true; if (-not $ui.Form.IsDisposed) { $ui.Form.Cursor = [System.Windows.Forms.Cursors]::Default } }
        Update-GBSensorsPanel
    })
    $bSet = Add-DlgButton $d "Reglages" 422 524 120
    $bSet.Add_Click({ Show-SensorSettings $this.FindForm() })
    $bClose = Add-DlgButton $d "Fermer" 652 524 100
    $bClose.Add_Click({ $this.FindForm().Close() })
    $d.CancelButton = $bClose
    $d.Add_FormClosed({ $Script:SensUi = $null })
    $Script:SensUi = $ui
    # Fenetre non modale : centree sur GameBoost (ou sur l'ecran si GameBoost est cache)
    $d.StartPosition = 'CenterScreen'
    if ($form.Visible -and $form.WindowState -ne 'Minimized') {
        $d.StartPosition = 'Manual'
        $k = [double]$Script:DpiScale
        $d.Location = New-Object System.Drawing.Point(($form.Left + [int](($form.Width - $d.Width * $k) / 2)), ($form.Top + [int](($form.Height - $d.Height * $k) / 2)))
    }
    try { [void](Update-GBSensors) } catch {}   # lecture immediate (charge NVML si besoin : puissance de la carte)
    Update-GBSensorsPanel
    if ($form.Visible) { $d.Show($form) } else { $d.Show() }
}
# Remplit les cartes avec la derniere mesure (appele toutes les 5 s tant que la fenetre est ouverte)
function Update-GBSensorsPanel {
    $ui = $Script:SensUi
    if (-not $ui -or $ui.Form.IsDisposed) { $Script:SensUi = $null; return }
    $o = Get-GBSensors; if (-not $o) { return }
    $w = $o.Why
    $setTip = { param($c, $t) if ($tip) { $tip.SetToolTip($c.Spark, [string]$t); $tip.SetToolTip($c.Extra, [string]$t) } }
    $c = $ui.Cards['cpu']
    $src = $o.CpuTempSrc; if (-not $src) { $src = "source : aucune" } else { $src = "source : " + $src }
    Update-GBSparkCtl $c.Spark 'CpuTemp' 'cpu' "PROCESSEUR" $src
    $c.Extra.Text = "Frequence " + (Format-GBSensorValue $o.CpuMhz 'mhz') + $(if ($null -ne $o.CpuTemp) { "  |  niveau : " + (Get-GBTempLevelText (Get-GBTempLevel $o.CpuTemp 'cpu')) } else { "" })
    & $setTip $c $(if ($null -eq $o.CpuTemp) { $w.CpuTemp } else { "Sources lisibles : " + ((@($o.CpuSources) | ForEach-Object { $_.Name + " " + (Format-GBTemp $_.T) }) -join ", ") })
    $c = $ui.Cards['gpu']
    $gn = $o.GpuName; if (-not $gn) { $gn = "CARTE GRAPHIQUE" }
    $src = "source : " + $(if ($o.GpuTempSrc) { $o.GpuTempSrc } elseif ($o.GpuSleep) { "carte en veille" } else { "aucune" })
    Update-GBSparkCtl $c.Spark 'GpuTemp' 'gpu' ("GPU DEDIE  " + $gn) $src
    $c.Extra.Text = "Frequence " + (Format-GBSensorValue $o.GpuClockMhz 'mhz') + "  |  memoire " + (Format-GBSensorValue $o.GpuMemMhz 'mhz') + $(if ($o.GpuTempMax) { "  |  limite " + (Format-GBTemp $o.GpuTempMax) } else { "" })
    & $setTip $c $(if ($null -eq $o.GpuTemp) { $w.GpuTemp } else { "Point chaud : n/d (" + $w.GpuHotspot + ")" })
    $c = $ui.Cards['igpu']
    $in = $o.IGpuName; if (-not $in) { $in = "aucune" }
    Update-GBSparkCtl $c.Spark 'IGpuTemp' 'gpu' ("GPU INTEGRE  " + $in) "temperature : voir le processeur"
    $c.Extra.Text = "Frequence " + (Format-GBSensorValue $o.IGpuClockMhz 'mhz')
    & $setTip $c $w.IGpuTemp
    $c = $ui.Cards['ssd']
    $hot = @($o.SsdTemps | Where-Object { $null -ne $_.Temp } | Sort-Object { $_.Temp } -Descending) | Select-Object -First 1
    $ssrc = "source : aucune"; if ($hot) { $ssrc = "source : " + $hot.Src }
    Update-GBSparkCtl $c.Spark 'SsdMax' 'ssd' "SSD (le plus chaud)" $ssrc
    $c.Extra.Text = (@($o.SsdTemps | ForEach-Object { $_.Name + " " + (Format-GBTemp $_.Temp) }) -join "  |  ")
    if (-not $c.Extra.Text) { $c.Extra.Text = "Aucun disque interne" }
    & $setTip $c $(if ($null -eq $o.SsdMax) { $w.SsdMax } else { "Mesure toutes les 60 s. " + $c.Extra.Text })
    $c = $ui.Cards['fan']
    Update-GBSparkCtl $c.Spark 'CpuFanRpm' 'rpm' "VENTILATEUR PROCESSEUR" $(if ($null -ne $o.CpuFanRpm) { "source : " + $o.CpuTempSrc } else { "source : aucune" })
    $c.Extra.Text = "Ventilateur carte graphique " + (Format-GBSensorValue $o.GpuFanRpm 'rpm') + $(if ($null -ne $o.GpuFanPct) { " (" + [int]$o.GpuFanPct + " %)" } else { "" })
    & $setTip $c $(if ($null -eq $o.CpuFanRpm) { $w.CpuFanRpm } else { "Vitesses lues dans le BIOS (lecture seule)." })
    $c = $ui.Cards['power']
    Update-GBSparkCtl $c.Spark 'GpuPowerW' 'power' "PUISSANCE CARTE GRAPHIQUE" $(if ($null -ne $o.GpuPowerW) { "source : NVIDIA (NVML)" } else { "source : aucune" })
    $c.Extra.Text = "Processeur " + (Format-GBSensorValue $o.CpuMhz 'mhz') + "  |  carte " + (Format-GBSensorValue $o.GpuClockMhz 'mhz')
    & $setTip $c $(if ($null -eq $o.GpuPowerW) { $w.GpuPowerW } else { "Consommation instantanee de la carte graphique." })
    # Texte d'explication selon le niveau du processeur
    $lv = Get-GBTempLevel $o.CpuTemp 'cpu'
    $th = Get-GBTempThresholds 'cpu'
    if ($lv -eq 'hot' -or $lv -eq 'crit') { $ui.Why.Text = "Processeur a " + (Format-GBTemp $o.CpuTemp) + " : le turbo le pousse jusqu'a sa limite. Baisse les GHz du TURBO pour gagner 10 a 15 degres sans perdre beaucoup d'images."; $ui.Why.ForeColor = (Get-GBTempColor $lv) }
    elseif ($null -eq $o.CpuTemp) { $ui.Why.Text = "Temperature du processeur : " + $w.CpuTemp; $ui.Why.ForeColor = $cMuted }
    else { $ui.Why.Text = "Seuils du processeur : chaud " + (Format-GBTemp $th[0]) + ", tres chaud " + (Format-GBTemp $th[1]) + ", critique " + (Format-GBTemp $th[2]) + ". Un portable HX tourne normalement a 85-95 en jeu."; $ui.Why.ForeColor = $cMuted }
}
function Get-GBTempLevelText([string]$Level) {
    switch ($Level) { 'ok' { return "normal" } 'warm' { return "chaud" } 'hot' { return "tres chaud" } 'crit' { return "critique" } }
    return "inconnu"
}

# Action du menu Performances (file d'attente du module raccourcis, puis declaration directe si elle existe deja)
$Script:SensActionDef = @{ Id = 'sensors.panel'; Label = 'Temperatures et capteurs...'; Menu = 'Performances'; Run = { Show-SensorsPanel }; DefaultKey = 'Ctrl+T'; Description = 'Temperatures du processeur, des cartes graphiques et des SSD, avec courbes sur 10 min' }
if (-not $Script:GBPendingActions) { $Script:GBPendingActions = New-Object System.Collections.ArrayList }
[void]$Script:GBPendingActions.Add($Script:SensActionDef)
function Register-GBSensorActions {
    if (-not (Get-Command Register-GBAction -ErrorAction SilentlyContinue)) { return $false }
    $a = $Script:SensActionDef
    Register-GBAction -Id $a.Id -Label $a.Label -Menu $a.Menu -Run $a.Run -DefaultKey $a.DefaultKey -Description $a.Description
    return $true
}
# Demarrage des mesures : 1,2 s apres l'affichage (les crochets du socle existent alors), ou par Add-GBStartHook
$Script:SensStartTimer = New-Object System.Windows.Forms.Timer
$Script:SensStartTimer.Interval = 1200
$Script:SensStartTimer.Add_Tick({ $Script:SensStartTimer.Stop(); $Script:SensStartTimer.Dispose(); try { Initialize-GBSensors } catch { Log ("Capteurs indisponibles : " + $_.Exception.Message) } })
$Script:SensStartTimer.Start()
try { if (Get-Command Add-GBStartHook -ErrorAction SilentlyContinue) { Add-GBStartHook { Initialize-GBSensors } } } catch {}
if (-not $Script:SensOK -and $Script:SensError) { Log ("Capteurs : composants C# indisponibles, mesures reduites (" + $Script:SensError + ")") }

# --- Ecrans : eteindre / rallumer UN ecran choisi (veille DDC/CI, detacher du bureau, voile noir) ---
# Tout ce que GameBoost eteint est note dans la config (MonitorsOff) : rallume a la fermeture et apres un arret brutal.
$monSrc = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Threading;
using System.Windows.Forms;

// Un ecran actif : nom Windows (\\.\DISPLAYn), nom lisible, zone, mode d'affichage exact
public class GBMonInfo {
    public string Device = "", Name = "", Path = "";
    public bool Primary, Internal;
    public int X, Y, W, H, Hz, Bpp, Orient, Tech = -1;
}
// Mode d'un ecran a remettre (W = 0 : ecran detache du bureau)
public class GBMonMode {
    public string Device = "";
    public int X, Y, W, H, Hz, Bpp, Orient;
    public bool Primary;
}

public static class GBMon {
    public static bool DryRun = false;                        // test : rien n'est envoye a Windows, les appels sont notes
    public static List<string> Calls = new List<string>();

    [StructLayout(LayoutKind.Sequential)] struct RECT { public int L, T, R, B; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] struct MONITORINFOEX {
        public int cbSize; public RECT rcMonitor; public RECT rcWork; public int dwFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string szDevice; }
    delegate bool MonEnumProc(IntPtr h, IntPtr hdc, ref RECT r, IntPtr data);
    [DllImport("user32.dll")] static extern bool EnumDisplayMonitors(IntPtr hdc, IntPtr clip, MonEnumProc cb, IntPtr data);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool GetMonitorInfo(IntPtr h, ref MONITORINFOEX mi);

    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] public struct DEVMODE {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName; public short dmSpecVersion, dmDriverVersion, dmSize, dmDriverExtra; public int dmFields;
        public int dmPositionX, dmPositionY, dmDisplayOrientation, dmDisplayFixedOutput; public short dmColor, dmDuplex, dmYResolution, dmTTOption, dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName; public short dmLogPixels; public int dmBitsPerPel, dmPelsWidth, dmPelsHeight, dmDisplayFlags, dmDisplayFrequency,
        dmICMMethod, dmICMIntent, dmMediaType, dmDitherType, dmReserved1, dmReserved2, dmPanningWidth, dmPanningHeight; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] struct DISPLAY_DEVICE { public int cb;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string DeviceName; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceString;
        public int StateFlags; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceID; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string DeviceKey; }
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool EnumDisplayDevices(string dev, int i, ref DISPLAY_DEVICE dd, int flags);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern bool EnumDisplaySettings(string dev, int mode, ref DEVMODE dm);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int ChangeDisplaySettingsEx(string dev, ref DEVMODE dm, IntPtr hwnd, int flags, IntPtr p);
    [DllImport("user32.dll", CharSet = CharSet.Unicode, EntryPoint = "ChangeDisplaySettingsExW")] static extern int ChangeDisplaySettingsApply(IntPtr dev, IntPtr dm, IntPtr hwnd, int flags, IntPtr p);

    // QueryDisplayConfig : nom du modele et type de branchement (dalle interne ou non)
    [StructLayout(LayoutKind.Sequential)] struct LUID { public uint Low; public int High; }
    [StructLayout(LayoutKind.Sequential)] struct PATH_SOURCE { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] struct PATH_TARGET { public LUID adapterId; public uint id; public uint modeInfoIdx; public uint outputTechnology; public uint rotation; public uint scaling;
        public uint refreshNum; public uint refreshDen; public uint scanLineOrdering; public int targetAvailable; public uint statusFlags; }
    [StructLayout(LayoutKind.Sequential)] struct PATH_INFO { public PATH_SOURCE src; public PATH_TARGET tgt; public uint flags; }
    [StructLayout(LayoutKind.Sequential, Size = 64)] struct MODE_INFO { public uint infoType; public uint id; public LUID adapterId; }
    [StructLayout(LayoutKind.Sequential)] struct DI_HEADER { public uint type; public uint size; public LUID adapterId; public uint id; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] struct SOURCE_NAME { public DI_HEADER h;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string gdi; }
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)] struct TARGET_NAME { public DI_HEADER h; public uint flags; public uint tech; public ushort edidMan; public ushort edidProd; public uint connector;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 64)] public string friendly; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string path; }
    [DllImport("user32.dll")] static extern int GetDisplayConfigBufferSizes(uint flags, out uint np, out uint nm);
    [DllImport("user32.dll")] static extern int QueryDisplayConfig(uint flags, ref uint np, [Out] PATH_INFO[] p, ref uint nm, [Out] MODE_INFO[] m, IntPtr topo);
    [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(ref SOURCE_NAME r);
    [DllImport("user32.dll")] static extern int DisplayConfigGetDeviceInfo(ref TARGET_NAME r);

    // DDC/CI (dxva2) : commande d'alimentation 0xD6 de l'ecran
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode, Pack = 1)] struct PHYS { public IntPtr h; [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 128)] public string desc; }
    [DllImport("dxva2.dll")] static extern bool GetNumberOfPhysicalMonitorsFromHMONITOR(IntPtr hMon, out uint n);
    [DllImport("dxva2.dll")] static extern bool GetPhysicalMonitorsFromHMONITOR(IntPtr hMon, uint n, [Out] PHYS[] arr);
    [DllImport("dxva2.dll")] static extern bool DestroyPhysicalMonitors(uint n, PHYS[] arr);
    [DllImport("dxva2.dll")] static extern bool GetVCPFeatureAndVCPFeatureReply(IntPtr h, byte code, IntPtr type, out uint cur, out uint max);
    [DllImport("dxva2.dll")] static extern bool SetVCPFeature(IntPtr h, byte code, uint val);

    const int DM_POSITION = 0x20, DM_ORIENT = 0x80, DM_BPP = 0x40000, DM_W = 0x80000, DM_H = 0x100000, DM_HZ = 0x400000;
    const int CDS_UPDATEREGISTRY = 1, CDS_SET_PRIMARY = 0x10, CDS_NORESET = 0x10000000, CDS_RESET = 0x40000000;

    // Ecrans actifs (ceux du bureau)
    public static GBMonInfo[] List() {
        List<GBMonInfo> r = new List<GBMonInfo>();
        Dictionary<string, TARGET_NAME> names = new Dictionary<string, TARGET_NAME>(StringComparer.OrdinalIgnoreCase);
        try { Targets(2, names, null); } catch { }
        List<IntPtr> hs = new List<IntPtr>();
        EnumDisplayMonitors(IntPtr.Zero, IntPtr.Zero, delegate(IntPtr h, IntPtr hdc, ref RECT rc, IntPtr d) { hs.Add(h); return true; }, IntPtr.Zero);
        foreach (IntPtr h in hs) {
            MONITORINFOEX mi = new MONITORINFOEX(); mi.cbSize = Marshal.SizeOf(mi);
            if (!GetMonitorInfo(h, ref mi)) continue;
            GBMonInfo m = new GBMonInfo();
            m.Device = mi.szDevice; m.Primary = (mi.dwFlags & 1) != 0;
            m.X = mi.rcMonitor.L; m.Y = mi.rcMonitor.T; m.W = mi.rcMonitor.R - mi.rcMonitor.L; m.H = mi.rcMonitor.B - mi.rcMonitor.T;
            DEVMODE dm = NewMode();
            if (EnumDisplaySettings(m.Device, -1, ref dm)) { m.Hz = dm.dmDisplayFrequency; m.Bpp = dm.dmBitsPerPel; m.Orient = dm.dmDisplayOrientation; }
            TARGET_NAME t;
            if (names.TryGetValue(m.Device, out t)) {
                m.Name = (t.friendly ?? "").Trim(); m.Path = t.path ?? ""; m.Tech = (int)t.tech;
                m.Internal = IsInternalTech(t.tech);
            }
            r.Add(m);
        }
        return r.ToArray();
    }
    // Dalle de portable : interne, eDP (DisplayPort embarque), UDI embarque, ou LVDS (anciens portables)
    public static bool IsInternalTech(uint tech) { return tech == 0x80000000 || tech == 11 || tech == 13 || tech == 6; }

    // flags 2 = chemins actifs, 1 = tous ; available : chemins des ecrans branches (pour savoir si un ecran detache est encore la)
    static void Targets(uint flags, Dictionary<string, TARGET_NAME> byGdi, List<string> available) {
        uint np, nm;
        if (GetDisplayConfigBufferSizes(flags, out np, out nm) != 0) return;
        PATH_INFO[] paths = new PATH_INFO[np]; MODE_INFO[] modes = new MODE_INFO[nm];
        if (QueryDisplayConfig(flags, ref np, paths, ref nm, modes, IntPtr.Zero) != 0) return;
        for (int i = 0; i < np; i++) {
            TARGET_NAME t = new TARGET_NAME(); t.h.type = 2; t.h.size = (uint)Marshal.SizeOf(typeof(TARGET_NAME)); t.h.adapterId = paths[i].tgt.adapterId; t.h.id = paths[i].tgt.id;
            if (DisplayConfigGetDeviceInfo(ref t) != 0) continue;
            if (available != null && paths[i].tgt.targetAvailable != 0 && !string.IsNullOrEmpty(t.path) && !available.Contains(t.path)) available.Add(t.path);
            if (byGdi == null) continue;
            SOURCE_NAME s = new SOURCE_NAME(); s.h.type = 1; s.h.size = (uint)Marshal.SizeOf(typeof(SOURCE_NAME)); s.h.adapterId = paths[i].src.adapterId; s.h.id = paths[i].src.id;
            if (DisplayConfigGetDeviceInfo(ref s) != 0 || string.IsNullOrEmpty(s.gdi)) continue;
            if (!byGdi.ContainsKey(s.gdi)) byGdi[s.gdi] = t;
        }
    }
    // Ecran encore branche ? (chemin du moniteur connu : QueryDisplayConfig ; sinon moniteur rattache a la sortie)
    public static bool IsConnected(string dev, string path) {
        try {
            if (!string.IsNullOrEmpty(path)) {
                List<string> av = new List<string>(); Targets(1, null, av);
                foreach (string p in av) if (string.Equals(p, path, StringComparison.OrdinalIgnoreCase)) return true;
                return false;
            }
            DISPLAY_DEVICE d = new DISPLAY_DEVICE(); d.cb = Marshal.SizeOf(d);
            return EnumDisplayDevices(dev, 0, ref d, 0) && (d.StateFlags & 3) != 0;
        } catch { return true; }
    }
    // Signature rapide des ecrans actifs (pour voir un branchement / debranchement)
    public static string Signature() {
        List<string> r = new List<string>();
        foreach (Screen s in Screen.AllScreens) r.Add(s.DeviceName + "=" + s.Bounds.X + "," + s.Bounds.Y + "," + s.Bounds.Width + "x" + s.Bounds.Height + (s.Primary ? "*" : ""));
        r.Sort(StringComparer.Ordinal);
        return string.Join(";", r.ToArray());
    }

    static DEVMODE NewMode() { DEVMODE dm = new DEVMODE(); dm.dmSize = (short)Marshal.SizeOf(typeof(DEVMODE)); return dm; }
    // Mode actuel exact (null si l'ecran n'est pas sur le bureau)
    public static GBMonMode GetMode(string dev) {
        DEVMODE dm = NewMode();
        if (!EnumDisplaySettings(dev, -1, ref dm) || dm.dmPelsWidth <= 0) return null;
        bool active = false;
        foreach (Screen s in Screen.AllScreens) if (string.Equals(s.DeviceName, dev, StringComparison.OrdinalIgnoreCase)) active = true;
        if (!active) return null;
        GBMonMode m = new GBMonMode();
        m.Device = dev; m.X = dm.dmPositionX; m.Y = dm.dmPositionY; m.W = dm.dmPelsWidth; m.H = dm.dmPelsHeight;
        m.Hz = dm.dmDisplayFrequency; m.Bpp = dm.dmBitsPerPel; m.Orient = dm.dmDisplayOrientation;
        foreach (Screen s in Screen.AllScreens) if (s.Primary && string.Equals(s.DeviceName, dev, StringComparison.OrdinalIgnoreCase)) m.Primary = true;
        return m;
    }
    // Applique plusieurs ecrans d'un coup (W = 0 : detacher), puis un seul appel global : 0 = reussi
    public static int ApplyLayout(GBMonMode[] list) {
        int first = 0;
        foreach (GBMonMode m in list) {
            DEVMODE dm = NewMode();
            int flags = CDS_UPDATEREGISTRY | CDS_NORESET;
            if (m.W <= 0) { dm.dmFields = DM_POSITION | DM_W | DM_H; }
            else {
                dm.dmFields = DM_POSITION | DM_W | DM_H | DM_ORIENT;
                dm.dmPositionX = m.X; dm.dmPositionY = m.Y; dm.dmPelsWidth = m.W; dm.dmPelsHeight = m.H; dm.dmDisplayOrientation = m.Orient;
                if (m.Hz > 1) { dm.dmFields |= DM_HZ; dm.dmDisplayFrequency = m.Hz; }
                if (m.Bpp > 0) { dm.dmFields |= DM_BPP; dm.dmBitsPerPel = m.Bpp; }
                if (m.Primary) flags |= CDS_SET_PRIMARY;
            }
            int rc = 0;
            if (DryRun) Calls.Add("CDS " + m.Device + " fields=0x" + dm.dmFields.ToString("X") + " pos=" + dm.dmPositionX + "," + dm.dmPositionY + " size=" + dm.dmPelsWidth + "x" + dm.dmPelsHeight +
                                   " hz=" + dm.dmDisplayFrequency + " bpp=" + dm.dmBitsPerPel + " orient=" + dm.dmDisplayOrientation + " flags=0x" + flags.ToString("X"));
            else rc = ChangeDisplaySettingsEx(m.Device, ref dm, IntPtr.Zero, flags, IntPtr.Zero);
            if (rc != 0 && first == 0) first = rc;
        }
        int g = 0;
        if (DryRun) Calls.Add("CDS appliquer (global)");
        else g = ChangeDisplaySettingsApply(IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, 0, IntPtr.Zero);
        return first != 0 ? first : g;
    }
    // Remet le mode actuel tel quel (nouvelle synchro du signal : reveille un ecran reste en veille)
    public static int Resync(string dev) {
        DEVMODE dm = NewMode();
        if (!EnumDisplaySettings(dev, -1, ref dm)) return -99;
        dm.dmFields = DM_W | DM_H | DM_HZ;
        if (DryRun) { Calls.Add("CDS resync " + dev); return 0; }
        return ChangeDisplaySettingsEx(dev, ref dm, IntPtr.Zero, CDS_RESET, IntPtr.Zero);
    }

    static IntPtr HMonOf(string dev) {
        IntPtr found = IntPtr.Zero;
        List<IntPtr> hs = new List<IntPtr>();
        EnumDisplayMonitors(IntPtr.Zero, IntPtr.Zero, delegate(IntPtr h, IntPtr hdc, ref RECT rc, IntPtr d) { hs.Add(h); return true; }, IntPtr.Zero);
        foreach (IntPtr h in hs) {
            MONITORINFOEX mi = new MONITORINFOEX(); mi.cbSize = Marshal.SizeOf(mi);
            if (GetMonitorInfo(h, ref mi) && string.Equals(mi.szDevice, dev, StringComparison.OrdinalIgnoreCase)) found = h;
        }
        return found;
    }
    static PHYS[] Phys(string dev) {
        IntPtr hm = HMonOf(dev); uint n;
        if (hm == IntPtr.Zero || !GetNumberOfPhysicalMonitorsFromHMONITOR(hm, out n) || n == 0) return null;
        PHYS[] a = new PHYS[n];
        if (!GetPhysicalMonitorsFromHMONITOR(hm, n, a)) return null;
        return a;
    }
    // Lecture seule de 0xD6 : -1 = DDC impossible, sinon l'etat (1 allume, 4/5 eteint)
    public static int DdcRead(string dev) {
        PHYS[] a = null;
        try {
            a = Phys(dev); if (a == null) return -1;
            for (int i = 0; i < a.Length; i++) { uint cur, max; if (GetVCPFeatureAndVCPFeatureReply(a[i].h, 0xD6, IntPtr.Zero, out cur, out max)) return (int)cur; }
            return -1;
        } catch { return -1; } finally { if (a != null) try { DestroyPhysicalMonitors((uint)a.Length, a); } catch { } }
    }
    public static bool DdcSet(string dev, int value) {
        if (DryRun) { Calls.Add("DDC " + dev + " D6=" + value); return true; }
        PHYS[] a = null;
        try {
            a = Phys(dev); if (a == null) return false;
            bool ok = false;
            for (int i = 0; i < a.Length; i++) if (SetVCPFeature(a[i].h, 0xD6, (uint)value)) ok = true;
            return ok;
        } catch { return false; } finally { if (a != null) try { DestroyPhysicalMonitors((uint)a.Length, a); } catch { } }
    }
    // Luminosite d'un ecran externe (code DDC 0x10) : lue et reglee en arriere-plan, une commande a la fois
    static readonly Dictionary<string, int> _lum = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
    static readonly object _lumLock = new object();
    // -2 = pas encore lu, -1 = impossible, sinon valeur | (maximum << 16)
    public static int LumKnown(string dev) { lock (_lum) { int v; return _lum.TryGetValue(dev, out v) ? v : -2; } }
    static int VcpRead(string dev, byte code) {
        PHYS[] a = null;
        try {
            a = Phys(dev); if (a == null) return -1;
            for (int i = 0; i < a.Length; i++) { uint cur, max; if (GetVCPFeatureAndVCPFeatureReply(a[i].h, code, IntPtr.Zero, out cur, out max) && max > 0) return (int)(cur & 0xFFFF) | ((int)(max & 0x7FFF) << 16); }
            return -1;
        } catch { return -1; } finally { if (a != null) try { DestroyPhysicalMonitors((uint)a.Length, a); } catch { } }
    }
    public static void ProbeLumAsync(string[] devs) {
        ThreadPool.QueueUserWorkItem(delegate {
            lock (_lumLock) foreach (string d in devs) { int v = VcpRead(d, 0x10); lock (_lum) { _lum[d] = v; } }
        });
    }
    public static void LumSetAsync(string dev, int value) {
        ThreadPool.QueueUserWorkItem(delegate {
            lock (_lumLock) {
                PHYS[] a = null;
                try {
                    a = Phys(dev); if (a == null) return;
                    bool ok = false;
                    for (int i = 0; i < a.Length; i++) if (SetVCPFeature(a[i].h, 0x10, (uint)value)) ok = true;
                    if (ok) lock (_lum) { int old; int max = 100; if (_lum.TryGetValue(dev, out old) && old > 0) max = old >> 16; _lum[dev] = value | (max << 16); }
                } catch { } finally { if (a != null) try { DestroyPhysicalMonitors((uint)a.Length, a); } catch { } }
            }
        });
    }
    // Capacite DDC lue en arriere-plan (une lecture DDC peut prendre 50 a 500 ms)
    static readonly Dictionary<string, int> _ddc = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
    public static int DdcKnown(string dev) { lock (_ddc) { int v; return _ddc.TryGetValue(dev, out v) ? v : -2; } }
    public static void DdcRemember(string dev, int v) { lock (_ddc) { _ddc[dev] = v; } }
    public static void DdcReset() { lock (_ddc) { _ddc.Clear(); } }
    public static void ProbeDdcAsync(string[] devs) {
        ThreadPool.QueueUserWorkItem(delegate {
            foreach (string d in devs) { if (DdcKnown(d) != -2) continue; int v = DdcRead(d); DdcRemember(d, v); }
        });
    }
}

// Voile noir plein ecran : double-clic ou Echap pour le retirer, petit texte discret qui s'efface
public class GBMonVeil : Form {
    public string Device = "";
    public bool ByUser;
    public string Hint = "Ecran eteint par GameBoost - double-clic pour rallumer";
    readonly Rectangle _b;
    readonly int _auto, _fadeMs;
    readonly System.Windows.Forms.Timer _t = new System.Windows.Forms.Timer();
    readonly Stopwatch _sw = Stopwatch.StartNew();
    double _hintAt = 0;     // debut de l'affichage du texte (ms)
    bool _hintIn = false;   // texte qui revient (souris bougee)
    float _hint = 1f;
    Point _last = new Point(-10000, -10000);
    Font _f;
    public GBMonVeil(Rectangle bounds, int autoCloseMs, int fadeMs) {
        _b = bounds; _auto = autoCloseMs; _fadeMs = fadeMs;
        FormBorderStyle = FormBorderStyle.None; BackColor = Color.Black; ForeColor = Color.Gray; ShowInTaskbar = false;
        StartPosition = FormStartPosition.Manual; Bounds = bounds; TopMost = true; KeyPreview = true; DoubleBuffered = true;
        Text = "GameBoost - ecran eteint"; AutoScaleMode = AutoScaleMode.None;
        _f = new Font("Segoe UI", 10f);
        if (_fadeMs > 0) Opacity = 0.0;
        _t.Interval = 15; _t.Tick += Tick;
    }
    protected override bool ShowWithoutActivation { get { return true; } }   // ne vole pas le clavier au jeu
    protected override CreateParams CreateParams { get { CreateParams cp = base.CreateParams; cp.ExStyle |= 0x80; return cp; } }   // hors Alt+Tab
    protected override void OnShown(EventArgs e) { base.OnShown(e); Bounds = _b; _t.Start(); }
    static float Out(double p) { if (p <= 0) return 0f; if (p >= 1) return 1f; double q = 1 - p; return (float)(1 - q * q * q); }
    void Tick(object s, EventArgs e) {
        double now = _sw.Elapsed.TotalMilliseconds;
        bool busy = false;
        if (_fadeMs > 0 && Opacity < 1.0) { double p = now / _fadeMs; Opacity = p >= 1 ? 1.0 : Math.Max(0.01, Out(p)); busy = true; }
        double t = now - _hintAt; float h;
        if (_hintIn && t < 200) h = Math.Max(_hint, Out(t / 200.0));
        else if (t < 2800) { h = 1f; _hintIn = false; }
        else h = 1f - Out((t - 2800) / 900.0);
        if (Math.Abs(h - _hint) > 0.004f) { _hint = h; Invalidate(); }
        if (_hint > 0.004f) busy = true;
        if (_auto > 0 && now >= _auto) { ByUser = false; Close(); return; }
        _t.Interval = busy ? 15 : 400;
    }
    protected override void OnPaint(PaintEventArgs e) {
        base.OnPaint(e);
        if (_hint <= 0.004f) return;
        int v = (int)(118 * _hint);
        using (SolidBrush br = new SolidBrush(Color.FromArgb(v, v, v))) {
            SizeF sz = e.Graphics.MeasureString(Hint, _f);
            e.Graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.ClearTypeGridFit;
            e.Graphics.DrawString(Hint, _f, br, (ClientSize.Width - sz.Width) / 2f, ClientSize.Height * 0.86f - sz.Height / 2f);
        }
    }
    // La souris bouge sur le voile : le texte revient un instant
    protected override void OnMouseMove(MouseEventArgs e) {
        base.OnMouseMove(e);
        if (Math.Abs(e.X - _last.X) + Math.Abs(e.Y - _last.Y) > 24) {
            bool first = _last.X == -10000; _last = e.Location;
            if (!first && _hint < 0.6f) { _hintIn = true; _hintAt = _sw.Elapsed.TotalMilliseconds; _t.Interval = 15; }
        }
    }
    protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); try { Activate(); } catch { } }
    protected override void OnMouseDoubleClick(MouseEventArgs e) { base.OnMouseDoubleClick(e); ByUser = true; Close(); }
    protected override void OnKeyDown(KeyEventArgs e) { base.OnKeyDown(e); if (e.KeyCode == Keys.Escape) { ByUser = true; Close(); } }
    protected override void Dispose(bool disposing) { if (disposing) { _t.Stop(); _t.Dispose(); if (_f != null) _f.Dispose(); } base.Dispose(disposing); }
}
'@
$Script:MonOK = $false
try {
    $monRefs = @('System.Windows.Forms', 'System.Drawing')
    if ($uiRefs -and $PSVersionTable.PSEdition -eq 'Core') { $monRefs = $uiRefs }
    $Script:MonOK = [bool](Add-GBCompiled 'GBMon' $monSrc $monRefs 'GBMonVeil')
} catch { $Script:MonOK = $false }
$Script:MonOff     = @{}     # \\.\DISPLAYn -> @{ Device; Key; Name; Method; Saved; Layout; WasPrimary; Shift; Time; Veil }
$Script:MonVeils   = New-Object System.Collections.ArrayList
$Script:MonList    = @()     # derniere liste (menus, raccourcis : sans nouvelle lecture)
$Script:MonSig     = ''
$Script:MonMethodNames = [ordered]@{ auto = 'Auto'; ddc = 'Veille DDC'; detach = 'Detacher du bureau'; veil = 'Voile noir' }

# Acces a Windows (remplacables dans les tests par un faux PC)
function Get-GBMonRaw {
    if ($Script:MonOK) { try { return @([GBMon]::List()) } catch {} }
    $r = @()
    foreach ($s in [System.Windows.Forms.Screen]::AllScreens) {
        $r += [pscustomobject]@{ Device = $s.DeviceName; Name = ''; Path = ''; Primary = $s.Primary; Internal = $false
                                 X = $s.Bounds.X; Y = $s.Bounds.Y; W = $s.Bounds.Width; H = $s.Bounds.Height; Hz = 0; Bpp = 0; Orient = 0; Tech = -1 }
    }
    return $r
}
function Get-GBMonMode([string]$Device) {
    if (-not $Script:MonOK) { return $null }
    $m = $null; try { $m = [GBMon]::GetMode($Device) } catch {}
    if (-not $m) { return $null }
    return @{ Device = $m.Device; X = $m.X; Y = $m.Y; W = $m.W; H = $m.H; Hz = $m.Hz; Bpp = $m.Bpp; Orient = $m.Orient; Primary = [bool]$m.Primary }
}
function Invoke-GBMonApply($Plan) {
    if (-not $Script:MonOK) { return -99 }
    $arr = New-Object 'System.Collections.Generic.List[GBMonMode]'
    foreach ($p in @($Plan)) {
        $o = New-Object GBMonMode
        $o.Device = [string]$p.Device; $o.X = [int]$p.X; $o.Y = [int]$p.Y; $o.W = [int]$p.W; $o.H = [int]$p.H
        $o.Hz = [int]$p.Hz; $o.Bpp = [int]$p.Bpp; $o.Orient = [int]$p.Orient; $o.Primary = [bool]$p.Primary
        $arr.Add($o)
    }
    return [int][GBMon]::ApplyLayout($arr.ToArray())
}
function Invoke-GBMonDdc([string]$Device, [int]$Value) { if (-not $Script:MonOK) { return $false }; return [bool][GBMon]::DdcSet($Device, $Value) }
function Read-GBMonDdc([string]$Device) { if (-not $Script:MonOK) { return -1 }; return [int][GBMon]::DdcRead($Device) }
function Test-GBMonConnected([string]$Device, [string]$Key) {
    if (-not $Script:MonOK) { return $true }
    $p = ''; if ($Key -and $Key -ne $Device) { $p = $Key }
    try { return [bool][GBMon]::IsConnected($Device, $p) } catch { return $true }
}

# Mode d'un ecran en texte court pour la config : "\\.\DISPLAY2|x|y|largeur|hauteur|Hz|bits|orientation|principal"
function ConvertTo-GBMonModeText($m) { return ([string]$m.Device + '|' + [int]$m.X + '|' + [int]$m.Y + '|' + [int]$m.W + '|' + [int]$m.H + '|' + [int]$m.Hz + '|' + [int]$m.Bpp + '|' + [int]$m.Orient + '|' + [int][bool]$m.Primary) }
function ConvertFrom-GBMonModeText([string]$t) {
    $p = $t -split '\|'; if ($p.Count -lt 9) { return $null }
    return @{ Device = $p[0]; X = [int]$p[1]; Y = [int]$p[2]; W = [int]$p[3]; H = [int]$p[4]; Hz = [int]$p[5]; Bpp = [int]$p[6]; Orient = [int]$p[7]; Primary = ($p[8] -eq '1') }
}
function Get-GBMonNum([string]$Device) { if ($Device -match '(\d+)\s*$') { return [int]$Matches[1] }; return 999 }
function Get-GBMonName($m) {
    $n = [string]$m.Name
    if ($n) { return $n }
    if ($m.Internal) { return 'Ecran du portable' }
    return ('Ecran ' + (Get-GBMonNum ([string]$m.Device)))
}
function Get-GBMonPref([string]$Key) {
    $p = $null; try { $p = $Script:Config.MonitorPrefs[$Key] } catch {}
    if ($p -and $Script:MonMethodNames.Contains([string]$p)) { return [string]$p }
    return 'auto'
}
# Veille DDC possible ? (lecture de 0xD6 en arriere-plan, sinon tout de suite ; jamais sur un ecran deja eteint)
function Test-GBMonDdc($m) {
    if (-not $Script:MonOK -or $m.Internal) { return $false }
    $k = [GBMon]::DdcKnown([string]$m.Device)
    if ($k -eq -2) { $k = Read-GBMonDdc ([string]$m.Device); [GBMon]::DdcRemember([string]$m.Device, $k) }
    return ($k -ge 0)
}

# Liste des ecrans : actifs + ceux que GameBoost a detaches (Index stable : ordre des sorties \\.\DISPLAYn)
function Get-GBMonitors([switch]$NoDdc) {
    $list = New-Object System.Collections.ArrayList
    $seen = @{}
    foreach ($m in @(Get-GBMonRaw)) {
        $dev = [string]$m.Device; if (-not $dev -or $seen.ContainsKey($dev)) { continue }
        $seen[$dev] = $true
        $key = $dev; if ($m.Path) { $key = [string]$m.Path }
        $e = $Script:MonOff[$dev]
        if ($e -and $e.Method -eq 'detach') { $e = $null }   # rallume entre-temps (Win+P...) : corrige par la verification minute
        $methods = @(); $ddc = $false
        if ($Script:MonOK -and -not $m.Internal) {
            if ($e -and $e.Method -eq 'ddc') { $ddc = $true }
            elseif ($NoDdc -or $e) { $ddc = ([GBMon]::DdcKnown($dev) -ge 0) }
            else { $ddc = Test-GBMonDdc $m }
        }
        if ($ddc) { $methods += 'ddc' }
        if ($Script:MonOK) { $methods += 'detach' }
        $methods += 'veil'
        [void]$list.Add([pscustomobject]@{
            Index = 0; Name = (Get-GBMonName $m); Device = $dev; Key = $key; Primary = [bool]$m.Primary; Internal = [bool]$m.Internal
            Bounds = (New-Object System.Drawing.Rectangle([int]$m.X, [int]$m.Y, [int]$m.W, [int]$m.H)); Width = [int]$m.W; Height = [int]$m.H; Hz = [int]$m.Hz
            Off = [bool]$e; Method = $(if ($e) { [string]$e.Method } else { '' }); Methods = $methods; Connected = $true; Pref = (Get-GBMonPref $key); Num = (Get-GBMonNum $dev) })
    }
    foreach ($dev in @($Script:MonOff.Keys)) {
        $e = $Script:MonOff[$dev]
        if ($seen.ContainsKey($dev) -or $e.Method -ne 'detach') { continue }
        $s = ConvertFrom-GBMonModeText $e.Saved; if (-not $s) { continue }
        [void]$list.Add([pscustomobject]@{
            Index = 0; Name = [string]$e.Name; Device = $dev; Key = [string]$e.Key; Primary = $false; Internal = [bool]$e.Internal
            Bounds = (New-Object System.Drawing.Rectangle($s.X, $s.Y, $s.W, $s.H)); Width = $s.W; Height = $s.H; Hz = $s.Hz
            Off = $true; Method = 'detach'; Methods = @('detach'); Connected = (Test-GBMonConnected $dev ([string]$e.Key)); Pref = (Get-GBMonPref ([string]$e.Key)); Num = (Get-GBMonNum $dev) })
    }
    $sorted = @($list | Sort-Object Num, Device)
    for ($i = 0; $i -lt $sorted.Count; $i++) { $sorted[$i].Index = $i + 1 }
    $Script:MonList = $sorted
    return $sorted
}
function Test-GBMonitorOff([int]$Index) { $m = @($Script:MonList | Where-Object { $_.Index -eq $Index })[0]; return [bool]($m -and $Script:MonOff.ContainsKey($m.Device)) }
function Test-GBMonitorExists([int]$Index) { return ($Index -ge 1 -and $Index -le @($Script:MonList).Count) }

# Etat garde dans la config (pour tout rallumer apres un arret brutal)
function Save-GBMonState {
    $arr = @()
    foreach ($dev in @($Script:MonOff.Keys | Sort-Object)) {
        $e = $Script:MonOff[$dev]
        $arr += @{ Device = $dev; Key = [string]$e.Key; Name = [string]$e.Name; Method = [string]$e.Method; Internal = [bool]$e.Internal; Saved = [string]$e.Saved
                   Layout = @($e.Layout); WasPrimary = [bool]$e.WasPrimary; Shift = [string]$e.Shift; Time = [string]$e.Time }
    }
    $Script:Config.MonitorsOff = $arr
    try { Save-Config } catch {}
}
function Get-GBMonStateText { return ((@($Script:MonOff.Keys | Sort-Object | ForEach-Object { $_ + '=' + $Script:MonOff[$_].Method })) -join ';') }

# Duree du fondu du voile selon le modele (aucune animation au clavier, ni si les animations Windows sont coupees)
function Get-GBMonFadeMs([switch]$Keyboard) {
    if ($Keyboard) { return 0 }
    try { if ($Script:UiOK -and [GBMotion]::Reduced) { return 0 } } catch {}
    $mo = ''; try { $mo = [string]$Script:Theme.Motion } catch {}
    switch ($mo) { 'punch' { return 140 } 'soft' { return 220 } default { return 160 } }
}
function New-GBMonVeil($Bounds, [int]$AutoMs, [int]$FadeMs) {
    if ($Script:MonOK) { return (New-Object GBMonVeil($Bounds, $AutoMs, $FadeMs)) }
    # Secours sans C# : fenetre noire classique
    $v = New-Object System.Windows.Forms.Form
    $v.FormBorderStyle = 'None'; $v.BackColor = [System.Drawing.Color]::Black; $v.ShowInTaskbar = $false; $v.TopMost = $true
    $v.StartPosition = 'Manual'; $v.Bounds = $Bounds; $v.KeyPreview = $true; $v.Text = 'GameBoost - ecran eteint'
    $l = New-Object System.Windows.Forms.Label; $l.Text = 'Ecran eteint par GameBoost - double-clic pour rallumer'; $l.ForeColor = [System.Drawing.Color]::FromArgb(110, 110, 110)
    $l.AutoSize = $false; $l.TextAlign = 'MiddleCenter'; $l.Dock = 'Bottom'; $l.Height = [int]($Bounds.Height * 0.25); $v.Controls.Add($l)
    $l.Add_DoubleClick({ $this.FindForm().Close() })
    $v.Add_DoubleClick({ $this.Close() }); $v.Add_KeyDown({ if ($_.KeyCode -eq 'Escape') { $this.Close() } })
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 3000; $tm.Tag = @{ Form = $v; Label = $l; Auto = $AutoMs; Start = [Environment]::TickCount }
    $tm.Add_Tick({ $t = $this.Tag; $t.Label.Visible = $false; if ($t.Auto -gt 0 -and ([Environment]::TickCount - $t.Start) -ge $t.Auto) { $this.Stop(); $t.Form.Close() } })
    $v.Add_Shown({ $tm.Start() }.GetNewClosure())
    $v.Add_FormClosed({ $tm.Stop(); $tm.Dispose() }.GetNewClosure())
    return $v
}
# Voile ferme (double-clic, Echap, 10 minutes) : l'ecran redevient "allume" pour GameBoost
function Remove-GBMonVeilEntry($v) {
    try { [void]$Script:MonVeils.Remove($v) } catch {}
    foreach ($dev in @($Script:MonOff.Keys)) {
        $e = $Script:MonOff[$dev]
        if ($e.Method -eq 'veil' -and [object]::ReferenceEquals($e.Veil, $v)) {
            $Script:MonOff.Remove($dev); Save-GBMonState
            try { Log ("Ecran rallume (voile retire) : " + $e.Name) } catch {}
        }
    }
}

# Plan de remise des ecrans detaches (layout d'origine si l'ecran principal a ete detache)
function Get-GBMonRestorePlan($Entries) {
    $plan = [ordered]@{}
    $prim = @($Entries | Where-Object { $_.WasPrimary } | Sort-Object { [string]$_.Time })[0]
    $own = @{}; foreach ($dev in @($Script:MonOff.Keys)) { if ($Script:MonOff[$dev].Method -eq 'detach') { $own[$dev] = $true } }
    $mine = @{}; foreach ($e in @($Entries)) { $mine[[string]$e.Device] = $true }
    if ($prim) {
        foreach ($t in @($prim.Layout)) {
            $m = ConvertFrom-GBMonModeText $t; if (-not $m) { continue }
            # un autre ecran detache a part (et pas remis maintenant) reste detache
            if ($own.ContainsKey($m.Device) -and -not $mine.ContainsKey($m.Device)) { continue }
            $plan[$m.Device] = $m
        }
    }
    foreach ($e in @($Entries)) {
        if ($plan.Contains([string]$e.Device)) { continue }
        $m = ConvertFrom-GBMonModeText $e.Saved; if (-not $m) { continue }
        $m.Primary = $false
        $plan[$m.Device] = $m
    }
    return @($plan.Values)
}
# Rallume un ecran (par sa sortie \\.\DISPLAYn) avec la methode qui l'a eteint
function Set-GBMonOn([string]$Device, [switch]$Quiet, [switch]$NoSave) {
    $e = $Script:MonOff[$Device]
    if (-not $e) { return $true }
    $ok = $false
    try {
        switch ($e.Method) {
            'veil' { $Script:MonOff.Remove($Device); try { if ($e.Veil -and -not $e.Veil.IsDisposed) { $e.Veil.Close() } } catch {}; $ok = $true }
            'ddc' {
                $ok = Invoke-GBMonDdc $Device 1
                if (-not $ok) { Start-Sleep -Milliseconds 250; $ok = Invoke-GBMonDdc $Device 1 }
                # Ecran qui ne repond plus en DDC : nouvelle synchro du signal (meme mode), qui le reveille
                if (-not $ok -and $Script:MonOK) { try { $ok = ([GBMon]::Resync($Device) -eq 0) } catch {} }
            }
            'detach' {
                $plan = @(Get-GBMonRestorePlan @($e))
                $rc = Invoke-GBMonApply $plan
                $back = Get-GBMonMode $Device
                $ok = ($rc -eq 0 -and $back)
                if (-not $ok -and -not (Test-GBMonConnected $Device ([string]$e.Key))) { if (-not $Quiet) { Log ("Ecran " + $e.Name + " debranche : il sera rallume quand il sera rebranche et GameBoost relance") } }
                elseif ($ok) {
                    $s = ConvertFrom-GBMonModeText $e.Saved
                    if ($s -and ($back.W -ne $s.W -or $back.H -ne $s.H -or ($s.Hz -gt 1 -and $back.Hz -ne $s.Hz))) { Log ("Ecran " + $e.Name + " rallume, mais Windows a choisi " + $back.W + " x " + $back.H + " a " + $back.Hz + " Hz") }
                    # ecrans detaches apres l'ecran principal : leurs positions etaient decalees, on les recale
                    if ($e.WasPrimary -and $e.Shift -match '^(-?\d+),(-?\d+)$') {
                        $dx = [int]$Matches[1]; $dy = [int]$Matches[2]
                        foreach ($od in @($Script:MonOff.Keys)) {
                            $o = $Script:MonOff[$od]
                            if ($od -eq $Device -or $o.Method -ne 'detach' -or [string]$o.Time -lt [string]$e.Time) { continue }
                            $sm = ConvertFrom-GBMonModeText $o.Saved; if ($sm) { $sm.X -= $dx; $sm.Y -= $dy; $o.Saved = ConvertTo-GBMonModeText $sm }
                        }
                    }
                } elseif (-not $Quiet) { Log ("Ecran " + $e.Name + " : Windows refuse de le rattacher (code " + $rc + ")") }
            }
        }
    } catch { try { Log ("Ecran " + $e.Name + " : erreur au rallumage (" + $_.Exception.Message + ")") } catch {} }
    if ($ok) {
        $Script:MonOff.Remove($Device)
        if (-not $Quiet) { try { Log ("Ecran rallume : " + $e.Name) } catch {} }
    }
    if (-not $NoSave) { Save-GBMonState }
    return [bool]$ok
}

# Eteint (Off = $true) ou rallume un ecran ; renvoie @{ Ok; Method; Text }
function Set-GBMonitorPower([int]$Index, [bool]$Off, [string]$Method = '', [switch]$Keyboard) {
    $r = @{ Ok = $false; Method = ''; Text = '' }
    try {
        $all = @(Get-GBMonitors)
        $m = @($all | Where-Object { $_.Index -eq $Index })[0]
        if (-not $m) { $r.Text = "Pas d'ecran " + $Index + " sur ce PC"; return $r }
        if (-not $Off) {
            if (-not $m.Off) { $r.Ok = $true; $r.Text = $m.Name + " est deja allume"; return $r }
            $r.Method = $m.Method
            $r.Ok = Set-GBMonOn $m.Device
            $r.Text = $(if ($r.Ok) { $m.Name + " rallume" } else { $m.Name + " : rallumage impossible pour l'instant" })
            return $r
        }
        if ($m.Off) { $r.Ok = $true; $r.Method = $m.Method; $r.Text = $m.Name + " est deja eteint"; return $r }
        $on = @($all | Where-Object { -not $_.Off })
        $single = ($all.Count -eq 1)
        # Garde-fou : jamais le dernier ecran allume (seul le voile, qui se retire tout seul, est permis sur un ecran unique)
        if (-not $single -and $on.Count -le 1) { $r.Text = "C'est le dernier ecran allume : GameBoost ne l'eteint pas."; Log $r.Text; return $r }
        $order = @()
        if ($single) { $order = @('veil') }
        else {
            $pref = $Method; if (-not $pref) { $pref = $m.Pref }
            if ($pref -and $pref -ne 'auto') { $order += $pref }
            foreach ($x in @('ddc', 'detach', 'veil')) { if ($order -notcontains $x) { $order += $x } }
        }
        foreach ($meth in $order) {
            if ($m.Methods -notcontains $meth) { continue }
            $ok = $false
            switch ($meth) {
                'ddc' {
                    $ok = Invoke-GBMonDdc $m.Device 4
                    if (-not $ok) { $ok = Invoke-GBMonDdc $m.Device 5 }
                    if ($ok) {
                        $Script:MonOff[$m.Device] = @{ Device = $m.Device; Key = $m.Key; Name = $m.Name; Method = 'ddc'; Internal = $m.Internal; Time = (Get-Date).ToString('o') }
                        Start-GBMonDdcVerify $m.Device $Index
                    }
                }
                'detach' {
                    $layout = @(); $me = $null; $np = $null
                    foreach ($a in $all) {
                        if ($a.Off -and $a.Method -eq 'detach') { continue }
                        $md = Get-GBMonMode $a.Device; if (-not $md) { continue }
                        $layout += ,$md
                        if ($a.Device -eq $m.Device) { $me = $md } elseif (-not $np -and -not $a.Off) { $np = $md }
                    }
                    if (-not $me -or -not $np) { break }
                    $plan = @(); $shift = ''
                    if ($m.Primary) {
                        # L'ecran principal part : un autre ecran allume devient principal (en 0,0), les autres suivent
                        $dx = - $np.X; $dy = - $np.Y; $shift = [string]$dx + ',' + [string]$dy
                        foreach ($l in $layout) {
                            if ($l.Device -eq $m.Device) { $plan += @{ Device = $l.Device; W = 0 }; continue }
                            $plan += @{ Device = $l.Device; X = $l.X + $dx; Y = $l.Y + $dy; W = $l.W; H = $l.H; Hz = $l.Hz; Bpp = $l.Bpp; Orient = $l.Orient; Primary = ($l.Device -eq $np.Device) }
                        }
                    } else { $plan = @(@{ Device = $m.Device; W = 0 }) }
                    $rc = Invoke-GBMonApply $plan
                    if ($rc -eq 0 -and -not (Get-GBMonMode $m.Device)) {
                        $ok = $true
                        $Script:MonOff[$m.Device] = @{ Device = $m.Device; Key = $m.Key; Name = $m.Name; Method = 'detach'; Internal = $m.Internal; Saved = (ConvertTo-GBMonModeText $me)
                                                       Layout = @($layout | ForEach-Object { ConvertTo-GBMonModeText $_ }); WasPrimary = [bool]$m.Primary; Shift = $shift; Time = (Get-Date).ToString('o') }
                    } elseif ($rc -eq 0) {
                        # Windows a garde l'ecran : on remet tout comme avant
                        [void](Invoke-GBMonApply @($layout | ForEach-Object { $_ }))
                    }
                }
                'veil' {
                    $auto = 0; if ($single) { $auto = 600000 }
                    $v = New-GBMonVeil $m.Bounds $auto (Get-GBMonFadeMs -Keyboard:$Keyboard)
                    try { $v.Device = $m.Device } catch {}
                    $v.Add_FormClosed({ Remove-GBMonVeilEntry $this })
                    [void]$Script:MonVeils.Add($v)
                    $Script:MonOff[$m.Device] = @{ Device = $m.Device; Key = $m.Key; Name = $m.Name; Method = 'veil'; Internal = $m.Internal; Veil = $v; Time = (Get-Date).ToString('o') }
                    $v.Show()
                    $ok = $true
                }
            }
            if ($ok) { $r.Ok = $true; $r.Method = $meth; break }
        }
        if ($r.Ok) {
            $r.Text = $m.Name + " eteint (" + $Script:MonMethodNames[$r.Method] + ")"
            if ($single) { $r.Text += " : double-clic ou Echap pour le retirer, ou tout seul dans 10 minutes" }
            Save-GBMonState
        } else { $r.Text = $m.Name + " : impossible de l'eteindre" }
        Log $r.Text
    } catch { $r.Text = "Ecrans : erreur (" + $_.Exception.Message + ")"; try { Log $r.Text } catch {} }
    return $r
}
# DDC : certains ecrans se rallument d'eux-memes (signal toujours present) -> on passe a la methode suivante
function Start-GBMonDdcVerify([string]$Device, [int]$Index) {
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1600; $tm.Tag = @{ Device = $Device; Index = $Index }
    $tm.Add_Tick({
        $this.Stop(); $t = $this.Tag; $this.Dispose()
        try {
            $e = $Script:MonOff[$t.Device]
            if (-not $e -or $e.Method -ne 'ddc') { return }
            if ((Read-GBMonDdc $t.Device) -eq 1) {
                [GBMon]::DdcRemember($t.Device, -1)
                $Script:MonOff.Remove($t.Device)
                Log ("Ecran " + $e.Name + " : la veille DDC est ignoree par l'ecran, autre methode")
                [void](Set-GBMonitorPower $t.Index $true)
            }
        } catch {}
    })
    $tm.Start()
}
# Bascule eteint / allume (raccourcis, menu)
function Switch-GBMonitor([int]$Index, [switch]$Keyboard) {
    $m = @(Get-GBMonitors -NoDdc | Where-Object { $_.Index -eq $Index })[0]
    if (-not $m) { try { Log ("Pas d'ecran " + $Index + " sur ce PC") } catch {}; try { [System.Media.SystemSounds]::Beep.Play() } catch {}; return $null }
    $r = Set-GBMonitorPower $Index (-not $m.Off) -Keyboard:$Keyboard
    if (-not $r.Ok) { try { [System.Media.SystemSounds]::Beep.Play() } catch {} }
    return $r
}
# Tout rallumer (raccourci, menu, fermeture) : veiles, DDC, puis les ecrans detaches en une seule fois
function Restore-GBAllMonitors([switch]$Closing) {
    $n = 0; $fail = 0
    try {
        foreach ($dev in @($Script:MonOff.Keys)) { if ($Script:MonOff[$dev].Method -ne 'detach') { if (Set-GBMonOn $dev -NoSave -Quiet:$Closing) { $n++ } else { $fail++ } } }
        $det = @($Script:MonOff.Values | Where-Object { $_.Method -eq 'detach' })
        if ($det.Count -gt 0) {
            $plan = @(Get-GBMonRestorePlan $det)
            $rc = Invoke-GBMonApply $plan
            foreach ($e in $det) {
                if (Get-GBMonMode ([string]$e.Device)) { $Script:MonOff.Remove([string]$e.Device); $n++ } else { $fail++ }
            }
            if ($rc -ne 0 -and -not $Closing) { Log ("Ecrans : Windows a repondu " + $rc + " en rattachant les ecrans") }
        }
        foreach ($v in @($Script:MonVeils)) { try { if (-not $v.IsDisposed) { $v.Close() } } catch {} }
        $Script:MonVeils.Clear()
    } catch { try { Log ("Ecrans : erreur en rallumant tout (" + $_.Exception.Message + ")") } catch {} }
    Save-GBMonState
    if (-not $Closing) {
        if ($n -gt 0) { Log ("Tous les ecrans sont rallumes (" + $n + ")") } elseif ($fail -eq 0) { Log "Tous les ecrans sont deja allumes" }
    }
    return ($fail -eq 0)
}
# Demarrage : ecrans laisses eteints par une session de GameBoost fermee brutalement
function Resume-GBMonitorsAfterCrash {
    $saved = @($Script:Config.MonitorsOff | Where-Object { $_ })
    if ($saved.Count -eq 0) { return }
    $names = @()
    foreach ($s in $saved) {
        $dev = [string]$s.Device; if (-not $dev -or $s.Method -eq 'veil') { continue }   # un voile disparait avec GameBoost
        $Script:MonOff[$dev] = @{ Device = $dev; Key = [string]$s.Key; Name = [string]$s.Name; Method = [string]$s.Method; Internal = [bool]$s.Internal; Saved = [string]$s.Saved
                                  Layout = @($s.Layout | Where-Object { $_ }); WasPrimary = [bool]$s.WasPrimary; Shift = [string]$s.Shift; Time = [string]$s.Time }
        $names += [string]$s.Name
    }
    if ($names.Count -gt 0) {
        [void](Restore-GBAllMonitors -Closing)
        $left = @($Script:MonOff.Values | ForEach-Object { $_.Name })
        Log ("Ecrans laisses eteints par une fermeture brutale de GameBoost, rallumes : " + ($names -join ', ') + $(if ($left.Count) { " (encore eteint, debranche : " + ($left -join ', ') + ")" } else { "" }))
    } else { Save-GBMonState }
}
# Verification minute : branchement / debranchement, voiles orphelins, etat coherent
function Test-GBMonitorsHealth {
    $msgs = @()
    $raw = @(Get-GBMonRaw); $active = @{}
    foreach ($m in $raw) { $active[[string]$m.Device] = $m }
    $sig = (@($raw | ForEach-Object { [string]$_.Device + '=' + [string]$_.Path }) | Sort-Object) -join ';'
    if ($Script:MonSig -and $sig -ne $Script:MonSig) {
        $msgs += ("ecrans changes (" + $raw.Count + " ecran(s) actif(s))")
        if ($Script:MonOK) { [GBMon]::DdcReset() }
        try { [void](Register-GBMonitorActions) } catch {}
    }
    $Script:MonSig = $sig
    foreach ($dev in @($Script:MonOff.Keys)) {
        $e = $Script:MonOff[$dev]
        switch ($e.Method) {
            'veil' {
                if (-not $active.ContainsKey($dev)) { try { if ($e.Veil -and -not $e.Veil.IsDisposed) { $e.Veil.Close() } } catch {}; $Script:MonOff.Remove($dev); $msgs += ($e.Name + " debranche : voile retire") }
                elseif (-not $e.Veil -or $e.Veil.IsDisposed) { $Script:MonOff.Remove($dev); $msgs += ("voile de " + $e.Name + " disparu : etat corrige") }
                else {
                    $a = $active[$dev]; $b = New-Object System.Drawing.Rectangle([int]$a.X, [int]$a.Y, [int]$a.W, [int]$a.H)
                    if ($e.Veil.Bounds -ne $b) { $e.Veil.Bounds = $b; $msgs += ("voile de " + $e.Name + " recale sur l'ecran") }
                }
            }
            'ddc' { if (-not $active.ContainsKey($dev)) { $Script:MonOff.Remove($dev); $msgs += ($e.Name + " debranche (etait en veille DDC)") } }
            'detach' { if ($active.ContainsKey($dev)) { $Script:MonOff.Remove($dev); $msgs += ($e.Name + " rallume en dehors de GameBoost") } }
        }
    }
    foreach ($v in @($Script:MonVeils)) {
        if ($v.IsDisposed) { [void]$Script:MonVeils.Remove($v); continue }
        $owned = $false; foreach ($e in @($Script:MonOff.Values)) { if ([object]::ReferenceEquals($e.Veil, $v)) { $owned = $true } }
        if (-not $owned) { try { $v.Close() } catch {}; [void]$Script:MonVeils.Remove($v); $msgs += "voile orphelin retire" }
    }
    # Plus aucun ecran visible (ecran allume debranche...) : tout est rallume
    $all = @(Get-GBMonitors -NoDdc)
    $on = @($all | Where-Object { -not $_.Off })
    if ($all.Count -gt 1 -and $on.Count -eq 0) { [void](Restore-GBAllMonitors); $msgs += "plus aucun ecran allume : tout est rallume" }
    $cfg = ((@($Script:Config.MonitorsOff | Where-Object { $_ } | ForEach-Object { [string]$_.Device + '=' + [string]$_.Method }) | Sort-Object) -join ';')
    if ($cfg -ne (Get-GBMonStateText)) { Save-GBMonState; $msgs += "etat des ecrans resynchronise" }
    if ($msgs.Count -gt 0) { return ("Ecrans : " + ($msgs -join ' ; ')) }
    return $null
}

# Actions (menu Ecrans, raccourcis globaux : marchent aussi en jeu)
function Get-GBMonActionDefs {
    $raw = @(); try { $raw = @(Get-GBMonitors -NoDdc) } catch {}
    $defs = @()
    $defs += @{ Id = 'screen.panel'; Label = 'Gerer les ecrans...'; Menu = 'Ecrans'; Run = { Show-MonitorsPanel }; Order = 1; Description = 'Schema des ecrans, methode et raccourci de chaque ecran' }
    for ($i = 1; $i -le 6; $i++) {
        $m = @($raw | Where-Object { $_.Index -eq $i })[0]
        $lbl = 'Ecran ' + $i + $(if ($m) { ' (' + $m.Name + ')' } else { ' (non branche)' }) + ' : eteindre / rallumer'
        $defs += @{ Id = 'screen.off.' + $i; Label = $lbl; Menu = 'Ecrans'; Run = [scriptblock]::Create('[void](Switch-GBMonitor ' + $i + ' -Keyboard)')
                    DefaultKey = 'Ctrl+Alt+Shift+F' + $i; Global = $true; Order = 10 + $i
                    Checked = [scriptblock]::Create('Test-GBMonitorOff ' + $i); Enabled = [scriptblock]::Create('Test-GBMonitorExists ' + $i)
                    Description = 'Eteint ou rallume cet ecran (veille DDC, detacher ou voile noir)' }
    }
    $defs += @{ Id = 'screen.allon'; Label = 'Tout rallumer'; Menu = 'Ecrans'; Run = { [void](Restore-GBAllMonitors) }; DefaultKey = 'Ctrl+Alt+Shift+F12'; Global = $true; Order = 30
                Description = 'Rallume tous les ecrans eteints par GameBoost' }
    return $defs
}
# Crochets du socle (fermeture, demarrage, verification minute), une seule fois
function Register-GBMonitorHooks {
    if ($Script:MonHooksDone) { return }
    if (-not (Test-Path function:Add-GBCloseHook)) { return }
    $Script:MonHooksDone = $true
    try { Add-GBCloseHook { [void](Restore-GBAllMonitors -Closing) } } catch {}
    try { Add-GBStartHook { Start-GBMonitors } } catch {}
    try { Add-GBMinuteCheck 'ecrans' { Test-GBMonitorsHealth } } catch {}
}
# Demarrage (une fois) : ecrans laisses eteints par un arret brutal, etat de depart, capacite DDC lue en arriere-plan
function Start-GBMonitors {
    if ($Script:MonStarted) { return }
    $Script:MonStarted = $true
    try { Resume-GBMonitorsAfterCrash } catch {}
    try { [void](Get-GBMonitors -NoDdc); $Script:MonSig = ''; [void](Test-GBMonitorsHealth) } catch {}
    try { if ($Script:MonOK) { [GBMon]::ProbeDdcAsync([string[]]@($Script:MonList | Where-Object { -not $_.Internal -and -not $_.Off } | ForEach-Object { $_.Device })) } } catch {}
}
# A appeler apres le chargement du module raccourcis (et quand les ecrans changent : libelles avec le vrai nom)
function Register-GBMonitorActions {
    Register-GBMonitorHooks
    if (-not (Test-Path function:Register-GBAction)) { return $false }
    foreach ($d in @(Get-GBMonActionDefs)) { try { Register-GBAction @d } catch { try { Log ("Ecrans : action " + $d.Id + " refusee (" + $_.Exception.Message + ")") } catch {} } }
    if ($Script:Menu -and (Test-Path function:Update-GBMenu)) { try { Update-GBMenu } catch {} }
    return $true
}
Register-GBMonitorHooks
# Crochets pas encore definis a ce stade : nouvel essai 1,5 s apres l'ouverture, sinon nos propres minuteurs
if (-not $Script:MonHooksDone) {
    $Script:MonLateTimer = New-Object System.Windows.Forms.Timer; $Script:MonLateTimer.Interval = 1500
    $Script:MonLateTimer.Add_Tick({
        $this.Stop()
        try {
            Register-GBMonitorHooks
            if (-not $Script:MonHooksDone) {
                $Script:MonHooksDone = $true
                $form.Add_FormClosing({ param($s, $e) if ($e.Cancel) { return }; [void](Restore-GBAllMonitors -Closing) })
                $Script:MonMinuteTimer = New-Object System.Windows.Forms.Timer; $Script:MonMinuteTimer.Interval = 60000
                $Script:MonMinuteTimer.Add_Tick({ try { $t = Test-GBMonitorsHealth; if ($t) { Log $t } } catch {} })
                $Script:MonMinuteTimer.Start()
            }
            Start-GBMonitors
            if (Test-Path function:Register-GBAction) { [void](Register-GBMonitorActions) }
        } catch {}
    })
    $Script:MonLateTimer.Start()
}
if (Test-Path function:Register-GBAction) { [void](Register-GBMonitorActions) }
else {
    if (-not $Script:GBPendingActions) { $Script:GBPendingActions = New-Object System.Collections.ArrayList }
    foreach ($d in @(Get-GBMonActionDefs)) { [void]$Script:GBPendingActions.Add($d) }
}

# Forme du theme pour les miniatures : coins coupes (NEXUS) ou arrondis (ARENA, PURE)
function New-GBMonShapePath([System.Drawing.RectangleF]$r, [single]$size) {
    $p = New-Object System.Drawing.Drawing2D.GraphicsPath
    $shape = 'Chamfer'; try { if ($Script:Theme -and $Script:Theme.Shape) { $shape = [string]$Script:Theme.Shape } } catch {}
    $s = [single][math]::Max(1, [math]::Min($size, [math]::Min($r.Width, $r.Height) / 2 - 1))
    if ($shape -eq 'Chamfer') {
        $pts = @((New-Object System.Drawing.PointF(($r.X + $s), $r.Y)), (New-Object System.Drawing.PointF($r.Right, $r.Y)), (New-Object System.Drawing.PointF($r.Right, ($r.Bottom - $s))),
                 (New-Object System.Drawing.PointF(($r.Right - $s), $r.Bottom)), (New-Object System.Drawing.PointF($r.X, $r.Bottom)), (New-Object System.Drawing.PointF($r.X, ($r.Y + $s))))
        $p.AddPolygon([System.Drawing.PointF[]]$pts)
    } else {
        $d = $s * 2
        $p.AddArc($r.X, $r.Y, $d, $d, 180, 90); $p.AddArc(($r.Right - $d), $r.Y, $d, $d, 270, 90)
        $p.AddArc(($r.Right - $d), ($r.Bottom - $d), $d, $d, 0, 90); $p.AddArc($r.X, ($r.Bottom - $d), $d, $d, 90, 90); $p.CloseFigure()
    }
    return $p
}
# Schema des ecrans a leurs positions reelles (miniatures) ; $st.Rects garde les zones cliquables
function Invoke-GBMonSchemaPaint($g, $ctl, $st) {
    $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::ClearTypeGridFit
    $st.Rects = @{}
    $mons = @($st.Mons); if ($mons.Count -eq 0) { return }
    $ux1 = [int]::MaxValue; $uy1 = [int]::MaxValue; $ux2 = [int]::MinValue; $uy2 = [int]::MinValue
    foreach ($m in $mons) { $b = $m.Bounds; $ux1 = [math]::Min($ux1, $b.X); $uy1 = [math]::Min($uy1, $b.Y); $ux2 = [math]::Max($ux2, $b.Right); $uy2 = [math]::Max($uy2, $b.Bottom) }
    $pad = 14.0; $cw = [double]$ctl.ClientSize.Width; $chh = [double]$ctl.ClientSize.Height
    $k = [math]::Min(($cw - 2 * $pad) / [math]::Max(1, $ux2 - $ux1), ($chh - 2 * $pad) / [math]::Max(1, $uy2 - $uy1))
    $ox = ($cw - ($ux2 - $ux1) * $k) / 2; $oy = ($chh - ($uy2 - $uy1) * $k) / 2
    $rad = 6.0; try { if ($Script:Theme -and $Script:Theme.Radius) { $rad = [double]$Script:Theme.Radius } } catch {}
    foreach ($m in $mons) {
        $b = $m.Bounds
        $r = New-Object System.Drawing.RectangleF([single]($ox + ($b.X - $ux1) * $k + 3), [single]($oy + ($b.Y - $uy1) * $k + 3), [single]([math]::Max(8, $b.Width * $k - 6)), [single]([math]::Max(8, $b.Height * $k - 6)))
        $st.Rects[$m.Index] = $r
        $hot = ($st.Hot -eq $m.Index); $down = ($st.Down -eq $m.Index)
        $rr = $r; if ($down) { $rr = [System.Drawing.RectangleF]::Inflate($r, -3, -3) }   # appui : la miniature s'enfonce un peu
        $path = New-GBMonShapePath $rr ([single]$rad)
        if ($m.Off) { $fill = $st.OffFill; $edge = $st.Line } else { $fill = $st.Card; $edge = $st.Accent }
        if ($hot -and -not $m.Off) { $fill = $st.CardHot }
        $br = New-Object System.Drawing.SolidBrush($fill); $g.FillPath($br, $path); $br.Dispose()
        $pw = 1.5; if ($hot) { $pw = 2.5 }
        $pen = New-Object System.Drawing.Pen($edge, [single]$pw)
        if ($m.Off -and $m.Method -eq 'detach') { $pen.DashStyle = [System.Drawing.Drawing2D.DashStyle]::Dash }
        if ($hot -and $m.Off) { $pen.Color = $st.Muted }
        $g.DrawPath($pen, $path); $pen.Dispose(); $path.Dispose()
        # numero, nom, etat
        $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'; $sf.Trimming = 'EllipsisCharacter'; $sf.FormatFlags = 'NoWrap'
        $numC = $st.Text; if ($m.Off) { $numC = $st.Muted } elseif ($m.Primary) { $numC = $st.Accent }
        $nb = New-Object System.Drawing.SolidBrush($numC)
        $fh = [single][math]::Max(10, [math]::Min(28, $rr.Height * 0.30))
        $fnum = New-Object System.Drawing.Font($st.FontNum.FontFamily, $fh, [System.Drawing.FontStyle]::Bold, [System.Drawing.GraphicsUnit]::Pixel)
        $g.DrawString([string]$m.Index, $fnum, $nb, (New-Object System.Drawing.RectangleF($rr.X, ($rr.Y + $rr.Height * 0.08), $rr.Width, ($rr.Height * 0.46))), $sf)
        $fnum.Dispose(); $nb.Dispose()
        if ($rr.Height -ge 52) {
            $tb = New-Object System.Drawing.SolidBrush($st.Muted)
            $g.DrawString([string]$m.Name, $st.FontSmall, $tb, (New-Object System.Drawing.RectangleF(($rr.X + 4), ($rr.Y + $rr.Height * 0.54), ($rr.Width - 8), 16)), $sf)
            $stt = 'allume'; $sc = $st.Green
            if ($m.Off) { $stt = 'eteint (' + @{ ddc = 'DDC'; detach = 'detache'; veil = 'voile' }[[string]$m.Method] + ')'; $sc = $st.Muted } elseif ($m.Primary) { $stt = 'allume - principal' }
            $sb = New-Object System.Drawing.SolidBrush($sc)
            $g.DrawString($stt, $st.FontSmall, $sb, (New-Object System.Drawing.RectangleF(($rr.X + 4), ($rr.Y + $rr.Height * 0.54 + 16), ($rr.Width - 8), 16)), $sf)
            $tb.Dispose(); $sb.Dispose()
        }
        $sf.Dispose()
    }
}

# Fenetre "Ecrans" : schema cliquable, une ligne par ecran (methode, raccourci), Tout rallumer
function Show-MonitorsPanel {
    $card = $cPanel; if ($cCard) { $card = $cCard }
    $acc = $cCyan; if ($cAccent) { $acc = $cAccent }
    $isDark = $true; try { if ($Script:Theme -and $null -ne $Script:Theme.IsDark) { $isDark = [bool]$Script:Theme.IsDark } } catch {}
    $mix = { param($a, $b, $t) [System.Drawing.Color]::FromArgb([int]($a.R + ($b.R - $a.R) * $t), [int]($a.G + ($b.G - $a.G) * $t), [int]($a.B + ($b.B - $a.B) * $t)) }
    $mons = @(Get-GBMonitors)
    $st = @{ Mons = $mons; Rects = @{}; Hot = 0; Down = 0; Card = $card; CardHot = (& $mix $card $acc 0.10); OffFill = $(if ($isDark) { [System.Drawing.Color]::Black } else { (& $mix $cBg $cLine 0.55) })
             Accent = $acc; Line = $cLine; Text = $cText; Muted = $cMuted; Green = $cGreen; FontNum = $fontBold; FontSmall = $fontSmall; Busy = $false; Sig = '' }
    $W = 740; $rowH = 74
    $n = [math]::Max(1, $mons.Count); $listH = [math]::Min(4, $n) * ($rowH + 8) - 8
    $single = ($mons.Count -le 1)
    $y0 = 262 + $listH + 12
    if ($single) { $y0 += 44 }
    $H = $y0 + 30 + 58
    $d = New-GBDialog "Ecrans" $W $H
    $null = Add-DlgLabel $d "Ecrans" 16 8 300 30 $fontPage $acc
    $subTxt = "Clique sur un ecran pour l'eteindre ou le rallumer. Pratique pour jouer sur un ecran pendant que l'autre se repose."
    if ($single) { $subTxt = "Un seul ecran detecte. Cette fonction sert a partir de 2 ecrans : branche un second ecran pour en eteindre un pendant que tu joues sur l'autre." }
    $null = Add-DlgLabel $d $subTxt 16 40 690 36 $fontUI $cMuted
    # Schema
    $sch = New-Object System.Windows.Forms.Panel
    $sch.Location = New-Object System.Drawing.Point(16, 80); $sch.Size = New-Object System.Drawing.Size(692, 170); $sch.BackColor = $cDeep
    Set-GBDoubleBuffered $sch
    $d.Controls.Add($sch)
    $sch.Add_Paint({ try { Invoke-GBMonSchemaPaint $_.Graphics $this $st } catch {} })
    $hit = { param($pt) foreach ($k in @($st.Rects.Keys)) { if ($st.Rects[$k].Contains([single]$pt.X, [single]$pt.Y)) { return [int]$k } }; return 0 }
    $sch.Add_MouseMove({ $h = & $hit $_.Location; if ($h -ne $st.Hot) { $st.Hot = $h; $this.Cursor = $(if ($h) { [System.Windows.Forms.Cursors]::Hand } else { [System.Windows.Forms.Cursors]::Default }); $this.Invalidate() } })
    $sch.Add_MouseLeave({ if ($st.Hot -or $st.Down) { $st.Hot = 0; $st.Down = 0; $this.Invalidate() } })
    $sch.Add_MouseDown({ if ($_.Button -eq 'Left') { $st.Down = & $hit $_.Location; if ($st.Down) { $this.Invalidate(); $this.Update() } } })
    $sch.Add_MouseUp({
        $h = & $hit $_.Location; $was = $st.Down; $st.Down = 0; $this.Invalidate()
        if ($h -and $h -eq $was) { & $toggle $h }
    })
    # Lignes
    $rows = New-Object System.Windows.Forms.Panel
    $rows.Location = New-Object System.Drawing.Point(16, 262); $rows.Size = New-Object System.Drawing.Size(692, $listH); $rows.AutoScroll = ($mons.Count -gt 4); $rows.BackColor = $cBg
    $d.Controls.Add($rows)
    if ($single) { $null = Add-DlgLabel $d "Le voile noir couvre tout l'ecran : double-clic ou Echap pour le retirer. Il se retire tout seul apres 10 minutes." 16 (262 + $listH + 8) 690 36 $fontUI $cYellow }
    $bAll = Add-DlgButton $d "Tout rallumer" 16 $y0 160
    $bAll.ForeColor = $cGreen
    $status = Add-DlgLabel $d "" 190 ($y0 + 6) 400 20 $fontUI $cMuted
    $bClose = Add-DlgButton $d "Fermer" 608 $y0 100
    $bClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $d.CancelButton = $bClose
    $hasKeys = [bool](Test-Path function:Get-GBActionKey)
    $hasPanel = [bool](Test-Path function:Invoke-GBAction)
    $keyOf = { param($i) $t = 'Ctrl+Alt+Shift+F' + $i; if ($hasKeys) { try { $t = [string](Get-GBActionKey ('screen.off.' + $i)) } catch {} }; if (-not $t) { $t = 'aucun' }; return $t }
    $codes = @($Script:MonMethodNames.Keys)
    # Une ligne par ecran ; k = echelle (1 avant l'ouverture, zoom Windows ensuite)
    $buildRows = {
        param([double]$k)
        $sc = { param($v) [int][math]::Round($v * $k) }
        $rows.SuspendLayout()
        foreach ($c in @($rows.Controls)) { $rows.Controls.Remove($c); $c.Dispose() }
        $y = 0
        foreach ($m in @($st.Mons)) {
            $p = New-Object System.Windows.Forms.Panel; $p.BackColor = $card
            $p.Location = New-Object System.Drawing.Point(0, (& $sc $y)); $p.Size = New-Object System.Drawing.Size((& $sc 672), (& $sc $rowH)); $p.Tag = $m.Index
            if ($mons.Count -le 4) { $p.Width = & $sc 692 }
            $mk = { param($t, $x, $yy, $w, $h, $f, $col) $l = New-Object System.Windows.Forms.Label; $l.Text = $t; $l.Location = New-Object System.Drawing.Point((& $sc $x), (& $sc $yy)); $l.Size = New-Object System.Drawing.Size((& $sc $w), (& $sc $h)); $l.Font = $f; $l.ForeColor = $col; $l.BackColor = $card; $l.AutoEllipsis = $true; $p.Controls.Add($l); return $l }
            $null = & $mk ([string]$m.Index) 12 10 30 26 $fontPage $acc
            $null = & $mk ([string]$m.Name) 48 8 240 20 $fontBold $cText
            $det = "" + $m.Width + " x " + $m.Height + $(if ($m.Hz -gt 1) { " - " + $m.Hz + " Hz" } else { "" }) + $(if ($m.Primary) { " - principal" } else { "" }) + $(if ($m.Internal) { " - ecran du portable" } else { "" })
            $null = & $mk $det 48 29 240 18 $fontSmall $cMuted
            $sl = & $mk "" 48 48 240 18 $fontSmall $cGreen; $sl.Name = 'state'
            $null = & $mk "Methode" 296 6 150 16 $fontSmall $cMuted
            $cb = New-GBComboCtl; $cb.Location = New-Object System.Drawing.Point((& $sc 296), (& $sc 26)); $cb.Size = New-Object System.Drawing.Size((& $sc 150), (& $sc 26)); $cb.Font = $fontUI
            $avail = @('auto') + @($m.Methods | Where-Object { $_ })
            if ($single) { $avail = @('veil') }
            foreach ($c in $avail) { [void]$cb.Items.Add($Script:MonMethodNames[$c]) }
            $cur = [string]$m.Pref; if ($avail -notcontains $cur) { $cur = $avail[0] }
            $cb.SelectedIndex = [array]::IndexOf([string[]]$avail, $cur)
            $cb.Tag = @{ Key = $m.Key; Avail = $avail }
            $cb.Add_SelectedIndexChanged({
                $t = $this.Tag; $code = $t.Avail[$this.SelectedIndex]
                if (-not ($Script:Config.MonitorPrefs -is [hashtable])) { $Script:Config.MonitorPrefs = @{} }
                if ($code -eq 'auto') { $Script:Config.MonitorPrefs.Remove($t.Key) } else { $Script:Config.MonitorPrefs[$t.Key] = $code }
                Save-Config
            })
            if ($single) { $cb.Enabled = $false }
            $p.Controls.Add($cb)
            $null = & $mk "Raccourci" 458 6 128 16 $fontSmall $cMuted
            $kl = & $mk (& $keyOf $m.Index) 458 25 128 18 $fontBold $cText; $kl.Name = 'key'
            if ($m.Index -gt 6) { $kl.Text = 'aucun (7e ecran et plus)' }
            if ($hasPanel -and $m.Index -le 6) {
                $ll = New-Object System.Windows.Forms.LinkLabel; $ll.Text = "modifier"; $ll.Font = $fontSmall; $ll.BackColor = $card
                $ll.LinkColor = $acc; $ll.ActiveLinkColor = $acc; $ll.LinkBehavior = 'HoverUnderline'
                $ll.Location = New-Object System.Drawing.Point((& $sc 458), (& $sc 46)); $ll.Size = New-Object System.Drawing.Size((& $sc 90), (& $sc 18))
                $ll.Add_LinkClicked({ try { [void](Invoke-GBAction 'hotkeys.panel') } catch {}; & $refresh })
                $p.Controls.Add($ll)
            }
            $b = New-GBButtonCtl; $b.Location = New-Object System.Drawing.Point((& $sc 592), (& $sc 20)); $b.Size = New-Object System.Drawing.Size((& $sc 86), (& $sc 32)); $b.Tag = $m.Index; $b.Name = 'btn'
            $b.Add_Click({ & $toggle ([int]$this.Tag) })
            $p.Controls.Add($b)
            $rows.Controls.Add($p)
            $y += $rowH + 8
        }
        $rows.ResumeLayout()
    }
    # Met les textes a jour (etat, bouton, raccourci) sans tout reconstruire
    $refresh = {
        if ($d.IsDisposed) { return }
        $old = @($st.Mons).Count
        $st.Mons = @(Get-GBMonitors -NoDdc)
        if (@($st.Mons).Count -ne $old) { & $buildRows $Script:DpiScale }
        foreach ($p in @($rows.Controls)) {
            $m = @($st.Mons | Where-Object { $_.Index -eq $p.Tag })[0]; if (-not $m) { continue }
            foreach ($c in $p.Controls) {
                if ($c.Name -eq 'state') {
                    if ($m.Off) { $c.Text = "Eteint - " + $Script:MonMethodNames[$m.Method] + $(if (-not $m.Connected) { " (debranche)" } else { "" }); $c.ForeColor = $cYellow }
                    else { $c.Text = "Allume"; $c.ForeColor = $cGreen }
                } elseif ($c.Name -eq 'btn') {
                    if ($m.Off) { $c.Text = "Rallumer"; $c.ForeColor = $cGreen } else { $c.Text = $(if ($single) { "Voile" } else { "Eteindre" }); $c.ForeColor = $acc }
                } elseif ($c.Name -eq 'key' -and $m.Index -le 6) { $c.Text = & $keyOf $m.Index }
            }
        }
        $bAll.Enabled = ($Script:MonOff.Count -gt 0)
        $st.Sig = $(if ($Script:MonOK) { [GBMon]::Signature() } else { '' }) + '|' + (Get-GBMonStateText)
        $sch.Invalidate()
    }
    $toggle = {
        param([int]$i)
        if ($st.Busy) { return }
        $st.Busy = $true
        try {
            $m = @($st.Mons | Where-Object { $_.Index -eq $i })[0]; if (-not $m) { return }
            $d.Cursor = [System.Windows.Forms.Cursors]::WaitCursor
            $r = Set-GBMonitorPower $i (-not $m.Off)
            $d.Cursor = [System.Windows.Forms.Cursors]::Default
            $status.Text = [string]$r.Text; $status.ForeColor = $(if ($r.Ok) { $cMuted } else { $cYellow })
            # La fenetre etait sur l'ecran qu'on vient d'eteindre : elle passe sur un ecran allume
            if ($r.Ok -and -not $m.Off) {
                try {
                    $here = [System.Windows.Forms.Screen]::FromControl($d)
                    if ($here.DeviceName -eq $m.Device) {
                        $to = @([System.Windows.Forms.Screen]::AllScreens | Where-Object { $_.DeviceName -ne $m.Device -and -not $Script:MonOff.ContainsKey($_.DeviceName) })[0]
                        if ($to) { $wa = $to.WorkingArea; $d.Location = New-Object System.Drawing.Point(($wa.X + [int](($wa.Width - $d.Width) / 2)), ($wa.Y + [int](($wa.Height - $d.Height) / 2))) }
                    }
                } catch {}
            }
        } finally { $st.Busy = $false; $d.Cursor = [System.Windows.Forms.Cursors]::Default }
        & $refresh
    }
    $bAll.Add_Click({ [void](Restore-GBAllMonitors); $status.Text = "Tous les ecrans sont rallumes"; $status.ForeColor = $cMuted; & $refresh })
    & $buildRows 1.0
    # Branchement / debranchement pendant que la fenetre est ouverte
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1500
    $tm.Add_Tick({ if ($st.Busy) { return }; try { $sg = $(if ($Script:MonOK) { [GBMon]::Signature() } else { '' }) + '|' + (Get-GBMonStateText); if ($sg -ne $st.Sig) { & $refresh } } catch {} })
    $d.Add_Shown({ & $refresh; $tm.Start() })
    $Script:MonPanelOpen = $d
    try { [void]$d.ShowDialog($form) }
    finally { $tm.Stop(); $tm.Dispose(); $Script:MonPanelOpen = $null; $d.Dispose() }
}

# --- Lancements lies : quand un programme A demarre, GameBoost lance B (au niveau normal de l'utilisateur, jamais en admin sans le demander) ---
# Surveillance legere : liste des PID (GBLinkWatch), seuls les nouveaux processus sont identifies ; repli : instantane du moteur (GBProcSnap)
$Script:LinkOK = $true
try {
$linkSrc = @"
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;

// Chemin complet et niveau (admin ou non) d'un processus, sans WMI
public static class GBLinkNative {
    [DllImport("kernel32.dll", SetLastError = true)] static extern IntPtr OpenProcess(int access, bool inherit, int pid);
    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)] static extern bool QueryFullProcessImageNameW(IntPtr h, int flags, StringBuilder sb, ref int size);
    [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr h);
    [DllImport("advapi32.dll", SetLastError = true)] static extern bool OpenProcessToken(IntPtr h, int access, out IntPtr tok);
    [DllImport("advapi32.dll", SetLastError = true)] static extern bool GetTokenInformation(IntPtr tok, int cls, out int info, int len, out int ret);
    const int QUERY_LIMITED = 0x1000;   // PROCESS_QUERY_LIMITED_INFORMATION : marche aussi sur les jeux lances en admin
    public static string ImagePath(int pid) {
        IntPtr h = OpenProcess(QUERY_LIMITED, false, pid);
        if (h == IntPtr.Zero) return null;
        try {
            StringBuilder sb = new StringBuilder(1024); int n = sb.Capacity;
            if (QueryFullProcessImageNameW(h, 0, sb, ref n)) return sb.ToString(0, n);
            return null;
        } finally { CloseHandle(h); }
    }
    // 1 = administrateur (eleve), 0 = niveau normal, -1 = inconnu
    public static int Elevated(int pid) {
        IntPtr h = OpenProcess(QUERY_LIMITED, false, pid);
        if (h == IntPtr.Zero) return -1;
        try {
            IntPtr tok;
            if (!OpenProcessToken(h, 0x0008, out tok)) return -1;
            try { int v, r; if (GetTokenInformation(tok, 20, out v, 4, out r)) return v != 0 ? 1 : 0; return -1; }
            finally { CloseHandle(tok); }
        } finally { CloseHandle(h); }
    }
    // Nom de l'exe d'un PID sans ouvrir le processus (SystemProcessIdInformation) : repli quand le chemin est illisible
    [StructLayout(LayoutKind.Sequential)] struct PidInfo { public IntPtr ProcessId; public ushort Length; public ushort MaximumLength; public IntPtr Buffer; }
    [DllImport("ntdll.dll")] static extern int NtQuerySystemInformation(int cls, ref PidInfo info, int len, out int ret);
    public static string ImageName(int pid) {
        PidInfo pi = new PidInfo(); pi.ProcessId = new IntPtr(pid); pi.MaximumLength = 1024;
        pi.Buffer = Marshal.AllocHGlobal(1024);
        try {
            int ret;
            if (NtQuerySystemInformation(88, ref pi, Marshal.SizeOf(typeof(PidInfo)), out ret) != 0 || pi.Length == 0) return null;
            string s = Marshal.PtrToStringUni(pi.Buffer, pi.Length / 2);
            int i = s.LastIndexOf('\\'); return i >= 0 ? s.Substring(i + 1) : s;
        } catch { return null; }
        finally { Marshal.FreeHGlobal(pi.Buffer); }
    }
}

// Surveillance des lancements : liste des PID (EnumProcesses, tres rapide) ; seuls les NOUVEAUX PID sont identifies.
// Tous les FullEvery passages, tout est relu pour rattraper un PID reutilise par Windows pour un autre programme.
public class GBLinkWatch {
    [DllImport("psapi.dll", SetLastError = true)] static extern bool EnumProcesses([Out] int[] ids, int cb, out int needed);
    readonly Dictionary<int, string[]> _known = new Dictionary<int, string[]>();   // pid -> { nom en minuscules, chemin en minuscules ou "" }
    HashSet<string> _names = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    int[] _buf = new int[2048];
    int _tick;
    public int FullEvery = 8;
    public int LastNew;                    // nouveaux PID identifies au dernier passage
    public void SetNames(string[] names) { _names = new HashSet<string>(names ?? new string[0], StringComparer.OrdinalIgnoreCase); }
    static string[] Identify(int pid) {
        string path = GBLinkNative.ImagePath(pid);
        string name = null;
        if (path != null) name = System.IO.Path.GetFileName(path); else name = GBLinkNative.ImageName(pid);
        if (name == null) name = "";
        if (name.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)) name = name.Substring(0, name.Length - 4);
        return new string[] { name.ToLowerInvariant(), path == null ? "" : path.ToLowerInvariant() };
    }
    // Processus surveilles en cours : "pid|nom|chemin" (chemin vide = illisible, comparaison par le nom)
    public string[] Poll() {
        int needed;
        while (true) {
            if (!EnumProcesses(_buf, _buf.Length * 4, out needed)) return null;
            if (needed < _buf.Length * 4) break;
            _buf = new int[_buf.Length * 2];
        }
        int n = needed / 4;
        bool full = (++_tick % FullEvery) == 0;
        HashSet<int> cur = new HashSet<int>();
        LastNew = 0;
        for (int i = 0; i < n; i++) {
            int pid = _buf[i];
            if (pid <= 4 || !cur.Add(pid)) continue;
            string[] info;
            if (!_known.TryGetValue(pid, out info)) { _known[pid] = Identify(pid); LastNew++; }
            else if (full) {
                // Verification complete : le nom seul suffit (pas d'ouverture du processus)
                string nm = GBLinkNative.ImageName(pid);
                if (nm != null) {
                    if (nm.EndsWith(".exe", StringComparison.OrdinalIgnoreCase)) nm = nm.Substring(0, nm.Length - 4);
                    if (!string.Equals(nm, info[0], StringComparison.OrdinalIgnoreCase)) { _known[pid] = Identify(pid); LastNew++; }
                }
            }
        }
        List<int> dead = new List<int>();
        foreach (int pid in _known.Keys) if (!cur.Contains(pid)) dead.Add(pid);
        foreach (int pid in dead) _known.Remove(pid);
        List<string> res = new List<string>();
        foreach (KeyValuePair<int, string[]> kv in _known) if (_names.Contains(kv.Value[0])) res.Add(kv.Key + "|" + kv.Value[0] + "|" + kv.Value[1]);
        return res.ToArray();
    }
    public int Count { get { return _known.Count; } }
}
"@
    $linkRefs = $null; if ($PSVersionTable.PSEdition -ne 'Core') { $linkRefs = @('System') }
    if (-not (Add-GBCompiled 'GBLink' $linkSrc $linkRefs 'GBLinkNative')) { throw $Script:GBCompileError }
} catch { $Script:LinkOK = $false; $Script:LinkError = $_.Exception.Message }
$Script:LinkWatcher = $null
if ($Script:LinkOK) { try { $Script:LinkWatcher = New-Object GBLinkWatch } catch {} }

$Script:LinkIsAdmin = $false
try { $Script:LinkIsAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) } catch {}
$Script:LinkPathCache = @{}      # "pid|nom" -> chemin complet en minuscules ('' = illisible : comparaison par le nom)
$Script:LinkPids      = @{}      # cle d'un exe surveille -> PID en cours (dernier passage)
$Script:LinkPrimed    = New-Object 'System.Collections.Generic.HashSet[string]'   # cles deja vues une fois (pas de declenchement pour ce qui tournait avant)
$Script:LinkOurs      = @{}      # cle d'un exe lance par GameBoost -> @{ By = Id du lien ; Time }
$Script:LinkPending   = @{}      # "Id|sens" -> minuteur du delai
$Script:LinkState     = @{}      # Id -> @{ Text ; Kind ('ok'|'warn'|'info') ; Time }
$Script:LinkNameCache = @{}
$Script:LinkIconCache = @{}
$Script:LinkWatchNames = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
$Script:LinkWatchMap  = @{}      # nom de l'exe (minuscules) -> cles surveillees
$Script:LinkActionIds = @()
$Script:LinkReady = $false; $Script:LinksInit = $false; $Script:LinkTicks = 0; $Script:LinkOwnMinute = $true
$Script:LinkScanMs = 0.0; $Script:LinkScanN = 0

# Cle de comparaison : chemin complet en minuscules, ou 'name:exe' quand seul le nom est connu
function Get-GBLinkKey([string]$p) {
    if (-not $p) { return '' }
    $p = $p.Trim().Trim('"')
    if ($p.IndexOf('\') -lt 0) { $n = $p.ToLowerInvariant(); if ($n.EndsWith('.exe')) { $n = $n.Substring(0, $n.Length - 4) }; return ('name:' + $n) }
    try { $p = [IO.Path]::GetFullPath($p) } catch {}
    return $p.ToLowerInvariant()
}
function Get-GBLinkExeName([string]$p) {
    $n = ([string]$p).Trim().Trim('"')
    try { $n = [IO.Path]::GetFileName($n) } catch {}
    if ($n.ToLowerInvariant().EndsWith('.exe')) { $n = $n.Substring(0, $n.Length - 4) }
    return $n.ToLowerInvariant()
}
function Test-GBLinkHasPath([string]$p) { return ([string]$p).IndexOf('\') -ge 0 }

# --- Liens dans la config ---
function Get-GBLinks { return @($Script:Config.LinkedApps | Where-Object { $_ }) }
function Get-GBLinkById([string]$id) { foreach ($l in (Get-GBLinks)) { if ([string]$l.Id -eq $id) { return $l } }; return $null }
function New-GBLink {
    return @{ Id = [guid]::NewGuid().ToString('N').Substring(0, 8); Name = ''; Source = ''; Target = ''; Args = ''; Delay = 0
              CloseWith = $false; CloseForce = $false; Both = $false; Enabled = $true; AsAdmin = $false }
}
function Save-GBLinks($list) {
    $Script:Config.LinkedApps = @($list | Where-Object { $_ })
    if ($Script:RealConfig) { $Script:RealConfig.LinkedApps = $Script:Config.LinkedApps }   # session "mesure seule" : les vrais reglages suivent
    try { Save-Config } catch { Log ("Lancements lies : enregistrement impossible (" + $_.Exception.Message + ")") }
    Update-GBLinkWatch
    Register-GBLinkActions
}
# Nom lisible d'un programme : description du fichier (Spotify, Discord...) sinon nom de l'exe
function Get-GBLinkAppName([string]$p) {
    if (-not $p) { return '?' }
    if ($Script:LinkNameCache.ContainsKey($p)) { return $Script:LinkNameCache[$p] }
    $n = [IO.Path]::GetFileNameWithoutExtension($p.Trim('"'))
    if ((Test-GBLinkHasPath $p) -and (Test-Path -LiteralPath $p -PathType Leaf)) {
        try { $fd = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($p).FileDescription; if ($fd -and $fd.Trim() -and $fd.Trim().Length -le 32) { $n = $fd.Trim() } } catch {}
    }
    $Script:LinkNameCache[$p] = $n
    return $n
}
function Get-GBLinkTitle($l) {
    if ($l.Name) { return [string]$l.Name }
    return (Get-GBLinkAppName $l.Source) + " + " + (Get-GBLinkAppName $l.Target)
}
function Set-GBLinkState([string]$id, [string]$text, [string]$kind = 'info') {
    $Script:LinkState[$id] = @{ Text = $text; Kind = $kind; Time = (Get-Date) }
}
# Texte d'etat d'un lien pour le panneau
function Get-GBLinkStatus($l) {
    $a = Get-GBLinkAppName $l.Source; $b = Get-GBLinkAppName $l.Target
    if (-not $l.Enabled) {
        $st = $Script:LinkState[[string]$l.Id]
        if ($st -and $st.Kind -eq 'warn') { return @{ Text = $st.Text; Kind = 'warn' } }
        return @{ Text = "Desactive"; Kind = 'off' }
    }
    $st = $Script:LinkState[[string]$l.Id]
    if ($st) {
        $k = $st.Kind; if ($k -eq 'ok' -and ((Get-Date) - $st.Time).TotalMinutes -gt 2) { $k = 'info' }
        return @{ Text = $st.Text; Kind = $k }
    }
    $t = "Pret : " + $b + " se lance quand " + $a + " demarre"
    if ([int]$l.Delay -gt 0) { $t += " (+" + [int]$l.Delay + " s)" }
    if ($l.CloseWith) { $t += ", et se ferme avec lui" }
    if (-not (Test-GBLinkHasPath $l.Source)) { $t += " (reconnu par son nom)" }
    return @{ Text = $t; Kind = 'info' }
}

# --- Lancement au niveau normal de l'utilisateur (GameBoost tourne en administrateur) ---
# Le shell du bureau (explorer, sans droits admin) lance le programme a notre place : il herite de SES droits.
# Methode connue : ShellWindows.FindWindowSW(bureau) -> Document.Application (IShellDispatch2) -> ShellExecute.
function Start-GBUnelevated([string]$Path, [string]$Arguments = '', [string]$WorkDir = '') {
    if (-not $Path) { return $false }
    if (-not $WorkDir) { try { $WorkDir = [IO.Path]::GetDirectoryName($Path) } catch { $WorkDir = '' } }
    $sh = $null
    try {
        $sh = New-Object -ComObject Shell.Application
        $hw = 0
        $desk = $sh.Windows().FindWindowSW(0, $null, 8, [ref]$hw, 1)   # CSIDL_DESKTOP, SWC_DESKTOP, SWFO_NEEDDISPATCH
        if ($desk) {
            $desk.Document.Application.ShellExecute($Path, [string]$Arguments, [string]$WorkDir, 'open', 1)
            return $true
        }
    } catch {
        if (-not $Script:LinkShellWarned) { $Script:LinkShellWarned = $true; Log ("Lancement sans droits admin : shell du bureau indisponible (" + $_.Exception.Message + "), repli sur explorer.exe") }
    } finally { if ($sh) { try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($sh) } catch {} } }
    # Repli : explorer.exe confie le programme au bureau (niveau normal), mais les arguments ne passent pas
    try {
        if ($Arguments) { Log ("Lancement de " + [IO.Path]::GetFileName($Path) + " : arguments ignores (repli explorer.exe)") }
        Start-Process -FilePath (Join-Path $env:SystemRoot 'explorer.exe') -ArgumentList ('"' + $Path + '"')
        return $true
    } catch {}
    # GameBoost sans droits admin (copie de test) : un lancement direct reste au niveau normal
    if (-not $Script:LinkIsAdmin) {
        try {
            $sp = @{ FilePath = $Path }; if ($WorkDir) { $sp.WorkingDirectory = $WorkDir }; if ($Arguments) { $sp.ArgumentList = $Arguments }
            Start-Process @sp; return $true
        } catch {}
    }
    return $false
}
# Lancement en administrateur (seulement si "administrateur" est coche sur le lien)
function Start-GBElevated([string]$Path, [string]$Arguments = '', [string]$WorkDir = '') {
    try {
        $sp = @{ FilePath = $Path }
        if ($WorkDir) { $sp.WorkingDirectory = $WorkDir }
        if ($Arguments) { $sp.ArgumentList = $Arguments }
        if (-not $Script:LinkIsAdmin) { $sp.Verb = 'RunAs' }
        Start-Process @sp
        return $true
    } catch { Log ("Lancement en administrateur impossible : " + $_.Exception.Message); return $false }
}

# --- Surveillance ---
# Chemin complet d'un processus, lu une seule fois par "pid|nom" (un PID peut etre reutilise par Windows pour un autre programme)
function Get-GBLinkProcPath([int]$procId, [string]$name) {
    $ck = "" + $procId + "|" + $name
    $v = $Script:LinkPathCache[$ck]
    if ($null -ne $v) { return $v }
    $path = $null
    if ($Script:LinkOK) { try { $path = [GBLinkNative]::ImagePath($procId) } catch {} }
    if (-not $path) { try { $pp = [System.Diagnostics.Process]::GetProcessById($procId); try { $path = $pp.MainModule.FileName } finally { $pp.Dispose() } } catch {} }
    if ($path) { $v = $path.ToLowerInvariant() } else { $v = '' }
    $Script:LinkPathCache[$ck] = $v
    return $v
}
# Liste (pid, nom) de tous les processus : instantane rapide du moteur, sinon .NET
function Get-GBLinkSnapshot {
    $snap = $null
    if ($Script:FastOK) { try { $snap = [GBProcSnap]::Take() } catch {} }
    if ($snap) { return $snap }
    $res = New-Object System.Collections.ArrayList
    foreach ($p in [System.Diagnostics.Process]::GetProcesses()) { try { [void]$res.Add(@{ Pid = $p.Id; Name = $p.ProcessName }) } catch {} finally { $p.Dispose() } }
    return $res
}
# Les exe a surveiller (A, et B pour savoir s'il tourne deja), reconstruits a chaque changement de lien
function Update-GBLinkWatch {
    $names = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $map = @{}
    foreach ($l in (Get-GBLinks)) {
        if (-not $l.Enabled) { continue }
        foreach ($p in @($l.Source, $l.Target)) {
            $k = Get-GBLinkKey $p; if (-not $k) { continue }
            $n = Get-GBLinkExeName $p
            [void]$names.Add($n)
            if (-not $map.ContainsKey($n)) { $map[$n] = New-Object System.Collections.ArrayList }
            if (-not $map[$n].Contains($k)) { [void]$map[$n].Add($k) }
        }
    }
    $Script:LinkWatchNames = $names; $Script:LinkWatchMap = $map
    if ($Script:LinkWatcher) { try { $Script:LinkWatcher.SetNames([string[]]@($names)) } catch {} }
    $Script:LinkSigOk = $false
    # Liens desactives : lancements en attente annules
    foreach ($pk in @($Script:LinkPending.Keys)) {
        $ln = Get-GBLinkById ($pk.Split('|')[0])
        if (-not $ln -or -not $ln.Enabled) { Stop-GBLinkPending $pk }
    }
    if (-not $Script:LinkReady -or -not $Script:LinkTimer) { return }
    if ($names.Count -gt 0) { if (-not $Script:LinkTimer.Enabled) { $Script:LinkPrimed.Clear(); $Script:LinkPids = @{}; $Script:LinkTimer.Start(); Invoke-GBLinkScan } }
    else { $Script:LinkTimer.Stop(); $Script:LinkPids = @{}; $Script:LinkPrimed.Clear() }
}
function Stop-GBLinkPending([string]$pk) {
    $t = $Script:LinkPending[$pk]
    if ($t) { try { $t.Stop(); $t.Dispose() } catch {} }
    $Script:LinkPending.Remove($pk)
}
# Processus surveilles en cours : @{ Pid ; Name (minuscules) ; Path (minuscules, '' = illisible) }
# -OnlyName : un exe hors surveillance (bouton Tester d'un lien en pause), lu dans l'instantane complet
function Get-GBLinkHits([string]$OnlyName = '', $Polled = $null) {
    $res = New-Object System.Collections.ArrayList
    if (-not $OnlyName -or $Script:LinkWatchNames.Contains($OnlyName)) {
        $arr = $Polled
        if ($null -eq $arr -and $Script:LinkWatcher) { try { $arr = $Script:LinkWatcher.Poll() } catch { $arr = $null } }
        if ($null -ne $arr) {
            foreach ($s in $arr) {
                $f = $s.Split('|')
                $Script:LinkPathCache[$f[0] + '|' + $f[1]] = $f[2]
                [void]$res.Add(@{ Pid = [int]$f[0]; Name = $f[1]; Path = $f[2] })
            }
            return $res
        }
    }
    foreach ($p in (Get-GBLinkSnapshot)) {
        $n = [string]$p.Name
        if ($OnlyName) { if ($n -ne $OnlyName) { continue } } elseif (-not $Script:LinkWatchNames.Contains($n)) { continue }
        [void]$res.Add(@{ Pid = [int]$p.Pid; Name = $n.ToLowerInvariant(); Path = (Get-GBLinkProcPath ([int]$p.Pid) $n) })
    }
    return $res
}
# Un passage : seuls les NOUVEAUX processus sont identifies (GBLinkWatch) ; un exe "demarre" quand aucun de ses PID n'existait au passage precedent
function Invoke-GBLinkScan {
    $names = $Script:LinkWatchNames
    if (-not $names -or $names.Count -eq 0) { return }
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    # Rien n'a change depuis le passage precedent (memes PID surveilles) : rien a faire, cout quasi nul
    $arr = $null
    if ($Script:LinkWatcher) { try { $arr = $Script:LinkWatcher.Poll() } catch { $arr = $null } }
    if ($null -ne $arr) {
        $sig = [string]::Join(";", $arr)
        if ($Script:LinkSigOk -and $sig -eq $Script:LinkSig) { $sw.Stop(); $Script:LinkScanMs += $sw.Elapsed.TotalMilliseconds; $Script:LinkScanN++; return }
        $Script:LinkSig = $sig
    }
    $found = @{}
    foreach ($h in (Get-GBLinkHits '' $arr)) {
        foreach ($k in @($Script:LinkWatchMap[$h.Name])) {
            if (-not $k) { continue }
            $byName = $k.StartsWith('name:')
            if ($byName -or $h.Path -eq '' -or $h.Path -eq $k) {
                if (-not $found.ContainsKey($k)) { $found[$k] = New-Object 'System.Collections.Generic.List[int]' }
                $found[$k].Add([int]$h.Pid)
                if ($byName -and $h.Path) { $Script:LinkLearn = @{ Key = $k; Pid = [int]$h.Pid } }
            }
        }
    }
    $prev = $Script:LinkPids
    $keys = New-Object 'System.Collections.Generic.HashSet[string]'
    foreach ($k in $prev.Keys) { [void]$keys.Add($k) }
    foreach ($k in $found.Keys) { [void]$keys.Add($k) }
    $started = New-Object System.Collections.ArrayList; $stopped = New-Object System.Collections.ArrayList
    foreach ($k in $keys) {
        if (-not $Script:LinkPrimed.Contains($k)) { continue }
        $old = @(); if ($prev.ContainsKey($k)) { $old = @($prev[$k]) }
        $cur = @(); if ($found.ContainsKey($k)) { $cur = @($found[$k]) }
        # Aucun PID commun : l'ancienne instance est partie (ferme puis relance en moins de 2 s compte aussi)
        $common = $false; foreach ($x in $cur) { if ($old -contains $x) { $common = $true; break } }
        if ($common) { continue }
        if ($old.Count -gt 0) { [void]$stopped.Add($k) }
        if ($cur.Count -gt 0) { [void]$started.Add($k) }
    }
    foreach ($lst in $Script:LinkWatchMap.Values) { foreach ($k in $lst) { [void]$Script:LinkPrimed.Add($k) } }
    $Script:LinkPids = $found; $Script:LinkSigOk = $true
    # (le tout premier passage identifie tous les processus une fois, ~50 ms : compte a part)
    $sw.Stop(); if ($Script:LinkWatcher -and $Script:LinkWatcher.LastNew -gt 50) { $Script:LinkFirstMs = $sw.Elapsed.TotalMilliseconds } else { $Script:LinkScanMs += $sw.Elapsed.TotalMilliseconds; $Script:LinkScanN++ }
    foreach ($k in $stopped) { try { Invoke-GBLinkOnStop $k } catch { Log ("Lancements lies : " + $_.Exception.Message) } }
    foreach ($k in $started) { try { Invoke-GBLinkOnStart $k } catch { Log ("Lancements lies : " + $_.Exception.Message) } }
    # Lien enregistre avec le seul nom (jeu de "Mes jeux" jamais vu) : le chemin complet est retenu des qu'il tourne
    if ($Script:LinkLearn) { $ln = $Script:LinkLearn; $Script:LinkLearn = $null; Update-GBLinkLearnPath $ln.Key $ln.Pid }
}
function Update-GBLinkLearnPath([string]$key, [int]$procId) {
    # Chemin avec sa vraie casse (celui du cache est en minuscules)
    $real = $null
    if ($Script:LinkOK) { try { $real = [GBLinkNative]::ImagePath($procId) } catch {} }
    if (-not $real) { try { $pp = [System.Diagnostics.Process]::GetProcessById($procId); try { $real = $pp.MainModule.FileName } finally { $pp.Dispose() } } catch {} }
    if (-not $real) { return }
    $changed = $false
    foreach ($l in (Get-GBLinks)) {
        if (-not (Test-GBLinkHasPath $l.Source) -and (Get-GBLinkKey $l.Source) -eq $key) { $l.Source = $real; $changed = $true }
    }
    if ($changed) {
        Log ("Lancements lies : chemin retenu pour " + [IO.Path]::GetFileName($real))
        Save-GBLinks (Get-GBLinks)
    }
}
# A vient de demarrer (aucune instance avant) : B sera lance apres le delai, une seule fois
function Invoke-GBLinkOnStart([string]$k) {
    foreach ($l in (Get-GBLinks)) {
        if (-not $l.Enabled) { continue }
        if ((Get-GBLinkKey $l.Source) -eq $k) { Request-GBLinkLaunch $l 0 }
        if ($l.Both -and (Get-GBLinkKey $l.Target) -eq $k) { Request-GBLinkLaunch $l 1 }
    }
}
# A s'est ferme (plus aucune instance) : lancement en attente annule, B ferme si GameBoost l'a lance et si "fermer avec" est coche
function Invoke-GBLinkOnStop([string]$k) {
    foreach ($l in (Get-GBLinks)) {
        if (-not $l.Enabled) { continue }
        $sk = Get-GBLinkKey $l.Source; $tk = Get-GBLinkKey $l.Target
        foreach ($dir in @(0, 1)) {
            if ($dir -eq 1 -and -not $l.Both) { continue }
            $ak = $sk; $bk = $tk; $aPath = $l.Source; $bPath = $l.Target
            if ($dir -eq 1) { $ak = $tk; $bk = $sk; $aPath = $l.Target; $bPath = $l.Source }
            if ($ak -ne $k) { continue }
            Stop-GBLinkPending ([string]$l.Id + "|" + $dir)
            $ours = $Script:LinkOurs[$bk]
            if ($l.CloseWith -and $ours -and [string]$ours.By -eq [string]$l.Id) { Close-GBLinkTarget $l $bk $bPath $aPath }
        }
    }
    $Script:LinkOurs.Remove($k)
}
function Request-GBLinkLaunch($l, [int]$dir, [switch]$Now) {
    $pk = [string]$l.Id + "|" + $dir
    if ($Script:LinkPending.ContainsKey($pk)) { return }
    $d = [int]$l.Delay; if ($Now) { $d = 0 }
    if ($d -le 0) { [void](Invoke-GBLinkLaunch $l $dir); return }
    $tgt = $l.Target; $src = $l.Source; if ($dir -eq 1) { $tgt = $l.Source; $src = $l.Target }
    $t = New-Object System.Windows.Forms.Timer
    $t.Interval = [math]::Min(600, $d) * 1000; $t.Tag = $pk
    $t.Add_Tick({
        param($tm, $ea)
        try {
            $tm.Stop(); $key = [string]$tm.Tag
            $Script:LinkPending.Remove($key); $tm.Dispose()
            $parts = $key.Split('|'); $ln = Get-GBLinkById $parts[0]
            if ($ln -and $ln.Enabled) { [void](Invoke-GBLinkLaunch $ln ([int]$parts[1])) }
        } catch { Log ("Lancements lies : " + $_.Exception.Message) }
    })
    $Script:LinkPending[$pk] = $t
    $t.Start()
    Set-GBLinkState $l.Id ((Get-GBLinkAppName $tgt) + " se lance dans " + $d + " s (" + (Get-GBLinkAppName $src) + " a demarre)") 'info'
}
# Vrai si l'exe tourne en ce moment (lecture fraiche : pas de doublon)
function Test-GBLinkRunning([string]$k, [string]$exeName) {
    foreach ($h in (Get-GBLinkHits $exeName)) {
        if ($h.Name -ne $exeName) { continue }
        if ($k.StartsWith('name:') -or $h.Path -eq '' -or $h.Path -eq $k) { return $true }
    }
    return $false
}
# Lance B (sens 0) ou A (sens 1, lien dans les deux sens) s'il ne tourne pas deja
function Invoke-GBLinkLaunch($l, [int]$dir) {
    $src = [string]$l.Source; $tgt = [string]$l.Target; $targs = [string]$l.Args; $admin = [bool]$l.AsAdmin
    if ($dir -eq 1) { $src = [string]$l.Target; $tgt = [string]$l.Source; $targs = ''; $admin = $false }
    $sn = Get-GBLinkAppName $src; $tn = Get-GBLinkAppName $tgt
    if (-not (Test-GBLinkHasPath $tgt)) { Set-GBLinkState $l.Id ("Chemin de " + $tn + " inconnu : choisis le .exe dans le lien") 'warn'; return $false }
    if (-not (Test-Path -LiteralPath $tgt -PathType Leaf)) { Set-GBLinkState $l.Id ($tn + " introuvable : " + $tgt) 'warn'; return $false }
    $tk = Get-GBLinkKey $tgt
    $ours = $Script:LinkOurs[$tk]
    if ($ours -and ((Get-Date) - $ours.Time).TotalSeconds -lt 20) { return $false }   # deja lance a l'instant (bouton + surveillance)
    if (Test-GBLinkRunning $tk (Get-GBLinkExeName $tgt)) { Set-GBLinkState $l.Id ($tn + " etait deja ouvert quand " + $sn + " a demarre") 'info'; return $false }
    $dirW = ''; try { $dirW = [IO.Path]::GetDirectoryName($tgt) } catch {}
    if ($admin) { $ok = Start-GBElevated $tgt $targs $dirW } else { $ok = Start-GBUnelevated $tgt $targs $dirW }
    if (-not $ok) { Set-GBLinkState $l.Id ("Impossible de lancer " + $tn) 'warn'; return $false }
    $Script:LinkOurs[$tk] = @{ By = [string]$l.Id; Time = (Get-Date) }
    $lvl = ''; if ($admin) { $lvl = ' (administrateur)' }
    Set-GBLinkState $l.Id ($tn + " lance a " + (Get-Date -Format 'HH:mm') + " avec " + $sn + $lvl) 'ok'
    Log ("Lancement lie : " + $tn + " lance avec " + $sn + $lvl)
    return $true
}
# Fermeture polie de B (fenetre principale), puis forcee 5 s plus tard seulement si l'utilisateur l'a choisi
function Close-GBLinkTarget($l, [string]$bk, [string]$bPath, [string]$aPath) {
    $ids = @(); if ($Script:LinkPids.ContainsKey($bk)) { $ids = @($Script:LinkPids[$bk]) }
    $bn = Get-GBLinkAppName $bPath; $an = Get-GBLinkAppName $aPath
    if ($ids.Count -eq 0) { return }
    $polite = 0
    foreach ($id in $ids) {
        try {
            $p = [System.Diagnostics.Process]::GetProcessById([int]$id)
            try { if ($p.MainWindowHandle -ne [IntPtr]::Zero -and $p.CloseMainWindow()) { $polite++ } } finally { $p.Dispose() }
        } catch {}
    }
    if ($l.CloseForce) {
        $t = New-Object System.Windows.Forms.Timer; $t.Interval = 5000
        $t.Tag = @{ Ids = $ids; Name = (Get-GBLinkExeName $bPath); Label = $bn }
        $t.Add_Tick({
            param($tm, $ea)
            $tm.Stop(); $info = $tm.Tag; $tm.Dispose()
            $n = 0
            foreach ($id in @($info.Ids)) {
                try {
                    $p = [System.Diagnostics.Process]::GetProcessById([int]$id)
                    # Meme processus que celui surveille (un PID peut avoir ete reutilise entre-temps)
                    try { if ($p.ProcessName -eq $info.Name -and $Script:LinkPathCache.ContainsKey("" + $id + "|" + $p.ProcessName)) { $p.Kill(); $n++ } } finally { $p.Dispose() }
                } catch {}
            }
            if ($n -gt 0) { Log ("Lancement lie : " + $info.Label + " ferme de force (" + $n + " processus)") }
        })
        $t.Start()
    } elseif ($polite -eq 0) {
        Log ("Lancement lie : " + $bn + " n'a pas de fenetre a fermer (coche 'forcer' dans le lien pour le fermer quand meme)")
    }
    Set-GBLinkState $l.Id ($bn + " ferme avec " + $an + " a " + (Get-Date -Format 'HH:mm')) 'info'
    Log ("Lancement lie : " + $bn + " ferme avec " + $an)
}

# --- Actions ---
# "Lancer A + B" : A tout de suite (niveau normal), B apres le delai (sans doublon avec la surveillance)
function Invoke-GBLink([string]$id) {
    $l = Get-GBLinkById $id
    if (-not $l) { return }
    if (-not (Test-GBLinkHasPath $l.Source) -or -not (Test-Path -LiteralPath $l.Source -PathType Leaf)) {
        Log ("Lancements lies : chemin de " + (Get-GBLinkAppName $l.Source) + " inconnu ou introuvable (choisis le .exe dans le lien)"); return
    }
    if (Start-GBUnelevated $l.Source '' '') {
        $Script:LinkOurs[(Get-GBLinkKey $l.Source)] = @{ By = [string]$l.Id; Time = (Get-Date) }
        Log ("Lancement lie : " + (Get-GBLinkTitle $l))
        Request-GBLinkLaunch $l 0
    }
}
function Test-GBLinkRunnable([string]$id) { $l = Get-GBLinkById $id; return [bool]($l -and (Test-GBLinkHasPath $l.Source) -and (Test-GBLinkHasPath $l.Target)) }
# Envoie une action a "raccourcis" (Register-GBAction si elle existe deja, sinon la file d'attente)
function Send-GBLinkAction($h) {
    $cmd = Get-Command Register-GBAction -ErrorAction Ignore
    if ($cmd) {
        $sp = @{}; foreach ($k in $h.Keys) { if ($cmd.Parameters.ContainsKey($k)) { $sp[$k] = $h[$k] } }
        try { Register-GBAction @sp } catch { Log ("Lancements lies : action " + $h.Id + " non declaree (" + $_.Exception.Message + ")") }
    } else {
        if ($null -eq $Script:GBPendingActions) { $Script:GBPendingActions = New-Object System.Collections.ArrayList }
        [void]$Script:GBPendingActions.Add($h)
    }
}
# Une action "Lancer A + B" par lien (menu Jeux, sans raccourci par defaut, personnalisable)
function Register-GBLinkActions {
    $want = @{}
    foreach ($l in (Get-GBLinks)) {
        $id = 'links.run.' + [string]$l.Id
        $want[$id] = $true
        Send-GBLinkAction @{ Id = $id; Label = ('Lancer ' + (Get-GBLinkTitle $l)); Menu = 'Jeux'; Group = 'Lancements lies'; Order = 510
                             Run = [scriptblock]::Create("Invoke-GBLink '" + [string]$l.Id + "'")
                             Enabled = [scriptblock]::Create("Test-GBLinkRunnable '" + [string]$l.Id + "'")
                             Description = 'Lance les deux programmes du lien (le 2e apres le delai choisi)' }
    }
    # Lien supprime : action retiree (ou cachee si raccourcis ne sait pas retirer)
    foreach ($old in @($Script:LinkActionIds)) {
        if ($want.ContainsKey($old)) { continue }
        if (Get-Command Unregister-GBAction -ErrorAction Ignore) { try { Unregister-GBAction $old } catch {} }
        else { Send-GBLinkAction @{ Id = $old; Label = '(lien supprime)'; Menu = 'Jeux'; Run = {}; Enabled = { $false }; Editions = @('Aucune') } }
    }
    $Script:LinkActionIds = @($want.Keys)
    if ($Script:LinksInit -and (Get-Command Update-GBMenu -ErrorAction Ignore)) { try { Update-GBMenu } catch {} }
}

# --- Raccourci combine sur le Bureau : marche meme sans GameBoost ---
# Commande PowerShell en ligne (pas de fichier a cote, pas de politique d'execution), lancee par conhost --headless : aucune fenetre
# Apostrophes droites ET typographiques (PowerShell les traite toutes comme des apostrophes) : doublees
$Script:LinkQuoteRx = "['" + [char]0x2018 + [char]0x2019 + [char]0x201A + [char]0x201B + "]"
function ConvertTo-GBPsLiteral([string]$s) { return "'" + ($s -replace $Script:LinkQuoteRx, '$0$0') + "'" }
function ConvertTo-GBArgv([string]$s) {
    # Regles de la ligne de commande Windows : \ doubles devant un ", et " echappes par \
    $sb = New-Object System.Text.StringBuilder; [void]$sb.Append('"'); $bs = 0
    foreach ($ch in $s.ToCharArray()) {
        if ($ch -eq [char]'\') { $bs++; continue }
        if ($ch -eq [char]'"') { [void]$sb.Append([char]'\', 2 * $bs + 1); [void]$sb.Append('"') }
        else { if ($bs -gt 0) { [void]$sb.Append([char]'\', $bs) }; [void]$sb.Append($ch) }
        $bs = 0
    }
    if ($bs -gt 0) { [void]$sb.Append([char]'\', 2 * $bs) }
    [void]$sb.Append('"')
    return $sb.ToString()
}
function Get-GBLinkShortcutCommand($l) {
    $s = '$a=' + (ConvertTo-GBPsLiteral $l.Source) + ';$b=' + (ConvertTo-GBPsLiteral $l.Target) + ';' +
         'Start-Process -FilePath $a -WorkingDirectory ([IO.Path]::GetDirectoryName($a));'
    if ([int]$l.Delay -gt 0) { $s += 'Start-Sleep -Seconds ' + [int]$l.Delay + ';' }
    $s += '$n=[IO.Path]::GetFileNameWithoutExtension($b);' +
          'if(-not @(Get-Process -ErrorAction SilentlyContinue|Where-Object{$_.ProcessName -eq $n}).Count){Start-Process -FilePath $b -WorkingDirectory ([IO.Path]::GetDirectoryName($b))'
    if ($l.Args) { $s += ' -ArgumentList ' + (ConvertTo-GBPsLiteral $l.Args) }
    if ($l.AsAdmin) { $s += ' -Verb RunAs' }
    return ($s + '}')
}
function New-GBLinkShortcut($l, [string]$Folder = '') {
    if (-not (Test-GBLinkHasPath $l.Source) -or -not (Test-GBLinkHasPath $l.Target)) { return $null }
    if (-not $Folder) { $Folder = [Environment]::GetFolderPath('Desktop') }
    $title = (Get-GBLinkAppName $l.Source) + " + " + (Get-GBLinkAppName $l.Target)
    foreach ($ch in [IO.Path]::GetInvalidFileNameChars()) { $title = $title.Replace([string]$ch, '') }
    $lnk = Join-Path $Folder ($title.Trim() + '.lnk')
    $ps = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
    $cmd = Get-GBLinkShortcutCommand $l
    $psArgs = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -Command ' + (ConvertTo-GBArgv $cmd)
    $conhost = Join-Path $env:SystemRoot 'System32\conhost.exe'
    $headless = ($Script:WinBuild -ge 17763 -and (Test-Path -LiteralPath $conhost))
    $target = $ps; $arg = $psArgs
    if ($headless) { $target = $conhost; $arg = '--headless "' + $ps + '" ' + $psArgs }
    # Chemins tres longs (plus de 1023 caracteres, limite d'un raccourci) : petit script a cote, dans le dossier de GameBoost
    if ($arg.Length -gt 1023) {
        $dir = Join-Path $AppDir 'liens'
        if (-not (Test-Path -LiteralPath $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        $file = Join-Path $dir ('lien_' + [string]$l.Id + '.ps1')
        [IO.File]::WriteAllText($file, $cmd, (New-Object System.Text.UTF8Encoding($true)))
        $psArgs = '-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + $file + '"'
        $arg = $psArgs; if ($headless) { $arg = '--headless "' + $ps + '" ' + $psArgs }
    }
    $ws = New-Object -ComObject WScript.Shell
    try {
        $sc = $ws.CreateShortcut($lnk)
        $sc.TargetPath = $target
        $sc.Arguments = $arg
        $sc.WorkingDirectory = [IO.Path]::GetDirectoryName($l.Source)
        $sc.IconLocation = $l.Source + ',0'
        $sc.Description = "Lance " + (Get-GBLinkAppName $l.Source) + " puis " + (Get-GBLinkAppName $l.Target) + " (GameBoost)"
        if (-not $headless) { $sc.WindowStyle = 7 }   # console reduite si conhost --headless n'existe pas (Windows 10 avant 1809)
        $sc.Save()
    } finally { try { [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($ws) } catch {} }
    return $lnk
}

# --- Verification toutes les minutes : exe disparu = lien desactive (signale une fois), etat nettoye ---
function Test-GBLinksHealth {
    $msgs = @(); $changed = $false
    foreach ($l in (Get-GBLinks)) {
        if (-not $l.Enabled) { continue }
        $miss = $null
        foreach ($p in @($l.Source, $l.Target)) { if ((Test-GBLinkHasPath $p) -and -not (Test-Path -LiteralPath $p -PathType Leaf)) { $miss = $p; break } }
        if ($miss) {
            $l.Enabled = $false; $changed = $true
            $msgs += ("'" + (Get-GBLinkTitle $l) + "' desactive, " + [IO.Path]::GetFileName($miss) + " introuvable")
            Set-GBLinkState $l.Id ("Desactive : " + [IO.Path]::GetFileName($miss) + " introuvable (desinstalle ou deplace ?)") 'warn'
        }
    }
    # Nettoyage : lancements en attente et etats de liens supprimes, chemins de processus fermes, lancements jamais apparus
    foreach ($pk in @($Script:LinkPending.Keys)) { $ln = Get-GBLinkById ($pk.Split('|')[0]); if (-not $ln -or -not $ln.Enabled) { Stop-GBLinkPending $pk } }
    foreach ($id in @($Script:LinkState.Keys)) { if (-not (Get-GBLinkById $id)) { $Script:LinkState.Remove($id) } }
    if ($Script:LinkPathCache.Count -gt 0) {
        $alive = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($p in (Get-GBLinkSnapshot)) { [void]$alive.Add("" + $p.Pid + "|" + $p.Name) }
        foreach ($ck in @($Script:LinkPathCache.Keys)) { if (-not $alive.Contains($ck)) { $Script:LinkPathCache.Remove($ck) } }
    }
    foreach ($k in @($Script:LinkOurs.Keys)) {
        $o = $Script:LinkOurs[$k]
        if (-not $Script:LinkPids.ContainsKey($k) -and ((Get-Date) - $o.Time).TotalMinutes -gt 2) { $Script:LinkOurs.Remove($k) }
    }
    if ($changed) { Save-GBLinks (Get-GBLinks) }
    if ($msgs.Count -gt 0) { return ("Lancements lies : " + ($msgs -join ' ; ')) }
    return $null
}

# --- Minuteurs : surveillance toutes les 2 s (seulement s'il existe un lien actif) et accrochage au demarrage ---
$Script:LinkTimer = New-Object System.Windows.Forms.Timer
$Script:LinkTimer.Interval = 2000
$Script:LinkTimer.Add_Tick({
    try {
        Invoke-GBLinkScan
        $Script:LinkTicks++
        # Sans la verification commune toutes les minutes (socle absent), la mienne : toutes les 30 passages = 60 s
        if ($Script:LinkOwnMinute -and $Script:LinkTicks % 30 -eq 0) { $r = Test-GBLinksHealth; if ($r) { Log $r } }
    } catch {
        $m = $_.Exception.Message
        if ($m -ne $Script:LinkLastError) { $Script:LinkLastError = $m; Log ("Lancements lies : erreur de surveillance (" + $m + ")") }
    }
})
function Stop-GBLinks {
    try { $Script:LinkTimer.Stop() } catch {}
    foreach ($pk in @($Script:LinkPending.Keys)) { Stop-GBLinkPending $pk }
}
# Accroche crochets et actions une fois que tout GameBoost est charge (idempotent)
function Initialize-GBLinks {
    if ($Script:LinksInit) { return }
    $Script:LinksInit = $true
    if (Get-Command Add-GBMinuteCheck -ErrorAction Ignore) { Add-GBMinuteCheck 'liens' { Test-GBLinksHealth }; $Script:LinkOwnMinute = $false }
    if (Get-Command Add-GBCloseHook -ErrorAction Ignore) { Add-GBCloseHook { Stop-GBLinks } }
    else { $form.Add_FormClosing({ param($s, $e) if ($e.Cancel) { return }; Stop-GBLinks }) }
    Register-GBLinkActions
    $Script:LinkReady = $true
    Update-GBLinkWatch
    $n = @(Get-GBLinks | Where-Object { $_.Enabled }).Count
    if ($n -gt 0) { Log ("Lancements lies : " + $n + " lien(s) actif(s), surveillance toutes les 2 s") }
}
if ($null -eq $Script:GBPendingActions) { $Script:GBPendingActions = New-Object System.Collections.ArrayList }
[void]$Script:GBPendingActions.Add(@{ Id = 'links.panel'; Label = 'Lancements lies...'; Menu = 'Jeux'; Group = 'Lancements lies'; Order = 500
                                      Run = { Show-LinkedAppsPanel }; Description = 'Reunir deux programmes : quand tu lances l un, l autre se lance tout seul' })
if (Get-Command Add-GBStartHook -ErrorAction Ignore) { Add-GBStartHook { Initialize-GBLinks } }
# Filet : un minuteur unique attend que GameBoost ait fini de demarrer (minuteur principal lance), quel que soit l'ordre des modules
$Script:LinkInitTries = 0
$Script:LinkInitTimer = New-Object System.Windows.Forms.Timer
$Script:LinkInitTimer.Interval = 1500
$Script:LinkInitTimer.Add_Tick({
    $Script:LinkInitTries++
    if (-not ($timer -and $timer.Enabled) -and $Script:LinkInitTries -lt 40) { return }
    $Script:LinkInitTimer.Stop(); $Script:LinkInitTimer.Dispose()
    try { Initialize-GBLinks } catch { Log ("Lancements lies : demarrage impossible (" + $_.Exception.Message + ")") }
})
$Script:LinkInitTimer.Start()

# --- Fenetre "Lancements lies" : liste A -> B, ajout / modification, test, raccourci sur le Bureau ---
# Icone d'un exe (cache) ; sinon pastille avec l'initiale, aux couleurs du theme
function Get-GBLinkIcon([string]$p) {
    $k = [string]$p
    if ($Script:LinkIconCache.ContainsKey($k)) { return $Script:LinkIconCache[$k] }
    $bmp = $null
    if ((Test-GBLinkHasPath $p) -and (Test-Path -LiteralPath $p -PathType Leaf)) {
        try { $ic = [System.Drawing.Icon]::ExtractAssociatedIcon($p); if ($ic) { $bmp = $ic.ToBitmap(); $ic.Dispose() } } catch {}
    }
    if (-not $bmp) {
        $bmp = New-Object System.Drawing.Bitmap(32, 32)
        $g = [System.Drawing.Graphics]::FromImage($bmp)
        try {
            $g.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $g.TextRenderingHint = [System.Drawing.Text.TextRenderingHint]::AntiAliasGridFit
            $br = New-Object System.Drawing.SolidBrush($cLine); $g.FillEllipse($br, 1, 1, 30, 30); $br.Dispose()
            $t = '?'; $n = Get-GBLinkExeName $p; if ($n) { $t = $n.Substring(0, 1).ToUpperInvariant() }
            $sf = New-Object System.Drawing.StringFormat; $sf.Alignment = 'Center'; $sf.LineAlignment = 'Center'
            $tb = New-Object System.Drawing.SolidBrush($cText); $g.DrawString($t, $fontBold, $tb, (New-Object System.Drawing.RectangleF(0, 0, 32, 32)), $sf); $tb.Dispose(); $sf.Dispose()
        } finally { $g.Dispose() }
    }
    $Script:LinkIconCache[$k] = $bmp
    return $bmp
}
function Get-GBLinkKindColor([string]$kind) {
    switch ($kind) { 'ok' { return $cGreen } 'warn' { return $cYellow } default { return $cMuted } }
}
# Choix proposes pour A et B : jeux de "Mes jeux" et programmes ouverts (avec fenetre)
function Get-GBLinkChoices {
    $res = New-Object System.Collections.ArrayList
    $seen = @{}
    $running = @{}
    try { foreach ($g in @(Get-RunningAppGroups $false)) { if ($g.Path) { $running[([string]$g.Name).ToLowerInvariant()] = $g } } } catch {}
    foreach ($n in @($Script:Config.Games | Where-Object { $_ } | Sort-Object)) {
        $ln = ([string]$n).ToLowerInvariant()
        $lbl = "Jeu : " + $n
        if ($running.ContainsKey($ln)) { [void]$res.Add(@{ Text = $lbl + "   (" + $running[$ln].Path + ")"; Path = [string]$running[$ln].Path }); $seen[$ln] = $true }
        else {
            # Jeu jamais vu en cours : reconnu par son nom, chemin retenu au premier lancement
            $known = $null; foreach ($l in (Get-GBLinks)) { foreach ($pp in @($l.Source, $l.Target)) { if ((Test-GBLinkHasPath $pp) -and (Get-GBLinkExeName $pp) -eq $ln) { $known = $pp } } }
            if ($known) { [void]$res.Add(@{ Text = $lbl + "   (" + $known + ")"; Path = $known }) }
            else { [void]$res.Add(@{ Text = $lbl + "   (reconnu par son nom)"; Path = ($ln + '.exe') }) }
            $seen[$ln] = $true
        }
    }
    foreach ($k in @($running.Keys | Sort-Object)) {
        if ($seen.ContainsKey($k)) { continue }
        $g = $running[$k]
        $desc = $g.Name; try { $desc = Get-AppDescription $g } catch {}
        $t = "Ouvert : " + $desc; if ($desc -ne $g.Name) { $t += "  (" + $g.Name + ".exe)" }
        [void]$res.Add(@{ Text = $t; Path = [string]$g.Path })
    }
    return $res
}

# Fenetre d'ajout / modification d'un lien ; renvoie la table modifiee ou $null (Annuler)
function Show-GBLinkEditor($link) {
    $isNew = ($null -eq $link)
    $l = New-GBLink
    if (-not $isNew) { foreach ($k in @($link.Keys)) { $l[$k] = $link[$k] } }
    $d = New-GBDialog $(if ($isNew) { "Nouveau lien" } else { "Modifier le lien" }) 620 600
    $null = Add-DlgLabel $d $(if ($isNew) { "Nouveau lien" } else { "Modifier le lien" }) 16 8 560 30 $fontPage $cCyan
    $ed = @{ Choices = $null }
    $mkPick = {
        param($y, $title, $hint, $value)
        $null = New-GBHeader $d $title $hint 16 $y 572 22
        $tb = New-Object System.Windows.Forms.TextBox
        $tb.Location = New-Object System.Drawing.Point(16, ($y + 30)); $tb.Size = New-Object System.Drawing.Size(452, 26)
        $tb.BackColor = $cDeep; $tb.ForeColor = $cText; $tb.BorderStyle = "FixedSingle"; $tb.Text = [string]$value
        $d.Controls.Add($tb)
        $br = Add-DlgButton $d "Parcourir..." 476 ($y + 28) 112 28
        $br.Tag = $tb
        $br.Add_Click({
            param($snd, $ea)
            $ofd = New-Object System.Windows.Forms.OpenFileDialog
            $ofd.Filter = "Programme (*.exe)|*.exe"; $ofd.Title = "Choisis le programme"
            $cur = [string]$snd.Tag.Text
            if (Test-GBLinkHasPath $cur) { try { $ofd.InitialDirectory = [IO.Path]::GetDirectoryName($cur) } catch {} }
            if ($ofd.ShowDialog($d) -eq "OK") { $snd.Tag.Text = $ofd.FileName }
            $ofd.Dispose()
        })
        $cb = New-GBComboCtl
        $cb.Location = New-Object System.Drawing.Point(16, ($y + 62)); $cb.Size = New-Object System.Drawing.Size(572, 26)
        $cb.DropDownStyle = "DropDownList"; $cb.Font = $fontUI; $cb.Tag = $tb
        [void]$cb.Items.Add("Ou choisis un jeu de Mes jeux, ou un programme ouvert...")
        $cb.SelectedIndex = 0
        $cb.Add_DropDown({
            param($snd, $ea)
            if ($null -ne $ed.Choices) { return }
            $ed.Choices = Get-GBLinkChoices
            foreach ($c in @($cmbA, $cmbB)) {
                if (-not $c) { continue }
                while ($c.Items.Count -gt 1) { $c.Items.RemoveAt(1) }
                foreach ($ch in $ed.Choices) { [void]$c.Items.Add($ch.Text) }
                if ($ed.Choices.Count -eq 0) { [void]$c.Items.Add("(aucun jeu ni programme ouvert : utilise Parcourir...)") }
            }
        })
        $cb.Add_SelectedIndexChanged({
            param($snd, $ea)
            $i = $snd.SelectedIndex - 1
            if ($i -ge 0 -and $ed.Choices -and $i -lt $ed.Choices.Count) { $snd.Tag.Text = [string]$ed.Choices[$i].Path }
        })
        $d.Controls.Add($cb)
        return @($tb, $cb)
    }
    $pa = & $mkPick 48 "Programme A" "celui que tu lances toi-meme" $l.Source
    $tbA = $pa[0]; $cmbA = $pa[1]
    $pb = & $mkPick 148 "Programme B" "lance automatiquement par GameBoost" $l.Target
    $tbB = $pb[0]; $cmbB = $pb[1]
    $null = New-GBHeader $d "Options" "" 16 248 572 22
    $null = Add-DlgLabel $d "Arguments de B (facultatif) :" 16 280 200 22 $fontUI $cMuted
    $tbArgs = New-Object System.Windows.Forms.TextBox
    $tbArgs.Location = New-Object System.Drawing.Point(216, 278); $tbArgs.Size = New-Object System.Drawing.Size(372, 26)
    $tbArgs.BackColor = $cDeep; $tbArgs.ForeColor = $cText; $tbArgs.BorderStyle = "FixedSingle"; $tbArgs.Text = [string]$l.Args
    $d.Controls.Add($tbArgs)
    $null = Add-DlgLabel $d "Lancer B apres :" 16 314 200 22 $fontUI $cMuted
    $nDelay = New-Object System.Windows.Forms.NumericUpDown
    $nDelay.Minimum = 0; $nDelay.Maximum = 600; $nDelay.Value = [decimal]([math]::Max(0, [math]::Min(600, [int]$l.Delay)))
    $nDelay.BackColor = $cDeep; $nDelay.ForeColor = $cText; $nDelay.BorderStyle = "FixedSingle"; $nDelay.TextAlign = "Center"
    $nDelay.Location = New-Object System.Drawing.Point(216, 312); $nDelay.Size = New-Object System.Drawing.Size(70, 26)
    $d.Controls.Add($nDelay)
    $null = Add-DlgLabel $d "secondes (0 = tout de suite)" 294 314 260 22 $fontUI $cMuted
    $chkClose = Add-DlgCheck $d "Fermer B quand A se ferme (seulement si GameBoost l'a lance)" 16 346 572 $l.CloseWith
    $chkForce = Add-DlgCheck $d "Forcer la fermeture si B est encore ouvert 5 s apres (apps qui se cachent)" 36 372 552 $l.CloseForce
    $chkBoth  = Add-DlgCheck $d "Dans les deux sens : lancer B lance aussi A" 16 398 572 $l.Both
    $chkAdmin = Add-DlgCheck $d "Lancer B en administrateur (deconseille : Discord, Steam, glisser-deposer)" 16 424 572 $l.AsAdmin
    if ($Script:UiOK) { $chkAdmin.OnColor = $cYellow }
    $syncForce = { $chkForce.Enabled = $chkClose.Checked }
    $chkClose.Add_CheckedChanged($syncForce); & $syncForce
    $null = Add-DlgLabel $d "Nom (facultatif) :" 16 460 200 22 $fontUI $cMuted
    $tbName = New-Object System.Windows.Forms.TextBox
    $tbName.Location = New-Object System.Drawing.Point(216, 458); $tbName.Size = New-Object System.Drawing.Size(372, 26)
    $tbName.BackColor = $cDeep; $tbName.ForeColor = $cText; $tbName.BorderStyle = "FixedSingle"; $tbName.Text = [string]$l.Name
    $d.Controls.Add($tbName)
    $err = Add-DlgLabel $d "" 16 494 572 22 $fontUI $cRed
    Add-DlgOkCancel $d 524 604
    # Verification avant de fermer : le message reste dans la fenetre (pas de boite d'alerte)
    $d.Add_FormClosing({
        param($snd, $ea)
        if ($d.DialogResult -ne [System.Windows.Forms.DialogResult]::OK) { return }
        $a = $tbA.Text.Trim().Trim('"'); $b = $tbB.Text.Trim().Trim('"')
        $msg = $null
        if (-not $a) { $msg = "Choisis le programme A." }
        elseif (-not $b) { $msg = "Choisis le programme B." }
        elseif (-not $a.ToLowerInvariant().EndsWith('.exe') -or -not $b.ToLowerInvariant().EndsWith('.exe')) { $msg = "A et B doivent etre des programmes .exe." }
        elseif ((Test-GBLinkHasPath $a) -and -not (Test-Path -LiteralPath $a -PathType Leaf)) { $msg = "Programme A introuvable : " + $a }
        elseif (-not (Test-GBLinkHasPath $b)) { $msg = "Pour B, il faut le chemin complet (Parcourir...) : GameBoost doit pouvoir le lancer." }
        elseif (-not (Test-Path -LiteralPath $b -PathType Leaf)) { $msg = "Programme B introuvable : " + $b }
        elseif ((Get-GBLinkKey $a) -eq (Get-GBLinkKey $b)) { $msg = "A et B sont le meme programme." }
        elseif ($chkBoth.Checked -and -not (Test-GBLinkHasPath $a)) { $msg = "Dans les deux sens, A doit aussi avoir son chemin complet (Parcourir...)." }
        if ($msg) { $err.Text = $msg; $ea.Cancel = $true; [System.Media.SystemSounds]::Beep.Play() }
    })
    $r = $null
    try {
        if ($d.ShowDialog($form) -eq "OK") {
            $l.Source = $tbA.Text.Trim().Trim('"'); $l.Target = $tbB.Text.Trim().Trim('"'); $l.Args = $tbArgs.Text.Trim()
            $l.Delay = [int]$nDelay.Value; $l.CloseWith = $chkClose.Checked; $l.CloseForce = ($chkClose.Checked -and $chkForce.Checked)
            $l.Both = $chkBoth.Checked; $l.AsAdmin = $chkAdmin.Checked; $l.Name = $tbName.Text.Trim()
            $r = $l
        }
    } finally { $d.Dispose() }
    return $r
}

function Show-LinkedAppsPanel {
    if ($Script:LinkDlg -and -not $Script:LinkDlg.IsDisposed) { try { $Script:LinkDlg.Activate() } catch {}; return }
    $rowBg = $cPanel; if ($cCard) { $rowBg = $cCard }
    $arrow = [string][char]0x2192; $both = [string][char]0x2194
    $d = New-GBDialog "Lancements lies" 720 580
    $Script:LinkDlg = $d
    $null = Add-DlgLabel $d "Lancements lies" 16 8 400 30 $fontPage $cCyan
    $null = Add-DlgLabel $d ("Quand tu lances A, GameBoost lance B tout seul, sans droits administrateur. Exemples : un jeu et son overlay, Discord et Spotify.") 16 40 672 36 $fontUI $cMuted
    $list = New-Object System.Windows.Forms.Panel
    $list.Location = New-Object System.Drawing.Point(16, 80); $list.Size = New-Object System.Drawing.Size(672, 330)
    $list.BackColor = $cDeep; $list.AutoScroll = $true
    Set-GBDoubleBuffered $list
    $d.Controls.Add($list)
    $ui = @{ Sel = $null; Rows = @{}; Busy = $false }
    $bAdd   = Add-DlgButton $d "Ajouter un lien" 16 422 150
    $bAdd.ForeColor = $cGreen
    $bEdit  = Add-DlgButton $d "Modifier" 174 422 100
    $bDel   = Add-DlgButton $d "Supprimer" 282 422 100
    $bDel.ForeColor = $cRed
    $bTest  = Add-DlgButton $d "Tester" 390 422 90
    $bLnk   = Add-DlgButton $d "Creer un raccourci sur le Bureau" 488 422 200
    $tip.SetToolTip($bTest, "Lance B maintenant (comme si A venait de demarrer)")
    $tip.SetToolTip($bLnk, "Raccourci 'A + B' sur le Bureau : lance A puis B, meme quand GameBoost est ferme")
    $info = Add-DlgLabel $d "" 16 464 520 40 $fontSmall $cMuted
    $bClose = Add-DlgButton $d "Fermer" 588 470 100
    $bClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
    $d.CancelButton = $bClose

    $syncButtons = {
        $l = $null; if ($ui.Sel) { $l = Get-GBLinkById $ui.Sel }
        $has = ($null -ne $l)
        $bEdit.Enabled = $has; $bDel.Enabled = $has
        $bTest.Enabled = ($has -and (Test-GBLinkHasPath $l.Target))
        $bLnk.Enabled = ($has -and (Test-GBLinkHasPath $l.Source) -and (Test-GBLinkHasPath $l.Target))
        $n = @(Get-GBLinks | Where-Object { $_.Enabled }).Count
        if ($n -eq 0) { $t = "Aucun lien actif : la surveillance est arretee (zero cout)." }
        else {
            $t = "Surveillance active toutes les 2 s (" + $n + " lien(s))"
            if ($Script:LinkScanN -gt 0) { $t += ", " + ("{0:N1}" -f ($Script:LinkScanMs / $Script:LinkScanN)) + " ms par passage" }
            $t += "."
        }
        if ($has -and -not (Test-GBLinkHasPath $l.Source)) { $t += " Raccourci possible apres le premier lancement de A (chemin retenu)." }
        $info.Text = $t
    }
    $paintSel = {
        foreach ($id in @($ui.Rows.Keys)) {
            $rw = $ui.Rows[$id]; $on = ($id -eq $ui.Sel)
            $bg = $rowBg; if ($on) { $bg = $cSel }
            # Selection : changement de couleur immediat (action frequente, pas d'animation)
            $rw.Row.BackColor = $bg
            if ($on) { $rw.Bar.BackColor = $cCyan } else { $rw.Bar.BackColor = $bg }
            $rw.Toggle.Invalidate()
        }
    }
    $select = { param($id) $ui.Sel = $id; & $paintSel; & $syncButtons }
    $refreshStatus = {
        foreach ($id in @($ui.Rows.Keys)) {
            $l = Get-GBLinkById $id; if (-not $l) { continue }
            $st = Get-GBLinkStatus $l; $rw = $ui.Rows[$id]
            if ($rw.Status.Text -ne $st.Text) { $rw.Status.Text = $st.Text; $tip.SetToolTip($rw.Status, $st.Text) }
            $col = Get-GBLinkKindColor $st.Kind
            if ($rw.Status.ForeColor -ne $col) { $rw.Status.ForeColor = $col }
            if ($rw.Toggle.Checked -ne [bool]$l.Enabled) { $ui.Busy = $true; $rw.Toggle.Checked = [bool]$l.Enabled; $ui.Busy = $false }
        }
    }
    $onRowClick = { param($snd, $ea) & $select ([string]$snd.Tag) }
    $onRowDbl = { param($snd, $ea) & $select ([string]$snd.Tag); $bEdit.PerformClick() }
    $onToggle = {
        param($snd, $ea)
        if ($ui.Busy) { return }
        $l = Get-GBLinkById ([string]$snd.Tag); if (-not $l) { return }
        $l.Enabled = [bool]$snd.Checked
        if ($l.Enabled) { $Script:LinkState.Remove([string]$l.Id) }
        Save-GBLinks (Get-GBLinks)
        Log ("Lien " + (Get-GBLinkTitle $l) + " : " + $(if ($l.Enabled) { "actif" } else { "desactive" }))
        & $select ([string]$l.Id); & $refreshStatus
    }
    $fill = {
        $list.SuspendLayout()
        foreach ($c in @($list.Controls)) { $c.Dispose() }
        $ui.Rows = @{}
        $links = @(Get-GBLinks)
        $k = [single]$Script:DpiScale
        if ($links.Count -eq 0) {
            $e = New-Object System.Windows.Forms.Label
            $e.Text = "Aucun lien pour l'instant.`r`nClique sur 'Ajouter un lien' pour reunir deux programmes : par exemple Discord" + $arrow + "Spotify, ou ton jeu" + $arrow + "son overlay."
            $e.TextAlign = "MiddleCenter"; $e.ForeColor = $cMuted; $e.Font = $fontUI
            $e.Location = New-Object System.Drawing.Point(16, 100); $e.Size = New-Object System.Drawing.Size(640, 80)
            if ([math]::Abs($k - 1.0) -ge 0.01) { $e.Scale((New-Object System.Drawing.SizeF($k, $k))) }
            $list.Controls.Add($e)
            $ui.Sel = $null
        }
        $y = 8
        foreach ($l in $links) {
            $id = [string]$l.Id
            $r = New-Object System.Windows.Forms.Panel
            $r.Location = New-Object System.Drawing.Point(8, $y); $r.Size = New-Object System.Drawing.Size(634, 58)
            $r.BackColor = $rowBg; $r.Tag = $id; $r.Cursor = [System.Windows.Forms.Cursors]::Hand
            $bar = New-Object System.Windows.Forms.Panel; $bar.Location = New-Object System.Drawing.Point(0, 0); $bar.Size = New-Object System.Drawing.Size(3, 58); $bar.Tag = $id
            $pA = New-Object System.Windows.Forms.PictureBox; $pA.Location = New-Object System.Drawing.Point(16, 13); $pA.Size = New-Object System.Drawing.Size(32, 32)
            $pA.SizeMode = "Zoom"; $pA.Image = Get-GBLinkIcon $l.Source; $pA.Tag = $id
            $ar = New-Object System.Windows.Forms.Label; $ar.Text = $(if ($l.Both) { $both } else { $arrow }); $ar.Font = $fontBold; $ar.ForeColor = $cMuted
            $ar.TextAlign = "MiddleCenter"; $ar.Location = New-Object System.Drawing.Point(50, 15); $ar.Size = New-Object System.Drawing.Size(24, 28); $ar.Tag = $id
            $pB = New-Object System.Windows.Forms.PictureBox; $pB.Location = New-Object System.Drawing.Point(76, 13); $pB.Size = New-Object System.Drawing.Size(32, 32)
            $pB.SizeMode = "Zoom"; $pB.Image = Get-GBLinkIcon $l.Target; $pB.Tag = $id
            $ttl = New-Object System.Windows.Forms.Label; $ttl.Font = $fontBold; $ttl.ForeColor = $cText; $ttl.AutoEllipsis = $true
            $sep = " " + $arrow + " "; if ($l.Both) { $sep = " " + $both + " " }
            $ttl.Text = $(if ($l.Name) { [string]$l.Name + "   (" + (Get-GBLinkAppName $l.Source) + $sep + (Get-GBLinkAppName $l.Target) + ")" } else { (Get-GBLinkAppName $l.Source) + $sep + (Get-GBLinkAppName $l.Target) })
            $ttl.UseMnemonic = $false
            $ttl.Location = New-Object System.Drawing.Point(122, 9); $ttl.Size = New-Object System.Drawing.Size(410, 22); $ttl.Tag = $id
            $st = Get-GBLinkStatus $l
            $sl = New-Object System.Windows.Forms.Label; $sl.Font = $fontSmall; $sl.ForeColor = (Get-GBLinkKindColor $st.Kind); $sl.Text = $st.Text; $sl.AutoEllipsis = $true
            $sl.UseMnemonic = $false
            $sl.Location = New-Object System.Drawing.Point(122, 31); $sl.Size = New-Object System.Drawing.Size(410, 20); $sl.Tag = $id
            $tip.SetToolTip($sl, $st.Text)
            $tg = New-GBToggleCtl "Actif" $l.Enabled
            $tg.Location = New-Object System.Drawing.Point(546, 17); $tg.Size = New-Object System.Drawing.Size(80, 24); $tg.Tag = $id
            $tip.SetToolTip($tg, "Active ou met en pause ce lien")
            foreach ($c in @($r, $bar, $pA, $ar, $pB, $ttl, $sl)) { $c.Add_Click($onRowClick); $c.Add_DoubleClick($onRowDbl) }
            $tg.Add_CheckedChanged($onToggle)
            $r.Controls.AddRange(@($bar, $pA, $ar, $pB, $ttl, $sl, $tg))
            if ([math]::Abs($k - 1.0) -ge 0.01) { $r.Scale((New-Object System.Drawing.SizeF($k, $k))) }
            $list.Controls.Add($r)
            $ui.Rows[$id] = @{ Row = $r; Bar = $bar; Status = $sl; Toggle = $tg }
            $y += 64
        }
        if ($ui.Sel -and -not $ui.Rows.ContainsKey($ui.Sel)) { $ui.Sel = $null }
        if (-not $ui.Sel -and $links.Count -gt 0) { $ui.Sel = [string]$links[0].Id }
        $list.ResumeLayout()
        Set-GBDarkTree $list
        & $paintSel; & $syncButtons
    }
    $bAdd.Add_Click({
        $n = Show-GBLinkEditor $null
        if ($n) {
            Save-GBLinks (@(Get-GBLinks) + $n)
            Log ("Lien ajoute : " + (Get-GBLinkTitle $n))
            $ui.Sel = [string]$n.Id; & $fill
        }
    })
    $bEdit.Add_Click({
        $l = Get-GBLinkById $ui.Sel; if (-not $l) { return }
        $n = Show-GBLinkEditor $l
        if ($n) {
            $list2 = @(); foreach ($x in (Get-GBLinks)) { if ([string]$x.Id -eq [string]$n.Id) { $list2 += $n } else { $list2 += $x } }
            $Script:LinkState.Remove([string]$n.Id)
            Save-GBLinks $list2
            Log ("Lien modifie : " + (Get-GBLinkTitle $n))
            & $fill
        }
    })
    $bDel.Add_Click({
        $l = Get-GBLinkById $ui.Sel; if (-not $l) { return }
        $r = [System.Windows.Forms.MessageBox]::Show(("Supprimer le lien " + (Get-GBLinkTitle $l) + " ?`r`n(les deux programmes ne sont pas touches)"), "GameBoost", "YesNo", "Question")
        if ($r -ne "Yes") { return }
        foreach ($dir in @(0, 1)) { Stop-GBLinkPending ([string]$l.Id + "|" + $dir) }
        $Script:LinkState.Remove([string]$l.Id)
        Save-GBLinks @(Get-GBLinks | Where-Object { [string]$_.Id -ne [string]$l.Id })
        Log ("Lien supprime : " + (Get-GBLinkTitle $l))
        $ui.Sel = $null; & $fill
    })
    $bTest.Add_Click({
        $l = Get-GBLinkById $ui.Sel; if (-not $l) { return }
        Request-GBLinkLaunch $l 0 -Now
        & $refreshStatus
    })
    $bLnk.Add_Click({
        $l = Get-GBLinkById $ui.Sel; if (-not $l) { return }
        try {
            $p = New-GBLinkShortcut $l
            if ($p) {
                Log ("Raccourci cree : " + $p)
                $info.Text = "Raccourci cree sur le Bureau : " + [IO.Path]::GetFileName($p)
                $info.ForeColor = $cGreen
            }
        } catch {
            Log ("Raccourci impossible : " + $_.Exception.Message)
            $info.Text = "Raccourci impossible (Bureau protege ?) : " + $_.Exception.Message; $info.ForeColor = $cYellow
        }
    })
    # Etat en direct (B lance a 21:04 avec A...) : texte mis a jour chaque seconde, sans animation
    $tm = New-Object System.Windows.Forms.Timer; $tm.Interval = 1000
    $tm.Add_Tick({ try { & $refreshStatus } catch {} })
    $d.Add_Load({ & $fill })
    $d.Add_Shown({ $tm.Start() })
    try { [void]$d.ShowDialog($form) }
    finally { $tm.Stop(); $tm.Dispose(); $d.Dispose(); $Script:LinkDlg = $null }
}

# --- Raccourcis clavier : actions, barre de menus du haut, raccourcis personnalisables (globaux = marchent aussi en jeu) ---
# Chaque option de GameBoost est une "action" : elle apparait dans le menu du haut et peut recevoir un raccourci.
# Global = RegisterHotKey (marche en jeu, fenetre cachee) ; sinon le raccourci marche quand la fenetre GameBoost est active.
$Script:HotkeyOK = $false
$Script:HotkeyError = ""
try {
$hotkeySrc = @"
using System;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public class GBHotkeyEventArgs : EventArgs {
    public int Id;
    public GBHotkeyEventArgs(int id) { Id = id; }
}

// Fenetre invisible (message seulement) : recoit WM_HOTKEY sur le thread de l'interface, rien sur un autre thread
public class GBHotkeyWindow : NativeWindow, IDisposable {
    [DllImport("user32.dll", SetLastError = true)] static extern bool RegisterHotKey(IntPtr hWnd, int id, uint mods, uint vk);
    [DllImport("user32.dll", SetLastError = true)] static extern bool UnregisterHotKey(IntPtr hWnd, int id);
    const int WM_HOTKEY = 0x0312;
    public const uint MOD_NOREPEAT = 0x4000;
    readonly Dictionary<int, int[]> _keys = new Dictionary<int, int[]>();
    public event EventHandler<GBHotkeyEventArgs> Pressed;
    public int LastError;
    public bool Recreated;
    public GBHotkeyWindow() { Create(); }
    void Create() {
        CreateParams cp = new CreateParams();
        cp.Caption = "GameBoostHotkeys";
        cp.Parent = new IntPtr(-3);   // HWND_MESSAGE
        CreateHandle(cp);
    }
    // Fenetre detruite (tres rare) : recreee, les raccourcis sont a reenregistrer
    public bool Ensure() {
        if (Handle != IntPtr.Zero) return true;
        _keys.Clear(); Recreated = true;
        try { Create(); } catch { }
        return Handle != IntPtr.Zero;
    }
    public bool Register(int id, int mods, int vk) {
        LastError = 0;
        if (!Ensure()) { LastError = -1; return false; }
        Unregister(id);
        if (RegisterHotKey(Handle, id, (uint)mods | MOD_NOREPEAT, (uint)vk)) { _keys[id] = new int[] { mods, vk }; return true; }
        LastError = Marshal.GetLastWin32Error();
        return false;
    }
    public bool Unregister(int id) {
        if (!_keys.ContainsKey(id)) return false;
        _keys.Remove(id);
        if (Handle == IntPtr.Zero) return false;
        return UnregisterHotKey(Handle, id);
    }
    public void UnregisterAll() { foreach (int id in new List<int>(_keys.Keys)) Unregister(id); }
    public bool IsRegistered(int id) { return _keys.ContainsKey(id); }
    public int Count { get { return _keys.Count; } }
    // Combinaison libre dans Windows ? (essai puis retrait immediat ; false = deja prise ailleurs)
    public bool Probe(int mods, int vk) {
        if (!Ensure()) return false;
        const int tmp = 0xBFFE;
        if (RegisterHotKey(Handle, tmp, (uint)mods | MOD_NOREPEAT, (uint)vk)) { UnregisterHotKey(Handle, tmp); LastError = 0; return true; }
        LastError = Marshal.GetLastWin32Error();
        return false;
    }
    protected override void WndProc(ref Message m) {
        if (m.Msg == WM_HOTKEY) {
            EventHandler<GBHotkeyEventArgs> h = Pressed;
            if (h != null) { try { h(this, new GBHotkeyEventArgs(m.WParam.ToInt32())); } catch { } }
            return;
        }
        base.WndProc(ref m);
    }
    public void Dispose() { UnregisterAll(); if (Handle != IntPtr.Zero) DestroyHandle(); }
}

// Touche Windows enfoncee (WinForms ne la donne pas dans les modificateurs)
public static class GBKeyState {
    [DllImport("user32.dll")] static extern short GetKeyState(int vk);
    public static bool WinDown { get { return (GetKeyState(0x5B) & 0x8000) != 0 || (GetKeyState(0x5C) & 0x8000) != 0; } }
}

// Couleurs de la barre de menus (suivent le theme du modele)
public class GBMenuColors : ProfessionalColorTable {
    public Color Back = Color.FromArgb(11, 13, 24), Drop = Color.FromArgb(14, 16, 28), Hover = Color.FromArgb(26, 32, 56), Border = Color.FromArgb(40, 48, 78);
    public GBMenuColors() { UseSystemColors = false; }
    public override Color MenuStripGradientBegin { get { return Back; } }
    public override Color MenuStripGradientEnd { get { return Back; } }
    public override Color ToolStripDropDownBackground { get { return Drop; } }
    public override Color ImageMarginGradientBegin { get { return Drop; } }
    public override Color ImageMarginGradientMiddle { get { return Drop; } }
    public override Color ImageMarginGradientEnd { get { return Drop; } }
    public override Color MenuItemSelected { get { return Hover; } }
    public override Color MenuItemSelectedGradientBegin { get { return Hover; } }
    public override Color MenuItemSelectedGradientEnd { get { return Hover; } }
    public override Color MenuItemPressedGradientBegin { get { return Drop; } }
    public override Color MenuItemPressedGradientMiddle { get { return Drop; } }
    public override Color MenuItemPressedGradientEnd { get { return Drop; } }
    public override Color MenuItemBorder { get { return Hover; } }
    public override Color MenuBorder { get { return Border; } }
    public override Color SeparatorDark { get { return Border; } }
    public override Color SeparatorLight { get { return Drop; } }
    public override Color CheckBackground { get { return Drop; } }
    public override Color CheckSelectedBackground { get { return Hover; } }
    public override Color CheckPressedBackground { get { return Hover; } }
    public override Color ToolStripBorder { get { return Back; } }
}

// Rendu : texte du theme, raccourci en gris a droite, coche dessinee a la couleur d'accent, trait fin sous la barre
public class GBMenuRenderer : ToolStripProfessionalRenderer {
    public Color Text = Color.White, Muted = Color.Gray, Accent = Color.Cyan, Line = Color.DimGray, TopActive = Color.Cyan;
    public GBMenuRenderer(GBMenuColors c) : base(c) { RoundedEdges = false; }
    protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e) {
        ToolStripMenuItem mi = e.Item as ToolStripMenuItem;
        bool top = mi != null && mi.Owner is MenuStrip;
        bool shortcut = mi != null && !top && !String.IsNullOrEmpty(mi.ShortcutKeyDisplayString) && e.Text == mi.ShortcutKeyDisplayString && e.Text != mi.Text;
        Color c = Text;
        if (!e.Item.Enabled) c = Color.FromArgb(150, Muted);
        else if (shortcut) c = Muted;
        else if (top && (e.Item.Selected || e.Item.Pressed)) c = TopActive;
        e.TextColor = c;
        base.OnRenderItemText(e);
    }
    protected override void OnRenderArrow(ToolStripArrowRenderEventArgs e) { e.ArrowColor = e.Item != null && e.Item.Enabled ? Text : Muted; base.OnRenderArrow(e); }
    protected override void OnRenderItemCheck(ToolStripItemImageRenderEventArgs e) {
        Rectangle r = e.ImageRectangle;
        if (r.Width <= 0) return;
        Graphics g = e.Graphics;
        SmoothingMode old = g.SmoothingMode; g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = Math.Max(1f, g.DpiX / 96f);
        using (Pen p = new Pen(Accent, 1.8f * s)) {
            p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; p.LineJoin = LineJoin.Round;
            float cx = r.Left + r.Width / 2f, cy = r.Top + r.Height / 2f, k = Math.Min(r.Width, r.Height) / 2f - 2f * s;
            g.DrawLines(p, new PointF[] { new PointF(cx - k, cy), new PointF(cx - k * 0.3f, cy + k * 0.7f), new PointF(cx + k, cy - k * 0.7f) });
        }
        g.SmoothingMode = old;
    }
    protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e) {
        if (e.ToolStrip is MenuStrip) { using (Pen p = new Pen(Line)) e.Graphics.DrawLine(p, 0, e.ToolStrip.Height - 1, e.ToolStrip.Width, e.ToolStrip.Height - 1); return; }
        base.OnRenderToolStripBorder(e);
    }
}
"@
    $hkRefs = @('System.Windows.Forms', 'System.Drawing')
    if ($PSVersionTable.PSEdition -eq 'Core' -and $uiRefs) { $hkRefs = $uiRefs }
    if (Add-GBCompiled 'GBHotkeys' $hotkeySrc $hkRefs 'GBHotkeyWindow') { $Script:HotkeyOK = $true } else { $Script:HotkeyError = $Script:GBCompileError }
} catch { $Script:HotkeyOK = $false; $Script:HotkeyError = $_.Exception.Message }

# Noms des touches (format 'Ctrl+Alt+Shift+Win+Touche') : code Windows -> nom, et noms acceptes -> code
$Script:GBKeyName = @{}
$Script:GBKeyCode = @{}
function Add-GBKeyName([int]$vk, [string]$name, [string[]]$alias) {
    $Script:GBKeyName[$vk] = $name
    $Script:GBKeyCode[$name.ToLower()] = $vk
    foreach ($x in @($alias)) { if ($x) { $Script:GBKeyCode[$x.ToLower()] = $vk } }
}
for ($i = 0; $i -lt 26; $i++) { Add-GBKeyName (65 + $i) ([string][char](65 + $i)) @() }
for ($i = 0; $i -le 9; $i++) { Add-GBKeyName (48 + $i) ([string]$i) @(('D' + $i)); Add-GBKeyName (96 + $i) ('Num' + $i) @(('NumPad' + $i), ('Pave' + $i)) }
for ($i = 1; $i -le 24; $i++) { Add-GBKeyName (111 + $i) ('F' + $i) @() }
Add-GBKeyName 106 'NumFois' @('Multiply', 'Num*', 'NumMul')
Add-GBKeyName 107 'NumPlus' @('Add', 'Num+')
Add-GBKeyName 109 'NumMoins' @('Subtract', 'Num-', 'NumMinus')
Add-GBKeyName 110 'NumPoint' @('Decimal', 'Num.')
Add-GBKeyName 111 'NumDiv' @('Divide', 'Num/')
Add-GBKeyName 37 'Gauche' @('Left')
Add-GBKeyName 38 'Haut' @('Up')
Add-GBKeyName 39 'Droite' @('Right')
Add-GBKeyName 40 'Bas' @('Down')
Add-GBKeyName 19 'Pause' @('Attn')
Add-GBKeyName 45 'Inser' @('Insert', 'Ins')
Add-GBKeyName 46 'Suppr' @('Delete', 'Del')
Add-GBKeyName 36 'Debut' @('Home', 'Origine')
Add-GBKeyName 35 'Fin' @('End')
Add-GBKeyName 33 'PgPrec' @('PageUp', 'PgUp', 'Prior')
Add-GBKeyName 34 'PgSuiv' @('PageDown', 'PgDn', 'Next')
Add-GBKeyName 32 'Espace' @('Space')
Add-GBKeyName 13 'Entree' @('Enter', 'Return')
Add-GBKeyName 27 'Echap' @('Esc', 'Escape')
Add-GBKeyName 9 'Tab' @('Tabulation')
Add-GBKeyName 8 'RetourArr' @('Backspace', 'Back', 'Retour')
Add-GBKeyName 44 'ImprEcran' @('PrintScreen', 'PrtSc', 'Snapshot')
$Script:GBModCode = @{ 'ctrl' = 2; 'control' = 2; 'ctl' = 2; 'strg' = 2; 'alt' = 1; 'shift' = 4; 'maj' = 4; 'win' = 8; 'windows' = 8; 'meta' = 8 }

# Texte -> @{ Mods; Vk; Key; Text } (Mods comme RegisterHotKey : Alt 1, Ctrl 2, Shift 4, Win 8), $null si invalide
function ConvertTo-GBHotkey([string]$text) {
    if (-not $text) { return $null }
    $t = $text.Trim()
    if (-not $t) { return $null }
    $parts = @($t -split '\s*\+\s*' | Where-Object { $_ -ne '' })
    # 'Num+' et 'Ctrl++' : le signe plus en fin de texte est la touche
    if ($t.EndsWith('+') -and $parts.Count -ge 1 -and $parts[-1] -match '^(Num|Pave)$') { $parts[-1] = $parts[-1] + '+' }
    $mods = 0; $vk = 0
    foreach ($p in $parts) {
        $k = $p.Trim().ToLower()
        if ($Script:GBModCode.ContainsKey($k)) { $mods = $mods -bor $Script:GBModCode[$k]; continue }
        if ($vk -ne 0) { return $null }   # deux touches principales
        if ($Script:GBKeyCode.ContainsKey($k)) { $vk = [int]$Script:GBKeyCode[$k] } else { return $null }
    }
    if ($vk -eq 0) { return $null }
    $txt = Format-GBHotkey $mods $vk
    return @{ Mods = [int]$mods; Vk = [int]$vk; Key = $Script:GBKeyName[$vk]; Text = $txt }
}
function Format-GBHotkey([int]$mods, [int]$vk) {
    $s = @()
    if ($mods -band 2) { $s += 'Ctrl' }
    if ($mods -band 1) { $s += 'Alt' }
    if ($mods -band 4) { $s += 'Shift' }
    if ($mods -band 8) { $s += 'Win' }
    if ($vk -gt 0) {
        if ($Script:GBKeyName.ContainsKey($vk)) { $s += $Script:GBKeyName[$vk] } else { return '' }
    }
    return ($s -join '+')
}
# Texte normalise ('' si vide ou invalide)
function Format-GBHotkeyText([string]$text) { $k = ConvertTo-GBHotkey $text; if ($k) { return $k.Text }; return '' }

# --- Registre des actions -----------------------------------------------------
$Script:GBActions = [ordered]@{}
$Script:GBActionRunning = @{}
$Script:GBActionSeq = 0
$Script:GBNextHkId = 0x0100
$Script:GBMenuDirty = $false
$Script:GBMenuOrder = @('GameBoost', 'Boost', 'Performances', 'Ecrans', 'Jeux', 'Outils', 'Affichage', 'Aide')
$Script:GBMenuText = @{ GameBoost = '&GameBoost'; Boost = '&Boost'; Performances = '&Performances'; Ecrans = '&Ecrans'; Jeux = '&Jeux'; Outils = '&Outils'; Affichage = '&Affichage'; Aide = 'Ai&de' }
$Script:GBHotkeyReg = @{}        # numero RegisterHotKey -> @{ Text; Ok; Err; Act }
$Script:GBHotkeyWarned = @{}
$Script:GBHotkeyWin = $null
$Script:GBHotkeysSuspended = $false
$Script:GBQuietDepth = 0
$Script:GBReducedBase = $false
$Script:GBDefaultKeyOverride = @{}   # touche par defaut imposee pour une action declaree sans -DefaultKey
if (-not $Script:GBPendingActions) { $Script:GBPendingActions = New-Object System.Collections.ArrayList }
$Script:GBOnClick = [System.Windows.Forms.Control].GetMethod('OnClick', [System.Reflection.BindingFlags]'NonPublic, Instance')

function Register-GBAction {
    param([string]$Id, [string]$Label, [string]$Menu = 'Outils', [scriptblock]$Run, [string]$DefaultKey = '', [switch]$Global,
          [string[]]$Editions, [scriptblock]$Checked, [scriptblock]$Enabled, [string]$Group = '', [int]$Order = 0,
          [string]$Confirm = '', [string]$Description = '', $Data = $null)
    if (-not $Id -or -not $Run) { Log ("Action ignoree (id ou -Run manquant) : " + $Id); return }
    if (-not $Label) { $Label = $Id }
    if ($Script:GBMenuOrder -notcontains $Menu) { $Menu = 'Outils' }
    $old = $Script:GBActions[$Id]
    if (-not $DefaultKey -and $Script:GBDefaultKeyOverride.ContainsKey($Id)) { $DefaultKey = $Script:GBDefaultKeyOverride[$Id] }
    $Script:GBActionSeq++
    $a = @{ Id = $Id; Label = $Label; Menu = $Menu; Run = $Run; DefaultKey = (Format-GBHotkeyText $DefaultKey); Global = [bool]$Global
            Editions = @($Editions | Where-Object { $_ }); Checked = $Checked; Enabled = $Enabled; Group = $Group; Order = $Order
            Confirm = $Confirm; Description = $Description; Data = $Data; Seq = $Script:GBActionSeq; HkId = 0 }
    if ($a.Order -le 0) { $a.Order = 500 }
    # Re-declaration : meme numero de raccourci global et meme place
    if ($old) { $a.HkId = $old.HkId; $a.Seq = $old.Seq } else { $Script:GBNextHkId++; $a.HkId = $Script:GBNextHkId }
    $Script:GBActions[$Id] = $a
    $Script:GBKeyMap = $null
    Request-GBActionRefresh
}
function Get-GBActions { return @($Script:GBActions.Values) }
# Retire une action (ex. lien supprime) : son raccourci global est libere, le choix de touche est oublie
function Unregister-GBAction([string]$Id) {
    if (-not $Script:GBActions.Contains($Id)) { return $false }
    $a = $Script:GBActions[$Id]
    $Script:GBActions.Remove($Id)
    $hk = [int]$a.HkId
    if ($Script:GBHotkeyReg.ContainsKey($hk)) { if ($Script:GBHotkeyWin) { try { [void]$Script:GBHotkeyWin.Unregister($hk) } catch {} }; $Script:GBHotkeyReg.Remove($hk) }
    try { $st = Get-GBHotkeyStore; if ($st.ContainsKey($Id)) { $st.Remove($Id); Save-Config } } catch {}
    $Script:GBKeyMap = $null
    Request-GBActionRefresh
    return $true
}
# Action visible dans le modele en cours (-Editions)
function Test-GBActionShown($a) {
    if (-not $a) { return $false }
    if (@($a.Editions).Count -eq 0) { return $true }
    $ed = [string]$Script:Edition; if (-not $ed) { $ed = 'Nexus' }
    return (@($a.Editions) -contains $ed)
}
# File d'attente : actions declarees par les modules charges avant celui-ci
function Register-GBPendingActions {
    if (-not $Script:GBPendingActions) { return }
    $list = @($Script:GBPendingActions); $Script:GBPendingActions.Clear()
    foreach ($p in $list) {
        try { if ($p -is [hashtable]) { Register-GBAction @p } } catch { Log ("Action de la file ignoree : " + $_.Exception.Message) }
    }
}
# Menus et raccourcis globaux mis a jour une fois, apres une serie de declarations
function Request-GBActionRefresh {
    $Script:GBMenuDirty = $true
    if ($Script:GBRefreshPending -or -not $Script:Menu) { return }
    try {
        if ($form.IsHandleCreated) {
            $Script:GBRefreshPending = $true
            [void]$form.BeginInvoke([System.Action]{ $Script:GBRefreshPending = $false; try { Update-GBMenu; Sync-GBHotkeys } catch { Log ("Menus : " + $_.Exception.Message) } })
        }
    } catch { $Script:GBRefreshPending = $false }
}

# Touches de l'action : choix de l'utilisateur (config 'Hotkeys'), sinon touche par defaut ; '' = aucune
function Get-GBHotkeyStore {
    $cfg = $Script:Config; if ($Script:RealConfig) { $cfg = $Script:RealConfig }
    if (-not ($cfg.Hotkeys -is [hashtable])) {
        $h = @{}; if ($cfg.Hotkeys) { foreach ($pp in $cfg.Hotkeys.PSObject.Properties) { $h[$pp.Name] = [string]$pp.Value } }
        $cfg['Hotkeys'] = $h
    }
    # Copie "mesure seule" ou profil de jeu : meme table
    if ($Script:RealConfig -and $Script:Config) { $Script:Config['Hotkeys'] = $cfg.Hotkeys }
    return $cfg.Hotkeys
}
function Get-GBActionKey([string]$Id) {
    $a = $Script:GBActions[$Id]
    $st = Get-GBHotkeyStore
    if ($st.ContainsKey($Id)) { return (Format-GBHotkeyText ([string]$st[$Id])) }
    if ($a) { return [string]$a.DefaultKey }
    return ''
}
# $Keys = 'Ctrl+Shift+F1' ; '' = aucun raccourci ; $null = revenir a la touche par defaut
function Set-GBActionKey([string]$Id, $Keys) {
    $st = Get-GBHotkeyStore
    $a = $Script:GBActions[$Id]
    if ($null -eq $Keys) { $st.Remove($Id) }
    else {
        $t = ''
        if ([string]$Keys) { $k = ConvertTo-GBHotkey ([string]$Keys); if (-not $k) { return $false }; $t = $k.Text }
        if ($a -and $t -eq $a.DefaultKey) { $st.Remove($Id) } else { $st[$Id] = $t }
    }
    try { Save-Config } catch { Log ("Raccourcis : enregistrement impossible (" + $_.Exception.Message + ")") }
    $Script:GBMenuDirty = $true; $Script:GBKeyMap = $null
    Sync-GBHotkeys
    if ($Script:Menu) { try { Update-GBMenuState $null } catch {} }
    return $true
}
# Action qui utilise deja cette combinaison (dans le modele en cours), sinon $null
function Find-GBActionByKey([string]$text, [string]$exceptId = '') {
    if (-not $text) { return $null }
    foreach ($a in $Script:GBActions.Values) {
        if ($a.Id -eq $exceptId -or -not (Test-GBActionShown $a)) { continue }
        if ((Get-GBActionKey $a.Id) -eq $text) { return $a }
    }
    return $null
}

# Table touches -> action (raccourcis locaux : une recherche par touche appuyee, recalculee seulement apres un changement)
$Script:GBKeyMap = $null
function Get-GBKeyMap {
    if ($Script:GBKeyMap) { return $Script:GBKeyMap }
    $m = @{}
    foreach ($a in $Script:GBActions.Values) {
        if (-not (Test-GBActionShown $a)) { continue }
        $k = Get-GBActionKey $a.Id
        if ($k -and -not $m.ContainsKey($k)) { $m[$k] = $a }
    }
    $Script:GBKeyMap = $m
    return $m
}

# Execute une action : protegee (erreur = journal), un deuxieme appui pendant qu'elle tourne est ignore
function Invoke-GBAction([string]$Id, [string]$Source = 'code') {
    $a = $Script:GBActions[$Id]
    if (-not $a) { Log ("Action inconnue : " + $Id); return $false }
    if (-not (Test-GBActionShown $a)) { return $false }
    if ($Script:GBActionRunning.ContainsKey($Id)) { return $false }
    if ($a.Enabled) {
        $en = $true; try { $en = [bool](& $a.Enabled $a) } catch { $en = $true }
        if (-not $en) { if ($Source -eq 'key') { Log ("Raccourci : '" + $a.Label + "' indisponible pour l'instant") }; return $false }
    }
    if ($a.Confirm) {
        $r = [System.Windows.Forms.MessageBox]::Show($a.Confirm, "GameBoost", "YesNo", "Question")
        if ($r -ne "Yes") { return $false }
    }
    $Script:GBActionRunning[$Id] = $true
    $Script:GBActionSource = $Source
    # Action lancee au clavier : aucune animation (changement instantane) ; les fenetres ouvertes ("...") gardent les leurs
    $quiet = ($Source -eq 'key' -and $Script:UiOK -and -not $a.Label.EndsWith('...'))
    if ($quiet) {
        try { if ($Script:GBQuietDepth -le 0) { $Script:GBReducedBase = [GBMotion]::ForceReduced }; $Script:GBQuietDepth++; [GBMotion]::ForceReduced = $true } catch { $quiet = $false }
    }
    $ok = $false
    try { [void](& $a.Run $a); $ok = $true }
    catch { Log ("Erreur de l'action '" + $a.Label + "' : " + $_.Exception.Message) }
    finally {
        $Script:GBActionRunning.Remove($Id)
        $Script:GBActionSource = ''
        # Retour aux animations apres le travail deja mis en file par l'action (ex. balayage du bouton BOOST)
        if ($quiet) {
            $done = $false
            try { if ($form.IsHandleCreated) { [void]$form.BeginInvoke([System.Action]{ Exit-GBQuiet }); $done = $true } } catch {}
            if (-not $done) { Exit-GBQuiet }
        }
    }
    return $ok
}
function Exit-GBQuiet {
    $Script:GBQuietDepth--
    if ($Script:GBQuietDepth -le 0) { $Script:GBQuietDepth = 0; try { [GBMotion]::ForceReduced = $Script:GBReducedBase } catch {} }
}

# Appel du gestionnaire d'un bouton meme s'il n'est pas range dans la fenetre (PerformClick ne marche que s'il est visible)
function Invoke-GBClick($ctl) {
    if (-not $ctl -or $ctl.IsDisposed) { return $false }
    if (-not $ctl.Enabled) { return $false }
    [void]$Script:GBOnClick.Invoke($ctl, @([EventArgs]::Empty))
    return $true
}
# Interrupteur : inverse la case (ses evenements se declenchent), puis la config est enregistree
function Switch-GBCheck($chk, [string]$name) {
    if (-not $chk -or $chk.IsDisposed) { return }
    if (-not $chk.Enabled) { Log ("'" + $name + "' indisponible sur ce PC"); return }
    $chk.Checked = -not $chk.Checked
    try { Sync-ConfigFromUI } catch {}
    if ($Script:GBActionSource -eq 'key') { Log ($name + " : " + $(if ($chk.Checked) { "active" } else { "desactive" }) + " (raccourci)") }
}
function Invoke-GBIfExists([string]$name) { if (Get-Command $name -CommandType Function -ErrorAction SilentlyContinue) { & $name } }

# Niveau gaming choisi au clavier ou dans le menu (meme effet que lacher le curseur)
function Set-GBGameLevel([int]$v) {
    $v = [math]::Max(0, [math]::Min($Script:GameLevels.Count - 1, $v))
    $lv = $Script:GameLevels[$v]
    if ($lv.On -contains 'Force') {
        $q = "Niveau Extreme : pendant le boost, les applis ouvertes sont fermees DE FORCE.`r`n`r`nTout ce qui n'est pas enregistre dans ces applis (document, message en cours...) sera perdu. Les apps autorisees ne sont jamais fermees.`r`n`r`nChoisir ce niveau ?"
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Niveau gaming", "YesNo", "Warning") -ne "Yes") { Update-GameLevelUI; return }
    }
    $Script:GameLevelApplying = $true
    try { foreach ($k in $Script:GameChecks.Keys) { $c = $Script:GameChecks[$k]; if ($c.Enabled) { $c.Checked = ($lv.On -contains $k) } } }
    finally { $Script:GameLevelApplying = $false }
    Sync-ConfigFromUI
    Update-GameLevelUI
    $msg = "Niveau gaming : " + $lv.L
    if ($Script:Boosted) { $msg += " (s'applique au prochain boost)" }
    Log $msg
}
function Step-GBGameLevel([int]$delta) {
    $cur = Get-GameLevelNow
    if ($cur -lt 0) { try { $cur = [int]$sldGame.Value } catch { $cur = 2 } }
    $nv = $cur + $delta
    if ($nv -lt 0 -or $nv -ge $Script:GameLevels.Count) { Log ("Niveau gaming : deja au niveau " + $Script:GameLevels[$cur].L); return }
    Set-GBGameLevel $nv
}

# Fenetre principale : cachee pres de l'horloge si elle est au premier plan, sinon ramenee devant
function Switch-GBMainWindow {
    $front = ($form.Visible -and $form.WindowState -ne 'Minimized' -and [System.Windows.Forms.Form]::ActiveForm -eq $form)
    if ($front) { $form.Hide() } else { Show-GBMainFront }
}

# --- Raccourcis globaux (RegisterHotKey) ---------------------------------------
function Get-GBHotkeyErrText([int]$err) {
    if ($err -eq 1409) { return "deja prise par un autre programme ou par Windows" }
    if ($err -eq -1) { return "fenetre des raccourcis indisponible" }
    if ($err -eq 0) { return "refusee par Windows" }
    return ("refusee par Windows (code " + $err + ")")
}
function Start-GBHotkeys {
    if ($Script:GBHotkeyWin -or -not $Script:HotkeyOK) { return }
    try {
        $Script:GBHotkeyWin = New-Object GBHotkeyWindow
        $Script:GBHotkeyWin.add_Pressed({ param($s, $e) Invoke-GBHotkeyId ([int]$e.Id) })
        Sync-GBHotkeys
    } catch { $Script:GBHotkeyWin = $null; $Script:HotkeyError = $_.Exception.Message; Log ("Raccourcis globaux indisponibles : " + $Script:HotkeyError) }
}
function Stop-GBHotkeys {
    if (-not $Script:GBHotkeyWin) { return }
    try { $Script:GBHotkeyWin.Dispose() } catch {}
    $Script:GBHotkeyWin = $null; $Script:GBHotkeyReg.Clear()
}
# Pendant la saisie d'une combinaison : plus aucun raccourci global (sinon Ctrl+Alt+F9 lancerait le boost au lieu d'etre note)
function Suspend-GBHotkeys {
    $Script:GBHotkeysSuspended = $true
    if ($Script:GBHotkeyWin) { try { $Script:GBHotkeyWin.UnregisterAll() } catch {} }
    $Script:GBHotkeyReg.Clear()
}
function Resume-GBHotkeys { $Script:GBHotkeysSuspended = $false; Sync-GBHotkeys }
# Enregistre les raccourcis globaux voulus, retire les anciens ; un echec est garde (affiche dans la fenetre, reessaye chaque minute)
function Sync-GBHotkeys {
    $win = $Script:GBHotkeyWin
    if (-not $win -or $Script:GBHotkeysSuspended) { return }
    if ($win.Recreated) { $win.Recreated = $false; $Script:GBHotkeyReg.Clear() }
    $want = @{}
    foreach ($a in $Script:GBActions.Values) {
        if (-not $a.Global -or -not (Test-GBActionShown $a)) { continue }
        $k = ConvertTo-GBHotkey (Get-GBActionKey $a.Id)
        if ($k) { $want[[int]$a.HkId] = @{ Mods = $k.Mods; Vk = $k.Vk; Text = $k.Text; Act = $a.Id } }
    }
    foreach ($id in @($Script:GBHotkeyReg.Keys)) {
        $r = $Script:GBHotkeyReg[$id]
        if (-not $want.ContainsKey($id) -or $want[$id].Text -ne $r.Text) { try { [void]$win.Unregister([int]$id) } catch {}; $Script:GBHotkeyReg.Remove($id) }
    }
    foreach ($id in @($want.Keys)) {
        $w = $want[$id]
        if ($Script:GBHotkeyReg.ContainsKey($id) -and $Script:GBHotkeyReg[$id].Ok) { continue }
        $ok = $false; $err = 0
        try { $ok = $win.Register([int]$id, [int]$w.Mods, [int]$w.Vk); $err = $win.LastError } catch { $err = -1 }
        $Script:GBHotkeyReg[$id] = @{ Text = $w.Text; Ok = $ok; Err = $err; Act = $w.Act; Mods = $w.Mods; Vk = $w.Vk }
        $wk = $w.Act + '|' + $w.Text
        if (-not $ok -and -not $Script:GBHotkeyWarned.ContainsKey($wk)) {
            $Script:GBHotkeyWarned[$wk] = $true
            Log ("Raccourci global " + $w.Text + " (" + $Script:GBActions[$w.Act].Label + ") indisponible : " + (Get-GBHotkeyErrText $err))
        }
    }
}
# Etat du raccourci d'une action, pour la fenetre des raccourcis
function Get-GBHotkeyStatus($a) {
    $key = Get-GBActionKey $a.Id
    if (-not $key) { return @{ Ok = $true; Text = "" } }
    if (-not $a.Global) { return @{ Ok = $true; Text = "fenetre active" } }
    if (-not $Script:HotkeyOK -or -not $Script:GBHotkeyWin) { return @{ Ok = $false; Text = "fenetre active seulement (composant bloque)" } }
    if ($Script:GBHotkeysSuspended) { return @{ Ok = $true; Text = "en pause (saisie)" } }
    $r = $Script:GBHotkeyReg[[int]$a.HkId]
    if (-not $r) { return @{ Ok = $false; Text = "pas encore enregistre" } }
    if ($r.Ok) { return @{ Ok = $true; Text = "actif partout" } }
    return @{ Ok = $false; Text = (Get-GBHotkeyErrText ([int]$r.Err)) }
}
function Invoke-GBHotkeyId([int]$hk) {
    $r = $Script:GBHotkeyReg[$hk]
    if (-not $r) { return }
    if ($Script:BusyDepth -gt 0) { Log ("Raccourci " + $r.Text + " ignore : GameBoost est occupe"); return }
    [void](Invoke-GBAction $r.Act 'key')
}

# Raccourcis locaux : touches appuyees quand la fenetre GameBoost est active
function Get-GBKeyEventText($e) {
    $vk = [int]$e.KeyCode
    if (-not $Script:GBKeyName.ContainsKey($vk)) { return '' }
    $mods = 0
    if ($e.Control) { $mods = $mods -bor 2 }
    if ($e.Alt) { $mods = $mods -bor 1 }
    if ($e.Shift) { $mods = $mods -bor 4 }
    if ($Script:HotkeyOK) { try { if ([GBKeyState]::WinDown) { $mods = $mods -bor 8 } } catch {} }
    return (Format-GBHotkey $mods $vk)
}
function Invoke-GBLocalKey($e) {
    $txt = Get-GBKeyEventText $e
    if (-not $txt) { return }
    $map = Get-GBKeyMap
    if (-not $map.ContainsKey($txt)) { return }
    $a = $map[$txt]
    # Raccourci global qui marche deja : Windows l'a deja traite (on ne le double pas)
    if ($a.Global -and $Script:GBHotkeyWin) { $r = $Script:GBHotkeyReg[[int]$a.HkId]; if ($r -and $r.Ok) { return } }
    $e.Handled = $true; $e.SuppressKeyPress = $true
    if ($Script:BusyDepth -gt 0) { return }
    [void](Invoke-GBAction $a.Id 'key')
}

# --- Regles des combinaisons ---------------------------------------------------
# @{ Ok; Kind ('ok'|'empty'|'invalid'|'nomod'|'altgr'|'reserved'|'edit'|'conflict'|'taken'); Text; Other }
$Script:GBReservedKeys = @{
    'Ctrl+Alt+Suppr' = "ouvre l'ecran de securite de Windows"; 'Ctrl+Shift+Echap' = "ouvre le Gestionnaire des taches"; 'Ctrl+Echap' = "ouvre le menu Demarrer"
    'Alt+Tab' = "passe d'une fenetre a l'autre"; 'Alt+Shift+Tab' = "passe d'une fenetre a l'autre"; 'Alt+Echap' = "passe d'une fenetre a l'autre"; 'Alt+F4' = "ferme la fenetre"
    'Alt+Espace' = "ouvre le menu de la fenetre"; 'Win+L' = "verrouille le PC"; 'Win+D' = "affiche le bureau"; 'Win+G' = "ouvre la Xbox Game Bar"
    'Alt+Win+R' = "enregistre une video (Game Bar)"; 'Alt+Win+G' = "enregistre les dernieres secondes (Game Bar)"; 'Win+Tab' = "ouvre la vue des taches"
    'Win+R' = "ouvre Executer"; 'Win+E' = "ouvre l'Explorateur"; 'Win+I' = "ouvre les Parametres"; 'Win+X' = "ouvre le menu Demarrer avance"
    'F10' = "active le menu de la fenetre"; 'Shift+F10' = "ouvre le menu contextuel"; 'Ctrl+Shift+Win+B' = "relance le pilote graphique"
}
$Script:GBEditKeys = @{ 'Ctrl+C' = 'copier'; 'Ctrl+V' = 'coller'; 'Ctrl+X' = 'couper'; 'Ctrl+A' = 'tout selectionner'; 'Ctrl+Z' = 'annuler'; 'Ctrl+Y' = 'retablir'; 'Ctrl+Inser' = 'copier'; 'Shift+Inser' = 'coller'; 'Shift+Suppr' = 'couper' }
function Test-GBHotkeyChoice([string]$Id, [string]$text) {
    $a = $Script:GBActions[$Id]
    if (-not $text) { return @{ Ok = $true; Kind = 'empty'; Text = "Aucun raccourci." } }
    $k = ConvertTo-GBHotkey $text
    if (-not $k) { return @{ Ok = $false; Kind = 'invalid'; Text = ("Combinaison non reconnue : " + $text + ". Touches possibles : lettres, chiffres, F1 a F24, pave numerique, fleches, Pause, Inser, Suppr...") } }
    $t = $k.Text; $m = $k.Mods; $vk = $k.Vk
    $typing = (($vk -ge 65 -and $vk -le 90) -or ($vk -ge 48 -and $vk -le 57) -or $vk -eq 32)
    $isGlobal = [bool]($a -and $a.Global)
    # AltGr = Ctrl+Alt sur un clavier AZERTY : bloquerait la frappe de @ # { [ | ` \ ^ ] } et de l'euro
    if (($m -band 3) -eq 3 -and -not ($m -band 8) -and (($vk -ge 65 -and $vk -le 90) -or ($vk -ge 48 -and $vk -le 57))) {
        return @{ Ok = $false; Kind = 'altgr'; Text = ($t + " est refuse : sur un clavier AZERTY, Ctrl+Alt = AltGr. Ce raccourci empecherait d'ecrire @ # { [ | `` \ ^ ] } et le symbole euro" + $(if ($isGlobal) { " dans TOUT Windows" } else { "" }) + ". Prends plutot Ctrl+Alt+F1 a F12, Ctrl+Shift+une lettre ou Ctrl+Alt+Shift+F1 a F12.") }
    }
    if ($Script:GBReservedKeys.ContainsKey($t)) { return @{ Ok = $false; Kind = 'reserved'; Text = ($t + " est reserve par Windows (" + $Script:GBReservedKeys[$t] + ").") } }
    if (($m -band 8) -and $typing) { return @{ Ok = $false; Kind = 'reserved'; Text = ("Win + lettre ou chiffre est reserve par Windows (raccourcis du systeme). Prends plutot Ctrl+Alt+F1 a F12.") } }
    $fkey = ($vk -ge 112 -and $vk -le 135)
    $hiF = ($vk -ge 124 -and $vk -le 135)
    if (($m -band 11) -eq 0) {
        # Sans Ctrl / Alt / Win
        if ($m -band 4) {
            if (-not $fkey) { return @{ Ok = $false; Kind = 'nomod'; Text = ("Shift seul avec cette touche sert a ecrire (majuscules, chiffres). Ajoute Ctrl ou Alt.") } }
        } elseif ($isGlobal -and -not ($hiF -or $vk -eq 19)) {
            return @{ Ok = $false; Kind = 'nomod'; Text = ($t + " seule en raccourci global ne marcherait plus dans tes jeux ni dans les autres programmes. Ajoute Ctrl, Alt ou Shift (ex. Ctrl+Alt+" + $k.Key + ").") }
        } elseif (-not $isGlobal -and -not ($fkey -or $vk -eq 19 -or $vk -eq 45)) {
            return @{ Ok = $false; Kind = 'nomod'; Text = ($t + " seule servirait aussi a ecrire ou a se deplacer dans la fenetre. Ajoute Ctrl, Alt ou Shift.") }
        }
    }
    if ($Script:GBEditKeys.ContainsKey($t)) { return @{ Ok = $false; Kind = 'edit'; Text = ($t + " sert deja a " + $Script:GBEditKeys[$t] + " dans les champs de texte.") } }
    $o = Find-GBActionByKey $t $Id
    if ($o) { return @{ Ok = $false; Kind = 'conflict'; Other = $o.Id; Text = ($t + " est deja utilise par '" + $o.Label + "'. Clique sur Remplacer pour le lui retirer.") } }
    if ($isGlobal -and $Script:GBHotkeyWin) {
        # Deja enregistre par cette action : forcement libre
        $mine = $Script:GBHotkeyReg[[int]$a.HkId]
        if (-not ($mine -and $mine.Ok -and $mine.Text -eq $t)) {
            $free = $true; try { $free = $Script:GBHotkeyWin.Probe($m, $vk) } catch {}
            if (-not $free) { return @{ Ok = $false; Kind = 'taken'; Text = ($t + " est deja pris par Windows ou par un autre programme ouvert (Discord, logiciel de la carte graphique, enregistreur...). Choisis une autre combinaison.") } }
        }
    }
    return @{ Ok = $true; Kind = 'ok'; Text = $t }
}

# --- Barre de menus du haut ------------------------------------------------------
function Get-GBMenuRenderer {
    if (-not $Script:HotkeyOK) { return $null }
    try {
        $dark = $true; if ($Script:Theme -and $null -ne $Script:Theme.IsDark) { $dark = [bool]$Script:Theme.IsDark }
        $acc = $cCyan; if ($cAccent) { $acc = $cAccent }
        $col = New-Object GBMenuColors
        $col.Back = $cRail; $col.Drop = $cPanel; $col.Hover = $cSel; $col.Border = $cLine
        $r = New-Object GBMenuRenderer($col)
        $r.Text = $cText; $r.Muted = $cMuted; $r.Accent = $acc; $r.Line = $cLine
        # Sombre (NEXUS, ARENA) : titre ouvert a la couleur d'accent ; clair (PURE) : texte normal sur fond selectionne
        if ($dark) { $r.TopActive = $acc } else { $r.TopActive = $cText }
        return $r
    } catch { return $null }
}
function New-GBMenuBar {
    if (-not $Script:GBCoreDone) { Register-GBCoreActions }
    Register-GBPendingActions
    if ($Script:Menu -and -not $Script:Menu.IsDisposed) { Update-GBMenu; return $Script:Menu }
    $h = 24; if ($Script:MenuH) { $h = [int]$Script:MenuH } else { $Script:MenuH = $h }
    $m = New-Object System.Windows.Forms.MenuStrip
    $m.Dock = 'Top'; $m.AutoSize = $false; $m.Height = $h
    $m.Padding = New-Object System.Windows.Forms.Padding(6, 0, 0, 0)
    $m.GripStyle = 'Hidden'; $m.ShowItemToolTips = $true; $m.CanOverflow = $false
    $m.Font = $fontUI; $m.BackColor = $cRail; $m.ForeColor = $cText
    $rd = Get-GBMenuRenderer
    if ($rd) { $m.Renderer = $rd }
    $Script:GBMenuTops = [ordered]@{}
    foreach ($name in $Script:GBMenuOrder) {
        $t = New-Object System.Windows.Forms.ToolStripMenuItem($Script:GBMenuText[$name])
        $t.Tag = $name
        if ($rd) { $t.ForeColor = $cText }
        $t.add_DropDownOpening({ try { if ($Script:GBMenuDirty) { Update-GBMenu }; if ($Script:GBMenuBuilt[[string]$this.Tag] -ne $Script:GBMenuVersion) { Build-GBMenuTop $this } else { Update-GBMenuState $this } } catch { Log ("Menu : " + $_.Exception.Message) } })
        [void]$m.Items.Add($t)
        $Script:GBMenuTops[$name] = $t
    }
    $m.add_MenuActivate({ try { if ($Script:GBMenuDirty) { Update-GBMenu } } catch {} })
    $form.Controls.Add($m)
    $form.MainMenuStrip = $m
    $Script:Menu = $m
    # Raccourcis locaux : la fenetre voit les touches avant ses controles (le Ctrl+1..9 de secours de la mise en page se retire)
    $Script:GBKeysByActions = $true
    $form.KeyPreview = $true
    $form.Add_KeyDown({ param($s, $e) try { Invoke-GBLocalKey $e } catch {} })
    Update-GBMenu
    Start-GBHotkeys
    # Actions declarees entre la construction et l'affichage : menus et raccourcis globaux a jour des l'ouverture
    $form.Add_Shown({ try { if ($Script:GBMenuDirty) { Update-GBMenu }; Sync-GBHotkeys } catch {} })
    # Crochets du socle (fermeture, verification chaque minute) ; sans eux, fermeture branchee directement
    if (Get-Command Add-GBCloseHook -ErrorAction SilentlyContinue) { Add-GBCloseHook { Stop-GBHotkeys } }
    else { $form.Add_FormClosing({ param($s, $e) if ($e.Cancel) { return }; Stop-GBHotkeys }) }
    if (Get-Command Add-GBMinuteCheck -ErrorAction SilentlyContinue) { Add-GBMinuteCheck 'raccourcis' { Test-GBHotkeysHealth } }
    if (-not $Script:HotkeyOK) { Log ("Raccourcis globaux indisponibles (composant bloque : " + $Script:HotkeyError + ") : les raccourcis marchent quand la fenetre GameBoost est active") }
    return $m
}
# Reconstruit le contenu des menus (actions declarees apres coup, modele, touches)
# Menus a jour : les menus du haut vides sont caches ; le contenu d'un menu est (re)construit a sa prochaine ouverture
# (demarrage rapide, et les actions declarees apres coup par les autres modules apparaissent toujours)
$Script:GBMenuVersion = 0
$Script:GBMenuBuilt = @{}
function Update-GBMenu {
    if (-not $Script:Menu -or $Script:Menu.IsDisposed) { return }
    $Script:GBMenuDirty = $false
    $Script:GBMenuVersion++
    $count = @{}
    foreach ($a in $Script:GBActions.Values) { if (Test-GBActionShown $a) { $count[$a.Menu] = 1 + [int]$count[$a.Menu] } }
    foreach ($name in $Script:GBMenuOrder) {
        $top = $Script:GBMenuTops[$name]
        $top.Visible = ([int]$count[$name] -gt 0)
        if ($top.DropDown.Visible) { Build-GBMenuTop $top }
        # Un menu sans element ne s'ouvre pas : element d'attente remplace a l'ouverture
        elseif ($top.DropDownItems.Count -eq 0) { [void]$top.DropDownItems.Add((New-Object System.Windows.Forms.ToolStripMenuItem('...'))) }
    }
}
function Build-GBMenuTop($top) {
    $name = [string]$top.Tag
    $old = @($top.DropDownItems | ForEach-Object { $_ })
    $top.DropDownItems.Clear()
    foreach ($o in $old) { try { $o.Dispose() } catch {} }
    $acts = @($Script:GBActions.Values | Where-Object { $_.Menu -eq $name -and (Test-GBActionShown $_) } | Sort-Object @{ Expression = { $_.Order } }, @{ Expression = { $_.Seq } })
    # Sous-menus (-Group) : places a l'endroit de leur premiere action ; un trait entre les blocs (centaines de -Order)
    $subs = @{}; $lastBlock = $null
    foreach ($a in $acts) {
        $block = [math]::Floor($a.Order / 100)
        if ($a.Group) {
            if (-not $subs.ContainsKey($a.Group)) {
                if ($null -ne $lastBlock -and $block -ne $lastBlock) { [void]$top.DropDownItems.Add((New-Object System.Windows.Forms.ToolStripSeparator)) }
                $lastBlock = $block
                $sm = New-Object System.Windows.Forms.ToolStripMenuItem($a.Group)
                $sm.add_DropDownOpening({ try { Update-GBMenuState $this } catch {} })
                [void]$top.DropDownItems.Add($sm)
                $subs[$a.Group] = @{ Item = $sm; Last = $null }
            }
            $sg = $subs[$a.Group]
            if ($null -ne $sg.Last -and $block -ne $sg.Last) { [void]$sg.Item.DropDownItems.Add((New-Object System.Windows.Forms.ToolStripSeparator)) }
            $sg.Last = $block
            [void]$sg.Item.DropDownItems.Add((New-GBMenuItem $a))
        } else {
            if ($null -ne $lastBlock -and $block -ne $lastBlock) { [void]$top.DropDownItems.Add((New-Object System.Windows.Forms.ToolStripSeparator)) }
            $lastBlock = $block
            [void]$top.DropDownItems.Add((New-GBMenuItem $a))
        }
    }
    $Script:GBMenuBuilt[$name] = $Script:GBMenuVersion
    Update-GBMenuState $top
}
function New-GBMenuItem($a) {
    $mi = New-Object System.Windows.Forms.ToolStripMenuItem($a.Label)
    $mi.Tag = $a.Id
    $tt = $a.Description
    if ($a.Global) { if ($tt) { $tt += "`r`n" }; $tt += "Raccourci global : marche aussi en jeu, fenetre cachee." }
    if ($tt) { $mi.ToolTipText = $tt }
    $mi.add_Click({ try { [void](Invoke-GBAction ([string]$this.Tag) 'menu') } catch {} })
    return $mi
}
# Coches, grise / actif et touches affichees a droite (a l'ouverture d'un menu, ou partout si $item = $null)
function Update-GBMenuState($item) {
    if (-not $Script:Menu) { return }
    $roots = @()
    if ($item) { $roots = @($item) } else { $roots = @($Script:GBMenuTops.Values) }
    $stack = New-Object System.Collections.Stack
    foreach ($r in $roots) { $stack.Push($r) }
    while ($stack.Count -gt 0) {
        $it = $stack.Pop()
        if ($it -isnot [System.Windows.Forms.ToolStripMenuItem]) { continue }
        foreach ($ch in $it.DropDownItems) { $stack.Push($ch) }
        $a = $null; if ($it.Tag -is [string]) { $a = $Script:GBActions[[string]$it.Tag] }
        if (-not $a) { continue }
        $it.ShortcutKeyDisplayString = (Get-GBActionKey $a.Id)
        $it.ShowShortcutKeys = $true
        if ($a.Checked) { $c = $false; try { $c = [bool](& $a.Checked $a) } catch {}; $it.Checked = $c }
        if ($a.Enabled) { $en = $true; try { $en = [bool](& $a.Enabled $a) } catch {}; $it.Enabled = $en }
    }
}

# Verification chaque minute : les raccourcis globaux sont toujours a GameBoost, sinon nouvel essai
function Test-GBHotkeysHealth {
    if (-not $Script:HotkeyOK) { return $null }
    if (-not $Script:GBHotkeyWin) { Start-GBHotkeys; if (-not $Script:GBHotkeyWin) { return "fenetre des raccourcis globaux impossible a creer" }; return "raccourcis globaux relances" }
    if ($Script:GBHotkeysSuspended) { return $null }
    $fixed = 0
    [void]$Script:GBHotkeyWin.Ensure()
    foreach ($id in @($Script:GBHotkeyReg.Keys)) {
        $r = $Script:GBHotkeyReg[$id]
        # Combinaison libre alors qu'elle devrait etre a nous : perdue, on la reprend
        if ($r.Ok) { $lost = $false; try { $lost = $Script:GBHotkeyWin.Probe([int]$r.Mods, [int]$r.Vk) } catch {}; if ($lost) { $r.Ok = $false; $fixed++ } }
    }
    Sync-GBHotkeys
    $bad = @($Script:GBHotkeyReg.Values | Where-Object { -not $_.Ok })
    if ($bad.Count -gt 0) { return ("" + $bad.Count + " raccourci(s) global(aux) indisponible(s) : " + (@($bad | ForEach-Object { $_.Text + " (" + (Get-GBHotkeyErrText ([int]$_.Err)) + ")" }) -join ", ")) }
    if ($fixed -gt 0) { return ("" + $fixed + " raccourci(s) global(aux) perdu(s), enregistre(s) de nouveau") }
    return $null
}

# --- Actions du moteur (apres la mise en page : les boutons TURBO / GPU et les pages existent) ---
function Register-GBCoreActions {
    $Script:GBCoreDone = $true
    # GameBoost
    Register-GBAction -Id 'hotkeys.panel' -Label 'Raccourcis clavier...' -Menu 'GameBoost' -Order 100 -Run { Show-HotkeysPanel } -Description "Choisis une touche pour chaque option de GameBoost."
    Register-GBAction -Id 'window.toggle' -Label 'Afficher / cacher la fenetre' -Menu 'GameBoost' -Order 200 -DefaultKey 'Ctrl+Alt+F8' -Global -Run { Switch-GBMainWindow }
    Register-GBAction -Id 'tray.panel' -Label 'Panneau rapide (boost, luminosite, ecrans, FPS)' -Menu 'GameBoost' -Order 200 -DefaultKey 'Ctrl+Alt+F7' -Global -Run { Show-GBTrayPanel -Corner } -Description "Le panneau du clic droit sur l'icone, en bas a droite de l'ecran. Meme touche ou Echap pour le fermer."
    Register-GBAction -Id 'startup.toggle' -Label 'Lancer GameBoost avec Windows' -Menu 'GameBoost' -Order 200 -Run { $chkStartup.Checked = -not $chkStartup.Checked } -Checked { [bool]$chkStartup.Checked }
    Register-GBAction -Id 'app.closetotray' -Label "La croix range GameBoost pres de l'horloge" -Menu 'GameBoost' -Order 200 -Run { $Script:Config.CloseToTray = -not [bool]$Script:Config.CloseToTray; Save-Config } -Checked { [bool]$Script:Config.CloseToTray } -Description "Fermer la fenetre la cache seulement : GameBoost continue pres de l'horloge (clic droit sur l'icone)."
    Register-GBAction -Id 'app.quit' -Label 'Quitter (tout est remis comme avant)' -Menu 'GameBoost' -Order 900 -Run { Exit-GBApp }
    # Boost
    Register-GBAction -Id 'boost.toggle' -Label 'Lancer / arreter le boost' -Menu 'Boost' -Order 100 -DefaultKey 'Ctrl+Alt+F9' -Global -Run { Switch-BoostManual } -Checked { [bool]$Script:Boosted }
    Register-GBAction -Id 'boost.auto' -Label 'Boost automatique (quand un jeu se lance)' -Menu 'Boost' -Order 100 -Run { Switch-GBCheck $chkAuto 'Boost automatique' } -Checked { [bool]$chkAuto.Checked }
    Register-GBAction -Id 'boost.measure' -Label 'Mode comparaison : mesurer sans optimiser' -Menu 'Boost' -Order 200 -Run { Switch-GBCheck $chkMeasure 'Mode comparaison' } -Checked { [bool]$chkMeasure.Checked }
    Register-GBAction -Id 'boost.fps' -Label 'Mesurer les FPS en jeu (PresentMon)' -Menu 'Boost' -Order 200 -Run { Switch-GBCheck $chkFps 'Mesure des FPS' } -Checked { [bool]$chkFps.Checked } -Enabled { [bool]$chkFps.Enabled }
    Register-GBAction -Id 'overlay.toggle' -Label 'Overlay en jeu (FPS, CPU, GPU, ping)' -Menu 'Boost' -Order 300 -DefaultKey 'Ctrl+Alt+F10' -Global -Checked { [bool]$Script:Config.Overlay } -Run {
        $Script:Config.Overlay = -not [bool]$Script:Config.Overlay; Save-Config
        if (-not $Script:Config.Overlay) { Hide-GBOverlay }
        Log ("Overlay en jeu : " + $(if ($Script:Config.Overlay) { "active" + $(if ($Script:Boosted) { "" } else { " (visible pendant le boost)" }) } else { "desactive" }))
    }
    # Performances : TURBO, GPU, niveau gaming, RAM, interrupteurs et reglages
    Register-GBAction -Id 'turbo.toggle' -Label 'TURBO du processeur (coche = ON)' -Menu 'Performances' -Order 100 -DefaultKey 'Ctrl+Alt+F11' -Global -Checked { -not [bool]$Script:Config.TurboOnlyInGame } -Run {
        # Fonction du bouton (partie commune des modeles), sinon le bouton lui-meme, sinon le meme travail ici
        if (Get-Command Switch-GBTurbo -CommandType Function -ErrorAction SilentlyContinue) { Switch-GBTurbo }
        elseif (-not (Invoke-GBClick $Script:BtnTurbo)) {
            $Script:Config.TurboOnlyInGame = -not [bool]$Script:Config.TurboOnlyInGame; Save-Config
            Invoke-GBIfExists 'Update-GBTurboButton'; Update-GBTurboCap
        }
        Log ("TURBO : " + $(if ($Script:Config.TurboOnlyInGame) { "OFF (coupe hors jeu)" } else { "ON" }))
    }
    Register-GBAction -Id 'turbo.settings' -Label 'Reglages du TURBO...' -Menu 'Performances' -Order 100 -Run { Show-TurboSettings; Invoke-GBIfExists 'Update-GBTurboButton' }
    Register-GBAction -Id 'gpu.toggle' -Label 'Carte graphique ON / ECO (coche = ON)' -Menu 'Performances' -Order 200 -DefaultKey 'Ctrl+Alt+F12' -Global -Checked { -not [bool]$Script:Config.GpuEco } -Run {
        $i = Get-GBGpuCtlInfo
        if (-not ($i.Smi -and $i.CanLock)) {
            # Carte non reglable directement : au clavier on l'ecrit dans le journal, depuis le menu on ouvre la fenetre d'explication
            if ($Script:GBActionSource -eq 'key') { Log "GPU ECO : cette carte graphique ne se regle pas directement (voir l'engrenage GPU)"; return }
            Show-GpuSettings; Invoke-GBIfExists 'Update-GBGpuButton'; return
        }
        if (Get-Command Switch-GBGpuMode -CommandType Function -ErrorAction SilentlyContinue) { Switch-GBGpuMode }
        elseif (-not (Invoke-GBClick $Script:BtnGpu)) {
            $Script:Config.GpuEco = -not [bool]$Script:Config.GpuEco; Save-Config
            Invoke-GBIfExists 'Update-GBGpuButton'; $Script:GpuLastKey = $null; Update-GBGpuCap
        }
        Log ("Carte graphique : " + $(if ($Script:Config.GpuEco) { "ECO" } else { "ON" }))
    }
    Register-GBAction -Id 'gpu.settings' -Label 'Reglages de la carte graphique...' -Menu 'Performances' -Order 200 -Run { Show-GpuSettings; Invoke-GBIfExists 'Update-GBGpuButton' }
    Register-GBAction -Id 'gpu.apps' -Label 'Applis sur la carte graphique...' -Menu 'Performances' -Order 200 -Run { Show-AppGpuSettings }
    Register-GBAction -Id 'level.up' -Label 'Niveau gaming : un cran plus fort' -Menu 'Performances' -Order 300 -Run { Step-GBGameLevel 1 }
    Register-GBAction -Id 'level.down' -Label 'Niveau gaming : un cran plus doux' -Menu 'Performances' -Order 300 -Run { Step-GBGameLevel (-1) }
    Register-GBAction -Id 'level.reco' -Label 'Reglages recommandes' -Menu 'Performances' -Order 300 -Run { if (-not (Invoke-GBClick $btnReco)) { Log "Reglages recommandes indisponibles" } }
    Register-GBAction -Id 'ram.purge' -Label 'Vider la RAM en attente maintenant' -Menu 'Performances' -Order 400 -Run {
        $ok = Invoke-StandbyPurge "vidage manuel"
        if (-not $ok) {
            if ($Script:GBActionSource -eq 'key') { Log "Vidage de la RAM en attente : echec (detail plus haut)" }
            else { [System.Windows.Forms.MessageBox]::Show("Le vidage a echoue (fonction bloquee par un antivirus ?). Detail dans le journal.", "GameBoost") | Out-Null }
        }
    }
    $g1 = 'Optimisations du boost'
    $opts = @(
        @('opt.close', $chkClose, 'Fermer les autres applications', 1100), @('opt.force', $chkForce, 'Forcer la fermeture (risque de perte)', 1100),
        @('opt.services', $chkServices, 'Services inutiles en pause', 1100), @('opt.ram', $chkRam, 'Liberer la RAM des autres programmes', 1100),
        @('opt.power', $chkPower, 'Alimentation au maximum', 1100), @('opt.prio', $chkPrio, 'Priorite CPU haute pour le jeu', 1100),
        @('opt.lowbg', $chkLowBg, 'Launchers en priorite basse', 1100), @('opt.reopen', $chkReopen, 'Rouvrir les applis fermees apres le jeu', 1100),
        @('opt.standby', $chkStandby, 'Anti-saccades (cache RAM)', 1200), @('opt.dvr', $chkDvr, "Couper l'enregistrement Xbox (Game Bar)", 1200),
        @('opt.rp', $chkRP, 'Point de restauration avant le boost', 1200), @('opt.gpuprio', $chkGpu, 'Priorite GPU et planificateur aux jeux', 1200),
        @('opt.plan', $chkPlan, 'USB, PCIe et processeur au maximum', 1200), @('opt.gpupref', $chkGpuPref, 'Carte graphique puissante (portables)', 1200),
        @('opt.nagle', $chkNetwork, 'Reseau : Nagle coupe (jeux TCP / MMO)', 1200), @('opt.mouse', $chkMouse, "Desactiver l'acceleration de la souris", 1200),
        @('opt.known', $chkKnown, 'Detecter les jeux populaires', 1300)
    )
    foreach ($o in $opts) {
        # La case est passee dans -Data : le meme scriptblock sert a tous les interrupteurs
        Register-GBAction -Id $o[0] -Label $o[2] -Menu 'Performances' -Group $g1 -Order $o[3] -Data @{ Chk = $o[1]; Name = $o[2] } `
            -Run { param($a) Switch-GBCheck $a.Data.Chk $a.Data.Name } -Checked { param($a) [bool]$a.Data.Chk.Checked } -Enabled { param($a) [bool]$a.Data.Chk.Enabled }
    }
    # Fermeture forcee : demande avant d'activer (meme avertissement que le niveau Extreme)
    $Script:GBActions['opt.force'].Run = {
        param($a)
        if (-not $chkForce.Checked) {
            $q = "Fermeture FORCEE : pendant le boost, les applis ouvertes sont fermees de force et ce qui n'est pas enregistre est perdu. Les apps autorisees ne sont jamais fermees.`r`n`r`nActiver ?"
            if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost", "YesNo", "Warning") -ne "Yes") { return }
        }
        Switch-GBCheck $chkForce 'Fermeture forcee'
    }
    $g2 = 'Reglages des optimisations'
    Register-GBAction -Id 'set.close' -Label 'Programmes a fermer...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-CloseSettings }
    Register-GBAction -Id 'set.services' -Label 'Services mis en pause...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-ServicesSettings }
    Register-GBAction -Id 'set.lowbg' -Label 'Launchers en priorite basse...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-LowBgSettings }
    Register-GBAction -Id 'set.standby' -Label 'Anti-saccades (seuils)...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-StandbySettings }
    Register-GBAction -Id 'set.power' -Label 'Alimentation pendant le boost...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-PowerSettings }
    Register-GBAction -Id 'set.prio' -Label 'Priorite du jeu...' -Menu 'Performances' -Group $g2 -Order 1400 -Run { Show-GamePrioSettings }
    # Jeux
    Register-GBAction -Id 'games.hub' -Label 'Mes parties...' -Menu 'Jeux' -Order 100 -Run { Show-GameHub } -Description "Historique des parties, overlay en jeu, sauvegardes de jeux."
    Register-GBAction -Id 'games.add' -Label 'Ajouter un jeu (.exe)...' -Menu 'Jeux' -Order 200 -Run { [void](Invoke-GBClick $btnBrowse) }
    # Outils
    Register-GBAction -Id 'tools.wincfg' -Label 'Config Windows...' -Menu 'Outils' -Order 100 -Run { if (-not (Invoke-GBClick $btnWinCfg)) { Show-WindowsConfig; Update-GBTurboCap } }
    Register-GBAction -Id 'tools.uninstall' -Label 'Desinstallation profonde...' -Menu 'Outils' -Order 100 -Run { Show-DeepUninstall }
    Register-GBAction -Id 'tools.drivers' -Label 'Pilotes et mises a jour...' -Menu 'Outils' -Order 100 -Run { Show-DriverCenter }
    Register-GBAction -Id 'tools.diag' -Label 'Diagnostic du PC...' -Menu 'Outils' -Order 200 -Run { Show-Diagnostic }
    Register-GBAction -Id 'tools.prioapps' -Label 'Priorites des applis...' -Menu 'Outils' -Order 200 -Run { Show-AppPriorities }
    Register-GBAction -Id 'tools.restore' -Label 'TOUT RESTAURER...' -Menu 'Outils' -Order 900 -Run { [void](Invoke-GBClick $btnRestoreAll) } -Description "Remet le PC comme avant GameBoost (une question est posee avant)."
    # Aide
    Register-GBAction -Id 'help.report' -Label 'Rapport pour Claude' -Menu 'Aide' -Order 100 -Run { Export-ClaudeReport } -Enabled { [bool]$btnExport.Enabled }
    Register-GBAction -Id 'help.specs' -Label 'Copier les specs du PC' -Menu 'Aide' -Order 100 -Run { [void](Invoke-GBClick $btnSpecs) }
    Register-GBAction -Id 'help.logs' -Label 'Ouvrir les logs' -Menu 'Aide' -Order 100 -Run { [void](Invoke-GBClick $btnLogs) }
    Register-GBAction -Id 'help.about' -Label 'A propos de GameBoost' -Menu 'Aide' -Order 900 -Run {
        $ed = [string]$Script:Edition; if (-not $ed) { $ed = 'Nexus' }
        $nG = @($Script:GBActions.Values | Where-Object { $_.Global -and (Get-GBActionKey $_.Id) }).Count
        [System.Windows.Forms.MessageBox]::Show(("GameBoost " + $AppVersion + " - modele " + $ed.ToUpper() + "`r`n`r`nOptimiseur gaming : tout ce qui est change est remis comme avant.`r`n" +
            $nG + " raccourci(s) global(aux) : menu GameBoost > Raccourcis clavier."), "GameBoost") | Out-Null
    }
    # Affichage : pages de la mise en page, puis modele
    Register-GBPageActions
    foreach ($ed in @(@('Nexus', 'NEXUS', 'complet'), @('Arena', 'ARENA', 'gaming'), @('Pure', 'PURE', 'leger'))) {
        Register-GBAction -Id ('edition.' + $ed[0].ToLower()) -Label ($ed[1] + " (" + $ed[2] + ")") -Menu 'Affichage' -Group 'Modele' -Order 200 -Data $ed[0] `
            -Checked { param($a) ([string]$Script:Edition -eq $a.Data -or (-not $Script:Edition -and $a.Data -eq 'Nexus')) } -Enabled { [bool](Get-Command Switch-GBEdition -ErrorAction SilentlyContinue) } `
            -Run { param($a) if ([string]$Script:Edition -eq $a.Data) { return }; Switch-GBEdition $a.Data } -Description "GameBoost redemarre avec ce modele (reglages gardes)."
    }
}
# page.1 .. page.6 depuis l'ordre des pages de la mise en page (Ctrl+1 .. Ctrl+6)
function Register-GBPageActions {
    $keys = @($Script:PageOrder | Where-Object { $_ })
    if ($keys.Count -eq 0 -and $Script:Pages) { $keys = @($Script:Pages.Keys) }
    for ($i = 1; $i -le 6; $i++) {
        $id = 'page.' + $i
        if ($i -gt $keys.Count) { if ($Script:GBActions.Contains($id)) { $Script:GBActions.Remove($id); $Script:GBMenuDirty = $true; $Script:GBKeyMap = $null }; continue }
        $k = [string]$keys[$i - 1]; $title = $k
        try { $p = $Script:Pages[$k]; if ($p -and $p.Title) { $title = [string]$p.Title } elseif ($p -and $p.Nav -and $p.Nav.Text) { $title = [string]$p.Nav.Text } } catch {}
        Register-GBAction -Id $id -Label ("Page " + $i + " : " + $title) -Menu 'Affichage' -Order 100 -DefaultKey ('Ctrl+' + $i) -Data $k `
            -Run { param($a) Show-GBPage ([string]$a.Data) } -Checked { param($a) ([string]$Script:CurrentPage -eq [string]$a.Data) }
    }
}
Register-GBPendingActions

# --- Fenetre "Raccourcis clavier" : liste par menu, saisie de la combinaison, conflits en clair ---
function Show-HotkeysPanel {
    $d = New-GBDialog "Raccourcis clavier" 800 640
    $null = Add-DlgLabel $d "Raccourcis clavier" 16 8 500 30 $fontPage $cCyan
    $intro = "Global = marche partout, meme en jeu et fenetre cachee. Les autres marchent quand la fenetre GameBoost est active."
    if (-not $Script:HotkeyOK) { $intro = "Raccourcis globaux indisponibles (composant bloque par l'antivirus) : tous les raccourcis marchent seulement quand la fenetre GameBoost est active." }
    $null = Add-DlgLabel $d $intro 16 40 760 36 $fontUI $cMuted
    $lv = New-Object System.Windows.Forms.ListView
    $lv.View = "Details"; $lv.FullRowSelect = $true; $lv.MultiSelect = $false; $lv.HideSelection = $false
    $lv.Location = New-Object System.Drawing.Point(16, 78); $lv.Size = New-Object System.Drawing.Size(752, 318)
    foreach ($c in @(@('Action', 330), @('Raccourci', 150), @('Portee', 70), @('Etat', 180))) { [void]$lv.Columns.Add($c[0], $c[1]) }
    Set-GBListViewStyle $lv; $d.Controls.Add($lv)

    $pnl = New-Object System.Windows.Forms.Panel; $pnl.BackColor = $cPanel
    $pnl.Location = New-Object System.Drawing.Point(16, 406); $pnl.Size = New-Object System.Drawing.Size(752, 136); $d.Controls.Add($pnl)
    $lblAct = Add-DlgLabel $pnl "Choisis une action dans la liste." 12 8 728 22 $fontBold $cText
    $tb = New-Object System.Windows.Forms.TextBox
    $tb.ReadOnly = $true; $tb.ShortcutsEnabled = $false; $tb.TextAlign = "Center"; $tb.Font = $fontBold
    $tb.BackColor = $cDeep; $tb.ForeColor = $cText; $tb.BorderStyle = "FixedSingle"; $tb.Cursor = [System.Windows.Forms.Cursors]::Hand
    $tb.Location = New-Object System.Drawing.Point(12, 36); $tb.Size = New-Object System.Drawing.Size(260, 28); $tb.Enabled = $false
    $pnl.Controls.Add($tb)
    $tip.SetToolTip($tb, "Clique ici puis appuie sur la combinaison. Retour arriere = aucun raccourci, Echap = annuler.")
    $bClear = Add-DlgButton $pnl "Effacer" 282 35 100
    $bDef = Add-DlgButton $pnl "Par defaut" 390 35 110
    $bRep = Add-DlgButton $pnl "Remplacer" 508 35 110; $bRep.ForeColor = $cYellow; $bRep.Visible = $false
    $lblMsg = Add-DlgLabel $pnl "" 12 72 728 58 $fontUI $cMuted
    foreach ($b in @($bClear, $bDef)) { $b.Enabled = $false }
    $bReset = Add-DlgButton $d "Tout reinitialiser" 16 556 170; $bReset.ForeColor = $cRed
    $bClose = Add-DlgButton $d "Fermer" 652 556 116
    $d.CancelButton = $bClose; $bClose.Add_Click({ $d.Close() })

    $st = @{ Lv = $lv; Sel = $null; Pending = $null; Capturing = $false }
    # Remplit la liste : une ligne de titre par menu, puis ses actions
    $st.Fill = {
        $keep = $st.Sel
        $st.Lv.BeginUpdate(); $st.Lv.Items.Clear()
        foreach ($mn in $Script:GBMenuOrder) {
            $acts = @($Script:GBActions.Values | Where-Object { $_.Menu -eq $mn -and (Test-GBActionShown $_) } | Sort-Object @{ Expression = { $_.Order } }, @{ Expression = { $_.Seq } })
            if ($acts.Count -eq 0) { continue }
            $h = New-Object System.Windows.Forms.ListViewItem($mn.ToUpper()); $h.ForeColor = $cCyan; $h.Font = $fontBold; $h.Tag = $null
            [void]$st.Lv.Items.Add($h)
            foreach ($a in $acts) {
                $lab = "   " + $a.Label; if ($a.Group) { $lab = "   " + $a.Group + " > " + $a.Label }
                $it = New-Object System.Windows.Forms.ListViewItem($lab)
                $key = Get-GBActionKey $a.Id; $ks = Get-GBHotkeyStatus $a
                [void]$it.SubItems.Add($(if ($key) { $key } else { "-" }))
                [void]$it.SubItems.Add($(if ($a.Global) { "global" } else { "fenetre" }))
                [void]$it.SubItems.Add($ks.Text)
                if (-not $key) { $it.ForeColor = $cMuted } elseif (-not $ks.Ok) { $it.ForeColor = $cRed } elseif ($a.Global) { $it.ForeColor = $cGreen } else { $it.ForeColor = $cText }
                $it.Tag = $a.Id
                [void]$st.Lv.Items.Add($it)
                if ($a.Id -eq $keep) { $it.Selected = $true }
            }
        }
        $st.Lv.EndUpdate()
        if ($st.Lv.SelectedItems.Count -gt 0) { $st.Lv.SelectedItems[0].EnsureVisible() }
    }
    $st.Show = {
        $a = $null; if ($st.Sel) { $a = $Script:GBActions[$st.Sel] }
        $bRep.Visible = $false; $st.Pending = $null
        if (-not $a) {
            $lblAct.Text = "Choisis une action dans la liste."; $tb.Text = ""; $tb.Enabled = $false; $bClear.Enabled = $false; $bDef.Enabled = $false
            $lblMsg.Text = ""; return
        }
        $tb.Enabled = $true; $bClear.Enabled = $true; $bDef.Enabled = $true
        $lblAct.Text = $a.Label + $(if ($a.Global) { "   (global)" } else { "" })
        $key = Get-GBActionKey $a.Id; $tb.Text = $(if ($key) { $key } else { "(aucun)" })
        $dk = "aucun"; if ($a.DefaultKey) { $dk = $a.DefaultKey }
        $ks = Get-GBHotkeyStatus $a
        if ($key -and -not $ks.Ok) { $lblMsg.ForeColor = $cRed; $lblMsg.Text = $key + " : " + $ks.Text + ". Choisis une autre combinaison (raccourci par defaut : " + $dk + ")." }
        else { $lblMsg.ForeColor = $cMuted; $lblMsg.Text = "Clique dans la case puis appuie sur la combinaison (ex. Ctrl+Alt+F5). Retour arriere = aucun raccourci, Echap = annuler. Par defaut : " + $dk + "." }
    }
    $st.Apply = {
        param($text)
        if (-not $st.Sel) { return }
        $a = $Script:GBActions[$st.Sel]
        $res = Test-GBHotkeyChoice $st.Sel $text
        if ($res.Ok) {
            [void](Set-GBActionKey $st.Sel $(if ($res.Kind -eq 'empty') { '' } else { $res.Text }))
            & $st.Fill; & $st.Show
            $lblMsg.ForeColor = $cGreen
            if ($res.Kind -eq 'empty') { $lblMsg.Text = "'" + $a.Label + "' n'a plus de raccourci." } else { $lblMsg.Text = "Enregistre : " + $res.Text + " -> " + $a.Label + $(if ($a.Global) { " (marche aussi en jeu)" } else { "" }) }
            return
        }
        $tb.Text = $(if ((Get-GBActionKey $st.Sel)) { Get-GBActionKey $st.Sel } else { "(aucun)" })
        $lblMsg.Text = $res.Text
        if ($res.Kind -eq 'conflict') { $lblMsg.ForeColor = $cYellow; $st.Pending = @{ Text = (ConvertTo-GBHotkey $text).Text; Other = $res.Other }; $bRep.Visible = $true }
        else { $lblMsg.ForeColor = $cRed; $bRep.Visible = $false; $st.Pending = $null }
    }
    $lv.add_SelectedIndexChanged({
        $id = $null; if ($st.Lv.SelectedItems.Count -gt 0) { $id = $st.Lv.SelectedItems[0].Tag }
        if (-not $id) { if ($st.Lv.SelectedItems.Count -gt 0) { $st.Lv.SelectedItems[0].Selected = $false }; return }
        $st.Sel = [string]$id; & $st.Show
    })
    $lv.add_DoubleClick({ if ($st.Sel) { [void]$tb.Focus() } })
    $lv.add_KeyDown({ param($s, $e) if ($e.KeyCode -eq 'Enter' -and $st.Sel) { $e.Handled = $true; $e.SuppressKeyPress = $true; [void]$tb.Focus() } })
    # Saisie : toutes les touches vont dans la case (Tab, Entree, fleches comprises)
    $tb.add_PreviewKeyDown({ param($s, $e) $e.IsInputKey = $true })
    $tb.add_Enter({ $st.Capturing = $true; Suspend-GBHotkeys; $tb.BackColor = $cSel; $tb.Text = "Appuie sur la combinaison..." })
    $tb.add_Leave({ $st.Capturing = $false; $tb.BackColor = $cDeep; Resume-GBHotkeys; try { & $st.Fill } catch {} })
    $tb.add_KeyDown({
        param($s, $e)
        $e.Handled = $true; $e.SuppressKeyPress = $true
        if (-not $st.Sel) { return }
        $code = [int]$e.KeyCode
        $plain = (-not $e.Control -and -not $e.Alt -and -not $e.Shift)
        if ($plain -and $code -eq 27) { [void]$st.Lv.Focus(); return }
        if ($plain -and $code -eq 8) { [void]$st.Lv.Focus(); & $st.Apply ''; return }
        # Modificateur seul : apercu ("Ctrl+Alt+...")
        if (@(16, 17, 18, 91, 92) -contains $code) {
            $mods = 0; if ($e.Control) { $mods = $mods -bor 2 }; if ($e.Alt) { $mods = $mods -bor 1 }; if ($e.Shift) { $mods = $mods -bor 4 }
            if ($Script:HotkeyOK) { try { if ([GBKeyState]::WinDown) { $mods = $mods -bor 8 } } catch {} }
            $tb.Text = (Format-GBHotkey $mods 0) + "+..."
            return
        }
        $txt = Get-GBKeyEventText $e
        if (-not $txt) { $lblMsg.ForeColor = $cRed; $lblMsg.Text = "Cette touche n'est pas utilisable pour un raccourci. Touches possibles : lettres, chiffres, F1 a F24, pave numerique, fleches, Pause, Inser, Suppr, Debut, Fin, PgPrec, PgSuiv."; return }
        # Sortie de la case d'abord (raccourcis globaux remis), puis enregistrement et message
        [void]$st.Lv.Focus()
        & $st.Apply $txt
    })
    $tb.add_KeyUp({ param($s, $e) $e.Handled = $true; if ($st.Capturing -and $tb.Text.EndsWith('+...') -and -not $e.Control -and -not $e.Alt -and -not $e.Shift) { $tb.Text = "Appuie sur la combinaison..." } })
    $bClear.Add_Click({ & $st.Apply '' })
    $bDef.Add_Click({
        if (-not $st.Sel) { return }
        $a = $Script:GBActions[$st.Sel]
        if (-not $a.DefaultKey) { & $st.Apply ''; return }
        $o = Find-GBActionByKey $a.DefaultKey $a.Id
        if ($o) { $lblMsg.ForeColor = $cYellow; $lblMsg.Text = $a.DefaultKey + " est utilise par '" + $o.Label + "'. Clique sur Remplacer pour le lui retirer."; $st.Pending = @{ Text = $a.DefaultKey; Other = $o.Id }; $bRep.Visible = $true; return }
        [void](Set-GBActionKey $a.Id $null); & $st.Fill; & $st.Show
        $lblMsg.ForeColor = $cGreen; $lblMsg.Text = "Raccourci par defaut remis : " + $a.DefaultKey
    })
    $bRep.Add_Click({
        $p = $st.Pending; if (-not $p -or -not $st.Sel) { return }
        $other = $Script:GBActions[$p.Other]
        [void](Set-GBActionKey $p.Other '')
        $st.Pending = $null; $bRep.Visible = $false
        & $st.Apply $p.Text
        if ($other) { $lblMsg.Text += "   ('" + $other.Label + "' n'a plus de raccourci.)" }
    })
    $bReset.Add_Click({
        $r = [System.Windows.Forms.MessageBox]::Show("Remettre TOUS les raccourcis par defaut ?", "GameBoost - Raccourcis clavier", "YesNo", "Question")
        if ($r -ne "Yes") { return }
        $stt = Get-GBHotkeyStore; $stt.Clear(); $Script:GBKeyMap = $null
        try { Save-Config } catch {}
        Sync-GBHotkeys; $Script:GBMenuDirty = $true
        & $st.Fill; & $st.Show
        $lblMsg.ForeColor = $cGreen; $lblMsg.Text = "Tous les raccourcis sont revenus par defaut."
        Log "Raccourcis clavier remis par defaut"
    })
    & $st.Fill
    # Premiere action selectionnee
    foreach ($it in $lv.Items) { if ($it.Tag) { $it.Selected = $true; break } }
    try { [void]$d.ShowDialog($form) } finally { if ($Script:GBHotkeysSuspended) { Resume-GBHotkeys }; $d.Dispose() }
    if ($Script:Menu) { Update-GBMenuState $null }
}

# --- Ecran et FPS : luminosite de chaque ecran, limite de FPS (pilote NVIDIA) et frequence de l'ecran ---
# Luminosite : dalle du portable par Windows (WMI), ecran externe par DDC/CI (code 0x10, en arriere-plan).
# Limite de FPS : reglage "Frequence d'images maximale" du profil global NVIDIA ; la valeur d'origine est gardee pour "Tout restaurer".
$fpsSrc = @'
using System;
using System.Runtime.InteropServices;
// Limite de FPS de toutes les applis : reglage "Frequence d'images maximale" du pilote NVIDIA (profil global), via nvapi
public static class GBFpsCap {
    public const uint FRL_FPS = 0x10835002;
    [DllImport("nvapi64.dll", EntryPoint = "nvapi_QueryInterface", CallingConvention = CallingConvention.Cdecl)] static extern IntPtr QI64(uint id);
    [DllImport("nvapi.dll", EntryPoint = "nvapi_QueryInterface", CallingConvention = CallingConvention.Cdecl)] static extern IntPtr QI32(uint id);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DVoid();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DOut(out IntPtr a);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DH(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DHOut(IntPtr h, out IntPtr p);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DGet(IntPtr h, IntPtr p, uint id, IntPtr s);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DSet(IntPtr h, IntPtr p, IntPtr s);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int DDel(IntPtr h, IntPtr p, uint id);
    // NVDRS_SETTING (version 1) : 12320 octets
    const int SIZE = 12320, OFS_ID = 4100, OFS_TYPE = 4104, OFS_CUR = 8220;
    public static string LastError = "";

    static T Fn<T>(uint id) where T : class {
        IntPtr p = IntPtr.Zero;
        try { p = IntPtr.Size == 8 ? QI64(id) : QI32(id); } catch (DllNotFoundException) { throw new Exception("pilote NVIDIA absent (nvapi introuvable)"); }
        if (p == IntPtr.Zero) throw new Exception("fonction nvapi 0x" + id.ToString("X8") + " indisponible");
        return (T)(object)Marshal.GetDelegateForFunctionPointer(p, typeof(T));
    }
    public static bool Available() {
        try { return Fn<DVoid>(0x0150E828)() == 0; } catch (Exception ex) { LastError = ex.Message; return false; }
    }
    // Ouvre une session du pilote, appelle f(session, profil global), ferme
    static int WithGlobal(Func<IntPtr, IntPtr, int> f, bool save) {
        if (Fn<DVoid>(0x0150E828)() != 0) throw new Exception("nvapi ne s'initialise pas");
        IntPtr h;
        int rc = Fn<DOut>(0x0694D52E)(out h); if (rc != 0) throw new Exception("session du pilote refusee (" + rc + ")");
        try {
            rc = Fn<DH>(0x375DBD6B)(h); if (rc != 0) throw new Exception("lecture des reglages du pilote refusee (" + rc + ")");
            IntPtr prof; rc = Fn<DHOut>(0x617BFF9F)(h, out prof); if (rc != 0) throw new Exception("profil global introuvable (" + rc + ")");
            int r = f(h, prof);
            if (save) { rc = Fn<DH>(0xFCBC7E14)(h); if (rc != 0) throw new Exception("enregistrement refuse par le pilote (" + rc + ") : droits administrateur ?"); }
            return r;
        } finally { try { Fn<DH>(0xDAD9CFF8)(h); } catch { } }
    }
    // Limite actuelle : 0 = aucune, -1 = erreur (LastError)
    public static int Get() {
        try {
            return WithGlobal(delegate(IntPtr h, IntPtr p) {
                IntPtr s = Marshal.AllocHGlobal(SIZE);
                try {
                    for (int i = 0; i < SIZE; i += 4) Marshal.WriteInt32(s, i, 0);
                    Marshal.WriteInt32(s, 0, SIZE | (1 << 16));
                    int rc = Fn<DGet>(0x73BF8338)(h, p, FRL_FPS, s);
                    if (rc == -160) return 0;   // reglage absent du profil = aucune limite
                    if (rc != 0) throw new Exception("lecture de la limite refusee (" + rc + ")");
                    return Marshal.ReadInt32(s, OFS_CUR);
                } finally { Marshal.FreeHGlobal(s); }
            }, false);
        } catch (Exception ex) { LastError = ex.Message; return -1; }
    }
    // fps = 0 : retire la limite ; renvoie true si le pilote l'a enregistree
    public static bool Set(int fps) {
        try {
            WithGlobal(delegate(IntPtr h, IntPtr p) {
                if (fps <= 0) {
                    int rd = Fn<DDel>(0xE4A26362)(h, p, FRL_FPS);
                    if (rd != 0 && rd != -160) throw new Exception("retrait de la limite refuse (" + rd + ")");
                    return 0;
                }
                IntPtr s = Marshal.AllocHGlobal(SIZE);
                try {
                    for (int i = 0; i < SIZE; i += 4) Marshal.WriteInt32(s, i, 0);
                    Marshal.WriteInt32(s, 0, SIZE | (1 << 16));
                    Marshal.WriteInt32(s, OFS_ID, unchecked((int)FRL_FPS));
                    Marshal.WriteInt32(s, OFS_TYPE, 0);
                    Marshal.WriteInt32(s, OFS_CUR, fps);
                    int rc = Fn<DSet>(0x577DD202)(h, p, s);
                    if (rc != 0) throw new Exception("limite refusee par le pilote (" + rc + ")");
                    return 0;
                } finally { Marshal.FreeHGlobal(s); }
            }, true);
            return true;
        } catch (Exception ex) { LastError = ex.Message; return false; }
    }
}
'@
$Script:FpsOK = $null
function Initialize-GBFps {
    if ($null -ne $Script:FpsOK) { return $Script:FpsOK }
    $Script:FpsOK = $false
    try { $Script:FpsOK = [bool](Add-GBCompiled 'GBFps' $fpsSrc $null 'GBFpsCap') } catch {}
    return $Script:FpsOK
}
# Limite de FPS possible ? @{ Ok; Value (0 = aucune); Why }
function Get-GBFpsCapInfo([switch]$Refresh) {
    if ($Script:FpsInfo -and -not $Refresh) { return $Script:FpsInfo }
    $i = @{ Ok = $false; Value = 0; Why = "" }
    $nv = [bool]($Script:MainGpu -and [string]$Script:MainGpu.Name -match 'NVIDIA')
    if (-not $nv) {
        $i.Why = "Reserve aux cartes NVIDIA. AMD : Radeon Chill ou FRTC dans le logiciel AMD. Intel : limite dans les reglages du jeu."
    } elseif (-not (Initialize-GBFps)) {
        $i.Why = "Composant de GameBoost bloque (antivirus ?) : limite indisponible."
    } elseif (-not [GBFpsCap]::Available()) {
        $i.Why = "Pilote NVIDIA injoignable : " + [GBFpsCap]::LastError
    } else {
        $v = [GBFpsCap]::Get()
        if ($v -lt 0) { $i.Why = "Lecture impossible : " + [GBFpsCap]::LastError } else { $i.Ok = $true; $i.Value = $v }
    }
    $Script:FpsInfo = $i
    return $i
}
# Applique une limite (0 = aucune) ; la limite d'origine est retenue au premier changement
function Set-GBFpsCap([int]$Fps) {
    $i = Get-GBFpsCapInfo
    if (-not $i.Ok) { Log ("Limite de FPS indisponible : " + $i.Why); return $false }
    if ([int]$Script:Config.FpsCapOrig -lt 0) { $Script:Config.FpsCapOrig = [int]$i.Value }
    if (-not [GBFpsCap]::Set($Fps)) { Log ("Limite de FPS refusee : " + [GBFpsCap]::LastError); $Script:FpsInfo = $null; return $false }
    $now = [GBFpsCap]::Get(); $Script:FpsInfo = $null
    if ($Fps -gt 0 -and $now -ne $Fps) { Log ("Limite de FPS : le pilote garde " + $now + " au lieu de " + $Fps); return $false }
    $Script:Config.FpsCap = $Fps; Save-Config
    if ($Fps -gt 0) { Log ("Limite de FPS : " + $Fps + " images par seconde maximum (jeux lances ou relances apres ce changement)") }
    else { Log "Limite de FPS retiree (images par seconde illimitees)" }
    return $true
}
# Tout restaurer : limite d'origine du pilote
function Restore-GBFpsCap {
    $o = [int]$Script:Config.FpsCapOrig
    if ($o -lt 0) { return }
    $i = Get-GBFpsCapInfo -Refresh
    if ($i.Ok -and [GBFpsCap]::Set($o)) { Log ("Limite de FPS d'origine remise (" + $(if ($o -gt 0) { "" + $o + " FPS" } else { "aucune" }) + ")") }
    $Script:Config.FpsCapOrig = -1; $Script:Config.FpsCap = 0; Save-Config; $Script:FpsInfo = $null
    if ($Script:DispCard) { Update-GBDisplayCard }
}

# Ecrans dont la luminosite est reglable : dalle du portable (Windows) ou ecran externe (DDC)
function Get-GBWmiBrightness {
    try { return @(Get-CimInstance -Namespace root/wmi -ClassName WmiMonitorBrightness -ErrorAction Stop) } catch { return @() }
}
function Get-GBBrightTargets {
    $r = New-Object System.Collections.ArrayList
    $mons = @(); try { $mons = @(Get-GBMonitors -NoDdc | Where-Object { -not $_.Off }) } catch {}
    if ($null -eq $Script:WmiBrightOK) { $Script:WmiBrightOK = (@(Get-GBWmiBrightness).Count -gt 0) }
    foreach ($m in $mons) {
        $kind = $(if ($m.Internal) { 'wmi' } else { 'ddc' })
        if ($kind -eq 'wmi' -and -not $Script:WmiBrightOK) { $kind = '' }
        if ($kind -eq 'ddc' -and -not $Script:MonOK) { $kind = '' }
        $label = "" + $m.Index + " - " + $m.Name; if ($m.Internal) { $label += " (portable)" }; if ($m.Primary) { $label += " *" }
        [void]$r.Add([pscustomobject]@{ Device = [string]$m.Device; Label = $label; Kind = $kind; Primary = [bool]$m.Primary; Internal = [bool]$m.Internal })
    }
    # PC sans liste d'ecrans (composant bloque) : la dalle du portable seule
    if ($r.Count -eq 0 -and $Script:WmiBrightOK) { [void]$r.Add([pscustomobject]@{ Device = ''; Label = "Ecran du portable"; Kind = 'wmi'; Primary = $true; Internal = $true }) }
    return $r
}
# Luminosite actuelle : 0..100, -2 = en cours de lecture, -1 = non reglable
function Get-GBBrightness($t) {
    if (-not $t -or -not $t.Kind) { return -1 }
    if ($t.Kind -eq 'wmi') {
        $b = @(Get-GBWmiBrightness | Select-Object -First 1)
        if ($b.Count) { return [int]$b[0].CurrentBrightness }; return -1
    }
    $v = [GBMon]::LumKnown($t.Device)
    if ($v -lt 0) { return $v }
    $max = [int]($v -shr 16); if ($max -le 0) { $max = 100 }
    return [int][math]::Round(100.0 * ($v -band 0xFFFF) / $max)
}
function Set-GBBrightness($t, [int]$Pct) {
    $Pct = [math]::Max(0, [math]::Min(100, $Pct))
    if (-not $t -or -not $t.Kind) { return $false }
    if ($t.Kind -eq 'wmi') {
        try {
            $mt = @(Get-CimInstance -Namespace root/wmi -ClassName WmiMonitorBrightnessMethods -ErrorAction Stop)
            foreach ($x in $mt) { Invoke-CimMethod -InputObject $x -MethodName WmiSetBrightness -Arguments @{ Timeout = [uint32]1; Brightness = [byte]$Pct } -ErrorAction Stop | Out-Null }
            return ($mt.Count -gt 0)
        } catch { Log ("Luminosite : Windows refuse le changement (" + $_.Exception.Message + ")"); return $false }
    }
    $v = [GBMon]::LumKnown($t.Device); $max = 100
    if ($v -gt 0) { $max = [int]($v -shr 16); if ($max -le 0) { $max = 100 } }
    [GBMon]::LumSetAsync($t.Device, [int][math]::Round($Pct * $max / 100.0))
    return $true
}
# Ecran ou se trouve la souris (raccourcis luminosite +/-)
function Get-GBBrightTargetUnderMouse {
    $ts = @(Get-GBBrightTargets | Where-Object { $_.Kind })
    if ($ts.Count -eq 0) { return $null }
    $dev = ''; try { $dev = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).DeviceName } catch {}
    $hit = @($ts | Where-Object { $_.Device -eq $dev })
    if ($hit.Count) { return $hit[0] }
    return $ts[0]
}
function Step-GBBrightness([int]$Delta) {
    $t = Get-GBBrightTargetUnderMouse
    if (-not $t) { Log "Luminosite : aucun ecran reglable (ecran externe sans DDC/CI ?)"; return }
    if ($t.Kind -eq 'ddc' -and [GBMon]::LumKnown($t.Device) -eq -2) { [GBMon]::ProbeLumAsync([string[]]@($t.Device)); Start-Sleep -Milliseconds 400 }
    $cur = Get-GBBrightness $t
    if ($cur -lt 0) { Log ("Luminosite : " + $t.Label + " ne se regle pas depuis le PC (utilise les boutons de l'ecran)"); return }
    $new = [math]::Max(0, [math]::Min(100, $cur + $Delta))
    if (Set-GBBrightness $t $new) { if ($Script:DispCard) { Update-GBDisplayCard -Soon } }
}

# Frequence de l'ecran choisi : @{ Cur; Max } (0 si inconnue)
function Get-GBScreenHz([string]$dev) {
    $r = @{ Cur = 0; Max = 0; Dev = $dev }
    if (-not (Initialize-GBDisplay)) { return $r }
    foreach ($s in @([GBDisplay]::List())) {
        $p = $s.Split('|')
        if (-not $dev -or $p[0] -eq $dev) { $r.Cur = [int]$p[4]; $r.Max = [int]$p[5]; $r.Dev = $p[0]; break }
    }
    return $r
}

# Carte "Ecran et FPS" de l'accueil : ecran, luminosite, limite de FPS, frequence
$Script:FpsChoices = @(0, 30, 60, 90, 120, 144, 165, 240)
function New-GBDisplayCard($parent, $x, $y, $w) {
    $c = New-GBCard $parent $x $y $w 104 "Ecran et FPS" "luminosite, images par seconde, frequence" $cGreen
    $null = New-GBDisplayControls $c
    $colW = [int](($w - 32 - 24) / 2); $xR = 16 + $colW + 24
    # Colonne gauche : ecran + luminosite ; colonne droite : limite de FPS + frequence
    Set-GBDisplayRow $c 16 39 70 ($colW - 72) $Script:DispLbl.Scr @($Script:DispScr, $Script:DispScrName)
    Set-GBDisplayRow $c 16 69 70 ($colW - 72) $Script:DispLbl.Bright @($Script:DispBright, $Script:DispBrightNa)
    Set-GBDisplayRow $c $xR 39 110 ($colW - 112) $Script:DispLbl.Fps @($Script:DispFps)
    Set-GBDisplayRow $c $xR 69 110 ($colW - 112) $Script:DispLbl.Hz @($Script:DispHz)
    Set-GBPlace $Script:DispHzBtn $c ($xR + $colW - 104) 70 104 26
    return $c
}
# Une ligne de la carte : libelle gris a gauche, controle(s) a droite (meme place, un seul visible a la fois)
function Set-GBDisplayRow($parent, $x, $y, $lw, $cw, $lbl, $ctls) {
    Set-GBPlace $lbl $parent $x ($y + 3) $lw 20
    foreach ($k in @($ctls)) {
        if ($k -is [System.Windows.Forms.Label]) { Set-GBPlace $k $parent ($x + $lw + 2) ($y + 3) $cw 20 }
        elseif ($k -is [System.Windows.Forms.TrackBar] -or ($Script:SliderOK -and $k -is [GBSlider])) { Set-GBPlace $k $parent ($x + $lw + 2) ($y - 1) $cw 30 }
        else { Set-GBPlace $k $parent ($x + $lw + 2) $y $cw 26 }
        $k.BackColor = $parent.BackColor
    }
}
# Controles "Ecran et FPS" (communs aux 3 modeles) : chaque modele les range a sa facon
function New-GBDisplayControls($c) {
    $Script:DispCard = $c; $Script:DispSilent = $true
    $Script:DispLbl = @{
        Scr = New-GBLabelIn $c "Ecran" 0 0 70 20 $fontUI $cMuted; Bright = New-GBLabelIn $c "Luminosite" 0 0 70 20 $fontUI $cMuted
        Fps = New-GBLabelIn $c "Limite de FPS" 0 0 110 20 $fontUI $cMuted; Hz = New-GBLabelIn $c "Frequence" 0 0 110 20 $fontUI $cMuted }
    $Script:DispScr = New-GBComboCtl; $Script:DispScr.DropDownStyle = "DropDownList"; $c.Controls.Add($Script:DispScr)
    $Script:DispScrName = New-GBLabelIn $c "" 0 0 100 20 $fontBold $cText; $Script:DispScrName.AutoEllipsis = $true; $Script:DispScrName.Visible = $false
    $Script:DispBright = New-GBSlider $c 0 100 50 $null $null " %" 0 0 200
    if ($Script:DispBright -isnot [System.Windows.Forms.TrackBar]) { $Script:DispBright.ValueWidth = 46; $Script:DispBright.StepWheel = 5; $Script:DispBright.StepKey = 5; $Script:DispBright.FillColor = $cGreen }
    $Script:DispBrightNa = New-GBLabelIn $c "" 0 0 100 20 $fontSmall $cMuted; $Script:DispBrightNa.AutoEllipsis = $true; $Script:DispBrightNa.Visible = $false
    $Script:DispFps = New-GBComboCtl; $Script:DispFps.DropDownStyle = "DropDownList"; $c.Controls.Add($Script:DispFps)
    $Script:DispHz = New-GBLabelIn $c "" 0 0 100 20 $fontBold $cText; $Script:DispHz.AutoEllipsis = $true
    $Script:DispHzBtn = New-GBButtonCtl; $Script:DispHzBtn.Font = $fontSmall; $Script:DispHzBtn.ForeColor = $cGreen; $Script:DispHzBtn.Visible = $false; $c.Controls.Add($Script:DispHzBtn)
    $tip.SetToolTip($Script:DispBright, "Luminosite de l'ecran choisi. Ecran du portable : regle par Windows. Ecran externe : regle par le cable (DDC/CI, a activer dans le menu de l'ecran si besoin).")
    $tip.SetToolTip($Script:DispFps, ("Nombre maximum d'images par seconde pour TOUS les jeux (reglage du pilote NVIDIA)." + "`r`n" +
        "Moins de FPS = PC plus frais et plus silencieux. Conseil : un peu sous la frequence de l'ecran (ex : 162 pour 165 Hz) pour un jeu fluide sans dechirure." + "`r`n" +
        "S'applique aux jeux lances apres le changement. Remis comme avant avec TOUT RESTAURER."))
    $tip.SetToolTip($Script:DispHzBtn, "Passe l'ecran a sa frequence maximale (image plus fluide). Windows garde ce reglage.")
    $Script:DispScr.Add_SelectedIndexChanged({ if (-not $Script:DispSilent) { Update-GBDisplayCard -KeepScreen } })
    Add-SliderCommit $Script:DispBright {
        if ($Script:DispSilent) { return }
        $t = Get-GBDispTarget
        if ($t -and $t.Kind) { [void](Set-GBBrightness $t ([int]$Script:DispBright.Value)) }
    }
    $Script:DispFps.Add_SelectedIndexChanged({
        if ($Script:DispSilent) { return }
        $i = $Script:DispFps.SelectedIndex; if ($i -lt 0 -or $i -ge $Script:DispFpsVals.Count) { return }
        $v = [int]$Script:DispFpsVals[$i]
        if ($v -eq [int](Get-GBFpsCapInfo).Value) { return }
        [void](Set-GBFpsCap $v)
        Update-GBDisplayCard -KeepScreen
    })
    $Script:DispHzBtn.Add_Click({
        $t = Get-GBDispTarget; $hz = Get-GBScreenHz $(if ($t) { $t.Device } else { '' })
        if ($hz.Max -gt $hz.Cur -and $hz.Dev) {
            $rc = [GBDisplay]::SetHz($hz.Dev, $hz.Max)
            if ($rc -eq 0) { Log ("Ecran passe a " + $hz.Max + " Hz") } else { Log ("Frequence " + $hz.Max + " Hz refusee par Windows (code " + $rc + ")") }
        }
        Update-GBDisplayCard -KeepScreen
    })
    $Script:DispSilent = $false
    # Lecture apres l'affichage (Windows et DDC peuvent prendre un instant)
    Add-GBStartHook { Update-GBDisplayCard -Probe }
    return $c
}
function Get-GBDispTarget {
    $ts = @($Script:DispTargets)
    if ($ts.Count -eq 0) { return $null }
    # (selection de la liste, meme cachee : par defaut l'ecran principal)
    $i = 0; if ($Script:DispScr.SelectedIndex -ge 0) { $i = $Script:DispScr.SelectedIndex }
    if ($i -ge $ts.Count) { $i = 0 }
    return $ts[$i]
}
function Update-GBDisplayCard([switch]$Probe, [switch]$KeepScreen, [switch]$Soon) {
    if (-not $Script:DispCard) { return }
    if ($Soon) {
        if (-not $Script:DispSoonT) { $Script:DispSoonT = New-Object System.Windows.Forms.Timer; $Script:DispSoonT.Interval = 700; $Script:DispSoonT.Add_Tick({ $Script:DispSoonT.Stop(); Update-GBDisplayCard -KeepScreen }) }
        $Script:DispSoonT.Stop(); $Script:DispSoonT.Start(); return
    }
    $Script:DispSilent = $true
    try {
        if (-not $KeepScreen -or -not $Script:DispTargets) {
            $prev = ''; $old = Get-GBDispTarget; if ($old) { $prev = $old.Device }
            $Script:DispTargets = @(Get-GBBrightTargets)
            $Script:DispScr.Items.Clear()
            foreach ($t in $Script:DispTargets) { [void]$Script:DispScr.Items.Add($t.Label) }
            $sel = 0
            for ($k = 0; $k -lt $Script:DispTargets.Count; $k++) { if (($prev -and $Script:DispTargets[$k].Device -eq $prev) -or (-not $prev -and $Script:DispTargets[$k].Primary)) { $sel = $k } }
            if ($Script:DispScr.Items.Count -gt 0) { $Script:DispScr.SelectedIndex = $sel }
            $many = ($Script:DispTargets.Count -gt 1)
            $Script:DispScr.Visible = $many; $Script:DispScrName.Visible = -not $many
            $Script:DispScrName.Text = $(if ($Script:DispTargets.Count) { [string]$Script:DispTargets[0].Label } else { "aucun ecran detecte" })
            if ($Probe -and $Script:MonOK) {
                $ext = @($Script:DispTargets | Where-Object { $_.Kind -eq 'ddc' } | ForEach-Object { $_.Device })
                if ($ext.Count) { [GBMon]::ProbeLumAsync([string[]]$ext); $Script:DispProbeN = 0
                    if (-not $Script:DispProbeT) { $Script:DispProbeT = New-Object System.Windows.Forms.Timer; $Script:DispProbeT.Interval = 600
                        $Script:DispProbeT.Add_Tick({ $Script:DispProbeN++; $t = Get-GBDispTarget; $done = (-not $t -or $t.Kind -ne 'ddc' -or [GBMon]::LumKnown($t.Device) -ne -2)
                            if ($done -or $Script:DispProbeN -ge 8) { $Script:DispProbeT.Stop(); Update-GBDisplayCard -KeepScreen } }) }
                    $Script:DispProbeT.Start() }
            }
        }
        # Luminosite
        $t = Get-GBDispTarget; $v = Get-GBBrightness $t
        if ($v -ge 0) {
            $Script:DispBright.Visible = $true; $Script:DispBrightNa.Visible = $false; $Script:DispBright.Enabled = $true
            if ($Script:DispBright -is [System.Windows.Forms.TrackBar]) { $Script:DispBright.Value = $v } else { $Script:DispBright.SetValueSilently($v) }
        } else {
            $Script:DispBright.Visible = $false; $Script:DispBrightNa.Visible = $true
            $Script:DispBrightNa.Text = $(if ($v -eq -2) { "lecture de l'ecran..." } elseif ($t -and $t.Internal) { "non reglable par Windows sur ce PC" } else { "a regler avec les boutons de l'ecran (DDC/CI coupe)" })
        }
        # Limite de FPS
        $fi = Get-GBFpsCapInfo
        $hz = Get-GBScreenHz $(if ($t) { $t.Device } else { '' })
        $vals = New-Object System.Collections.ArrayList
        foreach ($n in $Script:FpsChoices) { [void]$vals.Add($n) }
        if ($hz.Cur -gt 30 -and -not $vals.Contains($hz.Cur - 3)) { [void]$vals.Add($hz.Cur - 3) }
        if ($fi.Value -gt 0 -and -not $vals.Contains([int]$fi.Value)) { [void]$vals.Add([int]$fi.Value) }
        $sorted = @(@($vals | Where-Object { $_ -gt 0 } | Sort-Object) )
        $Script:DispFpsVals = @(0) + $sorted
        $Script:DispFps.Items.Clear()
        foreach ($n in $Script:DispFpsVals) {
            if ($n -eq 0) { $lab = "Aucune limite" } elseif ($hz.Cur -gt 30 -and $n -eq $hz.Cur - 3) { $lab = "" + $n + " FPS (conseille)" } else { $lab = "" + $n + " FPS" }
            [void]$Script:DispFps.Items.Add($lab)
        }
        $Script:DispFps.SelectedIndex = [math]::Max(0, [array]::IndexOf([int[]]$Script:DispFpsVals, [int]$fi.Value))
        $Script:DispFps.Enabled = [bool]$fi.Ok
        if (-not $fi.Ok) { $tip.SetToolTip($Script:DispFps, ("Limite de FPS indisponible : " + $fi.Why)) }
        # Frequence
        if ($hz.Cur -gt 0) {
            if ($hz.Max -gt $hz.Cur) { $Script:DispHz.Text = "" + $hz.Cur + " Hz"; $Script:DispHz.ForeColor = $cYellow; $Script:DispHzBtn.Text = "Passer a " + $hz.Max + " Hz"; $Script:DispHzBtn.Visible = $true; $Script:DispHz.Width = [math]::Max(40, $Script:DispHzBtn.Left - $Script:DispHz.Left - 6) }
            else { $Script:DispHz.Text = "" + $hz.Cur + " Hz (le maximum)"; $Script:DispHz.ForeColor = $cText; $Script:DispHzBtn.Visible = $false; $Script:DispHz.Width = $Script:DispHzBtn.Right - $Script:DispHz.Left }
        } else { $Script:DispHz.Text = "inconnue"; $Script:DispHz.ForeColor = $cMuted; $Script:DispHzBtn.Visible = $false }
        # Modele avec sa propre presentation (PURE : sous-titres des lignes)
        if ($Script:DispAfterUpdate) { & $Script:DispAfterUpdate $t $v $fi $hz }
    } catch { Log ("Carte Ecran et FPS : " + $_.Exception.Message) }
    finally { $Script:DispSilent = $false }
}

# Menus et raccourcis (tous les modeles) : luminosite +/- sur l'ecran de la souris, limites de FPS
