function Get-SpecsLines {
    # Chaque ligne est lue separement : si une source manque, les autres restent (et des sources sans WMI servent de secours)
    $os = $null; try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch {}
    $cpu = $null
    try { $cpu = (Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1).Name.Trim() } catch {}
    if (-not $cpu) { try { $cpu = ([string](Get-ItemProperty 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -ErrorAction Stop).ProcessorNameString).Trim() } catch {} }
    if (-not $cpu) { $cpu = "n/d" }
    $ram = $null
    if ($os) { $ram = [math]::Round([double]$os.TotalVisibleMemorySize / 1MB, 1) }
    elseif ($Script:FastOK) { try { $ram = [math]::Round([double]([GBSys]::Memory())[0] / 1GB, 1) } catch {} }
    $mods = @(); try { $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop | ForEach-Object { [string]([math]::Round($_.Capacity / 1GB)) + " Go @ " + $_.Speed + " MHz" }) } catch {}
    $disks = @(); try { $disks = @(Get-CimInstance Win32_DiskDrive -ErrorAction Stop | ForEach-Object { $_.Model + " (" + [math]::Round($_.Size / 1GB) + " Go)" }) } catch {}
    $plan = "n/d"; try { $plan = ((powercfg /getactivescheme) -join ' ') -replace '^.*\(', '' -replace '\).*$', '' } catch {}
    $win = "n/d"
    if ($os) { $win = $os.Caption + " " + $Script:WinDisplay + " (build " + $os.BuildNumber + ", " + $Script:NativeArch + ")" }
    else { try { $cv = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop; $win = [string]$cv.ProductName + " " + $Script:WinDisplay + " (build " + $cv.CurrentBuild + ", " + $Script:NativeArch + ")" } catch {} }
    $type = "PC fixe"; if ($Script:IsLaptop) { $type = "PC portable" }
    $gpuTxt = "n/d"; try { $gpuTxt = Get-GpuSpecText } catch {}
    $txt = @(
        "=== Specs du PC (GameBoost " + $AppVersion + ") ===",
        ("Type        : " + $type),
        ("Processeur  : " + $cpu + " (" + $Script:Cores + " threads)"),
        ("Carte graph.: " + $gpuTxt),
        ("RAM         : " + $(if ($null -ne $ram) { "" + $ram + " Go" } else { "n/d" }) + $(if ($mods.Count) { " (" + ($mods -join ", ") + ")" } else { "" })),
        ("Disques     : " + $(if ($disks.Count) { $disks -join ", " } else { "n/d" })),
        ("Windows     : " + $win),
        ("Alimentation: " + $plan)
    )
    $scr = @()
    try { $scr = @(Get-CimInstance Win32_VideoController -ErrorAction Stop | Where-Object { $_.CurrentRefreshRate } | ForEach-Object { "" + $_.CurrentHorizontalResolution + "x" + $_.CurrentVerticalResolution + " a " + $_.CurrentRefreshRate + " Hz (max indique " + $_.MaxRefreshRate + " Hz)" }) } catch {}
    if ($scr.Count -eq 0) { try { $scr = @([System.Windows.Forms.Screen]::AllScreens | ForEach-Object { "" + $_.Bounds.Width + "x" + $_.Bounds.Height }) } catch {} }
    $txt += ("Ecran       : " + ($scr -join ", "))
    if ($Script:VramTotalGo) { $txt += ("VRAM        : " + $Script:VramTotalGo + " Go") }
    return $txt
}

$btnSpecs.Add_Click({
    try {
        [System.Windows.Forms.Clipboard]::SetText(((Get-SpecsLines) -join "`r`n"))
        Log "Specs copiees dans le presse-papiers"
    } catch { Log "Impossible de copier les specs" }
})

function Export-ClaudeReport {
    $btnExport.Enabled = $false
    $lblStatus.Text = "Creation du rapport pour Claude (15 secondes environ)..."
    $lblStatus.ForeColor = $cCyan
    [System.Windows.Forms.Application]::DoEvents()
    $out = New-Object System.Collections.ArrayList
    function A($t) { [void]$out.Add($t) }
    try {
        A "===== RAPPORT GAMEBOOST POUR CLAUDE ====="
        A ("Genere le " + (Get-Date -Format "dd/MM/yyyy HH:mm") + " par GameBoost " + $AppVersion)
        A "Envoie ce fichier a Claude : il contient la config du PC, le diagnostic et les dernieres sessions de jeu."
        A "Astuce : une partie en 'Mode comparaison' + une partie en BOOST sur le meme jeu = comparaison fiable."
        if ($Script:Boosted) { A "(Une session est en cours : arrete le boost puis refais le rapport pour l'inclure.)" }
        A ""
        A "## 1. CONFIGURATION DU PC"
        foreach ($l in (Get-SpecsLines)) { A $l }
        A ""
        A "## 1b. CARTES GRAPHIQUES (detail technique)"
        try { Initialize-GpuInventory } catch {}
        foreach ($l in (Get-GpuDetailLines)) { A $l }
        A ""
        A "## 2. REGLAGES GAMEBOOST"
        $opt = Get-OptionsText
        A ("Activees    : " + $opt[0])
        A ("Desactivees : " + $opt[1])
        A ("Mes jeux    : " + (@($Script:Config.Games) -join ", "))
        A ("Apps autorisees : " + (@($Script:Config.Whitelist) -join ", "))
        $pmTxt = "non"; if ($Script:PMPath) { $pmTxt = "oui" }
        A ("PresentMon disponible : " + $pmTxt)
        A ""
        A "## 3. DIAGNOSTIC"
        foreach ($l in @(Get-Diagnostic)) { A $l }
        A ""
        A "## 4. HISTORIQUE DES SESSIONS (les plus recentes en bas)"
        $idx = @(Get-SessionIndex)
        if ($idx.Count -eq 0) {
            A "Aucune session enregistree : joue au moins 10 minutes avec GameBoost actif (BOOST, mode auto ou mode comparaison), puis refais le rapport."
        } else {
            A "Date             | Jeu                  | Mode   | Duree | FPS   | 1% bas | Sacc/min | CPU | Coeur max | GPU | VRAM max | RAM | Ping"
            foreach ($e in @($idx | Select-Object -Last 20)) {
                A ("{0,-16} | {1,-20} | {2,-6} | {3,5} | {4,5} | {5,6} | {6,8} | {7,3} | {8,9} | {9,3} | {10,8} | {11,3} | {12,4}" -f
                   $e.Date, ([string]$e.Jeu).Substring(0, [math]::Min(20, ([string]$e.Jeu).Length)), $e.Mode, $e.DureeMin, $e.Fps, $e.Low1,
                   $e.SaccadesMin, $e.Cpu, $e.CoeurMax, $e.Gpu, $e.VramMax, $e.Ram, $e.Ping)
            }
        }
        A ""
        A "## 5. RAPPORTS DETAILLES DES 3 DERNIERES SESSIONS"
        $reports = @(Get-ChildItem -LiteralPath $LogDir -Filter 'rapport_session_*.txt' -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 3)
        if ($reports.Count -eq 0) { A "Aucun rapport de session pour l'instant." }
        foreach ($r in $reports) { foreach ($l in (Get-Content -LiteralPath $r.FullName -Encoding UTF8)) { A $l } }
        A ""
        A "## 6. PILOTES (derniere analyse du bouton 'Mises a jour pilotes')"
        if (Test-Path -LiteralPath $Script:DriverReportFile) { foreach ($l in (Get-Content -LiteralPath $Script:DriverReportFile -Encoding UTF8)) { A $l } }
        else { A "Pas encore d'analyse : clique sur 'Mises a jour pilotes' puis refais le rapport." }
        A ""
        A "## 7. ERREURS ET ALERTES DES 14 DERNIERS JOURS"
        $cut = (Get-Date).AddDays(-14)
        $groupsE = [ordered]@{}
        foreach ($lf in @(Get-ChildItem -LiteralPath $LogDir -Filter 'GameBoost_*.log' -ErrorAction SilentlyContinue | Where-Object { $_.LastWriteTime -ge $cut } | Sort-Object Name)) {
            foreach ($ln in (Get-Content -LiteralPath $lf.FullName -Encoding UTF8 -ErrorAction SilentlyContinue)) {
                if ($ln -notmatch 'ERREUR|ALERTE|impossible|Impossible|introuvable') { continue }
                $msg = $ln -replace '^\[[^\]]+\]\s*', ''
                $key = $msg -replace '\d+', '#'
                if ($groupsE.Contains($key)) { $groupsE[$key].N++; $groupsE[$key].Last = $ln }
                else { $groupsE[$key] = @{ N = 1; Last = $ln } }
            }
        }
        if ($groupsE.Count -eq 0) { A "Aucune erreur ni alerte." }
        foreach ($k in @($groupsE.Keys | Sort-Object { $groupsE[$_].N } -Descending | Select-Object -First 40)) {
            A ("[x" + $groupsE[$k].N + "] " + $groupsE[$k].Last)
        }
        A ""
        A "===== FIN DU RAPPORT ====="

        $text = $out -join "`r`n"
        # Confidentialite : on retire le nom d'utilisateur Windows des chemins
        $text = [regex]::Replace($text, [regex]::Escape('\Users\' + $env:USERNAME), '\Users\<utilisateur>', 'IgnoreCase')
        $desk = [Environment]::GetFolderPath('Desktop')
        if (-not $desk -or -not (Test-Path -LiteralPath $desk)) { $desk = $LogDir }
        $file = Join-Path $desk ("GameBoost_Rapport_" + (Get-Date -Format "yyyy-MM-dd_HH-mm") + ".txt")
        try { Set-Content -LiteralPath $file -Value $text -Encoding UTF8 -ErrorAction Stop }
        catch {
            # Bureau protege (ex : "Dossiers controles" de Windows Securite) -> dossier des logs
            $desk = $LogDir
            $file = Join-Path $LogDir ("GameBoost_Rapport_" + (Get-Date -Format "yyyy-MM-dd_HH-mm") + ".txt")
            Set-Content -LiteralPath $file -Value $text -Encoding UTF8
        }
        if ($desk -ne $LogDir) { Copy-Item -LiteralPath $file -Destination $LogDir -Force -ErrorAction SilentlyContinue }
        Log ("Rapport pour Claude cree : " + $file)
        try { Start-Process explorer.exe -ArgumentList ('/select,"' + $file + '"') } catch {}
        $where = "sur ton Bureau"; if ($desk -eq $LogDir) { $where = "dans le dossier des logs (le Bureau est protege)" }
        [System.Windows.Forms.MessageBox]::Show(("Rapport cree " + $where + " :`r`n" + [IO.Path]::GetFileName($file) + "`r`n`r`nEnvoie ce fichier a Claude (glisse-le dans la conversation)."), "GameBoost") | Out-Null
    } catch {
        Log ("ERREUR pendant la creation du rapport : " + $_.Exception.Message)
    } finally {
        $btnExport.Enabled = $true
        Update-BoostButton
    }
}

$btnLogs.Add_Click({
