# --- Curseur "niveau gaming" : coche les optimisations du boost, de Leger a Extreme ---------------
# (le mode auto, le lancement au demarrage, la mesure des FPS et le mode comparaison restent a ton choix)
$Script:GameChecks = [ordered]@{ Close = $chkClose; Force = $chkForce; Services = $chkServices; Power = $chkPower; Prio = $chkPrio; Ram = $chkRam; Reopen = $chkReopen
                                 Known = $chkKnown; Dvr = $chkDvr; LowBg = $chkLowBg; Standby = $chkStandby; RP = $chkRP; Gpu = $chkGpu; Plan = $chkPlan
                                 GpuPref = $chkGpuPref; Network = $chkNetwork; Mouse = $chkMouse }
$Script:GameLevels = @(
    @{ L = 'Leger'; C = $cGreen; On = @('Power', 'Prio', 'Dvr', 'Known', 'GpuPref', 'Reopen', 'RP')
       D = "Alimentation au max et priorite au jeu. Rien n'est ferme." },
    @{ L = 'Equilibre'; C = $cCyan; On = @('Power', 'Prio', 'Dvr', 'Known', 'GpuPref', 'Reopen', 'RP', 'Close', 'Services', 'Ram', 'LowBg', 'Gpu')
       D = "+ applis inutiles fermees (rouvertes apres), services en pause, RAM liberee." },
    @{ L = 'Conseille'; C = $cViolet; On = @('Power', 'Prio', 'Dvr', 'Known', 'GpuPref', 'Reopen', 'RP', 'Close', 'Services', 'Ram', 'LowBg', 'Gpu', 'Standby', 'Plan')
       D = "+ anti-saccades et USB / PCIe / processeur au max. Le meilleur choix." },
    @{ L = 'Competitif'; C = $cYellow; On = @('Power', 'Prio', 'Dvr', 'Known', 'GpuPref', 'Reopen', 'RP', 'Close', 'Services', 'Ram', 'LowBg', 'Gpu', 'Standby', 'Plan', 'Mouse', 'Network')
       D = "+ souris sans acceleration et Nagle coupe. Pour le jeu en ligne competitif." },
    @{ L = 'Extreme'; C = $cRed; On = @('Power', 'Prio', 'Dvr', 'Known', 'GpuPref', 'Reopen', 'RP', 'Close', 'Services', 'Ram', 'LowBg', 'Gpu', 'Standby', 'Plan', 'Mouse', 'Network', 'Force')
       D = "+ fermeture FORCEE des applis : le non-sauvegarde est perdu." }
)
