$lblGameCur = New-Label "" 20 ($gameRowTop + 24) 150 18 $fontUI $cMuted
$sldGame = New-GBSlider $form 0 ($Script:GameLevels.Count - 1) 2 @($Script:GameLevels | ForEach-Object { $_.L }) @($Script:GameLevels | ForEach-Object { $_.C }) "" 170 ($gameRowTop + 6) 340
if ($sldGame -isnot [System.Windows.Forms.TrackBar]) { $sldGame.ValueWidth = 110 }
