function Get-GameLevelNow {
    for ($i = $Script:GameLevels.Count - 1; $i -ge 0; $i--) {
        $want = $Script:GameLevels[$i].On; $ok = $true
        foreach ($k in $Script:GameChecks.Keys) {
            $c = $Script:GameChecks[$k]
            if (-not $c.Enabled) { continue }
            if ([bool]$c.Checked -ne ($want -contains $k)) { $ok = $false; break }
        }
        if ($ok) { return $i }
    }
    return -1
}
function Update-GameLevelUI {
    $lv = Get-GameLevelNow
    $v = $lv
    if ($lv -lt 0) {
        # Personnalise : le curseur se place sur le niveau le plus proche
        $best = 0; $bestScore = -1
        for ($i = 0; $i -lt $Script:GameLevels.Count; $i++) {
            $score = 0; foreach ($k in $Script:GameChecks.Keys) { $c = $Script:GameChecks[$k]; if ($c.Enabled -and [bool]$c.Checked -eq ($Script:GameLevels[$i].On -contains $k)) { $score++ } }
            if ($score -gt $bestScore) { $best = $i; $bestScore = $score }
        }
        $v = $best
        $lblGameCur.Text = "personnalise"; $lblGameCur.ForeColor = $cYellow
    } else { $lblGameCur.Text = "niveau actuel"; $lblGameCur.ForeColor = $Script:GameLevels[$lv].C }
    Set-SliderValue $sldGame $v
    $lblGameDesc.Text = $Script:GameLevels[$v].D; $lblGameDesc.ForeColor = $Script:GameLevels[$v].C
    if ($Script:TileLevel) { Update-GBHomeTiles }
}
$sldGame.add_ValueChanged({ $v = [int]$sldGame.Value; $lblGameDesc.Text = $Script:GameLevels[$v].D; $lblGameDesc.ForeColor = $Script:GameLevels[$v].C })
Add-SliderCommit $sldGame {
    $v = [int]$sldGame.Value; $lv = $Script:GameLevels[$v]
    if ($lv.On -contains 'Force') {
        $q = "Niveau Extreme : pendant le boost, les applis ouvertes sont fermees DE FORCE.`r`n`r`nTout ce qui n'est pas enregistre dans ces applis (document, message en cours...) sera perdu. Les apps autorisees ne sont jamais fermees.`r`n`r`nChoisir ce niveau ?"
        if ([System.Windows.Forms.MessageBox]::Show($q, "GameBoost - Niveau gaming", "YesNo", "Warning") -ne "Yes") { Update-GameLevelUI; return }
    }
    $Script:GameLevelApplying = $true
    foreach ($k in $Script:GameChecks.Keys) { $c = $Script:GameChecks[$k]; if ($c.Enabled) { $c.Checked = ($lv.On -contains $k) } }
    $Script:GameLevelApplying = $false
    Sync-ConfigFromUI
    Update-GameLevelUI
    $msg = "Niveau gaming : " + $lv.L
    if ($Script:Boosted) { $msg += " (s'applique au prochain boost)" }
    Log $msg
}
foreach ($c in $Script:GameChecks.Values) { $c.Add_CheckedChanged({ if (-not $Script:GameLevelApplying) { Update-GameLevelUI } }) }

# --- Profils de jeu : un niveau gaming propre a chaque jeu (clic droit dans "Mes jeux") ---
$Script:GameCfgMap = [ordered]@{ Close = 'CloseApps'; Force = 'ForceClose'; Services = 'PauseServices'; Power = 'PowerPlan'; Prio = 'GamePriority'; Ram = 'CleanRam'
                                 Reopen = 'ReopenApps'; Known = 'KnownGames'; Dvr = 'GameDvrOff'; LowBg = 'LowerBackground'; Standby = 'StandbyClean'; RP = 'RestorePoint'
                                 Gpu = 'GpuPriority'; Plan = 'PlanTuning'; GpuPref = 'GpuPreference'; Network = 'NetworkTweak'; Mouse = 'MouseAccelOff' }
function Get-GameProfileLevel($game) {
    foreach ($k in @($Script:Config.GameProfiles.Keys)) { if ($k -ieq [string]$game) { return [int]$Script:Config.GameProfiles[$k] } }
    return $null
}
# Jeu en cours qui a un profil (le premier trouve), sinon $null
function Get-GameProfileFor {
    if (@($Script:Config.GameProfiles.Keys).Count -eq 0) { return $null }
    foreach ($p in @(Get-GameProcesses)) {
        $lv = Get-GameProfileLevel $p.ProcessName
        if ($null -ne $lv -and $lv -ge 0 -and $lv -lt $Script:GameLevels.Count) { return @{ Game = $p.ProcessName; Level = $lv } }
    }
    return $null
}
# Copie de la config avec les optimisations du niveau (le reste - listes, curseurs des engrenages - est garde)
function New-GameProfileConfig($cfg, [int]$level) {
    $c = [ordered]@{}; foreach ($k in @($cfg.Keys)) { $c[$k] = $cfg[$k] }
    $on = $Script:GameLevels[$level].On
    foreach ($k in $Script:GameCfgMap.Keys) {
        if ($k -eq 'GpuPref' -and -not $chkGpuPref.Enabled) { continue }
        $c[$Script:GameCfgMap[$k]] = ($on -contains $k)
    }
    return $c
}
# Liste "Mes jeux" : le profil s'affiche a droite du nom, en couleur
$lstGames.DrawMode = "OwnerDrawFixed"
