$lstGames.add_DrawItem({
    param($sender, $e)
    if ($e.Index -lt 0) { return }
    $sel = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
    $bg = $sender.BackColor; if ($sel) { $bg = $cSel }
    $br = New-Object System.Drawing.SolidBrush($bg); $e.Graphics.FillRectangle($br, $e.Bounds); $br.Dispose()
    if ($sel) { $ba = New-Object System.Drawing.SolidBrush($cCyan); $e.Graphics.FillRectangle($ba, $e.Bounds.X, $e.Bounds.Y + 3, 2, $e.Bounds.Height - 6); $ba.Dispose() }
    $name = [string]$sender.Items[$e.Index]
    $flags = [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis
    $lv = Get-GameProfileLevel $name
    $tag = ""; $tagColor = $cMuted
    if ($null -ne $lv -and $lv -ge 0 -and $lv -lt $Script:GameLevels.Count) { $tag = "profil " + $Script:GameLevels[$lv].L; $tagColor = $Script:GameLevels[$lv].C }
    $tw = 0; if ($tag) { $tw = [System.Windows.Forms.TextRenderer]::MeasureText($tag, $fontUI).Width + 8 }
    $r1 = New-Object System.Drawing.Rectangle(($e.Bounds.X + 10), $e.Bounds.Y, [math]::Max(10, $e.Bounds.Width - $tw - 12), $e.Bounds.Height)
    $fg = $cText; if ($sel) { $fg = $cCyan }
    # Jeu connu : son vrai nom, puis le nom du programme en gris
    $label = Get-GameLabel $name
    if ($label -ne $name) {
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $label, $fontUI, $r1, $fg, $flags)
        $lw = [System.Windows.Forms.TextRenderer]::MeasureText($e.Graphics, $label, $fontUI, $r1.Size, $flags).Width
        if ($lw + 40 -lt $r1.Width) {
            $r3 = New-Object System.Drawing.Rectangle(($r1.X + $lw + 6), $r1.Y, ($r1.Width - $lw - 6), $r1.Height)
            [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, ($name + ".exe"), $fontSmall, $r3, $cMuted, $flags)
        }
    } else { [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $name, $fontUI, $r1, $fg, $flags) }
    if ($tag) {
        $r2 = New-Object System.Drawing.Rectangle(($e.Bounds.Right - $tw), $e.Bounds.Y, ($tw - 4), $e.Bounds.Height)
        [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $tag, $fontUI, $r2, $tagColor, ($flags -bor [System.Windows.Forms.TextFormatFlags]::Right))
    }
})
