# --- Menu de l'icone pres de l'horloge (clic droit) : rempli a chaque ouverture ----------------------
# Ouvrir, boost, luminosite, ecrans (eteindre / rallumer), limite de FPS, option de la croix, quitter
$trayMenu = New-Object System.Windows.Forms.ContextMenuStrip
$trayMenu.Font = $fontUI
function Add-GBTrayItem($parent, [string]$text, [scriptblock]$run = $null, $arg = $null, [bool]$checked = $false, [bool]$enabled = $true) {
    $it = New-Object System.Windows.Forms.ToolStripMenuItem($text)
    $it.Checked = $checked; $it.Enabled = $enabled
    if ($run) {
        $it.Tag = @{ Run = $run; Arg = $arg }
        $it.Add_Click({ $t = $this.Tag; try { & $t.Run $t.Arg } catch { try { Log ("Menu de l'icone : " + $_.Exception.Message) } catch {} } })
    }
    if ($parent -is [System.Windows.Forms.ToolStripMenuItem]) {
        if ($Script:TrayRenderer) { $parent.DropDown.Renderer = $Script:TrayRenderer }
        [void]$parent.DropDownItems.Add($it)
    } else { [void]$parent.Items.Add($it) }
    return $it
}
function Add-GBTraySep($parent) {
    $sp = New-Object System.Windows.Forms.ToolStripSeparator
    if ($parent -is [System.Windows.Forms.ToolStripMenuItem]) { [void]$parent.DropDownItems.Add($sp) } else { [void]$parent.Items.Add($sp) }
}
# Luminosite d'un ecran depuis le menu : valeur fixe (Pct) ou pas (+/- Step)
$Script:TrayBrightRun = {
    param($a)
    $p = $a.Pct
    if ($null -ne $a.Step) { $c = Get-GBBrightness $a.T; if ($c -lt 0) { Log ("Luminosite : " + $a.T.Label + " pas encore lue, reessaie dans un instant"); return }; $p = $c + $a.Step }
    if (Set-GBBrightness $a.T ([int]$p)) { if ($Script:DispCard) { Update-GBDisplayCard -Soon } }
}
function Add-GBTrayBright($parent, $t) {
    $cur = Get-GBBrightness $t
    if ($cur -ge 0) { $parent.Text = $parent.Text + "  (" + $cur + " %)" }
    foreach ($p in @(100, 75, 50, 25, 10)) {
        $ok = ($cur -ge 0 -and [math]::Abs($cur - $p) -le 2)
        [void](Add-GBTrayItem $parent ("" + $p + " %") $Script:TrayBrightRun @{ T = $t; Pct = $p } $ok)
    }
    Add-GBTraySep $parent
    [void](Add-GBTrayItem $parent "Plus clair (+10 %)" $Script:TrayBrightRun @{ T = $t; Step = 10 })
    [void](Add-GBTrayItem $parent "Plus sombre (-10 %)" $Script:TrayBrightRun @{ T = $t; Step = -10 })
}
function Update-GBTrayMenu {
    $m = $trayMenu
    if ($null -eq $Script:TrayRenderer) { $Script:TrayRenderer = $false; try { $r = Get-GBMenuRenderer; if ($r) { $Script:TrayRenderer = $r } } catch {} }
    if ($Script:TrayRenderer) { $m.Renderer = $Script:TrayRenderer }
    $old = @($m.Items); $m.Items.Clear(); foreach ($o in $old) { try { $o.Dispose() } catch {} }

    $op = Add-GBTrayItem $m "Ouvrir GameBoost" { Open-GBMainFromTray 'menu' }
    $op.Font = New-Object System.Drawing.Font($m.Font, [System.Drawing.FontStyle]::Bold)
    Add-GBTraySep $m
    $bt = $(if ($Script:Boosted) { "Arreter le boost" } else { "BOOST : lancer le mode jeu" })
    [void](Add-GBTrayItem $m $bt { Switch-BoostManual } $null ([bool]$Script:Boosted))

    # Luminosite : un sous-menu par ecran reglable (lecture DDC lancee en fond si pas encore connue)
    $bts = @(); try { $bts = @(Get-GBBrightTargets | Where-Object { $_.Kind }) } catch {}
    try {
        $unk = @($bts | Where-Object { $_.Kind -eq 'ddc' -and [GBMon]::LumKnown($_.Device) -eq -2 } | ForEach-Object { [string]$_.Device })
        if ($unk.Count) { [GBMon]::ProbeLumAsync([string[]]$unk) }
    } catch {}
    if ($bts.Count -eq 0) { [void](Add-GBTrayItem $m "Luminosite : aucun ecran reglable" $null $null $false $false) }
    elseif ($bts.Count -eq 1) { $lm = Add-GBTrayItem $m "Luminosite"; Add-GBTrayBright $lm $bts[0] }
    else {
        $lm = Add-GBTrayItem $m "Luminosite"
        foreach ($t in $bts) { $sm = Add-GBTrayItem $lm ([string]$t.Label); Add-GBTrayBright $sm $t }
    }

    # Ecrans : eteindre / rallumer chacun, tout rallumer
    $mons = @(); try { $mons = @(Get-GBMonitors -NoDdc) } catch {}
    if ($mons.Count -gt 0 -and (Test-Path function:Switch-GBMonitor)) {
        $em = Add-GBTrayItem $m "Ecrans"
        foreach ($mo in $mons) {
            $lab = $(if ($mo.Off) { "Rallumer : " } else { "Eteindre : " }) + $mo.Index + " - " + $mo.Name
            if ($mo.Internal) { $lab += " (portable)" }
            [void](Add-GBTrayItem $em $lab { param($i) [void](Switch-GBMonitor $i) } ([int]$mo.Index) ([bool]$mo.Off))
        }
        if (@($mons | Where-Object { $_.Off }).Count -gt 0) {
            Add-GBTraySep $em
            [void](Add-GBTrayItem $em "Tout rallumer" { [void](Restore-GBAllMonitors) })
        }
    }

    # Limite de FPS (pilote NVIDIA)
    if (Test-Path function:Get-GBFpsCapInfo) {
        $fi = $null; try { $fi = Get-GBFpsCapInfo } catch {}
        if ($fi -and $fi.Ok) {
            $fm = Add-GBTrayItem $m ("Limite de FPS" + $(if ([int]$fi.Value -gt 0) { "  (" + $fi.Value + ")" } else { "" }))
            $ch = @($Script:FpsChoices)
            if ([int]$fi.Value -gt 0 -and $ch -notcontains [int]$fi.Value) { $ch = @($ch + [int]$fi.Value | Sort-Object) }
            foreach ($n in $ch) {
                $lab = $(if ($n -eq 0) { "Aucune limite" } else { "" + $n + " FPS" })
                [void](Add-GBTrayItem $fm $lab {
                    param($n)
                    if (-not (Set-GBFpsCap $n)) { $tray.ShowBalloonTip(3000, "GameBoost", "Limite de FPS refusee par le pilote NVIDIA (droits administrateur ?).", [System.Windows.Forms.ToolTipIcon]::Warning) }
                    if ($Script:DispCard) { Update-GBDisplayCard -KeepScreen }
                } $n ([int]$fi.Value -eq $n))
            }
        }
    }

    Add-GBTraySep $m
    [void](Add-GBTrayItem $m "La croix range GameBoost ici" { $Script:Config.CloseToTray = -not [bool]$Script:Config.CloseToTray; Save-Config } $null ([bool]$Script:Config.CloseToTray))
    [void](Add-GBTrayItem $m "Quitter (tout est remis comme avant)" { Exit-GBApp })
}
$trayMenu.Add_Opening({ try { Update-GBTrayMenu } catch { try { Log ("Menu de l'icone : " + $_.Exception.Message) } catch {} } })
# (Opening ne se declenche pas sur un menu vide : une entree de depart)
[void]$trayMenu.Items.Add("Ouvrir GameBoost")
# (le menu ci-dessus ne sert plus qu'en secours : le clic droit ouvre le panneau rapide ci-dessous)

# --- Panneau rapide de l'icone (clic droit) : tout se regle directement, sans sous-menu ------------------
# Ouvrir, BOOST, un curseur de luminosite par ecran, eteindre / rallumer chaque ecran, limite de FPS en un clic,
# option de la croix, Quitter. Se ferme en cliquant ailleurs ou avec Echap.
function Get-TPS($v) { return [int][math]::Round([double]$v * [double]$Script:TrayK) }
function New-GBTrayBtn($p, [string]$text, $x, $y, $w, $h, $color, [scriptblock]$click, $tag = $null) {
    $b = New-GBButtonCtl; $b.Text = $text; $b.Font = $fontUI; $b.ForeColor = $color; $b.BackColor = $cPanel
    $b.Location = New-Object System.Drawing.Point((Get-TPS $x), (Get-TPS $y)); $b.Size = New-Object System.Drawing.Size((Get-TPS $w), (Get-TPS $h))
    $b.Tag = @{ Run = $click; Arg = $tag }; $b.TabStop = $false
    $b.Add_Click({
        $t = $this.Tag; $Script:TrayPanelBusy = $true
        try { & $t.Run $t.Arg } catch { try { Log ("Panneau de l'icone : " + $_.Exception.Message) } catch {} }
        $Script:TrayPanelBusy = $false
        # Mise a jour du panneau juste apres le clic (pas pendant : le bouton clique serait detruit sous la souris)
        if (-not $Script:TrayRebuildT) {
            $Script:TrayRebuildT = New-Object System.Windows.Forms.Timer; $Script:TrayRebuildT.Interval = 40
            $Script:TrayRebuildT.Add_Tick({ $Script:TrayRebuildT.Stop(); try { if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed -and $Script:TrayPanel.Visible) { Build-GBTrayPanel; $Script:TrayPanel.Activate() } } catch { try { Log ("Panneau de l'icone : " + $_.Exception.Message) } catch {} } })
        }
        $Script:TrayRebuildT.Stop(); $Script:TrayRebuildT.Start()
    })
    $p.Controls.Add($b); return $b
}
function New-GBTrayHead($p, [string]$text, $y) { [void](New-GBLabelIn $p $text (Get-TPS 14) (Get-TPS $y) (Get-TPS 284) (Get-TPS 18) $fontSmall $cMuted) }
# Cases CPU / GPU / RAM du panneau : derniere mesure (toutes les 5 s) + capteurs (temperatures, cache 6 s)
function Update-GBTrayStats {
    $st = $Script:TrayStats; if (-not $st -or -not $st.CPU -or $st.CPU.Val.IsDisposed) { return }
    $s = $Script:LastSample
    if (-not $s) { try { $s = Get-SystemSnapshot } catch {} }
    $se = $null; try { $se = Get-GBSensors } catch {}
    $pct = { param($v) if ($null -eq $v) { "--" } else { "" + [int][math]::Round([double]$v) + " %" } }
    $set = {
        param($k, $v, $t, $kind, $pre)
        $st[$k].Val.Text = & $pct $v
        if ($null -ne $t) {
            $st[$k].Temp.Text = $pre + (Format-GBTemp $t -NoUnit) + [char]0xB0
            $st[$k].Temp.ForeColor = Get-GBTempColor (Get-GBTempLevel $t $kind)
        } else { $st[$k].Temp.Text = "" }
    }
    $ct = $null; $gt = $null; $dt = $null
    if ($se) {
        $ct = $se.CpuTemp; $gt = $se.GpuTemp
        $hot = @($se.SsdTemps | Where-Object { $null -ne $_.Temp } | Sort-Object { $_.Temp } -Descending | Select-Object -First 1)
        if ($hot.Count) { $dt = $hot[0].Temp }
    }
    & $set 'CPU' $(if ($s) { $s.Cpu }) $ct 'cpu' ''
    & $set 'GPU' $(if ($s) { $s.Gpu }) $gt 'gpu' ''
    & $set 'RAM' $(if ($s) { $s.RamPct }) $null 'ssd' ''
}
function Build-GBTrayPanel {
    $p = $Script:TrayPanel; if (-not $p -or $p.IsDisposed) { return }
    $Script:TrayK = 1.0; if ($Script:DpiScale) { $Script:TrayK = [double]$Script:DpiScale }
    $acc = $cCyan; if ($cAccent) { $acc = $cAccent }
    $p.SuspendLayout()
    $old = @($p.Controls); $p.Controls.Clear(); foreach ($o in $old) { try { $o.Dispose() } catch {} }
    $W = 312; $L = 14; $IW = $W - 2 * $L; $y = 12

    # En-tete : nom + etat, bouton Ouvrir
    [void](New-GBLabelIn $p "GameBoost" (Get-TPS $L) (Get-TPS $y) (Get-TPS 150) (Get-TPS 22) $fontBold $cText)
    $st = $(if ($Script:Boosted) { "Boost actif" } else { "Pret" })
    [void](New-GBLabelIn $p $st (Get-TPS $L) (Get-TPS ($y + 21)) (Get-TPS 150) (Get-TPS 18) $fontSmall $(if ($Script:Boosted) { $cGreen } else { $cMuted }))
    [void](New-GBTrayBtn $p "Ouvrir" ($L + $IW - 86) ($y + 4) 86 30 $acc { Open-GBMainFromTray 'panneau' })
    $y += 48

    # Recherche : ecris ton besoin, Entree (ou Chercher) ouvre les resultats
    if (Test-Path function:Show-GBSearch) {
        $sb = New-Object System.Windows.Forms.TextBox
        $sb.BackColor = $cDeep; $sb.ForeColor = $cText; $sb.BorderStyle = "FixedSingle"; $sb.Font = $fontUI
        $sb.Location = New-Object System.Drawing.Point((Get-TPS $L), (Get-TPS ($y + 2))); $sb.Size = New-Object System.Drawing.Size((Get-TPS ($IW - 92)), (Get-TPS 26))
        $p.Controls.Add($sb); $Script:TraySearchBox = $sb
        $sb.Add_KeyDown({ if ($_.KeyCode -eq 'Return') { $_.Handled = $true; $_.SuppressKeyPress = $true; Open-GBSearchFromTray } })
        try { if ($tip) { $tip.SetToolTip($sb, "Ecris ce que tu cherches : mon jeu rame, pc trop chaud, micro, fps...") } } catch {}
        [void](New-GBTrayBtn $p "Chercher" ($L + $IW - 86) $y 86 30 $acc { Open-GBSearchFromTray })
        $y += 40
    }

    # Etat du PC : 3 petites cases (utilisation en % + temperature en couleur), mises a jour toutes les 2 s
    $Script:TrayStats = @{}
    $gap = 6; $tw = [int](($IW - 2 * $gap) / 3)
    $i = 0
    foreach ($k in @('CPU', 'GPU', 'RAM')) {
        $bx = New-Object System.Windows.Forms.Panel; $bx.BackColor = $cDeep
        $bx.Location = New-Object System.Drawing.Point((Get-TPS ($L + $i * ($tw + $gap))), (Get-TPS $y)); $bx.Size = New-Object System.Drawing.Size((Get-TPS $tw), (Get-TPS 46))
        $p.Controls.Add($bx)
        $nm = New-GBLabelIn $bx $k (Get-TPS 8) (Get-TPS 5) (Get-TPS 34) (Get-TPS 16) $fontSmall $cMuted; $nm.BackColor = $cDeep
        $tp = New-GBLabelIn $bx "" (Get-TPS 44) (Get-TPS 5) (Get-TPS ($tw - 50)) (Get-TPS 16) $fontSmall $cMuted; $tp.BackColor = $cDeep; $tp.TextAlign = 'TopRight'
        $vl = New-GBLabelIn $bx "--" (Get-TPS 8) (Get-TPS 21) (Get-TPS ($tw - 14)) (Get-TPS 22) $fontBold $cText; $vl.BackColor = $cDeep
        $Script:TrayStats[$k] = @{ Val = $vl; Temp = $tp }
        $i++
    }
    $y += 56
    Update-GBTrayStats

    # BOOST
    $bt = $(if ($Script:Boosted) { "ARRETER LE BOOST" } else { "BOOST" })
    $bb = New-GBTrayBtn $p $bt $L $y $IW 42 $(if ($Script:Boosted) { $cRed } else { $cGreen }) { Switch-BoostManual }
    $bb.Font = $fontBold
    $y += 54

    # Luminosite : un curseur par ecran reglable
    New-GBTrayHead $p "LUMINOSITE" $y; $y += 20
    $bts = @(); try { $bts = @(Get-GBBrightTargets) } catch {}
    $Script:TraySliders = New-Object System.Collections.ArrayList
    if ($bts.Count -eq 0) { [void](New-GBLabelIn $p "Aucun ecran detecte" (Get-TPS $L) (Get-TPS $y) (Get-TPS $IW) (Get-TPS 18) $fontUI $cMuted); $y += 24 }
    foreach ($t in $bts) {
        $nm = New-GBLabelIn $p ([string]$t.Label) (Get-TPS $L) (Get-TPS $y) (Get-TPS $IW) (Get-TPS 18) $fontUI $cText; $nm.AutoEllipsis = $true
        $y += 19
        if (-not $t.Kind) { [void](New-GBLabelIn $p "Se regle avec les boutons de l'ecran" (Get-TPS $L) (Get-TPS $y) (Get-TPS $IW) (Get-TPS 18) $fontSmall $cMuted); $y += 24; continue }
        $cur = Get-GBBrightness $t
        if ($cur -eq -2) { try { [GBMon]::ProbeLumAsync([string[]]@([string]$t.Device)) } catch {} }
        $s = New-GBSlider $p 0 100 ([math]::Max(0, $cur)) $null $null " %" (Get-TPS $L) (Get-TPS ($y - 2)) (Get-TPS $IW)
        $s.Height = Get-TPS 30
        if ($s -isnot [System.Windows.Forms.TrackBar]) { $s.ValueWidth = Get-TPS 56; $s.StepWheel = 5; $s.StepKey = 5; $s.FillColor = $acc }
        $s.Tag = $t; $s.Enabled = ($cur -ge 0)
        Add-SliderCommit $s { $t = $this.Tag; if (Set-GBBrightness $t ([int]$this.Value)) { if ($Script:DispCard) { Update-GBDisplayCard -Soon } } }
        if ($cur -lt 0) { [void]$Script:TraySliders.Add($s) }
        $y += 34
    }

    # Ecrans : eteindre / rallumer chacun
    $mons = @(); try { $mons = @(Get-GBMonitors -NoDdc) } catch {}
    if ($mons.Count -gt 0 -and (Test-Path function:Switch-GBMonitor)) {
        $y += 2; New-GBTrayHead $p "ECRANS" $y; $y += 20
        foreach ($mo in $mons) {
            $lab = "" + $mo.Index + " - " + $mo.Name; if ($mo.Internal) { $lab += " (portable)" }
            $nm = New-GBLabelIn $p $lab (Get-TPS $L) (Get-TPS ($y + 5)) (Get-TPS ($IW - 104)) (Get-TPS 18) $fontUI $(if ($mo.Off) { $cMuted } else { $cText }); $nm.AutoEllipsis = $true
            [void](New-GBTrayBtn $p $(if ($mo.Off) { "Rallumer" } else { "Eteindre" }) ($L + $IW - 96) $y 96 28 $(if ($mo.Off) { $cGreen } else { $cYellow }) { param($i) [void](Switch-GBMonitor $i) } ([int]$mo.Index))
            $y += 34
        }
        if (@($mons | Where-Object { $_.Off }).Count -gt 1) { [void](New-GBTrayBtn $p "Tout rallumer" $L $y $IW 28 $cGreen { [void](Restore-GBAllMonitors) }); $y += 34 }
    }

    # Limite de FPS : une pastille par valeur, la valeur actuelle en couleur
    if (Test-Path function:Get-GBFpsCapInfo) {
        $fi = $null; try { $fi = Get-GBFpsCapInfo } catch {}
        $y += 2; New-GBTrayHead $p "LIMITE DE FPS (jeux NVIDIA)" $y; $y += 20
        if ($fi -and $fi.Ok) {
            $ch = @($Script:FpsChoices)
            if ([int]$fi.Value -gt 0 -and $ch -notcontains [int]$fi.Value) { $ch = @($ch + [int]$fi.Value | Sort-Object) }
            $per = 4; $gap = 6; $cw = [int](($IW - ($per - 1) * $gap) / $per); $k = 0
            foreach ($n in $ch) {
                $on = ([int]$fi.Value -eq $n)
                $b = New-GBTrayBtn $p $(if ($n -eq 0) { "Aucune" } else { "" + $n }) ($L + ($k % $per) * ($cw + $gap)) $y $cw 28 $(if ($on) { $acc } else { $cMuted }) {
                    param($n)
                    if (-not (Set-GBFpsCap $n)) { $tray.ShowBalloonTip(3000, "GameBoost", "Limite de FPS refusee par le pilote NVIDIA (droits administrateur ?).", [System.Windows.Forms.ToolTipIcon]::Warning) }
                    if ($Script:DispCard) { Update-GBDisplayCard -KeepScreen }
                } $n
                if ($on) { $b.Font = $fontBold }
                $k++; if ($k % $per -eq 0) { $y += 34 }
            }
            if ($k % $per -ne 0) { $y += 34 }
        } else {
            $why = "Indisponible"; if ($fi -and $fi.Why) { $why = [string]$fi.Why }
            $wl = New-GBLabelIn $p $why (Get-TPS $L) (Get-TPS $y) (Get-TPS $IW) (Get-TPS 34) $fontSmall $cMuted; $y += 38
        }
    }

    # Pied : option de la croix + Quitter
    $ln = New-Object System.Windows.Forms.Panel; $ln.BackColor = $cLine
    $ln.Location = New-Object System.Drawing.Point((Get-TPS $L), (Get-TPS ($y + 2))); $ln.Size = New-Object System.Drawing.Size((Get-TPS $IW), 1); $p.Controls.Add($ln)
    $y += 10
    $cb = New-Object System.Windows.Forms.CheckBox
    $cb.Text = "La croix range GameBoost ici"; $cb.Font = $fontSmall; $cb.ForeColor = $cMuted; $cb.BackColor = $cPanel; $cb.FlatStyle = 'Flat'; $cb.TabStop = $false
    $cb.Checked = [bool]$Script:Config.CloseToTray
    $cb.Location = New-Object System.Drawing.Point((Get-TPS $L), (Get-TPS ($y + 4))); $cb.Size = New-Object System.Drawing.Size((Get-TPS ($IW - 92)), (Get-TPS 22))
    $cb.Add_CheckedChanged({ $Script:Config.CloseToTray = [bool]$this.Checked; Save-Config })
    $p.Controls.Add($cb)
    [void](New-GBTrayBtn $p "Quitter" ($L + $IW - 84) $y 84 28 $cRed { $Script:TrayPanel.Close(); Exit-GBApp })
    $y += 40

    $p.ClientSize = New-Object System.Drawing.Size((Get-TPS $W), (Get-TPS $y))
    $p.ResumeLayout()
    Set-GBTrayPanelPlace
    # Ecrans externes encore en lecture (DDC) : curseur active des que la valeur arrive
    if ($Script:TraySliders.Count -gt 0) {
        if (-not $Script:TrayProbeT) {
            $Script:TrayProbeT = New-Object System.Windows.Forms.Timer; $Script:TrayProbeT.Interval = 400
            $Script:TrayProbeT.Add_Tick({
                $Script:TrayProbeN++
                foreach ($s in @($Script:TraySliders)) {
                    if ($s.IsDisposed) { $Script:TraySliders.Remove($s); continue }
                    $v = Get-GBBrightness $s.Tag
                    if ($v -ge 0) { Set-SliderValue $s $v; $s.Enabled = $true; $Script:TraySliders.Remove($s) }
                    elseif ($v -eq -1 -or $Script:TrayProbeN -gt 15) { $s.Enabled = $false; $Script:TraySliders.Remove($s) }
                }
                if ($Script:TraySliders.Count -eq 0) { $Script:TrayProbeT.Stop() }
            })
        }
        $Script:TrayProbeN = 0; $Script:TrayProbeT.Start()
    }
}
# Pres de l'icone : au-dessus de la barre des taches, sous la souris, jamais hors de l'ecran
function Set-GBTrayPanelPlace {
    $p = $Script:TrayPanel; if (-not $p -or $p.IsDisposed) { return }
    $pt = [System.Windows.Forms.Cursor]::Position
    if ($Script:TrayAnchor) { $pt = $Script:TrayAnchor }
    $wa = [System.Windows.Forms.Screen]::FromPoint($pt).WorkingArea
    $m = Get-TPS 10
    $x = [math]::Min($pt.X - [int]($p.Width / 2), $wa.Right - $p.Width - $m); $x = [math]::Max($wa.Left + $m, $x)
    $y = [math]::Min($pt.Y - $p.Height - $m, $wa.Bottom - $p.Height - $m); $y = [math]::Max($wa.Top + $m, $y)
    $p.Location = New-Object System.Drawing.Point([int]$x, [int]$y)
}
# Fenetre des icones cachees (fleche ^ de la barre des taches) : si elle est encore ouverte quand le panneau
# s'affiche, elle avale le premier clic dans le panneau ("Ouvrir" ne faisait rien). On la ferme d'abord comme
# l'utilisateur le ferait (touche Echap), puis le panneau s'ouvre.
$trayFlySrc = @'
using System; using System.Text; using System.Runtime.InteropServices;
public static class GBTrayFly {
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] static extern IntPtr GetAncestor(IntPtr h, uint flags);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern int GetClassName(IntPtr h, StringBuilder s, int n);
    [DllImport("user32.dll")] static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);
    public static string ForegroundClass() {
        IntPtr h = GetForegroundWindow(); if (h == IntPtr.Zero) return "";
        IntPtr r = GetAncestor(h, 2); if (r != IntPtr.Zero) h = r;
        StringBuilder s = new StringBuilder(256); GetClassName(h, s, 256); return s.ToString();
    }
    public static bool OverflowOpen() {
        string c = ForegroundClass();
        return c == "TopLevelWindowForOverflowXamlIsland" || c == "NotifyIconOverflowWindow";
    }
    public static void Escape() { keybd_event(0x1B, 0, 0, UIntPtr.Zero); keybd_event(0x1B, 0, 2, UIntPtr.Zero); }
}
'@
function Close-GBTrayOverflow {
    if ($null -eq $Script:TrayFlyOK) { $Script:TrayFlyOK = $false; try { $Script:TrayFlyOK = [bool](Add-GBCompiled 'GBTrayFly' $trayFlySrc $null 'GBTrayFly') } catch {} }
    if (-not $Script:TrayFlyOK) { return $false }
    try { if ([GBTrayFly]::OverflowOpen()) { [GBTrayFly]::Escape(); return $true } } catch {}
    return $false
}
# -Corner (raccourci clavier) : en bas a droite de l'ecran principal, la ou se trouve l'icone
function Show-GBTrayPanel([switch]$Corner, [switch]$AfterFly) {
    if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed) { $Script:TrayPanel.Close(); return }
    # (clic sur l'icone juste apres une fermeture par clic ailleurs : on ne rouvre pas)
    if (-not $Corner -and -not $AfterFly -and $Script:TrayPanelClosedAt -and ((Get-Date) - $Script:TrayPanelClosedAt).TotalMilliseconds -lt 250) { return }
    # Icone derriere la fleche ^ : la fenetre des icones cachees se ferme d'abord, le panneau s'ouvre 150 ms apres
    if (-not $Corner -and -not $AfterFly) {
        $Script:TrayFlyAnchor = [System.Windows.Forms.Cursor]::Position
        if (Close-GBTrayOverflow) {
            if (-not $Script:TrayFlyT) {
                $Script:TrayFlyT = New-Object System.Windows.Forms.Timer; $Script:TrayFlyT.Interval = 150
                $Script:TrayFlyT.Add_Tick({ $Script:TrayFlyT.Stop(); try { Show-GBTrayPanel -AfterFly } catch { try { Log ("Panneau de l'icone : " + $_.Exception.Message) } catch {} } })
            }
            $Script:TrayFlyT.Stop(); $Script:TrayFlyT.Start(); return
        }
    }
    $p = New-Object System.Windows.Forms.Form
    $p.FormBorderStyle = 'None'; $p.ShowInTaskbar = $false; $p.TopMost = $true; $p.StartPosition = 'Manual'
    $p.AutoScaleMode = 'None'; $p.KeyPreview = $true; $p.Text = "GameBoost"
    $p.BackColor = $cPanel; $p.ForeColor = $cText; $p.Font = $fontUI; $p.Opacity = 0
    if ($Script:UiOK) { try { [GBTheme]::DoubleBuffer($p) } catch {} }
    $p.Add_Paint({ param($s, $e) $pen = New-Object System.Drawing.Pen($cLine); $e.Graphics.DrawRectangle($pen, 0, 0, $s.ClientSize.Width - 1, $s.ClientSize.Height - 1); $pen.Dispose() })
    $p.Add_KeyDown({ param($s, $e) if ($e.KeyCode -eq [System.Windows.Forms.Keys]::Escape) { $s.Close() } })
    # Perte du premier plan : on attend 300 ms. Icone derriere la fleche ^ de la barre des taches : la fenetre des
    # icones cachees se referme au premier clic dans le panneau et rend la main a l'explorateur un instant ;
    # si la souris est sur le panneau, c'est un clic DANS le panneau : on le garde (et on le remet devant).
    $p.Add_Deactivate({
        if ($Script:TrayPanelBusy) { return }
        if (-not $Script:TrayDeactT) {
            $Script:TrayDeactT = New-Object System.Windows.Forms.Timer; $Script:TrayDeactT.Interval = 300
            $Script:TrayDeactT.Add_Tick({
                $Script:TrayDeactT.Stop()
                $tp = $Script:TrayPanel
                if (-not $tp -or $tp.IsDisposed -or -not $tp.Visible -or $Script:TrayPanelBusy) { return }
                if ([System.Windows.Forms.Form]::ActiveForm -eq $tp) { return }
                if ($tp.Bounds.Contains([System.Windows.Forms.Cursor]::Position)) { try { $tp.Activate(); if ($Script:UiOK) { [void][GBTheme]::ShowFront($tp) } } catch {}; return }
                try { $tp.Close() } catch {}
            })
        }
        $Script:TrayDeactT.Stop(); $Script:TrayDeactT.Start()
    })
    $p.Add_FormClosed({
        $Script:TrayPanel = $null; $Script:TrayPanelClosedAt = Get-Date
        try { if ($Script:TrayProbeT) { $Script:TrayProbeT.Stop() } } catch {}
        try { if ($Script:TrayStatsT) { $Script:TrayStatsT.Stop() } } catch {}
    })
    if (-not $Script:TrayStatsT) {
        $Script:TrayStatsT = New-Object System.Windows.Forms.Timer; $Script:TrayStatsT.Interval = 2000
        $Script:TrayStatsT.Add_Tick({ try { Update-GBTrayStats } catch {} })
    }
    $Script:TrayStatsT.Start()
    $Script:TrayPanel = $p; $Script:TrayAnchor = [System.Windows.Forms.Cursor]::Position
    if ($AfterFly -and $Script:TrayFlyAnchor) { $Script:TrayAnchor = $Script:TrayFlyAnchor }
    if ($Corner) { $wa = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea; $Script:TrayAnchor = New-Object System.Drawing.Point(($wa.Right - 1), ($wa.Bottom - 1)) }
    Build-GBTrayPanel
    $p.Show(); $p.Activate()
    if ($Script:UiOK) { try { [void][GBTheme]::ShowFront($p) } catch {} }   # (raccourci : un autre programme est devant)
    # Apparition courte (fondu de 120 ms) : le panneau arrive sans sauter aux yeux
    $ft = New-Object System.Windows.Forms.Timer; $ft.Interval = 15; $ft.Tag = $p
    $ft.Add_Tick({ $f = $this.Tag; if (-not $f -or $f.IsDisposed) { $this.Stop(); $this.Dispose(); return }; $f.Opacity = [math]::Min(1.0, $f.Opacity + 0.15); if ($f.Opacity -ge 1.0) { $this.Stop(); $this.Dispose() } })
    $ft.Start()
}
# Clic droit sur l'icone : panneau rapide (menu classique en secours si le panneau echoue)
$tray.Add_MouseUp({
    param($s, $e)
    if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Right) { return }
    try { Show-GBTrayPanel }
    catch {
        try { Log ("Panneau de l'icone : " + $_.Exception.Message) } catch {}
        try { if ($Script:TrayPanel) { $Script:TrayPanel.Close() } } catch {}
        try { Update-GBTrayMenu; $trayMenu.Show([System.Windows.Forms.Cursor]::Position) } catch {}
    }
})

$chkAuto.Add_CheckedChanged({ Sync-ConfigFromUI; Update-BoostButton })

# Surveillance toutes les 3 secondes
$timer = New-Object System.Windows.Forms.Timer
$timer.Interval = 3000
$Script:LastTickError = ""
$timer.Add_Tick({
  if ($Script:BusyDepth -gt 0) { return }
  try {
    Apply-AppPriorityRules
    $running = Get-GameProcesses
    if ($running.Count -eq 0) { $Script:ManualStop = $false }   # jeu ferme : le mode auto pourra reservir au prochain lancement
    if (-not $Script:Boosted) {
        if ($chkAuto.Checked -and $running.Count -gt 0 -and -not $Script:ManualStop) {
            Log ("Jeu detecte : " + (Get-GameLabel $running[0].ProcessName))
            Invoke-Boost $true
        }
    } else {
        if ($running.Count -gt 0) {
            if ($Script:SessionGame -like '(*') { $Script:SessionGame = (Get-GameLabel $running[0].ProcessName); Log ("Jeu detecte : " + $Script:SessionGame) }
            Apply-GamePriority
            Apply-GpuPreference
            Start-FpsCapture
        }
        elseif ($Script:AutoBoosted) { Log "Jeu ferme"; Invoke-Restore }
    }
  } catch {
    $m = $_.Exception.Message
    if ($m -ne $Script:LastTickError) { Log ("Erreur de surveillance : " + $m); $Script:LastTickError = $m }
  }
})

# Mesure des performances toutes les 5 secondes
$monTimer = New-Object System.Windows.Forms.Timer
$monTimer.Interval = 5000
$monTimer.Add_Tick({ Take-Sample })

# Clic gauche sur l'icone : ouvre GameBoost (clic droit : menu rapide)
$tray.Add_MouseClick({ param($s, $e) if ($e.Button -eq [System.Windows.Forms.MouseButtons]::Left) { Open-GBMainFromTray 'clic sur l''icone' } })
$Script:OpeningFront = (-not $Minimized)
$form.Add_Resize({
    if ($form.WindowState -ne "Minimized") { return }
    if ($Script:OpeningFront) { return }   # ouverture : la fenetre doit s'afficher, pas partir pres de l'horloge
    $form.Hide(); $tray.ShowBalloonTip(1500, "GameBoost", "GameBoost tourne en arriere-plan.", [System.Windows.Forms.ToolTipIcon]::Info)
})
# Ouvrir depuis l'icone (panneau, menu, clic gauche) : 3 essais (0, 150, 400 ms) comme au demarrage, car Windows
# peut refuser le premier plan a une appli en administrateur ; une ligne dans le journal dit ce qui s'est passe
function Open-GBMainFromTray([string]$From = 'icone') {
    $Script:OpenFrom = $From
    # la fenetre passe devant AVANT de cacher le panneau (le panneau qui disparait rendrait le premier plan a un autre programme)
    try { if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed) { $Script:TrayPanelBusy = $true } } catch {}
    try { Show-GBMainFront } catch { try { Log ("Ouvrir (" + $From + ") : " + $_.Exception.Message) } catch {} }
    try { if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed) { $Script:TrayPanel.Hide() } } catch {}
    if (-not $Script:OpenT) {
        $Script:OpenT = New-Object System.Windows.Forms.Timer
        $Script:OpenT.Add_Tick({
            $Script:OpenTries++
            $front = ([System.Windows.Forms.Form]::ActiveForm -eq $form -or ($Script:UiOK -and [GBTheme]::IsFront($form)))
            if (-not $form.Visible -or $form.WindowState -eq 'Minimized' -or -not $front) { try { Show-GBMainFront } catch {} }
            if ($Script:OpenTries -eq 1) { $Script:OpenT.Interval = 250; return }
            $Script:OpenT.Stop()
            try { if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed) { $Script:TrayPanelBusy = $false; $Script:TrayPanel.Close() } } catch {}
            $front = ([System.Windows.Forms.Form]::ActiveForm -eq $form -or ($Script:UiOK -and [GBTheme]::IsFront($form)))
            if (-not $form.Visible -or -not $front) {
                try { Log ("Ouvrir (" + $Script:OpenFrom + ") : fenetre visible=" + $form.Visible + " etat=" + $form.WindowState + " place=" + $form.Bounds + " devant=" + $front) } catch {}
            }
        })
    }
    $Script:OpenTries = 0; $Script:OpenT.Interval = 150; $Script:OpenT.Stop(); $Script:OpenT.Start()
}
# Ouverture normale : fenetre visible, restauree et au premier plan (lancement depuis GameBoost.exe, le .bat ou un raccourci)
function Show-GBMainFront {
    $form.WindowState = "Normal"
    if (-not $form.Visible) { $form.Show() }
    # Fenetre restee sur un ecran eteint / detache (ou debranche) : ramenee au milieu de l'ecran de la souris
    try {
        $b = $form.Bounds; $seen = $false
        foreach ($sc in [System.Windows.Forms.Screen]::AllScreens) {
            $r = [System.Drawing.Rectangle]::Intersect($sc.WorkingArea, $b)
            if ($r.Width -ge 160 -and $r.Height -ge 100) { $seen = $true; break }
        }
        $off = @($Script:MonOff.Values | ForEach-Object { [string]$_.Device })
        if ($seen -and $off.Count) { $dv = [System.Windows.Forms.Screen]::FromRectangle($b).DeviceName; if ($off -contains $dv) { $seen = $false } }
        if (-not $seen) {
            $wa = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea
            $x = $wa.X + [math]::Max(0, [int](($wa.Width - $b.Width) / 2)); $y = $wa.Y + [math]::Max(0, [int](($wa.Height - $b.Height) / 2))
            $form.Location = New-Object System.Drawing.Point($x, $y)
        }
    } catch {}
    $form.TopMost = $true; $form.TopMost = $false
    $form.Activate()
    if ($Script:UiOK) { [void][GBTheme]::ShowFront($form) }
}
if (-not $Minimized) {
    $Script:FrontTimer = New-Object System.Windows.Forms.Timer
    $Script:FrontTimer.Interval = 150
    $Script:FrontTicks = 0
    $Script:FrontTimer.Add_Tick({
        $Script:FrontTicks++
        try { Show-GBMainFront } catch {}
        # 2 essais (le 2e rattrape une fenetre que Windows aurait encore cachee), puis comportement normal
        if ($Script:FrontTicks -ge 2) { $Script:FrontTimer.Stop(); $Script:FrontTimer.Dispose(); $Script:OpeningFront = $false }
    })
    $Script:FrontTimer.Start()
}
# Un 2e lancement (GameBoost.exe, raccourci...) ramene la fenetre au premier plan
$Script:ShowTimer = New-Object System.Windows.Forms.Timer
$Script:ShowTimer.Interval = 400
$Script:ShowTimer.Add_Tick({ try { if ($Script:ShowEvent.WaitOne(0)) { Show-GBMainFront } } catch {} })
$Script:ShowTimer.Start()

$form.Add_FormClosing({
    param($s, $e)
    if ($e.Cancel) { return }   # croix = rangee pres de l'horloge (voir Hide-GBToTray)
    $Script:Closing = $true
    if ($Script:Boosted) { Invoke-Restore }
    # Crochets de fermeture des modules (ecrans rallumes, liens...) : avant la remise du turbo et de la carte graphique
    try { if ($Script:MinuteTimer) { $Script:MinuteTimer.Stop() } } catch {}
    try { Invoke-GBCloseHooks } catch {}
    # GameBoost ferme : le processeur retrouve son turbo normal et la carte graphique sa frequence (personne pour les remettre pendant les jeux)
    try { Set-GBTurboCap $false } catch {}
    try { Set-GBGpuCap $false } catch {}
    Sync-ConfigFromUI
    $timer.Stop(); $monTimer.Stop(); $tray.Visible = $false; $tray.Dispose()
})

# --- Coque de la fenetre principale (socle) : barre de menus en haut, puis $Script:Body -------------------
# Le menu ($Script:Menu, Dock Top) est ajoute plus tard par le module des raccourcis : $Script:Body est pose sous lui
# (0, $Script:MenuH), sans ancrage ni Dock, donc le menu ne decale rien. Chaque mise en page range tout dans $Script:Body.
if ($null -eq $Script:MenuH) { $Script:MenuH = 24 }
$Script:Body = New-Object System.Windows.Forms.Panel
$Script:Body.Name = 'GBBody'; $Script:Body.BackColor = $cBg
$Script:Body.Location = New-Object System.Drawing.Point(0, [int]$Script:MenuH)
$Script:Body.Size = New-Object System.Drawing.Size(920, 640)
if ($Script:UiOK) { [GBTheme]::DoubleBuffer($Script:Body) }
$form.Controls.Add($Script:Body)
$Script:ShellScaled = $false
$form.Add_Load({ $Script:ShellScaled = $true })   # (apres la mise a l'echelle du zoom Windows par Register-GBDpi)
# (Log fait DoEvents : le minuteur d'ouverture peut afficher la fenetre avant Application.Run, on note donc l'affichage ici)
$Script:FormShown = $false
$form.Add_Shown({ $Script:FormShown = $true })
# Taille de la zone utile du modele ($MainW x $MainH, en pixels a 100 %) : la fenetre ajoute la hauteur du menu
function Set-GBShellSize([int]$w, [int]$h) {
    $Script:MainW = $w; $Script:MainH = $h
    if (-not $Script:Body -or $Script:Body.IsDisposed) { return }
    $k = 1.0; if ($Script:ShellScaled) { $k = [double]$Script:DpiScale }   # appel apres l'ouverture : deja a l'echelle
    $mh = [int][math]::Round([int]$Script:MenuH * $k)
    $sw = [int][math]::Round($w * $k); $sh = [int][math]::Round($h * $k)
    $Script:Body.Location = New-Object System.Drawing.Point(0, $mh)
    $Script:Body.Size = New-Object System.Drawing.Size($sw, $sh)
    $form.ClientSize = New-Object System.Drawing.Size($sw, ($sh + $mh))
}
# ============================================================================
# --- CLAVIER ET SON --------------------------------------------------------
#  Clavier : touches remplacees, macros, disposition (AZERTY / QWERTY)
#  Son     : volume, sortie et micro de chaque application, peripheriques, egaliseur
#  Reglages dans %APPDATA%\GameBoost\clavier.json et son.json
# ============================================================================
$Script:GBKeysSrc = @'
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Threading;

// Une etape de macro. Kind : 0 = touche (appui + relache), 1 = appui, 2 = relache, 3 = attente (Ms), 4 = texte
public class GBMacroStep { public int Kind; public int Vk; public int Ms; public string Text; }
// Mode : 0 = une fois, 1 = repete tant que la touche est maintenue, 2 = bascule (1er appui demarre, 2e arrete)
public class GBMacro {
    public string Name; public int Vk; public int Mods; public int Mode; public int GapMs = 40; public GBMacroStep[] Steps;
    internal volatile bool Running; internal volatile bool StopFlag; internal volatile bool Held;
}

// Clavier : touches remplacees et macros, par un crochet clavier Windows sur un fil a part
// (le fil de l'interface peut etre occupe sans ralentir la frappe).
public static class GBKeys {
    delegate IntPtr HookProc(int code, IntPtr w, IntPtr l);
    [StructLayout(LayoutKind.Sequential)] struct KBD { public uint vk, scan, flags, time; public UIntPtr extra; }
    [StructLayout(LayoutKind.Sequential)] struct MOUSEINPUT { public int dx, dy; public uint mouseData, dwFlags, time; public UIntPtr dwExtraInfo; }
    [StructLayout(LayoutKind.Sequential)] struct KEYBDINPUT { public ushort wVk, wScan; public uint dwFlags, time; public UIntPtr dwExtraInfo; }
    [StructLayout(LayoutKind.Explicit)] struct InputUnion { [FieldOffset(0)] public MOUSEINPUT mi; [FieldOffset(0)] public KEYBDINPUT ki; }
    [StructLayout(LayoutKind.Sequential)] struct INPUT { public uint type; public InputUnion u; }
    [StructLayout(LayoutKind.Sequential)] struct MSG { public IntPtr hwnd; public uint message; public IntPtr wParam, lParam; public uint time; public int x, y; }

    [DllImport("user32.dll", SetLastError = true)] static extern IntPtr SetWindowsHookEx(int id, HookProc proc, IntPtr mod, uint thread);
    [DllImport("user32.dll")] static extern bool UnhookWindowsHookEx(IntPtr h);
    [DllImport("user32.dll")] static extern IntPtr CallNextHookEx(IntPtr h, int code, IntPtr w, IntPtr l);
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode)] static extern IntPtr GetModuleHandle(string name);
    [DllImport("kernel32.dll")] static extern uint GetCurrentThreadId();
    [DllImport("user32.dll")] static extern int GetMessage(out MSG msg, IntPtr hwnd, uint min, uint max);
    [DllImport("user32.dll")] static extern bool PostThreadMessage(uint thread, uint msg, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] static extern uint SendInput(uint n, INPUT[] inputs, int size);
    [DllImport("user32.dll")] static extern uint MapVirtualKey(uint code, uint type);
    [DllImport("user32.dll")] static extern short GetAsyncKeyState(int vk);
    [DllImport("user32.dll", CharSet = CharSet.Unicode)] static extern IntPtr LoadKeyboardLayout(string klid, uint flags);
    [DllImport("user32.dll")] static extern bool PostMessage(IntPtr hwnd, uint msg, IntPtr w, IntPtr l);
    [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] static extern uint GetWindowThreadProcessId(IntPtr hwnd, out uint pid);
    [DllImport("user32.dll")] static extern IntPtr GetKeyboardLayout(uint thread);

    // Marque de nos propres frappes : le crochet les laisse passer sans les retraiter
    static readonly UIntPtr Tag = new UIntPtr(0x47424B31u);
    static Thread th; static IntPtr hook = IntPtr.Zero; static uint tid; static HookProc proc;
    static readonly ManualResetEvent ready = new ManualResetEvent(false);
    static volatile Dictionary<int, int> remap = new Dictionary<int, int>();
    static volatile Dictionary<int, GBMacro> macros = new Dictionary<int, GBMacro>();
    static readonly Dictionary<int, GBMacro> heldBy = new Dictionary<int, GBMacro>();
    static readonly HashSet<int> swallowed = new HashSet<int>();
    static readonly List<int[]> rec = new List<int[]>();
    public static volatile bool Paused;       // tout est suspendu (capture d'une touche dans GameBoost)
    public static volatile bool MacrosOff;    // macros suspendues (pendant le boost si l'option le demande)
    public static volatile bool Recording;    // enregistrement d'une macro : les frappes passent et sont notees
    public static bool Active { get { return hook != IntPtr.Zero; } }
    public static int LastError;

    public static bool Start() {
        if (Active) return true;
        ready.Reset();
        th = new Thread(Loop); th.IsBackground = true; th.Name = "GameBoost clavier"; th.Start();
        ready.WaitOne(2000);
        return Active;
    }
    public static void Stop() {
        StopAllMacros();
        if (!Active) return;
        try { PostThreadMessage(tid, 0x0012, IntPtr.Zero, IntPtr.Zero); } catch { }
        try { if (th != null) th.Join(1500); } catch { }
    }
    static void Loop() {
        proc = Proc;
        tid = GetCurrentThreadId();
        hook = SetWindowsHookEx(13, proc, GetModuleHandle(null), 0);
        if (hook == IntPtr.Zero) LastError = Marshal.GetLastWin32Error();
        ready.Set();
        if (hook == IntPtr.Zero) return;
        MSG m;
        while (GetMessage(out m, IntPtr.Zero, 0, 0) > 0) { }
        UnhookWindowsHookEx(hook); hook = IntPtr.Zero;
    }

    // Nouvelle configuration, appliquee d'un coup. from[i] -> to[i] (0 = touche desactivee)
    public static void Configure(int[] from, int[] to, GBMacro[] list) {
        Dictionary<int, int> r = new Dictionary<int, int>();
        if (from != null && to != null) for (int i = 0; i < from.Length && i < to.Length; i++) if (from[i] > 0 && from[i] != to[i]) r[from[i]] = to[i];
        Dictionary<int, GBMacro> m = new Dictionary<int, GBMacro>();
        if (list != null) foreach (GBMacro x in list) if (x != null && x.Vk > 0 && x.Steps != null && x.Steps.Length > 0) m[x.Vk | (x.Mods << 16)] = x;
        StopAllMacros();
        remap = r; macros = m;
    }
    public static void StopAllMacros() {
        foreach (GBMacro x in macros.Values) { x.StopFlag = true; x.Held = false; }
        lock (heldBy) heldBy.Clear();
    }

    public static void StartRecord() { lock (rec) rec.Clear(); Recording = true; }
    // Chaque ligne : touche, 0 = appui / 1 = relache, heure en millisecondes
    public static int[][] StopRecord() { Recording = false; lock (rec) return rec.ToArray(); }

    static bool IsMod(int vk) { return vk == 0x10 || vk == 0x11 || vk == 0x12 || (vk >= 0xA0 && vk <= 0xA5) || vk == 0x5B || vk == 0x5C; }
    static int Mods() {
        int m = 0;
        if (GetAsyncKeyState(0x11) < 0) m |= 1;
        if (GetAsyncKeyState(0x12) < 0) m |= 2;
        if (GetAsyncKeyState(0x10) < 0) m |= 4;
        if (GetAsyncKeyState(0x5B) < 0 || GetAsyncKeyState(0x5C) < 0) m |= 8;
        return m;
    }

    static IntPtr Proc(int code, IntPtr w, IntPtr l) {
        try {
            if (code == 0) {
                KBD k = (KBD)Marshal.PtrToStructure(l, typeof(KBD));
                if (k.extra != Tag) {
                    int vk = (int)k.vk; int msg = (int)w;
                    bool up = (msg == 0x0101 || msg == 0x0105);
                    if (Recording) { lock (rec) if (rec.Count < 2000) rec.Add(new int[] { vk, up ? 1 : 0, Environment.TickCount }); }
                    else if (!Paused) {
                        // Relache d'une touche dont l'appui a ete avale : avalee aussi
                        if (up) {
                            GBMacro hm = null; bool was;
                            lock (heldBy) { if (heldBy.TryGetValue(vk, out hm)) heldBy.Remove(vk); was = swallowed.Remove(vk); }
                            if (hm != null) { hm.Held = false; return (IntPtr)1; }
                            if (was && !remap.ContainsKey(vk)) return (IntPtr)1;
                        }
                        if (!MacrosOff && !up) {
                            GBMacro m;
                            int key = IsMod(vk) ? vk : (vk | (Mods() << 16));
                            if (macros.TryGetValue(key, out m)) {
                                bool repeat;
                                lock (heldBy) { repeat = heldBy.ContainsKey(vk); heldBy[vk] = m; }
                                if (!repeat) {
                                    m.Held = true;
                                    if (m.Mode == 2 && m.Running) m.StopFlag = true;
                                    else if (!m.Running) { m.Running = true; m.StopFlag = false; GBMacro mm = m; ThreadPool.QueueUserWorkItem(delegate { Run(mm); }); }
                                }
                                return (IntPtr)1;
                            }
                        }
                        int to;
                        if (remap.TryGetValue(vk, out to)) {
                            if (to > 0) Send(to, up);
                            return (IntPtr)1;
                        }
                    }
                }
            }
        } catch { }
        return CallNextHookEx(hook, code, w, l);
    }

    static bool Extended(int vk) {
        return (vk >= 0x21 && vk <= 0x28) || vk == 0x2D || vk == 0x2E || vk == 0x90 || vk == 0xA3 || vk == 0xA5 || vk == 0x6F || vk == 0x5B || vk == 0x5C || vk == 0x5D;
    }
    static void Send(int vk, bool up) {
        INPUT[] a = new INPUT[1];
        a[0].type = 1;
        a[0].u.ki.wVk = (ushort)vk; a[0].u.ki.wScan = (ushort)MapVirtualKey((uint)vk, 0);
        a[0].u.ki.dwFlags = (up ? 2u : 0u) | (Extended(vk) ? 1u : 0u);
        a[0].u.ki.dwExtraInfo = Tag;
        SendInput(1, a, Marshal.SizeOf(typeof(INPUT)));
    }
    static void SendChar(char c) {
        INPUT[] a = new INPUT[2];
        for (int i = 0; i < 2; i++) { a[i].type = 1; a[i].u.ki.wScan = c; a[i].u.ki.dwFlags = 4u | (i == 1 ? 2u : 0u); a[i].u.ki.dwExtraInfo = Tag; }
        SendInput(2, a, Marshal.SizeOf(typeof(INPUT)));
    }
    static bool Wait(GBMacro m, int ms) {
        int left = Math.Max(0, Math.Min(ms, 60000));
        while (left > 0) { if (m.StopFlag) return false; int s = Math.Min(left, 10); Thread.Sleep(s); left -= s; }
        return !m.StopFlag;
    }
    static void Run(GBMacro m) {
        HashSet<int> down = new HashSet<int>();
        try {
            int loops = 0;
            do {
                foreach (GBMacroStep s in m.Steps) {
                    if (m.StopFlag) break;
                    switch (s.Kind) {
                        case 0: Send(s.Vk, false); Thread.Sleep(12); Send(s.Vk, true); break;
                        case 1: Send(s.Vk, false); down.Add(s.Vk); break;
                        case 2: Send(s.Vk, true); down.Remove(s.Vk); break;
                        case 3: Wait(m, s.Ms); break;
                        case 4: if (s.Text != null) foreach (char c in s.Text) { if (m.StopFlag) break; SendChar(c); Thread.Sleep(4); } break;
                    }
                    if (s.Kind != 3) Thread.Sleep(8);
                }
                if (m.Mode == 0) break;
                if (!Wait(m, Math.Max(20, m.GapMs))) break;
                if (++loops > 100000) break;
            } while (!m.StopFlag && !MacrosOff && !Paused && (m.Mode == 2 || m.Held));
        } catch { }
        finally {
            foreach (int v in down) { try { Send(v, true); } catch { } }
            m.Running = false; m.StopFlag = false;
        }
    }

    // --- Disposition du clavier (AZERTY, QWERTY...) : klid = "0000040C" (francais), "00000409" (anglais US)...
    public static bool SetLayout(string klid) {
        IntPtr h = LoadKeyboardLayout(klid, 1);
        if (h == IntPtr.Zero) return false;
        IntPtr fg = GetForegroundWindow();
        if (fg != IntPtr.Zero) PostMessage(fg, 0x0050, IntPtr.Zero, h);
        PostMessage((IntPtr)0xFFFF, 0x0050, IntPtr.Zero, h);
        return true;
    }
    // Langue de la disposition de la fenetre active (0x040C = francais, 0x0409 = anglais US...)
    public static int CurrentLayout() {
        uint pid; uint t = GetWindowThreadProcessId(GetForegroundWindow(), out pid);
        return (int)((long)GetKeyboardLayout(t) & 0xFFFF);
    }
}
'@
$Script:GBAudioSrc = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;

public class GBAudioDevice { public string Id; public string Name; public bool IsDefault; public bool IsCapture; public int Volume; public bool Mute; }
public class GBAudioSession { public int Pid; public string Name; public string DeviceId; public string DeviceName; public int Volume; public bool Mute; public bool IsSystem; public bool IsCapture; public bool Active; }

// Son de Windows : peripheriques, volume de chaque application, sortie et micro par application.
public static class GBAudio {
    [ComImport, Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")] class MMDeviceEnumerator { }
    [ComImport, Guid("870af99c-171d-4f9e-af0d-e63df40c2bc9")] class PolicyConfigClient { }

    [Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IMMDeviceEnumerator {
        [PreserveSig] int EnumAudioEndpoints(int flow, int mask, out IMMDeviceCollection devices);
        [PreserveSig] int GetDefaultAudioEndpoint(int flow, int role, out IMMDevice device);
        [PreserveSig] int GetDevice([MarshalAs(UnmanagedType.LPWStr)] string id, out IMMDevice device);
    }
    [Guid("0BD7A1BE-7A1A-44DB-8397-CC5392387B5E"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IMMDeviceCollection { [PreserveSig] int GetCount(out int n); [PreserveSig] int Item(int i, out IMMDevice device); }
    [Guid("D666063F-1587-4E43-81F1-B948E807363F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IMMDevice {
        [PreserveSig] int Activate(ref Guid iid, int ctx, IntPtr activation, [MarshalAs(UnmanagedType.IUnknown)] out object o);
        [PreserveSig] int OpenPropertyStore(int access, out IPropertyStore store);
        [PreserveSig] int GetId([MarshalAs(UnmanagedType.LPWStr)] out string id);
        [PreserveSig] int GetState(out int state);
    }
    [StructLayout(LayoutKind.Sequential)] struct PROPERTYKEY { public Guid fmtid; public int pid; }
    [StructLayout(LayoutKind.Sequential)] struct PROPVARIANT { public ushort vt, r1, r2, r3; public IntPtr p1; public IntPtr p2; }
    [Guid("886d8eeb-8cf2-4446-8d02-cdba1dbdcf99"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IPropertyStore {
        [PreserveSig] int GetCount(out int n);
        [PreserveSig] int GetAt(int i, out PROPERTYKEY key);
        [PreserveSig] int GetValue(ref PROPERTYKEY key, out PROPVARIANT v);
    }
    [DllImport("ole32.dll")] static extern int PropVariantClear(ref PROPVARIANT v);

    [Guid("5CDF2C82-841E-4546-9722-0CF74078229A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IAudioEndpointVolume {
        [PreserveSig] int RegisterControlChangeNotify(IntPtr n);
        [PreserveSig] int UnregisterControlChangeNotify(IntPtr n);
        [PreserveSig] int GetChannelCount(out int n);
        [PreserveSig] int SetMasterVolumeLevel(float db, ref Guid ctx);
        [PreserveSig] int SetMasterVolumeLevelScalar(float level, ref Guid ctx);
        [PreserveSig] int GetMasterVolumeLevel(out float db);
        [PreserveSig] int GetMasterVolumeLevelScalar(out float level);
        [PreserveSig] int SetChannelVolumeLevel(int ch, float db, ref Guid ctx);
        [PreserveSig] int SetChannelVolumeLevelScalar(int ch, float level, ref Guid ctx);
        [PreserveSig] int GetChannelVolumeLevel(int ch, out float db);
        [PreserveSig] int GetChannelVolumeLevelScalar(int ch, out float level);
        [PreserveSig] int SetMute([MarshalAs(UnmanagedType.Bool)] bool mute, ref Guid ctx);
        [PreserveSig] int GetMute([MarshalAs(UnmanagedType.Bool)] out bool mute);
    }
    [Guid("77AA99A0-1BD6-484F-8BC7-2C654C9A9B6F"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IAudioSessionManager2 {
        [PreserveSig] int GetAudioSessionControl(IntPtr guid, int flags, out IntPtr ctl);
        [PreserveSig] int GetSimpleAudioVolume(IntPtr guid, int flags, out IntPtr vol);
        [PreserveSig] int GetSessionEnumerator(out IAudioSessionEnumerator e);
    }
    [Guid("E2F5BB11-0570-40CA-ACDD-3AA01277DEE8"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IAudioSessionEnumerator { [PreserveSig] int GetCount(out int n); [PreserveSig] int GetSession(int i, out IAudioSessionControl2 s); }
    [Guid("bfb7ff88-7239-4fc9-8fa2-07c950be9c6d"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IAudioSessionControl2 {
        [PreserveSig] int GetState(out int state);
        [PreserveSig] int GetDisplayName([MarshalAs(UnmanagedType.LPWStr)] out string name);
        [PreserveSig] int SetDisplayName([MarshalAs(UnmanagedType.LPWStr)] string name, ref Guid ctx);
        [PreserveSig] int GetIconPath([MarshalAs(UnmanagedType.LPWStr)] out string path);
        [PreserveSig] int SetIconPath([MarshalAs(UnmanagedType.LPWStr)] string path, ref Guid ctx);
        [PreserveSig] int GetGroupingParam(out Guid g);
        [PreserveSig] int SetGroupingParam(ref Guid g, ref Guid ctx);
        [PreserveSig] int RegisterAudioSessionNotification(IntPtr n);
        [PreserveSig] int UnregisterAudioSessionNotification(IntPtr n);
        [PreserveSig] int GetSessionIdentifier([MarshalAs(UnmanagedType.LPWStr)] out string id);
        [PreserveSig] int GetSessionInstanceIdentifier([MarshalAs(UnmanagedType.LPWStr)] out string id);
        [PreserveSig] int GetProcessId(out uint pid);
        [PreserveSig] int IsSystemSoundsSession();
        [PreserveSig] int SetDuckingPreference([MarshalAs(UnmanagedType.Bool)] bool optOut);
    }
    [Guid("87CE5498-68D6-44E5-9215-6DA47EF883D8"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface ISimpleAudioVolume {
        [PreserveSig] int SetMasterVolume(float level, ref Guid ctx);
        [PreserveSig] int GetMasterVolume(out float level);
        [PreserveSig] int SetMute([MarshalAs(UnmanagedType.Bool)] bool mute, ref Guid ctx);
        [PreserveSig] int GetMute([MarshalAs(UnmanagedType.Bool)] out bool mute);
    }
    [Guid("f8679f50-850a-41cf-9c72-430f290290c8"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IPolicyConfig {
        [PreserveSig] int GetMixFormat(); [PreserveSig] int GetDeviceFormat(); [PreserveSig] int ResetDeviceFormat(); [PreserveSig] int SetDeviceFormat();
        [PreserveSig] int GetProcessingPeriod(); [PreserveSig] int SetProcessingPeriod(); [PreserveSig] int GetShareMode(); [PreserveSig] int SetShareMode();
        [PreserveSig] int GetPropertyValue(); [PreserveSig] int SetPropertyValue();
        [PreserveSig] int SetDefaultEndpoint([MarshalAs(UnmanagedType.LPWStr)] string id, int role);
    }

    static readonly Guid IID_Volume = new Guid("5CDF2C82-841E-4546-9722-0CF74078229A");
    static readonly Guid IID_SessMgr = new Guid("77AA99A0-1BD6-484F-8BC7-2C654C9A9B6F");
    static Guid Ctx = Guid.Empty;

    static void Free(object o) { try { if (o != null) Marshal.ReleaseComObject(o); } catch { } }
    static IMMDeviceEnumerator Enum() { return (IMMDeviceEnumerator)(new MMDeviceEnumerator()); }

    static string FriendlyName(IMMDevice d) {
        IPropertyStore ps = null;
        try {
            if (d.OpenPropertyStore(0, out ps) != 0 || ps == null) return "";
            PROPERTYKEY k = new PROPERTYKEY(); k.fmtid = new Guid("a45c254e-df1c-4efd-8020-67d146a850e0"); k.pid = 14;
            PROPVARIANT v;
            if (ps.GetValue(ref k, out v) != 0) return "";
            string s = (v.vt == 31 && v.p1 != IntPtr.Zero) ? Marshal.PtrToStringUni(v.p1) : "";
            PropVariantClear(ref v);
            return s ?? "";
        } catch { return ""; } finally { Free(ps); }
    }
    static IAudioEndpointVolume VolumeOf(IMMDevice d) {
        object o; Guid iid = IID_Volume;
        if (d.Activate(ref iid, 23, IntPtr.Zero, out o) != 0) return null;
        return o as IAudioEndpointVolume;
    }

    // Peripheriques branches et actifs. capture = false : sorties (casque, enceintes) ; true : micros
    public static GBAudioDevice[] Devices(bool capture) {
        List<GBAudioDevice> list = new List<GBAudioDevice>();
        IMMDeviceEnumerator en = null; IMMDeviceCollection col = null;
        try {
            en = Enum(); int flow = capture ? 1 : 0;
            string def = "";
            IMMDevice dd; if (en.GetDefaultAudioEndpoint(flow, 0, out dd) == 0 && dd != null) { dd.GetId(out def); Free(dd); }
            if (en.EnumAudioEndpoints(flow, 1, out col) != 0 || col == null) return list.ToArray();
            int n; col.GetCount(out n);
            for (int i = 0; i < n; i++) {
                IMMDevice d; if (col.Item(i, out d) != 0 || d == null) continue;
                try {
                    GBAudioDevice x = new GBAudioDevice(); d.GetId(out x.Id); x.Name = FriendlyName(d); x.IsCapture = capture; x.IsDefault = (x.Id == def);
                    IAudioEndpointVolume v = VolumeOf(d);
                    if (v != null) { float f; if (v.GetMasterVolumeLevelScalar(out f) == 0) x.Volume = (int)Math.Round(f * 100); bool m; if (v.GetMute(out m) == 0) x.Mute = m; Free(v); }
                    list.Add(x);
                } finally { Free(d); }
            }
        } catch { } finally { Free(col); Free(en); }
        return list.ToArray();
    }

    static IMMDevice Find(IMMDeviceEnumerator en, string id, bool capture) {
        IMMDevice d = null;
        if (string.IsNullOrEmpty(id)) { en.GetDefaultAudioEndpoint(capture ? 1 : 0, 0, out d); return d; }
        en.GetDevice(id, out d); return d;
    }
    // Volume general d'un peripherique (id vide = celui par defaut). level : 0 a 100, -1 = ne pas changer ; mute : 0 / 1, -1 = ne pas changer, 2 = inverser
    public static bool SetDevice(string id, bool capture, int level, int mute) {
        IMMDeviceEnumerator en = null; IMMDevice d = null; IAudioEndpointVolume v = null;
        try {
            en = Enum(); d = Find(en, id, capture); if (d == null) return false;
            v = VolumeOf(d); if (v == null) return false;
            if (level >= 0) v.SetMasterVolumeLevelScalar(Math.Min(100, level) / 100f, ref Ctx);
            if (mute == 2) { bool m; v.GetMute(out m); v.SetMute(!m, ref Ctx); } else if (mute >= 0) v.SetMute(mute == 1, ref Ctx);
            return true;
        } catch { return false; } finally { Free(v); Free(d); Free(en); }
    }
    public static bool GetMute(string id, bool capture) {
        IMMDeviceEnumerator en = null; IMMDevice d = null; IAudioEndpointVolume v = null;
        try { en = Enum(); d = Find(en, id, capture); if (d == null) return false; v = VolumeOf(d); bool m = false; if (v != null) v.GetMute(out m); return m; }
        catch { return false; } finally { Free(v); Free(d); Free(en); }
    }
    // Peripherique par defaut de Windows (son general, multimedia et communications)
    public static bool SetDefault(string id) {
        object o = null;
        try {
            o = new PolicyConfigClient(); IPolicyConfig pc = (IPolicyConfig)o;
            int hr = 0; for (int role = 0; role < 3; role++) { int r = pc.SetDefaultEndpoint(id, role); if (r != 0) hr = r; }
            return hr == 0;
        } catch { return false; } finally { Free(o); }
    }

    static string ProcName(int pid) {
        try { using (Process p = Process.GetProcessById(pid)) return p.ProcessName; } catch { return ""; }
    }
    // Applications qui jouent du son (capture = false) ou qui utilisent un micro (capture = true)
    public static GBAudioSession[] Sessions(bool capture) {
        List<GBAudioSession> list = new List<GBAudioSession>();
        IMMDeviceEnumerator en = null; IMMDeviceCollection col = null;
        try {
            en = Enum();
            if (en.EnumAudioEndpoints(capture ? 1 : 0, 1, out col) != 0 || col == null) return list.ToArray();
            int n; col.GetCount(out n);
            for (int i = 0; i < n; i++) {
                IMMDevice d; if (col.Item(i, out d) != 0 || d == null) continue;
                IAudioSessionManager2 mgr = null; IAudioSessionEnumerator se = null;
                try {
                    string did; d.GetId(out did); string dname = FriendlyName(d);
                    object o; Guid iid = IID_SessMgr;
                    if (d.Activate(ref iid, 23, IntPtr.Zero, out o) != 0) continue;
                    mgr = o as IAudioSessionManager2; if (mgr == null) continue;
                    if (mgr.GetSessionEnumerator(out se) != 0 || se == null) continue;
                    int c; se.GetCount(out c);
                    for (int j = 0; j < c; j++) {
                        IAudioSessionControl2 s; if (se.GetSession(j, out s) != 0 || s == null) continue;
                        try {
                            int st; s.GetState(out st); if (st == 2) continue;   // session terminee
                            GBAudioSession x = new GBAudioSession(); x.DeviceId = did; x.DeviceName = dname; x.IsCapture = capture; x.Active = (st == 1);
                            uint pid; s.GetProcessId(out pid); x.Pid = (int)pid;
                            x.IsSystem = (s.IsSystemSoundsSession() == 0);
                            x.Name = x.IsSystem ? "Sons de Windows" : ProcName(x.Pid);
                            if (!x.IsSystem && x.Name.Length == 0) continue;
                            ISimpleAudioVolume v = s as ISimpleAudioVolume;
                            if (v != null) { float f; if (v.GetMasterVolume(out f) == 0) x.Volume = (int)Math.Round(f * 100); bool m; if (v.GetMute(out m) == 0) x.Mute = m; }
                            list.Add(x);
                        } finally { Free(s); }
                    }
                } catch { } finally { Free(se); Free(mgr); Free(d); }
            }
        } catch { } finally { Free(col); Free(en); }
        return list.ToArray();
    }
    // Volume d'une application (toutes ses sessions, sur toutes les sorties). level -1 = ne pas changer ; mute -1 = ne pas changer
    public static int SetApp(int pid, int level, int mute) {
        int done = 0;
        IMMDeviceEnumerator en = null; IMMDeviceCollection col = null;
        try {
            en = Enum();
            if (en.EnumAudioEndpoints(0, 1, out col) != 0 || col == null) return 0;
            int n; col.GetCount(out n);
            for (int i = 0; i < n; i++) {
                IMMDevice d; if (col.Item(i, out d) != 0 || d == null) continue;
                IAudioSessionManager2 mgr = null; IAudioSessionEnumerator se = null;
                try {
                    object o; Guid iid = IID_SessMgr;
                    if (d.Activate(ref iid, 23, IntPtr.Zero, out o) != 0) continue;
                    mgr = o as IAudioSessionManager2; if (mgr == null || mgr.GetSessionEnumerator(out se) != 0 || se == null) continue;
                    int c; se.GetCount(out c);
                    for (int j = 0; j < c; j++) {
                        IAudioSessionControl2 s; if (se.GetSession(j, out s) != 0 || s == null) continue;
                        try {
                            uint p; s.GetProcessId(out p); if ((int)p != pid) continue;
                            ISimpleAudioVolume v = s as ISimpleAudioVolume; if (v == null) continue;
                            if (level >= 0) v.SetMasterVolume(Math.Min(100, level) / 100f, ref Ctx);
                            if (mute >= 0) v.SetMute(mute == 1, ref Ctx);
                            done++;
                        } finally { Free(s); }
                    }
                } catch { } finally { Free(se); Free(mgr); Free(d); }
            }
        } catch { } finally { Free(col); Free(en); }
        return done;
    }

    // --- Sortie et micro par application (reglage "Volume des applications et preferences des peripheriques" de Windows 10 1803+ / 11)
    [DllImport("combase.dll")] static extern int RoGetActivationFactory(IntPtr classId, ref Guid iid, out IntPtr factory);
    [DllImport("combase.dll", CharSet = CharSet.Unicode)] static extern int WindowsCreateString(string s, int len, out IntPtr h);
    [DllImport("combase.dll")] static extern int WindowsDeleteString(IntPtr h);
    [DllImport("combase.dll")] static extern IntPtr WindowsGetStringRawBuffer(IntPtr h, out uint len);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int SetEp(IntPtr self, uint pid, int flow, int role, IntPtr deviceId);
    [UnmanagedFunctionPointer(CallingConvention.StdCall)] delegate int GetEp(IntPtr self, uint pid, int flow, int role, out IntPtr deviceId);
    const string RenderSuffix = "#{e6327cad-dcec-4949-ae8a-991e976a79d2}", CaptureSuffix = "#{2eef81be-33fa-4800-9670-1cd474972c3f}", Prefix = @"\\?\SWD#MMDEVAPI#";
    public static int LastHr;

    static IntPtr Factory() {
        IntPtr cls; if (WindowsCreateString("Windows.Media.Internal.AudioPolicyConfig", 40, out cls) != 0) return IntPtr.Zero;
        try {
            foreach (string g in new string[] { "ab3d4648-e242-459f-b02f-541c70306324", "2a59116d-6c4f-45e0-a74f-707e3fef9258" }) {
                Guid iid = new Guid(g); IntPtr f;
                if (RoGetActivationFactory(cls, ref iid, out f) == 0 && f != IntPtr.Zero) return f;
            }
        } catch { } finally { WindowsDeleteString(cls); }
        return IntPtr.Zero;
    }
    static T Slot<T>(IntPtr self, int index) where T : class {
        IntPtr vt = Marshal.ReadIntPtr(self);
        return Marshal.GetDelegateForFunctionPointer(Marshal.ReadIntPtr(vt, index * IntPtr.Size), typeof(T)) as T;
    }
    public static bool AppRoutingAvailable() { IntPtr f = Factory(); if (f == IntPtr.Zero) return false; Marshal.Release(f); return true; }
    // Peripherique choisi pour une application ("" = celui par defaut de Windows)
    public static string GetAppDevice(int pid, bool capture) {
        IntPtr f = Factory(); if (f == IntPtr.Zero) return "";
        try {
            IntPtr h; LastHr = Slot<GetEp>(f, 26)(f, (uint)pid, capture ? 1 : 0, 1, out h);
            if (LastHr != 0 || h == IntPtr.Zero) return "";
            uint len; string s = Marshal.PtrToStringUni(WindowsGetStringRawBuffer(h, out len), (int)len); WindowsDeleteString(h);
            if (string.IsNullOrEmpty(s)) return "";
            int a = s.IndexOf("MMDEVAPI#", StringComparison.OrdinalIgnoreCase); if (a < 0) return s;
            a += 9; int b = s.IndexOf('#', a); return b > a ? s.Substring(a, b - a) : s.Substring(a);
        } catch { return ""; } finally { Marshal.Release(f); }
    }
    // deviceId vide = revenir au peripherique par defaut de Windows
    public static bool SetAppDevice(int pid, bool capture, string deviceId) {
        IntPtr f = Factory(); if (f == IntPtr.Zero) return false;
        IntPtr h = IntPtr.Zero;
        try {
            if (!string.IsNullOrEmpty(deviceId)) {
                string full = Prefix + deviceId + (capture ? CaptureSuffix : RenderSuffix);
                if (WindowsCreateString(full, full.Length, out h) != 0) return false;
            }
            SetEp set = Slot<SetEp>(f, 25); int flow = capture ? 1 : 0;
            int hr = set(f, (uint)pid, flow, 1, h);
            int hr2 = set(f, (uint)pid, flow, 0, h);
            LastHr = hr != 0 ? hr : hr2;
            return hr == 0 && hr2 == 0;
        } catch { return false; } finally { if (h != IntPtr.Zero) WindowsDeleteString(h); Marshal.Release(f); }
    }
}
'@

# Objets lus dans un fichier JSON -> tables et listes modifiables
function ConvertTo-GBPlain($o) {
    if ($null -eq $o) { return $null }
    if ($o -is [string] -or $o -is [ValueType]) { return $o }
    if ($o -is [System.Collections.IDictionary]) { $h = @{}; foreach ($k in @($o.Keys)) { $h[[string]$k] = ConvertTo-GBPlain $o[$k] }; return $h }
    if ($o -is [System.Collections.IEnumerable]) { $l = New-Object System.Collections.ArrayList; foreach ($x in $o) { [void]$l.Add((ConvertTo-GBPlain $x)) }; return , $l }
    $h = @{}; foreach ($p in $o.PSObject.Properties) { $h[$p.Name] = ConvertTo-GBPlain $p.Value }
    return $h
}
function Read-GBJsonFile([string]$path, $default) {
    try {
        if (Test-Path -LiteralPath $path) {
            $o = ConvertTo-GBPlain ((Get-Content -LiteralPath $path -Raw -Encoding UTF8) | ConvertFrom-Json)
            if ($o -is [hashtable]) { foreach ($k in @($default.Keys)) { if (-not $o.ContainsKey($k) -or $null -eq $o[$k]) { $o[$k] = $default[$k] } }; return $o }
        }
    } catch { try { Log ("Reglages illisibles (" + (Split-Path -Leaf $path) + ") : valeurs par defaut") } catch {} }
    return $default
}
function ConvertTo-GBList($v) {
    $l = New-Object System.Collections.ArrayList
    if ($null -ne $v) { foreach ($x in @($v)) { if ($null -ne $x) { [void]$l.Add($x) } } }
    return , $l
}

$Script:KbFile = Join-Path $AppDir 'clavier.json'
$Script:SndFile = Join-Path $AppDir 'son.json'
$Script:Kb = Read-GBJsonFile $Script:KbFile @{ Enabled = $true; MacrosInBoost = $false; Remaps = @(); Macros = @() }
$Script:Kb.Remaps = ConvertTo-GBList $Script:Kb.Remaps
$Script:Kb.Macros = ConvertTo-GBList $Script:Kb.Macros
$Script:Snd = Read-GBJsonFile $Script:SndFile @{ EqActive = ''; EqBands = @(); EqBoost = ''; EqIdle = ''; EqCustom = @() }
$Script:Snd.EqCustom = ConvertTo-GBList $Script:Snd.EqCustom
function Save-GBKb { try { $Script:Kb | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $Script:KbFile -Encoding UTF8 } catch { Log ("Clavier : reglages non enregistres (" + $_.Exception.Message + ")") } }
function Save-GBSnd { try { $Script:Snd | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $Script:SndFile -Encoding UTF8 } catch { Log ("Son : reglages non enregistres (" + $_.Exception.Message + ")") } }

function Initialize-GBKeys {
    if ('GBKeys' -as [type]) { return $true }
    try { return [bool](Add-GBCompiled 'GBKeys' $Script:GBKeysSrc $null 'GBKeys') } catch { return $false }
}
function Initialize-GBAudio {
    if ('GBAudio' -as [type]) { return $true }
    try { return [bool](Add-GBCompiled 'GBAudio' $Script:GBAudioSrc $null 'GBAudio') } catch { return $false }
}

# ---------------------------------------------------------------- noms des touches
$Script:VkNames = @{
    8 = 'Retour'; 9 = 'Tab'; 13 = 'Entree'; 16 = 'Maj'; 17 = 'Ctrl'; 18 = 'Alt'; 19 = 'Pause'; 20 = 'VerrMaj'; 27 = 'Echap'; 32 = 'Espace'
    33 = 'PagePrec'; 34 = 'PageSuiv'; 35 = 'Fin'; 36 = 'Debut'; 37 = 'Gauche'; 38 = 'Haut'; 39 = 'Droite'; 40 = 'Bas'; 44 = 'ImprEcran'; 45 = 'Inser'; 46 = 'Suppr'
    91 = 'Win'; 92 = 'WinDroite'; 93 = 'Menu'; 106 = 'NumFois'; 107 = 'NumPlus'; 109 = 'NumMoins'; 110 = 'NumPoint'; 111 = 'NumDivise'; 144 = 'VerrNum'; 145 = 'ArretDefil'
    160 = 'MajGauche'; 161 = 'MajDroite'; 162 = 'CtrlGauche'; 163 = 'CtrlDroite'; 164 = 'AltGauche'; 165 = 'AltGr'
    173 = 'SonMuet'; 174 = 'SonMoins'; 175 = 'SonPlus'; 176 = 'PisteSuivante'; 177 = 'PistePrecedente'; 178 = 'StopMedia'; 179 = 'LecturePause'
}
function Get-GBVkName([int]$vk) {
    if ($vk -le 0) { return '' }
    if (($vk -ge 48 -and $vk -le 57) -or ($vk -ge 65 -and $vk -le 90)) { return [string][char]$vk }
    if ($vk -ge 96 -and $vk -le 105) { return 'Num' + ($vk - 96) }
    if ($vk -ge 112 -and $vk -le 135) { return 'F' + ($vk - 111) }
    if ($Script:VkNames.ContainsKey($vk)) { return $Script:VkNames[$vk] }
    return 'Touche' + $vk
}
function Get-GBVkFromName([string]$name) {
    $n = ([string]$name).Trim(); if (-not $n) { return 0 }
    if (-not $Script:VkByName) {
        $Script:VkByName = @{}
        for ($v = 1; $v -le 254; $v++) { $k = (Get-GBVkName $v).ToLower(); if (-not $Script:VkByName.ContainsKey($k)) { $Script:VkByName[$k] = $v } }
        foreach ($al in @(@('shift', 16), @('control', 17), @('entrer', 13), @('enter', 13), @('esc', 27), @('escape', 27), @('space', 32), @('del', 46), @('supprimer', 46), @('backspace', 8))) { $Script:VkByName[$al[0]] = $al[1] }
    }
    $k = $n.ToLower()
    if ($Script:VkByName.ContainsKey($k)) { return [int]$Script:VkByName[$k] }
    return 0
}
function Get-GBKeyComboText([int]$vk, [int]$mods) {
    $t = @()
    if ($mods -band 1) { $t += 'Ctrl' }; if ($mods -band 2) { $t += 'Alt' }; if ($mods -band 4) { $t += 'Maj' }; if ($mods -band 8) { $t += 'Win' }
    $t += (Get-GBVkName $vk)
    return ($t -join '+')
}
# Maj, Ctrl et Alt : le clavier envoie en realite la touche de gauche ou de droite
function Expand-GBVk([int]$vk) {
    switch ($vk) { 16 { return @(160, 161) } 17 { return @(162, 163) } 18 { return @(164, 165) } default { return @($vk) } }
}

# ---------------------------------------------------------------- macros : texte -> etapes
# Une ligne par action :  touche A | touche Ctrl+C | appui Maj | relache Maj | attendre 50 | texte Bonjour
function ConvertTo-GBMacroSteps([string]$text) {
    $steps = New-Object System.Collections.ArrayList; $err = ''; $n = 0
    foreach ($raw in (([string]$text) -split "`r?`n")) {
        $n++; $line = $raw.Trim()
        if (-not $line -or $line.StartsWith('#')) { continue }
        $i = $line.IndexOf(' '); $cmd = $line; $arg = ''
        if ($i -gt 0) { $cmd = $line.Substring(0, $i); $arg = $line.Substring($i + 1) }
        $cmd = $cmd.ToLower()
        if ($cmd -eq 'texte') {
            if ($arg.Length -gt 2000) { $arg = $arg.Substring(0, 2000) }
            [void]$steps.Add(@{ Kind = 4; Vk = 0; Ms = 0; Text = $arg })
        } elseif ($cmd -eq 'attendre') {
            $ms = 0
            if (-not [int]::TryParse($arg.Trim(), [ref]$ms) -or $ms -lt 0) { $err = "Ligne " + $n + " : ecris un nombre de millisecondes apres 'attendre' (ex : attendre 50)."; break }
            [void]$steps.Add(@{ Kind = 3; Vk = 0; Ms = [math]::Min($ms, 60000); Text = '' })
        } elseif (@('touche', 'appui', 'relache') -contains $cmd) {
            $names = @($arg.Trim()); if ((Get-GBVkFromName $arg) -eq 0) { $names = @($arg.Trim() -split '\+' | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
            $vks = @(); foreach ($nm in $names) { $v = Get-GBVkFromName $nm; if ($v -eq 0) { $err = "Ligne " + $n + " : touche inconnue '" + $nm + "'."; break }; $vks += $v }
            if ($err) { break }
            if ($vks.Count -eq 0) { $err = "Ligne " + $n + " : il manque le nom de la touche."; break }
            if ($cmd -eq 'touche') {
                for ($j = 0; $j -lt $vks.Count - 1; $j++) { [void]$steps.Add(@{ Kind = 1; Vk = $vks[$j]; Ms = 0; Text = '' }) }
                [void]$steps.Add(@{ Kind = 0; Vk = $vks[-1]; Ms = 0; Text = '' })
                for ($j = $vks.Count - 2; $j -ge 0; $j--) { [void]$steps.Add(@{ Kind = 2; Vk = $vks[$j]; Ms = 0; Text = '' }) }
            } else {
                $kind = 1; if ($cmd -eq 'relache') { $kind = 2 }
                foreach ($v in $vks) { [void]$steps.Add(@{ Kind = $kind; Vk = $v; Ms = 0; Text = '' }) }
            }
        } else { $err = "Ligne " + $n + " : commande inconnue '" + $cmd + "'. Commandes : touche, appui, relache, attendre, texte."; break }
        if ($steps.Count -gt 400) { $err = "Macro trop longue (400 actions au maximum)."; break }
    }
    return @{ Steps = $steps; Error = $err }
}
# Frappes enregistrees (touche, 0 appui / 1 relache, heure) -> texte de macro
function ConvertFrom-GBKeyRecord($events) {
    $lines = New-Object System.Collections.ArrayList
    $ev = @($events); $last = 0
    for ($i = 0; $i -lt $ev.Count; $i++) {
        $e = $ev[$i]; $vk = [int]$e[0]; $up = ([int]$e[1] -eq 1); $t = [int]$e[2]
        # repetition automatique d'une touche maintenue : ignoree
        if (-not $up) { $dup = $false; for ($j = $i - 1; $j -ge 0; $j--) { if ([int]$ev[$j][0] -eq $vk) { $dup = ([int]$ev[$j][1] -eq 0); break } }; if ($dup) { continue } }
        if ($last -gt 0) { $gap = $t - $last; if ($gap -ge 20) { [void]$lines.Add('attendre ' + [math]::Min(5000, [int]([math]::Round($gap / 10.0) * 10))) } }
        $last = $t
        $name = Get-GBVkName $vk
        # appui suivi de sa relache (repetitions automatiques sautees) en moins de 250 ms : une simple "touche"
        $j = $i + 1; while (-not $up -and $j -lt $ev.Count -and [int]$ev[$j][0] -eq $vk -and [int]$ev[$j][1] -eq 0) { $j++ }
        if (-not $up -and $j -lt $ev.Count -and [int]$ev[$j][0] -eq $vk -and [int]$ev[$j][1] -eq 1 -and ([int]$ev[$j][2] - $t) -lt 250) { [void]$lines.Add('touche ' + $name); $last = [int]$ev[$j][2]; $i = $j }
        elseif ($up) { [void]$lines.Add('relache ' + $name) } else { [void]$lines.Add('appui ' + $name) }
    }
    return ($lines -join "`r`n")
}

# ---------------------------------------------------------------- moteur clavier
function Update-GBKeysEngine {
    $kb = $Script:Kb
    $from = New-Object System.Collections.ArrayList; $to = New-Object System.Collections.ArrayList; $defs = New-Object System.Collections.ArrayList
    if ($kb.Enabled) {
        foreach ($r in @($kb.Remaps)) {
            if (-not $r.On -or [int]$r.From -le 0) { continue }
            foreach ($v in (Expand-GBVk ([int]$r.From))) { [void]$from.Add([int]$v); [void]$to.Add([int]$r.To) }
        }
        foreach ($m in @($kb.Macros)) {
            if (-not $m.On -or [int]$m.Vk -le 0) { continue }
            $p = ConvertTo-GBMacroSteps ([string]$m.Script)
            if ($p.Error -or $p.Steps.Count -eq 0) { continue }
            [void]$defs.Add(@{ M = $m; Steps = $p.Steps })
        }
    }
    if ($from.Count -eq 0 -and $defs.Count -eq 0) {
        if ('GBKeys' -as [type]) { try { [GBKeys]::Configure($null, $null, $null); [GBKeys]::Stop() } catch {} }
        return $true
    }
    if (-not (Initialize-GBKeys)) { Log "Clavier : le composant n'a pas pu etre charge (bloque par l'antivirus ?). Touches et macros inactives."; return $false }
    $list = New-Object System.Collections.ArrayList
    foreach ($d in $defs) {
        $steps = @(foreach ($s in $d.Steps) { $x = New-Object GBMacroStep; $x.Kind = [int]$s.Kind; $x.Vk = [int]$s.Vk; $x.Ms = [int]$s.Ms; $x.Text = [string]$s.Text; $x })
        foreach ($v in (Expand-GBVk ([int]$d.M.Vk))) {
            $g = New-Object GBMacro; $g.Name = [string]$d.M.Name; $g.Vk = [int]$v; $g.Mods = [int]$d.M.Mods; $g.Mode = [int]$d.M.Mode
            $g.GapMs = [math]::Max(20, [int]$d.M.Gap); $g.Steps = [GBMacroStep[]]$steps
            [void]$list.Add($g)
        }
    }
    try {
        [GBKeys]::Configure([int[]]@($from), [int[]]@($to), [GBMacro[]]@($list))
        [GBKeys]::MacrosOff = ([bool]$Script:Boosted -and -not [bool]$kb.MacrosInBoost)
        if (-not [GBKeys]::Start()) { Log ("Clavier : Windows a refuse l'ecoute du clavier (code " + [GBKeys]::LastError + "). Touches et macros inactives."); return $false }
    } catch { Log ("Clavier : " + $_.Exception.Message); return $false }
    return $true
}
function Get-GBKeysSummary {
    $kb = $Script:Kb
    $r = @($kb.Remaps | Where-Object { $_.On }).Count; $m = @($kb.Macros | Where-Object { $_.On }).Count
    if (-not $kb.Enabled) { return "coupe" }
    if ($r + $m -eq 0) { return "aucune touche changee" }
    return ($r.ToString() + " touche(s), " + $m + " macro(s)")
}

# ---------------------------------------------------------------- disposition du clavier
$Script:KbLayouts = @(
    @{ Id = '0000040C'; Lang = 0x040C; Name = 'AZERTY (francais)' }, @{ Id = '00000409'; Lang = 0x0409; Name = 'QWERTY (anglais US)' },
    @{ Id = '00000809'; Lang = 0x0809; Name = 'QWERTY (anglais UK)' }, @{ Id = '00000407'; Lang = 0x0407; Name = 'QWERTZ (allemand)' },
    @{ Id = '0000080C'; Lang = 0x080C; Name = 'AZERTY (belge)' }, @{ Id = '0000040A'; Lang = 0x040A; Name = 'QWERTY (espagnol)' })
function Get-GBKeyLayoutName {
    if (-not (Initialize-GBKeys)) { return 'inconnue' }
    $l = 0; try { $l = [GBKeys]::CurrentLayout() } catch {}
    foreach ($x in $Script:KbLayouts) { if ($x.Lang -eq $l) { return $x.Name } }
    try { return ([System.Globalization.CultureInfo]::GetCultureInfo($l)).DisplayName } catch { return ('0x{0:X4}' -f $l) }
}
function Set-GBKeyLayout([string]$klid) {
    if (-not (Initialize-GBKeys)) { Log "Clavier : composant indisponible, disposition inchangee."; return $false }
    $name = $klid; foreach ($x in $Script:KbLayouts) { if ($x.Id -eq $klid) { $name = $x.Name } }
    $ok = $false; try { $ok = [GBKeys]::SetLayout($klid) } catch {}
    if ($ok) { Log ("Clavier : disposition " + $name) } else { Log ("Clavier : Windows n'a pas pu charger la disposition " + $name) }
    return $ok
}
function Switch-GBKeyLayout {
    $l = 0; if (Initialize-GBKeys) { try { $l = [GBKeys]::CurrentLayout() } catch {} }
    if ($l -eq 0x040C -or $l -eq 0x080C) { [void](Set-GBKeyLayout '00000409') } else { [void](Set-GBKeyLayout '0000040C') }
}

