function Get-GBSearchIndex {
    $l = New-Object System.Collections.ArrayList
    foreach ($a in @($Script:GBActions.Values)) {
        if (-not (Test-GBActionShown $a)) { continue }
        $k = ''; try { $k = [string](Get-GBActionKey $a.Id) } catch {}
        $ti = ([string]$a.Label) -replace '\.\.\.$', ''
        [void]$l.Add(@{ T = $ti; W = 'Menu ' + [string]$a.Menu; D = [string]$a.Description; K = $k; Kind = 'action'; Id = [string]$a.Id })
    }
    $keys = @($Script:PageOrder | Where-Object { $_ }); if ($keys.Count -eq 0 -and $Script:Pages) { $keys = @($Script:Pages.Keys) }
    foreach ($pk in $keys) {
        $pg = $Script:Pages[$pk]; if (-not $pg -or -not $pg.Page) { continue }
        $title = [string]$pk; try { if ($pg.Title) { $title = [string]$pg.Title } elseif ($pg.Nav -and $pg.Nav.Text) { $title = [string]$pg.Nav.Text } } catch {}
        $stack = New-Object System.Collections.Stack; $stack.Push($pg.Page)
        while ($stack.Count -gt 0) {
            $c = $stack.Pop()
            foreach ($ch in $c.Controls) { $stack.Push($ch) }
            if ($c -isnot [System.Windows.Forms.ButtonBase]) { continue }
            $tx = (([string]$c.Text) -replace '\s+', ' ').Trim()
            if ($tx.Length -lt 3) { continue }
            $ds = ''; try { $ds = [string]$tip.GetToolTip($c) } catch {}
            [void]$l.Add(@{ T = $tx; W = 'Page ' + $title; D = $ds; K = ''; Kind = 'ctl'; Id = ''; Page = [string]$pk; Ctl = $c })
        }
    }
    if (Get-Command Show-GBEditionPicker -ErrorAction Ignore) {
        [void]$l.Add(@{ T = 'Changer de modele : NEXUS, ARENA ou PURE'; W = 'GameBoost'; D = "Trois interfaces pour le meme GameBoost : complete, gaming ou tres simple. GameBoost se relance tout seul."; K = ''; Kind = 'action'; Id = 'fn.edition'
            Run = { $e2 = $null; try { $e2 = Show-GBEditionPicker -Owner $form } catch {}; if ($e2 -and $e2 -ne $Script:Edition) { Switch-GBEdition $e2 } } })
    }
    foreach ($e in $l) { $e.ST = ConvertTo-GBSearchText $e.T; $e.TW = [string[]]@(Get-GBSearchWords $e.T); $e.BW = [string[]]@(Get-GBSearchWords ($e.W + ' ' + $e.D)) }
    return , $l
}
# Resultats : d'abord les conseils pour le besoin exprime, puis les options classees par ressemblance
function Find-GBSearch($index, [string]$query) {
    $q = ConvertTo-GBSearchText $query
    if (-not $q) { return @($index | Where-Object { $_.Kind -eq 'action' } | Sort-Object { $_.W }, { $_.T }) }
    $res = New-Object System.Collections.ArrayList; $seen = @{}
    foreach ($need in $Script:SearchNeeds) {
        if ($q -notmatch $need.P) { continue }
        foreach ($to in $need.To) {
            $hits = @()
            if ($to.StartsWith('ctl:')) { $k = $to.Substring(4); $hits = @($index | Where-Object { $_.Kind -eq 'ctl' -and $_.ST.Contains($k) } | Select-Object -First 1) }
            elseif ($to.StartsWith('label:')) { $k = $to.Substring(6); $hits = @($index | Where-Object { $_.Kind -eq 'action' -and $_.ST.Contains($k) }) }
            else { $hits = @($index | Where-Object { $_.Kind -eq 'action' -and $_.Id -eq $to }) }
            foreach ($hit in $hits) {
                $key = [string]$hit.Kind + '|' + [string]$hit.Id + '|' + [string]$hit.T
                if ($seen.ContainsKey($key)) { continue }; $seen[$key] = 1
                $c2 = $hit.Clone(); $c2.W = 'Conseil'; $c2.D = [string]$need.Why; [void]$res.Add($c2)
            }
        }
    }
    $words = [string[]]@(Get-GBSearchWords $query)
    if ($words.Count -gt 0) {
        $scores = $null
        if (-not $Script:SearchEngineTried) { $Script:SearchEngineTried = $true; try { [void](Add-GBCompiled 'GBSearch' $Script:GBSearchSrc $null 'GBSearch') } catch {} }
        if ('GBSearch' -as [type]) {
            try {
                $titles = [string[][]]@(foreach ($e in $index) { , $e.TW }); $bodies = [string[][]]@(foreach ($e in $index) { , $e.BW })
                $alt = [string[][]]@(foreach ($w in $words) { , ([string[]]@(Get-GBSearchAlt $w)) })
                $scores = [GBSearch]::Rank($titles, $bodies, $words, $alt)
            } catch { $scores = $null }
        }
        if (-not $scores) {
            # secours sans le composant : le mot doit apparaitre tel quel
            $scores = @(foreach ($e in $index) { $s = 0; foreach ($w in $words) { if ($e.ST.Contains($w)) { $s += 20 } elseif ((($e.BW) -join ' ').Contains($w)) { $s += 8 } }; $s })
        }
        $ranked = New-Object System.Collections.ArrayList
        for ($i = 0; $i -lt $index.Count; $i++) { if ($scores[$i] -gt 0) { $e = $index[$i]; [void]$ranked.Add(@{ E = $e; Score = [int]$scores[$i] + $(if ($e.Kind -eq 'action') { 2 } else { 0 }) + [math]::Max(0, 6 - @($e.TW).Count) }) } }
        foreach ($x in @($ranked | Sort-Object { - $_.Score }, { $_.E.T } | Select-Object -First 60)) {
            $e = $x.E; $key = [string]$e.Kind + '|' + [string]$e.Id + '|' + [string]$e.T
            $k2 = 'texte|' + [string]$e.ST + '|' + [string]$e.W
            if ($seen.ContainsKey($key) -or $seen.ContainsKey($k2)) { continue }
            $seen[$k2] = 1
            [void]$res.Add($e)
        }
    }
    return @($res)
}
# Preferences d'interface (%APPDATA%\GameBoost\interface.json)
$Script:UiPrefsFile = Join-Path $AppDir 'interface.json'
$Script:UiPrefs = Read-GBJsonFile $Script:UiPrefsFile @{ NexusAdvanced = $false }
# NEXUS, page Optimisations : affiche ou replie les options avancees
function Set-GBNexusAdvanced([bool]$on, [switch]$NoSave) {
    $a = $Script:NxAdv; if (-not $a) { return }
    try {
        $a.Adv.Visible = $on; $a.Mes.Visible = $on; $a.Note.Visible = (-not $on)
        $a.Btn.Text = $(if ($on) { "Masquer les options avancees" } else { "Afficher les options avancees (11)" })
    } catch {}
    if (-not $NoSave) {
        $Script:UiPrefs.NexusAdvanced = $on
        try { $Script:UiPrefs | ConvertTo-Json | Set-Content -LiteralPath $Script:UiPrefsFile -Encoding UTF8 } catch {}
    }
}
# Montre une option d'une page : ouvre la page, amene l'option a l'ecran et la fait clignoter
function Show-GBSearchTarget($e) {
    if ($e.Run) { & $e.Run; return }
    if ($e.Kind -eq 'action') { [void](Invoke-GBAction $e.Id 'search'); return }
    try { if (-not $form.Visible -or $form.WindowState -eq "Minimized") { Show-GBMainFront } } catch {}
    try { Show-GBPage $e.Page } catch {}
    $c = $e.Ctl; if (-not $c -or $c.IsDisposed) { return }
    try { if (-not $c.Visible -and $Script:NxAdv) { Set-GBNexusAdvanced $true } } catch {}
    try { $p = $c.Parent; while ($p) { if ($p -is [System.Windows.Forms.ScrollableControl] -and $p.AutoScroll) { $p.ScrollControlIntoView($c) }; $p = $p.Parent } } catch {}
    try { [void]$c.Focus() } catch {}
    $acc = $cCyan; if ($cAccent) { $acc = $cAccent }
    if ($Script:SearchFlashT) { try { $Script:SearchFlashT.Stop(); if ($Script:SearchFlash.Ctl -and -not $Script:SearchFlash.Ctl.IsDisposed) { $Script:SearchFlash.Ctl.BackColor = $Script:SearchFlash.Back } } catch {} }
    $Script:SearchFlash = @{ Ctl = $c; Back = $c.BackColor; Hi = $acc; N = 0 }
    if (-not $Script:SearchFlashT) {
        $Script:SearchFlashT = New-Object System.Windows.Forms.Timer; $Script:SearchFlashT.Interval = 170
        $Script:SearchFlashT.Add_Tick({
            $st = $Script:SearchFlash
            try {
                if (-not $st.Ctl -or $st.Ctl.IsDisposed) { $this.Stop(); return }
                $st.N++
                if ($st.N -ge 7) { $st.Ctl.BackColor = $st.Back; $st.Ctl.Invalidate(); $this.Stop(); return }
                $st.Ctl.BackColor = $(if ($st.N % 2 -eq 1) { $st.Hi } else { $st.Back }); $st.Ctl.Invalidate()
            } catch { $this.Stop() }
        })
    }
    $Script:SearchFlashT.Stop(); $Script:SearchFlashT.Start()
}
function Show-GBSearch([string]$Query = '') {
    $acc = $cCyan; if ($cAccent) { $acc = $cAccent }
    $st = @{ Index = (Get-GBSearchIndex); Res = @(); Pick = $null }
    $d = New-GBDialog "Rechercher" 700 560
    $d.KeyPreview = $true
    $null = Add-DlgLabel $d "Rechercher" 16 8 300 30 $fontPage $acc
    $null = Add-DlgLabel $d "Ecris ce que tu cherches ou ton probleme : mon jeu rame, pc trop chaud, pas de son, micro..." 16 40 660 22 $fontUI $cMuted
    $tq = New-GBKsText $d 16 68 652 30; $tq.Font = $fontBold; $tq.Text = $Query
    $lv = New-GBKsList $d 16 104 652 330 @(@('Option', 330), @('Ou', 170), @('Raccourci', 140))
    $ld = Add-DlgLabel $d "" 16 442 652 38 $fontUI $cText
    $null = Add-DlgLabel $d "Fleches haut / bas : choisir.   Entree ou double-clic : y aller.   Echap : fermer." 16 486 500 22 $fontSmall $cMuted
    $bClose = Add-DlgButton $d "Fermer" 568 480 100
    $bClose.DialogResult = [System.Windows.Forms.DialogResult]::Cancel; $d.CancelButton = $bClose
    $setCur = { param($i)
        if ($lv.Items.Count -eq 0) { $ld.Text = "Rien trouve. Essaie un autre mot."; return }
        $i = [math]::Max(0, [math]::Min($lv.Items.Count - 1, [int]$i))
        $it = $lv.Items[$i]; Set-GBKsCurrent $lv $it; $it.EnsureVisible()
        $e = $it.Tag; $ld.Text = $(if ($e.D) { [string]$e.D } elseif ($e.Kind -eq 'ctl') { "Ouvre la " + $e.W.ToLower() + " et montre cette option." } else { "" })
    }
    $fill = {
        $st.Res = @(Find-GBSearch $st.Index $tq.Text)
        $lv.BeginUpdate(); $lv.Items.Clear()
        foreach ($e in $st.Res) {
            $it = New-Object System.Windows.Forms.ListViewItem([string]$e.T)
            [void]$it.SubItems.Add([string]$e.W); [void]$it.SubItems.Add([string]$e.K); $it.Tag = $e; [void]$lv.Items.Add($it)
        }
        $lv.EndUpdate()
        & $setCur 0
    }
    $go = { $it = Get-GBKsSelected $lv; if (-not $it) { return }; $st.Pick = $it.Tag; $d.Close() }
    $deb = New-Object System.Windows.Forms.Timer; $deb.Interval = 110; $deb.Add_Tick({ $this.Stop(); & $fill })
    $tq.Add_TextChanged({ $deb.Stop(); $deb.Start() })
    $lv.Add_SelectedIndexChanged({ $it = Get-GBKsSelected $lv; if ($it) { $e = $it.Tag; $ld.Text = $(if ($e.D) { [string]$e.D } elseif ($e.Kind -eq 'ctl') { "Ouvre la " + $e.W.ToLower() + " et montre cette option." } else { "" }) } })
    $lv.Add_DoubleClick({ & $go })
    $d.Add_KeyDown({
        $cur = Get-GBKsSelected $lv; $i = 0; if ($cur) { $i = $cur.Index }
        if ($_.KeyCode -eq 'Down') { & $setCur ($i + 1); $_.Handled = $true; $_.SuppressKeyPress = $true }
        elseif ($_.KeyCode -eq 'Up') { & $setCur ($i - 1); $_.Handled = $true; $_.SuppressKeyPress = $true }
        elseif ($_.KeyCode -eq 'PageDown') { & $setCur ($i + 10); $_.Handled = $true; $_.SuppressKeyPress = $true }
        elseif ($_.KeyCode -eq 'PageUp') { & $setCur ($i - 10); $_.Handled = $true; $_.SuppressKeyPress = $true }
        elseif ($_.KeyCode -eq 'Return') { $_.Handled = $true; $_.SuppressKeyPress = $true; & $go }
        if (-not $tq.Focused -and $_.KeyCode -ne 'Return') { [void]$tq.Focus() }
    })
    $d.Add_Shown({ if (-not $form.Visible) { $this.StartPosition = "Manual"; $wa = [System.Windows.Forms.Screen]::FromPoint([System.Windows.Forms.Cursor]::Position).WorkingArea; $this.Location = New-Object System.Drawing.Point(($wa.X + [int](($wa.Width - $this.Width) / 2)), ($wa.Y + [int](($wa.Height - $this.Height) / 2))); $this.TopMost = $true; $this.Activate() }; & $fill; [void]$tq.Focus(); $tq.Select($tq.Text.Length, 0) })
    try { [void]$d.ShowDialog($form) } finally { $deb.Stop(); $deb.Dispose(); $d.Dispose() }
    if ($st.Pick) { try { Show-GBSearchTarget $st.Pick } catch { Log ("Recherche : " + $_.Exception.Message) } }
}
function Open-GBSearchFromTray {
    $Script:TraySearchQuery = ''; try { if ($Script:TraySearchBox -and -not $Script:TraySearchBox.IsDisposed) { $Script:TraySearchQuery = [string]$Script:TraySearchBox.Text } } catch {}
    if (-not $Script:TraySearchT) {
        $Script:TraySearchT = New-Object System.Windows.Forms.Timer; $Script:TraySearchT.Interval = 70
        $Script:TraySearchT.Add_Tick({
            $this.Stop()
            try { if ($Script:TrayPanel -and -not $Script:TrayPanel.IsDisposed) { $Script:TrayPanelBusy = $false; $Script:TrayPanel.Close() } } catch {}
            try { Show-GBSearch $Script:TraySearchQuery } catch { try { Log ("Recherche : " + $_.Exception.Message) } catch {} }
        })
    }
    $Script:TraySearchT.Stop(); $Script:TraySearchT.Start()
}
# Loupe a droite de la barre de menus (les 3 modeles ont cette barre)
function Add-GBSearchMenuItem {
    if (-not $Script:Menu -or $Script:Menu.IsDisposed -or $Script:SearchMenuItem) { return }
    $it = New-Object System.Windows.Forms.ToolStripMenuItem
    $it.Text = "Rechercher"; if ([string]$Script:Edition -eq 'Pure') { $it.Text = "Chercher" }
    $it.Alignment = [System.Windows.Forms.ToolStripItemAlignment]::Right
    $it.ToolTipText = "Trouver n'importe quelle option (Ctrl+K)"
    $acc = $cCyan; if ($cAccent) { $acc = $cAccent }; $it.ForeColor = $acc
    $it.Add_Click({ Show-GBSearch })
    [void]$Script:Menu.Items.Add($it); $Script:SearchMenuItem = $it
}
if (Test-Path function:Register-GBAction) {
    Register-GBAction -Id 'app.search' -Label 'Rechercher une option...' -Menu 'GameBoost' -Order 1 -DefaultKey 'Ctrl+K' -Run { Show-GBSearch } -Description "Tape un mot pour trouver un reglage, un outil ou une page"
}
try { Add-GBStartHook { Add-GBSearchMenuItem } } catch {}
# Mise en page du modele : Build-GBLayoutNexus / Arena / Pure (NEXUS si celle du modele manque ou echoue)
function Invoke-GBLayout {
    $fn = 'Build-GBLayout' + $Script:Edition
    if (-not (Get-Command $fn -CommandType Function -ErrorAction SilentlyContinue)) { $fn = 'Build-GBLayoutNexus' }
    if (-not (Get-Command $fn -CommandType Function -ErrorAction SilentlyContinue)) { $Script:LayoutName = ''; return }
    $Script:LayoutName = $fn
    try { & $fn }
    catch {
        $why = $_.Exception.Message
        try { Log ("Mise en page " + (Get-GBEditionLabel $Script:Edition) + " : erreur (" + $why + ")") } catch {}
        if ($fn -ne 'Build-GBLayoutNexus' -and (Get-Command 'Build-GBLayoutNexus' -CommandType Function -ErrorAction SilentlyContinue)) {
            try { Log "Retour a la mise en page NEXUS pour cette fois" } catch {}
            try { $Script:Body.Controls.Clear() } catch {}
            $Script:LayoutName = 'Build-GBLayoutNexus'
            try { Build-GBLayoutNexus } catch { try { Log ("Mise en page NEXUS : erreur (" + $_.Exception.Message + ")") } catch {} }
        }
    }
}

# Verification toutes les minutes (socle) : 1) configuration, 2) turbo et carte graphique, 3) journal
Add-GBMinuteCheck 'config' {
    if (-not (Test-Path -LiteralPath $ConfigFile)) { try { Save-Config } catch {}; return "fichier de configuration absent : recree avec les reglages en cours" }
    $readable = $true
    try { $null = [System.IO.File]::ReadAllText($ConfigFile) | ConvertFrom-Json -ErrorAction Stop } catch { $readable = $false }
    if (-not $readable) { try { Save-Config } catch {}; return "fichier de configuration illisible : reecrit avec les reglages en cours" }
    $c = $Script:Config; $fix = @()
    if ($c.Edition -and (Resolve-GBEdition $c.Edition) -cne [string]$c.Edition) { $c.Edition = $Script:Edition; $fix += 'modele' }
    if ([int]$c.PurgeInterval -lt 30) { $c.PurgeInterval = 180; $fix += 'intervalle du vidage memoire' }
    if ([int]$c.OverlayCorner -lt 0 -or [int]$c.OverlayCorner -gt 3) { $c.OverlayCorner = 0; $fix += "coin de l'overlay" }
    if ($null -eq $c.Games) { $c.Games = @(); $fix += 'liste des jeux' }
    if ($null -eq $c.Whitelist) { $c.Whitelist = @($DefaultWhitelist); $fix += 'apps autorisees' }
    if ($fix.Count -gt 0) { try { Save-Config } catch {}; return ("configuration corrigee : " + ($fix -join ', ')) }
    return $null
}
Add-GBMinuteCheck 'turbo-gpu' {
    $out = @(); $c = $Script:Config
    # Processeur : seulement si GameBoost regle le turbo (cle de suivi TurboOrig), 2 lectures powercfg au plus
    if ($c.TurboOnlyInGame -or [int]$c.TurboOnMhz -gt 0 -or $c.TurboOrig) {
        $want = $null; try { $want = Get-GBTurboWant } catch {}
        $o = $c.TurboOrig
        if (-not $want) {
            if ($o -and $o.Scheme) { Update-GBTurboCap; $out += "processeur : reglages d'origine remis" }
        } elseif (-not $Script:TurboRefused -and -not $Script:TurboNoSupportLogged) {
            $need = $false; $sch = Get-ActiveScheme
            if (-not $o -or -not $o.Scheme -or $o.Scheme -ne $sch) { $need = $true }
            else {
                if ($null -ne $o.BAC) {
                    $exp = [int]$o.BAC; if ($want.BoostOff) { $exp = 0 }
                    $vb = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PERFBOOSTMODE'; if (-not $vb -or [int]$vb.AC -ne $exp) { $need = $true }
                }
                $mhz = [int]$want.Mhz; if ($want.BoostOff -and $null -eq $o.BAC -and $mhz -le 0) { $mhz = Get-GBCpuBaseMhz }
                if (-not $need -and $null -ne $o.FAC) {
                    $expF = [int]$o.FAC; if ($mhz -gt 0) { $expF = $mhz }
                    $vf = Get-GBPowerValue $sch 'SUB_PROCESSOR' 'PROCFREQMAX'; if (-not $vf -or [int]$vf.AC -ne $expF) { $need = $true }
                }
            }
            if ($need) { Update-GBTurboCap; $out += ("processeur : limite re-appliquee (" + $want.Txt + ")") }
        }
    }
    # Carte graphique : cle de suivi (GpuLastKey, GpuLocked, GpuPlSet) ; nvidia-smi seulement si l'etat voulu a change
    if ($c.GpuEco -or [int]$c.GpuOnMhz -gt 0 -or $c.GpuLocked -or $c.GpuPlSet -or ($c.GpuPowerMax -and $Script:Boosted)) {
        $gi = $Script:GpuCtlInfo
        if (-not $gi) {
            if (-not $Script:GpuCheckInit) { $Script:GpuCheckInit = $true; Update-GBGpuCap }   # jamais applique depuis l'ouverture
        } elseif ($gi.Smi) {
            $w = Get-GBGpuWant; $key = "" + $w.Mhz + "|" + $w.Power
            $lockOff = ($gi.CanLock -and (($w.Mhz -gt 0) -ne [bool]$c.GpuLocked))
            if ($key -ne $Script:GpuLastKey -or $lockOff -or ($w.Power -ne [bool]$c.GpuPlSet)) {
                Update-GBGpuCap
                $out += ("carte graphique : " + $(if ($w.Txt) { $w.Txt } else { "frequence et puissance d'origine" }) + " re-applique")
            }
        }
    }
    if ($out.Count -gt 0) { return ($out -join ' ; ') }
    return $null
}
Add-GBMinuteCheck 'journal' {
    $msg = $null
    try { if (-not (Test-Path -LiteralPath $LogDir)) { New-Item -ItemType Directory -Path $LogDir -Force | Out-Null; $msg = "dossier du journal recree" } }
    catch { return ("dossier du journal inaccessible : " + $_.Exception.Message) }
    # GameBoost peut rester ouvert plusieurs jours : un fichier par jour
    $today = Join-Path $LogDir ("GameBoost_" + (Get-Date -Format "yyyy-MM-dd") + ".log")
    if ($Script:LogFile -ne $today) { $Script:LogFile = $today }
    try { $fs = [System.IO.File]::Open($Script:LogFile, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::ReadWrite); $fs.Dispose() }
    catch { return ("journal inaccessible (" + $Script:LogFile + ") : " + $_.Exception.Message) }
    return $msg
}
# Minuteurs de la coque : verification chaque minute, crochets de demarrage 700 ms apres l'affichage
function Start-GBShellTimers {
    if ($Script:MinuteTimer) { return }
    $Script:MinuteTimer = New-Object System.Windows.Forms.Timer
    $Script:MinuteTimer.Interval = 60000
    $Script:MinuteTimer.Add_Tick({ if ($Script:Closing) { return }; try { Invoke-GBMinuteChecks } catch {} })
    $Script:MinuteTimer.Start()
    $Script:StartHookTimer = New-Object System.Windows.Forms.Timer
    $Script:StartHookTimer.Interval = 700
    $Script:StartHookTimer.Add_Tick({ $Script:StartHookTimer.Stop(); try { Invoke-GBStartHooks } catch {} })
    if ($Script:FormShown -or $form.Visible) { $Script:StartHookTimer.Start() }   # fenetre deja affichee (avant Application.Run)
    else { $form.Add_Shown({ try { $Script:StartHookTimer.Start() } catch {} }) }
}

# --- Disposition de la fenetre principale : navigation a gauche + 4 pages ---------------------------
# --- Composants communs des 3 modeles ---------------------------------------------------------
# Objets et fonctions dont le moteur a besoin quel que soit le modele : chaque Build-GBLayoutX les RANGE seulement (Set-GBPlace).
# Un objet non range reste invisible mais garde son etat ; tout ce que le moteur ou les minuteurs appellent supporte son absence.
$Script:IconFont = $null
foreach ($n in @("Segoe Fluent Icons", "Segoe MDL2 Assets")) {
    try { $f = New-Object System.Drawing.Font($n, [single]12); if ($f.Name -eq $n) { $Script:IconFont = $f; break }; $f.Dispose() } catch {}
}
# Tailles par defaut (celles de NEXUS) : chaque modele les fixe avec Set-GBShellSize et $Script:PageX / PageW avant de creer ses pages
if (-not $MainW) { $MainW = 920 }
if (-not $MainH) { $MainH = 640 }
$Script:RailW = 196; $Script:PageX = 196; $Script:PageW = $MainW - 196; $Script:Pad = 24; $Script:Inner = $Script:PageW - 2 * $Script:Pad
$Script:NavParent = $null

# Place un controle (parent $null = juste la taille et la position, sans le ranger)
function Set-GBPlace($c, $parent, $x, $y, $w, $h) {
    if (-not $c) { return }
    if ($parent -and $c.Parent -ne $parent) { if ($c.Parent) { $c.Parent.Controls.Remove($c) }; $parent.Controls.Add($c) }
    $c.Location = New-Object System.Drawing.Point([int]$x, [int]$y)
    if ($w -gt 0) { $c.Size = New-Object System.Drawing.Size([int]$w, [int]$h) }
}
function New-GBCard($parent, $x, $y, $w, $h, $title, $hint, $accent) {
    if ($Script:UiOK) { $p = New-Object GBCard; if ($accent) { $p.Accent = $accent } }
    else { $p = New-Object System.Windows.Forms.Panel; $p.BorderStyle = "FixedSingle" }
    $p.BackColor = $cPanel
    $p.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $p.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    if ($parent) { $parent.Controls.Add($p) }
    if ($title) { $hd = New-GBHeader $p $title $hint 16 10 ($w - 32) 22; if ($Script:UiOK -and $accent) { $hd.Accent = $accent } }
    return $p
}
# Page du modele : dans $Script:Body, a droite de la navigation (taille selon le modele) ; titre et sous-titre facultatifs
function New-GBPage($title, $sub, $parent = $Script:Body, $x = $Script:PageX, $y = 0, $w = $Script:PageW, $h = $MainH) {
    $p = New-Object System.Windows.Forms.Panel
    $p.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $p.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    $p.BackColor = $cBg; $p.Visible = $false
    if ($Script:UiOK) { [GBTheme]::DoubleBuffer($p) }
    if ($parent) { $parent.Controls.Add($p) }
    $iw = $w - 2 * $Script:Pad
    if ($title) {
        $t = New-Object System.Windows.Forms.Label; $t.Text = $title; $t.Font = $fontPage; $t.ForeColor = $cText
        $t.Location = New-Object System.Drawing.Point($Script:Pad, 16); $t.Size = New-Object System.Drawing.Size($iw, 30); $p.Controls.Add($t)
    }
    if ($sub) {
        $s = New-Object System.Windows.Forms.Label; $s.Text = $sub; $s.Font = $fontUI; $s.ForeColor = $cMuted; $s.AutoEllipsis = $true
        $s.Location = New-Object System.Drawing.Point($Script:Pad, 47); $s.Size = New-Object System.Drawing.Size($iw, 20); $p.Controls.Add($s)
    }
    return $p
}
function New-GBLabelIn($parent, $text, $x, $y, $w, $h, $font = $fontUI, $color = $cMuted) {
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $text; $l.Font = $font; $l.ForeColor = $color
    $l.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $l.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    if ($parent) { $parent.Controls.Add($l) }
    return $l
}
# Bouton existant transforme en tuile : titre + description (page Outils, resume de l'accueil)
function Set-GBTile($b, $parent, $title, $desc, $x, $y, $w, $h, $color) {
    Set-GBPlace $b $parent $x $y $w $h
    $b.Text = $title; $b.ForeColor = $color; $b.Font = $fontHud
    if ($Script:UiOK) { $b.Desc = $desc; $b.DescFont = $fontSmall; $b.Cut = 10 }
    else { $b.Text = $title + "`r`n" + $desc; $b.TextAlign = "MiddleLeft"; $b.Padding = New-Object System.Windows.Forms.Padding(10, 0, 0, 0) }
    if ($desc -and -not $tip.GetToolTip($b)) { $tip.SetToolTip($b, $desc) }
}
function New-GBTile($parent, $title, $desc, $x, $y, $w, $h, $color) {
    $b = New-GBButtonCtl; Set-GBTile $b $parent $title $desc $x $y $w $h $color; return $b
}

# Pages : cle -> @{ Nav; Page; Title; OnShow } ; $Script:PageOrder = ordre des raccourcis Page 1..N (defini par le modele)
$Script:Pages = [ordered]@{}
$Script:PageOrder = @()
$Script:CurrentPage = $null
# Element de navigation (generique : parent, position et taille au choix du modele ; le clic ouvre la page $key)
function New-GBNavItem($text, $glyph, $key, $y, $tipText, $parent = $Script:NavParent, $w = $Script:RailW, $h = 42, $x = 0) {
    if ($Script:UiOK) {
        $n = New-Object GBNavItem
        if ($Script:IconFont) { $n.Glyph = [string]$glyph; $n.GlyphFont = $Script:IconFont }
    } else {
        $n = New-Object System.Windows.Forms.Button; $n.FlatStyle = "Flat"; $n.FlatAppearance.BorderSize = 0; $n.TextAlign = "MiddleLeft"
        $n.Padding = New-Object System.Windows.Forms.Padding(18, 0, 0, 0); $n.FlatAppearance.MouseOverBackColor = $cSel; $n.BackColor = $cRail
    }
    $n.Text = $text; $n.Font = $fontNav; $n.ForeColor = $cText; $n.Tag = $key; $n.Cursor = [System.Windows.Forms.Cursors]::Hand
    $n.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $n.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    if ($parent) { $parent.Controls.Add($n) }
    $n.Add_Click({ Show-GBPage ([string]$this.Tag) })
    if ($tipText) { $tip.SetToolTip($n, $tipText) }
    return $n
}
# Affiche une page (sans animation : la navigation se fait aussi au clavier)
function Show-GBPage([string]$key) {
    if (-not $Script:Pages.Contains($key)) { return }
    $new = $Script:Pages[$key].Page
    if (-not $new) { return }
    $new.Visible = $true; $new.BringToFront()
    foreach ($k in @($Script:Pages.Keys)) {
        $pg = $Script:Pages[$k]; $on = ($k -eq $key)
        if (-not $on -and $pg.Page -and $pg.Page -ne $new) { $pg.Page.Visible = $false }
        if (-not $pg.Nav) { continue }
        if ($pg.Nav -is [System.Windows.Forms.ButtonBase]) {
            if ($on) { $pg.Nav.BackColor = $cSel; $pg.Nav.ForeColor = $cCyan } else { $pg.Nav.BackColor = $cRail; $pg.Nav.ForeColor = $cText }
        } else { try { $pg.Nav.Selected = $on } catch {} }
    }
    $Script:CurrentPage = $key
    if ($Script:Pages[$key].OnShow) { try { & $Script:Pages[$key].OnShow } catch { Log ("Page " + $key + " : " + $_.Exception.Message) } }
}
# Le modele est prevenu quand un bloc apparait ou disparait (bandeau pilote, tiroir GPU) : $Script:OnLayoutChange = { ... }
$Script:OnLayoutChange = $null
function Invoke-GBLayoutChanged { if ($Script:OnLayoutChange) { try { & $Script:OnLayoutChange } catch {} } }

# Ancienne disposition plate : seuls les titres et libelles sans nom (aucune variable ne les tient) sont liberes.
# Les controles du moteur ($btnBoost, $chk*, $gear*, jauges...) sont retires de la fenetre mais JAMAIS liberes : le modele les range.
$Script:GBEngineRefs = New-Object System.Collections.Generic.HashSet[object]
foreach ($v in @(Get-Variable -Scope Script -ErrorAction SilentlyContinue)) {
    $val = $v.Value
    if ($val -is [System.Windows.Forms.Control]) { [void]$Script:GBEngineRefs.Add($val) }
    elseif ($val -is [System.Collections.IDictionary]) { foreach ($x in @($val.Values)) { if ($x -is [System.Windows.Forms.Control]) { [void]$Script:GBEngineRefs.Add($x) } } }
    elseif ($val -is [System.Collections.IList] -and $val.Count -lt 200) { foreach ($x in @($val)) { if ($x -is [System.Windows.Forms.Control]) { [void]$Script:GBEngineRefs.Add($x) } } }
}
$oldMain = @($form.Controls | Where-Object { $_ -ne $Script:Body -and $_ -ne $Script:Menu })
$form.SuspendLayout()
$form.Controls.Clear()
foreach ($c in $oldMain) { if (-not $Script:GBEngineRefs.Contains($c)) { try { $c.Dispose() } catch {} } }
$oldMain = $null
# Coque : $Script:Body (sous le menu) cree par le socle ; sinon un Body de secours de la meme forme
if ($null -eq $Script:MenuH) { $Script:MenuH = 0 }
if (-not $Script:Body) {
    $Script:Body = New-Object System.Windows.Forms.Panel
    $Script:Body.Location = New-Object System.Drawing.Point(0, [int]$Script:MenuH); $Script:Body.Size = New-Object System.Drawing.Size($MainW, $MainH)
    $Script:Body.BackColor = $cBg
    if ($Script:UiOK) { [GBTheme]::DoubleBuffer($Script:Body) }
}
if ($Script:Body.Parent -ne $form) { $form.Controls.Add($Script:Body) }
if ($Script:Menu -and $Script:Menu.Parent -ne $form) { $form.Controls.Add($Script:Menu) }

# Bouton GPU ON / ECO : ECO = frequence de la carte graphique limitee hors jeu (plus froide, plus silencieuse), sans limite pendant le boost
# (d'autres boutons peuvent refleter l'etat : $Script:GpuViews / $Script:TurboViews, mis a jour avec le bouton principal)
$Script:GpuViews = New-Object System.Collections.ArrayList
$Script:TurboViews = New-Object System.Collections.ArrayList
$Script:BtnGpu = New-GBButtonCtl
$Script:BtnGpu.Font = $fontHud
