$form.Controls.Remove($gearGpu)
$gearGpu.Add_Click({ Show-GpuSettings; Update-GBGpuButton })
function Update-GBGpuButton {
    foreach ($b in @(@($Script:BtnGpu) + @($Script:GpuViews))) {
        if (-not $b) { continue }
        if ($Script:Config.GpuEco) { $b.Text = "GPU : ECO"; $b.ForeColor = $cCyan }
        else { $b.Text = "GPU : ON"; $b.ForeColor = $cGreen }
    }
}
function Switch-GBGpuMode {
    $i = Get-GBGpuCtlInfo
    # Carte non reglable directement (AMD, Intel, ancienne NVIDIA...) : la fenetre explique et propose le logiciel du fabricant
    if (-not ($i.Smi -and $i.CanLock)) { Show-GpuSettings; Update-GBGpuButton; return }
    $Script:Config.GpuEco = -not [bool]$Script:Config.GpuEco; Save-Config
    Update-GBGpuButton
    $Script:GpuLastKey = $null
    Update-GBGpuCap
}
$Script:BtnGpu.Add_Click({ Switch-GBGpuMode })
$Script:GpuTipText = ("ON : la carte graphique monte a sa frequence maximale (ou celle choisie avec l'engrenage).`r`n" +
                      "ECO : frequence limitee hors jeu, carte plus froide et ventilateurs plus calmes. Pendant le boost, plus aucune limite.`r`n" +
                      "Remis comme avant quand tu fermes GameBoost ou avec TOUT RESTAURER.")
$tip.SetToolTip($Script:BtnGpu, $Script:GpuTipText)
Update-GBGpuButton

