$form.Controls.Remove($gearTurbo)
$gearTurbo.Add_Click({ Show-TurboSettings; Update-GBTurboButton })
function Update-GBTurboButton {
    foreach ($b in @(@($Script:BtnTurbo) + @($Script:TurboViews))) {
        if (-not $b) { continue }
        if ($Script:Config.TurboOnlyInGame) { $b.Text = "TURBO : OFF"; $b.ForeColor = $cCyan }
        else { $b.Text = "TURBO : ON"; $b.ForeColor = $cYellow }
    }
}
function Switch-GBTurbo {
    $Script:Config.TurboOnlyInGame = -not [bool]$Script:Config.TurboOnlyInGame; Save-Config
    Update-GBTurboButton
    Update-GBTurboCap
}
$Script:BtnTurbo.Add_Click({ Switch-GBTurbo })
$Script:TurboTipText = ("ON : turbo normal (le processeur monte a son maximum au moindre travail et chauffe).`r`n" +
