    $lb = New-Object System.Windows.Forms.ListBox
    $lb.Location = New-Object System.Drawing.Point(16, 60); $lb.Size = New-Object System.Drawing.Size(314, 112)
    $lb.BackColor = $cDeep; $lb.ForeColor = $cText; $lb.BorderStyle = "None"; $lb.IntegralHeight = $false; $lb.AllowDrop = $true
    $lb.DrawMode = "OwnerDrawFixed"; $lb.ItemHeight = [int](22 * [math]::Max(1.0, [double]$Script:DpiScale)); $lb.Tag = $side
    if ($Script:UiOK) { [GBTheme]::DoubleBuffer($lb) }
