# Taille du tiroir et place des deux listes (une seule liste s'il n'y a qu'une carte graphique) : a appeler pendant Build-GBLayoutX
function Set-GBGpuDrawerLayout([int]$w, [int]$h = 184) {
    $c = $Script:CardGpuApps
    $c.Size = New-Object System.Drawing.Size($w, $h)
    if ($Script:CardGpuAppsHdr) { $Script:CardGpuAppsHdr.Width = $w - 32 }
    $lh = [math]::Max(40, $h - 72)
    $gcw = [int](($w - 32 - 16) / 2)
    $I = $Script:GpuLists['I']; $D = $Script:GpuLists['D']
    if ($Script:GpuHybrid) {
        $I.Lb.Visible = $true; $I.Hdr.Visible = $true
        $I.Hdr.SetBounds(16, 38, $gcw, 18); $I.Lb.SetBounds(16, 60, $gcw, $lh)
        $D.Hdr.SetBounds((16 + $gcw + 16), 38, $gcw, 18); $D.Lb.SetBounds((16 + $gcw + 16), 60, $gcw, $lh)
    } else {
        $I.Lb.Visible = $false; $I.Hdr.Visible = $false
        $D.Hdr.SetBounds(16, 38, ($w - 32), 18); $D.Lb.SetBounds(16, 60, ($w - 32), $lh)
    }
}
Set-GBGpuDrawerLayout 676 184
# Une ligne : nom de l'appli, carte prevue au prochain lancement (si elle change), pourcentage
$Script:DrawGpuItem = {
    param($sender, $e)
    if ($e.Index -lt 0) { return }
    $it = $sender.Items[$e.Index]; $g = $e.Graphics; $r = $e.Bounds
    $sel = (($e.State -band [System.Windows.Forms.DrawItemState]::Selected) -ne 0)
    $bg = $sender.BackColor; if ($sel -and -not $it.Placeholder) { $bg = $cSel }
    $br = New-Object System.Drawing.SolidBrush($bg); $g.FillRectangle($br, $r); $br.Dispose()
    $fl = [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::NoPrefix -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::SingleLine
    if ($it.Placeholder) { [System.Windows.Forms.TextRenderer]::DrawText($g, [string]$it.Name, $fontSmall, (New-Object System.Drawing.Rectangle(($r.X + 8), $r.Y, ($r.Width - 10), $r.Height)), $cMuted, $fl); return }
    $pw = [int](48 * [math]::Max(1.0, [double]$Script:DpiScale))
    $pc = [int][math]::Round([double]$it.Pct); $pcol = $cText; if ($pc -ge 50) { $pcol = $cYellow }
    [System.Windows.Forms.TextRenderer]::DrawText($g, ("" + $pc + " %"), $fontUI, (New-Object System.Drawing.Rectangle(($r.Right - $pw - 6), $r.Y, $pw, $r.Height)), $pcol, ($fl -bor [System.Windows.Forms.TextFormatFlags]::Right))
    $right = $r.Right - $pw - 10
    if ($it.Move) {
        $mt = [System.Windows.Forms.TextRenderer]::MeasureText($g, [string]$it.Move, $fontSmall, $r.Size, $fl).Width
        [System.Windows.Forms.TextRenderer]::DrawText($g, [string]$it.Move, $fontSmall, (New-Object System.Drawing.Rectangle(($right - $mt), $r.Y, $mt, $r.Height)), $cGreen, $fl)
        $right -= $mt + 6
    }
    $nc = $cText; if ($sel) { $nc = $cCyan }; $nm = [string]$it.Name; if ($it.Sys) { $nc = $cMuted; $nm += "  (Windows)" }
    if ($sel) { $ba = New-Object System.Drawing.SolidBrush($cGreen); $g.FillRectangle($ba, $r.X, $r.Y + 3, 2, $r.Height - 6); $ba.Dispose() }
    [System.Windows.Forms.TextRenderer]::DrawText($g, $nm, $fontUI, (New-Object System.Drawing.Rectangle(($r.X + 8), $r.Y, [math]::Max(10, $right - $r.X - 8), $r.Height)), $nc, $fl)
}
# Faire tourner une appli sur une carte (D = carte graphique dediee, I = puce integree, A = Windows decide)
function Set-GBAppGpuSide([string]$path, [string]$side) {
    $pref = 0; $to = "Windows decide"
    if ($side -eq 'D') { $pref = 2; $to = $Script:MainGpu.Short } elseif ($side -eq 'I') { $pref = 1; $to = $Script:IGpu.Short }
    try {
        Set-GBAppGpuPref $path $pref
        Log ([IO.Path]::GetFileNameWithoutExtension($path) + " tournera sur " + $to + " (a son prochain lancement)")
    } catch { Log ("Carte graphique pour " + $path + " : echec (" + $_.Exception.Message + ")") }
    Update-GBGpuDrawer
}
function Update-GBGpuDrawer {
    if (-not $Script:GpuDrawerOpen -or $Script:GpuDragging -or -not $Script:GpuLists) { return }
    $gd = $Script:LastGpuDetail
    $prefs = @{}; foreach ($a in @(Get-GBAppGpuList)) { $prefs[([string]$a.Path).ToLower()] = [int]$a.Pref }
    $by = @{ I = @{}; D = @{} }
    $use = @{ I = $null; D = $null }
    if ($gd) {
        foreach ($ad in @($gd.Adapters)) { $sd = 'D'; if ($ad.Kind -eq 'integree') { $sd = 'I' }; if ($null -eq $use[$sd] -or $ad.Usage -gt $use[$sd]) { $use[$sd] = $ad.Usage } }
        if ($Script:PidPath.Count -gt 400) { $Script:PidPath = @{} }
        foreach ($kv in $gd.Procs.GetEnumerator()) {
            $parts = ([string]$kv.Key).Split('|'); $procId = [int]$parts[1]
            if ($procId -le 4) { continue }
            $info = Get-GpuInfoByLuid $parts[0]; $sd = 'D'; if ($info.Kind -eq 'integree') { $sd = 'I' }
            if (-not $Script:GpuHybrid) { $sd = 'D' }
            # (un numero de processus peut etre reutilise par Windows : le cache est lie au numero ET au nom du programme)
            $p = Get-Process -Id $procId -ErrorAction SilentlyContinue; if (-not $p) { continue }
            $ck = "" + $procId + "|" + $p.ProcessName
            $pi = $Script:PidPath[$ck]
            if (-not $pi) {
                $path = $null; try { $path = Get-ProcessPath $p } catch {}
                $pi = @{ Name = $p.ProcessName; Path = $path }; $Script:PidPath[$ck] = $pi
            }
            $key = ([string]$pi.Name).ToLower()
            $cur = $by[$sd][$key]
            if (-not $cur) {
                $sys = (-not $pi.Path) -or ([string]$pi.Path -like ($env:SystemRoot + '\*'))
                $cur = @{ Name = $pi.Name; Path = $pi.Path; Pct = 0.0; Sys = $sys; Move = ''; Placeholder = $false }; $by[$sd][$key] = $cur
            }
            $cur.Pct = [math]::Min(100.0, $cur.Pct + [double]$kv.Value)
        }
    }
    foreach ($sd in @('I', 'D')) {
        $L = $Script:GpuLists[$sd]; $lb = $L.Lb
        $u = $use[$sd]
        if ($sd -eq 'I') { $L.Hdr.Text = "GPU PROCESSEUR" + $(if ($null -ne $u) { "  " + $u + " %" } else { "" }) + $(if ($Script:IGpu) { "  |  " + $Script:IGpu.Short } else { "" }); $L.Hdr.ForeColor = $cViolet }
        else { $L.Hdr.Text = "GPU CARTE" + $(if ($null -ne $u) { "  " + $u + " %" } else { "  au repos" }) + $(if ($Script:MainGpu) { "  |  " + $Script:MainGpu.Short } else { "" }); $L.Hdr.ForeColor = $cCyan }
        $items = @($by[$sd].Values | Sort-Object { $_.Pct } -Descending | Select-Object -First 12)
        foreach ($it in $items) {
            if (-not $it.Path -or -not $Script:GpuHybrid) { continue }
            $pf = $prefs[([string]$it.Path).ToLower()]
            if ($sd -eq 'I' -and $pf -eq 2) { $it.Move = "-> " + $Script:MainGpu.Short + " au prochain lancement" }
            elseif ($sd -eq 'D' -and $pf -eq 1) { $it.Move = "-> " + $Script:IGpu.Short + " au prochain lancement" }
        }
        # Rien de change depuis la derniere seconde (memes applis, memes %) : pas de redessin
        $sig = (@($items | ForEach-Object { [string]$_.Name + ':' + [int][math]::Round([double]$_.Pct) + ':' + $_.Move }) -join '|') + '#' + $(if ($gd) { 1 } else { 0 })
        if ($sig -eq $L.Sig -and $items.Count -gt 0) { continue }
        $L.Sig = $sig
        $selName = $null; if ($lb.SelectedItem -and -not $lb.SelectedItem.Placeholder) { $selName = $lb.SelectedItem.Name }
        $lb.BeginUpdate(); $lb.Items.Clear()
        foreach ($it in $items) { [void]$lb.Items.Add($it) }
        if ($items.Count -eq 0) {
            $msg = "Aucune appli en ce moment"; if (-not $gd) { $msg = "Mesure indisponible sur ce PC" } elseif ($sd -eq 'D' -and $Script:GpuHybrid -and -not $use['D']) { $msg = "Carte au repos (aucune appli)" }
            [void]$lb.Items.Add(@{ Name = $msg; Placeholder = $true })
        }
        if ($selName) { for ($k = 0; $k -lt $lb.Items.Count; $k++) { if ($lb.Items[$k].Name -eq $selName) { $lb.SelectedIndex = $k; break } } }
        $lb.EndUpdate()
    }
}
$gpuMenu = New-Object System.Windows.Forms.ContextMenuStrip
$Script:GpuMenuD = $gpuMenu.Items.Add("Faire tourner sur la carte graphique"); $Script:GpuMenuD.Tag = 'D'
$Script:GpuMenuI = $gpuMenu.Items.Add("Faire tourner sur la puce integree"); $Script:GpuMenuI.Tag = 'I'
$Script:GpuMenuA = $gpuMenu.Items.Add("Laisser Windows decider"); $Script:GpuMenuA.Tag = 'A'
[void]$gpuMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
$gpuMenuAll = $gpuMenu.Items.Add("Toutes les applis reglees..."); $gpuMenuAll.Tag = 'all'
$gpuMenu.add_Opening({
    param($sender, $e)
    $lb = $sender.SourceControl; $it = $null; if ($lb) { $it = $lb.SelectedItem }
    $ok = ($it -and -not $it.Placeholder -and -not $it.Sys -and $it.Path)
    foreach ($m in @($Script:GpuMenuD, $Script:GpuMenuI, $Script:GpuMenuA)) { $m.Enabled = [bool]($ok -and $Script:GpuHybrid) }
    if ($Script:MainGpu) { $Script:GpuMenuD.Text = "Faire tourner sur " + $Script:MainGpu.Short + " (hautes performances)" }
    if ($Script:IGpu) { $Script:GpuMenuI.Text = "Faire tourner sur " + $Script:IGpu.Short + " (economie d'energie)" }
})
$gpuMenu.add_ItemClicked({
    param($sender, $e)
    $tag = [string]$e.ClickedItem.Tag
    if ($tag -eq 'all') { $sender.Close(); [void]$form.BeginInvoke([Action]{ Show-AppGpuSettings; Update-GBGpuDrawer }); return }
    $lb = $sender.SourceControl; if (-not $lb -or -not $lb.SelectedItem) { return }
    $it = $lb.SelectedItem; if ($it.Placeholder -or $it.Sys -or -not $it.Path) { return }
    Set-GBAppGpuSide ([string]$it.Path) $tag
})
foreach ($L in $Script:GpuLists.Values) {
    $lb = $L.Lb
    $lb.add_DrawItem($Script:DrawGpuItem)
    $lb.ContextMenuStrip = $gpuMenu
    $tip.SetToolTip($lb, "Glisse une appli vers l'autre carte (ou clic droit) : elle y tournera a son prochain lancement. Les applis de Windows ne se deplacent pas.")
    $lb.add_MouseDown({
        param($sender, $e)
        $Script:GpuDragStart = $e.Location; $Script:GpuDragIdx = $sender.IndexFromPoint($e.Location)
        if ($Script:GpuDragIdx -ge 0) { $sender.SelectedIndex = $Script:GpuDragIdx }
    })
    $lb.add_MouseMove({
        param($sender, $e)
        if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Left -or $Script:GpuDragIdx -lt 0 -or -not $Script:GpuHybrid) { return }
        if ([math]::Abs($e.X - $Script:GpuDragStart.X) + [math]::Abs($e.Y - $Script:GpuDragStart.Y) -lt 6) { return }
        $it = $sender.Items[$Script:GpuDragIdx]; $Script:GpuDragIdx = -1
        if (-not $it -or $it.Placeholder -or $it.Sys -or -not $it.Path) { return }
        $Script:GpuDragging = $true
        try { [void]$sender.DoDragDrop(('GBGPU|' + $sender.Tag + '|' + $it.Path), [System.Windows.Forms.DragDropEffects]::Move) } finally { $Script:GpuDragging = $false }
    })
    $lb.add_MouseUp({ $Script:GpuDragIdx = -1 })
    $lb.add_DragOver({
        param($sender, $e)
        $dd = $null; try { $dd = [string]$e.Data.GetData([string]) } catch {}
        if ($dd -like 'GBGPU|*' -and $dd.Split('|')[1] -ne [string]$sender.Tag) { $e.Effect = [System.Windows.Forms.DragDropEffects]::Move } else { $e.Effect = [System.Windows.Forms.DragDropEffects]::None }
    })
    $lb.add_DragDrop({
        param($sender, $e)
        $dd = $null; try { $dd = [string]$e.Data.GetData([string]) } catch {}
        if ($dd -notlike 'GBGPU|*') { return }
        $parts = $dd.Split('|', 3); if ($parts[1] -eq [string]$sender.Tag) { return }
        Set-GBAppGpuSide $parts[2] ([string]$sender.Tag)
    })
}
# Fleche dans le titre des jauges GPU (bas = ouvrir, haut = fermer) ; aucune fleche si le modele ne range pas le tiroir
function Update-GBMeterArrows {
    if (-not $Script:Meters) { return }
    $ar = [string][char]0x25BE; if ($Script:GpuDrawerOpen) { $ar = [string][char]0x25B4 }
    foreach ($k in @('Dgpu', 'Igpu')) {
        $m = $Script:Meters[$k]; if (-not $m) { continue }
        $base = ([string]$m.Label) -replace ('\s*[' + [char]0x25BE + [char]0x25B4 + ']$'), ''
        if (-not $Script:CardGpuApps.Parent) { $m.Label = $base; continue }
        $m.Label = $base + " " + $ar
        $t = [string]$tip.GetToolTip($m); if ($t -notmatch 'Clique') { $tip.SetToolTip($m, ($t + "`r`nClique : quelles applis utilisent cette carte (glisser pour changer de carte).").Trim()) }
    }
}
# Temps reel, comme le Gestionnaire des taches : mise a jour chaque seconde, seulement tiroir ouvert, range, visible et fenetre visible
$Script:GpuLiveTimer = New-Object System.Windows.Forms.Timer
$Script:GpuLiveTimer.Interval = 1000
$Script:GpuLiveTimer.Add_Tick({
    if (-not $Script:GpuDrawerOpen -or -not $Script:CardGpuApps.Parent -or -not $form.Visible -or $form.WindowState -eq 'Minimized' -or $Script:BusyDepth -gt 0 -or $Script:GpuDragging) { return }
    if ($Script:GpuDrawerPage -and $Script:CurrentPage -ne $Script:GpuDrawerPage) { return }
    try {
        $gu = Get-GpuUsage
        $Script:LastGpuDetail = $gu
        if ($Script:Meters) {
            if ($null -ne $gu.Dedicated -and ($Script:MeterHasD -or -not $Script:MeterHasI)) { $Script:Meters.Dgpu.SetValue([float]$gu.Dedicated, ("" + $gu.Dedicated + " %")) }
            if ($null -ne $gu.Integrated -and $Script:MeterHasI) { $Script:Meters.Igpu.SetValue([float]$gu.Integrated, ("" + $gu.Integrated + " %")) }
        }
        Update-GBGpuDrawer
    } catch {}
})
function Switch-GBGpuDrawer {
    # Tiroir non range par le modele : la fenetre complete des applis par carte graphique
    if (-not $Script:CardGpuApps.Parent) { $Script:GpuDrawerOpen = $false; $Script:GpuLiveTimer.Stop(); try { Show-AppGpuSettings } catch {}; return }
    $Script:GpuDrawerOpen = -not $Script:GpuDrawerOpen
    $Script:CardGpuApps.Visible = $Script:GpuDrawerOpen
    Update-GBMeterArrows
    Invoke-GBLayoutChanged
    if ($Script:GpuDrawerOpen) {
        # Mesures directes de Windows : chaque seconde ; repli WMI (plus lent) : toutes les 2 s
        $Script:GpuLiveTimer.Interval = $(if ($Script:Perf) { 1000 } else { 2000 })
        if (-not $Script:LastGpuDetail) { try { $Script:LastGpuDetail = Get-GpuUsage } catch {} }
        Update-GBGpuDrawer; $Script:GpuLiveTimer.Start()
    } else { $Script:GpuLiveTimer.Stop() }
}
$Script:BtnGpuApps = $null
if ($Script:Meters) {
    foreach ($k in @('Dgpu', 'Igpu')) { $m = $Script:Meters[$k]; $m.Cursor = [System.Windows.Forms.Cursors]::Hand; $m.Add_Click({ Switch-GBGpuDrawer }) }
} else {
    # Interface Windows classique (pas de jauges) : petit bouton a la place de la fleche (range par le modele)
    $Script:BtnGpuApps = New-GBButtonCtl; $Script:BtnGpuApps.Text = "Applis par carte graphique"; $Script:BtnGpuApps.Font = $fontSmall
    $Script:BtnGpuApps.Add_Click({ Switch-GBGpuDrawer })
}

# Nouveau pilote de carte graphique : bandeau (s'il est range) + point jaune sur la tuile Pilotes et sur la page qui la contient
function Set-GBDriverNotice([string]$text) {
    if (-not $Script:HomeBanner) { return }
    $on = [bool]$text
    if ($Script:UiOK) {
        if ($on) { $Script:HomeBanner.Desc = $text; $Script:HomeBanner.Invalidate() }
        try { $btnDrivers.Badge = $on } catch {}
        foreach ($k in @($Script:Pages.Keys)) {
            $pg = $Script:Pages[$k]
            if ($pg.Nav -and $pg.Nav -isnot [System.Windows.Forms.ButtonBase] -and ($k -eq 'tools' -or $pg.Page -eq $btnDrivers.Parent)) { try { $pg.Nav.Badge = $on } catch {} }
        }
    } elseif ($on) { $Script:HomeBanner.Text = "NOUVEAU PILOTE GRAPHIQUE DISPONIBLE`r`n" + $text }
    if ($Script:BannerOn -ne $on) { $Script:BannerOn = $on; $Script:HomeBanner.Visible = $on; Invoke-GBLayoutChanged }
}
function Update-GBHomeTiles {
    if (-not $Script:TileLevel) { return }
    $lv = Get-GameLevelNow
    if ($lv -ge 0) { $Script:TileLevel.Text = "NIVEAU " + $Script:GameLevels[$lv].L.ToUpper(); $Script:TileLevel.ForeColor = $Script:GameLevels[$lv].C }
    else { $Script:TileLevel.Text = "NIVEAU PERSONNALISE"; $Script:TileLevel.ForeColor = $cYellow }
    $n = @($Script:Config.Games).Count
    if ($n -eq 0) { $gt = "AUCUN JEU AJOUTE" } elseif ($n -eq 1) { $gt = "1 JEU SUIVI" } else { $gt = "" + $n + " JEUX SUIVIS" }
    $Script:TileGames.Text = $gt
    $wl = -1; try { $wl = [int]$Script:Config.WinLevel } catch {}
    if ($wl -ge 1 -and $wl -lt $Script:WinLevels.Count) { $Script:TileWin.Text = "WINDOWS " + $Script:WinLevels[$wl].L.ToUpper(); $Script:TileWin.ForeColor = $Script:WinLevels[$wl].C }
    else { $Script:TileWin.Text = "WINDOWS D'ORIGINE"; $Script:TileWin.ForeColor = $cViolet }
    if ($Script:UiOK) {
        # Descriptions en clair : ce que c'est, puis ce que fait le clic
        if ($lv -ge 0) { $Script:TileLevel.Desc = "Force du boost pendant tes parties. Clique pour la changer." }
        else { $Script:TileLevel.Desc = "Options choisies a la main. Clique pour les voir." }
        if ($n -eq 0) { $Script:TileGames.Desc = "Ajoute tes jeux : le boost demarre avec eux." }
        else { $Script:TileGames.Desc = "Le boost demarre avec eux. Clique pour gerer la liste." }
        if ($wl -ge 1 -and $wl -lt $Script:WinLevels.Count) { $Script:TileWin.Desc = "Windows est allege (annulable). Clique pour regler." }
        else { $Script:TileWin.Desc = "Windows pas encore allege. Clique pour l'optimiser." }
        foreach ($t in @($Script:TileLevel, $Script:TileGames, $Script:TileWin)) { $t.Invalidate() }
    }
    if ($Script:GamesEmpty) { $Script:GamesEmpty.Visible = ($lstGames.Items.Count -eq 0) }
}

# Raccourcis de page Ctrl+1..9 selon $Script:PageOrder (de secours : le module raccourcis les remplace par les actions page.N)
$form.KeyPreview = $true
$form.Add_KeyDown({
    param($sender, $e)
    if ($Script:GBKeysByActions) { return }
    if (-not $e.Control -or $e.Alt) { return }
    $kc = [string]$e.KeyCode; $n = 0
    if ($kc -like 'D[1-9]') { $n = [int][string]$kc[1] } elseif ($kc -like 'NumPad[1-9]') { $n = [int][string]$kc[6] }
    $order = @($Script:PageOrder)
    if ($n -ge 1 -and $n -le $order.Count) { Show-GBPage ([string]$order[$n - 1]); $e.Handled = $true; $e.SuppressKeyPress = $true }
})

# Fin commune de chaque Build-GBLayoutX : mise en page reprise, premiere page affichee, resumes a jour
function Complete-GBLayout {
    try { $form.ResumeLayout() } catch {}
    Update-GBMeterArrows
    $first = $null
    foreach ($k in @($Script:PageOrder)) { if ($Script:Pages.Contains([string]$k)) { $first = [string]$k; break } }
    if (-not $first -and $Script:Pages.Count -gt 0) { $first = @($Script:Pages.Keys)[0] }
    if ($first) { Show-GBPage $first }
    Update-GBHomeTiles
    if ($Script:GpuLatest -and @($Script:GpuLatest | Where-Object { $_.State -eq 'update' }).Count -gt 0) { Set-GpuLatestResult $Script:GpuLatest $false }
    $Script:LayoutDone = $true
}

# Pages cachees preparees (fenetres Windows creees) juste apres l'affichage : le 1er clic sur une page est instantane
$Script:WarmTimer = New-Object System.Windows.Forms.Timer
$Script:WarmTimer.Interval = 700
$Script:WarmTimer.Add_Tick({
    $Script:WarmTimer.Stop(); $Script:WarmTimer.Dispose()
    try {
        $stack = New-Object System.Collections.Stack
        foreach ($k in @($Script:Pages.Keys)) { if ($k -ne $Script:CurrentPage -and $Script:Pages[$k].Page) { $stack.Push($Script:Pages[$k].Page) } }
        while ($stack.Count -gt 0) { $c = $stack.Pop(); if (-not $c.IsHandleCreated) { [void]$c.Handle }; foreach ($ch in $c.Controls) { $stack.Push($ch) } }
    } catch {}
    # Turbo seulement en jeu : applique apres l'affichage (powercfg ne retarde pas l'ouverture)
    if ($Script:Config.TurboOnlyInGame -or $Script:Config.TurboOrig -or [int]$Script:Config.TurboOnMhz -gt 0) { Update-GBTurboCap }
    # Carte graphique : mode choisi, ou remise d'origine apres un arret brutal de GameBoost
    if ($Script:Config.GpuEco -or $Script:Config.GpuLocked -or $Script:Config.GpuPlSet -or [int]$Script:Config.GpuOnMhz -gt 0) { Update-GBGpuCap }
    # Crochets de demarrage des modules (socle : Add-GBStartHook)
    if (Test-Path function:Invoke-GBStartHooks) { try { Invoke-GBStartHooks } catch {} }
})
$form.Add_Shown({ if ($Script:WarmTimer) { try { $Script:WarmTimer.Start() } catch {} } })

# --- Modele NEXUS : navigation a gauche + pages (Accueil, Mes jeux, Optimisations, Capteurs, Outils) ---------------------------
# Accueil : tuiles, jauges, tiroir GPU et journal ; le journal descend sous les blocs ouverts (bandeau pilote, tiroir)
function Update-GBHomeLayout {
    if (-not $Script:PgHome -or -not $Script:CardPerf) { return }
    $s = [double]$Script:PgHome.Width / $Script:PageW
    $y = 80
    if ($Script:BannerOn) { $y += 58 + 12 }   # (Visible vaut faux tant que la page Accueil est cachee)
    foreach ($t in @($Script:TileLevel, $Script:TileGames, $Script:TileWin)) { $t.Top = [int]($y * $s) }
    $y += 74 + 14
    $Script:CardPerf.Top = [int]($y * $s); $y += 122 + 14
    if ($Script:GpuDrawerOpen) { $Script:CardGpuApps.Top = [int]($y * $s); $y += 184 + 14 }
    if ($Script:DispCard -and $Script:DispCard.Parent -eq $Script:PgHome) { $Script:DispCard.Top = [int]($y * $s); $y += 104 + 14 }
    # Journal : la place qui reste (cache si le tiroir GPU ne lui en laisse presque plus)
    $lh = $MainH - 20 - $y
    $Script:CardLog.Visible = ($lh -ge 90)
    if ($lh -ge 90) { $Script:CardLog.Top = [int]($y * $s); $Script:CardLog.Height = [int]($lh * $s) }
}
# Couleur d'une temperature selon le niveau (module capteurs), gris si inconnue
function Get-GBNxTempColor($t, [string]$kind) {
    if ($null -eq $t) { return $cMuted }
    try { return (Get-GBTempColor (Get-GBTempLevel $t $kind)) } catch { return $cText }
}
function Format-GBNxTemp($t) {
    if ($null -eq $t) { return "n/d" }
    try { return (Format-GBTemp $t) } catch { return ("" + [int][math]::Round([double]$t) + " " + [char]0xB0 + "C") }
}
# Bande compacte de l'accueil : CPU et GPU en degres, aux couleurs du niveau
function Update-GBNexusHomeTemps($o) {
    if (-not $Script:NxHomeCpu -or -not $o) { return }
    $Script:NxHomeCpu.Text = "CPU " + (Format-GBNxTemp $o.CpuTemp); $Script:NxHomeCpu.ForeColor = Get-GBNxTempColor $o.CpuTemp 'cpu'
    $Script:NxHomeGpu.Text = "GPU " + (Format-GBNxTemp $o.GpuTemp); $Script:NxHomeGpu.ForeColor = Get-GBNxTempColor $o.GpuTemp 'gpu'
}
# Une ligne de detail : cachee si la valeur est inconnue (rien n'est invente)
function Set-GBNxLine($l, [string]$text) { if ($text) { $l.Text = $text; $l.Visible = $true } else { $l.Text = ""; $l.Visible = $false } }
# Page Capteurs : 4 cartes (courbe 10 min, min/max, source, frequences, puissance, ventilateurs)
function Update-GBNexusSensors {
    if (-not $Script:NxSensCards) { return }
    $o = $null; try { $o = Get-GBSensors } catch {}
    if (-not $o) { return }
    Update-GBNexusHomeTemps $o
    $C = $Script:NxSensCards
    # Processeur
    $src = [string]$o.CpuTempSrc; $why = $null; try { $why = [string]$o.Why.CpuTemp } catch {}
    $sub = $(if ($src) { "source : " + $src } elseif ($why) { $why } else { "temperature non donnee par Windows" })
    Update-GBSparkCtl $C.Cpu.Spark 'CpuTemp' 'cpu' 'TEMPERATURE' $sub
    Set-GBNxLine $C.Cpu.L1 $(if ($o.CpuMhz) { "Frequence : " + ([math]::Round([double]$o.CpuMhz / 1000, 2)).ToString([Globalization.CultureInfo]::InvariantCulture) + " GHz" } else { "" })
    Set-GBNxLine $C.Cpu.L2 $(if ($o.CpuFanRpm) { "Ventilateur : " + [int]$o.CpuFanRpm + " tr/min" } else { "" })
    Set-GBNxLine $C.Cpu.L3 $(if ($Script:Config.TurboOnlyInGame) { "Turbo coupe hors jeu (TURBO : OFF)" } else { "Turbo normal (TURBO : ON)" })
    # Carte graphique
    $gsub = [string]$o.GpuName; if ($o.GpuSleep) { $gsub = "carte en veille (economie d'energie)" } elseif ($o.GpuTempSrc) { $gsub += "  |  " + $o.GpuTempSrc }
    Update-GBSparkCtl $C.Gpu.Spark 'GpuTemp' 'gpu' 'TEMPERATURE' $gsub
    $f = @(); if ($o.GpuClockMhz) { $f += ("" + [int]$o.GpuClockMhz + " MHz") }; if ($o.GpuMemMhz) { $f += ("memoire " + [int]$o.GpuMemMhz + " MHz") }
    Set-GBNxLine $C.Gpu.L1 $(if ($f.Count) { "Frequence : " + ($f -join ", ") } else { "" })
    $pw = @(); if ($null -ne $o.GpuPowerW) { $pw += ("Puissance : " + [int][math]::Round([double]$o.GpuPowerW) + " W") }; if ($null -ne $o.GpuHotspot) { $pw += ("point chaud " + (Format-GBNxTemp $o.GpuHotspot)) }
    Set-GBNxLine $C.Gpu.L2 ($pw -join "  |  ")
    $fan = ""; if ($null -ne $o.GpuFanPct) { $fan = "Ventilateurs : " + [int]$o.GpuFanPct + " %" } elseif ($o.GpuFanRpm) { $fan = "Ventilateurs : " + [int]$o.GpuFanRpm + " tr/min" }
    Set-GBNxLine $C.Gpu.L3 $fan
    # Puce graphique du processeur
    $isub = $(if ($o.IGpuName) { [string]$o.IGpuName } elseif ($Script:IGpu) { [string]$Script:IGpu.Short } else { "aucune puce integree" })
    if ($null -eq $o.IGpuTemp -and $Script:IGpu) { $isub += "  |  meme puce que le processeur" }
    Update-GBSparkCtl $C.Igpu.Spark 'IGpuTemp' 'cpu' 'TEMPERATURE' $isub
    $iu = $null; if ($Script:NxLastSample) { $iu = $Script:NxLastSample.IgpuU }
    Set-GBNxLine $C.Igpu.L1 $(if ($null -ne $iu -and $Script:IGpu) { "Charge : " + [int][math]::Round([double]$iu) + " %" } else { "" })
    Set-GBNxLine $C.Igpu.L2 $(if ($o.IGpuClockMhz) { "Frequence : " + [int]$o.IGpuClockMhz + " MHz" } else { "" })
    Set-GBNxLine $C.Igpu.L3 $(if ($null -eq $o.IGpuTemp -and $null -ne $o.CpuTemp -and $Script:IGpu) { "Processeur : " + (Format-GBNxTemp $o.CpuTemp) } else { "" })
    # Disques
    $ss = @($o.SsdTemps | Where-Object { $_ })
    Update-GBSparkCtl $C.Ssd.Spark 'SsdMax' 'ssd' 'TEMPERATURE' $(if ($ss.Count) { "le plus chaud de " + $ss.Count + " disque(s)" } else { "aucune temperature de disque donnee par Windows" })
    $i = 0
    foreach ($l in @($C.Ssd.L1, $C.Ssd.L2, $C.Ssd.L3)) {
        if ($i -lt $ss.Count) { $d = $ss[$i]; Set-GBNxLine $l ([string]$d.Name + " : " + (Format-GBNxTemp $d.Temp)); $l.ForeColor = Get-GBNxTempColor $d.Temp 'ssd' } else { Set-GBNxLine $l "" }
        $i++
    }
}
# Toutes les 5 s (crochet de mesure) : seulement la page visible est mise a jour, fenetre ouverte
function Invoke-GBNexusSensorTick($s) {
    if ($s) { $Script:NxLastSample = $s }
    if (-not $form.Visible -or $form.WindowState -eq 'Minimized') { return }
    if ($Script:CurrentPage -eq 'sensors') { Update-GBNexusSensors }
    elseif ($Script:CurrentPage -eq 'home' -and $Script:NxHomeCpu) { $o = $null; try { $o = Get-GBSensors } catch {}; Update-GBNexusHomeTemps $o }
}

function Build-GBLayoutNexus {
    # Modules presents (chaque ajout NEXUS est protege : sans le module, la disposition reste celle d'avant)
    $hasSens  = (Test-Path function:Get-GBSensors) -and (Test-Path function:Update-GBSparkCtl)
    $hasMon   = (Test-Path function:Show-MonitorsPanel)
    $hasLinks = (Test-Path function:Show-LinkedAppsPanel)
    $hasKeys  = (Test-Path function:Show-HotkeysPanel) -or (Test-Path function:Get-GBActionKey)
    $hasKeyFn = (Test-Path function:Get-GBActionKey)

    # Coque : 920 x 640 sous la barre de menus
    if (Test-Path function:Set-GBShellSize) { Set-GBShellSize 920 640 }
    else {
        $Script:MainW = 920; $Script:MainH = 640
        $Script:Body.Size = New-Object System.Drawing.Size(920, 640)
        $form.ClientSize = New-Object System.Drawing.Size(920, (640 + [int]$Script:MenuH))
    }
    $Script:RailW = 196; $Script:PageX = 196; $Script:PageW = $MainW - 196; $Script:Pad = 24; $Script:Inner = $Script:PageW - 2 * $Script:Pad
    $RailW = $Script:RailW; $PageW = $Script:PageW; $Pad = $Script:Pad; $Inner = $Script:Inner
    $body = $Script:Body

    # Colonne de gauche : logo, pages, etat + BOOST
    $rail = New-Object System.Windows.Forms.Panel
    $rail.Location = New-Object System.Drawing.Point(0, 0); $rail.Size = New-Object System.Drawing.Size($RailW, $MainH); $rail.BackColor = $cRail
    $body.Controls.Add($rail)
    $Script:NexusRail = $rail; $Script:NavParent = $rail
    if ($Script:UiOK) {
        $ttl.Font = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 17; $ttl.Sub = ""
        Set-GBPlace $ttl $rail 16 16 ($RailW - 32) 34
    } else { $null = New-GBLabelIn $rail "GAMEBOOST" 16 16 ($RailW - 32) 30 $fontBoost $cCyan }
    $null = New-GBLabelIn $rail ("v" + $AppVersion) 18 52 40 18 $fontSmall $cMuted
    # Modele : clic = NEXUS / ARENA / PURE
    $edSw = New-GBLabelIn $rail ("MODELE NEXUS " + [char]0x25BE) 58 50 ($RailW - 32 - 40) 20 $fontSmall $cCyan
    $edSw.TextAlign = "MiddleLeft"
    $edSw.Add_MouseEnter({ $this.ForeColor = $cText }); $edSw.Add_MouseLeave({ $this.ForeColor = $cCyan })
    if (Test-Path function:Add-GBEditionSwitch) { Add-GBEditionSwitch $edSw }

    Set-GBPlace $Script:BtnGpu $rail 14 ($MainH - 280) ($RailW - 28 - 30) 36
    Set-GBPlace $gearGpu $rail ($RailW - 14 - 26) ($MainH - 280 + 7) 26 22
    Set-GBPlace $Script:BtnTurbo $rail 14 ($MainH - 236) ($RailW - 28 - 30) 36
    Set-GBPlace $gearTurbo $rail ($RailW - 14 - 26) ($MainH - 236 + 7) 26 22
    foreach ($gb in @($gearGpu, $gearTurbo)) { $gb.BackColor = $cRail; $gb.FlatAppearance.MouseOverBackColor = $cRail; $gb.FlatAppearance.MouseDownBackColor = $cRail }

    $sep = New-Object System.Windows.Forms.Panel
    $sep.Location = New-Object System.Drawing.Point(16, ($MainH - 186)); $sep.Size = New-Object System.Drawing.Size(($RailW - 32), 1); $sep.BackColor = $cLine
    $rail.Controls.Add($sep)
    $null = New-GBLabelIn $rail "MODE JEU" 16 ($MainH - 176) ($RailW - 32) 18 $fontSmall $cMuted
    Set-GBPlace $lblStatus $rail 16 ($MainH - 156) ($RailW - 32) 44
    $lblStatus.Font = $fontBold
    Set-GBPlace $btnBoost $rail 14 ($MainH - 108) ($RailW - 28) 52
    $btnBoost.Font = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Black") 12.5
    Set-GBPlace $chkAuto $rail 14 ($MainH - 46) ($RailW - 28) 26
    $chkAuto.Text = "Boost automatique"
    $tip.SetToolTip($chkAuto, "Le boost demarre tout seul quand un de tes jeux se lance, et tout est remis quand tu le quittes.")
    $tip.SetToolTip($btnBoost, "Lance ou arrete le boost (aussi depuis l'icone pres de l'horloge)")

    # --- Page Accueil : resume, performances en direct, journal
    $pgHome = New-GBPage "Accueil" "Ton PC en un coup d'oeil. BOOST (a gauche) ne garde que ton jeu, Discord et l'essentiel."
    $Script:PgHome = $pgHome
    Set-GBPlace $Script:HomeBanner $pgHome $Pad 80 $Inner 58
    $tileW = [int](($Inner - 24) / 3)
    Set-GBPlace $Script:TileLevel $pgHome $Pad 80 $tileW 74
    Set-GBPlace $Script:TileGames $pgHome ($Pad + $tileW + 12) 80 $tileW 74
    Set-GBPlace $Script:TileWin $pgHome ($Pad + 2 * ($tileW + 12)) 80 ($Inner - 2 * ($tileW + 12)) 74
    $Script:CardPerf = New-GBCard $pgHome $Pad 168 $Inner 122 "Performances en direct" "mesurees toutes les 5 secondes"
    # Bande de temperatures (module capteurs) : a droite de la ligne des FPS, sans surcharger la carte
    $tempW = 0; if ($hasSens) { $tempW = 172 }
    if ($Script:Meters) {
        $null = Set-GBMeterHost $Script:CardPerf 16 42 ($Inner - 32) 46 $cPanel
        Set-GBPlace $lblStats $Script:CardPerf 16 94 ($Inner - 32 - $tempW) 20
        $lblStats.Font = $fontUI; $lblStats.AutoEllipsis = $true
    } else {
        Set-GBPlace $lblStats $Script:CardPerf 16 40 ($Inner - 32 - $tempW) 72
    }
    $Script:NxHomeCpu = $null; $Script:NxHomeGpu = $null
    if ($hasSens) {
        $ty = 94; if (-not $Script:Meters) { $ty = 40 }
        $Script:NxHomeCpu = New-GBLabelIn $Script:CardPerf "CPU n/d" ($Inner - 16 - $tempW) $ty 84 20 $fontBold $cMuted
        $Script:NxHomeGpu = New-GBLabelIn $Script:CardPerf "GPU n/d" ($Inner - 16 - $tempW + 88) $ty 84 20 $fontBold $cMuted
        foreach ($l in @($Script:NxHomeCpu, $Script:NxHomeGpu)) {
            $l.TextAlign = "MiddleRight"; $l.Cursor = [System.Windows.Forms.Cursors]::Hand
            $l.Add_Click({ Show-GBPage 'sensors' })
            $tip.SetToolTip($l, "Temperatures en direct. Clique : page Capteurs (courbes sur 10 minutes).")
        }
    }
    # Tiroir des applis par carte graphique, sous les performances
    Set-GBPlace $Script:CardGpuApps $pgHome $Pad 304 $Inner 184
    Set-GBGpuDrawerLayout $Inner 184
    $Script:GpuDrawerPage = 'home'
    if ($Script:BtnGpuApps) { Set-GBPlace $Script:BtnGpuApps $Script:CardPerf ($Inner - 16 - 190) 8 190 24 }
    # Ecran et FPS : luminosite, limite de FPS, frequence (sous les performances)
    $logY = 304
    if (Test-Path function:New-GBDisplayCard) { $null = New-GBDisplayCard $pgHome $Pad 304 $Inner; $logY = 304 + 104 + 14 }
    $Script:CardLog = New-GBCard $pgHome $Pad $logY $Inner ($MainH - $logY - 20) "Journal" "ce que fait GameBoost, en direct"
    Set-GBPlace $txtLog $Script:CardLog 12 40 ($Inner - 24) ($MainH - $logY - 20 - 52)
    $txtLog.Anchor = "Top, Bottom, Left, Right"; $txtLog.BorderStyle = "None"
    $Script:OnLayoutChange = { Update-GBHomeLayout }

    # --- Page Mes jeux : liste des jeux + apps autorisees
    $pgGames = New-GBPage "Mes jeux" "Le boost s'active pour ces jeux. Les apps autorisees ne sont jamais fermees pendant le boost."
    $gW = 404; $wW = $Inner - $gW - 16; $cH = $MainH - 80 - 20
    $cardGames = New-GBCard $pgGames $Pad 80 $gW $cH "Mes jeux" "clic droit = profil du jeu"
    Set-GBPlace $lstGames $cardGames 16 42 ($gW - 32) 268
    $lstGames.BackColor = $cDeep; $lstGames.BorderStyle = "None"; $lstGames.IntegralHeight = $false
    $Script:GamesEmpty = New-GBLabelIn $cardGames ("Aucun jeu dans ta liste." + "`r`n" + "Ajoute ton jeu ci-dessous, ou laisse la detection des jeux populaires.") 30 130 ($gW - 60) 56 $fontUI $cMuted
    $Script:GamesEmpty.BackColor = $cDeep; $Script:GamesEmpty.TextAlign = "MiddleCenter"; $Script:GamesEmpty.BringToFront()
    Set-GBPlace $btnRemove $cardGames 16 318 ($gW - 32) 28
    $btnRemove.Text = "Retirer le jeu selectionne"; $btnRemove.ForeColor = $cRed
    Set-GBPlace $chkKnown $cardGames 16 356 ($gW - 32) 24
    $sep2 = New-Object System.Windows.Forms.Panel
    $sep2.Location = New-Object System.Drawing.Point(16, 392); $sep2.Size = New-Object System.Drawing.Size(($gW - 32), 1); $sep2.BackColor = $cLine
    $cardGames.Controls.Add($sep2)
    $null = New-GBLabelIn $cardGames "AJOUTER UN JEU" 16 402 ($gW - 32) 20 $fontHud $cCyan
    Set-GBPlace $btnBrowse $cardGames 16 426 ($gW - 32) 30
    $btnBrowse.Text = "Choisir le .exe du jeu..."; $btnBrowse.ForeColor = $cGreen
    $null = New-GBLabelIn $cardGames "ou un programme ouvert (lance d'abord ton jeu) :" 16 464 ($gW - 32) 18 $fontSmall $cMuted
    Set-GBPlace $cmbRunning $cardGames 16 486 ($gW - 32 - 108) 28
    Set-GBPlace $btnAddRunning $cardGames ($gW - 16 - 100) 484 100 30
    $btnAddRunning.Text = "Ajouter"; $btnAddRunning.ForeColor = $cGreen
    $tip.SetToolTip($cmbRunning, "Programmes ouverts avec une fenetre : choisis ton jeu puis clique sur Ajouter")

    $cardWl = New-GBCard $pgGames ($Pad + $gW + 16) 80 $wW $cH "Apps autorisees" "" $cGreen
    Set-GBPlace $txtWhite $cardWl 16 42 ($wW - 32) 396
    $txtWhite.BackColor = $cDeep; $txtWhite.BorderStyle = "None"
    $hw = [int](($wW - 32 - 8) / 2)
    Set-GBPlace $btnAddApp $cardWl 16 446 $hw 30
    Set-GBPlace $btnRemoveApp $cardWl (16 + $hw + 8) 446 ($wW - 32 - $hw - 8) 30
    foreach ($b in @($btnAddApp, $btnRemoveApp)) { $b.Font = $fontUI; $b.Padding = New-Object System.Windows.Forms.Padding(0) }
    $btnAddApp.Text = "+ Ajouter"; $btnRemoveApp.Text = "Retirer"
    $null = New-GBLabelIn $cardWl "Une par ligne, sans .exe. Discord, Steam et les launchers y sont deja." 16 484 ($wW - 32) 40 $fontSmall $cMuted

    # --- Page Optimisations : niveau gaming + interrupteurs
    $pgOpt = New-GBPage "Optimisations" "Tout ce que le boost change est remis comme avant a la fin de la partie."
    $cardLvl = New-GBCard $pgOpt $Pad 80 $Inner 100 "Niveau gaming" "glisse : les options en dessous se cochent" $cCyan
    Set-GBPlace $sldGame $cardLvl 16 38 ($Inner - 32 - 150) 30
    $sldGame.BackColor = $cPanel
    Set-GBPlace $btnReco $cardLvl ($Inner - 16 - 136) 38 136 28
    $btnReco.Text = "Recommandes"; $btnReco.ForeColor = $cGreen
    Set-GBPlace $lblGameDesc $cardLvl 16 72 ($Inner - 32 - 150) 20
    $lblGameDesc.AutoEllipsis = $true
    Set-GBPlace $lblGameCur $cardLvl ($Inner - 16 - 136) 72 136 20
    $lblGameCur.TextAlign = "MiddleRight"
    $colW = [int](($Inner - 32 - 20) / 2); $xL = 16; $xR = 16 + $colW + 20; $rowH = 27
    function Set-GBRow($chk, $card, $x, $row, $gear, $text, [int]$indent = 0, [int]$extra = 0) {
        $w = $colW - $indent; if ($gear) { $w -= 28 }; $w -= $extra
        Set-GBPlace $chk $card ($x + $indent) (38 + $row * $rowH) $w 24
        if ($text -and $chk.Enabled) { $chk.Text = $text }
        if ($gear) { Set-GBPlace $gear $card ($x + $colW - 24) (39 + $row * $rowH) 24 22; $gear.BackColor = $cPanel; $gear.FlatAppearance.MouseOverBackColor = $cPanel; $gear.FlatAppearance.MouseDownBackColor = $cPanel }
    }
    $cardBoost = New-GBCard $pgOpt $Pad 192 $Inner 154 "Pendant le boost" "engrenage = reglages" $cCyan
    Set-GBRow $chkClose    $cardBoost $xL 0 $gearClose    "Fermer les autres applications"
    Set-GBRow $chkForce    $cardBoost $xL 1 $null         "Forcer la fermeture (risque de perte)" 20
    Set-GBRow $chkServices $cardBoost $xL 2 $gearServices "Services inutiles en pause"
    Set-GBRow $chkRam      $cardBoost $xL 3 $null         "Liberer la RAM des autres programmes"
    Set-GBRow $chkPower    $cardBoost $xR 0 $gearPower    "Alimentation au maximum"
    Set-GBRow $chkPrio     $cardBoost $xR 1 $gearPrio     "Priorite CPU haute pour le jeu"
    Set-GBRow $chkLowBg    $cardBoost $xR 2 $gearLowBg    "Launchers en priorite basse"
    Set-GBRow $chkReopen   $cardBoost $xR 3 $null         "Rouvrir les applis fermees apres le jeu"
    $cardAdv = New-GBCard $pgOpt $Pad 358 $Inner 154 "Anti-saccades et avance" "tout est remis a la fin" $cViolet
    Set-GBRow $chkStandby  $cardAdv $xL 0 $gearStandby    "Anti-saccades (cache RAM)" 0 72
    Set-GBPlace $btnPurge $cardAdv ($xL + $colW - 28 - 66) 38 62 24
    Set-GBRow $chkDvr      $cardAdv $xL 1 $null           "Couper l'enregistrement Xbox (Game Bar)"
    Set-GBRow $chkRP       $cardAdv $xL 2 $null           "Point de restauration avant le boost"
    if ($chkGpuPref.Enabled) { Set-GBRow $chkGpuPref $cardAdv $xL 3 $null "Carte graphique puissante (portables)" }
    else { Set-GBRow $chkGpuPref $cardAdv $xL 3 $null ""; $chkGpuPref.Text = "Carte puissante : inutile (1 seule carte)" }
    Set-GBRow $chkGpu      $cardAdv $xR 0 $null           "Priorite GPU et planificateur aux jeux"
    Set-GBRow $chkPlan     $cardAdv $xR 1 $null           "USB, PCIe et processeur au maximum"
    Set-GBRow $chkNetwork  $cardAdv $xR 2 $null           "Reseau : Nagle coupe (jeux TCP / MMO)"
    Set-GBRow $chkMouse    $cardAdv $xR 3 $null           "Desactiver l'acceleration de la souris"
    $cardMes = New-GBCard $pgOpt $Pad 524 $Inner 100 "Mesure et demarrage" "" $cYellow
    if ($chkFps.Enabled) { Set-GBRow $chkFps $cardMes $xL 0 $null "Mesurer les FPS en jeu (PresentMon)" }
    else { Set-GBRow $chkFps $cardMes $xL 0 $null ""; $chkFps.Text = "FPS : PresentMon.exe introuvable" }
    Set-GBRow $chkMeasure  $cardMes $xL 1 $null           "Mode comparaison : mesurer SANS optimiser"
    Set-GBRow $chkStartup  $cardMes $xR 0 $null           "Lancer GameBoost avec Windows (reduit)"
    $tip.SetToolTip($chkForce, "Les applis sont fermees de force : ce qui n'est pas enregistre dedans est perdu. Les apps autorisees ne sont jamais fermees.")
    $tip.SetToolTip($chkPower, "Plan d'alimentation 'Performances maximales' pendant le boost (remis a la fin).")
    $tip.SetToolTip($chkClose, "Demande aux applis ouvertes (sauf les apps autorisees) de se fermer pendant le boost.")
    $tip.SetToolTip($chkServices, "Met en pause des services Windows inutiles pendant le jeu (impression, telemetrie...). Relances a la fin.")
    $tip.SetToolTip($chkRam, "Libere la memoire des programmes en arriere-plan au debut du boost.")
    $tip.SetToolTip($chkPrio, "Le processeur s'occupe du jeu en premier.")
    $tip.SetToolTip($chkReopen, "Les applis fermees par le boost sont rouvertes quand tu arretes de jouer.")

    # --- Page allegee : l'essentiel d'abord. Les options avancees sont repliees (bouton en haut a droite),
    #     et l'explication de l'option survolee s'affiche sous le titre (2 lignes).
    $Script:NxOptSub = @($pgOpt.Controls | Where-Object { $_ -is [System.Windows.Forms.Label] -and $_.Location.Y -eq 47 })[0]
    $Script:NxOptSubText = "Tout est remis comme avant apres la partie. Survole une option pour voir ce qu'elle fait."
    if ($Script:NxOptSub) { $Script:NxOptSub.Location = New-Object System.Drawing.Point($Pad, 44); $Script:NxOptSub.Size = New-Object System.Drawing.Size($Inner, 36); $Script:NxOptSub.Text = $Script:NxOptSubText }
    foreach ($c in @($chkClose, $chkForce, $chkServices, $chkRam, $chkPower, $chkPrio, $chkLowBg, $chkReopen, $chkStandby, $chkDvr, $chkRP, $chkGpuPref, $chkGpu, $chkPlan, $chkNetwork, $chkMouse, $chkFps, $chkMeasure, $chkStartup)) {
        $c.Add_MouseEnter({ try { $h = [string]$tip.GetToolTip($this); if ($h -and $Script:NxOptSub) { $Script:NxOptSub.ForeColor = $cText; $Script:NxOptSub.Text = $h } } catch {} })
        $c.Add_MouseLeave({ try { if ($Script:NxOptSub) { $Script:NxOptSub.ForeColor = $cMuted; $Script:NxOptSub.Text = $Script:NxOptSubText } } catch {} })
    }
    $advBtn = New-GBButtonCtl
    Set-GBPlace $advBtn $pgOpt ($Pad + $Inner - 270) 14 270 28
    $advNote = New-GBCard $pgOpt $Pad 358 $Inner 112 "Options avancees" "masquees pour garder la page simple" $cViolet
    $null = New-GBLabelIn $advNote "Anti-saccades, enregistrement Xbox, point de restauration, carte graphique des portables, reseau, souris, mesure des FPS, demarrage avec Windows." 16 38 ($Inner - 32) 36 $fontUI $cText
    $null = New-GBLabelIn $advNote "Une option precise ? Cherche-la avec Ctrl+K." 16 78 ($Inner - 32 - 190) 20 $fontSmall $cMuted
    $advShow = New-GBButtonCtl; $advShow.Text = "Afficher"; $advShow.ForeColor = $cGreen
    Set-GBPlace $advShow $advNote ($Inner - 16 - 170) 72 170 28
    $Script:NxAdv = @{ Adv = $cardAdv; Mes = $cardMes; Note = $advNote; Btn = $advBtn }
    $advBtn.Add_Click({ Set-GBNexusAdvanced (-not [bool]$Script:UiPrefs.NexusAdvanced) })
    $advShow.Add_Click({ Set-GBNexusAdvanced $true })
    Set-GBNexusAdvanced ([bool]$Script:UiPrefs.NexusAdvanced) -NoSave

    # --- Page Capteurs (module capteurs) : 4 cartes avec courbes 10 min, et les boutons qui refroidissent
    $pgSens = $null; $Script:NxSensCards = $null
    if ($hasSens) {
        $pgSens = New-GBPage "Capteurs" "Temperatures en direct, courbes des 10 dernieres minutes. Rien n'est invente : n/d = non donne par Windows."
        $scw = [int](($Inner - 14) / 2); $sch = 222
        $cards = [ordered]@{}
        foreach ($cd in @(@('Cpu', 'Processeur', $cCyan, 0, 0), @('Gpu', 'Carte graphique', $cCyan, 1, 0), @('Igpu', 'GPU du processeur', $cViolet, 0, 1), @('Ssd', 'Disques SSD', $cGreen, 1, 1))) {
            $cx = $Pad + $cd[3] * ($scw + 14); $cy = 80 + $cd[4] * ($sch + 14)
            $card = New-GBCard $pgSens $cx $cy $scw $sch $cd[1] "" $cd[2]
            $sp = New-GBSparkCtl
            Set-GBPlace $sp $card 16 40 ($scw - 32) 112
            $ls = @(); for ($i = 0; $i -lt 3; $i++) { $ls += (New-GBLabelIn $card "" 16 (158 + $i * 19) ($scw - 32) 18 $fontSmall $cMuted); $ls[$i].AutoEllipsis = $true }
            $cards[$cd[0]] = @{ Card = $card; Spark = $sp; L1 = $ls[0]; L2 = $ls[1]; L3 = $ls[2] }
        }
        $Script:NxSensCards = $cards
        # Rappels pour refroidir : memes boutons que la colonne de gauche (etat partage)
        $by = 80 + 2 * ($sch + 14) + 2
        $bT = New-GBButtonCtl; Set-GBPlace $bT $pgSens $Pad $by 150 36; $bT.Font = $fontHud
        $bG = New-GBButtonCtl; Set-GBPlace $bG $pgSens ($Pad + 162) $by 150 36; $bG.Font = $fontHud
        $bT.Add_Click({ Switch-GBTurbo; if ($Script:CurrentPage -eq 'sensors') { Update-GBNexusSensors } })
        $bG.Add_Click({ Switch-GBGpuMode })
        $tip.SetToolTip($bT, $Script:TurboTipText); $tip.SetToolTip($bG, $Script:GpuTipText)
        [void]$Script:TurboViews.Add($bT); [void]$Script:GpuViews.Add($bG)
        Update-GBTurboButton; Update-GBGpuButton
        $null = New-GBLabelIn $pgSens "Trop chaud ? TURBO : OFF et GPU : ECO refroidissent le PC hors jeu. Tout revient au maximum pendant le boost." ($Pad + 326) ($by - 2) ($Inner - 326) 40 $fontSmall $cMuted
        # Mise a jour toutes les 5 s, seulement page visible (crochet de mesure du socle, sinon petit minuteur)
        if (Test-Path function:Add-GBSampleHook) { Add-GBSampleHook { param($s) Invoke-GBNexusSensorTick $s } }
        else {
            $Script:NxSensTimer = New-Object System.Windows.Forms.Timer; $Script:NxSensTimer.Interval = 5000
            $Script:NxSensTimer.Add_Tick({ try { Invoke-GBNexusSensorTick $null } catch {} }); $Script:NxSensTimer.Start()
        }
    }

    # --- Page Outils : tuiles (ecrans, lancements lies et raccourcis si les modules sont la)
    $pgTools = New-GBPage "Outils" "Par famille : jeu (bleu), materiel (vert), Windows (violet), GameBoost (jaune). Une option introuvable ? Ctrl+K."
    $tiles = New-Object System.Collections.ArrayList
    [void]$tiles.Add(@($btnWinCfg, "CONFIG WINDOWS", "Confidentialite, pubs, applis, nettoyage.", $cViolet))
    [void]$tiles.Add(@($btnGames, "MES PARTIES", "Historique, FPS, overlay, sauvegardes.", $cCyan))
    [void]$tiles.Add(@($btnUninst, "DESINSTALLATION PROFONDE", "Un programme et tous ses restes.", $cYellow))
    [void]$tiles.Add(@($btnDrivers, "PILOTES", "Pilotes certifies pour ton materiel.", $cCyan))
    [void]$tiles.Add(@($btnDiag, "DIAGNOSTIC PC", "Ce qui freine ton PC, et quoi faire.", $cGreen))
    [void]$tiles.Add(@($btnPrioApps, "PRIORITE DES APPLIS", "La priorite de chaque logiciel ouvert.", $cYellow))
    $Script:NxToolTiles = @{}
    if ($hasMon) {
        $b = New-GBButtonCtl; $b.Add_Click({ try { Show-MonitorsPanel } catch { Log ("Ecrans : " + $_.Exception.Message) } })
        [void]$tiles.Add(@($b, "ECRANS", "Eteindre un ecran, tout rallumer.", $cViolet)); $Script:NxToolTiles['screens'] = $b
    }
    if ($hasLinks) {
        $b = New-GBButtonCtl; $b.Add_Click({ try { Show-LinkedAppsPanel } catch { Log ("Lancements lies : " + $_.Exception.Message) } })
        [void]$tiles.Add(@($b, "LANCEMENTS LIES", "Deux programmes qui se lancent ensemble.", $cGreen)); $Script:NxToolTiles['links'] = $b
    }
    if ($hasKeys) {
        $b = New-GBButtonCtl
        $b.Add_Click({
            try { if (Test-Path function:Show-HotkeysPanel) { Show-HotkeysPanel } else { [void](Invoke-GBAction 'hotkeys.panel') } }
            catch { Log ("Raccourcis clavier : " + $_.Exception.Message) }
        })
        [void]$tiles.Add(@($b, "RACCOURCIS CLAVIER", "Choisis la touche de chaque action, meme en jeu.", $cViolet)); $Script:NxToolTiles['keys'] = $b
    }
    if (Test-Path function:Show-GBKeyboardPanel) {
        $b = New-GBButtonCtl; $b.Add_Click({ try { Show-GBKeyboardPanel } catch { Log ("Clavier : " + $_.Exception.Message) } })
        [void]$tiles.Add(@($b, "CLAVIER", "Touches, macros, AZERTY / QWERTY.", $cCyan)); $Script:NxToolTiles['kbd'] = $b
    }
    if (Test-Path function:Show-GBSoundPanel) {
        $b = New-GBButtonCtl; $b.Add_Click({ try { Show-GBSoundPanel } catch { Log ("Son : " + $_.Exception.Message) } })
        [void]$tiles.Add(@($b, "SON", "Son par appli, micro, egaliseur.", $cGreen)); $Script:NxToolTiles['sound'] = $b
    }
    if ($hasSens -and (Test-Path function:Show-SensorsPanel)) {
        $b = New-GBButtonCtl; $b.Add_Click({ try { Show-SensorsPanel } catch { Log ("Capteurs : " + $_.Exception.Message) } })
        [void]$tiles.Add(@($b, "TEMPERATURES", "Les capteurs en detail, a cote du jeu.", $cYellow)); $Script:NxToolTiles['sensors'] = $b
    }
    [void]$tiles.Add(@($btnExport, "RAPPORT POUR CLAUDE", "Config, diagnostic et parties, sur le Bureau.", $cCyan))
    [void]$tiles.Add(@($btnSpecs, "COPIER LES SPECS", "Les caracteristiques du PC dans le presse-papiers.", $cCyan))
    [void]$tiles.Add(@($btnLogs, "OUVRIR LES LOGS", "Journal detaille et sessions de jeu.", $cCyan))
    [void]$tiles.Add(@($btnRestoreAll, "TOUT RESTAURER", "PC comme avant GameBoost. Clic droit : options.", $cRed))
    # Rangement par famille, une couleur par famille : jeu (bleu), materiel (vert), Windows (violet), GameBoost (jaune)
    $famOrder = @('MES PARTIES', 'PRIORITE DES APPLIS', 'LANCEMENTS LIES', 'ECRANS', 'CLAVIER', 'SON', 'TEMPERATURES', 'PILOTES',
                  'CONFIG WINDOWS', 'DESINSTALLATION PROFONDE', 'DIAGNOSTIC PC', 'RACCOURCIS CLAVIER', 'RAPPORT POUR CLAUDE', 'COPIER LES SPECS', 'OUVRIR LES LOGS', 'TOUT RESTAURER')
    $famColor = @($cCyan, $cCyan, $cCyan, $cGreen, $cGreen, $cGreen, $cGreen, $cGreen, $cViolet, $cViolet, $cViolet, $cYellow, $cYellow, $cYellow, $cYellow, $cRed)
    $sorted = New-Object System.Collections.ArrayList
    foreach ($name in $famOrder) { foreach ($t0 in $tiles) { if ([string]$t0[1] -eq $name) { $t0[3] = $famColor[[array]::IndexOf($famOrder, $name)]; [void]$sorted.Add($t0) } } }
    foreach ($t0 in $tiles) { if (-not $sorted.Contains($t0)) { $sorted.Insert([math]::Max(0, $sorted.Count - 1), $t0) } }
    $tiles = $sorted
    # 2 colonnes ; jusqu'a 12 tuiles : tailles d'origine, au-dela un peu plus serrees (tout tient sans defilement) ; TOUT RESTAURER toujours en bas a droite
    $tw = [int](($Inner - 14) / 2); $x2 = $Pad + $tw + 14; $th = 70; $tg = 12
    $rows = [int][math]::Ceiling($tiles.Count / 2)
    if ($rows -gt 6) { $tg = 6; $th = [int][math]::Floor((($MainH - 20 - 80) + $tg) / $rows) - $tg; if ($th -gt 72) { $th = 72 } }
    for ($i = 0; $i -lt $tiles.Count; $i++) {
        $t = $tiles[$i]; $slot = $i
        if ($i -eq $tiles.Count - 1 -and ($tiles.Count % 2) -eq 1) { $slot = $i + 1 }
        $tx = $(if (($slot % 2) -eq 0) { $Pad } else { $x2 }); $ty = 80 + [int][math]::Floor($slot / 2) * ($th + $tg)
        Set-GBTile $t[0] $pgTools $t[1] $t[2] $tx $ty $tw $th $t[3]
        if (-not $Script:UiOK) { $t[0].FlatAppearance.BorderColor = $t[0].ForeColor }
    }
    # Aide des raccourcis de page : le module raccourcis la remplace par sa tuile et le menu
    $order = @('home', 'games', 'optim'); if ($pgSens) { $order += 'sensors' }; $order += 'tools'
    $Script:PageOrder = $order
    $titles = @{ home = 'Accueil'; games = 'Mes jeux'; optim = 'Optimisations'; sensors = 'Capteurs'; tools = 'Outils' }
    if (-not $hasKeyFn) {
        $hl = @(); for ($i = 0; $i -lt $order.Count; $i++) { $hl += ("Ctrl+" + ($i + 1) + " " + $titles[$order[$i]]) }
        $null = New-GBLabelIn $pgTools ("Raccourcis : " + ($hl -join ", ") + ".") $Pad ($MainH - 40) $Inner 20 $fontSmall $cMuted
    }

    # Navigation (glyphes Segoe Fluent / MDL2 : maison, manette, eclair, thermometre, cle)
    $navY = 92
    $glyphs = @{ home = [char]0xE80F; games = [char]0xE7FC; optim = [char]0xE945; sensors = [char]0xE9CA; tools = [char]0xE90F }
    $pages = @{ home = $pgHome; games = $pgGames; optim = $pgOpt; sensors = $pgSens; tools = $pgTools }
    for ($i = 0; $i -lt $order.Count; $i++) {
        $k = $order[$i]; $idx = $i + 1
        $kt = "Ctrl+" + $idx
        if ($hasKeyFn) { try { $kt = [string](Get-GBActionKey ('page.' + $idx)) } catch {}; if (-not $kt) { $kt = "Ctrl+" + $idx } }
        $item = New-GBNavItem $titles[$k] $glyphs[$k] $k $navY ($titles[$k] + " (" + $kt + ")") $rail
        $Script:Pages[$k] = @{ Nav = $item; Page = $pages[$k]; Title = $titles[$k] }
        $navY += 44
    }
    if ($pgSens) { $Script:Pages['sensors'].OnShow = { Update-GBNexusSensors } }
    $Script:Pages['home'].OnShow = { if ($Script:NxHomeCpu) { $o = $null; try { $o = Get-GBSensors } catch {}; Update-GBNexusHomeTemps $o } }

    Complete-GBLayout
}

# --- Modele ARENA : mise en page gaming (onglets en haut, heros BOOST, HUD, bibliotheque de jeux, loadout, arsenal) ---
# Range les controles du moteur (Set-GBPlace) et ajoute des tuiles purement visuelles : toute action passe par le moteur.
# Composants dessines ARENA dans un bloc C# separe, compile seulement si ARENA est choisi (repli : controles Windows classiques).
$arenaSrc = @'
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Text;
using System.Windows.Forms;

// ======================= GameBoost ARENA : composants du modele gaming (mouvement "punch") =======================
// Bloc autonome (aucune reference de compilation vers GBUi) : memes courbes que GBMotion, Reduced recopie par PowerShell.

public static class GBArenaFx {
    public static bool Reduced = false;
    static readonly Stopwatch _clock = Stopwatch.StartNew();
    public static double Now { get { return _clock.Elapsed.TotalMilliseconds; } }
    static double Bez(double x, double p1x, double p1y, double p2x, double p2y) {
        if (x <= 0) return 0; if (x >= 1) return 1;
        double cx = 3 * p1x, bx = 3 * (p2x - p1x) - cx, ax = 1 - cx - bx;
        double cy = 3 * p1y, by = 3 * (p2y - p1y) - cy, ay = 1 - cy - by;
        double lo = 0, hi = 1, t = x;
        for (int i = 0; i < 30; i++) {
            double v = ((ax * t + bx) * t + cx) * t;
            if (Math.Abs(v - x) < 1e-5) break;
            if (x > v) lo = t; else hi = t;
            t = (lo + hi) / 2;
        }
        return ((ay * t + by) * t + cy) * t;
    }
    // cubic-bezier(0.23, 1, 0.32, 1) : depart immediat, arrivee douce
    public static float EaseOut(float x) { return (float)Bez(x, 0.23, 1, 0.32, 1); }
    public static Color Mix(Color a, Color b, float t) {
        t = Math.Max(0f, Math.Min(1f, t));
        return Color.FromArgb(255, (int)(a.R + (b.R - a.R) * t), (int)(a.G + (b.G - a.G) * t), (int)(a.B + (b.B - a.B) * t));
    }
    public static Color A(Color c, int alpha) { return Color.FromArgb(Math.Max(0, Math.Min(255, alpha)), c.R, c.G, c.B); }
    public static GraphicsPath Round(RectangleF r, float rad) {
        GraphicsPath p = new GraphicsPath();
        float d = Math.Min(rad * 2, Math.Min(r.Width, r.Height));
        if (d < 1) { p.AddRectangle(r); return p; }
        p.AddArc(r.X, r.Y, d, d, 180, 90);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
        p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
        p.CloseFigure();
        return p;
    }
    public static float S(Graphics g) { return Math.Max(1f, g.DpiX / 96f); }
    // Un seul minuteur pour toutes les animations ARENA, actif seulement s'il y en a une
    static readonly List<GBArenaAnim> _active = new List<GBArenaAnim>();
    static Timer _timer;
    internal static void Run(GBArenaAnim a) {
        if (!_active.Contains(a)) _active.Add(a);
        if (_timer == null) { _timer = new Timer(); _timer.Interval = 15; _timer.Tick += Tick; }
        if (!_timer.Enabled) _timer.Start();
    }
    static void Tick(object sender, EventArgs e) {
        double now = Now;
        for (int i = _active.Count - 1; i >= 0; i--) { if (i < _active.Count && _active[i].Step(now)) _active.RemoveAt(i); }
        if (_active.Count == 0) _timer.Stop();
    }
}

// Valeur animee interruptible (repart de la valeur actuelle, comme une transition CSS)
public class GBArenaAnim {
    public float Value;
    float _from, _to;
    double _start, _dur;
    public Control Owner;
    public bool Motion = true;   // false = fondu de couleur, garde quand les animations Windows sont coupees
    public GBArenaAnim(Control owner, float v) { Owner = owner; Value = v; _to = v; }
    public float Target { get { return _to; } }
    public void To(float target, double ms) {
        if (Math.Abs(target - _to) < 0.0001f && Math.Abs(Value - target) < 0.0001f) return;
        _to = target;
        bool can = Owner != null && !Owner.IsDisposed && Owner.IsHandleCreated && Owner.Visible;
        if (can) { Form f = Owner.FindForm(); if (f == null || f.WindowState == FormWindowState.Minimized) can = false; }
        if ((Motion && GBArenaFx.Reduced) || ms <= 0 || !can) { Value = target; if (Owner != null && !Owner.IsDisposed) Owner.Invalidate(); return; }
        _from = Value; _start = GBArenaFx.Now; _dur = ms;
        GBArenaFx.Run(this);
    }
    internal bool Step(double now) {
        if (Owner == null || Owner.IsDisposed) return true;
        double p = (now - _start) / _dur;
        bool done = p >= 1;
        Value = done ? _to : _from + GBArenaFx.EaseOut((float)p) * (_to - _from);
        Owner.Invalidate();
        return done;
    }
}

// ----------------------- Surface : carte arrondie, bandeau heros (degrade + rayures), barre du haut -----------------------
// Tout est dessine dans le fond : les libelles transparents poses dessus le recopient.
public class GBArenaSurface : Panel {
    public int Radius = 14;
    public int Style = 0;                // 0 carte, 1 heros, 2 barre du haut, 3 plat
    public Color Border = Color.FromArgb(46, 42, 58);
    public Color Accent = Color.FromArgb(255, 51, 119);
    public Color Accent2 = Color.FromArgb(255, 140, 26);
    public Color TitleColor = Color.White, HintColor = Color.Gray;
    public string Title = "", Hint = "", Glyph = "";
    public Font TitleFont, HintFont, GlyphFont;
    public Rectangle PulseRect = Rectangle.Empty;
    bool _pulse; float _pv = 0.5f; Timer _pt;
    public GBArenaSurface() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
    }
    // Pulsation douce autour du BOOST pendant le jeu seulement (rien quand les animations Windows sont coupees)
    public bool Pulse {
        get { return _pulse; }
        set {
            if (_pulse == value) return;
            _pulse = value;
            if (_pulse && !GBArenaFx.Reduced) {
                if (_pt == null) { _pt = new Timer(); _pt.Interval = 40; _pt.Tick += PulseTick; }
                _pt.Start();
            } else if (_pt != null) _pt.Stop();
            InvalidatePulse();
        }
    }
    void InvalidatePulse() { if (!PulseRect.IsEmpty) { Rectangle r = PulseRect; r.Inflate(24, 24); Invalidate(r); } }
    void PulseTick(object sender, EventArgs e) {
        Form f = FindForm();
        // fenetre cachee, reduite ou pas au premier plan (en jeu) : aucun dessin
        if (!Visible || f == null || !f.Visible || f.WindowState == FormWindowState.Minimized || Form.ActiveForm == null) return;
        _pv = (float)((Math.Sin(GBArenaFx.Now / 1600.0 * 2 * Math.PI) + 1) / 2);
        InvalidatePulse();
    }
    protected override void Dispose(bool disposing) { if (disposing && _pt != null) { _pt.Stop(); _pt.Dispose(); _pt = null; } base.Dispose(disposing); }
    protected override void OnPaint(PaintEventArgs e) { }
    protected override void OnPaintBackground(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
        float s = GBArenaFx.S(g);
        Color outer = Parent != null ? Parent.BackColor : BackColor;
        if (Style == 2 || Style == 3) {
            using (SolidBrush b = new SolidBrush(BackColor)) g.FillRectangle(b, ClientRectangle);
            if (Style == 2) {
                // filet degrade en bas de la barre : accent -> accent 2 -> rien
                RectangleF lr = new RectangleF(0, Height - 2 * s, Width, 2 * s);
                using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(0, 0, Width, 4), Accent, Color.Transparent, 0f)) {
                    ColorBlend cb = new ColorBlend(3);
                    cb.Colors = new Color[] { Accent, Accent2, GBArenaFx.A(Accent2, 0) };
                    cb.Positions = new float[] { 0f, 0.35f, 1f };
                    lb.InterpolationColors = cb;
                    g.FillRectangle(lb, lr);
                }
            }
            return;
        }
        g.Clear(outer);
        RectangleF r = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f);
        using (GraphicsPath p = GBArenaFx.Round(r, Radius * s)) {
            using (SolidBrush b = new SolidBrush(BackColor)) g.FillPath(b, p);
            Region old = g.Clip; g.SetClip(p, CombineMode.Intersect);
            if (Style == 1) {
                // lueur d'accent a gauche, rayures diagonales discretes : ambiance "setup RGB"
                float gw = Width * 0.62f;
                using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(0, 0, gw, Height), GBArenaFx.A(Accent, 70), GBArenaFx.A(Accent, 0), 0f)) g.FillRectangle(lb, 0, 0, gw, Height);
                using (GraphicsPath ep = new GraphicsPath()) {
                    ep.AddEllipse(-Width * 0.12f, Height * 0.35f, Width * 0.5f, Height * 1.1f);
                    using (PathGradientBrush pb = new PathGradientBrush(ep)) { pb.CenterColor = GBArenaFx.A(Accent2, 60); pb.SurroundColors = new Color[] { GBArenaFx.A(Accent2, 0) }; g.FillPath(pb, ep); }
                }
                using (Pen sp = new Pen(Color.FromArgb(9, 255, 255, 255), 6 * s)) {
                    for (float x = -Height; x < gw; x += 22 * s) g.DrawLine(sp, x, Height, x + Height, 0);
                }
            } else {
                // trait degrade en haut a gauche de la carte
                RectangleF tr = new RectangleF(Radius * s, 0, 56 * s, 3 * s);
                using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(tr.X - 1, 0, tr.Width + 2, 4), Accent, Accent2, 0f)) g.FillRectangle(lb, tr);
            }
            g.Clip = old;
            using (Pen bp = new Pen(Border, 1f)) g.DrawPath(bp, p);
        }
        if (Style == 1 && _pulse && !PulseRect.IsEmpty) {
            float k = GBArenaFx.Reduced ? 0.5f : _pv;
            for (int i = 1; i <= 3; i++) {
                RectangleF pr = new RectangleF(PulseRect.X - (3 + i * 4) * s, PulseRect.Y - (3 + i * 4) * s, PulseRect.Width + (6 + i * 8) * s, PulseRect.Height + (6 + i * 8) * s);
                using (GraphicsPath hp = GBArenaFx.Round(pr, (12 + i * 4) * s))
                using (Pen hpen = new Pen(GBArenaFx.A(Accent, (int)((70 - i * 18) * (0.35f + 0.65f * k))), 3f * s)) g.DrawPath(hpen, hp);
            }
        }
        if (!string.IsNullOrEmpty(Title) && TitleFont != null) {
            int x = (int)(18 * s), y = (int)(14 * s), th = (int)(TitleFont.GetHeight(g) + 2);
            TextFormatFlags fl = TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding;
            if (GlyphFont != null && !string.IsNullOrEmpty(Glyph)) {
                TextRenderer.DrawText(g, Glyph, GlyphFont, new Rectangle(x, y, (int)(20 * s), th), Accent, fl | TextFormatFlags.HorizontalCenter);
                x += (int)(28 * s);
            }
            Size ts = TextRenderer.MeasureText(g, Title, TitleFont, Size.Empty, fl);
            TextRenderer.DrawText(g, Title, TitleFont, new Rectangle(x, y, ts.Width + 2, th), TitleColor, fl);
            if (!string.IsNullOrEmpty(Hint) && HintFont != null)
                TextRenderer.DrawText(g, Hint, HintFont, new Rectangle(x + ts.Width + (int)(10 * s), y, Math.Max(1, Width - x - ts.Width - (int)(28 * s)), th), HintColor, fl | TextFormatFlags.EndEllipsis);
        }
    }
}

// ----------------------- Onglet de la barre du haut (JOUER, JEUX, LOADOUT...) -----------------------
// Changement de page instantane (action frequente, aussi au clavier) ; seul le survol a un fondu court.
public class GBArenaNav : Control {
    GBArenaAnim _hover;
    bool _sel, _badge;
    public string Glyph = "";
    public Font GlyphFont;
    public Color Accent = Color.FromArgb(255, 51, 119), Accent2 = Color.FromArgb(255, 140, 26);
    public Color Muted = Color.Gray, Badge2 = Color.FromArgb(255, 204, 0);
    public GBArenaNav() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        _hover = new GBArenaAnim(this, 0); _hover.Motion = false;
        Cursor = Cursors.Hand; TabStop = true;
    }
    public bool Selected { get { return _sel; } set { if (_sel == value) return; _sel = value; Invalidate(); } }
    public bool Badge { get { return _badge; } set { _badge = value; Invalidate(); } }
    protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); _hover.To(1, 120); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 180); }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override bool IsInputKey(Keys k) { if (k == Keys.Enter || k == Keys.Space) return true; return base.IsInputKey(k); }
    protected override void OnKeyDown(KeyEventArgs e) { base.OnKeyDown(e); if (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Space) { e.Handled = true; OnClick(EventArgs.Empty); } }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = Parent != null ? Parent.BackColor : BackColor;
        g.Clear(bg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = GBArenaFx.S(g), h = _hover.Value;
        TextFormatFlags fl = TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding;
        Size ts = TextRenderer.MeasureText(g, Text, Font, Size.Empty, fl);
        int gw = (GlyphFont != null && !string.IsNullOrEmpty(Glyph)) ? (int)(24 * s) : 0;
        int cw = gw + ts.Width;
        int x = (Width - cw) / 2;
        RectangleF pill = new RectangleF(x - 12 * s, Height / 2f - 16 * s, cw + 24 * s, 32 * s);
        float a = _sel ? 0.16f : 0.07f * h;
        if (a > 0.005f) using (GraphicsPath pp = GBArenaFx.Round(pill, 9 * s)) using (SolidBrush pb = new SolidBrush(GBArenaFx.Mix(bg, Accent, a))) g.FillPath(pb, pp);
        Color fg = _sel ? ForeColor : GBArenaFx.Mix(Muted, ForeColor, 0.25f + 0.75f * h);
        if (gw > 0) TextRenderer.DrawText(g, Glyph, GlyphFont, new Rectangle(x, 0, (int)(18 * s), Height), _sel ? Accent : fg, fl | TextFormatFlags.HorizontalCenter);
        TextRenderer.DrawText(g, Text, Font, new Rectangle(x + gw, 0, ts.Width + 2, Height), fg, fl);
        if (_sel) {
            RectangleF u = new RectangleF(x, Height - 4 * s, cw, 3 * s);
            using (GraphicsPath up = GBArenaFx.Round(u, 1.5f * s))
            using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(u.X - 1, u.Y, u.Width + 2, u.Height), Accent, Accent2, 0f)) g.FillPath(lb, up);
        }
        if (_badge) {
            float d = 7 * s, bx = pill.Right - d - 2 * s, by = pill.Top + 2 * s;
            using (SolidBrush gb = new SolidBrush(GBArenaFx.A(Badge2, 70))) g.FillEllipse(gb, bx - 3 * s, by - 3 * s, d + 6 * s, d + 6 * s);
            using (SolidBrush bb = new SolidBrush(Badge2)) g.FillEllipse(bb, bx, by, d, d);
        }
        if (Focused && ShowFocusCues) using (GraphicsPath fp = GBArenaFx.Round(pill, 9 * s)) using (Pen pen = new Pen(GBArenaFx.A(Accent, 150), 1f)) g.DrawPath(pen, fp);
    }
}

// ----------------------- Tuile : outil, interrupteur rapide, jeu de la bibliotheque, preset, pastille -----------------------
// Survol : leger soulevement + lueur (160 ms). Appui : enfoncement a 0.97 (100 ms), relache 160 ms. Clavier : aucun mouvement.
public class GBArenaTile : Control {
    GBArenaAnim _hover, _press, _glow;
    public int Kind = 0;                 // 0 tuile, 1 jeu, 2 preset, 3 pastille
    public int Radius = 12;
    public string Title = "", Desc = "", Glyph = "", Monogram = "", Tag2 = "";
    public Font TitleFont, DescFont, GlyphFont, MonoFont;
    public Color Accent = Color.FromArgb(255, 51, 119), Accent2 = Color.FromArgb(255, 140, 26);
    public Color Border = Color.FromArgb(46, 42, 58), Muted = Color.Gray, DescColor = Color.Empty, Badge2 = Color.FromArgb(255, 204, 0);
    public Image Picture;
    public bool Toggle = false, Static = false;
    bool _checked, _sel, _badge;
    public GBArenaTile() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        _hover = new GBArenaAnim(this, 0); _press = new GBArenaAnim(this, 0); _glow = new GBArenaAnim(this, 0); _glow.Motion = false;
        Cursor = Cursors.Hand; TabStop = true;
        BackColor = Color.FromArgb(26, 23, 34); ForeColor = Color.White;
    }
    public bool Checked { get { return _checked; } set { if (_checked == value) return; _checked = value; Invalidate(); } }
    public bool Selected { get { return _sel; } set { if (_sel == value) return; _sel = value; Invalidate(); } }
    public bool Badge { get { return _badge; } set { _badge = value; Invalidate(); } }
    protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); if (Static || !Enabled) return; _hover.To(1, 160); _glow.To(1, 160); }
    protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); _hover.To(0, 200); _glow.To(0, 200); _press.To(0, 160); }
    protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (!Static && Enabled && e.Button == MouseButtons.Left) _press.To(1, 100); }
    protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); _press.To(0, 160); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); if (!Enabled) { _hover.To(0, 0); _glow.To(0, 0); _press.To(0, 0); } Invalidate(); }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override bool IsInputKey(Keys k) { if (k == Keys.Enter || k == Keys.Space) return true; return base.IsInputKey(k); }
    protected override void OnKeyDown(KeyEventArgs e) { base.OnKeyDown(e); if (!Static && Enabled && (e.KeyCode == Keys.Enter || e.KeyCode == Keys.Space)) { e.Handled = true; OnClick(EventArgs.Empty); } }

    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color outer = Parent != null ? Parent.BackColor : Color.Black;
        g.Clear(outer);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.InterpolationMode = InterpolationMode.HighQualityBicubic;
        g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
        float s = GBArenaFx.S(g);
        float h = Enabled ? _hover.Value : 0f, gl = Enabled ? _glow.Value : 0f, pr = _press.Value;
        Color acc = Enabled ? Accent : Muted;
        // soulevement (2 px) et enfoncement (0.97) : seulement si les animations Windows sont actives
        float lift = GBArenaFx.Reduced ? 0f : -2f * s * h;
        float sc = 1f - 0.03f * pr;
        g.TranslateTransform(Width / 2f, Height / 2f + lift); g.ScaleTransform(sc, sc); g.TranslateTransform(-Width / 2f, -Height / 2f);
        float pad = Kind == 3 ? 1f * s : 3f * s;
        RectangleF r = new RectangleF(pad, pad, Width - 2 * pad - 1, Height - 2 * pad - 1);
        float rad = Kind == 3 ? r.Height / 2f : Radius * s;
        Color fill = BackColor;
        if (Kind == 2 && _sel) fill = GBArenaFx.Mix(BackColor, acc, 0.16f);
        if (Kind == 3) fill = GBArenaFx.Mix(outer, acc, 0.16f);
        if (Toggle && _checked) fill = GBArenaFx.Mix(BackColor, acc, 0.10f);
        fill = GBArenaFx.Mix(fill, Color.White, 0.03f * h);
        if (!Enabled) fill = GBArenaFx.Mix(fill, outer, 0.5f);
        using (GraphicsPath p = GBArenaFx.Round(r, rad)) {
            if (gl > 0.01f || _sel) {
                float k = Math.Max(gl, _sel ? 0.7f : 0f);
                for (int i = 3; i >= 1; i--) using (Pen gp = new Pen(GBArenaFx.A(acc, (int)(26 * k / i)), (1.5f + i * 2.5f) * s)) g.DrawPath(gp, p);
            }
            using (SolidBrush b = new SolidBrush(fill)) g.FillPath(b, p);
            Region old = g.Clip; g.SetClip(p, CombineMode.Intersect);
            if (Kind == 1) PaintGameArt(g, r, s);
            if (Kind == 2) using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(r.X - 1, r.Y, r.Width + 2, 4 * s), acc, GBArenaFx.Mix(acc, Accent2, 0.6f), 0f)) g.FillRectangle(lb, r.X, r.Y, r.Width, 4 * s);
            g.Clip = old;
            Color border = (_sel || (Toggle && _checked)) ? acc : GBArenaFx.Mix(Border, acc, 0.85f * gl);
            using (Pen bp = new Pen(border, (_sel ? 1.6f : 1f) * s)) g.DrawPath(bp, p);
        }
        Color tc = Enabled ? ForeColor : Muted;
        Color dc = DescColor.IsEmpty ? Muted : DescColor;
        TextFormatFlags fl = TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPadding;
        if (Kind == 3) {
            float d = 7 * s;
            using (SolidBrush db = new SolidBrush(acc)) g.FillEllipse(db, r.X + 12 * s, r.Y + r.Height / 2f - d / 2f, d, d);
            Rectangle cr = new Rectangle((int)(r.X + 25 * s), (int)r.Y, (int)(r.Width - 33 * s), (int)r.Height);
            TextRenderer.DrawText(g, Title, TitleFont ?? Font, cr, tc, fl | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine);
        } else if (Kind == 1) {
            float artH = Math.Min(r.Height - 40 * s, r.Width * 0.62f);
            Rectangle nr = new Rectangle((int)(r.X + 12 * s), (int)(r.Y + artH + 8 * s), (int)(r.Width - 24 * s), (int)((TitleFont ?? Font).GetHeight(g) + 2));
            TextRenderer.DrawText(g, Title, TitleFont ?? Font, nr, tc, fl | TextFormatFlags.SingleLine);
            if (!string.IsNullOrEmpty(Desc)) {
                Rectangle dr = new Rectangle(nr.X, nr.Bottom + (int)(1 * s), nr.Width, (int)((DescFont ?? Font).GetHeight(g) + 2));
                TextRenderer.DrawText(g, Desc, DescFont ?? Font, dr, dc, fl | TextFormatFlags.SingleLine);
            }
        } else {
            float x = r.X + 14 * s, top = r.Y + 12 * s;
            if (Kind == 2) top += 4 * s;
            bool hasGlyph = GlyphFont != null && !string.IsNullOrEmpty(Glyph);
            // tuile etroite : icone et interrupteur en haut, titre et texte en dessous sur toute la largeur
            bool stack = Kind == 0 && hasGlyph && Width < 220 * s;
            float ibs = stack ? 30 * s : 34 * s;
            if (hasGlyph) {
                RectangleF ib = new RectangleF(x, top, ibs, ibs);
                using (GraphicsPath ip = GBArenaFx.Round(ib, 9 * s)) using (SolidBrush ibb = new SolidBrush(GBArenaFx.A(acc, Enabled ? 40 + (int)(30 * h) : 25))) g.FillPath(ibb, ip);
                TextRenderer.DrawText(g, Glyph, GlyphFont, Rectangle.Round(ib), acc, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix);
                if (!stack) x += ibs + 12 * s;
            }
            float right = r.Right - 12 * s;
            if (Toggle) {
                RectangleF tr = new RectangleF(r.Right - 14 * s - 34 * s, stack ? top + (ibs - 18 * s) / 2f : top + 2 * s, 34 * s, 18 * s);
                using (GraphicsPath tp = GBArenaFx.Round(tr, 9 * s)) {
                    using (SolidBrush tb = new SolidBrush(_checked ? acc : GBArenaFx.Mix(BackColor, Color.White, 0.10f))) g.FillPath(tb, tp);
                }
                float kd = 12 * s, kx = _checked ? tr.Right - 3 * s - kd : tr.X + 3 * s;
                using (SolidBrush kb = new SolidBrush(_checked ? Color.White : Muted)) g.FillEllipse(kb, kx, tr.Y + 3 * s, kd, kd);
                if (!stack) right = tr.X - 8 * s;
            }
            if (stack) top += ibs + 8 * s;
            Font tf = TitleFont ?? Font;
            Rectangle trc = new Rectangle((int)x, (int)top, Math.Max(1, (int)(right - x)), (int)(tf.GetHeight(g) + 2));
            TextRenderer.DrawText(g, Title, tf, trc, Kind == 2 ? acc : tc, fl | TextFormatFlags.SingleLine);
            if (!string.IsNullOrEmpty(Desc)) {
                float dx = (Kind == 2 || !hasGlyph) ? x : x;
                Rectangle drc = new Rectangle((int)dx, trc.Bottom + (int)(3 * s), Math.Max(1, (int)(r.Right - 12 * s - dx)), Math.Max(1, (int)(r.Bottom - trc.Bottom - 8 * s)));
                TextRenderer.DrawText(g, Desc, DescFont ?? Font, drc, dc, fl | TextFormatFlags.WordBreak);
            }
            if (Kind == 2 && _sel && !string.IsNullOrEmpty(Tag2)) {
                Font bf = DescFont ?? Font;
                Size bs = TextRenderer.MeasureText(g, Tag2, bf, Size.Empty, fl | TextFormatFlags.SingleLine);
                RectangleF br = new RectangleF(r.Right - 12 * s - bs.Width - 14 * s, r.Y + 12 * s, bs.Width + 14 * s, 20 * s);
                using (GraphicsPath bp2 = GBArenaFx.Round(br, 10 * s)) using (SolidBrush bb = new SolidBrush(acc)) g.FillPath(bb, bp2);
                TextRenderer.DrawText(g, Tag2, bf, Rectangle.Round(br), Color.White, fl | TextFormatFlags.SingleLine | TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
            }
        }
        if (_badge) {
            float d = 8 * s, bx = r.Right - 12 * s - d, by = r.Y + 10 * s;
            if (Toggle) by = r.Bottom - 16 * s;
            using (SolidBrush gb = new SolidBrush(GBArenaFx.A(Badge2, 70))) g.FillEllipse(gb, bx - 3 * s, by - 3 * s, d + 6 * s, d + 6 * s);
            using (SolidBrush bb = new SolidBrush(Badge2)) g.FillEllipse(bb, bx, by, d, d);
        }
        if (Focused && ShowFocusCues && !Static) {
            g.ResetTransform();
            using (GraphicsPath fp = GBArenaFx.Round(new RectangleF(1, 1, Width - 3, Height - 3), rad + 2 * s)) using (Pen pen = new Pen(GBArenaFx.A(acc, 170), 1f)) g.DrawPath(pen, fp);
        }
    }
    // Jaquette du jeu : degrade de couleur + icone de l'exe (ou ses initiales)
    void PaintGameArt(Graphics g, RectangleF r, float s) {
        float artH = Math.Min(r.Height - 40 * s, r.Width * 0.62f);
        RectangleF ar = new RectangleF(r.X, r.Y, r.Width, artH);
        using (LinearGradientBrush lb = new LinearGradientBrush(new RectangleF(ar.X - 1, ar.Y - 1, ar.Width + 2, ar.Height + 2), GBArenaFx.Mix(BackColor, Accent, 0.55f), GBArenaFx.Mix(BackColor, Accent2, 0.30f), 35f)) g.FillRectangle(lb, ar);
        using (Pen sp = new Pen(Color.FromArgb(12, 255, 255, 255), 5 * s)) { for (float x = ar.X - ar.Height; x < ar.Right; x += 16 * s) g.DrawLine(sp, x, ar.Bottom, x + ar.Height, ar.Y); }
        float d = Math.Min(48 * s, artH - 16 * s);
        RectangleF ir = new RectangleF(ar.X + (ar.Width - d) / 2f, ar.Y + (artH - d) / 2f, d, d);
        if (Picture != null) {
            using (GraphicsPath sh = GBArenaFx.Round(new RectangleF(ir.X - 8 * s, ir.Y - 8 * s, ir.Width + 16 * s, ir.Height + 16 * s), 12 * s)) using (SolidBrush shb = new SolidBrush(Color.FromArgb(70, 0, 0, 0))) g.FillPath(shb, sh);
            g.DrawImage(Picture, ir);
        } else if (!string.IsNullOrEmpty(Monogram)) {
            Font mf = MonoFont ?? Font;
            TextRenderer.DrawText(g, Monogram, mf, Rectangle.Round(new RectangleF(ar.X + 2 * s, ar.Y + 2 * s, ar.Width, ar.Height)), Color.FromArgb(90, 0, 0, 0), TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
            TextRenderer.DrawText(g, Monogram, mf, Rectangle.Round(ar), Color.White, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine);
        }
    }
}

// ----------------------- Compteur du HUD : gros chiffre + anneau de charge (valeurs lues en continu : aucune animation) -----------------------
public class GBArenaStat : Control {
    public string Label = "", Value = "--", Unit = "", Sub = "", Glyph = "", RingText = "";
    public float Pct = -1f;               // -1 = pas d'anneau
    public float WarnAt = 70f, AlertAt = 90f;
    public int Radius = 12;
    public Color Accent = Color.FromArgb(255, 51, 119), Warn = Color.FromArgb(255, 204, 0), Alert = Color.FromArgb(255, 69, 58);
    public Color Border = Color.FromArgb(46, 42, 58), Muted = Color.Gray, Track = Color.FromArgb(44, 40, 56), SubColor = Color.Empty, RingTextColor = Color.Empty;
    public Font LabelFont, ValueFont, UnitFont, SubFont, GlyphFont;
    public GBArenaStat() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        TabStop = false; BackColor = Color.FromArgb(26, 23, 34); ForeColor = Color.White;
    }
    public void SetData(string value, string unit, string sub, float pct) {
        if (value == Value && unit == Unit && sub == Sub && Math.Abs(pct - Pct) < 0.01f) return;
        Value = value ?? "--"; Unit = unit ?? ""; Sub = sub ?? ""; Pct = pct; Invalidate();
    }
    Color Level(float v) { return v >= AlertAt ? Alert : (v >= WarnAt ? Warn : Accent); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : Color.Black);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        g.TextRenderingHint = TextRenderingHint.ClearTypeGridFit;
        float s = GBArenaFx.S(g);
        RectangleF r = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f);
        using (GraphicsPath p = GBArenaFx.Round(r, Radius * s)) {
            using (SolidBrush b = new SolidBrush(BackColor)) g.FillPath(b, p);
            using (Pen bp = new Pen(Border, 1f)) g.DrawPath(bp, p);
        }
        TextFormatFlags fl = TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding;
        float ringD = Pct >= 0 ? Math.Min(Height - 28 * s, 76 * s) : 0;
        float left = 16 * s, top = 12 * s;
        float textR = Width - 14 * s - (ringD > 0 ? ringD + 10 * s : 0);
        int lx = (int)left;
        if (GlyphFont != null && !string.IsNullOrEmpty(Glyph)) {
            TextRenderer.DrawText(g, Glyph, GlyphFont, new Rectangle(lx, (int)top, (int)(16 * s), (int)(16 * s)), Accent, fl | TextFormatFlags.VerticalCenter | TextFormatFlags.HorizontalCenter);
            lx += (int)(22 * s);
        }
        Font lf = LabelFont ?? Font;
        TextRenderer.DrawText(g, Label, lf, new Rectangle(lx, (int)top, Math.Max(1, (int)(textR - lx)), (int)(16 * s)), Muted, fl | TextFormatFlags.VerticalCenter | TextFormatFlags.EndEllipsis);
        Font vf = ValueFont ?? Font;
        Size vs = TextRenderer.MeasureText(g, Value, vf, Size.Empty, fl);
        int vy = (int)(Height - 14 * s - (SubFont != null && Sub.Length > 0 ? SubFont.GetHeight(g) + 2 * s : 0) - vs.Height);
        TextRenderer.DrawText(g, Value, vf, new Rectangle((int)left, vy, vs.Width + 2, vs.Height), ForeColor, fl);
        if (Unit.Length > 0) {
            Font uf = UnitFont ?? Font;
            Size us = TextRenderer.MeasureText(g, Unit, uf, Size.Empty, fl);
            TextRenderer.DrawText(g, Unit, uf, new Rectangle((int)left + vs.Width + (int)(4 * s), vy + vs.Height - us.Height - (int)(4 * s), us.Width + 2, us.Height), Muted, fl);
        }
        if (Sub.Length > 0 && SubFont != null)
            TextRenderer.DrawText(g, Sub, SubFont, new Rectangle((int)left, (int)(Height - 12 * s - SubFont.GetHeight(g)), Math.Max(1, (int)(textR - left)), (int)(SubFont.GetHeight(g) + 2)), SubColor.IsEmpty ? Muted : SubColor, fl | TextFormatFlags.EndEllipsis);
        if (ringD > 0) {
            float st = 7 * s;
            RectangleF rr = new RectangleF(Width - 14 * s - ringD + st / 2, (Height - ringD) / 2f + st / 2, ringD - st, ringD - st);
            using (Pen tp = new Pen(Track, st)) g.DrawEllipse(tp, rr);
            float v = Math.Max(0f, Math.Min(100f, Pct));
            if (v > 0.5f) using (Pen ap = new Pen(Level(v), st)) { ap.StartCap = LineCap.Round; ap.EndCap = LineCap.Round; g.DrawArc(ap, rr, -90f, 360f * v / 100f); }
            if (RingText.Length > 0) {
                Font rf = SubFont ?? Font;
                TextRenderer.DrawText(g, RingText, rf, Rectangle.Round(rr), RingTextColor.IsEmpty ? ForeColor : RingTextColor, fl | TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter);
            }
        }
    }
}
'@
$Script:ArenaFxOK = $false
$Script:ArenaLoaded = $false
$Script:ArenaOnClick = [System.Windows.Forms.Control].GetMethod('OnClick', [System.Reflection.BindingFlags]'Instance, NonPublic')
$Script:ArenaDot = "  " + [string][char]0xB7 + "  "

# Fonctions communes absentes (securite) : memes definitions que la disposition NEXUS
if (-not (Get-Command Set-GBPlace -ErrorAction Ignore)) {
    function Set-GBPlace($c, $parent, $x, $y, $w, $h) {
        if ($c.Parent -ne $parent) { if ($c.Parent) { $c.Parent.Controls.Remove($c) }; $parent.Controls.Add($c) }
        $c.Location = New-Object System.Drawing.Point([int]$x, [int]$y)
        if ($w -gt 0) { $c.Size = New-Object System.Drawing.Size([int]$w, [int]$h) }
    }
}
if (-not (Get-Command Show-GBPage -ErrorAction Ignore)) {
    function Show-GBPage([string]$key) {
        if (-not $Script:Pages -or -not $Script:Pages.Contains($key)) { return }
        $new = $Script:Pages[$key].Page
        $new.Visible = $true; $new.BringToFront()
        foreach ($k in @($Script:Pages.Keys)) {
            $pg = $Script:Pages[$k]; $on = ($k -eq $key)
            if (-not $on) { $pg.Page.Visible = $false }
            if ($pg.Nav -is [System.Windows.Forms.Button]) {
                if ($on) { $pg.Nav.BackColor = $cSel; $pg.Nav.ForeColor = $cCyan } else { $pg.Nav.BackColor = $cRail; $pg.Nav.ForeColor = $cText }
            } else { $pg.Nav.Selected = $on }
        }
        $Script:CurrentPage = $key
    }
}

# Clic sur un controle du moteur, meme s'il est sur une page cachee (PerformClick ne marche que sur un controle visible)
function Invoke-GBArenaClick($c) {
    if (-not $c -or $c.IsDisposed -or -not $c.Enabled) { return }
    try { [void]$Script:ArenaOnClick.Invoke($c, [object[]]@([EventArgs]::Empty)) }
    catch { $m = $_.Exception.Message; if ($_.Exception.InnerException) { $m = $_.Exception.InnerException.Message }; Log ("ARENA : action impossible (" + $m + ")") }
}
# Fonction d'un autre module (ecrans, liens, capteurs, raccourcis) : appelee si elle existe, sinon message clair
function Invoke-GBArenaPanel([string]$fn, [string]$what) {
    if (Get-Command $fn -ErrorAction Ignore) { try { & $fn } catch { Log ($what + " : " + $_.Exception.Message) } }
    else { [System.Windows.Forms.MessageBox]::Show(($what + " : fonction indisponible dans cette version."), "GameBoost") | Out-Null }
}
# Taille des controles crees apres l'ouverture (la mise a l'echelle du zoom Windows est deja faite)
function Get-GBArenaK { if ($Script:ArenaLoaded) { return [double]$Script:DpiScale } return 1.0 }

# --- Briques visuelles ARENA (avec repli sans C#) ---
function New-GBArenaLabel($parent, [string]$text, $x, $y, $w, $h, $font, $color, [string]$align = '') {
    $l = New-Object System.Windows.Forms.Label
    $l.Text = $text; $l.Font = $font; $l.ForeColor = $color; $l.BackColor = [System.Drawing.Color]::Transparent; $l.AutoEllipsis = $true
    $l.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $l.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    if ($align) { $l.TextAlign = $align }
    $parent.Controls.Add($l); return $l
}
function New-GBArenaSurface($parent, $x, $y, $w, $h, [string]$title, [string]$hint, [string]$glyph, [int]$style = 0, $accent = $null) {
    $A = $Script:AC
    if ($Script:ArenaFxOK) {
        $p = New-Object GBArenaSurface
        $p.Style = $style; $p.Radius = $A.Radius; $p.Border = $A.Line; $p.Accent = $A.Accent; $p.Accent2 = $A.Accent2
        if ($accent) { $p.Accent = $accent }
        $p.Title = $title; $p.Hint = $hint; $p.TitleFont = $Script:AF.Card; $p.HintFont = $fontSmall; $p.TitleColor = $A.Text; $p.HintColor = $A.Muted
        if ($glyph -and $Script:AF.Glyph) { $p.Glyph = $glyph; $p.GlyphFont = $Script:AF.Glyph }
    } else {
        $p = New-Object System.Windows.Forms.Panel
        if ($title) {
            $t = $title; if ($hint) { $t += "   " + $hint }
            $tl = New-GBArenaLabel $p $t 16 12 ($w - 32) 22 $Script:AF.Card $A.Text
            if ($accent) { $tl.ForeColor = $accent }
        }
    }
    if ($style -eq 2) { $p.BackColor = $A.Bar } elseif ($style -eq 3) { $p.BackColor = $A.Bg } else { $p.BackColor = $A.Card }
    $p.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $p.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    $parent.Controls.Add($p); return $p
}
# Tuile ARENA : Kind 0 tuile (icone + titre + texte), 1 jeu (jaquette), 2 preset, 3 pastille
function New-GBArenaTile($parent, [int]$kind, [string]$title, [string]$desc, [string]$glyph, $accent, $x, $y, $w, $h) {
    $A = $Script:AC
    if (-not $accent) { $accent = $A.Accent }
    if ($Script:ArenaFxOK) {
        $t = New-Object GBArenaTile
        $t.Kind = $kind; $t.Radius = $A.Radius; $t.Title = $title; $t.Desc = $desc; $t.Accent = $accent; $t.Accent2 = $A.Accent2
        $t.Border = $A.Line; $t.Muted = $A.Muted; $t.BackColor = $A.Tile; $t.ForeColor = $A.Text; $t.Badge2 = $A.Yellow
        $t.Font = $fontUI; $t.TitleFont = $Script:AF.Tile; $t.DescFont = $fontSmall; $t.MonoFont = $Script:AF.Mono
        if ($kind -eq 2) { $t.TitleFont = $Script:AF.Preset; $t.Tag2 = "ACTIF" }
        if ($kind -eq 3) { $t.TitleFont = $Script:AF.Chip; $t.BackColor = $parent.BackColor }
        if ($glyph -and $Script:AF.Glyph) { $t.Glyph = $glyph; $t.GlyphFont = $Script:AF.GlyphBig }
    } else {
        $t = New-GBButtonCtl
        $t.ForeColor = $accent; $t.Font = $Script:AF.Tile
        if ($Script:UiOK) { $t.Desc = $desc; $t.DescFont = $fontSmall; $t.Text = $title }
        else {
            $t.TextAlign = "MiddleLeft"; $t.Padding = New-Object System.Windows.Forms.Padding(8, 0, 4, 0); $t.FlatAppearance.BorderColor = $accent
            $t.Text = $title; if ($desc -and $kind -ne 3) { $t.Text = $title + "`r`n" + $desc }
        }
    }
    $t.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $t.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    $parent.Controls.Add($t); return $t
}
function Set-GBArenaTile($t, [string]$title, [string]$desc, $accent = $null) {
    if (-not $t) { return }
    if ($t -is [System.Windows.Forms.Button]) {
        $txt = $title
        if ($t.GetType().Name -eq 'GBButton') { $t.Desc = $desc; $t.Invalidate() } elseif ($desc) { $txt = $title + "`r`n" + $desc }
        if ($t.Text -cne $txt) { $t.Text = $txt }
        if ($accent) { $t.ForeColor = $accent; if (-not $Script:UiOK) { $t.FlatAppearance.BorderColor = $accent } }
        return
    }
    $ch = ($t.Title -cne $title -or $t.Desc -cne $desc)
    $t.Title = $title; $t.Desc = $desc
    if ($accent -and $t.Accent -ne $accent) { $t.Accent = $accent; $ch = $true }
    if ($ch) { $t.Invalidate() }
}
function New-GBArenaStat($parent, [string]$label, [string]$unit, [string]$glyph, $x, $y, $w, $h, [bool]$ring) {
    $A = $Script:AC
    if ($Script:ArenaFxOK) {
        $s = New-Object GBArenaStat
        $s.Label = $label; $s.Unit = $unit; $s.Radius = $A.Radius; $s.Accent = $A.Accent; $s.Warn = $A.Yellow; $s.Alert = $A.Red
        $s.Border = $A.Line; $s.Muted = $A.Muted; $s.Track = $A.Track; $s.BackColor = $A.Card; $s.ForeColor = $A.Text
        $s.Font = $fontUI; $s.LabelFont = $Script:AF.Label; $s.ValueFont = $Script:AF.Big; $s.UnitFont = $Script:AF.Unit; $s.SubFont = $fontSmall
        if ($glyph -and $Script:AF.Glyph) { $s.Glyph = $glyph; $s.GlyphFont = $Script:AF.Glyph }
        if (-not $ring) { $s.Pct = -1 } else { $s.Pct = 0 }
        $s.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $s.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
        $parent.Controls.Add($s)
        return @{ Ctl = $s; Ring = $ring }
    }
    # Repli : un panneau et trois textes
    $p = New-Object System.Windows.Forms.Panel; $p.BackColor = $A.Card
    $p.Location = New-Object System.Drawing.Point([int]$x, [int]$y); $p.Size = New-Object System.Drawing.Size([int]$w, [int]$h)
    $parent.Controls.Add($p)
    $null = New-GBArenaLabel $p $label 14 10 ($w - 28) 18 $Script:AF.Label $A.Muted
    $v = New-GBArenaLabel $p "--" 12 30 ($w - 24) 46 $Script:AF.Big $A.Text
    $sb = New-GBArenaLabel $p "" 14 ($h - 28) ($w - 28) 18 $fontSmall $A.Muted
    return @{ Ctl = $p; Val = $v; Sub = $sb; Unit = $unit; Ring = $ring }
}
function Set-GBArenaStat($st, [string]$value, [string]$sub, $pct, [string]$ringText = '', $ringColor = $null, $subColor = $null) {
    if (-not $st) { return }
    if ($Script:ArenaFxOK) {
        $c = $st.Ctl; $p = -1.0; if ($st.Ring) { $p = 0.0; if ($null -ne $pct) { $p = [double]$pct } }
        $c.RingText = $ringText; if ($ringColor) { $c.RingTextColor = $ringColor } else { $c.RingTextColor = [System.Drawing.Color]::Empty }
        if ($subColor) { $c.SubColor = $subColor } else { $c.SubColor = [System.Drawing.Color]::Empty }
        $c.SetData($value, $c.Unit, $sub, [single]$p); $c.Invalidate()
        return
    }
    $t = $value; if ($value -ne '--' -and $st.Unit) { $t += " " + $st.Unit }
    if ($ringText) { $t += "   " + $ringText }
    if ($st.Val.Text -ne $t) { $st.Val.Text = $t }
    if ($st.Sub.Text -ne $sub) { $st.Sub.Text = $sub }
    if ($ringColor) { $st.Val.ForeColor = $ringColor } else { $st.Val.ForeColor = $Script:AC.Text }
}
# Etat d'une tuile (interrupteur, selection, badge) : sans effet sur un bouton de repli sauf le texte
function Set-GBArenaFlag($t, [string]$name, [bool]$on) {
    if (-not $t) { return }
    if ($t -is [System.Windows.Forms.Button]) {
        # Repli : un interrupteur allume se voit a son fond teinte de sa couleur
        if ($name -eq 'Checked') {
            $a = $Script:AC.Card; $f = $t.ForeColor; $k = $(if ($on) { 0.22 } else { 0.0 })
            $t.BackColor = [System.Drawing.Color]::FromArgb(255, [int]($a.R + ($f.R - $a.R) * $k), [int]($a.G + ($f.G - $a.G) * $k), [int]($a.B + ($f.B - $a.B) * $k))
        }
        return
    }
    $t.$name = $on
}

# --- Bibliotheque : icones des jeux (exe trouve par le moteur), initiales sinon ---
$Script:ArenaIcons = @{}
function Get-GBArenaIcon([string]$name) {
    if (-not $name) { return $null }
    $k = $name.ToLower(); $e = $Script:ArenaIcons[$k]
    if ($e -and ($e.Bmp -or ((Get-Date) - $e.T).TotalSeconds -lt 120)) { return $e.Bmp }
    $bmp = $null
    try {
        $path = Find-GBGameExe $name
        if ($path -and (Test-Path -LiteralPath $path)) { $ic = [System.Drawing.Icon]::ExtractAssociatedIcon($path); if ($ic) { $bmp = $ic.ToBitmap(); $ic.Dispose() } }
    } catch {}
    $Script:ArenaIcons[$k] = @{ Bmp = $bmp; T = (Get-Date) }
    return $bmp
}
function Get-GBArenaMono([string]$label) {
    $w = @(([string]$label).ToUpper() -split '[^A-Z0-9]+' | Where-Object { $_ })
    if ($w.Count -ge 2) { return ($w[0].Substring(0, 1) + $w[1].Substring(0, 1)) }
    if ($w.Count -eq 1) { return $w[0].Substring(0, [math]::Min(2, $w[0].Length)) }
    return "?"
}
# Couleur stable par jeu (la bibliotheque reste coloree, comme des jaquettes)
function Get-GBArenaGameColor([string]$name) {
    $pal = @($Script:AC.Accent, $Script:AC.Violet, $Script:AC.Accent2, $Script:AC.Green, $cCyan)
    $h = 0; foreach ($ch in ([string]$name).ToCharArray()) { $h = ($h * 31 + [int]$ch) % 9973 }
    return $pal[$h % $pal.Count]
}
function Get-GBArenaGameDesc([string]$name) {
    $lv = Get-GameProfileLevel $name
    if ($null -ne $lv -and $lv -ge 0 -and $lv -lt $Script:GameLevels.Count) { return @(("PROFIL " + $Script:GameLevels[$lv].L.ToUpper()), $Script:GameLevels[$lv].C) }
    return @(($name + ".exe"), $Script:AC.Muted)
}
function Set-GBArenaGameTile($t, [string]$name) {
    $label = Get-GameLabel $name
    $d = Get-GBArenaGameDesc $name
    $t.Tag = $name
    if ($Script:ArenaFxOK) {
        $t.Title = $label.ToUpper(); $t.Desc = $d[0]; $t.DescColor = $d[1]
        $t.Accent = Get-GBArenaGameColor $name; $t.Picture = Get-GBArenaIcon $name; $t.Monogram = Get-GBArenaMono $label
        $t.Selected = ([string]$lstGames.SelectedItem -eq $name)
        $t.Invalidate()
    } else {
        $t.Text = $label + "`r`n" + $d[0]
        $img = Get-GBArenaIcon $name; if ($img) { $t.Image = $img; $t.TextImageRelation = "ImageAboveText" }
    }
    $tip.SetToolTip($t, ($label + " (" + $name + ".exe)`r`nClic droit : profil du jeu, optimisations permanentes."))
}
function Select-GBArenaGame([string]$name) {
    $i = $lstGames.Items.IndexOf($name)
    if ($i -ge 0) { $lstGames.SelectedIndex = $i }
    foreach ($t in @($Script:ArenaGameTiles) + @($Script:ArenaMiniTiles)) {
        if ($t -and -not $t.IsDisposed -and $t.Tag -and [string]$t.Tag -ne '+') { Set-GBArenaFlag $t 'Selected' ([string]$t.Tag -eq $name) }
    }
}
# Gestionnaires des tuiles de jeux : clic = choisir, clic droit = menu du moteur (profil, optimisations permanentes)
$Script:ArenaGameClick = {
    $n = [string]$this.Tag
    if ($n -eq '+') { Invoke-GBArenaClick $btnBrowse; Update-GBArenaGames; return }
    if ($n -eq '*') { Show-GBPage 'games'; return }
    Select-GBArenaGame $n
}
$Script:ArenaGameMouseUp = {
    param($sender, $e)
    if ($e.Button -ne [System.Windows.Forms.MouseButtons]::Right) { return }
    $n = [string]$sender.Tag; if (-not $n -or $n -eq '+' -or $n -eq '*') { return }
    Select-GBArenaGame $n
    if ($lstGames.ContextMenuStrip) { $lstGames.ContextMenuStrip.Show($sender, $e.Location) }
}
function Update-GBArenaGames {
    if (-not $Script:ArenaGrid) { return }
    $games = @($Script:Config.Games | Where-Object { $_ })
    $sig = ($games -join '|') + '#' + (@($Script:Config.GameProfiles.Keys | ForEach-Object { [string]$_ + '=' + $Script:Config.GameProfiles[$_] }) -join ',') + '#' + [string]$lstGames.SelectedItem
    # Bibliotheque complete (page JEUX) : reconstruite seulement si la liste a change
    $listSig = ($games -join '|')
    if ($listSig -ne $Script:ArenaGridSig) {
        $Script:ArenaGridSig = $listSig
        $g = $Script:ArenaGrid; $k = Get-GBArenaK
        $g.SuspendLayout()
        foreach ($t in @($Script:ArenaGameTiles)) { if ($t) { $g.Controls.Remove($t); $t.Dispose() } }
        $Script:ArenaGameTiles = New-Object System.Collections.ArrayList
        $g.AutoScrollPosition = New-Object System.Drawing.Point(0, 0)
        $tw = [int](144 * $k); $th = [int](168 * $k); $gap = [int](12 * $k)
        $cols = [math]::Max(1, [int][math]::Floor(($g.ClientSize.Width - [System.Windows.Forms.SystemInformation]::VerticalScrollBarWidth + $gap) / ($tw + $gap)))
        $i = 0
        foreach ($n in @($games) + @('+')) {
            $x = ($i % $cols) * ($tw + $gap); $y = [math]::Floor($i / $cols) * ($th + $gap)
            if ($n -eq '+') {
                $t = New-GBArenaTile $g 1 "AJOUTER UN JEU" "choisir le .exe" "" $Script:AC.Muted $x $y $tw $th
                $t.Tag = '+'; if ($Script:ArenaFxOK) { $t.Monogram = "+"; $t.Accent = $Script:AC.Line }
                $tip.SetToolTip($t, "Ajouter un jeu : choisis son .exe (ou un programme ouvert, a droite)")
            } else {
                $t = New-GBArenaTile $g 1 "" "" "" $null $x $y $tw $th
                Set-GBArenaGameTile $t $n
                $t.Add_MouseUp($Script:ArenaGameMouseUp)
            }
            $t.Add_Click($Script:ArenaGameClick)
            [void]$Script:ArenaGameTiles.Add($t); $i++
        }
        $g.ResumeLayout()
        if ($Script:ArenaGamesEmpty) { $Script:ArenaGamesEmpty.Visible = ($games.Count -eq 0) }
    } elseif ($sig -ne $Script:ArenaGamesSig) {
        foreach ($t in @($Script:ArenaGameTiles)) { if ($t -and [string]$t.Tag -ne '+') { Set-GBArenaGameTile $t ([string]$t.Tag) } }
    }
    $Script:ArenaGamesSig = $sig
    # Raccourci vers la bibliotheque sur la page JOUER : les 4 premiers jeux + "tout voir"
    for ($j = 0; $j -lt $Script:ArenaMiniTiles.Count; $j++) {
        $t = $Script:ArenaMiniTiles[$j]
        if ($j -lt [math]::Min(4, $games.Count)) { Set-GBArenaGameTile $t ([string]$games[$j]); $t.Visible = $true }
        elseif ($j -eq [math]::Min(4, $games.Count)) {
            $t.Tag = $(if ($games.Count -eq 0) { '+' } else { '*' })
            $lbl = $(if ($games.Count -eq 0) { "AJOUTER" } else { "TOUT VOIR" })
            if ($Script:ArenaFxOK) { $t.Title = $lbl; $t.Desc = $(if ($games.Count -eq 0) { "ton premier jeu" } else { "" + $games.Count + " jeu(x)" }); $t.DescColor = $Script:AC.Muted; $t.Picture = $null; $t.Monogram = $(if ($games.Count -eq 0) { "+" } else { [string][char]0x2192 }); $t.Accent = $Script:AC.Line; $t.Selected = $false; $t.Invalidate() }
            else { $t.Text = $lbl; $t.Image = $null }
            $tip.SetToolTip($t, $lbl); $t.Visible = $true
        } else { $t.Visible = $false }
    }
    if ($Script:ArenaChipGames) {
        $n = $games.Count; $tx = $(if ($n -eq 0) { "AUCUN JEU" } elseif ($n -eq 1) { "1 JEU" } else { "" + $n + " JEUX" })
        if ($chkKnown.Checked) { $tx += " + POPULAIRES" }
        Set-GBArenaTile $Script:ArenaChipGames $tx ""
    }
}

# --- Etat du boost : titre du heros, pastille de la barre, pulsation du BOOST (pendant le jeu seulement) ---
function Update-GBArenaState {
    if (-not $Script:ArenaHeroTitle) { return }
    $A = $Script:AC
    if ($Script:Boosted -and $Script:MeasureOnlySession) { $t = "MESURE EN COURS"; $chip = "MESURE"; $cc = $A.Yellow }
    elseif ($Script:Boosted) { $t = "EN JEU"; $chip = "EN JEU"; $cc = $A.Accent }
    else { $t = "PRET AU COMBAT"; $chip = "PRET"; $cc = $A.Green }
    if ($Script:ArenaHeroTitle.Text -ne $t) { $Script:ArenaHeroTitle.Text = $t }
    Set-GBArenaTile $Script:ArenaChipState $chip "" $cc
    if ($Script:ArenaFxOK -and $Script:ArenaHero) { $Script:ArenaHero.Pulse = [bool]($Script:Boosted -and -not $Script:MeasureOnlySession) }
    if ($Script:ArenaBoostKey) {
        $k = ''; if (Get-Command Get-GBActionKey -ErrorAction Ignore) { try { $k = [string](Get-GBActionKey 'boost.toggle') } catch {} }
        $Script:ArenaBoostKey.Text = $(if ($k) { "raccourci " + $k + " (marche aussi en jeu)" } else { "un clic : jeu, Discord et l'essentiel" })
    }
    if ($Script:ArenaWasBoosted -ne [bool]$Script:Boosted) { $Script:ArenaWasBoosted = [bool]$Script:Boosted; Update-GBArenaLast }
}
# Derniere partie (historique "Mes parties")
function Update-GBArenaLast {
    if (-not $Script:ArenaHeroLast) { return }
    $last = $null; try { $idx = @(Get-SessionIndex); if ($idx.Count) { $last = $idx[$idx.Count - 1] } } catch {}
    if ($Script:Boosted -and $Script:SessionGame -and [string]$Script:SessionGame -notlike '(*') {
        $Script:ArenaHeroLast.Text = "Partie en cours : " + ([string]$Script:SessionGame).ToUpper()
    } elseif ($last) {
        $Script:ArenaHeroLast.Text = "Derniere partie : " + ([string]$last.Jeu).ToUpper() + $Script:ArenaDot + $last.DureeMin + " min" + $(if ($last.Fps) { $Script:ArenaDot + $last.Fps + " FPS" } else { "" })
    } else { $Script:ArenaHeroLast.Text = "Aucune partie enregistree pour l'instant : lance BOOST et joue." }
    if ($Script:ArenaLastCard) {
        $L = $Script:ArenaLastCard
        if ($last) {
            $when = [string]$last.Date
            try {
                $d = [datetime]::ParseExact([string]$last.Date, 'yyyy-MM-dd HH:mm', [Globalization.CultureInfo]::InvariantCulture)
                $ago = (Get-Date) - $d
                if ($ago.TotalMinutes -lt 60) { $when = "il y a " + [int][math]::Max(1, $ago.TotalMinutes) + " min" }
                elseif ($ago.TotalHours -lt 24) { $when = "il y a " + [int]$ago.TotalHours + " h" }
                elseif ($ago.TotalDays -lt 2) { $when = "hier, " + $d.ToString('HH:mm') }
                else { $when = $d.ToString('dd/MM') }
            } catch {}
            $L.Name.Text = ([string]$last.Jeu).ToUpper()
            $L.When.Text = $when + $Script:ArenaDot + $last.DureeMin + " min" + $Script:ArenaDot + [string]$last.Mode
            $f = "FPS --"; if ($last.Fps) { $f = "" + $last.Fps + " FPS moy." + $(if ($last.Low1) { $Script:ArenaDot + "1% bas " + $last.Low1 } else { "" }) }
            $L.Fps.Text = $f
            $proc = [string]$last.Jeu; foreach ($kk in @($KnownGames.Keys)) { if ([string]$KnownGames[$kk] -eq [string]$last.Jeu) { $proc = $kk; break } }
            if ($Script:ArenaFxOK) { $L.Art.Monogram = Get-GBArenaMono ([string]$last.Jeu); $L.Art.Picture = Get-GBArenaIcon $proc; $L.Art.Accent = Get-GBArenaGameColor $proc; $L.Art.Invalidate() }
        } else {
            $L.Name.Text = "PAS ENCORE DE PARTIE"; $L.When.Text = "Joue au moins 1 minute avec BOOST :"; $L.Fps.Text = "FPS, 1 % bas et duree s'afficheront ici."
            if ($Script:ArenaFxOK) { $L.Art.Monogram = "?"; $L.Art.Picture = $null; $L.Art.Accent = $Script:AC.Line; $L.Art.Invalidate() }
        }
    }
}
# Niveau gaming : presets du LOADOUT et pastille du heros
function Update-GBArenaLevel {
    if (-not $Script:ArenaPresets) { return }
    $lv = Get-GameLevelNow
    for ($i = 0; $i -lt $Script:ArenaPresets.Count; $i++) { Set-GBArenaFlag $Script:ArenaPresets[$i] 'Selected' ($i -eq $lv) }
    if ($Script:ArenaChipLevel) {
        if ($lv -ge 0) { Set-GBArenaTile $Script:ArenaChipLevel ("LOADOUT " + $Script:GameLevels[$lv].L.ToUpper()) "" $Script:GameLevels[$lv].C }
        else { Set-GBArenaTile $Script:ArenaChipLevel "LOADOUT PERSO" "" $Script:AC.Yellow }
    }
}
# Applique un preset en passant par le curseur du moteur (meme validation, meme confirmation pour Extreme)
function Set-GBArenaPreset([int]$i) {
    try {
        if ($sldGame -is [System.Windows.Forms.TrackBar]) {
            $sldGame.Value = $i
            $m = [System.Windows.Forms.Control].GetMethod('OnMouseUp', [System.Reflection.BindingFlags]'Instance, NonPublic')
            $me = (New-Object System.Windows.Forms.MouseEventArgs([System.Windows.Forms.MouseButtons]::Left, 1, 0, 0, 0)).PSObject.BaseObject
            [void]$m.Invoke($sldGame, [object[]]@($me))
        } else {
            $sldGame.Value = $i
            $m = $sldGame.GetType().GetMethod('Commit', [System.Reflection.BindingFlags]'Instance, NonPublic')
            [void]$m.Invoke($sldGame, $null)
        }
    } catch { Log ("ARENA : preset impossible (" + $_.Exception.Message + ")") }
    Update-GBArenaLevel
}
# Interrupteurs rapides de la page JOUER : ils refletent l'etat du moteur
function Update-GBArenaQuick {
    $Q = $Script:ArenaQuick; if (-not $Q) { return }
    $A = $Script:AC
    $on = [bool]$chkAuto.Checked
    Set-GBArenaTile $Q.Auto "BOOST AUTO" $(if ($on) { "se lance avec ton jeu" } else { "manuel : bouton BOOST" }); Set-GBArenaFlag $Q.Auto 'Checked' $on
    if ($Script:BtnTurbo) {
        $tOn = ([string]$Script:BtnTurbo.Text -match 'ON')
        Set-GBArenaTile $Q.Turbo "TURBO CPU" $(if ($tOn) { "turbo normal, toujours" } else { "coupe hors jeu, PC frais" }); Set-GBArenaFlag $Q.Turbo 'Checked' $tOn
    }
    if ($Script:BtnGpu) {
        $gOn = ([string]$Script:BtnGpu.Text -match 'ON')
        Set-GBArenaTile $Q.Gpu "GPU" $(if ($gOn) { "frequence maximale" } else { "ECO hors jeu" }); Set-GBArenaFlag $Q.Gpu 'Checked' $gOn
    }
    $ov = [bool]$Script:Config.Overlay
    Set-GBArenaTile $Q.Overlay "OVERLAY" $(if ($ov) { "FPS a l'ecran en jeu" } else { "cache pendant le jeu" }); Set-GBArenaFlag $Q.Overlay 'Checked' $ov
    $nm = 1; try { if (Get-Command Get-GBMonitors -ErrorAction Ignore) { $nm = @(Get-GBMonitors).Count } else { $nm = [System.Windows.Forms.Screen]::AllScreens.Count } } catch {}
    $off = @($Script:Config.MonitorsOff | Where-Object { $_ }).Count
    Set-GBArenaTile $Q.Screens "ECRANS" $(if ($off -gt 0) { "" + $off + " eteint(s) sur " + $nm } else { "" + $nm + " ecran(s) allume(s)" }); Set-GBArenaFlag $Q.Screens 'Badge' ($off -gt 0)
    $nl = @($Script:Config.LinkedApps | Where-Object { $_ -and $_.Enabled }).Count
    Set-GBArenaTile $Q.Links "LIENS" $(if ($nl -gt 0) { "" + $nl + " lancement(s) lie(s)" } else { "lancer 2 exe ensemble" })
}
function Switch-GBArenaOverlay {
    $done = $false
    if (Get-Command Invoke-GBAction -ErrorAction Ignore) { try { $done = [bool](Invoke-GBAction 'overlay.toggle') } catch {} }
    if (-not $done) {
        # Meme effet que la case de "Mes parties"
        $Script:Config.Overlay = -not [bool]$Script:Config.Overlay; Save-Config
        if (-not $Script:Config.Overlay) { Hide-GBOverlay }
        Log ("Overlay en jeu : " + $(if ($Script:Config.Overlay) { "active" } else { "desactive" }))
    }
    Update-GBArenaQuick
}
# Nouveau pilote : pastille du heros + point jaune sur ARSENAL et sur la tuile Pilotes
function Update-GBArenaDriver {
    if ($Script:ArenaDriverBusy) { return }
    $Script:ArenaDriverBusy = $true
    try {
        # (premiere ligne seulement : en mode secours le bouton affiche aussi sa description)
        $first = ([string]$btnDrivers.Text -split "`r`n")[0]
        $on = ($first -match 'NOUVEAU'); $Script:ArenaDriverOn = $on
        if ($Script:ArenaChipDriver) { $Script:ArenaChipDriver.Visible = $on }
        if ($Script:Pages -and $Script:Pages.Contains('tools')) { Set-GBArenaFlag $Script:Pages['tools'].Nav 'Badge' $on }
        if ($btnDrivers.GetType().Name -eq 'GBButton') { $btnDrivers.Badge = $on }
        # (le texte du moteur "NOUVEAU PILOTE GPU !" est garde tel quel)
        if ($on) { Set-GBArenaTile $btnDrivers $first "Nouveau pilote graphique : clique pour l'installer." }
        else { Set-GBArenaTile $btnDrivers "PILOTES" "Pilotes certifies pour ton materiel." }
    } finally { $Script:ArenaDriverBusy = $false }
}
# Champ de la mesure du moteur (table ordonnee ou objet), $null s'il n'existe pas
function Get-GBArenaField($s, [string]$n) {
    if ($null -eq $s) { return $null }
    if ($s -is [System.Collections.IDictionary]) { if ($s.Contains($n)) { return $s[$n] }; return $null }
    $p = $s.PSObject.Properties[$n]; if ($p) { return $p.Value }
    return $null
}
# HUD en direct (crochet de mesure, toutes les 5 s) : FPS, CPU, GPU, RAM, ping + temperatures
function Update-GBArenaHud($s) {
    if (-not $Script:ArenaHud -or -not $form.Visible -or $form.WindowState -eq 'Minimized') { return }
    $A = $Script:AC; $H = $Script:ArenaHud
    $pg = [string]$Script:CurrentPage
    if ($pg -ne 'home' -and $pg -ne 'perfs') { return }
    $t = $null; if (Get-Command Get-GBSensors -ErrorAction Ignore) { try { $t = Get-GBSensors } catch {} }
    $hasTemp = [bool](Get-Command Get-GBTempLevel -ErrorAction Ignore)
    if ($pg -eq 'home') {
        $fps = Get-GBArenaField $s 'Fps'; $low = Get-GBArenaField $s 'FpsLow'
        if ($null -eq $fps -and $Script:Boosted) { $m = [regex]::Match([string]$lblStats.Text, 'FPS (\d+)\s*\(1% bas (\d+)'); if ($m.Success) { $fps = $m.Groups[1].Value; $low = $m.Groups[2].Value } }
        if ($null -ne $fps) { Set-GBArenaStat $H.Fps ([string]$fps) ("1% bas " + $low) $null }
        else { Set-GBArenaStat $H.Fps "--" $(if ($Script:Boosted) { "mesure en cours..." } else { "affiche pendant le boost" }) $null }
        $cpu = Get-GBArenaField $s 'Cpu'; $gpu = Get-GBArenaField $s 'DgpuU'; if ($null -eq $gpu) { $gpu = Get-GBArenaField $s 'Gpu' }; $ram = Get-GBArenaField $s 'RamPct'
        $ct = ''; $cc = $null; $gt = ''; $gc = $null
        if ($t -and $hasTemp) {
            if ($null -ne $t.CpuTemp) { $ct = "" + [int][math]::Round([double]$t.CpuTemp) + [char]0xB0; $cc = Get-GBTempColor (Get-GBTempLevel $t.CpuTemp 'cpu') }
            if ($null -ne $t.GpuTemp) { $gt = "" + [int][math]::Round([double]$t.GpuTemp) + [char]0xB0; $gc = Get-GBTempColor (Get-GBTempLevel $t.GpuTemp 'gpu') }
        }
        $csub = "processeur"; $cmx = Get-GBArenaField $s 'CpuMaxCore'; if ($null -ne $cmx) { $csub = "max " + $cmx + " %" }
        if ($t -and $t.CpuMhz) { $csub += $Script:ArenaDot + ([math]::Round([double]$t.CpuMhz / 1000, 1)).ToString([Globalization.CultureInfo]::InvariantCulture) + " GHz" }
        Set-GBArenaStat $H.Cpu $(if ($null -ne $cpu) { [string]$cpu } else { "--" }) $csub $cpu $ct $cc
        $gsub = "carte graphique"; if ($Script:MainGpu -and $Script:MainGpu.Short) { $gsub = [string]$Script:MainGpu.Short }
        if (Get-GBArenaField $s 'DgpuSleep') { $gsub = "carte en veille" }
        Set-GBArenaStat $H.Gpu $(if ($null -ne $gpu -and "$gpu" -match '^\d') { [string]$gpu } else { "--" }) $gsub $(if ("$gpu" -match '^\d') { $gpu } else { 0 }) $gt $gc
        $rsub = "memoire"; $ru = Get-GBArenaField $s 'RamUsedGo'; $rt = Get-GBArenaField $s 'RamTotalGo'; if ($null -ne $ru -and $null -ne $rt) { $rsub = "" + $ru + " / " + $rt + " Go" }
        Set-GBArenaStat $H.Ram $(if ($null -ne $ram) { [string]$ram } else { "--" }) $rsub $ram
        $ping = Get-GBArenaField $s 'Ping'
        if ($null -eq $ping -and $Script:FastOK) { try { $pv = [GBPinger]::Last; if ($pv -ge 0) { $ping = $pv } } catch {} }
        $pp = 0; if ($null -ne $ping) { $pp = [math]::Min(100, [double]$ping / 1.5) }
        Set-GBArenaStat $H.Ping $(if ($null -ne $ping) { [string]$ping } else { "--" }) $(if ($null -ne $ping -and $ping -ge 100) { "ping eleve" } else { "latence" }) $pp
    }
    if ($pg -eq 'perfs' -and $Script:ArenaTemps) {
        $T = $Script:ArenaTemps
        if ($T.Live -and $t) {
            try {
                # (API capteurs : le controle, la cle de Get-GBSensors, le type de seuils)
                Update-GBRingCtl $T.CpuRing 'CpuTemp' 'cpu' -Caption 'CPU'
                Update-GBRingCtl $T.GpuRing 'GpuTemp' 'gpu' -Caption 'GPU'
                Update-GBSparkCtl $T.CpuSpark 'CpuTemp' 'cpu' -Caption 'PROCESSEUR' -Sub ([string]$t.CpuTempSrc)
                Update-GBSparkCtl $T.GpuSpark 'GpuTemp' 'gpu' -Caption ([string]$(if ($t.GpuName) { ([string]$t.GpuName).ToUpper() } else { 'CARTE GRAPHIQUE' })) -Sub ([string]$t.GpuTempSrc)
            } catch { $Script:ArenaNote2 = "ARENA : temperatures (" + $_.Exception.Message + ")" }
        }
    }
}
# Une page s'affiche : ses donnees sont remises a jour (rien n'est calcule pour une page cachee)
function Update-GBArenaPage([string]$key) {
    $smp = $Script:ArenaLastSample; if (-not $smp) { $smp = $Script:LastSample }
    switch ($key) {
        'home'  { Update-GBArenaGames; Update-GBArenaQuick; Update-GBArenaLast; Update-GBArenaLevel; Update-GBArenaHud $smp }
        'games' { Update-GBArenaGames }
        'optim' { Update-GBArenaLevel }
        'perfs' { Update-GBArenaHud $smp }
    }
}

function Build-GBLayoutArena {
    # Composants ARENA (une seule compilation, gardee en cache) ; GBMotion.Reduced est recopie (animations Windows coupees)
    if ($Script:UiOK) {
        try {
            $refs = $uiRefs; if (-not $refs) { $refs = @('System.Windows.Forms', 'System.Drawing') }
            $Script:ArenaFxOK = [bool](Add-GBCompiled 'GBArena' $arenaSrc $refs 'GBArenaTile')
        } catch { $Script:ArenaFxOK = $false }
        if ($Script:ArenaFxOK) { try { [GBArenaFx]::Reduced = [bool][GBMotion]::Reduced } catch {} }
        # (message ecrit a la fin : Log fait DoEvents, la fenetre pourrait s afficher avant la fin de la mise en page)
    }
    # Palette ARENA (socle) ; repli sur la palette de base si une couleur manque
    $acc = $cAccent; if (-not $acc) { $acc = $cCyan }
    $acc2 = $cAccent2; if (-not $acc2) { $acc2 = $cYellow }
    $card = $cCard; if (-not $card) { $card = $cPanel }
    $rad = 12; if ($Script:Theme -and $Script:Theme.Radius) { $rad = [int]$Script:Theme.Radius + 2 }
    $Script:AC = @{
        Bg = $cBg; Card = $card; Tile = [System.Drawing.Color]::FromArgb(255, [math]::Min(255, $card.R + 8), [math]::Min(255, $card.G + 7), [math]::Min(255, $card.B + 10))
        Bar = $cRail; Line = $cLine; Text = $cText; Muted = $cMuted; Accent = $acc; Accent2 = $acc2; Green = $cGreen; Red = $cRed; Yellow = $cYellow; Violet = $cViolet
        Track = [System.Drawing.Color]::FromArgb(255, [math]::Min(255, $card.R + 22), [math]::Min(255, $card.G + 20), [math]::Min(255, $card.B + 28)); Radius = $rad
    }
    $A = $Script:AC
    # Polices : Bahnschrift (gras, condense pour les gros chiffres), icones Segoe Fluent / MDL2
    $bold = [System.Drawing.FontStyle]::Bold
    $Script:AF = @{
        Logo   = Get-GBFont @("Bahnschrift", "Segoe UI Black") 17 $bold
        Tab    = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 11.5
        Hero   = Get-GBFont @("Bahnschrift Condensed", "Bahnschrift", "Segoe UI Black") 32 $bold
        HeroSub = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 11.5
        Boost  = Get-GBFont @("Bahnschrift", "Segoe UI Black") 20 $bold
        Big    = Get-GBFont @("Bahnschrift SemiBold Condensed", "Bahnschrift SemiBold", "Segoe UI Semibold") 28
        Unit   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10
        Label  = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 9
        Card   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 11.5
        Tile   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 10.5
        Preset = Get-GBFont @("Bahnschrift", "Segoe UI Black") 14 $bold
        Chip   = Get-GBFont @("Bahnschrift SemiBold", "Segoe UI Semibold") 9
        Mono   = Get-GBFont @("Bahnschrift", "Segoe UI Black") 22 $bold
        Glyph  = $null; GlyphBig = $null
    }
    foreach ($n in @("Segoe Fluent Icons", "Segoe MDL2 Assets")) {
        try { $f = New-Object System.Drawing.Font($n, [single]11); if ($f.Name -eq $n) { $Script:AF.Glyph = $f; $Script:AF.GlyphBig = New-Object System.Drawing.Font($n, [single]14); break }; $f.Dispose() } catch {}
    }
    $G = @{ Play = [string][char]0xE768; Game = [string][char]0xE7FC; Bolt = [string][char]0xE945; Perf = [string][char]0xEC4A; Tools = [string][char]0xE90F
            Sync = [string][char]0xE895; Gpu = [string][char]0xF211; Eye = [string][char]0xE7B3; Screen = [string][char]0xE7F4; Link = [string][char]0xE71B
            Cpu = [string][char]0xE950; Net = [string][char]0xEC05; Sys = [string][char]0xE770; Chart = [string][char]0xE9D9; Temp = [string][char]0xE9CA; Ram = [string][char]0xE964 }

    # Fenetre un peu plus large : barre d'onglets + pages de 1040 x 596
    $W = 1040; $H = 760; $BarH = 64; $PH = $H - $BarH; $P = 20; $IW = $W - 2 * $P
    if (Get-Command Set-GBShellSize -ErrorAction Ignore) { Set-GBShellSize $W $H }
    else { $Script:MainW = $W; $Script:MainH = $H; if ($Script:Body) { $Script:Body.Size = New-Object System.Drawing.Size($W, $H) } }
    $body = $Script:Body
    if (-not $body) { $body = $form }
    $body.BackColor = $A.Bg
    $body.SuspendLayout()
    # Controles du moteur non affiches par ARENA : gardes ici (jamais liberes, ils gardent leur etat)
    $Script:ArenaStash = New-Object System.Windows.Forms.Panel
    $Script:ArenaStash.Visible = $false; $Script:ArenaStash.Size = New-Object System.Drawing.Size(10, 10)
    $body.Controls.Add($Script:ArenaStash)
    foreach ($c in @($lstGames, $sldGame, $chkAuto, $ttl, $lblGameLvl)) { if ($c -and -not $c.IsDisposed) { Set-GBPlace $c $Script:ArenaStash 0 0 0 0 } }

    # --- Barre du haut : logo, onglets, etat du mode jeu ---
    $bar = New-GBArenaSurface $body 0 0 $W $BarH "" "" "" 2
    $Script:ArenaBar = $bar
    $null = New-GBArenaLabel $bar "GAMEBOOST" 18 0 150 $BarH $Script:AF.Logo $A.Text "MiddleLeft"
    # Pastille du modele : clic = changer de modele (NEXUS / ARENA / PURE)
    $tag = New-GBArenaTile $bar 3 ("ARENA " + [char]0x25BE) "" "" $A.Accent 164 20 98 24
    $tag.TabStop = $false
    if (Test-Path function:Add-GBEditionSwitch) { Add-GBEditionSwitch $tag } else { Set-GBArenaFlag $tag 'Static' $true; $tag.Cursor = [System.Windows.Forms.Cursors]::Default }
    $Script:Pages = [ordered]@{}; $Script:PageX = 0; $Script:PageW = $W; $Script:RailW = 0; $Script:OnLayoutChange = $null
    $Script:PageOrder = @('home', 'games', 'optim', 'perfs', 'tools')
    $navDef = @(@('home', 'JOUER', $G.Play, 108), @('games', 'JEUX', $G.Game, 100), @('optim', 'LOADOUT', $G.Bolt, 130), @('perfs', 'PERFS', $G.Perf, 110), @('tools', 'ARSENAL', $G.Tools, 126))
    $nx = 268
    foreach ($nv in $navDef) {
        if ($Script:ArenaFxOK) {
            $n = New-Object GBArenaNav
            $n.Accent = $A.Accent; $n.Accent2 = $A.Accent2; $n.Muted = $A.Muted; $n.Badge2 = $A.Yellow
            if ($Script:AF.Glyph) { $n.Glyph = $nv[2]; $n.GlyphFont = $Script:AF.Glyph }
        } else {
            $n = New-Object System.Windows.Forms.Button; $n.FlatStyle = "Flat"; $n.FlatAppearance.BorderSize = 0
            $n.FlatAppearance.MouseOverBackColor = $cSel; $n.BackColor = $A.Bar
        }
        $n.Text = $nv[1]; $n.Font = $Script:AF.Tab; $n.ForeColor = $A.Text; $n.Tag = $nv[0]
        $n.Location = New-Object System.Drawing.Point($nx, 0); $n.Size = New-Object System.Drawing.Size([int]$nv[3], ($BarH - 2))
        $bar.Controls.Add($n)
        $n.Add_Click({ Show-GBPage ([string]$this.Tag) })
        $pgp = New-Object System.Windows.Forms.Panel
        $pgp.Location = New-Object System.Drawing.Point(0, $BarH); $pgp.Size = New-Object System.Drawing.Size($W, $PH)
        $pgp.BackColor = $A.Bg; $pgp.Visible = $false; $pgp.Tag = $nv[0]
        if ($Script:UiOK) { try { [GBTheme]::DoubleBuffer($pgp) } catch {} }
        $body.Controls.Add($pgp)
        $pgp.Add_VisibleChanged({ if ($this.Visible) { Update-GBArenaPage ([string]$this.Tag) } })
        $Script:Pages[$nv[0]] = @{ Nav = $n; Page = $pgp; Title = $nv[1]; OnShow = $null }
        $nx += [int]$nv[3]
    }
    $Script:ArenaChipState = New-GBArenaTile $bar 3 "PRET" "" "" $A.Green ($W - $P - 150) 18 150 28
    $Script:ArenaChipState.Add_Click({ Show-GBPage 'home' })
    $tip.SetToolTip($Script:ArenaChipState, "Etat du mode jeu (clic : page JOUER)")
    $pgHome = $Script:Pages['home'].Page; $pgGames = $Script:Pages['games'].Page; $pgOpt = $Script:Pages['optim'].Page
    $pgPerf = $Script:Pages['perfs'].Page; $pgTools = $Script:Pages['tools'].Page

    # --- JOUER : heros (etat + BOOST), HUD en direct, interrupteurs rapides, derniere partie, bibliotheque ---
    $hero = New-GBArenaSurface $pgHome $P 16 $IW 184 "" "" "" 1
    $Script:ArenaHero = $hero
    $null = New-GBArenaLabel $hero "MODE JEU" 30 22 300 18 $Script:AF.Label $A.Accent
    $Script:ArenaHeroTitle = New-GBArenaLabel $hero "PRET AU COMBAT" 26 36 600 56 $Script:AF.Hero $A.Text
    Set-GBPlace $lblStatus $hero 30 92 600 24
    $lblStatus.Font = $Script:AF.HeroSub; $lblStatus.BackColor = [System.Drawing.Color]::Transparent; $lblStatus.AutoEllipsis = $true
    $Script:ArenaHeroLast = New-GBArenaLabel $hero "" 30 117 600 20 $fontUI $A.Muted
    $Script:ArenaChipLevel = New-GBArenaTile $hero 3 "LOADOUT" "" "" $A.Accent 28 142 186 28
    $Script:ArenaChipLevel.Add_Click({ Show-GBPage 'optim' })
    $tip.SetToolTip($Script:ArenaChipLevel, "Niveau des optimisations du boost (clic : LOADOUT)")
    $Script:ArenaChipGames = New-GBArenaTile $hero 3 "JEUX" "" "" $A.Violet 222 142 186 28
    $Script:ArenaChipGames.Add_Click({ Show-GBPage 'games' })
    $tip.SetToolTip($Script:ArenaChipGames, "Jeux qui lancent le boost (clic : JEUX)")
    $Script:ArenaChipDriver = New-GBArenaTile $hero 3 "NOUVEAU PILOTE GPU" "" "" $A.Yellow 416 142 196 28
    $Script:ArenaChipDriver.Visible = $false
    $Script:ArenaChipDriver.Add_Click({ Invoke-GBArenaClick $btnDrivers })
    $bx = $IW - 28 - 300
    Set-GBPlace $btnBoost $hero $bx 36 300 100
    $btnBoost.Font = $Script:AF.Boost
    if ($Script:UiOK) { try { $btnBoost.Filled = $true } catch {} }
    if ($Script:ArenaFxOK) { $hero.PulseRect = New-Object System.Drawing.Rectangle($bx, 36, 300, 100) }
    $Script:ArenaBoostKey = New-GBArenaLabel $hero "" $bx 142 300 20 $fontSmall $A.Muted "MiddleCenter"

    $Script:ArenaHud = @{}
    $sw = [int](($IW - 4 * 12) / 5); $hy = 212; $hh = 104
    $Script:ArenaHud.Fps  = New-GBArenaStat $pgHome "FPS" "FPS" $G.Play ($P) $hy $sw $hh $false
    $Script:ArenaHud.Cpu  = New-GBArenaStat $pgHome "CPU" "%" $G.Cpu ($P + ($sw + 12)) $hy $sw $hh $true
    $Script:ArenaHud.Gpu  = New-GBArenaStat $pgHome "GPU" "%" $G.Gpu ($P + 2 * ($sw + 12)) $hy $sw $hh $true
    $Script:ArenaHud.Ram  = New-GBArenaStat $pgHome "RAM" "%" $G.Ram ($P + 3 * ($sw + 12)) $hy $sw $hh $true
    $Script:ArenaHud.Ping = New-GBArenaStat $pgHome "PING" "ms" $G.Net ($P + 4 * ($sw + 12)) $hy ($IW - 4 * ($sw + 12)) $hh $true
    if ($Script:ArenaFxOK) { $Script:ArenaHud.Fps.Ctl.Accent = $A.Accent2; $Script:ArenaHud.Ping.Ctl.WarnAt = 40; $Script:ArenaHud.Ping.Ctl.AlertAt = 66 }
    $tip.SetToolTip($Script:ArenaHud.Fps.Ctl, "Images par seconde du jeu (mesurees pendant le boost si la mesure des FPS est cochee)")
    $tip.SetToolTip($Script:ArenaHud.Cpu.Ctl, "Charge du processeur ; dans l'anneau : sa temperature")
    $tip.SetToolTip($Script:ArenaHud.Gpu.Ctl, "Charge de la carte graphique ; dans l'anneau : sa temperature")

    $Script:ArenaQuick = @{}
    $qw = [int](($IW - 5 * 12) / 6); $qy = 328; $qh = 100
    $Script:ArenaQuick.Auto    = New-GBArenaTile $pgHome 0 "BOOST AUTO" "" $G.Sync $A.Green ($P) $qy $qw $qh
    $Script:ArenaQuick.Turbo   = New-GBArenaTile $pgHome 0 "TURBO CPU" "" $G.Bolt $A.Yellow ($P + ($qw + 12)) $qy $qw $qh
    $Script:ArenaQuick.Gpu     = New-GBArenaTile $pgHome 0 "GPU" "" $G.Gpu $A.Accent ($P + 2 * ($qw + 12)) $qy $qw $qh
    $Script:ArenaQuick.Overlay = New-GBArenaTile $pgHome 0 "OVERLAY" "" $G.Eye $A.Accent2 ($P + 3 * ($qw + 12)) $qy $qw $qh
    $Script:ArenaQuick.Screens = New-GBArenaTile $pgHome 0 "ECRANS" "" $G.Screen $A.Violet ($P + 4 * ($qw + 12)) $qy $qw $qh
    $Script:ArenaQuick.Links   = New-GBArenaTile $pgHome 0 "LIENS" "" $G.Link $cCyan ($P + 5 * ($qw + 12)) $qy ($IW - 5 * ($qw + 12)) $qh
    foreach ($k in @('Auto', 'Turbo', 'Gpu', 'Overlay')) { Set-GBArenaFlag $Script:ArenaQuick[$k] 'Toggle' $true }
    $Script:ArenaQuick.Auto.Add_Click({ $chkAuto.Checked = -not $chkAuto.Checked; Update-GBArenaQuick })
    $Script:ArenaQuick.Turbo.Add_Click({ Invoke-GBArenaClick $Script:BtnTurbo; Update-GBArenaQuick })
    $Script:ArenaQuick.Gpu.Add_Click({ Invoke-GBArenaClick $Script:BtnGpu; Update-GBArenaQuick })
    $Script:ArenaQuick.Overlay.Add_Click({ Switch-GBArenaOverlay })
    $Script:ArenaQuick.Screens.Add_Click({ Invoke-GBArenaPanel 'Show-MonitorsPanel' 'Ecrans'; Update-GBArenaQuick })
    $Script:ArenaQuick.Links.Add_Click({ Invoke-GBArenaPanel 'Show-LinkedAppsPanel' 'Lancements lies'; Update-GBArenaQuick })
    $tip.SetToolTip($Script:ArenaQuick.Auto, "Le boost demarre tout seul quand un de tes jeux se lance, et tout est remis quand tu le quittes.")
    $tip.SetToolTip($Script:ArenaQuick.Turbo, "ON : turbo normal. OFF : turbo du processeur coupe hors jeu (il revient pendant le boost). Reglages : page PERFS.")
    $tip.SetToolTip($Script:ArenaQuick.Gpu, "ON : carte graphique a sa frequence maximale. ECO : limitee hors jeu, sans limite pendant le boost. Reglages : page PERFS.")
    $tip.SetToolTip($Script:ArenaQuick.Overlay, "Petit cadre FPS / CPU / GPU / ping au-dessus du jeu pendant le boost (jeux en fenetre ou sans bordure).")
    $tip.SetToolTip($Script:ArenaQuick.Screens, "Eteindre un ecran pendant le jeu (raccourci personnalisable), rallumer tout.")
    $tip.SetToolTip($Script:ArenaQuick.Links, "Lancer un .exe en meme temps qu'un autre (ex. ton jeu + son outil).")

    # Ecran et FPS : ecran, luminosite, limite de FPS, frequence, sur une seule ligne
    $by = 440
    if (Test-Path function:New-GBDisplayControls) {
        $ds = New-GBArenaSurface $pgHome $P 440 $IW 88 "ECRAN ET FPS" "luminosite, images par seconde, frequence" $G.Screen 0 $A.Green
        $null = New-GBDisplayControls $ds
        Set-GBDisplayRow $ds 16 46 52 200 $Script:DispLbl.Scr @($Script:DispScr, $Script:DispScrName)
        Set-GBDisplayRow $ds 288 46 82 190 $Script:DispLbl.Bright @($Script:DispBright, $Script:DispBrightNa)
        Set-GBDisplayRow $ds 566 46 94 130 $Script:DispLbl.Fps @($Script:DispFps)
        Set-GBDisplayRow $ds 798 46 0 70 $Script:DispLbl.Hz @($Script:DispHz)
        $Script:DispLbl.Hz.Visible = $false
        Set-GBPlace $Script:DispHzBtn $ds ($IW - 16 - 112) 46 112 26
        if ($Script:DispBright -isnot [System.Windows.Forms.TrackBar]) { $Script:DispBright.FillColor = $A.Green }
        $by = 540
    }
    $bh = $PH - 16 - $by
    $lc = New-GBArenaSurface $pgHome $P $by 330 $bh "DERNIERE PARTIE" "" $G.Chart 0
    $art = New-GBArenaTile $lc 1 "" "" "" $A.Accent 14 44 76 ($bh - 56)
    Set-GBArenaFlag $art 'Static' $true; $art.TabStop = $false
    $Script:ArenaLastCard = @{ Art = $art
        Name = New-GBArenaLabel $lc "" 100 44 214 22 $Script:AF.Tile $A.Text
        When = New-GBArenaLabel $lc "" 100 66 214 18 $fontSmall $A.Muted
        Fps  = New-GBArenaLabel $lc "" 100 86 214 18 $fontSmall $A.Accent2 }
    $hist = New-GBArenaTile $lc 3 "HISTORIQUE" "" "" $A.Accent 214 10 104 24
    $hist.Add_Click({ Invoke-GBArenaClick $btnGames })
    $tip.SetToolTip($hist, "Mes parties : FPS, 1 % bas, CPU, GPU, ping de chaque partie, overlay et sauvegardes de jeux")
    $lib = New-GBArenaSurface $pgHome ($P + 342) $by ($IW - 342) $bh "BIBLIOTHEQUE" "clic droit = profil du jeu" $G.Game 0
    $Script:ArenaMiniTiles = New-Object System.Collections.ArrayList
    $mw = [int](($IW - 342 - 28 - 4 * 10) / 5)
    for ($j = 0; $j -lt 5; $j++) {
        $t = New-GBArenaTile $lib 1 "" "" "" $A.Accent (14 + $j * ($mw + 10)) 40 $mw ($bh - 50)
        $t.Visible = $false; $t.Add_Click($Script:ArenaGameClick); $t.Add_Click({ if ([string]$this.Tag -notin @('+', '*')) { Show-GBPage 'games' } }); $t.Add_MouseUp($Script:ArenaGameMouseUp)
        [void]$Script:ArenaMiniTiles.Add($t)
    }

    # --- JEUX : bibliotheque en tuiles (la liste du moteur reste la source), ajout de jeux, apps autorisees ---
    $gl = New-GBArenaSurface $pgGames $P 16 676 ($PH - 32) "BIBLIOTHEQUE" "clic droit sur un jeu = profil, optimisations permanentes" $G.Game 0
    $Script:ArenaGrid = New-Object System.Windows.Forms.Panel
    $Script:ArenaGrid.Location = New-Object System.Drawing.Point(16, 48); $Script:ArenaGrid.Size = New-Object System.Drawing.Size(644, ($PH - 32 - 64))
    $Script:ArenaGrid.BackColor = $A.Card; $Script:ArenaGrid.AutoScroll = $true
    if ($Script:UiOK) { try { [GBTheme]::DoubleBuffer($Script:ArenaGrid) } catch {} }
    $gl.Controls.Add($Script:ArenaGrid)
    $Script:ArenaGameTiles = New-Object System.Collections.ArrayList; $Script:ArenaGridSig = $null
    $Script:ArenaGamesEmpty = New-GBArenaLabel $gl ("Ta bibliotheque est vide." + "`r`n" + "Ajoute ton jeu avec la tuile +, ou laisse la detection des jeux populaires.") 180 260 440 48 $fontUI $A.Muted "MiddleCenter"
    $Script:ArenaGamesEmpty.BringToFront()
    $ga = New-GBArenaSurface $pgGames ($P + 688) 16 ($IW - 688) 260 "AJOUTER UN JEU" "" $G.Play 0 $A.Green
    $cw = $IW - 688 - 32
    Set-GBPlace $btnBrowse $ga 16 48 $cw 34
    $btnBrowse.Text = "CHOISIR LE .EXE DU JEU"; $btnBrowse.ForeColor = $A.Green; $btnBrowse.Font = $Script:AF.Tile
    $null = New-GBArenaLabel $ga "ou un programme ouvert (lance d'abord ton jeu) :" 16 90 $cw 18 $fontSmall $A.Muted
    Set-GBPlace $cmbRunning $ga 16 112 ($cw - 96) 28
    Set-GBPlace $btnAddRunning $ga ($cw + 16 - 88) 110 88 30
    $btnAddRunning.Text = "AJOUTER"; $btnAddRunning.ForeColor = $A.Green
    $tip.SetToolTip($cmbRunning, "Programmes ouverts avec une fenetre : choisis ton jeu puis clique sur Ajouter")
    Set-GBPlace $chkKnown $ga 16 152 $cw 24
    $chkKnown.Text = "Detecter aussi ~40 jeux populaires"
    Set-GBPlace $btnRemove $ga 16 206 $cw 30
    $btnRemove.Text = "RETIRER LE JEU SELECTIONNE"; $btnRemove.ForeColor = $A.Red
    $gw2 = New-GBArenaSurface $pgGames ($P + 688) 288 ($IW - 688) ($PH - 16 - 288) "APPS AUTORISEES" "jamais fermees" $G.Sync 0 $A.Violet
    $wh = $PH - 16 - 288
    Set-GBPlace $txtWhite $gw2 16 48 $cw ($wh - 48 - 52)
    $txtWhite.BackColor = $cDeep; $txtWhite.BorderStyle = "None"
    $hw = [int](($cw - 8) / 2)
    Set-GBPlace $btnAddApp $gw2 16 ($wh - 44) $hw 30
    Set-GBPlace $btnRemoveApp $gw2 (16 + $hw + 8) ($wh - 44) ($cw - $hw - 8) 30
    foreach ($b in @($btnAddApp, $btnRemoveApp)) { $b.Font = $fontUI; $b.Padding = New-Object System.Windows.Forms.Padding(0) }
    $btnAddApp.Text = "+ Ajouter"; $btnRemoveApp.Text = "Retirer"
    foreach ($b in @($btnBrowse, $btnAddRunning, $btnRemove)) { $b.Add_Click({ Update-GBArenaGames }) }
    $chkKnown.Add_CheckedChanged({ Update-GBArenaGames })
    $gameMenu.add_Closed({ try { [void]$form.BeginInvoke([Action]{ Update-GBArenaGames }) } catch {} })

    # --- LOADOUT : presets du niveau gaming + tous les interrupteurs du boost en cartes, avec engrenages ---
    $pc = New-GBArenaSurface $pgOpt $P 16 $IW 168 "PRESETS" "un clic coche les optimisations du boost" $G.Bolt 0
    Set-GBPlace $btnReco $pc ($IW - 18 - 150) 12 150 28
    $btnReco.Text = "RECOMMANDES"; $btnReco.ForeColor = $A.Green
    $Script:ArenaPresets = New-Object System.Collections.ArrayList
    $pw = [int](($IW - 36 - 4 * 12) / 5)
    $pdesc = @("alim. max, priorite au jeu", "+ applis et services en pause", "+ anti-saccades, USB/PCIe", "+ souris brute, Nagle coupe", "+ fermeture FORCEE")
    for ($i = 0; $i -lt $Script:GameLevels.Count; $i++) {
        $lv = $Script:GameLevels[$i]
        $d = ""; if ($i -lt $pdesc.Count) { $d = $pdesc[$i] }
        $t = New-GBArenaTile $pc 2 ([string]$lv.L).ToUpper() $d "" $lv.C (18 + $i * ($pw + 12)) 46 $pw 84
        $t.Tag = $i
        $t.Add_Click({ Set-GBArenaPreset ([int]$this.Tag) })
        $tip.SetToolTip($t, ([string]$lv.L + " : " + [string]$lv.D))
