    }
    Set-GBPlace $lblGameDesc $pc 20 138 ($IW - 40 - 190) 20
    $lblGameDesc.BackColor = [System.Drawing.Color]::Transparent; $lblGameDesc.AutoEllipsis = $true
    Set-GBPlace $lblGameCur $pc ($IW - 20 - 180) 138 180 20
    $lblGameCur.BackColor = [System.Drawing.Color]::Transparent; $lblGameCur.TextAlign = "MiddleRight"
    $cy = 196; $ch = $PH - 16 - $cy; $c3 = [int](($IW - 24) / 3); $half = [int](($ch - 12) / 2)
    $Script:ArenaRowW = $c3
    $cSys = New-GBArenaSurface $pgOpt $P $cy $c3 $ch "SYSTEME" "pendant le boost" $G.Sys 0 $A.Accent
    $cCpu = New-GBArenaSurface $pgOpt ($P + $c3 + 12) $cy $c3 $half "PROCESSEUR" "" $G.Cpu 0 $A.Yellow
    $cGpu = New-GBArenaSurface $pgOpt ($P + $c3 + 12) ($cy + $half + 12) $c3 ($ch - $half - 12) "GRAPHIQUE" "" $G.Gpu 0 $A.Accent2
    $cNet = New-GBArenaSurface $pgOpt ($P + 2 * ($c3 + 12)) $cy ($IW - 2 * ($c3 + 12)) $half "RESEAU ET SOURIS" "" $G.Net 0 $cCyan
    $cMes = New-GBArenaSurface $pgOpt ($P + 2 * ($c3 + 12)) ($cy + $half + 12) ($IW - 2 * ($c3 + 12)) ($ch - $half - 12) "MESURE" "et demarrage" $G.Chart 0 $A.Violet
    $row = { param($chk, $card, [int]$r, $gear, [string]$text, [int]$indent = 0, [int]$extra = 0)
        $cwid = $card.Width; $w = $cwid - 32 - $indent; if ($gear) { $w -= 28 }; $w -= $extra
        Set-GBPlace $chk $card (16 + $indent) (46 + $r * 30) $w 24
        if ($text -and $chk.Enabled) { $chk.Text = $text }
        if ($gear) {
            Set-GBPlace $gear $card ($cwid - 16 - 24) (47 + $r * 30) 24 22
            $gear.BackColor = $Script:AC.Card; $gear.FlatAppearance.MouseOverBackColor = $Script:AC.Card; $gear.FlatAppearance.MouseDownBackColor = $Script:AC.Card
        }
    }
    & $row $chkClose    $cSys 0 $gearClose    "Fermer les autres applis"
    & $row $chkForce    $cSys 1 $null         "Fermeture forcee (risque de perte)" 20
    & $row $chkServices $cSys 2 $gearServices "Services inutiles en pause"
    & $row $chkRam      $cSys 3 $null         "Liberer la RAM des autres programmes"
    & $row $chkReopen   $cSys 4 $null         "Rouvrir les applis apres le jeu"
    & $row $chkStandby  $cSys 5 $gearStandby  "Anti-saccades (cache RAM)" 0 72
    Set-GBPlace $btnPurge $cSys ($c3 - 16 - 28 - 66) (46 + 5 * 30) 62 24
    & $row $chkRP       $cSys 6 $null         "Point de restauration avant le boost"
    $null = New-GBArenaLabel $cSys "Tout ce que le boost change est remis comme avant a la fin de la partie." 16 ($ch - 52) ($c3 - 32) 36 $fontSmall $A.Muted
    & $row $chkPrio     $cCpu 0 $gearPrio     "Priorite CPU haute pour le jeu"
    & $row $chkPower    $cCpu 1 $gearPower    "Alimentation au maximum"
    & $row $chkPlan     $cCpu 2 $null         "USB, PCIe et processeur au max"
    & $row $chkLowBg    $cCpu 3 $gearLowBg    "Launchers en priorite basse"
    & $row $chkGpu      $cGpu 0 $null         "Priorite GPU aux jeux"
    if ($chkGpuPref.Enabled) { & $row $chkGpuPref $cGpu 1 $null "Carte graphique puissante" }
    else { & $row $chkGpuPref $cGpu 1 $null ""; $chkGpuPref.Text = "Carte puissante : 1 seule carte" }
    & $row $chkDvr      $cGpu 2 $null         "Couper l'enregistrement Xbox"
    & $row $chkNetwork  $cNet 0 $null         "Nagle coupe (jeux TCP / MMO)"
    & $row $chkMouse    $cNet 1 $null         "Souris sans acceleration"
    if ($chkFps.Enabled) { & $row $chkFps $cMes 0 $null "Mesurer les FPS (PresentMon)" }
    else { & $row $chkFps $cMes 0 $null ""; $chkFps.Text = "FPS : PresentMon introuvable" }
    & $row $chkMeasure  $cMes 1 $null         "Comparer : mesurer SANS optimiser"
    & $row $chkStartup  $cMes 2 $null         "Lancer avec Windows (reduit)"
    foreach ($c in $Script:GameChecks.Values) { $c.Add_CheckedChanged({ if (-not $Script:GameLevelApplying) { Update-GBArenaLevel } }) }
    $lblGameDesc.Add_TextChanged({ Update-GBArenaLevel })
    $lblGameCur.Add_TextChanged({ Update-GBArenaLevel })

    # --- PERFS : temperatures et courbes, puissance (TURBO / GPU), charge en direct, applis sur la carte graphique ---
    $tc = New-GBArenaSurface $pgPerf $P 16 490 270 "TEMPERATURES" "toutes les 5 s" $G.Temp 0 $A.Accent2
    $Script:ArenaTemps = @{ Live = $false }
    if ((Get-Command New-GBRingCtl -ErrorAction Ignore) -and (Get-Command New-GBSparkCtl -ErrorAction Ignore)) {
        try {
            $T = $Script:ArenaTemps
            $T.CpuRing = New-GBRingCtl; Set-GBPlace $T.CpuRing $tc 14 46 104 104
            $T.CpuSpark = New-GBSparkCtl; Set-GBPlace $T.CpuSpark $tc 128 46 346 104
            $T.GpuRing = New-GBRingCtl; Set-GBPlace $T.GpuRing $tc 14 156 104 104
            $T.GpuSpark = New-GBSparkCtl; Set-GBPlace $T.GpuSpark $tc 128 156 346 104
            foreach ($c in @($T.CpuRing, $T.CpuSpark, $T.GpuRing, $T.GpuSpark)) {
                $c.BackColor = $A.Card
                # chiffres a la taille d'une carte ARENA (la police par defaut des capteurs est faite pour leur grande fenetre)
                try { if ($c.GetType().Name -eq 'GBRing') { $c.BigFont = $Script:AF.Unit } elseif ($c.GetType().Name -eq 'GBSpark') { $c.BigFont = $Script:AF.Preset } } catch {}
            }
            $T.Live = $true
        } catch { $Script:ArenaNote2 = "ARENA : capteurs indisponibles (" + $_.Exception.Message + ")" }
    }
    if (-not $Script:ArenaTemps.Live) { $null = New-GBArenaLabel $tc "Temperatures indisponibles sur ce PC." 16 120 458 24 $fontUI $A.Muted "MiddleCenter" }
    $sd = New-GBArenaTile $tc 3 "DETAILS" "" "" $A.Accent2 (490 - 18 - 96) 10 96 26
    $sd.Add_Click({ Invoke-GBArenaPanel 'Show-SensorsPanel' 'Capteurs' })
    $tip.SetToolTip($sd, "Toutes les temperatures (CPU, GPU, SSD), ventilateurs et frequences")
    $pwc = New-GBArenaSurface $pgPerf ($P + 502) 16 ($IW - 502) 270 "PUISSANCE" "engrenage = GHz et frequences" $G.Bolt 0 $A.Yellow
    $pcw = $IW - 502
    if ($Script:BtnTurbo) {
        Set-GBPlace $Script:BtnTurbo $pwc 16 50 ($pcw - 32 - 34) 56
        $Script:BtnTurbo.Font = $Script:AF.Preset
        $null = New-GBArenaLabel $pwc "OFF : turbo du processeur coupe hors jeu (PC plus frais). Il revient pendant le boost." 18 110 ($pcw - 36) 34 $fontSmall $A.Muted
    }
    if ($Script:BtnGpu) {
        Set-GBPlace $Script:BtnGpu $pwc 16 156 ($pcw - 32 - 34) 56
        $Script:BtnGpu.Font = $Script:AF.Preset
        $null = New-GBArenaLabel $pwc "ECO : carte graphique limitee hors jeu (plus froide, plus silencieuse). Sans limite en jeu." 18 216 ($pcw - 36) 34 $fontSmall $A.Muted
    }
    $gT = $gearTurbo; if (-not $gT) { $gT = $Script:GearTurbo }
    $gG = $gearGpu; if (-not $gG) { $gG = $Script:GearGpu }
    foreach ($gp in @(@($gT, 66), @($gG, 172))) {
        if ($gp[0]) { Set-GBPlace $gp[0] $pwc ($pcw - 16 - 26) $gp[1] 26 22; $gp[0].BackColor = $A.Card; $gp[0].FlatAppearance.MouseOverBackColor = $A.Card; $gp[0].FlatAppearance.MouseDownBackColor = $A.Card }
    }
    $lc2 = New-GBArenaSurface $pgPerf $P 298 $IW 124 "CHARGE EN DIRECT" "clic sur une jauge GPU : applis sur la carte" $G.Chart 0
    # Tiroir GPU non range dans ARENA : un clic sur une jauge GPU ouvre la fenetre des applis par carte (partie commune)
    $Script:GpuDrawerPage = 'perfs'
    if ($Script:Meters -and (Get-Command Set-GBMeterHost -ErrorAction Ignore)) {
        Set-GBMeterHost $lc2 18 46 ($IW - 36) 46 $A.Card
        Set-GBPlace $lblStats $lc2 18 96 ($IW - 36) 20
    } elseif ($Script:Meters) {
        $Script:MeterHost = New-Object System.Windows.Forms.Panel
        $Script:MeterHost.Location = New-Object System.Drawing.Point(18, 46); $Script:MeterHost.Size = New-Object System.Drawing.Size(($IW - 36), 46)
        $Script:MeterHost.BackColor = $A.Card; $Script:MeterHostW = $IW - 36
        $lc2.Controls.Add($Script:MeterHost)
        foreach ($m in $Script:Meters.Values) { $Script:MeterHost.Controls.Add($m); $m.Size = New-Object System.Drawing.Size(120, 46) }
        try { Set-GpuMeterLayout } catch {}
        Set-GBPlace $lblStats $lc2 18 96 ($IW - 36) 20
    } else { Set-GBPlace $lblStats $lc2 18 46 ($IW - 36) 66 }
    $lblStats.Font = $fontUI; $lblStats.AutoEllipsis = $true; $lblStats.BackColor = [System.Drawing.Color]::Transparent
    $ac = New-GBArenaSurface $pgPerf $P 434 $IW ($PH - 16 - 434) "CARTE GRAPHIQUE" "quelle appli tourne sur quelle carte" $G.Gpu 0 $A.Accent
    $aw = [int](($IW - 36 - 24) / 3); $ah = $PH - 16 - 434 - 60
    $t1 = New-GBArenaTile $ac 0 "APPLIS SUR LA CARTE" "Choisir la carte de chaque appli (comme Parametres Windows)." $G.Gpu $A.Accent 18 46 $aw $ah
    $t1.Add_Click({ try { Show-AppGpuSettings } catch { Log ("Applis GPU : " + $_.Exception.Message) } })
    $t2 = New-GBArenaTile $ac 0 "REGLAGES GPU" "Frequence en jeu et en ECO, puissance, reglage du fabricant." $G.Gpu $A.Accent2 (18 + $aw + 12) 46 $aw $ah
    $t2.Add_Click({ try { Show-GpuSettings; Update-GBArenaQuick } catch { Log ("Reglages GPU : " + $_.Exception.Message) } })
    $t3 = New-GBArenaTile $ac 0 "REGLAGES TURBO" "GHz du mode ON (et en jeu) et du mode OFF." $G.Bolt $A.Yellow (18 + 2 * ($aw + 12)) 46 ($IW - 36 - 2 * ($aw + 12)) $ah
    $t3.Add_Click({ try { Show-TurboSettings; Update-GBArenaQuick } catch { Log ("Reglages turbo : " + $_.Exception.Message) } })

    # --- ARSENAL : tous les outils en tuiles + journal ---
    $tw5 = [int](($IW - 4 * 12) / 5); $th5 = 72
    $tools = @(
        @($btnWinCfg, "CONFIG WINDOWS", "Pubs, applis, nettoyage.", $A.Violet),
        @($btnGames, "MES PARTIES", "Historique, FPS, overlay.", $cCyan),
        @($btnDrivers, "PILOTES", "Pilotes certifies.", $cCyan),
        @($btnDiag, "DIAGNOSTIC", "Ce qui freine ton PC.", $A.Green),
        @($btnPrioApps, "PRIORITES", "Priorite des logiciels.", $A.Yellow),
        @($btnUninst, "DESINSTALLER", "Programme + ses restes.", $A.Yellow),
        @('screens', "ECRANS", "Eteindre, rallumer.", $A.Violet),
        @('links', "LANCEMENTS LIES", "Deux .exe ensemble.", $cCyan),
        @('keys', "RACCOURCIS", "Touches des actions.", $A.Accent),
        @('kbd', "CLAVIER", "Touches, macros, AZERTY.", $cCyan),
        @('sound', "SON", "Par appli, egaliseur.", $A.Green),
        @('sensors', "CAPTEURS", "Temperatures, frequences.", $A.Accent2),
        @($btnExport, "RAPPORT CLAUDE", "Fichier pour des conseils.", $cCyan),
        @($btnSpecs, "COPIER LES SPECS", "Caracteristiques du PC.", $cCyan),
        @($btnLogs, "LOGS", "Journal et sessions.", $A.Accent2),
        @('edition', "MODELE", "NEXUS, ARENA ou PURE.", $A.Accent),
        @($btnRestoreAll, "TOUT RESTAURER", "PC comme avant. Clic droit.", $A.Red)
    )
    # Rangement par famille, une couleur par famille : jeu, materiel, Windows, GameBoost
    $famOrder = @('MES PARTIES', 'PRIORITES', 'LANCEMENTS LIES', 'ECRANS', 'CLAVIER', 'SON', 'CAPTEURS', 'PILOTES', 'CONFIG WINDOWS', 'DESINSTALLER', 'DIAGNOSTIC',
                  'RACCOURCIS', 'MODELE', 'RAPPORT CLAUDE', 'COPIER LES SPECS', 'LOGS', 'TOUT RESTAURER')
    $famColor = @($cCyan, $cCyan, $cCyan, $A.Green, $A.Green, $A.Green, $A.Green, $A.Green, $A.Violet, $A.Violet, $A.Violet, $A.Yellow, $A.Yellow, $A.Yellow, $A.Yellow, $A.Yellow, $A.Red)
    $sorted = New-Object System.Collections.ArrayList
    foreach ($name in $famOrder) { foreach ($t0 in $tools) { if ([string]$t0[1] -eq $name) { $t0[3] = $famColor[[array]::IndexOf($famOrder, $name)]; [void]$sorted.Add($t0) } } }
    foreach ($t0 in $tools) { if (-not $sorted.Contains($t0)) { $sorted.Insert([math]::Max(0, $sorted.Count - 1), $t0) } }
    $tools = @($sorted)
    $trows5 = [int][math]::Ceiling($tools.Count / 5.0); if ($trows5 -gt 3) { $th5 = 58 }   # 4 rangees : tuiles un peu moins hautes
    for ($i = 0; $i -lt $tools.Count; $i++) {
        $d = $tools[$i]; $x = $P + ($i % 5) * ($tw5 + 12); $y = 16 + [math]::Floor($i / 5) * ($th5 + 12)
        $b = $d[0]
        if ($b -is [string]) { $key = $b; $b = New-GBButtonCtl; $b.Tag = $key }
        Set-GBPlace $b $pgTools $x $y $tw5 $th5
        $b.Font = $Script:AF.Tile; $b.BackColor = $A.Card
        if ($b.GetType().Name -eq 'GBButton') { $b.DescFont = $fontSmall }
        Set-GBArenaTile $b $d[1] $d[2] $d[3]
        if ($Script:UiOK) { try { $b.Cut = 10 } catch {} } else { $b.TextAlign = "MiddleLeft"; $b.Padding = New-Object System.Windows.Forms.Padding(10, 0, 0, 0) }
        if (-not $tip.GetToolTip($b)) { $tip.SetToolTip($b, $d[2]) }
        switch ([string]$b.Tag) {
            'screens' { $b.Add_Click({ Invoke-GBArenaPanel 'Show-MonitorsPanel' 'Ecrans'; Update-GBArenaQuick }) }
            'links'   { $b.Add_Click({ Invoke-GBArenaPanel 'Show-LinkedAppsPanel' 'Lancements lies'; Update-GBArenaQuick }) }
            'keys'    { $b.Add_Click({ Invoke-GBArenaPanel 'Show-HotkeysPanel' 'Raccourcis clavier'; Update-GBArenaState }) }
            'sensors' { $b.Add_Click({ Invoke-GBArenaPanel 'Show-SensorsPanel' 'Capteurs' }) }
            'kbd'     { $b.Add_Click({ Invoke-GBArenaPanel 'Show-GBKeyboardPanel' 'Clavier' }) }
            'sound'   { $b.Add_Click({ Invoke-GBArenaPanel 'Show-GBSoundPanel' 'Son' }) }
            'edition' { $b.Add_Click({
                if (-not (Get-Command Show-GBEditionPicker -ErrorAction Ignore)) { return }
                $e2 = $null; try { $e2 = Show-GBEditionPicker -Owner $form } catch {}
                if ($e2 -and $e2 -ne $Script:Edition) { Switch-GBEdition $e2 } }) }
        }
    }
    $jc = New-GBArenaSurface $pgTools $P (16 + $trows5 * ($th5 + 12) + 4) $IW ($PH - 16 - (16 + $trows5 * ($th5 + 12) + 4)) "JOURNAL" "ce que fait GameBoost, en direct" $G.Chart 0 $A.Muted
    Set-GBPlace $txtLog $jc 14 44 ($IW - 28) ($jc.Height - 56)
    $txtLog.Anchor = "Top, Bottom, Left, Right"; $txtLog.BorderStyle = "None"; $txtLog.BackColor = $cDeep

    # --- Liens avec le moteur : l'affichage suit l'etat (aucune action dupliquee) ---
    $btnBoost.Add_TextChanged({ Update-GBArenaState })
    $btnDrivers.Add_TextChanged({ Update-GBArenaDriver })
    $chkAuto.Add_CheckedChanged({ Update-GBArenaQuick })
    if ($Script:BtnTurbo) { $Script:BtnTurbo.Add_TextChanged({ Update-GBArenaQuick }) }
    if ($Script:BtnGpu) { $Script:BtnGpu.Add_TextChanged({ Update-GBArenaQuick }) }
    if (Get-Command Add-GBSampleHook -ErrorAction Ignore) { Add-GBSampleHook { param($s) $Script:ArenaLastSample = $s; Update-GBArenaHud $s } }
    $form.Add_Load({ $Script:ArenaLoaded = $true })
    $tip.SetToolTip($btnBoost, "Lance ou arrete le boost (aussi depuis l'icone pres de l'horloge)")

    $body.ResumeLayout()
    if ($Script:UiOK -and -not $Script:ArenaFxOK) { $Script:ArenaNote = "ARENA : composants dessines indisponibles, affichage simplifie" }
    Update-GBArenaDriver
    Update-GBArenaState
    Update-GBArenaQuick
    Update-GBArenaLevel
    if (Get-Command Complete-GBLayout -ErrorAction Ignore) { Complete-GBLayout }
    Show-GBPage 'home'
    # Messages de la mise en page : ecrits apres l'affichage
    if ($Script:ArenaNote -or $Script:ArenaNote2) {
        if (Get-Command Add-GBStartHook -ErrorAction Ignore) { Add-GBStartHook { foreach ($nt in @($Script:ArenaNote, $Script:ArenaNote2)) { if ($nt) { Log $nt } } } }
    }
}

# --- Modele PURE : une seule page claire (etat, un bouton, cinq interrupteurs, niveau, mes jeux), le reste dans les menus ---
# Composants dessines du modele PURE (bloc C# separe, compile seulement si le modele PURE est choisi).
# Animations propres (un seul minuteur) : ce bloc ne depend pas de GBUi, qui peut etre compile en memoire sans chemin de fichier.
$pureSrc = @"
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;

// Mouvement PURE : doux et court, interruptible (repart toujours de la valeur affichee)
public static class GBPureMotion {
    public static bool Reduced = false;
    static readonly Stopwatch _clock = Stopwatch.StartNew();
    static readonly List<GBPureTween> _active = new List<GBPureTween>();
    static Timer _timer;
    public static double Now { get { return _clock.Elapsed.TotalMilliseconds; } }
    internal static void Start(GBPureTween t) {
        if (!_active.Contains(t)) _active.Add(t);
        if (_timer == null) { _timer = new Timer(); _timer.Interval = 15; _timer.Tick += Tick; }
        if (!_timer.Enabled) _timer.Start();
    }
    static void Tick(object sender, EventArgs e) {
        double now = Now;
        for (int i = _active.Count - 1; i >= 0; i--) {
            if (i >= _active.Count) continue;
            if (_active[i].Step(now)) _active.RemoveAt(i);
        }
        if (_active.Count == 0) _timer.Stop();
    }
    static double Bez(double t, double a, double b) { double u = 1 - t; return 3 * u * u * t * a + 3 * u * t * t * b + t * t * t; }
    // Courbe de sortie : cubic-bezier(0.23, 1, 0.32, 1)
    public static float EaseOut(double x) {
        if (x <= 0) return 0f; if (x >= 1) return 1f;
        double lo = 0, hi = 1, t = x;
        for (int i = 0; i < 24; i++) {
            double cx = Bez(t, 0.23, 0.32);
            if (Math.Abs(cx - x) < 0.0005) break;
            if (cx < x) lo = t; else hi = t;
            t = (lo + hi) / 2;
        }
        return (float)Bez(t, 1, 1);
    }
    public static Color Mix(Color a, Color b, float t) {
        t = Math.Max(0f, Math.Min(1f, t));
        return Color.FromArgb(255, (int)(a.R + (b.R - a.R) * t), (int)(a.G + (b.G - a.G) * t), (int)(a.B + (b.B - a.B) * t));
    }
    public static GraphicsPath Round(RectangleF r, float rad) {
        GraphicsPath p = new GraphicsPath();
        float d = Math.Max(1f, Math.Min(rad * 2, Math.Min(r.Width, r.Height)));
        p.AddArc(r.X, r.Y, d, d, 180, 90);
        p.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        p.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
        p.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
        p.CloseFigure();
        return p;
    }
    public static Color BackOf(Control c, Color fallback) { return c.Parent != null ? c.Parent.BackColor : fallback; }
    public static float Scale(Graphics g) { return Math.Max(1f, g.DpiX / 96f); }
}

public class GBPureTween {
    public float Value;
    float _from, _to;
    double _start, _dur;
    public Control Owner;
    public bool Running;
    public bool Motion = true;   // false = fondu (garde meme si les animations Windows sont coupees)
    public GBPureTween(Control owner, float v) { Owner = owner; Value = v; _to = v; }
    public float Target { get { return _to; } }
    public void From(float from, float target, double ms) { Value = from; Running = false; _to = from; To(target, ms); }
    public void To(float target, double ms) {
        if (Running && Math.Abs(target - _to) < 0.0001f) return;
        _to = target;
        bool can = Owner != null && !Owner.IsDisposed && Owner.IsHandleCreated && Owner.Visible;
        if (can) { Form f = Owner.FindForm(); if (f == null || !f.Visible || f.WindowState == FormWindowState.Minimized) can = false; }
        if ((Motion && GBPureMotion.Reduced) || ms <= 0 || !can) {
            Value = target; Running = false;
            if (Owner != null && !Owner.IsDisposed) Owner.Invalidate();
            return;
        }
        _from = Value; _start = GBPureMotion.Now; _dur = ms; Running = true;
        GBPureMotion.Start(this);
    }
    internal bool Step(double now) {
        if (Owner == null || Owner.IsDisposed) { Running = false; return true; }
        double p = (now - _start) / _dur;
        bool done = p >= 1;
        Value = done ? _to : _from + GBPureMotion.EaseOut(p) * (_to - _from);
        if (done) Running = false;
        Owner.Invalidate();
        return done;
    }
}

// Bouton pilule : couleur pleine, fondu d'environ 200 ms quand l'etat change, leger assombrissement a l'appui
public class GBPurePill : Button {
    GBPureTween _press, _fade;
    Color _fill0, _fill1, _fore0, _fore1;
    string _text0 = "";
    public GBPurePill() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _press = new GBPureTween(this, 0); _press.Motion = false;
        _fade = new GBPureTween(this, 1); _fade.Motion = false;
        _fill0 = _fill1 = Color.FromArgb(0, 113, 227); _fore0 = _fore1 = Color.White;
        FlatStyle = FlatStyle.Flat; FlatAppearance.BorderSize = 0;
        Cursor = Cursors.Hand;
    }
    public Color Fill { get { return _fill1; } }
    public void SetState(string text, Color fill, Color fore) {
        if (text == Text && fill == _fill1 && fore == _fore1) return;
        float p = _fade.Value;
        Color f = GBPureMotion.Mix(_fill0, _fill1, p), c = GBPureMotion.Mix(_fore0, _fore1, p);
        _text0 = (_text0 != Text && p < 0.5f) ? _text0 : Text;
        _fill0 = f; _fore0 = c; _fill1 = fill; _fore1 = fore;
        Text = text;
        _fade.From(0f, 1f, 200);
    }
    protected override void OnMouseDown(MouseEventArgs e) { if (e.Button == MouseButtons.Left) _press.To(1f, 70); base.OnMouseDown(e); }
    protected override void OnMouseUp(MouseEventArgs e) { _press.To(0f, 180); base.OnMouseUp(e); }
    protected override void OnMouseLeave(EventArgs e) { _press.To(0f, 180); base.OnMouseLeave(e); }
    protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color back = GBPureMotion.BackOf(this, BackColor);
        g.Clear(back);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = GBPureMotion.Scale(g), p = _fade.Value;
        Color fill = GBPureMotion.Mix(_fill0, _fill1, p);
        fill = GBPureMotion.Mix(fill, Color.Black, 0.12f * _press.Value);
        if (!Enabled) fill = GBPureMotion.Mix(fill, back, 0.5f);
        RectangleF r = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f);
        using (GraphicsPath gp = GBPureMotion.Round(r, r.Height / 2f)) using (SolidBrush b = new SolidBrush(fill)) g.FillPath(b, gp);
        string t = Text; Color tc;
        if (_text0 != Text && p < 0.5f) { t = _text0; tc = GBPureMotion.Mix(_fore0, fill, p * 2f); }
        else if (_text0 != Text) { tc = GBPureMotion.Mix(fill, _fore1, (p - 0.5f) * 2f); }
        else tc = GBPureMotion.Mix(_fore0, _fore1, p);
        TextRenderer.DrawText(g, t, Font, ClientRectangle, tc, fill,
            TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
        if (Focused && ShowFocusCues) {
            RectangleF fr = new RectangleF(2.5f * s, 2.5f * s, Width - 5f * s - 1, Height - 5f * s - 1);
            using (GraphicsPath fp = GBPureMotion.Round(fr, fr.Height / 2f)) using (Pen pen = new Pen(Color.FromArgb(150, Color.White), 1.5f * s)) g.DrawPath(pen, fp);
        }
    }
}

// Choix segmente (Doux / Equilibre / Max) : le curseur blanc glisse vers le choix ; clavier = instantane
public class GBPureSegment : Control {
    string[] _items = new string[0];
    int _sel = -1;
    GBPureTween _x, _show;
    public Color Track = Color.FromArgb(232, 232, 237);
    public Color Knob = Color.White;
    public Color TextColor = Color.FromArgb(29, 29, 31);
    public Color LineColor = Color.FromArgb(210, 210, 215);
    public Color Accent = Color.FromArgb(0, 113, 227);
    public Font SelFont;
    public event EventHandler SelectedIndexChanged;   // seulement quand l'utilisateur choisit
    public GBPureSegment() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        _x = new GBPureTween(this, 0);
        _show = new GBPureTween(this, 0); _show.Motion = false;
        TabStop = true; Cursor = Cursors.Hand;
    }
    public string[] Items { get { return _items; } set { _items = value ?? new string[0]; Invalidate(); } }
    public int SelectedIndex { get { return _sel; } set { Select(value, false, false); } }
    void Select(int i, bool animate, bool user) {
        if (i < -1 || i >= _items.Length) i = -1;
        if (i == _sel) return;
        int old = _sel; _sel = i;
        if (i >= 0) {
            if (old < 0) { _x.From(i, i, 0); _show.To(1f, animate ? 160 : 0); }
            else _x.To(i, animate ? 220 : 0);
        } else _show.To(0f, animate ? 160 : 0);
        Invalidate();
        if (user && SelectedIndexChanged != null) SelectedIndexChanged(this, EventArgs.Empty);
    }
    protected override bool IsInputKey(Keys k) { return k == Keys.Left || k == Keys.Right || base.IsInputKey(k); }
    protected override void OnKeyDown(KeyEventArgs e) {
        base.OnKeyDown(e);
        if (_items.Length == 0) return;
        if (e.KeyCode == Keys.Left) { Select(Math.Max(0, _sel - 1), false, true); e.Handled = true; }
        else if (e.KeyCode == Keys.Right) { Select(Math.Min(_items.Length - 1, _sel + 1), false, true); e.Handled = true; }
    }
    protected override void OnMouseDown(MouseEventArgs e) {
        base.OnMouseDown(e);
        if (e.Button != MouseButtons.Left || _items.Length == 0) return;
        Focus();
        int i = (int)(e.X / ((float)Width / _items.Length));
        Select(Math.Max(0, Math.Min(_items.Length - 1, i)), true, true);
    }
    protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
    protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color back = GBPureMotion.BackOf(this, BackColor);
        g.Clear(back);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = GBPureMotion.Scale(g);
        RectangleF tr = new RectangleF(0.5f, 0.5f, Width - 1.5f, Height - 1.5f);
        using (GraphicsPath p = GBPureMotion.Round(tr, 8f * s)) using (SolidBrush b = new SolidBrush(Track)) g.FillPath(b, p);
        int n = _items.Length; if (n == 0) return;
        float sw = (Width - 4f * s) / n;
        float x = _x.Value, a = _show.Value;
        // Separateurs fins, effaces pres du curseur
        for (int i = 1; i < n; i++) {
            float d = Math.Abs(x - (i - 0.5f));
            float vis = a > 0.01f ? Math.Max(0f, Math.Min(1f, d - 0.5f)) : 1f;
            if (vis <= 0.01f) continue;
            float lx = 2f * s + sw * i;
            using (Pen lp = new Pen(Color.FromArgb((int)(255 * vis), LineColor), 1f)) g.DrawLine(lp, lx, Height * 0.28f, lx, Height * 0.72f);
        }
        if (a > 0.01f) {
            RectangleF kr = new RectangleF(2f * s + sw * x, 2f * s, sw, Height - 4f * s - 1);
            RectangleF sr = kr; sr.Offset(0, 1f * s);
            using (GraphicsPath sp = GBPureMotion.Round(sr, 6.5f * s)) using (SolidBrush sb = new SolidBrush(Color.FromArgb((int)(26 * a), 0, 0, 0))) g.FillPath(sb, sp);
            using (GraphicsPath kp = GBPureMotion.Round(kr, 6.5f * s)) using (SolidBrush kb = new SolidBrush(Color.FromArgb((int)(255 * a), Knob))) g.FillPath(kb, kp);
        }
        for (int i = 0; i < n; i++) {
            Rectangle r = new Rectangle((int)(2f * s + sw * i), 0, (int)sw, Height);
            bool on = i == _sel;
            Font f = (on && SelFont != null) ? SelFont : Font;
            TextRenderer.DrawText(g, _items[i], f, r, Enabled ? TextColor : LineColor,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
        }
        if (Focused && ShowFocusCues) using (GraphicsPath fp = GBPureMotion.Round(tr, 8f * s)) using (Pen pen = new Pen(Color.FromArgb(160, Accent), 1.5f * s)) g.DrawPath(pen, fp);
    }
}

// Groupe de lignes (comme les Reglages d'iOS) : carte blanche aux coins arrondis
public class GBPureGroup : Panel {
    public Color Card = Color.White;
    public float Radius = 12f;
    public GBPureGroup() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        g.Clear(GBPureMotion.BackOf(this, Color.White));
        g.SmoothingMode = SmoothingMode.AntiAlias;
        float s = GBPureMotion.Scale(g);
        using (GraphicsPath p = GBPureMotion.Round(new RectangleF(0, 0, Width - 0.5f, Height - 0.5f), Radius * s)) using (SolidBrush b = new SolidBrush(Card)) g.FillPath(b, p);
    }
}

// Ligne : titre, sous-titre gris, valeur et chevron a droite ; le controle de droite (interrupteur...) est un enfant
public class GBPureRow : Panel {
    GBPureTween _hl;
    string _title = "", _sub = "", _value = "";
    public Font TitleFont, SubFont;
    public Color TitleColor = Color.FromArgb(29, 29, 31);
    public Color SubColor = Color.FromArgb(110, 110, 115);
    public Color LineColor = Color.FromArgb(210, 210, 215);
    public Color HighColor = Color.FromArgb(229, 229, 234);
    public bool TopLine = false;     // separateur fin au-dessus (sauf la premiere ligne)
    public bool Chevron = false;     // ligne qui ouvre une autre vue
    public bool Clickable = false;
    public int RightReserve = 0;     // largeur gardee a droite pour le controle (pixels a 100 %)
    public GBPureRow() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _hl = new GBPureTween(this, 0); _hl.Motion = false;
    }
    public string Title { get { return _title; } set { _title = value ?? ""; Invalidate(); } }
    public string Subtitle { get { return _sub; } set { if ((value ?? "") == _sub) return; _sub = value ?? ""; Invalidate(); } }
    public string Value { get { return _value; } set { if ((value ?? "") == _value) return; _value = value ?? ""; Invalidate(); } }
    protected override void OnMouseDown(MouseEventArgs e) { if (Clickable && e.Button == MouseButtons.Left) _hl.To(1f, 0); base.OnMouseDown(e); }
    protected override void OnMouseUp(MouseEventArgs e) { _hl.To(0f, 240); base.OnMouseUp(e); }
    protected override void OnMouseLeave(EventArgs e) { _hl.To(0f, 240); base.OnMouseLeave(e); }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = GBPureMotion.Mix(BackColor, HighColor, _hl.Value);
        g.Clear(bg);
        float s = GBPureMotion.Scale(g);
        int pad = (int)(16 * s);
        if (TopLine) using (Pen lp = new Pen(LineColor, 1f)) g.DrawLine(lp, pad, 0, Width, 0);
        int right = Width - pad - (int)(RightReserve * s);
        TextFormatFlags fl = TextFormatFlags.Left | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis;
        if (Chevron) {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            float cx = Width - pad - 4 * s, cy = Height / 2f;
            using (Pen cp = new Pen(GBPureMotion.Mix(SubColor, bg, 0.35f), 1.8f * s)) {
                cp.StartCap = LineCap.Round; cp.EndCap = LineCap.Round;
                g.DrawLines(cp, new PointF[] { new PointF(cx - 4 * s, cy - 6 * s), new PointF(cx + 1.5f * s, cy), new PointF(cx - 4 * s, cy + 6 * s) });
            }
            right = (int)(cx - 14 * s);
        }
        if (_value.Length > 0) {
            Size vs = TextRenderer.MeasureText(g, _value, TitleFont ?? Font, new Size(9999, Height), fl);
            Rectangle vr = new Rectangle(right - vs.Width, 0, vs.Width, Height);
            TextRenderer.DrawText(g, _value, TitleFont ?? Font, vr, SubColor, bg, fl | TextFormatFlags.VerticalCenter);
            right = vr.Left - (int)(10 * s);
        }
        Font tf = TitleFont ?? Font, sf = SubFont ?? Font;
        int th = TextRenderer.MeasureText(g, "Ag", tf, new Size(9999, 9999), fl).Height;
        int w = Math.Max(10, right - pad);
        if (_sub.Length == 0) {
            TextRenderer.DrawText(g, _title, tf, new Rectangle(pad, 0, w, Height), TitleColor, bg, fl | TextFormatFlags.VerticalCenter);
        } else {
            int sh = TextRenderer.MeasureText(g, "Ag", sf, new Size(9999, 9999), fl).Height;
            int top = (Height - th - sh) / 2;
            TextRenderer.DrawText(g, _title, tf, new Rectangle(pad, top, w, th), TitleColor, bg, fl);
            TextRenderer.DrawText(g, _sub, sf, new Rectangle(pad, top + th, w, sh), SubColor, bg, fl);
        }
    }
}

// Texte d'etat : quand il change, l'ancien s'efface puis le nouveau apparait (fondu d'environ 220 ms)
public class GBPureText : Control {
    GBPureTween _fade;
    string _old = "";
    Color _oldColor, _color;
    public bool Center = true;
    public GBPureText() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _fade = new GBPureTween(this, 1); _fade.Motion = false;
        _color = _oldColor = Color.Black;
    }
    public void SetText(string text, Color color) {
        text = text ?? "";
        if (text == Text && color == _color) return;
        if (text == Text) { _oldColor = color; _color = color; Invalidate(); return; }
        _old = _fade.Value < 0.5f ? _old : Text; _oldColor = _color;
        _color = color; Text = text;
        _fade.From(0f, 1f, 220);
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = GBPureMotion.BackOf(this, BackColor);
        g.Clear(bg);
        float p = _fade.Value;
        string t = Text; Color c = _color;
        if (p < 0.5f && _old != Text) { t = _old; c = GBPureMotion.Mix(_oldColor, bg, p * 2f); }
        else if (p < 1f) c = GBPureMotion.Mix(bg, _color, (p - 0.5f) * 2f);
        TextFormatFlags fl = TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis | (Center ? TextFormatFlags.HorizontalCenter : TextFormatFlags.Left);
        TextRenderer.DrawText(g, t, Font, ClientRectangle, c, bg, fl);
    }
}

// Pastille d'etat : disque teinte + point plein, la couleur passe en fondu
public class GBPureDot : Control {
    GBPureTween _fade;
    Color _c0 = Color.Gray, _c1 = Color.Gray;
    public GBPureDot() {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        _fade = new GBPureTween(this, 1); _fade.Motion = false;
    }
    public Color DotColor { get { return _c1; } }
    public void SetColor(Color c) {
        if (c == _c1) return;
        _c0 = GBPureMotion.Mix(_c0, _c1, _fade.Value); _c1 = c;
        _fade.From(0f, 1f, 220);
    }
    protected override void OnPaint(PaintEventArgs e) {
        Graphics g = e.Graphics;
        Color bg = GBPureMotion.BackOf(this, BackColor);
        g.Clear(bg);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        Color c = GBPureMotion.Mix(_c0, _c1, _fade.Value);
        float d = Math.Min(Width, Height) - 1f;
        float x = (Width - d) / 2f, y = (Height - d) / 2f;
        using (SolidBrush halo = new SolidBrush(GBPureMotion.Mix(bg, c, 0.16f))) g.FillEllipse(halo, x, y, d, d);
        float k = d * 0.34f;
        using (SolidBrush b = new SolidBrush(c)) g.FillEllipse(b, x + (d - k) / 2f, y + (d - k) / 2f, k, k);
    }
}
"@
$Script:PureOK = $false

# Compile les composants PURE (une fois). Faux = repli sur des controles Windows classiques.
function Initialize-GBPureUi {
    if ($Script:PureOK) { return $true }
    if (-not $Script:UiOK) { return $false }
    try {
        $refs = @('System.Windows.Forms', 'System.Drawing')
        if ($uiRefs) { $refs = $uiRefs }
        $Script:PureOK = [bool](Add-GBCompiled 'GBPure' $pureSrc $refs 'GBPureRow')
        if ($Script:PureOK) { try { [GBPureMotion]::Reduced = [bool][GBMotion]::Reduced } catch {} }
        else { Log ("Composants PURE indisponibles (" + $Script:GBCompileError + ") : interface Windows classique") }
    } catch { $Script:PureOK = $false }
    return $Script:PureOK
}

# Couleurs et polices PURE (palette de socle si elle existe, sinon les couleurs du theme actuel)
function Get-GBPureStyle {
    $Pal = @{ Bg = $cBg; Card = $cPanel; Text = $cText; Muted = $cMuted; Line = $cLine; Accent = $cCyan; OnAccent = [System.Drawing.Color]::White
            Green = $cGreen; Red = $cRed; Orange = $cYellow; Track = $cRail; Sel = $cSel; Deep = $cDeep }
    if ($cCard) { $Pal.Card = $cCard }
    if ($cAccent) { $Pal.Accent = $cAccent }
    if ($cOnAccent) { $Pal.OnAccent = $cOnAccent }
    $ui = "Segoe UI Variable Text"; $title = "Segoe UI Variable Display Semib"
    if ($Script:Theme -and $Script:Theme.FontUI) { $ui = [string]$Script:Theme.FontUI }
    $Fnt = @{
        Title = Get-GBFont @($title, "Segoe UI Semibold") 20
        Big   = Get-GBFont @($title, "Segoe UI Semibold") 17
        Row   = Get-GBFont @($ui, "Segoe UI") 10.5
        Sub   = Get-GBFont @($ui, "Segoe UI") 9
        Small = Get-GBFont @($ui, "Segoe UI") 8.75
        Pill  = Get-GBFont @("Segoe UI Variable Text Semibold", "Segoe UI Semibold") 11
        Seg   = Get-GBFont @($ui, "Segoe UI") 9.5
        SegOn = Get-GBFont @("Segoe UI Variable Text Semibold", "Segoe UI Semibold") 9.5
    }
    return @{ C = $Pal; F = $Fnt }
}

function New-GBPureGroup($parent, $x, $y, $w, $h) {
    $Pal = $Script:PureC
    if ($Script:PureOK) { $g = New-Object GBPureGroup; $g.Card = $Pal.Card; $g.Radius = 12 }
    else { $g = New-Object System.Windows.Forms.Panel; $g.BorderStyle = "FixedSingle" }
    $g.BackColor = $Pal.Card
    Set-GBPurePlace $g $parent $x $y $w $h
    return $g
}
# Ligne : titre + sous-titre (+ chevron). Repli : panneau et deux libelles.
function New-GBPureRow($group, $title, $sub, $reserve, [switch]$Chevron) {
    $Pal = $Script:PureC; $Fnt = $Script:PureF
    if ($Script:PureOK) {
        $r = New-Object GBPureRow
        $r.TitleFont = $Fnt.Row; $r.SubFont = $Fnt.Sub; $r.TitleColor = $Pal.Text; $r.SubColor = $Pal.Muted; $r.LineColor = $Pal.Line
        $r.HighColor = [GBPureMotion]::Mix($Pal.Card, $Pal.Muted, 0.14)
        $r.RightReserve = [int]$reserve; $r.Chevron = [bool]$Chevron; $r.Clickable = [bool]$Chevron
        $r.Title = $title; $r.Subtitle = $sub
    } else {
        $r = New-Object System.Windows.Forms.Panel
        $lt = New-Object System.Windows.Forms.Label; $lt.Text = $title; $lt.Font = $Fnt.Row; $lt.ForeColor = $Pal.Text; $lt.AutoEllipsis = $true
        $lt.Location = New-Object System.Drawing.Point(16, 6); $lt.Size = New-Object System.Drawing.Size([math]::Max(40, 500 - $reserve - 40), 20); $r.Controls.Add($lt)
        $ls = New-Object System.Windows.Forms.Label; $ls.Text = $sub; $ls.Font = $Fnt.Sub; $ls.ForeColor = $Pal.Muted; $ls.AutoEllipsis = $true
        $ls.Location = New-Object System.Drawing.Point(16, 26); $ls.Size = New-Object System.Drawing.Size([math]::Max(40, 500 - $reserve - 40), 18); $r.Controls.Add($ls)
        $r.Tag = @{ T = $lt; S = $ls }
        if ($Chevron) { foreach ($l in @($r, $lt, $ls)) { $l.Cursor = [System.Windows.Forms.Cursors]::Hand } }
    }
    $r.BackColor = $Pal.Card
    $group.Controls.Add($r)
    return $r
}
function Set-GBPureRowText($r, $title, $sub) {
    if ($null -eq $r) { return }
    if ($Script:PureOK -and $r -is [GBPureRow]) { if ($null -ne $title) { $r.Title = $title }; if ($null -ne $sub) { $r.Subtitle = $sub }; return }
    if ($r.Tag -is [hashtable]) { if ($null -ne $title) { $r.Tag.T.Text = $title }; if ($null -ne $sub) { $r.Tag.S.Text = $sub } }
}
function New-GBPureText($parent, $font, $color, $x, $y, $w, $h, [switch]$Left) {
    if ($Script:PureOK) { $t = New-Object GBPureText; $t.Center = (-not $Left); $t.SetText("", $color) }
    else { $t = New-Object System.Windows.Forms.Label; $t.AutoEllipsis = $true; if ($Left) { $t.TextAlign = "MiddleLeft" } else { $t.TextAlign = "MiddleCenter" } }
    $t.Font = $font; $t.ForeColor = $color; $t.BackColor = $Script:PureC.Bg
    Set-GBPurePlace $t $parent $x $y $w $h
    return $t
}
function Set-GBPureText($t, [string]$text, $color) {
    if ($null -eq $t) { return }
    if ($Script:PureOK -and $t -is [GBPureText]) { $t.SetText($text, $color) }
    else { $t.Text = $text; $t.ForeColor = $color }
}
# Place un controle (Set-GBPlace commun s'il existe)
function Set-GBPurePlace($c, $parent, $x, $y, $w, $h) {
    if (Get-Command Set-GBPlace -ErrorAction SilentlyContinue) { Set-GBPlace $c $parent $x $y $w $h; return }
    if ($c.Parent -ne $parent) { if ($c.Parent) { $c.Parent.Controls.Remove($c) }; $parent.Controls.Add($c) }
    $c.Location = New-Object System.Drawing.Point([int]$x, [int]$y)
    if ($w -gt 0) { $c.Size = New-Object System.Drawing.Size([int]$w, [int]$h) }
}
# Interrupteur range a droite d'une ligne (sans texte)
function Set-GBPureToggle($tg, $row) {
    $tg.Text = ""; $tg.BackColor = $Script:PureC.Card
    if ($tg -is [System.Windows.Forms.CheckBox] -and -not $Script:UiOK) { $tg.CheckAlign = "MiddleRight" }
    if ($Script:UiOK -and $tg -is [GBToggle]) { $tg.OnColor = $Script:PureC.Accent; $tg.Invalidate() }
    Set-GBPurePlace $tg $row ($Script:PureRowW - 14 - $Script:PureTgW) 9 $Script:PureTgW 32
    $tg.Anchor = "Top, Right"
}

# --- Etat en haut : titre, phrase, pastille et bouton (appele quand le moteur change le bouton BOOST ou le texte d'etat)
function Update-GBPureState {
    if (-not $Script:PureTitle) { return }
    try {
        $Pal = $Script:PureC
        $games = (@($Script:Config.Games).Count -gt 0 -or $Script:Config.KnownGames)
        if ($Script:Boosted) {
            $g = [string]$Script:SessionGame
            if ($Script:MeasureOnlySession) { $t = "Mesure en cours"; $sub = "Mode comparaison : rien n'est optimise."; $dot = $Pal.Orange; $pt = "Arreter la mesure" }
            else {
                if ($g -and $g -notlike '(*') { $t = "En jeu - " + $g; $sub = "Boost actif. Tout revient comme avant a la fin." }
                else { $t = "Boost actif"; $sub = "Lance ton jeu, GameBoost s'occupe du reste." }
                $dot = $Pal.Green; $pt = "Arreter le boost"
            }
            $pf = $Pal.Track; $pc = $Pal.Red
        } else {
            $t = "Pret"; $dot = $Pal.Accent; $pt = "Lancer le boost"; $pf = $Pal.Accent; $pc = $Pal.OnAccent
            if ($Script:Config.MeasureOnly) { $pt = "Lancer la mesure" }
            if ($Script:Config.AutoMode -and $Script:ManualStop) { $t = "En pause"; $sub = "Pas de relance tant que le jeu reste ouvert."; $dot = $Pal.Muted }
            elseif ($Script:Config.AutoMode -and $games) { $sub = "Le boost se lancera tout seul avec ton jeu." }
            elseif ($Script:Config.AutoMode) { $sub = "Ajoute ton jeu pour le boost automatique."; $dot = $Pal.Muted }
            else { $sub = "Lance le boost quand tu joues."; $dot = $Pal.Muted }
        }
        Set-GBPureText $Script:PureTitle $t $Pal.Text
        Set-GBPureText $Script:PureSub $sub $Pal.Muted
        if ($Script:PureOK) { $Script:PurePill.SetState($pt, $pf, $pc); $Script:PureDot.SetColor($dot) }
        else { $Script:PurePill.Text = $pt; $Script:PurePill.BackColor = $pf; $Script:PurePill.ForeColor = $pc; $Script:PureDot.ForeColor = $dot }
    } catch {}
}

# --- Ligne discrete : temperatures (capteurs) ou charge, et FPS en jeu
function Update-GBPureMetrics($s) {
    if (-not $Script:PureMetrics) { return }
    try {
        $deg = [string][char]0xB0; $sep = "   " + [char]0xB7 + "   "
        $sn = $null
        if (Get-Command Get-GBSensors -ErrorAction SilentlyContinue) { try { $sn = Get-GBSensors } catch {} }
        $parts = New-Object System.Collections.ArrayList
        if ($sn -and $null -ne $sn.CpuTemp) { [void]$parts.Add("Processeur " + [int][math]::Round([double]$sn.CpuTemp) + $deg) }
        elseif ($s -and $null -ne $s.Cpu) { [void]$parts.Add("Processeur " + [int][math]::Round([double]$s.Cpu) + " %") }
        if ($sn -and $null -ne $sn.GpuTemp) { [void]$parts.Add("Carte graphique " + [int][math]::Round([double]$sn.GpuTemp) + $deg) }
        elseif ($s) {
            $gu = $s.DgpuU; if ($null -eq $gu) { $gu = $s.Gpu }
            if ($null -ne $gu) { [void]$parts.Add("Carte graphique " + [int][math]::Round([double]$gu) + " %") }
        }
        if ($Script:Boosted) {
            $f = $null
            if ($s -and $s.Fps) { $f = $s.Fps }
            elseif ($Script:Samples -and $Script:Samples.Count -gt 0) { $f = $Script:Samples[$Script:Samples.Count - 1].Fps }
            if ($null -ne $f) { [void]$parts.Add("" + [int][math]::Round([double]$f) + " FPS") }
        }
        $Script:PureMetrics.Text = ($parts -join $sep)
    } catch {}
}

# --- Petite ligne d'etat en bas : dernier message utile du journal (lu sans l'interrompre)
function Update-GBPureNote {
    if (-not $Script:PureNote) { return }
    try {
        $n = $txtLog.TextLength
        if ($n -le $Script:PureLogLen) { $Script:PureLogLen = $n; return }
        $from = [math]::Max(0, $Script:PureLogLen); $Script:PureLogLen = $n
        $chunk = $txtLog.Text.Substring([math]::Min($from, $n))
        $last = $null; $games = $false
        foreach ($ln in ($chunk -split "`r?`n")) {
            $m = $ln.Trim(); if (-not $m) { continue }
            $m = $m -replace '^\[\d\d:\d\d:\d\d\]\s*', ''
            if ($m -match '^Jeu (ajoute|retire|detecte)') { $games = $true }
            if ($m -match '^(Perf :|Moteur :|Sauvegarde d.origine du)') { continue }
            $last = $m
        }
        if ($games) { Update-GBPureGames }
        if ($last) {
            $Script:PureNote.Text = (Get-Date -Format "HH:mm") + "   " + $last
            $tip.SetToolTip($Script:PureNote, $last)
        }
    } catch {}
}

# --- Interrupteurs : meme logique que les boutons TURBO, GPU et l'overlay de "Mes parties"
function Set-GBPureSilent([bool]$on) {
    if ([bool]$Script:Config.TurboOnlyInGame -eq $on) { return }
    if (Get-Command Switch-GBTurbo -ErrorAction SilentlyContinue) { Switch-GBTurbo; return }   # action du bouton TURBO (partie commune)
    $Script:Config.TurboOnlyInGame = $on; Save-Config
    if (Get-Command Update-GBTurboButton -ErrorAction SilentlyContinue) { try { Update-GBTurboButton } catch {} }
    Update-GBTurboCap
}
function Test-GBPureGpuCtl {
    $i = $null; try { $i = Get-GBGpuCtlInfo } catch {}
    return [bool]($i -and $i.Smi -and $i.CanLock)
}
function Set-GBPureGpuEco([bool]$on) {
    if ([bool]$Script:Config.GpuEco -eq $on) { return }
    if (-not (Test-GBPureGpuCtl)) {
        Log "Carte graphique : la frequence n'est pas reglable directement sur ce PC (menu Performances pour le detail)"
        $Script:PureShowGpu = [bool]$Script:Config.GpuEco
        Sync-GBPureToggles; Update-GBPureRows; return
    }
    if (Get-Command Switch-GBGpuMode -ErrorAction SilentlyContinue) { Switch-GBGpuMode; return }   # action du bouton GPU (partie commune)
    $Script:Config.GpuEco = $on; Save-Config
    if (Get-Command Update-GBGpuButton -ErrorAction SilentlyContinue) { try { Update-GBGpuButton } catch {} }
    $Script:GpuLastKey = $null
    Update-GBGpuCap
}
function Set-GBPureOverlay([bool]$on) {
    if ([bool]$Script:Config.Overlay -eq $on) { return }
    $Script:Config.Overlay = $on
    # L'overlay affiche les FPS seulement si la mesure PresentMon est active
    if ($on -and $chkFps.Enabled -and -not $chkFps.Checked) { $chkFps.Checked = $true; Sync-ConfigFromUI } else { Save-Config }
    if (-not $on) { Hide-GBOverlay }
    Log ("Overlay en jeu : " + $(if ($on) { "active" } else { "desactive" }))
}
function Get-GBPureSecondary {
    if (-not (Get-Command Get-GBMonitors -ErrorAction SilentlyContinue)) { return @() }
    $all = @(); try { $all = @(Get-GBMonitors) } catch {}
    if ($all.Count -lt 2) { return @() }
    return @($all | Where-Object { -not $_.Primary })
}
function Set-GBPureScreens([bool]$off) {
    foreach ($m in @(Get-GBPureSecondary)) {
        if ([bool]$m.Off -eq $off) { continue }
        try { [void](Set-GBMonitorPower $m.Index $off) } catch { Log ("Ecran " + $m.Index + " : " + $_.Exception.Message) }
    }
    Sync-GBPureToggles
}
# Les interrupteurs suivent la config (changee par un menu, un raccourci ou une autre fenetre)
function Sync-GBPureToggles {
    if (-not $Script:PureRows) { return }
    $Script:PureSyncing = $true
    try {
        $Script:PureTgSilent.Checked = [bool]$Script:Config.TurboOnlyInGame
        $Script:PureTgGpu.Checked = [bool]$Script:Config.GpuEco
        $Script:PureTgOverlay.Checked = [bool]$Script:Config.Overlay
        if ($Script:PureShowScreen) { $Script:PureTgScreen.Checked = [bool](@(Get-GBPureSecondary | Where-Object { $_.Off }).Count -gt 0) }
    } catch {} finally { $Script:PureSyncing = $false }
}

# --- Niveau : Doux / Equilibre / Max = niveaux Leger / Conseille / Competitif du curseur "niveau gaming"
$Script:PureLevelMap = @(0, 2, 3)
$Script:PureLevelDesc = @("Priorite au jeu, rien n'est ferme.", "Applis inutiles en pause, anti-saccades.", "Tout pour le jeu en ligne (souris, reseau).")
function Set-GBPureLevel([int]$seg) {
    if ($seg -lt 0 -or $seg -ge $Script:PureLevelMap.Count) { return }
    $v = $Script:PureLevelMap[$seg]; $lv = $Script:GameLevels[$v]
    $Script:GameLevelApplying = $true
    try { foreach ($k in $Script:GameChecks.Keys) { $c = $Script:GameChecks[$k]; if ($c.Enabled) { $c.Checked = ($lv.On -contains $k) } } }
    finally { $Script:GameLevelApplying = $false }
    Sync-ConfigFromUI
    try { Update-GameLevelUI } catch {}
    $msg = "Niveau : " + $Script:PureSegNames[$seg]
    if ($Script:Boosted) { $msg += " (s'applique au prochain boost)" }
    Log $msg
    Update-GBPureLevelUI
}
function Update-GBPureLevelUI {
    if (-not $Script:PureSeg) { return }
    try {
        $lv = Get-GameLevelNow
        $seg = [array]::IndexOf($Script:PureLevelMap, [int]$lv)
        if ($seg -ge 0) { $sub = $Script:PureLevelDesc[$seg] }
        elseif ($lv -ge 0) { $sub = "Niveau " + $Script:GameLevels[$lv].L + " (choisi dans le menu)" }
        else { $sub = "Reglage personnalise (menu Performances)" }
        if ($Script:PureOK) { $Script:PureSeg.SelectedIndex = $seg }
        else { $Script:PureSyncing = $true; try { for ($i = 0; $i -lt $Script:PureSegBtns.Count; $i++) { $Script:PureSegBtns[$i].Checked = ($i -eq $seg) } } finally { $Script:PureSyncing = $false } }
        Set-GBPureRowText $Script:PureRows.Level $null $sub
    } catch {}
}

# --- Mes jeux : resume sur l'accueil, liste sur la 2e vue
function Update-GBPureGames {
    if (-not $Script:PureRows) { return }
    try {
        $names = @($Script:Config.Games | ForEach-Object { Get-GameLabel ([string]$_) })
        $n = $names.Count
        if ($n -eq 0) { $sub = "Aucun jeu. Ajoute le tien."; if ($Script:Config.KnownGames) { $sub = "Les jeux populaires sont detectes. Ajoute les autres." } }
        elseif ($n -le 2) { $sub = $names -join ", " }
        else { $sub = $names[0] + ", " + $names[1] + " et " + ($n - 2) + " autre" + $(if ($n -gt 3) { "s" } else { "" }) }
        Set-GBPureRowText $Script:PureRows.Games $null $sub
        if ($Script:PureOK) { $Script:PureRows.Games.Value = $(if ($n -gt 0) { "" + $n } else { "" }) }
        if ($Script:PureGamesEmpty) { $Script:PureGamesEmpty.Visible = ($lstGames.Items.Count -eq 0) }
        $btnRemove.Enabled = ($null -ne $lstGames.SelectedItem)
    } catch {}
}

# --- Lignes visibles : la carte graphique non reglable et l'ecran secondaire (1 seul ecran) sont caches
function Update-GBPureRows {
    if (-not $Script:PureRows) { return }
    try {
        $Rows = $Script:PureRows
        $k = 1.0; if ($Script:PureGroupA.Width -gt 0) { $k = [double]$Script:PureGroupA.Width / [double]$Script:PureGroupW }
        $y = 4
        foreach ($r in @($Rows.Auto, $Rows.Silent, $Rows.Gpu, $Rows.Overlay, $Rows.Screen)) {
            $on = $true
            if ($r -eq $Rows.Gpu) { $on = [bool]$Script:PureShowGpu }
            if ($r -eq $Rows.Screen) { $on = [bool]$Script:PureShowScreen }
            $r.Visible = $on
            if (-not $on) { continue }
            $r.Top = [int][math]::Round($y * $k)
            if ($Script:PureOK) { $r.TopLine = ($y -gt 4); $r.Invalidate() }
            $y += $Script:PureRowH
        }
        $Script:PureGroupA.Height = [int][math]::Round(($y + 4) * $k)
        $next = $Script:PureGroupA
        if ($Script:PureGroupD) { $Script:PureGroupD.Top = $next.Top + $next.Height + [int][math]::Round(16 * $k); $next = $Script:PureGroupD }
        $Script:PureGroupB.Top = $next.Top + $next.Height + [int][math]::Round(16 * $k)
    } catch {}
}
# Apres l'affichage : la carte graphique est-elle reglable ? combien d'ecrans ?
function Update-GBPureCaps {
    try {
        $Script:PureShowGpu = (Test-GBPureGpuCtl) -or [bool]$Script:Config.GpuEco
        $Script:PureShowScreen = (@(Get-GBPureSecondary).Count -gt 0)
        Update-GBPureRows
        Sync-GBPureToggles
    } catch {}
}

function Show-GBPurePage([string]$key) {
    if (-not $Script:PurePages -or -not $Script:PurePages.Contains($key)) { return }
    # Show-GBPage commun (raccourcis Ctrl+1 / Ctrl+2, menu Affichage) ; sinon bascule simple, sans animation
    if ((Get-Command Show-GBPage -ErrorAction SilentlyContinue) -and $Script:Pages -and $Script:Pages.Contains($key) -and $Script:Pages[$key].Page -eq $Script:PurePages[$key]) { Show-GBPage $key; return }
    foreach ($k in @($Script:PurePages.Keys)) { if ($k -ne $key) { $Script:PurePages[$k].Visible = $false } }
    $Script:PurePages[$key].Visible = $true; $Script:PurePages[$key].BringToFront()
    $Script:CurrentPage = $key
    if ($key -eq 'home') { Update-GBPureGames; Update-GBPureLevelUI }
}

function Build-GBLayoutPure {
    [void](Initialize-GBPureUi)
    $st = Get-GBPureStyle; $Script:PureC = $st.C; $Script:PureF = $st.F
    $Pal = $Script:PureC; $Fnt = $Script:PureF
    $W = 580; $H = 652; $Pad = 24
    if (Test-Path function:New-GBDisplayControls) { $H += 124 }   # groupe Ecran (luminosite, limite de FPS)
    $Script:PureGroupW = $W - 2 * $Pad; $Script:PureRowW = $Script:PureGroupW - 4; $Script:PureRowH = 50; $Script:PureTgW = 36
    if (Get-Command Set-GBShellSize -ErrorAction SilentlyContinue) { Set-GBShellSize $W $H }
    else { $form.ClientSize = New-Object System.Drawing.Size($W, ($H + [int]$Script:MenuH)) }
    if (-not $Script:Body) {
        $Script:Body = New-Object System.Windows.Forms.Panel
        $Script:Body.Location = New-Object System.Drawing.Point(0, [int]$Script:MenuH); $Script:Body.Size = New-Object System.Drawing.Size($W, $H)
        $form.Controls.Add($Script:Body)
    }
    $body = $Script:Body
    $form.SuspendLayout()
    # Controles non ranges : gardes dans un panneau cache (ils existent, gardent leur etat, ne sont jamais liberes)
    $Script:PureParking = New-Object System.Windows.Forms.Panel
    $Script:PureParking.Visible = $false; $Script:PureParking.Size = New-Object System.Drawing.Size(1, 1)
    foreach ($c in @($form.Controls)) {
        if ($c -eq $Script:Body -or ($Script:Menu -and $c -eq $Script:Menu) -or $c -is [System.Windows.Forms.MenuStrip]) { continue }
        $form.Controls.Remove($c); $Script:PureParking.Controls.Add($c)
    }
    foreach ($c in @($body.Controls)) { $body.Controls.Remove($c); $Script:PureParking.Controls.Add($c) }
    $body.Controls.Add($Script:PureParking)
    $body.BackColor = $Pal.Bg; $form.BackColor = $Pal.Bg
    if ($Script:UiOK) { [GBTheme]::DoubleBuffer($body) }

    $pgHome = New-Object System.Windows.Forms.Panel
    $pgHome.Location = New-Object System.Drawing.Point(0, 0); $pgHome.Size = New-Object System.Drawing.Size($W, ($H - 30)); $pgHome.BackColor = $Pal.Bg
    $pgGames = New-Object System.Windows.Forms.Panel
    $pgGames.Location = New-Object System.Drawing.Point(0, 0); $pgGames.Size = New-Object System.Drawing.Size($W, ($H - 30)); $pgGames.BackColor = $Pal.Bg; $pgGames.Visible = $false
    foreach ($p in @($pgHome, $pgGames)) { if ($Script:UiOK) { [GBTheme]::DoubleBuffer($p) }; $body.Controls.Add($p) }
    $Script:PurePages = [ordered]@{ home = $pgHome; games = $pgGames }

    # Etat : pastille, grand titre, phrase, mesures
    if ($Script:PureOK) { $Script:PureDot = New-Object GBPureDot }
    else { $Script:PureDot = New-Object System.Windows.Forms.Label; $Script:PureDot.Text = [string][char]0x25CF; $Script:PureDot.TextAlign = "MiddleCenter"; $Script:PureDot.Font = $Fnt.Big }
    $Script:PureDot.BackColor = $Pal.Bg
    Set-GBPurePlace $Script:PureDot $pgHome (($W - 44) / 2) 24 44 44
    $Script:PureTitle = New-GBPureText $pgHome $Fnt.Title $Pal.Text $Pad 76 ($W - 2 * $Pad) 40
    $Script:PureSub = New-GBPureText $pgHome $Fnt.Row $Pal.Muted $Pad 116 ($W - 2 * $Pad) 22
    $Script:PureMetrics = New-Object System.Windows.Forms.Label
    $Script:PureMetrics.Font = $Fnt.Sub; $Script:PureMetrics.ForeColor = $Pal.Muted; $Script:PureMetrics.BackColor = $Pal.Bg
    $Script:PureMetrics.TextAlign = "MiddleCenter"; $Script:PureMetrics.AutoEllipsis = $true; $Script:PureMetrics.Text = ""
    Set-GBPurePlace $Script:PureMetrics $pgHome $Pad 138 ($W - 2 * $Pad) 20
    $tip.SetToolTip($Script:PureMetrics, "Mesure toutes les 5 secondes. Le detail est dans le menu Performances.")

    # Un seul gros bouton : meme action que BOOST
    if ($Script:PureOK) { $Script:PurePill = New-Object GBPurePill }
    else {
        $Script:PurePill = New-Object System.Windows.Forms.Button; $Script:PurePill.FlatStyle = "Flat"; $Script:PurePill.FlatAppearance.BorderSize = 0
        $Script:PurePill.Cursor = [System.Windows.Forms.Cursors]::Hand
    }
    $Script:PurePill.Font = $Fnt.Pill; $Script:PurePill.BackColor = $Pal.Bg
    Set-GBPurePlace $Script:PurePill $pgHome (($W - 300) / 2) 172 300 48
    $Script:PurePill.Add_Click({ try { Switch-BoostManual } catch { Log ("Boost : " + $_.Exception.Message) } })
    $tip.SetToolTip($Script:PurePill, "Lance ou arrete le boost. Tout ce qui change est remis comme avant a la fin.")

    # Reglages : cinq interrupteurs facon iOS
    $Script:PureGroupA = New-GBPureGroup $pgHome $Pad 240 $Script:PureGroupW 258
    $Rows = @{}
    $rw = $Script:PureRowW; $rh = $Script:PureRowH; $res = $Script:PureTgW + 12
    $Rows.Auto = New-GBPureRow $Script:PureGroupA "Boost automatique" "Se lance tout seul quand un de tes jeux demarre." $res
    $Rows.Silent = New-GBPureRow $Script:PureGroupA "Mode silencieux" "Processeur plus frais hors jeu. Pleine vitesse en jeu." $res
    $Rows.Gpu = New-GBPureRow $Script:PureGroupA "Carte graphique economique" "Plus calme hors jeu. Aucune limite pendant le boost." $res
    $ovSub = "Petit cadre FPS par-dessus le jeu."; if (-not $chkFps.Enabled) { $ovSub = "Processeur, carte graphique et ping par-dessus le jeu." }
    $Rows.Overlay = New-GBPureRow $Script:PureGroupA "Compteur FPS en jeu" $ovSub $res
    $Rows.Screen = New-GBPureRow $Script:PureGroupA "Ecran secondaire eteint" "Le 2e ecran s'eteint. Il se rallume a la fermeture." $res
    foreach ($r in @($Rows.Auto, $Rows.Silent, $Rows.Gpu, $Rows.Overlay, $Rows.Screen)) { Set-GBPurePlace $r $Script:PureGroupA 2 4 $rw $rh }
    $Script:PureRows = $Rows
    # Boost automatique : la vraie case du moteur, rangee dans la ligne
    Set-GBPureToggle $chkAuto $Rows.Auto
    $Script:PureTgSilent = New-GBToggleCtl "" ([bool]$Script:Config.TurboOnlyInGame); Set-GBPureToggle $Script:PureTgSilent $Rows.Silent
    $Script:PureTgGpu = New-GBToggleCtl "" ([bool]$Script:Config.GpuEco); Set-GBPureToggle $Script:PureTgGpu $Rows.Gpu
    $Script:PureTgOverlay = New-GBToggleCtl "" ([bool]$Script:Config.Overlay); Set-GBPureToggle $Script:PureTgOverlay $Rows.Overlay
    $Script:PureTgScreen = New-GBToggleCtl "" $false; Set-GBPureToggle $Script:PureTgScreen $Rows.Screen
    $Script:PureTgSilent.Add_CheckedChanged({ if (-not $Script:PureSyncing) { try { Set-GBPureSilent ([bool]$this.Checked) } catch { Log ("Mode silencieux : " + $_.Exception.Message) } } })
    $Script:PureTgGpu.Add_CheckedChanged({ if (-not $Script:PureSyncing) { try { Set-GBPureGpuEco ([bool]$this.Checked) } catch { Log ("Carte graphique : " + $_.Exception.Message) } } })
    $Script:PureTgOverlay.Add_CheckedChanged({ if (-not $Script:PureSyncing) { try { Set-GBPureOverlay ([bool]$this.Checked) } catch { Log ("Overlay : " + $_.Exception.Message) } } })
    $Script:PureTgScreen.Add_CheckedChanged({ if (-not $Script:PureSyncing) { try { Set-GBPureScreens ([bool]$this.Checked) } catch { Log ("Ecran : " + $_.Exception.Message) } } })
    $tip.SetToolTip($Rows.Silent, "Turbo du processeur coupe hors jeu (comme TURBO : OFF). Il revient pendant le boost.")
    $tip.SetToolTip($Rows.Gpu, "Frequence de la carte graphique limitee hors jeu (comme GPU : ECO). Remis comme avant a la fermeture.")
    $Script:PureShowGpu = $false
    try { if ($Script:MainGpu -and [string]$Script:MainGpu.Name -match 'NVIDIA|GeForce|Quadro|RTX|GTX') { $Script:PureShowGpu = $true } } catch {}
    if ($Script:Config.GpuEco) { $Script:PureShowGpu = $true }
    $Script:PureShowScreen = (@(Get-GBPureSecondary).Count -gt 0)

    # Ecran : luminosite de l'ecran principal et limite de FPS, deux lignes simples
    $Script:PureGroupD = $null; $gbY = 512
    if (Test-Path function:New-GBDisplayControls) {
        $Script:PureGroupD = New-GBPureGroup $pgHome $Pad 512 $Script:PureGroupW 108
        $null = New-GBDisplayControls $Script:PureParking
        $Rows.Bright = New-GBPureRow $Script:PureGroupD "Luminosite" "" 232
        Set-GBPurePlace $Rows.Bright $Script:PureGroupD 2 4 $rw $rh
        $Rows.Fps = New-GBPureRow $Script:PureGroupD "Limite de FPS" "Pour tous les jeux. Moins de FPS = PC plus frais." 184
        Set-GBPurePlace $Rows.Fps $Script:PureGroupD 2 (4 + $rh) $rw $rh
        if ($Script:PureOK) { $Rows.Fps.TopLine = $true }
        Set-GBPurePlace $Script:DispBright $Rows.Bright ($rw - 16 - 216) 10 216 30
        Set-GBPurePlace $Script:DispFps $Rows.Fps ($rw - 16 - 168) 12 168 26
        foreach ($k in @($Script:DispBright, $Script:DispFps)) { $k.BackColor = $Pal.Card; $k.Anchor = "Top, Right" }
        if ($Script:DispBright -isnot [System.Windows.Forms.TrackBar]) { $Script:DispBright.FillColor = $Pal.Accent; $Script:DispBright.ValueColor = $Pal.Text }
        # Sous-titres : ecran regle, ou pourquoi ce n'est pas possible
        $Script:DispAfterUpdate = {
            param($t, $v, $fi, $hz)
            $bs = $(if (-not $t) { "Aucun ecran reglable" } elseif ($v -eq -2) { "Lecture de l'ecran..." } elseif ($v -lt 0) { "A regler avec les boutons de l'ecran" } else { "Ecran principal : " + ([string]$t.Label -replace '^\d+ - ', '' -replace ' \*$', '') })
            Set-GBPureRowText $Script:PureRows.Bright $null $bs
            if (-not $fi.Ok) { Set-GBPureRowText $Script:PureRows.Fps $null "Reserve aux cartes NVIDIA" }
        }
        $gbY = 512 + 108 + 16
    }
    # Niveau et Mes jeux
    $Script:PureGroupB = New-GBPureGroup $pgHome $Pad $gbY $Script:PureGroupW 108
    $segW = 228
    $Rows.Level = New-GBPureRow $Script:PureGroupB "Niveau" "" ($segW + 12)
    Set-GBPurePlace $Rows.Level $Script:PureGroupB 2 4 $rw $rh
    $Script:PureSegNames = @("Doux", "Equilibre", "Max")
    if ($Script:PureOK) {
        $Script:PureSeg = New-Object GBPureSegment
        $Script:PureSeg.Items = [string[]]$Script:PureSegNames
        $Script:PureSeg.Font = $Fnt.Seg; $Script:PureSeg.SelFont = $Fnt.SegOn
        $Script:PureSeg.Track = [GBPureMotion]::Mix($Pal.Bg, $Pal.Muted, 0.10); $Script:PureSeg.Knob = $Pal.Card
        $Script:PureSeg.TextColor = $Pal.Text; $Script:PureSeg.LineColor = $Pal.Line; $Script:PureSeg.Accent = $Pal.Accent
        $Script:PureSeg.BackColor = $Pal.Card
        Set-GBPurePlace $Script:PureSeg $Rows.Level ($rw - 16 - $segW) 10 $segW 30
        $Script:PureSeg.Add_SelectedIndexChanged({ try { Set-GBPureLevel $Script:PureSeg.SelectedIndex } catch { Log ("Niveau : " + $_.Exception.Message) } })
    } else {
        $Script:PureSeg = New-Object System.Windows.Forms.Panel; $Script:PureSeg.BackColor = $Pal.Card
        Set-GBPurePlace $Script:PureSeg $Rows.Level ($rw - 16 - $segW) 10 $segW 30
        $Script:PureSegBtns = @()
        for ($i = 0; $i -lt 3; $i++) {
            $rb = New-Object System.Windows.Forms.RadioButton; $rb.Appearance = "Button"; $rb.FlatStyle = "Flat"; $rb.TextAlign = "MiddleCenter"
            $rb.Text = $Script:PureSegNames[$i]; $rb.Tag = $i; $rb.Font = $Fnt.Seg; $rb.ForeColor = $Pal.Text; $rb.FlatAppearance.CheckedBackColor = $Pal.Sel
            $rb.Location = New-Object System.Drawing.Point(($i * 76), 0); $rb.Size = New-Object System.Drawing.Size(76, 30)
            $rb.Add_CheckedChanged({ if ($this.Checked -and -not $Script:PureSyncing) { try { Set-GBPureLevel ([int]$this.Tag) } catch {} } })
            $Script:PureSeg.Controls.Add($rb); $Script:PureSegBtns += $rb
        }
    }
    $tip.SetToolTip($Script:PureSeg, "Doux : rien n'est ferme. Equilibre : le bon choix pour la plupart des PC. Max : pour le jeu en ligne competitif.")
    $Rows.Games = New-GBPureRow $Script:PureGroupB "Mes jeux" "" 40 -Chevron
    Set-GBPurePlace $Rows.Games $Script:PureGroupB 2 (4 + $rh) $rw $rh
    if ($Script:PureOK) { $Rows.Games.TopLine = $true }
    foreach ($x in @(@($Rows.Games) + @($Rows.Games.Controls))) { $x.Add_Click({ Show-GBPurePage 'games' }) }

    # Modele, en haut a droite (sur les deux vues) : clic = NEXUS / ARENA / PURE
    foreach ($pg in @($pgHome, $pgGames)) {
        $edSw = New-Object System.Windows.Forms.Label
        $edSw.Text = "PURE " + [char]0x25BE; $edSw.Font = $Fnt.Sub; $edSw.ForeColor = $Pal.Accent; $edSw.BackColor = $Pal.Bg; $edSw.TextAlign = "MiddleRight"
        Set-GBPurePlace $edSw $pg ($W - 16 - 90) 10 90 22
        if (Test-Path function:Add-GBEditionSwitch) { Add-GBEditionSwitch $edSw }
    }

    # Ligne d'etat en bas (sur les deux vues)
    $Script:PureNote = New-Object System.Windows.Forms.Label
    $Script:PureNote.Font = $Fnt.Small; $Script:PureNote.ForeColor = $Pal.Muted; $Script:PureNote.BackColor = $Pal.Bg
    $Script:PureNote.TextAlign = "MiddleCenter"; $Script:PureNote.AutoEllipsis = $true
    Set-GBPurePlace $Script:PureNote $body $Pad ($H - 28) ($W - 2 * $Pad) 20

    # --- Vue Mes jeux : la liste du moteur, ajouter, retirer
    $back = New-Object System.Windows.Forms.Label
    $back.Text = [string][char]0x2039 + " Retour"; $back.Font = $Fnt.Row; $back.ForeColor = $Pal.Accent; $back.BackColor = $Pal.Bg
    $back.Cursor = [System.Windows.Forms.Cursors]::Hand; $back.TextAlign = "MiddleLeft"
    Set-GBPurePlace $back $pgGames 16 12 100 28
    $back.Add_Click({ Show-GBPurePage 'home' })
    $gt = New-GBPureText $pgGames $Fnt.Title $Pal.Text $Pad 46 ($W - 2 * $Pad) 40 -Left
    Set-GBPureText $gt "Mes jeux" $Pal.Text
    $gs = New-GBPureText $pgGames $Fnt.Row $Pal.Muted $Pad 86 ($W - 2 * $Pad) 22 -Left
    Set-GBPureText $gs "Le boost se lance quand un de ces jeux demarre." $Pal.Muted
    $gl = New-GBPureGroup $pgGames $Pad 120 $Script:PureGroupW 330
    Set-GBPurePlace $lstGames $gl 10 10 ($Script:PureGroupW - 20) 310
    $lstGames.BackColor = $Pal.Card; $lstGames.ForeColor = $Pal.Text; $lstGames.BorderStyle = "None"; $lstGames.IntegralHeight = $false
    $lstGames.Font = $Fnt.Row
    $lstGames.ItemHeight = [int](34 * [math]::Max(1.0, [double]$Script:DpiScale))
    $Script:PureGamesEmpty = New-Object System.Windows.Forms.Label
    $Script:PureGamesEmpty.Text = "Aucun jeu pour l'instant." + "`r`n" + "Ajoute ton jeu : le boost se lancera avec lui."
    $Script:PureGamesEmpty.Font = $Fnt.Row; $Script:PureGamesEmpty.ForeColor = $Pal.Muted; $Script:PureGamesEmpty.BackColor = $Pal.Card; $Script:PureGamesEmpty.TextAlign = "MiddleCenter"
    Set-GBPurePlace $Script:PureGamesEmpty $gl 30 120 ($Script:PureGroupW - 60) 60
    $Script:PureGamesEmpty.BringToFront()
    $Script:GamesEmpty = $Script:PureGamesEmpty   # (Update-GBHomeTiles le montre quand la liste est vide)
    Set-GBPurePlace $btnBrowse $pgGames $Pad 462 190 36
    $btnBrowse.Text = "+ Ajouter un jeu"; $btnBrowse.ForeColor = $Pal.Accent; $btnBrowse.Font = $Fnt.Row
    Set-GBPurePlace $btnRemove $pgGames ($W - $Pad - 120) 462 120 36
    $btnRemove.Text = "Retirer"; $btnRemove.ForeColor = $Pal.Red; $btnRemove.Font = $Fnt.Row
    $tip.SetToolTip($btnRemove, "Retire le jeu selectionne (aussi par clic droit sur le jeu)")
    $tip.SetToolTip($btnBrowse, "Choisis le fichier .exe de ton jeu")
    $lstGames.add_SelectedIndexChanged({ $btnRemove.Enabled = ($null -ne $lstGames.SelectedItem) })
    $gk = New-GBPureGroup $pgGames $Pad 514 $Script:PureGroupW 58
    $rk = New-GBPureRow $gk "Jeux populaires" "Detecte aussi Valorant, CS2, Fortnite... sans les ajouter." $res
    Set-GBPurePlace $rk $gk 2 4 $rw $rh
    Set-GBPureToggle $chkKnown $rk
    # Clic droit sur un jeu : "Retirer de la liste" en plus des profils
    if ($gameMenu) {
        [void]$gameMenu.Items.Add((New-Object System.Windows.Forms.ToolStripSeparator))
        $miPureRemove = $gameMenu.Items.Add("Retirer de la liste")
        $miPureRemove.Add_Click({ if ($lstGames.SelectedItem) { $btnRemove.PerformClick() } })
    }

    # Pages pour les raccourcis (Ctrl+1, Ctrl+2) et le menu Affichage
    $Script:PageOrder = @('home', 'games')
    if (-not $Script:Pages) { $Script:Pages = [ordered]@{} }
    $Script:Pages.Clear()
    # (pas de colonne de navigation : Nav est un simple objet avec .Selected et .Badge, compatible avec Show-GBPage)
    $Script:Pages['home'] = @{ Nav = [pscustomobject]@{ Selected = $true; Badge = $false }; Page = $pgHome; Title = "Accueil" }
    $Script:Pages['games'] = @{ Nav = [pscustomobject]@{ Selected = $false; Badge = $false }; Page = $pgGames; Title = "Mes jeux" }
    $pgHome.Add_VisibleChanged({ if ($this.Visible) { $Script:CurrentPage = 'home'; Update-GBPureGames; Update-GBPureLevelUI } })
    $pgGames.Add_VisibleChanged({ if ($this.Visible) { $Script:CurrentPage = 'games' } })

    # Le moteur previent : nouveau texte du bouton BOOST ou de l'etat -> la page suit (rien n'est enveloppe)
    $btnBoost.Add_TextChanged({ Update-GBPureState })
    $lblStatus.Add_TextChanged({ Update-GBPureState })
    $Script:PureLogLen = $txtLog.TextLength
    $txtLog.Add_TextChanged({ Update-GBPureNote; Update-GBPureState })
    $chkAuto.Add_CheckedChanged({ Update-GBPureState })
    $chkKnown.Add_CheckedChanged({ Update-GBPureGames; Update-GBPureState })
    foreach ($c in $Script:GameChecks.Values) { $c.Add_CheckedChanged({ if (-not $Script:GameLevelApplying) { Update-GBPureLevelUI } }) }
    if ($Script:BtnTurbo) { $Script:BtnTurbo.Add_TextChanged({ Sync-GBPureToggles }) }
    if ($Script:BtnGpu) { $Script:BtnGpu.Add_TextChanged({ Sync-GBPureToggles }) }
    $form.Add_Activated({ Sync-GBPureToggles })
    if (Get-Command Add-GBSampleHook -ErrorAction SilentlyContinue) { Add-GBSampleHook { param($s) Update-GBPureMetrics $s } }
    else { $monTimer.Add_Tick({ Update-GBPureMetrics $null }) }
    if (Get-Command Add-GBStartHook -ErrorAction SilentlyContinue) { Add-GBStartHook { Update-GBPureCaps } }
    else {
        $Script:PureCapsTimer = New-Object System.Windows.Forms.Timer; $Script:PureCapsTimer.Interval = 900
        $Script:PureCapsTimer.Add_Tick({ $Script:PureCapsTimer.Stop(); $Script:PureCapsTimer.Dispose(); Update-GBPureCaps })
        $form.Add_Shown({ if ($Script:PureCapsTimer) { try { $Script:PureCapsTimer.Start() } catch {} } })
    }

    Update-GBPureRows
    Sync-GBPureToggles
    Update-GBPureGames
    Update-GBPureLevelUI
    Update-GBPureState
    Update-GBPureMetrics $Script:LastSample   # (temperatures tout de suite si capteurs les a deja)
    $form.ResumeLayout()
    Show-GBPurePage 'home'
    if (Get-Command Complete-GBLayout -ErrorAction SilentlyContinue) { Complete-GBLayout }
}

# --- Demarrage ---------------------------------------------------------------
# (socle) Mise en page du modele choisi : Build-GBLayoutNexus / Arena / Pure, avant tout le reste du demarrage
Invoke-GBLayout
# Barre de menus, actions et raccourcis clavier (toutes les options, raccourcis personnalisables)
$null = New-GBMenuBar
Refresh-Games
Update-BoostButton
Log "GameBoost demarre"
if ($Script:ConfigMigrated) { Save-Config; Log "Boost en mode MANUEL : il ne se lance qu'avec le bouton BOOST (le mode auto reste disponible si tu le coches)" }
$perfNote = "WMI (repli)"; if ($Script:Perf) { $perfNote = "compteurs Windows directs" }
Log ("Moteur : code " + ($Script:GBCompileNotes -join ", ") + " | mesures : " + $perfNote + $(if ($Script:FastOK) { "" } else { " | mesures rapides indisponibles : " + $Script:FastError }))
if (Test-Path -LiteralPath $StateFile) {
    Log "Session precedente non terminee proprement : restauration..."
    Invoke-Restore
}
Get-ChildItem -LiteralPath $LogDir -Filter 'fps_*.csv' -ErrorAction SilentlyContinue | Remove-Item -ErrorAction SilentlyContinue
$hadBaseline = Test-Path -LiteralPath $BaselineFile
Ensure-Baseline
if ($hadBaseline) { Log ("Sauvegarde d'origine du " + (Get-BaselineDate) + " disponible (bouton TOUT RESTAURER)") }

# Infos du PC, tache de lancement automatique et pilote de la carte graphique : lus en arriere-plan
# (requetes WMI et internet lentes) pour que la fenetre s'affiche tout de suite
Start-StartupChecks
if ($Minimized) { $form.Add_Shown({ $form.WindowState = "Minimized" }) }
if ($Script:Config.AutoMode) { Log "GameBoost pret. Le boost demarre quand un de tes jeux se lance (mode auto), ou avec le bouton BOOST." }
else { Log "GameBoost pret. Clique sur BOOST quand tu joues (le boost ne se lance jamais tout seul)." }
$timer.Start()
$monTimer.Start()
Start-GBShellTimers   # (socle) verification toutes les minutes + crochets de demarrage (Add-GBStartHook)
Take-Sample
# Application.Run (et pas ShowDialog) : la fenetre peut etre cachee pres de l'horloge sans fermer l'appli
if (-not $Script:NativeOK) { Log ("Fonctions avancees indisponibles (vidage RAM, mode d'alimentation) : " + $Script:NativeError + " - un antivirus bloque peut-etre la compilation") }
try { [System.Windows.Forms.Application]::Run($form) }
catch {
    Write-StartupError ("La fenetre de GameBoost n'a pas pu s'ouvrir : " + $_.Exception.Message)
    exit 1
}
